from __future__ import annotations

from dataclasses import dataclass, field
from typing import Iterable


@dataclass(frozen=True, slots=True)
class Event:
    title: str
    start_hour: int
    duration_hours: int
    tags: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if not 0 <= self.start_hour <= 23:
            raise ValueError("start_hour must be between 0 and 23")
        if self.duration_hours <= 0:
            raise ValueError("duration_hours must be positive")
        if self.start_hour + self.duration_hours > 24:
            raise ValueError("event must end within the same day")

    @property
    def end_hour(self) -> int:
        return self.start_hour + self.duration_hours

    def has_tag(self, tag: str) -> bool:
        return tag in self.tags


@dataclass(slots=True)
class Schedule:
    events: list[Event] = field(default_factory=list)

    def add_event(self, event: Event) -> None:
        self.events.append(event)

    def extend(self, events: Iterable[Event]) -> None:
        self.events.extend(events)

    def events_by_tag(self, tag: str) -> list[Event]:
        return [event for event in self.events if event.has_tag(tag)]

    def total_scheduled_hours(self) -> int:
        return sum(event.duration_hours for event in self.events)

    def has_overlaps(self) -> bool:
        ordered = sorted(self.events, key=lambda event: event.start_hour)
        for previous, current in zip(ordered, ordered[1:]):
            if current.start_hour < previous.end_hour:
                return True
        return False


if __name__ == "__main__":
    schedule = Schedule()
    schedule.extend(
        [
            Event("Team Sync", 9, 2, ("work", "meeting")),
            Event("Code Review", 11, 1, ("work",)),
            Event("Gym", 18, 2, ("health", "personal")),
        ]
    )

    print(schedule.events_by_tag("work"))
    print(schedule.total_scheduled_hours())
    print(schedule.has_overlaps())

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def remove_duplicates(head):
    """Remove duplicate values from a sorted singly linked list in place."""
    current = head

    while current and current.next:
        if current.val == current.next.val:
            # Skip the duplicate node
            current.next = current.next.next
        else:
            current = current.next

    return head


def build_linked_list(values):
    """Build a linked list from a Python list and return its head."""
    dummy = ListNode()
    tail = dummy

    for value in values:
        tail.next = ListNode(value)
        tail = tail.next

    return dummy.next


def linked_list_to_list(head):
    """Convert a linked list back into a Python list."""
    result = []
    current = head

    while current:
        result.append(current.val)
        current = current.next

    return result


# Example usage
if __name__ == "__main__":
    head = build_linked_list([1, 1, 2, 3, 3, 4, 4, 4, 5])
    updated_head = remove_duplicates(head)
    print(linked_list_to_list(updated_head))  # Output: [1, 2, 3, 4, 5]

import hmac
import hashlib
import json
from flask import Flask, request, jsonify

app = Flask(__name__)

# Shared secret used to verify webhook signatures.
WEBHOOK_SECRET = b"super-secret-key"

# In-memory replay protection for processed event IDs.
processed_events = set()
SUPPORTED_EVENTS = {"payment.succeeded", "payment.failed"}


def verify_signature(raw_body: bytes, signature: str) -> bool:
    """Return True if the provided signature matches the HMAC of the body."""
    expected = hmac.new(WEBHOOK_SECRET, raw_body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)


@app.post("/webhook")
def webhook_handler():
    raw_body = request.get_data()
    signature = request.headers.get("X-Signature")

    if not signature:
        return jsonify(error="missing signature header"), 401

    if not verify_signature(raw_body, signature):
        return jsonify(error="invalid signature"), 401

    try:
        payload = json.loads(raw_body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return jsonify(error="invalid JSON payload"), 400

    event_id = payload.get("id")
    event_type = payload.get("type")
    data = payload.get("data")

    if not event_id or not event_type or data is None:
        return jsonify(error="missing required fields: id, type, data"), 400

    if event_id in processed_events:
        return jsonify(status="ignored", reason="duplicate event", id=event_id), 200

    if event_type not in SUPPORTED_EVENTS:
        return jsonify(error="unsupported event type", type=event_type), 422

    # Mark as processed only after all validations pass.
    processed_events.add(event_id)

    # Example business logic hook.
    if event_type == "payment.succeeded":
        result = "payment recorded"
    else:
        result = "payment failure noted"

    return jsonify(status="processed", id=event_id, type=event_type, result=result), 200


if __name__ == "__main__":
    app.run(debug=True)

def process_orders(orders):
    processed = []
    failed = []

    for order in orders:
        customer = order.get('customer', '').strip()
        quantity = order.get('quantity')
        price = order.get('price')

        # Validate the order fields
        if not customer:
            failed.append({"order": order, "error": "Missing customer name"})
            continue
        if not isinstance(quantity, (int, float)) or quantity <= 0:
            failed.append({"order": order, "error": "Quantity must be positive"})
            continue
        if not isinstance(price, (int, float)) or price <= 0:
            failed.append({"order": order, "error": "Price must be positive"})
            continue

        # Calculate total cost for valid orders
        total_cost = quantity * price
        processed.append({
            "customer": customer,
            "total_cost": round(total_cost, 2)
        })

    return processed, failed


def main():
    orders = [
        {"customer": "Alice", "quantity": 3, "price": 19.99},
        {"customer": "", "quantity": 2, "price": 10.0},
        {"customer": "Bob", "quantity": -1, "price": 5.5},
        {"customer": "Carol", "quantity": 4, "price": 7.25}
    ]

    processed, failed = process_orders(orders)

    print("Processed Orders:")
    for item in processed:
        print(item)

    print("\nFailed Orders:")
    for item in failed:
        print(item)


if __name__ == "__main__":
    main()

