def caesar_shift(text, key):
    """Shift alphabetic characters in text by key positions."""
    result = []
    key %= 26  # Normalize large or negative keys

    for ch in text:
        if 'a' <= ch <= 'z':
            base = ord('a')
            shifted = chr(base + (ord(ch) - base + key) % 26)
            result.append(shifted)
        elif 'A' <= ch <= 'Z':
            base = ord('A')
            shifted = chr(base + (ord(ch) - base + key) % 26)
            result.append(shifted)
        else:
            result.append(ch)

    return ''.join(result)


def encrypt(message, key):
    """Encrypt a message using a Caesar cipher."""
    return caesar_shift(message, key)


def decrypt(ciphertext, key):
    """Decrypt a Caesar cipher message."""
    return caesar_shift(ciphertext, -key)


def main():
    message = 'Attack at Dawn! Meet at 05:30.'
    key = 5

    encrypted = encrypt(message, key)
    decrypted = decrypt(encrypted, key)

    print('Original :', message)
    print('Encrypted:', encrypted)
    print('Decrypted:', decrypted)


if __name__ == '__main__':
    main()

from abc import ABC, abstractmethod


class NotificationChannel(ABC):
    @property
    @abstractmethod
    def name(self) -> str:
        """Unique channel name used for routing recipients."""
        raise NotImplementedError

    @abstractmethod
    def send(self, recipient: str, message: str) -> bool:
        """Send a message to a single recipient."""
        raise NotImplementedError


class EmailChannel(NotificationChannel):
    @property
    def name(self) -> str:
        return "email"

    def send(self, recipient: str, message: str) -> bool:
        # Simulate a successful email send.
        print(f"[EMAIL] To: {recipient} | Message: {message}")
        return True


class SMSChannel(NotificationChannel):
    @property
    def name(self) -> str:
        return "sms"

    def send(self, recipient: str, message: str) -> bool:
        # Simulate a successful SMS send.
        print(f"[SMS] To: {recipient} | Message: {message}")
        return True


class NotificationManager:
    def __init__(self, channels):
        self._channels = {}
        for channel in channels:
            if not isinstance(channel, NotificationChannel):
                raise TypeError("All channels must be instances of NotificationChannel")
            self._channels[channel.name] = channel

    def broadcast(self, recipients_by_channel, message: str):
        results = {}
        for name, channel in self._channels.items():
            recipients = recipients_by_channel.get(name, [])
            success_count = 0
            for recipient in recipients:
                if channel.send(recipient, message):
                    success_count += 1
            results[name] = success_count
        return results


if __name__ == "__main__":
    manager = NotificationManager([EmailChannel(), SMSChannel()])
    recipients = {
        "email": ["alice@example.com", "bob@example.com"],
        "sms": ["+12025550123", "+12025550124"],
    }
    summary = manager.broadcast(recipients, "System maintenance starts at 10 PM.")
    print(summary)

class EventBus:
    def __init__(self):
        self._listeners = {}

    def subscribe(self, event_name, callback):
        """Register a callback for a named event."""
        self._listeners.setdefault(event_name, []).append(callback)

    def unsubscribe(self, event_name, callback):
        """Remove a callback from a named event if it exists."""
        if event_name in self._listeners:
            self._listeners[event_name] = [
                cb for cb in self._listeners[event_name] if cb != callback
            ]
            if not self._listeners[event_name]:
                del self._listeners[event_name]

    def emit(self, event_name, **data):
        """Trigger all callbacks subscribed to the event."""
        for callback in self._listeners.get(event_name, []):
            callback(**data)


