from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Callable, Dict, List, Type


class Plugin(ABC):
    """Base class for all text-processing plugins."""
    name: str

    @abstractmethod
    def transform(self, text: str) -> str:
        pass


class PluginManager:
    def __init__(self) -> None:
        self._plugins: Dict[str, Plugin] = {}
        self._order: List[str] = []
        self._enabled: Dict[str, bool] = {}

    def register(self, cls: Type[Plugin]) -> Type[Plugin]:
        """Decorator-based plugin registration with validation."""
        if not issubclass(cls, Plugin):
            raise TypeError("Plugin must inherit from Plugin base class")
        if not getattr(cls, "name", None) or not isinstance(cls.name, str):
            raise ValueError("Plugin must define a non-empty string 'name'")
        if cls.name in self._plugins:
            raise ValueError(f"Duplicate plugin name: {cls.name}")
        if "transform" not in cls.__dict__:
            raise ValueError(f"Plugin '{cls.name}' must implement transform()")

        instance = cls()
        self._plugins[cls.name] = instance
        self._order.append(cls.name)
        self._enabled[cls.name] = True
        return cls

    def enable(self, name: str) -> None:
        self._require_plugin(name)
        self._enabled[name] = True

    def disable(self, name: str) -> None:
        self._require_plugin(name)
        self._enabled[name] = False

    def process(self, text: str) -> str:
        for name in self._order:
            if self._enabled[name]:
                text = self._plugins[name].transform(text)
        return text

    def _require_plugin(self, name: str) -> None:
        if name not in self._plugins:
            raise KeyError(f"Unknown plugin: {name}")


manager = PluginManager()


@manager.register
class TrimPlugin(Plugin):
    name = "trim"

    def transform(self, text: str) -> str:
        return text.strip()


@manager.register
class UppercasePlugin(Plugin):
    name = "uppercase"

    def transform(self, text: str) -> str:
        return text.upper()


@manager.register
class DashPlugin(Plugin):
    name = "dashify"

    def transform(self, text: str) -> str:
        return text.replace(" ", "-")


if __name__ == "__main__":
    sample = "  hello plugin world  "
    manager.disable("uppercase")  # Demonstrate runtime toggling
    print(manager.process(sample))  # Output: hello-plugin-world
    manager.enable("uppercase")
    print(manager.process(sample))  # Output: HELLO-PLUGIN-WORLD

class BloomFilter:
    def __init__(self, size, hash_count):
        # Bit array represented as a list of 0/1 values
        self.size = size
        self.hash_count = hash_count
        self.bits = [0] * size

    def _hashes(self, item):
        # Generate multiple positions for the item
        for i in range(self.hash_count):
            position = hash((item, i)) % self.size
            yield position

    def add(self, item):
        # Set all hash positions to 1
        for position in self._hashes(item):
            self.bits[position] = 1

    def might_contain(self, item):
        # If any required bit is 0, the item is definitely not present
        for position in self._hashes(item):
            if self.bits[position] == 0:
                return False
        return True


# Demonstration
if __name__ == "__main__":
    bloom = BloomFilter(size=20, hash_count=3)

    inserted_words = ["apple", "banana", "orange"]
    test_words = ["apple", "grape", "banana", "melon", "orange"]

    for word in inserted_words:
        bloom.add(word)

    print("Inserted words:", inserted_words)
    print("Membership tests:")

    for word in test_words:
        if bloom.might_contain(word):
            print(f"{word}: possibly in set")
        else:
            print(f"{word}: definitely not in set")

class ExperimentTracker:
    def __init__(self):
        self.experiments = []

    def add_experiment(self, model_name, dataset_name, accuracy_score, training_time):
        experiment = {
            "model_name": str(model_name),
            "dataset_name": str(dataset_name),
            "accuracy_score": float(accuracy_score),
            "training_time": float(training_time),
        }
        self.experiments.append(experiment)

    def list_experiments(self):
        if not self.experiments:
            return "No experiments have been added yet."
        return self.experiments

    def best_experiment(self):
        if not self.experiments:
            return "No experiments have been added yet."
        return max(self.experiments, key=lambda experiment: experiment["accuracy_score"])

    def average_accuracy(self):
        if not self.experiments:
            return "No experiments have been added yet."
        total_accuracy = sum(experiment["accuracy_score"] for experiment in self.experiments)
        return total_accuracy / len(self.experiments)


if __name__ == "__main__":
    tracker = ExperimentTracker()

    print("Experiments:", tracker.list_experiments())
    print("Best experiment:", tracker.best_experiment())
    print("Average accuracy:", tracker.average_accuracy())

    tracker.add_experiment("ResNet50", "ImageNet", 0.91, 120.5)
    tracker.add_experiment("BERT", "TextCorpusV1", 0.88, 95.0)
    tracker.add_experiment("MobileNet", "CIFAR-10", 0.93, 45.2)

    print("\nAll experiments:")
    for experiment in tracker.list_experiments():
        print(experiment)

    print("\nBest experiment:")
    print(tracker.best_experiment())

    print("\nAverage accuracy:")
    print(tracker.average_accuracy())

class ConfigError(Exception):
    """Base class for configuration-related errors."""

    def __init__(self, field: str, message: str):
        self.field = field
        super().__init__(message)


class MissingFieldError(ConfigError):
    def __init__(self, field: str):
        super().__init__(field, f"Missing required configuration field: '{field}'")


class InvalidTypeError(ConfigError):
    def __init__(self, field: str, expected_type: str, actual_value):
        actual_type = type(actual_value).__name__
        super().__init__(
            field,
            f"Invalid type for '{field}': expected {expected_type}, got {actual_type}"
        )


class InvalidValueError(ConfigError):
    def __init__(self, field: str, reason: str):
        super().__init__(field, f"Invalid value for '{field}': {reason}")


def _require_int(field: str, value, min_value: int, max_value: int) -> int:
    # Reject bool explicitly because bool is a subclass of int.
    if not isinstance(value, int) or isinstance(value, bool):
        raise InvalidTypeError(field, 'int', value)
    if not (min_value <= value <= max_value):
        raise InvalidValueError(field, f'must be between {min_value} and {max_value}')
    return value


def _require_str(field: str, value) -> str:
    if not isinstance(value, str):
        raise InvalidTypeError(field, 'str', value)
    return value


def load_payment_config(data: dict) -> dict:
    if not isinstance(data, dict):
        raise InvalidTypeError('data', 'dict', data)

    if 'api_key' not in data:
        raise MissingFieldError('api_key')

    api_key = _require_str('api_key', data['api_key']).strip()
    if not api_key:
        raise InvalidValueError('api_key', 'must be a non-empty string')

    timeout = _require_int('timeout', data.get('timeout', 30), 1, 120)
    retries = _require_int('retries', data.get('retries', 3), 0, 10)

    mode = _require_str('mode', data.get('mode', 'test')).strip()
    if mode not in {'test', 'live'}:
        raise InvalidValueError('mode', "must be either 'test' or 'live'")

    return {
        'api_key': api_key,
        'timeout': timeout,
        'retries': retries,
        'mode': mode,
    }

import pytest


def merge_unique_sorted(a, b):
    """Merge two sorted integer lists into one sorted list with unique values."""
    if not isinstance(a, list) or not isinstance(b, list):
        raise TypeError("Both arguments must be lists")

    if any(not isinstance(x, int) for x in a + b):
        raise ValueError("All elements must be integers")

    merged = []
    i = j = 0

    # Two-pointer merge to preserve sorted order efficiently.
    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            value = a[i]
            i += 1
        elif a[i] > b[j]:
            value = b[j]
            j += 1
        else:
            value = a[i]
            i += 1
            j += 1

        if not merged or merged[-1] != value:
            merged.append(value)

    # Append remaining unique values from either list.
    for remainder, index in ((a, i), (b, j)):
        while index < len(remainder):
            value = remainder[index]
            if not merged or merged[-1] != value:
                merged.append(value)
            index += 1

    return merged


# ---------------------- pytest tests ----------------------

def test_merge_basic_lists():
    assert merge_unique_sorted([1, 3, 5], [2, 4, 6]) == [1, 2, 3, 4, 5, 6]


def test_merge_removes_duplicates():
    assert merge_unique_sorted([1, 2, 2, 4], [2, 3, 4, 4]) == [1, 2, 3, 4]


def test_merge_with_empty_lists():
    assert merge_unique_sorted([], [1, 1, 2]) == [1, 2]
    assert merge_unique_sorted([], []) == []


def test_raises_type_error_for_non_list_arguments():
    with pytest.raises(TypeError):
        merge_unique_sorted("not a list", [1, 2])


def test_raises_value_error_for_non_integer_elements():
    with pytest.raises(ValueError):
        merge_unique_sorted([1, "2"], [3, 4])

import time
from typing import Any, Dict, List

import requests


def fetch_all_users(base_url: str, token: str) -> List[Dict[str, Any]]:
    """Fetch all users from a paginated REST API with retries and de-duplication."""
    session = requests.Session()
    session.headers.update({
        "Authorization": f"Bearer {token}",
        "Accept": "application/json",
    })

    users_by_id: Dict[Any, Dict[str, Any]] = {}
    page = 1
    max_retries = 3

    while page is not None:
        url = f"{base_url.rstrip('/')}/users"
        params = {"page": page}

        for attempt in range(max_retries):
            response = session.get(url, params=params, timeout=5)

            # Retry only on rate limiting and server-side errors.
            if response.status_code == 429 or 500 <= response.status_code < 600:
                if attempt == max_retries - 1:
                    response.raise_for_status()
                time.sleep(2 ** attempt)
                continue

            # Fail fast for other client/server errors.
            response.raise_for_status()
            data = response.json()
            break
        else:
            # Defensive fallback; normally unreachable due to raise_for_status above.
            raise RuntimeError("Failed to fetch users after retries")

        for user in data.get("items", []):
            user_id = user.get("id")
            if user_id is not None:
                users_by_id[user_id] = user

        page = data.get("next_page")

    return list(users_by_id.values())

