def get_tasks():
    tasks = []
    print("Enter your tasks. Type 'done' when finished.\n")

    while True:
        name = input("Task name: ").strip()
        if name.lower() == "done":
            break

        if not name:
            print("Task name cannot be empty.\n")
            continue

        while True:
            priority_input = input("Priority number: ").strip()
            try:
                priority = int(priority_input)
                break
            except ValueError:
                print("Please enter a valid integer for priority.")

        tasks.append({"name": name, "priority": priority})
        print()

    return tasks


def sort_tasks(tasks):
    return sorted(tasks, key=lambda task: task["priority"])


def search_tasks(tasks, keyword):
    keyword = keyword.lower()
    return [task for task in tasks if keyword in task["name"].lower()]


def print_tasks(tasks, title="Tasks"):
    print(f"\n{title}:")
    if not tasks:
        print("No tasks found.")
        return

    for i, task in enumerate(tasks, start=1):
        print(f"{i}. {task['name']} (Priority: {task['priority']})")


def main():
    tasks = get_tasks()

    if not tasks:
        print("\nNo tasks were entered.")
        return

    sorted_tasks = sort_tasks(tasks)
    print_tasks(sorted_tasks, "Sorted To-Do List")

    keyword = input("\nEnter a keyword to search for tasks: ").strip()
    matching_tasks = search_tasks(sorted_tasks, keyword)
    print_tasks(matching_tasks, f"Search Results for '{keyword}'")


if __name__ == "__main__":
    main()
