from pathlib import Path


def list_directory_contents():
    # Ask the user for a directory path
    user_input = input("Enter a directory path: ").strip()
    directory = Path(user_input)

    # Check whether the path exists and is a directory
    if not directory.exists():
        print("Error: The path does not exist.")
        return

    if not directory.is_dir():
        print("Error: The path is not a directory.")
        return

    # Get and display the contents of the directory
    items = sorted(directory.iterdir(), key=lambda item: item.name.lower())

    if not items:
