from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any


@dataclass(frozen=True)
class AppConfig:
    name: str
    retries: int
    timeout: float
    tags: tuple[str, ...] = ()
    metadata: dict[str, str] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not self.name.strip():
            raise ValueError("name must be non-empty")
        if self.retries < 0:
            raise ValueError("retries must be non-negative")
        if self.timeout <= 0:
            raise ValueError("timeout must be greater than 0")


@dataclass
class Registry:
    _configs: dict[str, AppConfig] = field(default_factory=dict)

    def register(self, config: AppConfig) -> None:
        if config.name in self._configs:
            raise ValueError(f"duplicate config: {config.name}")
        self._configs[config.name] = config

    def get(self, name: str) -> AppConfig:
        return self._configs[name]

    def filter_by_tag(self, tag: str) -> list[AppConfig]:
        return sorted(
            (config for config in self._configs.values() if tag in config.tags),
            key=lambda config: config.name,
        )


def _parse_tags(value: object) -> tuple[str, ...]:
    if value is None:
        return ()
    if not isinstance(value, (list, tuple)):
        raise ValueError("tags must be a list or tuple of strings")
    if not all(isinstance(item, str) for item in value):
        raise ValueError("tags must contain only strings")
    return tuple(value)


def _parse_metadata(value: object) -> dict[str, str]:
    if value is None:
        return {}
    if not isinstance(value, dict):
        raise ValueError("metadata must be a dict[str, str]")
    if not all(isinstance(k, str) and isinstance(v, str) for k, v in value.items()):
        raise ValueError("metadata keys and values must be strings")
    return dict(value)


def load_configs(rows: list[dict[str, object]]) -> Registry:
    registry = Registry()

    for row in rows:
        try:
            name = row["name"]
            retries = row["retries"]
            timeout = row["timeout"]
        except KeyError as exc:
            raise ValueError(f"missing required field: {exc.args[0]}") from exc

        if not isinstance(name, str):
            raise ValueError("name must be a string")
        if not isinstance(retries, int) or isinstance(retries, bool):
            raise ValueError("retries must be an int")
        if not isinstance(timeout, (int, float)) or isinstance(timeout, bool):
            raise ValueError("timeout must be a float")

        config = AppConfig(
            name=name,
            retries=retries,
            timeout=float(timeout),
            tags=_parse_tags(row.get("tags")),
            metadata=_parse_metadata(row.get("metadata")),
        )
        registry.register(config)

    return registry

import json
import struct
from typing import Any, Dict

try:
    import msgpack
except ImportError:  # Optional dependency checked at runtime
    msgpack = None


REQUIRED_KEYS = {"id", "name", "active", "scores"}


def _validate_record(record: Dict[str, Any]) -> None:
    if set(record.keys()) != REQUIRED_KEYS:
        raise ValueError("record must contain exactly: id, name, active, scores")
    if not isinstance(record["id"], int) or not (0 <= record["id"] <= 0xFFFFFFFF):
        raise ValueError("id must be an unsigned 32-bit integer")
    if not isinstance(record["name"], str):
        raise ValueError("name must be a string")
    if not isinstance(record["active"], bool):
        raise ValueError("active must be a bool")
    if not isinstance(record["scores"], list):
        raise ValueError("scores must be a list")
    for score in record["scores"]:
        if not isinstance(score, int) or not (-32768 <= score <= 32767):
            raise ValueError("each score must be a signed 16-bit integer")


def _validate_deserialized(record: Dict[str, Any]) -> Dict[str, Any]:
    _validate_record(record)
    return record


def serialize_record(record: dict, format_name: str) -> bytes:
    _validate_record(record)
    fmt = format_name.lower()

    if fmt == "json":
        return json.dumps(record, separators=(",", ":"), ensure_ascii=False).encode("utf-8")

    if fmt == "messagepack":
        if msgpack is None:
            raise ValueError("MessagePack support requires the 'msgpack' package")
        return msgpack.packb(record, use_bin_type=True)

    if fmt == "binary":
        name_bytes = record["name"].encode("utf-8")
        if len(name_bytes) > 0xFFFF:
            raise ValueError("encoded name is too long")
        if len(record["scores"]) > 0xFFFF:
            raise ValueError("too many scores")

        parts = [
            struct.pack(">IBH", record["id"], int(record["active"]), len(name_bytes)),
            name_bytes,
            struct.pack(">H", len(record["scores"])),
        ]
        if record["scores"]:
            parts.append(struct.pack(">" + "h" * len(record["scores"]), *record["scores"]))
        return b"".join(parts)

    raise ValueError("unsupported format")


def deserialize_record(data: bytes, format_name: str) -> dict:
    fmt = format_name.lower()

    if fmt == "json":
        try:
            obj = json.loads(data.decode("utf-8"))
        except Exception as e:
            raise ValueError(f"malformed JSON: {e}") from e
        if not isinstance(obj, dict):
            raise ValueError("decoded JSON must be an object")
        return _validate_deserialized(obj)

    if fmt == "messagepack":
        if msgpack is None:
            raise ValueError("MessagePack support requires the 'msgpack' package")
        try:
            obj = msgpack.unpackb(data, raw=False)
        except Exception as e:
            raise ValueError(f"malformed MessagePack: {e}") from e
        if not isinstance(obj, dict):
            raise ValueError("decoded MessagePack must be a map/object")
        return _validate_deserialized(obj)

    if fmt == "binary":
        try:
            if len(data) < 9:
                raise ValueError("binary data too short")
            record_id, active_byte, name_len = struct.unpack(">IBH", data[:7])
            if active_byte not in (0, 1):
                raise ValueError("invalid active flag")

            pos = 7
            end_name = pos + name_len
            if end_name + 2 > len(data):
                raise ValueError("truncated name or scores count")

            name_bytes = data[pos:end_name]
            pos = end_name
            try:
                name = name_bytes.decode("utf-8")
            except UnicodeDecodeError as e:
                raise ValueError("name is not valid UTF-8") from e

            (score_count,) = struct.unpack(">H", data[pos:pos + 2])
            pos += 2
            expected_scores_size = score_count * 2
            if pos + expected_scores_size != len(data):
                raise ValueError("invalid scores section length")

            scores = list(struct.unpack(">" + "h" * score_count, data[pos:])) if score_count else []
            record = {
                "id": record_id,
                "name": name,
                "active": bool(active_byte),
                "scores": scores,
            }
            return _validate_deserialized(record)
        except struct.error as e:
            raise ValueError(f"malformed binary data: {e}") from e

    raise ValueError("unsupported format")

from collections import deque


def round_robin(*iterables):
    """Yield items from each iterable in turn until all are exhausted."""
    # Store active iterators in a deque so we can rotate efficiently.
    active = deque(iter(it) for it in iterables)

    while active:
        it = active.popleft()
        try:
            # Yield one item from the current iterator.
            yield next(it)
            # Put it back to the end if it still has potential items.
            active.append(it)
        except StopIteration:
            # Iterator is exhausted; do not reinsert it.
            pass


def take(n, iterable):
    """Yield at most n items from iterable lazily."""
    it = iter(iterable)
    for _ in range(n):
        try:
            yield next(it)
        except StopIteration:
            return


class Countdown:
    """Custom iterator that counts down from start to 1."""
    def __init__(self, start):
        self.current = start

    def __iter__(self):
        return self

    def __next__(self):
        if self.current <= 0:
            raise StopIteration
        value = self.current
        self.current -= 1
        return value


if __name__ == "__main__":
    data = ["A", "B", "C", "D"]
    squares = (i * i for i in range(1, 6))
    countdown = Countdown(4)

    merged = round_robin(data, squares, countdown)
    result = list(take(10, merged))
    print(result)

