from dataclasses import dataclass
from datetime import datetime, timedelta
from typing import Any, Dict, Iterable, List, Optional, Set


@dataclass(frozen=True)
class Transaction:
    transaction_id: str
    account_id: str
    amount: float
    timestamp: datetime
    country: str
    merchant_category: str

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "Transaction":
        if not isinstance(data, dict):
            raise TypeError("Each transaction record must be a dictionary.")

        required_fields = {
            "transaction_id",
            "account_id",
            "amount",
            "timestamp",
            "country",
            "merchant_category",
        }
        missing_fields = required_fields - data.keys()
        if missing_fields:
            raise ValueError(f"Missing required transaction fields: {sorted(missing_fields)}")

        transaction_id = cls._validate_non_empty_string(data["transaction_id"], "transaction_id")
        account_id = cls._validate_non_empty_string(data["account_id"], "account_id")
        amount = cls._validate_amount(data["amount"])
        timestamp = cls._validate_timestamp(data["timestamp"])
        country = cls._validate_non_empty_string(data["country"], "country").upper()
        merchant_category = cls._validate_non_empty_string(data["merchant_category"], "merchant_category")

        return cls(
            transaction_id=transaction_id,
            account_id=account_id,
            amount=amount,
            timestamp=timestamp,
            country=country,
            merchant_category=merchant_category,
        )

    @staticmethod
    def _validate_non_empty_string(value: Any, field_name: str) -> str:
        if not isinstance(value, str):
            raise TypeError(f"'{field_name}' must be a string.")
        value = value.strip()
        if not value:
            raise ValueError(f"'{field_name}' cannot be empty.")
        return value

    @staticmethod
    def _validate_amount(value: Any) -> float:
        if isinstance(value, bool):
            raise TypeError("'amount' must be a numeric value, not a boolean.")
        try:
            amount = float(value)
        except (TypeError, ValueError) as exc:
            raise TypeError("'amount' must be a numeric value.") from exc

        if amount < 0:
            raise ValueError("'amount' cannot be negative.")
        return amount

    @staticmethod
    def _validate_timestamp(value: Any) -> datetime:
        if isinstance(value, datetime):
            return value

        if not isinstance(value, str):
            raise TypeError("'timestamp' must be a datetime object or ISO 8601 string.")

        value = value.strip()
        if not value:
            raise ValueError("'timestamp' cannot be empty.")

        normalized = value.replace("Z", "+00:00")
        try:
            return datetime.fromisoformat(normalized)
        except ValueError as exc:
            raise ValueError(
                f"Invalid timestamp format: {value!r}. Expected ISO 8601 format."
            ) from exc


class FraudDetector:
    def __init__(
        self,
        large_amount_threshold: float = 10000.0,
        allowed_countries: Optional[Iterable[str]] = None,
        rapid_txn_count_threshold: int = 3,
        rapid_txn_window_minutes: int = 5,
    ) -> None:
        self.large_amount_threshold = self._validate_positive_number(
            large_amount_threshold, "large_amount_threshold", allow_zero=False
        )
        self.allowed_countries = self._normalize_allowed_countries(allowed_countries)
        self.rapid_txn_count_threshold = self._validate_integer_threshold(
            rapid_txn_count_threshold, "rapid_txn_count_threshold", minimum=2
        )
        self.rapid_txn_window_minutes = self._validate_integer_threshold(
            rapid_txn_window_minutes, "rapid_txn_window_minutes", minimum=1
        )

    @staticmethod
    def _validate_positive_number(value: Any, field_name: str, allow_zero: bool = False) -> float:
        if isinstance(value, bool):
            raise TypeError(f"'{field_name}' must be a numeric value, not a boolean.")
        try:
            number = float(value)
        except (TypeError, ValueError) as exc:
            raise TypeError(f"'{field_name}' must be a numeric value.") from exc

        if allow_zero:
            if number < 0:
                raise ValueError(f"'{field_name}' must be greater than or equal to 0.")
        else:
            if number <= 0:
                raise ValueError(f"'{field_name}' must be greater than 0.")
        return number

    @staticmethod
    def _validate_integer_threshold(value: Any, field_name: str, minimum: int) -> int:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"'{field_name}' must be an integer.")
        if value < minimum:
            raise ValueError(f"'{field_name}' must be at least {minimum}.")
        return value

    @staticmethod
    def _normalize_allowed_countries(allowed_countries: Optional[Iterable[str]]) -> Optional[Set[str]]:
        if allowed_countries is None:
            return None

        if isinstance(allowed_countries, (str, bytes)):
            raise TypeError("'allowed_countries' must be an iterable of country codes/strings.")

        normalized: Set[str] = set()
        for country in allowed_countries:
            if not isinstance(country, str):
                raise TypeError("Each allowed country must be a string.")
            country = country.strip().upper()
            if not country:
                raise ValueError("Allowed country values cannot be empty.")
            normalized.add(country)

        return normalized

    def analyze_transactions(self, transaction_records: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        transactions = self._parse_transactions(transaction_records)
        flagged_reasons = self._evaluate_transactions(transactions)
        return self._build_flagged_output(transactions, flagged_reasons)

    def _parse_transactions(self, transaction_records: List[Dict[str, Any]]) -> List[Transaction]:
        if not isinstance(transaction_records, list):
            raise TypeError("transaction_records must be provided as a list of dictionaries.")

        transactions: List[Transaction] = []
        seen_transaction_ids: Set[str] = set()

        for index, record in enumerate(transaction_records):
            try:
                transaction = Transaction.from_dict(record)
            except Exception as exc:
                raise ValueError(f"Invalid transaction at index {index}: {exc}") from exc

            if transaction.transaction_id in seen_transaction_ids:
                raise ValueError(
                    f"Duplicate transaction_id detected: {transaction.transaction_id!r}"
                )
            seen_transaction_ids.add(transaction.transaction_id)
            transactions.append(transaction)

        return transactions

    def _evaluate_transactions(self, transactions: List[Transaction]) -> Dict[str, List[str]]:
        flagged_reasons: Dict[str, List[str]] = {txn.transaction_id: [] for txn in transactions}

        self._apply_large_amount_rule(transactions, flagged_reasons)
        self._apply_country_rule(transactions, flagged_reasons)
        self._apply_rapid_transactions_rule(transactions, flagged_reasons)

        return {
            transaction_id: reasons
            for transaction_id, reasons in flagged_reasons.items()
            if reasons
        }

    def _apply_large_amount_rule(
        self,
        transactions: List[Transaction],
        flagged_reasons: Dict[str, List[str]],
    ) -> None:
        for transaction in transactions:
            if transaction.amount > self.large_amount_threshold:
                flagged_reasons[transaction.transaction_id].append(
                    f"Large transaction amount exceeds threshold of {self.large_amount_threshold:.2f}"
                )

    def _apply_country_rule(
        self,
        transactions: List[Transaction],
        flagged_reasons: Dict[str, List[str]],
    ) -> None:
        if self.allowed_countries is None:
            return

        for transaction in transactions:
            if transaction.country not in self.allowed_countries:
                flagged_reasons[transaction.transaction_id].append(
                    f"Transaction country '{transaction.country}' is outside the allowed list"
                )

    def _apply_rapid_transactions_rule(
        self,
        transactions: List[Transaction],
        flagged_reasons: Dict[str, List[str]],
    ) -> None:
        transactions_by_account: Dict[str, List[Transaction]] = {}
        for transaction in transactions:
            transactions_by_account.setdefault(transaction.account_id, []).append(transaction)

        window_delta = timedelta(minutes=self.rapid_txn_window_minutes)

        for account_id, account_transactions in transactions_by_account.items():
            sorted_transactions = sorted(account_transactions, key=lambda txn: txn.timestamp)
            left = 0

            for right in range(len(sorted_transactions)):
                while (
                    sorted_transactions[right].timestamp - sorted_transactions[left].timestamp
                    > window_delta
                ):
                    left += 1

                window_size = right - left + 1
                if window_size >= self.rapid_txn_count_threshold:
                    for idx in range(left, right + 1):
                        txn = sorted_transactions[idx]
                        reason = (
                            f"{window_size} transactions from account '{account_id}' within "
                            f"{self.rapid_txn_window_minutes} minute(s)"
                        )
                        if reason not in flagged_reasons[txn.transaction_id]:
                            flagged_reasons[txn.transaction_id].append(reason)

    def _build_flagged_output(
        self,
        transactions: List[Transaction],
        flagged_reasons: Dict[str, List[str]],
    ) -> List[Dict[str, Any]]:
        transaction_map = {txn.transaction_id: txn for txn in transactions}
        flagged_output: List[Dict[str, Any]] = []

        for transaction_id, reasons in flagged_reasons.items():
            transaction = transaction_map[transaction_id]
            flagged_output.append(
                {
                    "transaction_id": transaction.transaction_id,
                    "account_id": transaction.account_id,
                    "amount": transaction.amount,
                    "timestamp": transaction.timestamp.isoformat(),
                    "country": transaction.country,
                    "merchant_category": transaction.merchant_category,
                    "reasons": reasons,
                }
            )

        flagged_output.sort(key=lambda item: item["timestamp"])
        return flagged_output


def detect_potential_fraud(
    transaction_records: List[Dict[str, Any]],
    large_amount_threshold: float = 10000.0,
    allowed_countries: Optional[Iterable[str]] = None,
    rapid_txn_count_threshold: int = 3,
    rapid_txn_window_minutes: int = 5,
) -> List[Dict[str, Any]]:
    detector = FraudDetector(
        large_amount_threshold=large_amount_threshold,
        allowed_countries=allowed_countries,
        rapid_txn_count_threshold=rapid_txn_count_threshold,
        rapid_txn_window_minutes=rapid_txn_window_minutes,
    )
    return detector.analyze_transactions(transaction_records)


