from typing import Any, Callable, Dict, List


def process_batches(
    jobs: List[Dict[str, Any]],
    transform: Callable[[Any], Any],
    batch_size: int = 3,
) -> Dict[str, Any]:
    """Process jobs in batches with validation, retries, and metrics."""
    if batch_size <= 0:
        raise ValueError("batch_size must be positive")

    successes: List[Dict[str, Any]] = []
    failed_ids: List[Any] = []
    metrics: List[Dict[str, int]] = []
    required_fields = {"id", "payload", "retries"}

    for start in range(0, len(jobs), batch_size):
        batch = jobs[start:start + batch_size]
        batch_success = 0
        batch_failed = 0
        batch_invalid = 0

        for job in batch:
            if not required_fields.issubset(job):
                failed_ids.append(job.get("id"))
                batch_invalid += 1
                continue

            job_id = job["id"]
            payload = job["payload"]
            retries = job["retries"]

            if not isinstance(retries, int) or retries < 0:
                failed_ids.append(job_id)
                batch_invalid += 1
                continue

            last_error = None
            for _ in range(retries + 1):
                try:
                    result = transform(payload)
                    successes.append({"id": job_id, "result": result})
                    batch_success += 1
                    break
                except Exception as exc:  # Retry on transform failures
                    last_error = str(exc)
            else:
                failed_ids.append(job_id)
                batch_failed += 1

        metrics.append(
            {
                "batch_index": start // batch_size,
                "input_count": len(batch),
                "success_count": batch_success,
                "failed_count": batch_failed,
                "invalid_count": batch_invalid,
            }
        )

    return {
        "successes": successes,
        "failed_ids": failed_ids,
        "metrics": metrics,
    }


