def min_pal_partition(s: str) -> int:
    # Minimum cuts needed so every partitioned substring is a palindrome.
    n = len(s)
    if n <= 1:
        return 0

    # is_pal[i][j] == True if s[i:j+1] is a palindrome
    is_pal = [[False] * n for _ in range(n)]

    # Build palindrome table bottom-up
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if s[i] == s[j] and (j - i <= 2 or is_pal[i + 1][j - 1]):
                is_pal[i][j] = True

    # dp[i] = minimum cuts needed for s[:i+1]
    dp = [0] * n
    for i in range(n):
        if is_pal[0][i]:
            dp[i] = 0
        else:
            dp[i] = i  # Worst case: cut between every character
            for j in range(i):
                if is_pal[j + 1][i]:
                    dp[i] = min(dp[i], dp[j] + 1)

    return dp[-1]


