def analyze_orders(orders):
    """Analyze e-commerce orders using list comprehensions and list operations."""

    def is_valid(order):
        items = order.get('items', [])
        return bool(items) and all(
            item.get('qty', 0) > 0 and item.get('price', -1) >= 0
            for item in items
        )

    def order_total(order):
        subtotal = sum(item['qty'] * item['price'] for item in order['items'])
        discount = order.get('coupon', 0)
        return round(subtotal * (1 - discount), 2)

    # Keep valid orders in original order for downstream outputs.
    valid_orders = [order for order in orders if is_valid(order)]

    # 1) Sorted valid order IDs.
    valid_order_ids = sorted([order['id'] for order in valid_orders])

    # Precompute totals once for reuse.
    totals_by_order = [(order['id'], order_total(order), order['customer']) for order in valid_orders]

    # 2) Unique customers with order total > 100.
    high_value_customers = sorted({customer for _, total, customer in totals_by_order if total > 100})

    # 3) Aggregate item quantities across valid orders.
    all_items = [item for order in valid_orders for item in order['items']]
    item_names = {item['name'] for item in all_items}
    quantity_by_item = {
        name: sum(item['qty'] for item in all_items if item['name'] == name)
        for name in item_names
    }
    top_items = [
        name for name, _ in sorted(
            quantity_by_item.items(),
            key=lambda pair: (-pair[1], pair[0])
        )[:3]
    ]

    # 4) Order totals in original valid-order input order.
    order_totals = [(order_id, total) for order_id, total, _ in totals_by_order]

    return {
        'valid_order_ids': valid_order_ids,
        'high_value_customers': high_value_customers,
        'top_items': top_items,
        'order_totals': order_totals,
    }


