import json
import msgpack
import sys
from collections import defaultdict
from typing import Any, Dict, List


def is_valid_record(obj: Any) -> bool:
    """Return True if the object matches the required schema."""
    return (
        isinstance(obj, dict)
        and isinstance(obj.get("category"), str)
        and isinstance(obj.get("id"), int)
        and isinstance(obj.get("payload"), dict)
    )



def convert_ndjson_to_grouped_msgpack(input_path: str, output_path: str) -> None:
    """Read NDJSON, validate and group records, then write MessagePack output."""
    grouped: Dict[str, List[Dict[str, Any]]] = defaultdict(list)

    with open(input_path, "r", encoding="utf-8") as f:
        for line_number, line in enumerate(f, start=1):
            line = line.strip()
            if not line:
                continue

            try:
                obj = json.loads(line)
            except json.JSONDecodeError:
                # Skip malformed JSON lines
                continue

            if not is_valid_record(obj):
                # Skip records with missing or wrong-typed fields
                continue

            grouped[obj["category"]].append({
                "id": obj["id"],
                "payload": obj["payload"],
            })

    # Sort each category's records by id for deterministic output
    result = {
        category: sorted(records, key=lambda r: r["id"])
        for category, records in grouped.items()
    }

    with open(output_path, "wb") as f:
        msgpack.pack(result, f, use_bin_type=True)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python script.py input.ndjson output.msgpack")
        sys.exit(1)

    convert_ndjson_to_grouped_msgpack(sys.argv[1], sys.argv[2])

from __future__ import annotations

from dataclasses import dataclass, fields, replace
from typing import Any


@dataclass(frozen=True)
class AppConfig:
    host: str
    port: int
    debug: bool
    tags: tuple[str, ...]
    metadata: dict[str, str]


def _validate_field(name: str, value: Any) -> Any:
    """Validate and normalize a single AppConfig field value."""
    if name == "host":
        if not isinstance(value, str):
            raise TypeError("host must be a str")
        return value

    if name == "port":
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("port must be an int")
        return value

    if name == "debug":
        if not isinstance(value, bool):
            raise TypeError("debug must be a bool")
        return value

    if name == "tags":
        if isinstance(value, list):
            value = tuple(value)
        if not isinstance(value, tuple) or not all(isinstance(item, str) for item in value):
            raise TypeError("tags must be a tuple[str, ...] or list[str]")
        return value

    if name == "metadata":
        if not isinstance(value, dict):
            raise TypeError("metadata must be a dict[str, str]")
        if not all(isinstance(k, str) and isinstance(v, str) for k, v in value.items()):
            raise TypeError("metadata must contain only str keys and str values")
        return value

    raise ValueError(f"Unknown field: {name}")


def merge_config(base: AppConfig, overrides: dict[str, object]) -> AppConfig:
    """Return a new AppConfig with validated overrides applied."""
    valid_fields = {f.name for f in fields(AppConfig)}

    unknown = set(overrides) - valid_fields
    if unknown:
        raise ValueError(f"Unknown override keys: {sorted(unknown)}")

    normalized: dict[str, Any] = {}
    for key, value in overrides.items():
        normalized[key] = _validate_field(key, value)

    return replace(base, **normalized)


if __name__ == "__main__":
    base_config = AppConfig(
        host="localhost",
        port=8080,
        debug=False,
        tags=("api", "v1"),
        metadata={"env": "dev"},
    )

    updated = merge_config(
        base_config,
        {
            "port": 9090,
            "debug": True,
            "tags": ["api", "v2"],
            "metadata": {"env": "staging", "owner": "team-x"},
        },
    )

    print(updated)

from collections import deque


class MaxStack:
    def __init__(self):
        self.data = []
        self.max_data = []

    def push(self, x):
        self.data.append(x)
        if not self.max_data:
            self.max_data.append(x)
        else:
            self.max_data.append(max(x, self.max_data[-1]))

    def pop(self):
        if not self.data:
            return None
        self.max_data.pop()
        return self.data.pop()

    def max(self):
        return self.max_data[-1] if self.max_data else None

    def __bool__(self):
        return bool(self.data)


class MaxQueue:
    def __init__(self):
        self.data = deque()
        self.max_data = deque()

    def enqueue(self, x):
        self.data.append(x)
        while self.max_data and self.max_data[-1] < x:
            self.max_data.pop()
        self.max_data.append(x)

    def dequeue(self):
        if not self.data:
            return None
        val = self.data.popleft()
        if self.max_data[0] == val:
            self.max_data.popleft()
        return val

    def max(self):
        return self.max_data[0] if self.max_data else None

    def __bool__(self):
        return bool(self.data)


class MaxQueueStackProcessor:
    def __init__(self):
        self.stack = MaxStack()
        self.queue = MaxQueue()

    def execute(self, commands):
        outputs = []

        for command in commands:
            parts = command.split()
            op = parts[0]

            if op == 'PUSH_STACK':
                self.stack.push(int(parts[1]))
            elif op == 'POP_STACK':
                outputs.append(self.stack.pop())
            elif op == 'MAX_STACK':
                outputs.append(self.stack.max())
            elif op == 'ENQUEUE':
                self.queue.enqueue(int(parts[1]))
            elif op == 'DEQUEUE':
                outputs.append(self.queue.dequeue())
            elif op == 'MAX_QUEUE':
                outputs.append(self.queue.max())
            elif op == 'PROCESS':
                removed = []
                while self.stack and self.queue:
                    stack_max = self.stack.max()
                    queue_max = self.queue.max()
                    if stack_max >= queue_max:
                        removed.append(self.stack.pop())
                    else:
                        removed.append(self.queue.dequeue())
                outputs.append(removed)

        return outputs


