class TypedRange:
    """Descriptor that enforces type and inclusive numeric bounds."""

    def __init__(self, expected_type, min_value, max_value):
        self.expected_type = expected_type
        self.min_value = min_value
        self.max_value = max_value
        self.private_name = None

    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, self.expected_type):
            raise TypeError(
                f"Expected {self.expected_type} for {self.private_name[1:]}, got {type(value)}"
            )
        if not (self.min_value <= value <= self.max_value):
            raise ValueError(
                f"{self.private_name[1:]} must be between {self.min_value} and {self.max_value}"
            )
        setattr(instance, self.private_name, value)


class ServiceConfig:
    port = TypedRange(int, 1, 65535)
    timeout = TypedRange((int, float), 0.1, 120.0)

    def __init__(self, host, port, timeout=30.0):
        self.host = host
        self.port = port
        self.timeout = timeout

    @property
    def host(self):
        return self._host

    @host.setter
    def host(self, value):
        if not isinstance(value, str):
            raise TypeError("host must be a string")
        cleaned = value.strip()
        if not cleaned:
            raise ValueError("host cannot be empty")
        self._host = cleaned

    @property
    def base_url(self):
        return f"http://{self.host}:{self.port}"


