class Editor:
    def __init__(self):
        self.text = ""

    def insert(self, value: str):
        self.text += value

    def delete_last(self, count: int) -> str:
        deleted = self.text[-count:] if count <= len(self.text) else self.text
        self.text = self.text[:-count] if count <= len(self.text) else ""
        return deleted


class Command:
    def execute(self):
        raise NotImplementedError

    def undo(self):
        raise NotImplementedError


class InsertTextCommand(Command):
    def __init__(self, editor: Editor, value: str):
        self.editor = editor
        self.value = value

    def execute(self):
        self.editor.insert(self.value)

    def undo(self):
        self.editor.delete_last(len(self.value))


class DeleteTextCommand(Command):
    def __init__(self, editor: Editor, count: int):
        self.editor = editor
        self.count = count
        self.deleted_text = ""

    def execute(self):
        self.deleted_text = self.editor.delete_last(self.count)

    def undo(self):
        self.editor.insert(self.deleted_text)


class CommandInvoker:
    def __init__(self):
        self.history = []

    def run(self, command: Command):
        command.execute()
        self.history.append(command)

    def undo_last(self):
        if self.history:
            command = self.history.pop()
            command.undo()


if __name__ == "__main__":
