    invoker = CommandInvoker()

    commands = [
        InsertTextCommand(editor, "Hello"),
        InsertTextCommand(editor, " World"),
        DeleteTextCommand(editor, 3),
        InsertTextCommand(editor, "rld!"),
    ]

    for cmd in commands:
        invoker.run(cmd)
        print("Current text:", editor.text)

    invoker.undo_last()
    print("After undo:", editor.text)

    invoker.undo_last()
    print("After second undo:", editor.text)

class PluginManager:
    """Singleton plugin manager with a simple processor registry."""

    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._registry = {}
        return cls._instance

    def register(self, name, processor):
        """Register a processor function under a unique name."""
        if name in self._registry:
            raise ValueError(f"Processor '{name}' is already registered.")
        if not callable(processor):
            raise TypeError("processor must be callable")
        self._registry[name] = processor

    def get(self, name):
        """Return a registered processor by name."""
        try:
            return self._registry[name]
        except KeyError:
            raise KeyError(f"Processor '{name}' is not registered.")

    def run(self, name, data):
        """Run a named processor on the given data."""
        processor = self.get(name)
        return processor(data)


