from functools import lru_cache, wraps


def memoize(func=None, *, maxsize=128):
    """Decorator supporting both @memoize and @memoize(maxsize=...)."""
    def decorator(fn):
        # Create an LRU-cached version of the function.
        cached_fn = lru_cache(maxsize=maxsize)(fn)

        @wraps(fn)
        def wrapper(*args, **kwargs):
            return cached_fn(*args, **kwargs)

        # Expose cache management utilities on the wrapper.
        wrapper.cache_info = cached_fn.cache_info
        wrapper.cache_clear = cached_fn.cache_clear
        return wrapper

    # Handle bare decorator usage: @memoize
    if func is not None:
        return decorator(func)
    return decorator


@memoize(maxsize=256)
def fib(n):
    """Return the nth Fibonacci number using recursion."""
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)


def main():
    result = fib(20)
    print("fib(20) =", result)
    print("cache before clear:", fib.cache_info())
    fib.cache_clear()
    print("cache after clear:", fib.cache_info())


