def merge_sort(products):
    # Sort products by price using merge sort
    if len(products) <= 1:
        return products

    mid = len(products) // 2
    left = merge_sort(products[:mid])
    right = merge_sort(products[mid:])

    return merge(left, right)


def merge(left, right):
    merged = []
    i = j = 0

    while i < len(left) and j < len(right):
        if left[i][1] <= right[j][1]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1

    merged.extend(left[i:])
    merged.extend(right[j:])
    return merged


def binary_search_by_price(products, target_price):
    # Search for a product by price in a sorted list
    low, high = 0, len(products) - 1

    while low <= high:
        mid = (low + high) // 2
        mid_price = products[mid][1]

        if mid_price == target_price:
            return products[mid]
        elif mid_price < target_price:
            low = mid + 1
        else:
            high = mid - 1

    return None


