from collections import defaultdict


def count_target_expressions(nums, target):
    """
    Count how many ways to assign + or - to each number in nums
    so that the final sum equals target.

    Dynamic programming idea:
    dp[s] = number of ways to reach sum s after processing
    the current prefix of nums.
    """
    dp = {0: 1}

    for num in nums:
        next_dp = defaultdict(int)
        for current_sum, ways in dp.items():
            next_dp[current_sum + num] += ways
            next_dp[current_sum - num] += ways
        dp = next_dp

    return dp.get(target, 0)


def main():
    examples = [
        ([1, 1, 1, 1, 1], 3),
        ([2, 3, 5, 7], 7),
        ([1, 2, 3, 4, 5], 1),
    ]

    for nums, target in examples:
        result = count_target_expressions(nums, target)
        print(f"nums={nums}, target={target} -> ways={result}")


