class TrieNode:
    def __init__(self):
        self.children = {}
        self.prefix_count = 0  # number of words passing through this node
        self.word_count = 0    # number of words ending at this node


class WordFilter:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            node.prefix_count += 1
        node.word_count += 1

    def delete(self, word: str) -> None:
        # Only delete if the word exists.
        if self.count_words_equal_to(word) == 0:
            return

        node = self.root
        stack = []  # store (parent, char, child) for optional cleanup
        for ch in word:
            child = node.children[ch]
            stack.append((node, ch, child))
            node = child

        node.word_count -= 1

        # Decrease prefix counts along the path.
        for parent, ch, child in stack:
            child.prefix_count -= 1

        # Remove unnecessary nodes from the end.
        for parent, ch, child in reversed(stack):
            if child.prefix_count == 0 and child.word_count == 0 and not child.children:
                del parent.children[ch]
            else:
                break

    def count_words_equal_to(self, word: str) -> int:
        node = self.root
        for ch in word:
            if ch not in node.children:
                return 0
            node = node.children[ch]
        return node.word_count

    def count_words_starting_with(self, prefix: str) -> int:
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return 0
            node = node.children[ch]
        return node.prefix_count

from typing import List, Dict


WIRE_VARINT = 0
WIRE_LEN = 2


def _read_varint(data: bytes, pos: int) -> tuple[int, int]:
    """Read a protobuf varint starting at pos."""
    result = 0
    shift = 0
    while True:
        if pos >= len(data):
            raise ValueError("truncated varint")
        b = data[pos]
        pos += 1
        result |= (b & 0x7F) << shift
        if not (b & 0x80):
            return result, pos
        shift += 7
        if shift >= 64:
            raise ValueError("varint too long")


def _read_length_delimited(data: bytes, pos: int) -> tuple[bytes, int]:
    length, pos = _read_varint(data, pos)
    end = pos + length
    if end > len(data):
        raise ValueError("truncated length-delimited field")
    return data[pos:end], end


def _parse_person(data: bytes) -> Dict:
    person = {"id": 0, "name": "", "email": "", "active": False}
    pos = 0

    while pos < len(data):
        key, pos = _read_varint(data, pos)
        field_num = key >> 3
        wire_type = key & 0x07

        if field_num == 1 and wire_type == WIRE_VARINT:
            person["id"], pos = _read_varint(data, pos)
        elif field_num == 2 and wire_type == WIRE_LEN:
            raw, pos = _read_length_delimited(data, pos)
            person["name"] = raw.decode("utf-8")
        elif field_num == 3 and wire_type == WIRE_LEN:
            raw, pos = _read_length_delimited(data, pos)
            person["email"] = raw.decode("utf-8")
        elif field_num == 4 and wire_type == WIRE_VARINT:
            value, pos = _read_varint(data, pos)
            person["active"] = bool(value)
        else:
            raise ValueError(f"unsupported field or wire type in Person: field={field_num}, wire={wire_type}")

    if not person["name"]:
        raise ValueError("missing required field: name")
    return person


def decode_people(blob: bytes) -> List[Dict]:
    """Decode a top-level message containing repeated field 1 Person entries."""
    people = []
    pos = 0

    while pos < len(blob):
        key, pos = _read_varint(blob, pos)
        field_num = key >> 3
        wire_type = key & 0x07

        if field_num != 1 or wire_type != WIRE_LEN:
            raise ValueError(f"unsupported top-level field or wire type: field={field_num}, wire={wire_type}")

        person_bytes, pos = _read_length_delimited(blob, pos)
        people.append(_parse_person(person_bytes))

    return people


if __name__ == "__main__":
