class Router:
    def __init__(self):
        self.routes = []

    def add_route(self, method, pattern, handler_name):
        # Normalize and store the route definition
        route = {
            'method': method.upper(),
            'pattern': pattern,
            'segments': self._split_path(pattern),
            'handler': handler_name,
        }
        self.routes.append(route)

    def resolve(self, method, path):
        method = method.upper()
        path_segments = self._split_path(path)

        for route in self.routes:
            if route['method'] != method:
                continue

            pattern_segments = route['segments']
            if len(pattern_segments) != len(path_segments):
                continue

            params = {}
            matched = True

            for pattern_part, path_part in zip(pattern_segments, path_segments):
                if self._is_param(pattern_part):
                    param_name = pattern_part[1:-1]
                    params[param_name] = path_part
                elif pattern_part != path_part:
                    matched = False
                    break

            if matched:
                return {'handler': route['handler'], 'params': params}

        return None

    def _split_path(self, path):
        # Remove leading/trailing slashes and split into segments
        stripped = path.strip('/')
        return [] if stripped == '' else stripped.split('/')

    def _is_param(self, segment):
        return segment.startswith('<') and segment.endswith('>') and len(segment) > 2


# Example usage
if __name__ == '__main__':
