    print(router.resolve('DELETE', '/users/42'))

def sum_nested(data):
    """Recursively sum all integers in a nested list."""
    total = 0

    for item in data:
        if isinstance(item, int):
            total += item
        elif isinstance(item, list):
            total += sum_nested(item)
        else:
            raise TypeError(f"Unsupported element type: {type(item).__name__}")

    return total


