import heapq


def k_largest_sum(nums, k):
    """Return the sum of the k largest numbers in nums using a min-heap."""
    if k <= 0:
        return 0
    if k >= len(nums):
        return sum(nums)

    min_heap = []

    for num in nums:
        if len(min_heap) < k:
            heapq.heappush(min_heap, num)
        elif num > min_heap[0]:
            # Replace the smallest among the current k largest
            heapq.heapreplace(min_heap, num)

    return sum(min_heap)


