import re
from typing import Any, Dict


_PATTERN = re.compile(r"(?<!\\)\{\{\s*(.*?)\s*\}\}")
_DEFAULT_PATTERN = re.compile(r"^([a-zA-Z_][\w\.]*)(?:\|default\((['\"])(.*?)\2\))?$")


def _resolve_path(context: Dict[str, Any], path: str) -> Any:
    """Resolve dotted paths like 'user.profile.name' in nested dictionaries."""
    value: Any = context
    for part in path.split('.'):
        if not isinstance(value, dict) or part not in value:
            raise KeyError(path)
        value = value[part]
    return value


def render_template(template: str, context: Dict[str, Any]) -> str:
    """Render placeholders in the template using the provided context."""

    def replace(match: re.Match) -> str:
        expr = match.group(1).strip()
        parsed = _DEFAULT_PATTERN.match(expr)
        if not parsed:
            raise ValueError(f"Invalid placeholder syntax: {expr}")

        path, _, default_value = parsed.groups()

        try:
            value = _resolve_path(context, path)
        except KeyError:
            if default_value is not None:
                return default_value
            raise ValueError(f"Missing value for placeholder: {path}") from None

        if value is None:
            if default_value is not None:
                return default_value
            raise ValueError(f"None value for placeholder without default: {path}")

        return str(value)

    rendered = _PATTERN.sub(replace, template)

    # Unescape literal template markers: \{{ x }} -> {{ x }}
    return rendered.replace(r"\{{", "{{")


