class Stack:
    def __init__(self):
        self.items = []

    def push(self, value):
        self.items.append(value)

    def pop(self):
        if not self.items:
            return 'Stack is empty'
        return self.items.pop()

    def display(self):
        return self.items


class Queue:
    def __init__(self):
        self.items = []

    def enqueue(self, value):
        self.items.append(value)

    def dequeue(self):
        if not self.items:
            return 'Queue is empty'
        return self.items.pop(0)

    def display(self):
        return self.items


