from pydantic import BaseModel, Field, ValidationError, field_validator, model_validator, ConfigDict


class Resources(BaseModel):
    cpu: str
    memory: str

    @field_validator('cpu')
    @classmethod
    def validate_cpu(cls, value: str) -> str:
        match = re.fullmatch(r'(\d+)m', value)
        if not match:
            raise ValueError("cpu must be in the form '<number>m'")
        amount = int(match.group(1))
        if not 100 <= amount <= 4000:
            raise ValueError('cpu must be between 100m and 4000m')
        return value

    @field_validator('memory')
    @classmethod
    def validate_memory(cls, value: str) -> str:
        match = re.fullmatch(r'(\d+)(Mi|Gi)', value)
        if not match:
            raise ValueError("memory must be in the form '<number>Mi' or '<number>Gi'")

        amount = int(match.group(1))
        unit = match.group(2)

        if unit == 'Gi':
            if not 1 <= amount <= 16:
                raise ValueError('memory in Gi must be between 1Gi and 16Gi')
        else:  # Mi
            if not 128 <= amount <= 16384:
                raise ValueError('memory in Mi must be between 128Mi and 16384Mi')

        return value


