class TrieNode:
    def __init__(self):
        self.children = {}
        self.prefix_count = 0   # number of words passing through this node
        self.word_count = 0     # number of words ending at this node


class PrefixDictionary:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            node.prefix_count += 1
        node.word_count += 1

    def count_words_equal_to(self, word: str) -> int:
        node = self.root
        for ch in word:
            if ch not in node.children:
                return 0
            node = node.children[ch]
        return node.word_count

    def count_words_starting_with(self, prefix: str) -> int:
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return 0
            node = node.children[ch]
        return node.prefix_count

    def erase(self, word: str) -> None:
        # Only erase if the word exists.
        if self.count_words_equal_to(word) == 0:
            return

        node = self.root
        stack = []  # track parent, char, child for optional cleanup

        for ch in word:
            child = node.children[ch]
            stack.append((node, ch, child))
            node = child

        node.word_count -= 1

        # Decrease prefix counters along the path.
        for parent, ch, child in stack:
            child.prefix_count -= 1

        # Optional pruning of unused nodes from the end.
        for parent, ch, child in reversed(stack):
            if child.prefix_count == 0 and child.word_count == 0 and not child.children:
                del parent.children[ch]
            else:
                break


