    print(pd.count_words_equal_to('app'))        # 1
    print(pd.count_words_starting_with('app'))   # 3

    pd.erase('apple')
    print(pd.count_words_equal_to('apple'))      # 1
    print(pd.count_words_starting_with('app'))   # 2

def read_varint(data, pos):
    """Read a protobuf varint starting at pos."""
    result = 0
    shift = 0
    while True:
        if pos >= len(data):
            raise ValueError('Unexpected end of data while reading varint')
        byte = data[pos]
        pos += 1
        result |= (byte & 0x7F) << shift
        if not (byte & 0x80):
            return result, pos
        shift += 7
        if shift >= 64:
            raise ValueError('Varint too long')


def skip_field(data, pos, wire_type):
    """Skip an unknown field for supported wire types."""
    if wire_type == 0:  # varint
        _, pos = read_varint(data, pos)
        return pos
    if wire_type == 2:  # length-delimited
        size, pos = read_varint(data, pos)
        end = pos + size
        if end > len(data):
            raise ValueError('Length-delimited field exceeds input size')
        return end
    raise ValueError(f'Unsupported wire type: {wire_type}')


def parse_user_message(data):
    """Parse a fixed protobuf message into a dictionary."""
    result = {
        'user_id': None,
        'name': None,
        'active': None,
    }
    pos = 0

    while pos < len(data):
        key, pos = read_varint(data, pos)
        field_number = key >> 3
        wire_type = key & 0x07

        if field_number == 1:
            if wire_type != 0:
                raise ValueError('Field user_id must use varint wire type')
            value, pos = read_varint(data, pos)
            result['user_id'] = value
        elif field_number == 2:
            if wire_type != 2:
                raise ValueError('Field name must use length-delimited wire type')
            size, pos = read_varint(data, pos)
            end = pos + size
            if end > len(data):
                raise ValueError('String field exceeds input size')
            try:
                result['name'] = data[pos:end].decode('utf-8')
            except UnicodeDecodeError as e:
                raise ValueError('Invalid UTF-8 in name field') from e
            pos = end
        elif field_number == 3:
            if wire_type != 0:
                raise ValueError('Field active must use varint wire type')
            value, pos = read_varint(data, pos)
            if value not in (0, 1):
                raise ValueError('Boolean field active must be 0 or 1')
            result['active'] = bool(value)
        else:
            pos = skip_field(data, pos, wire_type)

    return result


