from datetime import datetime


def parse_time(time_str):
    """Convert HH:MM into a datetime object for easy comparison."""
    return datetime.strptime(time_str, "%H:%M")


def format_time(dt):
    """Convert a datetime object back into HH:MM format."""
    return dt.strftime("%H:%M")


def merge_busy_intervals(events):
    """
    Merge overlapping or touching busy intervals.

    Args:
        events: List of tuples like [("09:00", "10:30"), ("10:30", "11:00")]

    Returns:
        List of merged intervals in HH:MM string format.
    """
    valid_intervals = []

    # Parse and keep only valid intervals
    for start_str, end_str in events:
        start = parse_time(start_str)
        end = parse_time(end_str)
        if end > start:
            valid_intervals.append((start, end))

    # Sort intervals by start time
    valid_intervals.sort(key=lambda interval: interval[0])

    merged = []
    for start, end in valid_intervals:
        if not merged:
            merged.append([start, end])
            continue

        last_start, last_end = merged[-1]

        # Merge if intervals overlap or touch
        if start <= last_end:
            merged[-1][1] = max(last_end, end)
        else:
            merged.append([start, end])

    # Convert back to string tuples
    return [(format_time(start), format_time(end)) for start, end in merged]


def main():
    events = [
        ("09:00", "10:30"),
        ("10:30", "11:00"),
        ("13:15", "14:00"),
        ("13:45", "15:00"),
        ("16:00", "15:00"),  # invalid, ignored
        ("08:30", "09:15")
    ]

    result = merge_busy_intervals(events)
    print(result)


