import socket


def scan_ports(host, ports, timeout=0.5):
    """Scan TCP ports on a host and return their status."""
    results = {}

    for port in ports:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(timeout)
        try:
            # connect_ex returns 0 if the connection succeeds
            result = sock.connect_ex((host, port))
            results[port] = "open" if result == 0 else "closed"
        except socket.gaierror:
            results[port] = "closed"
        except socket.error:
            results[port] = "closed"
        finally:
            sock.close()

    return results


def main():
    host = "127.0.0.1"
    ports = [22, 80, 443, 9999]

    results = scan_ports(host, ports)

    print(f"Scan results for {host}:")
    for port, status in results.items():
        print(f"Port {port}: {status}")


