import re
from typing import Any, Dict


_PATTERN = re.compile(r"\{\{\s*(.*?)\s*\}\}")


def _parse_default_arg(arg: str) -> str:
    arg = arg.strip()
    if len(arg) >= 2 and arg[0] == arg[-1] and arg[0] in {"'", '"'}:
        return arg[1:-1]
    return arg


def _resolve_path(context: Dict[str, Any], path: str) -> Any:
    value: Any = context
    for part in path.strip().split('.'):
        part = part.strip()
        if isinstance(value, dict):
            if part not in value:
                raise KeyError(part)
            value = value[part]
        elif isinstance(value, (list, tuple)):
            try:
                value = value[int(part)]
            except (ValueError, IndexError):
                raise KeyError(part) from None
        else:
            if not hasattr(value, part):
                raise KeyError(part)
            value = getattr(value, part)
    return value


def _apply_filters(value: Any, filters: list[str]) -> Any:
    for flt in filters:
        flt = flt.strip()
        if flt == 'upper':
            value = str(value).upper()
        elif flt == 'lower':
            value = str(value).lower()
        elif flt == 'title':
            value = str(value).title()
        elif flt.startswith('default(') and flt.endswith(')'):
            # default() is handled before resolution failure; here it also covers None/empty values.
            default_value = _parse_default_arg(flt[len('default('):-1])
            if value in (None, ''):
                value = default_value
        else:
            raise ValueError(f'Unsupported filter: {flt}')
    return value


def render_template(template: str, context: Dict[str, Any]) -> str:
    def replace(match: re.Match) -> str:
        expr = match.group(1)
        parts = [p.strip() for p in expr.split('|')]
        path, filters = parts[0], parts[1:]

        # Pre-read default filter for missing keys.
        fallback = None
        has_default = False
        for flt in filters:
            if flt.startswith('default(') and flt.endswith(')'):
                fallback = _parse_default_arg(flt[len('default('):-1])
                has_default = True
                break

        try:
            value = _resolve_path(context, path)
        except KeyError:
            if has_default:
                value = fallback
            else:
                raise

        value = _apply_filters(value, filters)
        return str(value)

    return _PATTERN.sub(replace, template)


