import multiprocessing as mp


def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    limit = int(math.sqrt(n)) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return False
    return True


def count_primes(start, end):
    return sum(1 for n in range(start, end) if is_prime(n))


def threaded_prime_count(ranges):
    results = [0] * len(ranges)
    threads = []

    def worker(index, start, end):
        results[index] = count_primes(start, end)

    for i, (start, end) in enumerate(ranges):
        t = threading.Thread(target=worker, args=(i, start, end))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return sum(results)


def process_prime_count(ranges):
    with mp.Pool(processes=len(ranges)) as pool:
        results = pool.starmap(count_primes, ranges)
    return sum(results)


def make_ranges(start, end, parts):
    size = (end - start) // parts
    ranges = []
    current = start
    for i in range(parts):
        next_end = current + size
        if i == parts - 1:
            next_end = end
        ranges.append((current, next_end))
        current = next_end
    return ranges


if __name__ == '__main__':
    start_num, end_num, workers = 1, 50001, 4
    ranges = make_ranges(start_num, end_num, workers)

    t0 = time.perf_counter()
    thread_total = threaded_prime_count(ranges)
    t1 = time.perf_counter()
    print(f'Threading: {thread_total} primes found in {t1 - t0:.4f} seconds')

    t2 = time.perf_counter()
    process_total = process_prime_count(ranges)
    t3 = time.perf_counter()
    print(f'Multiprocessing: {process_total} primes found in {t3 - t2:.4f} seconds')

import requests


def fetch_users():
    """Fetch users from the API and print their name and email."""
    url = "https://jsonplaceholder.typicode.com/users"

    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()  # Raise an error for bad HTTP status codes
        users = response.json()

        for user in users:
            name = user.get("name", "Unknown")
            email = user.get("email", "No email")
            print(f"Name: {name} | Email: {email}")

    except requests.exceptions.RequestException as error:
        print(f"Failed to fetch users: {error}")


if __name__ == "__main__":
    fetch_users()

from itertools import islice, tee


def sliding_window(iterable, size):
    """Yield overlapping tuples of length `size` from `iterable`."""
    if size < 1:
        raise ValueError("size must be at least 1")

    iterators = tee(iterable, size)
    for offset, it in enumerate(iterators):
        next(islice(it, offset, offset), None)
    return zip(*iterators)



def sliding_window_averages(readings, size):
    """Return the average of each consecutive window of length `size`."""
    return [sum(window) / size for window in sliding_window(readings, size)]


if __name__ == "__main__":
    data = [10, 12, 15, 13, 18, 20]
    print(sliding_window_averages(data, 3))
    # Output: [12.333333333333334, 13.333333333333334, 15.333333333333334, 17.0]

import time
import uuid
from typing import Callable, Dict, List

Request = Dict[str, object]
Response = Dict[str, object]
Middleware = Callable[[Request, Callable[[Request], Response]], Response]
Handler = Callable[[Request], Response]


def build_pipeline(middlewares: List[Middleware], handler: Handler) -> Callable[[Request], Response]:
    """Compose middlewares around the final handler."""
    next_callable = handler

    # Wrap in reverse so the first middleware in the list runs first.
    for mw in reversed(middlewares):
        current_next = next_callable

        def make_wrapper(middleware: Middleware, downstream: Handler) -> Handler:
            def wrapper(request: Request) -> Response:
                return middleware(request, downstream)
            return wrapper

        next_callable = make_wrapper(mw, current_next)

    return next_callable


def correlation_middleware(request: Request, next_call: Callable[[Request], Response]) -> Response:
    request = dict(request)  # avoid mutating caller-owned input
    request.setdefault("correlation_id", str(uuid.uuid4()))
    response = next_call(request)
    response.setdefault("correlation_id", request["correlation_id"])
    return response


def timing_middleware(request: Request, next_call: Callable[[Request], Response]) -> Response:
    start = time.perf_counter()
    response = next_call(request)
    response["elapsed_ms"] = round((time.perf_counter() - start) * 1000, 3)
    return response


def denylist_middleware(denylist: set) -> Middleware:
    def middleware(request: Request, next_call: Callable[[Request], Response]) -> Response:
        if request.get("path") in denylist:
            return {
                "status": 403,
                "body": "Forbidden",
                "path": request.get("path"),
            }
        return next_call(request)
    return middleware


def app_handler(request: Request) -> Response:
    # Simulate application logic.
    return {
        "status": 200,
        "body": f"Handled {request.get('path', '/')} for {request.get('user', 'anonymous')}",
    }


if __name__ == "__main__":
    pipeline = build_pipeline(
        [
            correlation_middleware,
            timing_middleware,
            denylist_middleware({"/admin", "/internal"}),
        ],
        app_handler,
    )

    requests = [
        {"path": "/home", "user": "alice"},
        {"path": "/admin", "user": "bob"},
    ]

    for req in requests:
        print(pipeline(req))

import json
import os
import re
from typing import Any, Dict


_PLACEHOLDER_RE = re.compile(r"\$\{([A-Z0-9_]+)\}")


def _expand_env(value: Any) -> Any:
    """Recursively expand ${VAR} placeholders in strings."""
    if isinstance(value, dict):
        return {k: _expand_env(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_expand_env(v) for v in value]
    if isinstance(value, str):
        def repl(match: re.Match) -> str:
            var = match.group(1)
            if var not in os.environ:
                raise ValueError(f"Missing environment variable: {var}")
            return os.environ[var]
        return _PLACEHOLDER_RE.sub(repl, value)
    return value


def _deep_merge(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    """Merge override into base recursively without mutating inputs."""
    result = dict(base)
    for key, value in override.items():
        if isinstance(result.get(key), dict) and isinstance(value, dict):
            result[key] = _deep_merge(result[key], value)
        else:
            result[key] = value
    return result


def _validate_config(config: Dict[str, Any]) -> None:
    if not isinstance(config.get("host"), str) or not config["host"].strip():
        raise ValueError("'host' must be a non-empty string")
    if not isinstance(config.get("port"), int) or not (1 <= config["port"] <= 65535):
        raise ValueError("'port' must be an integer between 1 and 65535")
    if not isinstance(config.get("features"), dict):
        raise ValueError("'features' must be a dictionary")


def load_app_config(path: str, env_prefix: str = "APP_") -> Dict[str, Any]:
    """Load, expand, override, and validate application configuration."""
    try:
        with open(path, "r", encoding="utf-8") as f:
            config = json.load(f)
    except FileNotFoundError:
        raise
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in config file: {e}") from e

    config = _expand_env(config)

    override_var = f"{env_prefix}OVERRIDE_JSON"
    raw_override = os.environ.get(override_var)
    if raw_override:
        try:
            override = json.loads(raw_override)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON in {override_var}: {e}") from e
        if not isinstance(override, dict):
            raise ValueError(f"{override_var} must contain a JSON object")
        override = _expand_env(override)
        config = _deep_merge(config, override)

    if not isinstance(config, dict):
        raise ValueError("Top-level configuration must be a JSON object")
    _validate_config(config)
    return config

import time
from typing import Any, Dict, List, Optional
from urllib.parse import urljoin

import requests


class APIClientError(Exception):
    """Raised when the API client encounters a non-recoverable error."""


def fetch_all_users(base_url: str, token: str) -> List[Dict[str, Any]]:
    """Fetch all users from a paginated REST API."""
    session = requests.Session()
    session.headers.update({
        "Authorization": f"Bearer {token}",
        "Accept": "application/json",
    })

    users: List[Dict[str, Any]] = []
    next_url: Optional[str] = urljoin(base_url.rstrip("/") + "/", "users")

    while next_url:
        data = _get_with_retries(session, next_url)

        if not isinstance(data, dict) or "items" not in data or "next_page" not in data:
            raise APIClientError("Malformed response: expected 'items' and 'next_page' fields")
        if not isinstance(data["items"], list):
            raise APIClientError("Malformed response: 'items' must be a list")

        users.extend(data["items"])
        next_url = data["next_page"]

    return users


def _get_with_retries(session: requests.Session, url: str, max_retries: int = 4) -> Dict[str, Any]:
    """Perform GET with retry logic for 429 and 5xx responses."""
    backoff = 0.5

    for attempt in range(max_retries + 1):
        try:
            response = session.get(url, timeout=5)
        except requests.RequestException as exc:
            if attempt == max_retries:
                raise APIClientError(f"Request failed after retries: {exc}") from exc
            time.sleep(backoff)
            backoff *= 2
            continue

        if response.status_code == 429 or 500 <= response.status_code < 600:
            if attempt == max_retries:
                raise APIClientError(f"Transient HTTP error after retries: {response.status_code}")
            retry_after = response.headers.get("Retry-After")
            sleep_time = float(retry_after) if retry_after and retry_after.isdigit() else backoff
            time.sleep(sleep_time)
            backoff *= 2
            continue

        if not response.ok:
            raise APIClientError(f"Non-retryable HTTP error {response.status_code}: {response.text}")

        try:
            data = response.json()
        except ValueError as exc:
            raise APIClientError("Failed to decode JSON response") from exc

        if not isinstance(data, dict):
            raise APIClientError("Malformed response: expected a JSON object")
        return data

    raise APIClientError("Unexpected retry flow")

from typing import List, Optional, Dict, Any
from pydantic import BaseModel, EmailStr, Field, ValidationError, field_validator, ConfigDict
import re


class UserRegistration(BaseModel):
    model_config = ConfigDict(str_strip_whitespace=True)

    username: str = Field(..., min_length=3, max_length=20)
    email: EmailStr
    age: int = Field(..., ge=18, le=120)
    tags: Optional[List[str]] = None

    @field_validator('username')
    @classmethod
    def validate_username(cls, value: str) -> str:
        if not re.fullmatch(r'\w+', value):
            raise ValueError('username must contain only letters, numbers, and underscores')
        return value

    @field_validator('tags')
    @classmethod
    def validate_tags(cls, value: Optional[List[str]]) -> Optional[List[str]]:
        if value is None:
            return value
        cleaned = []
        for tag in value:
            tag = tag.strip()
            if not tag:
                raise ValueError('tags must not contain empty strings')
            cleaned.append(tag)
        return cleaned


def validate_registrations(records: List[Dict[str, Any]]) -> Dict[str, Any]:
    result = {'valid': [], 'errors': []}

    for index, record in enumerate(records):
        try:
            user = UserRegistration.model_validate(record)
            result['valid'].append(user.model_dump())
        except ValidationError as exc:
            result['errors'].append({
                'index': index,
                'details': exc.errors()
            })

    return result


if __name__ == '__main__':
    sample_data = [
        {
            'username': 'alice_01',
            'email': 'alice@example.com',
            'age': 28,
            'tags': ['admin', ' beta ']
        },
        {
            'username': 'x',
            'email': 'not-an-email',
            'age': 15,
            'tags': ['ok', '   ']
        }
    ]

    output = validate_registrations(sample_data)
    print(output)

class TrafficLight:
    # Simple state machine for a traffic light
    def __init__(self):
        self.states = ['Red', 'Green', 'Yellow']
        self.index = 0  # Start at Red

    def current_state(self):
        return self.states[self.index]

    def next_state(self):
        # Move to the next state in a cycle
        self.index = (self.index + 1) % len(self.states)
        return self.current_state()


def main():
    light = TrafficLight()

    print('Current state:', light.current_state())
    for i in range(5):
        print('Next state:', light.next_state())


if __name__ == '__main__':
    main()

def validate_record(record):
    """Validate a single user record against the schema."""
    errors = []

    if not isinstance(record, dict):
        return {
            'record': record,
            'valid': False,
            'errors': ['Record must be a dictionary.']
        }

    # Validate username
    username = record.get('username')
    if not isinstance(username, str) or not username.strip():
        errors.append("'username' must be a non-empty string.")
    elif len(username.strip()) < 3:
        errors.append("'username' must be at least 3 characters long.")

    # Validate email
    email = record.get('email')
    if not isinstance(email, str) or '@' not in email:
        errors.append("'email' must be a valid string containing '@'.")

    # Validate age
    age = record.get('age')
    if not isinstance(age, int) or isinstance(age, bool):
        errors.append("'age' must be an integer.")
    elif not (18 <= age <= 120):
        errors.append("'age' must be between 18 and 120.")

    # Validate is_active
    is_active = record.get('is_active')
    if not isinstance(is_active, bool):
        errors.append("'is_active' must be a boolean.")

    return {
        'record': record,
        'valid': len(errors) == 0,
        'errors': errors
    }


def validate_records(records):
    """Validate a list of user records."""
    return [validate_record(record) for record in records]


if __name__ == '__main__':
    sample_records = [
        {
            'username': 'alice',
            'email': 'alice@example.com',
            'age': 30,
            'is_active': True
        },
        {
            'username': 'bo',
            'email': 'boexample.com',
            'age': 17,
            'is_active': 'yes'
        },
        {
            'username': '   ',
            'email': 'charlie@example.com',
            'age': 25,
            'is_active': False
        },
        'not a dictionary'
    ]

    results = validate_records(sample_records)
    for result in results:
        print(result)

def is_even(number):
    """Return True if the given integer is even, otherwise False."""
    return number % 2 == 0


# Pytest unit tests

def test_is_even_positive_even():
    assert is_even(4) is True


def test_is_even_positive_odd():
    assert is_even(7) is False


def test_is_even_negative_even():
    assert is_even(-2) is True


def test_is_even_negative_odd():
    assert is_even(-5) is False


def test_is_even_zero():
    assert is_even(0) is True

import time
import uuid
from typing import Callable, Dict, Any, List

Request = Dict[str, Any]
Response = Dict[str, Any]
Middleware = Callable[[Request, Callable[[Request], Response]], Response]


class Pipeline:
    def __init__(self) -> None:
        self._middlewares: List[Middleware] = []

    def use(self, middleware: Middleware) -> None:
        """Register a middleware function."""
        self._middlewares.append(middleware)

    def _final_handler(self, request: Request) -> Response:
        """Default endpoint after all middleware has run."""
        return {
            "status": "ok",
            "data": request.copy(),
        }

    def execute(self, request: Request) -> Response:
        """Execute middleware chain in registration order."""
        def build_chain(index: int) -> Callable[[Request], Response]:
            if index == len(self._middlewares):
                return self._final_handler

            def handler(req: Request) -> Response:
                middleware = self._middlewares[index]
                next_handler = build_chain(index + 1)
                return middleware(req, next_handler)

            return handler

        chain = build_chain(0)
        return chain(request)


def add_request_id(request: Request, next_handler: Callable[[Request], Response]) -> Response:
    """Ensure every request has a unique ID."""
    request.setdefault("request_id", str(uuid.uuid4()))
    return next_handler(request)


def log_path_history(request: Request, next_handler: Callable[[Request], Response]) -> Response:
    """Track visited paths in a request-side history list."""
    request.setdefault("history", []).append(request.get("path", "/"))
    return next_handler(request)


def measure_time(request: Request, next_handler: Callable[[Request], Response]) -> Response:
    """Measure downstream execution time and attach it to the response."""
    start = time.perf_counter()
    response = next_handler(request)
    response["duration_ms"] = round((time.perf_counter() - start) * 1000, 3)
    return response


if __name__ == "__main__":
    pipeline = Pipeline()
    pipeline.use(add_request_id)
    pipeline.use(log_path_history)
    pipeline.use(measure_time)

    request = {
        "path": "/users",
        "method": "GET",
    }

    result = pipeline.execute(request)
    print(result)
}

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Dict, List, Optional


@dataclass
class VMInstance:
    instance_id: str
    region: str
    cpu_usage: Optional[float]
    memory_usage: Optional[float]
    hourly_cost: Optional[float]


class VMInstanceMonitor:
    def __init__(self, instance_records: List[Dict[str, Any]]) -> None:
        self.instances: List[VMInstance] = [self._parse_record(record) for record in instance_records]

    @staticmethod
    def _to_float(value: Any) -> Optional[float]:
        try:
            if value is None:
                return None
            number = float(value)
            return number
        except (TypeError, ValueError):
            return None

    def _parse_record(self, record: Dict[str, Any]) -> VMInstance:
        return VMInstance(
            instance_id=str(record.get("instance_id", "unknown")),
            region=str(record.get("region", "unknown")),
            cpu_usage=self._to_float(record.get("cpu_usage")),
            memory_usage=self._to_float(record.get("memory_usage")),
            hourly_cost=self._to_float(record.get("hourly_cost")),
        )

    def filter_overloaded_instances(
        self,
        cpu_threshold: float = 85.0,
        memory_threshold: float = 85.0,
    ) -> List[Dict[str, Any]]:
        overloaded = [
            {
                "instance_id": instance.instance_id,
                "region": instance.region,
                "cpu_usage": instance.cpu_usage,
                "memory_usage": instance.memory_usage,
                "hourly_cost": instance.hourly_cost,
            }
            for instance in self.instances
            if instance.cpu_usage is not None
            and instance.memory_usage is not None
            and instance.cpu_usage >= cpu_threshold
            and instance.memory_usage >= memory_threshold
        ]
        return overloaded

    def average_resource_usage_per_region(self) -> Dict[str, Dict[str, Optional[float]]]:
        regions = {instance.region for instance in self.instances}
        result: Dict[str, Dict[str, Optional[float]]] = {}

        for region in regions:
            regional_instances = [instance for instance in self.instances if instance.region == region]
            cpu_values = [instance.cpu_usage for instance in regional_instances if instance.cpu_usage is not None]
            memory_values = [instance.memory_usage for instance in regional_instances if instance.memory_usage is not None]

            avg_cpu = round(sum(cpu_values) / len(cpu_values), 2) if cpu_values else None
            avg_memory = round(sum(memory_values) / len(memory_values), 2) if memory_values else None

            result[region] = {
                "average_cpu_usage": avg_cpu,
                "average_memory_usage": avg_memory,
                "instance_count": len(regional_instances),
            }

        return dict(sorted(result.items(), key=lambda item: item[0]))

    def top_3_most_expensive_instances(self) -> List[Dict[str, Any]]:
        valid_cost_instances = [instance for instance in self.instances if instance.hourly_cost is not None]
        top_instances = sorted(valid_cost_instances, key=lambda instance: instance.hourly_cost, reverse=True)[:3]

        return [
            {
                "instance_id": instance.instance_id,
                "region": instance.region,
                "cpu_usage": instance.cpu_usage,
                "memory_usage": instance.memory_usage,
                "hourly_cost": instance.hourly_cost,
            }
            for instance in top_instances
        ]


if __name__ == "__main__":
    example_records = [
        {"instance_id": "vm-101", "region": "us-east-1", "cpu_usage": 91, "memory_usage": 88, "hourly_cost": 1.20},
