class NonEmptyString:
    # Descriptor that validates non-empty strings
    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, str):
            raise TypeError("Value must be a string")
        if not value.strip():
            raise ValueError("Value cannot be empty")
        setattr(instance, self.private_name, value)


class Person:
    first_name = NonEmptyString()
    last_name = NonEmptyString()

    def __init__(self, first_name, last_name, age):
        self.first_name = first_name
        self.last_name = last_name
        self.age = age

    @property
    def age(self):
        return self._age

    @age.setter
    def age(self, value):
        if not isinstance(value, int):
            raise TypeError("Age must be an integer")
        if value < 0:
            raise ValueError("Age cannot be negative")
        self._age = value

    def full_name(self):
        return f"{self.first_name} {self.last_name}"


# Example usage
person = Person("Alice", "Johnson", 30)
print(person.full_name())
print(person.age)

try:
    person.first_name = ""
except Exception as e:
    print(e)

try:
    person.age = -5
except Exception as e:
    print(e)

import threading
import time
from collections import OrderedDict, namedtuple
from functools import wraps

CacheInfo = namedtuple('CacheInfo', 'hits misses maxsize currsize')


def memoize(ttl=None, maxsize=128):
    def decorator(func):
        cache = OrderedDict()  # key -> (value, expires_at)
        in_flight = {}         # key -> threading.Event()
        lock = threading.RLock()
        stats = {'hits': 0, 'misses': 0}

        def make_key(args, kwargs):
            if kwargs:
                return args + (object(),) + tuple(sorted(kwargs.items()))
            return args

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            while True:
                with lock:
                    now = time.monotonic()
                    if key in cache:
                        value, expires_at = cache[key]
                        if expires_at is None or now < expires_at:
                            cache.move_to_end(key)
                            stats['hits'] += 1
                            return value
                        del cache[key]  # expired entry

                    if key in in_flight:
                        event = in_flight[key]
                    else:
                        event = threading.Event()
                        in_flight[key] = event
                        break

                event.wait()

            try:
                result = func(*args, **kwargs)
            finally:
                with lock:
                    if key in in_flight:
                        in_flight[key].set()
                        del in_flight[key]

            with lock:
                expires_at = None if ttl is None else time.monotonic() + ttl
                cache[key] = (result, expires_at)
                cache.move_to_end(key)
                stats['misses'] += 1
                while maxsize is not None and len(cache) > maxsize:
                    cache.popitem(last=False)
            return result

        def cache_info():
            with lock:
                return CacheInfo(stats['hits'], stats['misses'], maxsize, len(cache))

        def cache_clear():
            with lock:
                cache.clear()
                in_flight.clear()
                stats['hits'] = 0
                stats['misses'] = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator


@memoize(ttl=10, maxsize=256)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)


