    errors = []

    if not isinstance(record, dict):
        return False, ["Record must be a dictionary."]

    # Required fields
    required_fields = ["name", "age", "email"]
    for field in required_fields:
        if field not in record:
            errors.append(f"Missing required field: {field}")

    # Validate name
    name = record.get("name")
    if "name" in record:
        if not isinstance(name, str) or not name.strip():
            errors.append("Field 'name' must be a non-empty string.")

    # Validate age
    age = record.get("age")
    if "age" in record:
        if not isinstance(age, int) or isinstance(age, bool):
            errors.append("Field 'age' must be an integer.")
        elif not (18 <= age <= 120):
            errors.append("Field 'age' must be between 18 and 120.")

    # Validate email
    email = record.get("email")
    if "email" in record:
        if not isinstance(email, str):
            errors.append("Field 'email' must be a string.")
        else:
            parts = email.split("@")
            if len(parts) != 2 or not parts[0] or "." not in parts[1]:
                errors.append("Field 'email' must be a valid email address.")

    # Validate optional tags
    if "tags" in record:
        tags = record["tags"]
        if not isinstance(tags, list):
            errors.append("Field 'tags' must be a list of non-empty strings.")
        else:
            for i, tag in enumerate(tags):
                if not isinstance(tag, str) or not tag.strip():
                    errors.append(f"Field 'tags[{i}]' must be a non-empty string.")

