import hashlib


class BloomFilter:
    def __init__(self, size=128, hash_count=3):
        if size <= 0 or hash_count <= 0:
            raise ValueError("size and hash_count must be positive")
        self.size = size
        self.hash_count = hash_count
        self.bits = [0] * size

    def _hashes(self, item):
        """Generate multiple deterministic hash positions for a string item."""
        item_bytes = item.encode("utf-8")
        for i in range(self.hash_count):
            seed = i.to_bytes(2, byteorder="big")
            digest = hashlib.sha256(seed + item_bytes).digest()
            yield int.from_bytes(digest, byteorder="big") % self.size

    def add(self, item):
        """Mark all hashed positions for the given item."""
        for position in self._hashes(item):
            self.bits[position] = 1

    def contains(self, item):
        """Return False if definitely absent, True if possibly present."""
        return all(self.bits[position] for position in self._hashes(item))


