class MinMaxStack:
    """Stack that can return current min and max in O(1)."""

    def __init__(self):
        self._data = []  # Each item: (value, current_min, current_max)

    def push(self, value):
        if not self._data:
            self._data.append((value, value, value))
        else:
            _, current_min, current_max = self._data[-1]
            self._data.append((value, min(value, current_min), max(value, current_max)))

    def pop(self):
        if not self._data:
            raise IndexError("pop from empty stack")
        return self._data.pop()[0]

    def top(self):
        if not self._data:
            raise IndexError("top from empty stack")
        return self._data[-1][0]

    def get_min(self):
        if not self._data:
            raise IndexError("min from empty stack")
        return self._data[-1][1]

    def get_max(self):
        if not self._data:
            raise IndexError("max from empty stack")
        return self._data[-1][2]

    def __len__(self):
        return len(self._data)


class MinMaxQueue:
    """Queue implemented with two min-max stacks."""

    def __init__(self):
        self._in = MinMaxStack()
        self._out = MinMaxStack()

    def enqueue(self, value):
        self._in.push(value)

    def _shift(self):
        if len(self._out) == 0:
            while len(self._in) > 0:
                self._out.push(self._in.pop())

    def dequeue(self):
        self._shift()
        if len(self._out) == 0:
            raise IndexError("dequeue from empty queue")
        return self._out.pop()

    def front(self):
        self._shift()
        if len(self._out) == 0:
            raise IndexError("front from empty queue")
        return self._out.top()

    def get_min(self):
        if len(self._in) == 0 and len(self._out) == 0:
            raise IndexError("min from empty queue")
        if len(self._in) == 0:
            return self._out.get_min()
        if len(self._out) == 0:
            return self._in.get_min()
        return min(self._in.get_min(), self._out.get_min())

    def get_max(self):
        if len(self._in) == 0 and len(self._out) == 0:
            raise IndexError("max from empty queue")
        if len(self._in) == 0:
            return self._out.get_max()
        if len(self._out) == 0:
            return self._in.get_max()
        return max(self._in.get_max(), self._out.get_max())

    def __len__(self):
        return len(self._in) + len(self._out)

from collections import Counter


def hamming_distance(a: bytes, b: bytes) -> int:
    """Return the number of differing bits between two byte strings."""
    if len(a) != len(b):
        raise ValueError('Inputs must have equal length')
    return sum((x ^ y).bit_count() for x, y in zip(a, b))


def score_english(text: bytes) -> float:
    """Heuristic score: higher is more likely to be English text."""
    freq = {
        'e': 12.7, 't': 9.1, 'a': 8.2, 'o': 7.5, 'i': 7.0, 'n': 6.7,
        ' ': 13.0, 's': 6.3, 'h': 6.1, 'r': 6.0, 'd': 4.3, 'l': 4.0,
        'u': 2.8
    }
    score = 0.0
    for b in text:
        c = chr(b).lower()
        if c in freq:
            score += freq[c]
        elif 32 <= b <= 126 or b in (9, 10, 13):
            score += 0.2
        else:
            score -= 8.0
    return score


def crack_single_byte_xor(data: bytes) -> tuple[int, bytes, float]:
    """Find the best single-byte key for XOR-encrypted data."""
    best_key, best_plain, best_score = 0, b'', float('-inf')
    for key in range(256):
        plain = bytes(b ^ key for b in data)
        score = score_english(plain)
        if score > best_score:
            best_key, best_plain, best_score = key, plain, score
    return best_key, best_plain, best_score


def estimate_keysize(data: bytes, max_key_len: int) -> int:
    """Estimate repeating-key XOR key length using normalized Hamming distance."""
    candidates = []
    for keysize in range(2, max_key_len + 1):
        blocks = [data[i:i + keysize] for i in range(0, keysize * 4, keysize)]
        if len(blocks) < 4 or any(len(block) != keysize for block in blocks):
            continue
        pairs = [(blocks[0], blocks[1]), (blocks[1], blocks[2]), (blocks[2], blocks[3])]
        avg = sum(hamming_distance(x, y) / keysize for x, y in pairs) / len(pairs)
        candidates.append((avg, keysize))
    if not candidates:
        raise ValueError('Ciphertext too short to estimate key size')
    return min(candidates)[1]


def break_repeating_key_xor(cipher_hex: str, max_key_len: int = 40) -> tuple[str, str]:
    """Recover key and plaintext from a hex-encoded repeating-key XOR ciphertext."""
    data = bytes.fromhex(cipher_hex)
    keysize = estimate_keysize(data, max_key_len)

    # Transpose blocks: each block contains bytes XORed with the same key byte.
    transposed = [data[i::keysize] for i in range(keysize)]

    key_bytes = bytearray()
    for block in transposed:
        key_byte, _, _ = crack_single_byte_xor(block)
        key_bytes.append(key_byte)

    plaintext = bytes(data[i] ^ key_bytes[i % keysize] for i in range(len(data)))
    return key_bytes.decode('ascii', errors='replace'), plaintext.decode('utf-8', errors='replace')


if __name__ == '__main__':
    # Example ciphertext produced from English plaintext with a repeating ASCII key.
    ciphertext_hex = (
        '1d2b2c3a632430632422372c632d2c2b242b22632a2e3d632d2a373d6b63263d'
        '6322203b2c223d632f2a2b263d21632620372522372c632237632420373c2b36'
        '2c22632c2f6322203b2c223d632d26282d2c3d6b'
    )
    key, plaintext = break_repeating_key_xor(ciphertext_hex, max_key_len=12)
    print('Recovered key:', key)
    print('Plaintext:', plaintext)

