from datetime import datetime, timedelta


def summarize_events(events):
    """
    Process a list of events and return:
      - processed_events: each event with computed duration in minutes
      - daily_totals: total scheduled minutes grouped by start date
    """
    processed_events = []
    daily_totals = {}

    for event in events:
        title = event['title']
        start = datetime.strptime(event['start'], '%Y-%m-%d %H:%M')
        end = datetime.strptime(event['end'], '%Y-%m-%d %H:%M')

        # If end is earlier than start, assume the event continues past midnight
        if end < start:
            end += timedelta(days=1)

        duration_minutes = int((end - start).total_seconds() // 60)
        start_date = start.strftime('%Y-%m-%d')

        processed_events.append({
            'title': title,
            'start': event['start'],
            'end': end.strftime('%Y-%m-%d %H:%M'),
            'duration_minutes': duration_minutes
        })

        daily_totals[start_date] = daily_totals.get(start_date, 0) + duration_minutes

    return {
        'processed_events': processed_events,
        'daily_totals': daily_totals
    }


