@dataclass(frozen=True)
class DetectionConfig:
    risk_increase_threshold: float = 0.25
    rolling_window_minutes: int = 60
    severity_threshold: float = 5.0
    max_workers: int = 4
    batch_size: int = 4
    allowed_delay_minutes: int = 180


@dataclass
class PatientState:
    lock: Lock = field(default_factory=Lock)
    records: Deque[Dict[str, Any]] = field(default_factory=deque)
    last_timestamp: Optional[datetime] = None


def detect_deterioration_events(
    records_stream: Iterable[Dict[str, Any]],
    config: DetectionConfig = DetectionConfig(),
) -> Dict[str, Any]:
    """
    Process a stream of patient records in concurrent batches while preserving per-patient ordering.
    Detect clinically significant deterioration events based on:
      1) Risk score increase above threshold within a rolling time window.
      2) Weighted severity score from vital-sign abnormalities and lab deviations.

    Returns a structured summary with flagged events and aggregate statistics.
    """

    patient_states: Dict[str, PatientState] = {}
    patient_states_guard = Lock()

    stats = {
        "total_processed_records": 0,
        "invalid_records": 0,
        "batches_processed": 0,
        "average_processing_latency_per_batch_ms": 0.0,
    }
    stats_lock = Lock()

    flagged_events: List[Dict[str, Any]] = []
    flagged_events_lock = Lock()

    batch_latencies_ms: List[float] = []

    def parse_timestamp(value: Any) -> Optional[datetime]:
        if isinstance(value, datetime):
            return value
        if isinstance(value, str):
            try:
                return datetime.fromisoformat(value)
            except ValueError:
                return None
        return None

    def validate_record(record: Any) -> Tuple[bool, Optional[Dict[str, Any]], Optional[str]]:
        if not isinstance(record, dict):
            return False, None, "record_not_dict"

        required = {"patient_id", "timestamp", "vital_signs", "lab_values", "risk_score"}
        missing = required - set(record.keys())
        if missing:
            return False, None, f"missing_fields:{sorted(missing)}"

        patient_id = record.get("patient_id")
        timestamp = parse_timestamp(record.get("timestamp"))
        vital_signs = record.get("vital_signs")
        lab_values = record.get("lab_values")
        risk_score = record.get("risk_score")

        if not isinstance(patient_id, str) or not patient_id.strip():
            return False, None, "invalid_patient_id"
        if timestamp is None:
            return False, None, "invalid_timestamp"
        if not isinstance(vital_signs, dict):
            return False, None, "invalid_vital_signs"
        if not isinstance(lab_values, dict):
            return False, None, "invalid_lab_values"
        if not isinstance(risk_score, (int, float)):
            return False, None, "invalid_risk_score"

        normalized = {
            "patient_id": patient_id.strip(),
            "timestamp": timestamp,
            "vital_signs": vital_signs,
            "lab_values": lab_values,
            "risk_score": float(risk_score),
        }
        return True, normalized, None

    def get_patient_state(patient_id: str) -> PatientState:
        with patient_states_guard:
            if patient_id not in patient_states:
                patient_states[patient_id] = PatientState()
            return patient_states[patient_id]

    def compute_severity(vital_signs: Dict[str, Any], lab_values: Dict[str, Any]) -> Tuple[float, List[str]]:
        score = 0.0
        reasons: List[str] = []

        # Weighted vital sign abnormalities
        hr = vital_signs.get("heart_rate")
        if isinstance(hr, (int, float)):
            if hr >= 130:
                score += 2.0
                reasons.append("heart_rate>=130")
            elif hr >= 110:
                score += 1.0
                reasons.append("heart_rate>=110")
            elif hr <= 40:
                score += 2.0
                reasons.append("heart_rate<=40")
            elif hr <= 50:
                score += 1.0
                reasons.append("heart_rate<=50")

        sbp = vital_signs.get("systolic_bp")
        if isinstance(sbp, (int, float)):
            if sbp < 80:
                score += 2.0
                reasons.append("systolic_bp<80")
            elif sbp < 90:
                score += 1.5
                reasons.append("systolic_bp<90")

        rr = vital_signs.get("respiratory_rate")
        if isinstance(rr, (int, float)):
            if rr >= 30:
                score += 1.5
                reasons.append("respiratory_rate>=30")
            elif rr >= 24:
                score += 1.0
                reasons.append("respiratory_rate>=24")

        spo2 = vital_signs.get("spo2")
        if isinstance(spo2, (int, float)):
            if spo2 < 88:
                score += 2.0
                reasons.append("spo2<88")
            elif spo2 < 92:
                score += 1.0
                reasons.append("spo2<92")

        temp = vital_signs.get("temperature_c")
        if isinstance(temp, (int, float)):
            if temp >= 39.5 or temp <= 35.0:
                score += 1.5
                reasons.append("temperature_extreme")
            elif temp >= 38.5:
                score += 1.0
                reasons.append("temperature_high")

        # Weighted lab deviations
        lactate = lab_values.get("lactate")
        if isinstance(lactate, (int, float)):
            if lactate >= 4.0:
                score += 2.0
                reasons.append("lactate>=4.0")
            elif lactate >= 2.0:
                score += 1.0
                reasons.append("lactate>=2.0")

        wbc = lab_values.get("wbc")
        if isinstance(wbc, (int, float)):
            if wbc >= 20 or wbc <= 2:
                score += 1.5
                reasons.append("wbc_extreme")
            elif wbc >= 15 or wbc <= 4:
                score += 1.0
                reasons.append("wbc_abnormal")

        creatinine = lab_values.get("creatinine")
        if isinstance(creatinine, (int, float)):
            if creatinine >= 2.5:
                score += 1.5
                reasons.append("creatinine>=2.5")
            elif creatinine >= 1.8:
                score += 1.0
                reasons.append("creatinine>=1.8")

        platelets = lab_values.get("platelets")
        if isinstance(platelets, (int, float)):
            if platelets < 50:
                score += 1.5
                reasons.append("platelets<50")
            elif platelets < 100:
                score += 1.0
                reasons.append("platelets<100")

        return score, reasons

    def process_record(record: Dict[str, Any]) -> None:
        valid, normalized, _ = validate_record(record)

        with stats_lock:
            stats["total_processed_records"] += 1

        if not valid or normalized is None:
            with stats_lock:
                stats["invalid_records"] += 1
            return

        patient_id = normalized["patient_id"]
        timestamp = normalized["timestamp"]
        state = get_patient_state(patient_id)

        with state.lock:
            # Reject excessively delayed records to preserve near-real-time semantics.
            if state.last_timestamp is not None:
                max_delay = timedelta(minutes=config.allowed_delay_minutes)
                if timestamp < state.last_timestamp - max_delay:
                    with stats_lock:
                        stats["invalid_records"] += 1
                    return

            # Insert in timestamp order to preserve correct per-patient ordering.
            inserted = False
            if not state.records or timestamp >= state.records[-1]["timestamp"]:
                state.records.append(normalized)
                inserted = True
            else:
                temp = list(state.records)
                temp.append(normalized)
                temp.sort(key=lambda r: r["timestamp"])
                state.records = deque(temp)
                inserted = True

            if inserted:
                state.last_timestamp = max(
                    timestamp,
                    state.last_timestamp if state.last_timestamp is not None else timestamp,
                )

            # Remove records older than rolling window from the current timestamp.
            rolling_window = timedelta(minutes=config.rolling_window_minutes)
            while state.records and state.records[0]["timestamp"] < timestamp - rolling_window:
                state.records.popleft()

            # Risk increase detection within rolling window.
            min_risk_in_window = min((r["risk_score"] for r in state.records), default=normalized["risk_score"])
            risk_delta = normalized["risk_score"] - min_risk_in_window

            triggers: List[str] = []

            if risk_delta > config.risk_increase_threshold:
                triggers.append(
                    f"risk_increase>{config.risk_increase_threshold:.3f} (delta={risk_delta:.3f})"
                )

            severity_score, severity_reasons = compute_severity(
                normalized["vital_signs"], normalized["lab_values"]
            )
            if severity_score >= config.severity_threshold:
                triggers.append(
                    f"severity_score>={config.severity_threshold:.2f} "
                    f"(score={severity_score:.2f}; reasons={severity_reasons})"
                )

            if triggers:
                event = {
                    "patient_id": patient_id,
                    "event_timestamp": timestamp.isoformat(),
                    "triggering_conditions": triggers,
                    "risk_score": normalized["risk_score"],
                    "severity_score": round(severity_score, 3),
                }
                with flagged_events_lock:
                    flagged_events.append(event)

    def process_batch(batch: List[Dict[str, Any]]) -> float:
        start = perf_counter()
        for rec in batch:
            process_record(rec)
        end = perf_counter()
        return (end - start) * 1000.0

    def chunked(iterable: Iterable[Dict[str, Any]], size: int) -> List[List[Dict[str, Any]]]:
        batches: List[List[Dict[str, Any]]] = []
        current: List[Dict[str, Any]] = []
        for item in iterable:
            current.append(item)
            if len(current) >= size:
                batches.append(current)
                current = []
        if current:
            batches.append(current)
        return batches

    batches = chunked(records_stream, config.batch_size)

    with ThreadPoolExecutor(max_workers=config.max_workers) as executor:
        futures = [executor.submit(process_batch, batch) for batch in batches]
        for future in as_completed(futures):
            latency_ms = future.result()
            batch_latencies_ms.append(latency_ms)
            with stats_lock:
                stats["batches_processed"] += 1

    if batch_latencies_ms:
        stats["average_processing_latency_per_batch_ms"] = round(
            sum(batch_latencies_ms) / len(batch_latencies_ms), 3
        )

    flagged_events.sort(key=lambda e: (e["patient_id"], e["event_timestamp"]))

    summary = {
        "flagged_patient_ids": sorted({event["patient_id"] for event in flagged_events}),
        "events": flagged_events,
        "aggregate_statistics": stats,
    }
    return summary


