from abc import ABC, abstractmethod


class Notification(ABC):
    def __init__(self, recipient: str, subject: str, body: str):
        self.recipient = recipient
        self.subject = subject
        self.body = body

    @abstractmethod
    def send(self) -> str:
        pass


class EmailNotification(Notification):
    def send(self) -> str:
        return (
            f"Sending EMAIL to {self.recipient} | "
            f"Subject: {self.subject} | Body: {self.body}"
        )


class SMSNotification(Notification):
    def send(self) -> str:
        return f"Sending SMS to {self.recipient} | Message: {self.body}"


class NotificationFactory:
    @staticmethod
    def create(notification_type: str, recipient: str, subject: str, body: str) -> Notification:
        notification_type = notification_type.lower()
        if notification_type == "email":
            return EmailNotification(recipient, subject, body)
        if notification_type == "sms":
            return SMSNotification(recipient, subject, body)
        raise ValueError(f"Unsupported notification type: {notification_type}")


class NotificationBuilder:
    def __init__(self):
        self.reset()

    def reset(self):
        self._type = None
        self._recipient = None
        self._subject = ""
        self._body = ""

    def set_type(self, notification_type: str):
        self._type = notification_type
        return self

    def set_recipient(self, recipient: str):
        self._recipient = recipient
        return self

    def set_subject(self, subject: str):
        self._subject = subject
        return self

    def set_body(self, body: str):
        self._body = body
        return self

    def build(self) -> Notification:
        if not self._type or not self._recipient or not self._body:
            raise ValueError("Type, recipient, and body are required")

        notification = NotificationFactory.create(
            self._type, self._recipient, self._subject, self._body
        )
        self.reset()  # Ready builder for reuse
        return notification


if __name__ == "__main__":
    builder = NotificationBuilder()

    email = (
        builder
        .set_type("email")
        .set_recipient("alice@example.com")
        .set_subject("Welcome")
        .set_body("Thanks for signing up!")
        .build()
    )

    sms = (
        builder
        .set_type("sms")
        .set_recipient("+1234567890")
        .set_body("Your verification code is 4821")
        .build()
    )

    print(email.send())
    print(sms.send())

from dataclasses import dataclass


class Command:
    def execute(self):
        raise NotImplementedError

    def undo(self):
        raise NotImplementedError


class TextBuffer:
    def __init__(self, text=""):
        self.text = text

    def insert(self, index, value):
        self.text = self.text[:index] + value + self.text[index:]

    def delete(self, index, length):
        removed = self.text[index:index + length]
        self.text = self.text[:index] + self.text[index + length:]
        return removed

    def replace(self, index, length, value):
        old = self.text[index:index + length]
        self.text = self.text[:index] + value + self.text[index + length:]
        return old


@dataclass
class InsertCommand(Command):
    buffer: TextBuffer
    index: int
    value: str

    def execute(self):
        self.buffer.insert(self.index, self.value)

    def undo(self):
        self.buffer.delete(self.index, len(self.value))


@dataclass
class DeleteCommand(Command):
    buffer: TextBuffer
    index: int
    length: int
    removed: str = ""

    def execute(self):
        self.removed = self.buffer.delete(self.index, self.length)

    def undo(self):
        self.buffer.insert(self.index, self.removed)


@dataclass
class ReplaceCommand(Command):
    buffer: TextBuffer
    index: int
    length: int
    value: str
    old_value: str = ""

    def execute(self):
        self.old_value = self.buffer.replace(self.index, self.length, self.value)

    def undo(self):
        self.buffer.replace(self.index, len(self.value), self.old_value)


class EditorInvoker:
    def __init__(self, buffer=None):
        self.buffer = buffer or TextBuffer()
        self.undo_stack = []
        self.redo_stack = []

    def run(self, command):
        command.execute()
        self.undo_stack.append(command)
        self.redo_stack.clear()  # New action invalidates redo history.

    def undo(self):
        if not self.undo_stack:
            return False
        command = self.undo_stack.pop()
        command.undo()
        self.redo_stack.append(command)
        return True

    def redo(self):
        if not self.redo_stack:
            return False
        command = self.redo_stack.pop()
        command.execute()
        self.undo_stack.append(command)
        return True

    @property
    def text(self):
        return self.buffer.text


if __name__ == "__main__":
    editor = EditorInvoker(TextBuffer("Hello"))

    steps = [
        InsertCommand(editor.buffer, 5, " World"),
        ReplaceCommand(editor.buffer, 6, 5, "there"),
        DeleteCommand(editor.buffer, 0, 6),
    ]

    for cmd in steps:
        editor.run(cmd)
        print(editor.text)

    editor.undo()
    print(editor.text)
    editor.undo()
    print(editor.text)
    editor.redo()
    print(editor.text)

    editor.run(InsertCommand(editor.buffer, len(editor.text), "!"))
    print(editor.text)

    # Redo now fails because history was cleared by the new command.
    editor.redo()
    print(editor.text)

from collections import defaultdict
from typing import Callable, Dict, List


class EventBus:
    """Simple pub/sub event bus for named events."""

    def __init__(self):
        self._subscribers: Dict[str, List[Callable[..., None]]] = defaultdict(list)

    def subscribe(self, event_name: str, callback: Callable[..., None]) -> None:
        """Register a callback for an event."""
        self._subscribers[event_name].append(callback)

    def unsubscribe(self, event_name: str, callback: Callable[..., None]) -> None:
        """Remove a callback if it is subscribed."""
        if event_name in self._subscribers and callback in self._subscribers[event_name]:
            self._subscribers[event_name].remove(callback)

    def publish(self, event_name: str, **data) -> None:
        """Notify all subscribers of an event."""
        for callback in list(self._subscribers[event_name]):
            callback(**data)


class TemperatureSensor:
    """Publishes an event whenever the temperature changes."""

    def __init__(self, bus: EventBus):
        self._bus = bus
        self._temperature = None

    def set_temperature(self, value: float) -> None:
        old_value = self._temperature
        self._temperature = value
        self._bus.publish(
            "temperature_changed",
            old=old_value,
            new=value,
        )


def log_temperature_change(old, new):
    print(f"[LOG] Temperature changed from {old} to {new}")


def high_temperature_alert(old, new):
    if new > 30:
        print(f"[ALERT] High temperature detected: {new}")


if __name__ == "__main__":
    bus = EventBus()
    sensor = TemperatureSensor(bus)

    # Subscribe observers to the event
    bus.subscribe("temperature_changed", log_temperature_change)
    bus.subscribe("temperature_changed", high_temperature_alert)

    # Publish events through sensor updates
    sensor.set_temperature(22)
    sensor.set_temperature(31)

    # Unsubscribe the logger and publish again
    bus.unsubscribe("temperature_changed", log_temperature_change)
    sensor.set_temperature(35)

class TrieNode:
    def __init__(self):
        self.children = {}
        self.value = None          # Exact word value
        self.subtree_sum = 0       # Sum of all values in this subtree


class PrefixMap:
    def __init__(self):
        self.root = TrieNode()

    def get(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node.value

    def insert(self, word, value):
        old_value = self.get(word)
        delta = value - (old_value if old_value is not None else 0)

        node = self.root
        node.subtree_sum += delta
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            node.subtree_sum += delta
        node.value = value

    def delete(self, word):
        node = self.root
        path = [self.root]
        chars = []

        for ch in word:
            if ch not in node.children:
                return False
            chars.append(ch)
            node = node.children[ch]
            path.append(node)

        if node.value is None:
            return False

        removed_value = node.value
        node.value = None

        # Update subtree sums along the path.
        for n in path:
            n.subtree_sum -= removed_value

        # Prune unused nodes from the bottom up.
        for i in range(len(word) - 1, -1, -1):
            parent = path[i]
            ch = chars[i]
            child = parent.children[ch]
            if child.value is None and not child.children:
                del parent.children[ch]
            else:
                break

        return True

    def sum_prefix(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return 0
            node = node.children[ch]
        return node.subtree_sum


# Example usage
if __name__ == '__main__':
    pm = PrefixMap()
    pm.insert('apple', 3)
    pm.insert('app', 2)
    pm.insert('apex', 4)
    print(pm.sum_prefix('ap'))   # 9
    print(pm.sum_prefix('app'))  # 5
    pm.insert('app', 5)
    print(pm.sum_prefix('app'))  # 8
    print(pm.get('apple'))       # 3
    pm.delete('apple')
    print(pm.sum_prefix('app'))  # 5
    print(pm.get('apple'))       # None

import pytest


def apply_discount(price, percent, is_member=False):
    """Return the final price after applying discounts."""
    if price < 0:
        raise ValueError("price must be non-negative")
    if percent < 0 or percent > 100:
        raise ValueError("percent must be between 0 and 100")

    total_discount = percent + (5 if is_member else 0)
    # Prevent discounts from reducing price below zero.
    total_discount = min(total_discount, 100)
    return round(price * (1 - total_discount / 100), 2)


