# Pytest unit tests
# ----------------------

def test_apply_discount_regular_customer():
    assert apply_discount(200, 10) == 180.0


def test_apply_discount_member_gets_extra_discount():
    assert apply_discount(200, 10, True) == 170.0


def test_zero_percent_discount():
    assert apply_discount(50, 0) == 50.0


def test_full_discount_boundary():
    assert apply_discount(80, 100) == 0.0


def test_member_discount_capped_at_100_percent():
    assert apply_discount(80, 98, True) == 0.0


