class PaymentError(Exception):
    """Base class for all payment-related errors."""

    def __init__(self, message, *, account_id=None, amount=None):
        super().__init__(message)
        self.account_id = account_id
        self.amount = amount


class ValidationError(PaymentError):
    """Raised when input data is invalid."""


class InsufficientFundsError(PaymentError):
    """Raised when an account lacks enough balance."""


class FraudDetectedError(PaymentError):
    """Raised when a payment is blocked due to fraud rules."""


def process_payment(account, amount):
    """Validate and apply a payment, returning the updated balance."""
    account_id = account.get("id")

    if not isinstance(amount, (int, float)):
        raise ValidationError(
            "Amount must be numeric",
            account_id=account_id,
            amount=amount,
        )
    if amount <= 0:
        raise ValidationError(
            "Amount must be greater than zero",
            account_id=account_id,
            amount=amount,
        )
    if account.get("flagged", False):
        raise FraudDetectedError(
            "Payment blocked: account is flagged for review",
            account_id=account_id,
            amount=amount,
        )
    if account["balance"] < amount:
        raise InsufficientFundsError(
            f"Insufficient funds: available={account['balance']}, required={amount}",
            account_id=account_id,
            amount=amount,
        )

    account["balance"] -= amount
    return account["balance"]


def handle_payments(accounts, requests):
    """Process payment requests and collect per-request outcomes."""
    results = []

    for account_id, amount in requests:
        account = accounts.get(account_id)
        if account is None:
            results.append({
                "account_id": account_id,
                "status": "error",
                "error_type": "ValidationError",
                "message": f"Unknown account: {account_id}",
            })
            continue

        try:
            new_balance = process_payment(account, amount)
            results.append({
                "account_id": account_id,
                "status": "success",
                "new_balance": new_balance,
            })
        except PaymentError as exc:
            results.append({
                "account_id": account_id,
                "status": "error",
                "error_type": type(exc).__name__,
                "message": str(exc),
            })

    return results


if __name__ == "__main__":
    accounts = {
        "A100": {"id": "A100", "balance": 150.0, "flagged": False},
        "B200": {"id": "B200", "balance": 20.0, "flagged": False},
        "C300": {"id": "C300", "balance": 500.0, "flagged": True},
    }

    requests = [
        ("A100", 50),
        ("B200", 100),
        ("C300", 10),
        ("A100", -5),
        ("X999", 30),
    ]

    for result in handle_payments(accounts, requests):
        print(result)

import math
import hashlib


class BloomFilter:
    def __init__(self, size: int, num_hashes: int):
        if size <= 0 or num_hashes <= 0:
            raise ValueError('size and num_hashes must be positive')
        self.size = size
        self.num_hashes = num_hashes
        self.bits = bytearray((size + 7) // 8)
        self.count = 0  # number of inserted items

    def _hashes(self, item: str):
        # Double hashing: derive k indices from two strong digests.
        data = item.encode('utf-8')
        h1 = int.from_bytes(hashlib.sha256(data).digest(), 'big')
        h2 = int.from_bytes(hashlib.blake2b(data, digest_size=16).digest(), 'big') or 1
        for i in range(self.num_hashes):
            yield (h1 + i * h2) % self.size

    def _set_bit(self, index: int):
        self.bits[index // 8] |= 1 << (index % 8)

    def _get_bit(self, index: int) -> bool:
        return bool(self.bits[index // 8] & (1 << (index % 8)))

    def add(self, item: str):
        for index in self._hashes(item):
            self._set_bit(index)
        self.count += 1

    def __contains__(self, item: str) -> bool:
        return all(self._get_bit(index) for index in self._hashes(item))

    def false_positive_rate(self) -> float:
        # Standard Bloom filter estimate: (1 - e^(-kn/m))^k
        k, n, m = self.num_hashes, self.count, self.size
        return (1 - math.exp(-k * n / m)) ** k

    def merge(self, other: 'BloomFilter'):
        if self.size != other.size or self.num_hashes != other.num_hashes:
            raise ValueError('Bloom filters must have the same size and num_hashes')
        merged = BloomFilter(self.size, self.num_hashes)
        merged.bits = bytearray(a | b for a, b in zip(self.bits, other.bits))
        # Approximate merged count as sum; duplicates cannot be recovered.
        merged.count = self.count + other.count
        return merged


if __name__ == '__main__':
    bf1 = BloomFilter(size=1024, num_hashes=4)
    for word in ['apple', 'banana', 'cherry']:
        bf1.add(word)

    print('apple' in bf1)   # Expected: True
    print('grape' in bf1)   # Possibly False, rarely True
    print(f'Estimated FPR: {bf1.false_positive_rate():.6f}')

    bf2 = BloomFilter(size=1024, num_hashes=4)
    for word in ['date', 'elderberry']:
        bf2.add(word)

    merged = bf1.merge(bf2)
    print('date' in merged)         # Expected: True
    print('banana' in merged)       # Expected: True
    print('fig' in merged)          # Possibly False, rarely True
    print(f'Merged estimated FPR: {merged.false_positive_rate():.6f}')

class PluginRegistry:
    """Singleton registry for plugin classes."""
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._plugins = {}
        return cls._instance

    def register(self, name, plugin_cls):
        if name in self._plugins:
            raise ValueError(f"Plugin '{name}' is already registered")
        self._plugins[name] = plugin_cls

    def get(self, name):
        if name not in self._plugins:
            raise KeyError(f"Plugin '{name}' is not registered")
        return self._plugins[name]

    def create(self, name, *args, **kwargs):
        plugin_cls = self.get(name)
        return plugin_cls(*args, **kwargs)


class BasePlugin:
    """Base class that auto-registers subclasses."""
    plugin_name = None

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        if cls.plugin_name:
            PluginRegistry().register(cls.plugin_name, cls)

    def process(self, text):
        raise NotImplementedError


class UppercasePlugin(BasePlugin):
    plugin_name = "uppercase"

    def process(self, text):
        return text.upper()


class ReversePlugin(BasePlugin):
    plugin_name = "reverse"

    def process(self, text):
        return text[::-1]


if __name__ == "__main__":
    registry = PluginRegistry()

    text = "hello world"
    upper = registry.create("uppercase")
    reverse = registry.create("reverse")

    print(upper.process(text))
    print(reverse.process(text))

import hmac
import hashlib
import json
from flask import Flask, request, jsonify

app = Flask(__name__)

# Shared secret used to verify incoming webhook signatures
WEBHOOK_SECRET = b"supersecretkey"


def verify_signature(raw_body: bytes, signature: str) -> bool:
    """Validate the HMAC SHA-256 signature for the request body."""
    expected = hmac.new(WEBHOOK_SECRET, raw_body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)


@app.post('/webhook')
def webhook_handler():
    raw_body = request.get_data()
    signature = request.headers.get('X-Signature', '')

    if not signature or not verify_signature(raw_body, signature):
        return jsonify({"error": "invalid signature"}), 400

    try:
        payload = json.loads(raw_body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return jsonify({"error": "invalid json"}), 400

    event_type = payload.get('event')
    data = payload.get('data', {})
    object_id = data.get('id')

    if not event_type or object_id is None:
        return jsonify({"error": "missing required fields"}), 400

    return jsonify({
        "status": "received",
        "event": event_type,
        "object_id": object_id
    }), 200


if __name__ == '__main__':
    app.run(debug=True)

from urllib.parse import urljoin, urlsplit, urlunsplit, parse_qs, urlencode
import posixpath


def normalize_and_merge_url(base_url: str, relative_url: str, extra_params: dict[str, str | list[str]]) -> str:
    """Resolve, normalize, and merge query parameters into a URL."""
    # Resolve the relative URL against the base URL.
    resolved = urljoin(base_url, relative_url)
    parts = urlsplit(resolved)

    # Normalize scheme and hostname case, and strip default ports.
    scheme = parts.scheme.lower()
    hostname = (parts.hostname or "").lower()
    port = parts.port

    if (scheme == "http" and port == 80) or (scheme == "https" and port == 443):
        port = None

    # Rebuild netloc, preserving username/password if present.
    auth = ""
    if parts.username:
        auth = parts.username
        if parts.password:
            auth += f":{parts.password}"
        auth += "@"

    netloc = auth + hostname
    if port is not None:
        netloc += f":{port}"

    # Normalize path by removing dot segments.
    path = posixpath.normpath(parts.path)
    if parts.path.endswith("/") and not path.endswith("/"):
        path += "/"
    if parts.path.startswith("/") and not path.startswith("/"):
        path = "/" + path
    if path == ".":
        path = ""

    # Parse existing query params and override with extra_params.
    query_map = parse_qs(parts.query, keep_blank_values=True)
    for key, value in extra_params.items():
        if isinstance(value, list):
            query_map[key] = value
        else:
            query_map[key] = [value]

    query = urlencode(query_map, doseq=True)

    return urlunsplit((scheme, netloc, path, query, parts.fragment))


if __name__ == "__main__":
    print(normalize_and_merge_url(
        "HTTPS://Example.COM:443/a/b/c?x=1",
        "../d/./e?x=old&y=2#section",
        {"x": "42", "z": ["alpha", "beta"]}
    ))

    print(normalize_and_merge_url(
        "http://USER:pass@Example.com:80/root/path/",
        "../../new/../file.txt?keep=yes",
        {"keep": "no", "added": "1"}
    ))

    print(normalize_and_merge_url(
        "https://api.example.com/v1/resources",
        "../items/../search?q=test",
        {"q": "updated", "tag": ["python", "url"]}
    ))

from functools import reduce, partial, cmp_to_key


def _weighted_score(record, default_weight=1):
    """Return score * weight, using a configurable default weight."""
    return record["score"] * record.get("weight", default_weight)


def _accumulate_categories(state, record, score_fn):
    """Reducer helper that aggregates totals and distinct item names by category."""
    category = record["category"]
    entry = state.setdefault(category, {"total": 0, "names": set()})
    entry["total"] += score_fn(record)
    entry["names"].add(record["name"])
    return state


def _compare_reports(left, right):
    """Sort by descending total, then ascending category name."""
    if left["total"] != right["total"]:
        return right["total"] - left["total"]
    if left["category"] < right["category"]:
        return -1
    if left["category"] > right["category"]:
        return 1
    return 0


def build_ranked_report(records, threshold):
    """
    Build a ranked category report from input records.

    Args:
        records: Iterable of dicts with keys: category, name, score, optional weight.
        threshold: Minimum total score required for a category to be included.

    Returns:
        A sorted list of dicts with keys: category, total, items.
    """
    score_fn = partial(_weighted_score, default_weight=1)

    aggregated = reduce(
        lambda state, rec: _accumulate_categories(state, rec, score_fn),
        records,
        {},
    )

    report = []
    for category, data in aggregated.items():
        if data["total"] >= threshold:
            report.append({
                "category": category,
                "total": data["total"],
                "items": ",".join(sorted(data["names"], key=str.lower)),
            })

    return sorted(report, key=cmp_to_key(_compare_reports))


if __name__ == "__main__":
    sample_records = [
        {"category": "tools", "name": "Hammer", "score": 10, "weight": 2},
        {"category": "tools", "name": "drill", "score": 7},
        {"category": "garden", "name": "Shovel", "score": 8, "weight": 3},
        {"category": "garden", "name": "shovel", "score": 2},
        {"category": "office", "name": "Pen", "score": 4},
    ]
    print(build_ranked_report(sample_records, threshold=10))

from typing import Callable, Dict, List, Any

Request = Dict[str, Any]
Response = Dict[str, Any]
Middleware = Callable[[Request, Callable[[Request], Response]], Response]
Handler = Callable[[Request], Response]


def build_pipeline(middlewares: List[Middleware], final_handler: Handler) -> Handler:
    """Build a middleware chain around the final handler."""
    handler = final_handler

    # Wrap the handler from last middleware to first.
    for middleware in reversed(middlewares):
        next_handler = handler

        def make_handler(mw: Middleware, nxt: Handler) -> Handler:
            return lambda request: mw(request, nxt)

        handler = make_handler(middleware, next_handler)

    return handler


def logging_middleware(request: Request, next_handler: Handler) -> Response:
    request.setdefault('log', []).append(f"Visited: {request.get('path', '/')}")
    return next_handler(request)



def default_user_middleware(request: Request, next_handler: Handler) -> Response:
    request.setdefault('user', 'guest')
    return next_handler(request)



def admin_guard_middleware(request: Request, next_handler: Handler) -> Response:
    if request.get('path') == '/admin' and not request.get('is_admin', False):
        return {'status': 403, 'message': 'Forbidden'}
    return next_handler(request)



def final_handler(request: Request) -> Response:
    return {
        'status': 200,
        'message': f"Hello, {request['user']}! You requested {request.get('path', '/')}"
    }


if __name__ == '__main__':
    pipeline = build_pipeline(
        [logging_middleware, default_user_middleware, admin_guard_middleware],
        final_handler,
    )

    requests = [
        {'path': '/home'},
        {'path': '/admin', 'user': 'alice', 'is_admin': False},
    ]

    for req in requests:
        response = pipeline(req)
        print('Request:', req)
        print('Response:', response)
        print('-' * 40)

import random


def genetic_knapsack(items, capacity, pop_size=60, generations=120, mutation_rate=0.02, crossover_rate=0.8):
    n = len(items)

    def fitness(chrom):
        total_value = sum(g * v for g, (v, w) in zip(chrom, items))
        total_weight = sum(g * w for g, (v, w) in zip(chrom, items))
        return total_value if total_weight <= capacity else 0

    def weight(chrom):
        return sum(g * w for g, (_, w) in zip(chrom, items))

    def tournament_select(pop, k=3):
        contenders = random.sample(pop, k)
        return max(contenders, key=fitness)[:]

    def crossover(a, b):
        if n < 2 or random.random() >= crossover_rate:
            return a[:], b[:]
        point = random.randint(1, n - 1)
        return a[:point] + b[point:], b[:point] + a[point:]

    def mutate(chrom):
        for i in range(n):
            if random.random() < mutation_rate:
                chrom[i] ^= 1
        return chrom

    population = [[random.randint(0, 1) for _ in range(n)] for _ in range(pop_size)]

    for _ in range(generations):
        best = max(population, key=fitness)[:]
        new_population = [best]  # elitism

        while len(new_population) < pop_size:
            p1 = tournament_select(population)
            p2 = tournament_select(population)
            c1, c2 = crossover(p1, p2)
            new_population.append(mutate(c1))
            if len(new_population) < pop_size:
                new_population.append(mutate(c2))

        population = new_population

    best = max(population, key=fitness)
    return best, fitness(best), weight(best)


if __name__ == "__main__":
    random.seed(42)
    items = [
        (20, 6), (30, 5), (35, 7), (12, 3),
        (3, 1), (40, 9), (25, 4), (18, 2)
    ]
    capacity = 20

    chromosome, total_value, total_weight = genetic_knapsack(
        items, capacity, pop_size=80, generations=150, mutation_rate=0.03, crossover_rate=0.85
    )

    selected = [i for i, bit in enumerate(chromosome) if bit]
    print("Best chromosome:", chromosome)
    print("Selected item indices:", selected)
    print("Total value:", total_value)
    print("Total weight:", total_weight)

