    unrealized_pnl: float
    total_pnl: float
    gross_exposure: float
    positions: List[PositionSnapshot]


@dataclass
class PositionState:
    quantity: int = 0
    avg_cost: float = 0.0

    def unrealized_pnl(self, market_price: float) -> float:
        if self.quantity == 0:
            return 0.0
        return (market_price - self.avg_cost) * self.quantity

    def market_value(self, market_price: float) -> float:
        return abs(self.quantity) * market_price

    def apply_fill(self, side: str, quantity: int, price: float) -> float:
        signed_qty = quantity if side == "BUY" else -quantity
        realized = 0.0

        if self.quantity == 0:
            self.quantity = signed_qty
            self.avg_cost = price
            return realized

        if self.quantity > 0 and signed_qty > 0:
            new_qty = self.quantity + signed_qty
            self.avg_cost = ((self.avg_cost * self.quantity) + (price * signed_qty)) / new_qty
            self.quantity = new_qty
            return realized

        if self.quantity < 0 and signed_qty < 0:
            abs_old = abs(self.quantity)
            abs_new = abs(self.quantity + signed_qty)
            self.avg_cost = ((self.avg_cost * abs_old) + (price * abs(signed_qty))) / abs_new
            self.quantity += signed_qty
            return realized

        if self.quantity > 0 and signed_qty < 0:
            closing_qty = min(self.quantity, abs(signed_qty))
            realized += (price - self.avg_cost) * closing_qty
            remaining_signed = self.quantity + signed_qty
            if remaining_signed > 0:
                self.quantity = remaining_signed
            elif remaining_signed == 0:
                self.quantity = 0
                self.avg_cost = 0.0
            else:
                self.quantity = remaining_signed
                self.avg_cost = price
            return realized

        if self.quantity < 0 and signed_qty > 0:
            closing_qty = min(abs(self.quantity), signed_qty)
            realized += (self.avg_cost - price) * closing_qty
            remaining_signed = self.quantity + signed_qty
            if remaining_signed < 0:
                self.quantity = remaining_signed
            elif remaining_signed == 0:
                self.quantity = 0
                self.avg_cost = 0.0
            else:
                self.quantity = remaining_signed
                self.avg_cost = price
            return realized

        return realized


@dataclass
class AccountState:
    positions: Dict[str, PositionState] = field(default_factory=dict)
    realized_pnl: float = 0.0


class RiskControlService:
    def __init__(self, config: ServiceConfig):
        self._config = config
        self._accounts: Dict[str, AccountState] = {}
        self._market_prices: Dict[str, float] = {}
        self._lock = RLock()

    @classmethod
    def from_config_file(cls, path: str | Path) -> "RiskControlService":
        config_path = Path(path)
        if not config_path.exists():
            raise FileNotFoundError(f"Config file not found: {config_path}")
        with config_path.open("r", encoding="utf-8") as fh:
            raw = json.load(fh)
        config = ServiceConfig.model_validate(raw)
        return cls(config=config)

    def load_risk_rules(self, path: str | Path) -> None:
        new_service = self.from_config_file(path)
        with self._lock:
            self._config = new_service._config

    def _get_rules(self, account_id: str) -> RiskRuleConfig:
        return self._config.account_rules.get(account_id, self._config.default_rules)

    def _get_account_state(self, account_id: str) -> AccountState:
        if account_id not in self._accounts:
            self._accounts[account_id] = AccountState()
        return self._accounts[account_id]

    def update_market_price(self, update: MarketPriceUpdate) -> None:
        with self._lock:
            self._market_prices[update.symbol] = update.price

    def record_fill(self, fill: FillEvent) -> Dict[str, float]:
        with self._lock:
            account = self._get_account_state(fill.account_id)
            position = account.positions.setdefault(fill.symbol, PositionState())
            realized = position.apply_fill(fill.side, fill.quantity, fill.price)
            account.realized_pnl += realized
            if position.quantity == 0:
                account.positions.pop(fill.symbol, None)
            snapshot = self.get_account_snapshot(fill.account_id)
            return {
                "realized_increment": round(realized, 2),
                "realized_pnl": round(snapshot.realized_pnl, 2),
                "unrealized_pnl": round(snapshot.unrealized_pnl, 2),
                "total_pnl": round(snapshot.total_pnl, 2),
            }

    def _compute_unrealized_pnl(self, account: AccountState) -> float:
        total = 0.0
        for symbol, position in account.positions.items():
            market_price = self._market_prices.get(symbol, position.avg_cost)
            total += position.unrealized_pnl(market_price)
        return total

    def _compute_gross_exposure(self, account: AccountState) -> float:
        total = 0.0
        for symbol, position in account.positions.items():
            market_price = self._market_prices.get(symbol, position.avg_cost)
            total += position.market_value(market_price)
        return total

    def _project_position(self, current_qty: int, side: str, quantity: int) -> int:
        return current_qty + quantity if side == "BUY" else current_qty - quantity

    def _project_gross_exposure(self, account: AccountState, order: TradeOrder) -> float:
        total = 0.0
        for symbol, position in account.positions.items():
            market_price = self._market_prices.get(symbol, position.avg_cost)
            qty = position.quantity
            if symbol == order.symbol:
                qty = self._project_position(position.quantity, order.side, order.quantity)
                market_price = order.price
            total += abs(qty) * market_price

        if order.symbol not in account.positions:
            projected_qty = self._project_position(0, order.side, order.quantity)
            total += abs(projected_qty) * order.price

        return total

    def check_order(self, order: TradeOrder) -> OrderCheckResponse:
        with self._lock:
            rules = self._get_rules(order.account_id)
            account = self._get_account_state(order.account_id)
            position = account.positions.get(order.symbol, PositionState())
            current_position = position.quantity
            projected_position = self._project_position(current_position, order.side, order.quantity)

            current_gross = self._compute_gross_exposure(account)
            projected_gross = self._project_gross_exposure(account, order)

            realized_pnl = account.realized_pnl
            unrealized_pnl = self._compute_unrealized_pnl(account)
            total_pnl = realized_pnl + unrealized_pnl

            reasons: List[str] = []

            if abs(projected_position) > rules.max_abs_position_per_symbol:
                reasons.append(
                    f"Projected position {projected_position} exceeds symbol limit "
                    f"{rules.max_abs_position_per_symbol}"
                )

            if projected_gross > rules.max_gross_exposure:
                reasons.append(
                    f"Projected gross exposure {projected_gross:.2f} exceeds limit "
                    f"{rules.max_gross_exposure:.2f}"
                )

            if total_pnl <= -rules.daily_loss_limit:
                reasons.append(
                    f"Daily loss threshold breached: total P&L {total_pnl:.2f} <= "
                    f"-{rules.daily_loss_limit:.2f}"
                )

            approved = len(reasons) == 0
            if approved:
                reasons.append("APPROVED")

            return OrderCheckResponse(
                approved=approved,
                reasons=reasons,
                account_id=order.account_id,
                symbol=order.symbol,
                current_position=current_position,
                projected_position=projected_position,
                current_gross_exposure=round(current_gross, 2),
                projected_gross_exposure=round(projected_gross, 2),
                realized_pnl=round(realized_pnl, 2),
                unrealized_pnl=round(unrealized_pnl, 2),
                total_pnl=round(total_pnl, 2),
            )

    def get_account_snapshot(self, account_id: str) -> AccountRiskSnapshot:
        with self._lock:
            account = self._get_account_state(account_id)
            positions: List[PositionSnapshot] = []
            unrealized = 0.0
            gross = 0.0

            for symbol, position in account.positions.items():
                market_price = self._market_prices.get(symbol, position.avg_cost)
                upnl = position.unrealized_pnl(market_price)
                unrealized += upnl
                gross += position.market_value(market_price)
                positions.append(
                    PositionSnapshot(
                        account_id=account_id,
                        symbol=symbol,
                        quantity=position.quantity,
                        avg_cost=round(position.avg_cost, 4),
                        market_price=round(market_price, 4),
                        unrealized_pnl=round(upnl, 2),
                    )
                )

            realized = account.realized_pnl
            return AccountRiskSnapshot(
                account_id=account_id,
                realized_pnl=round(realized, 2),
                unrealized_pnl=round(unrealized, 2),
                total_pnl=round(realized + unrealized, 2),
                gross_exposure=round(gross, 2),
                positions=positions,
            )


