        raise HTTPException(status_code=400, detail=f"Config load failed: {exc}") from exc

class NonNegative:
    """Descriptor that allows only non-negative numeric values."""

    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, (int, float)):
            raise TypeError(f"{self.private_name[1:]} must be a number")
        if value < 0:
            raise ValueError(f"{self.private_name[1:]} cannot be negative")
        setattr(instance, self.private_name, value)


class Product:
    price = NonNegative()
    stock = NonNegative()

    def __init__(self, name, price, stock):
        self.name = name      # validated by property
        self.price = price    # validated by descriptor
        self.stock = stock    # validated by descriptor

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        cleaned = value.strip()
        if not cleaned:
            raise ValueError("name cannot be empty")
        self._name = cleaned

    @property
    def inventory_value(self):
        """Read-only computed property."""
        return self.price * self.stock


