import hashlib


def repeating_key_xor(data: bytes, key: bytes) -> bytes:
    """Apply repeating-key XOR to input bytes."""
    if not key:
        raise ValueError("Key must not be empty")
    return bytes(b ^ key[i % len(key)] for i, b in enumerate(data))


def encrypt_to_hex(plaintext: str, key: str) -> str:
    """Encrypt plaintext with repeating-key XOR and return hex ciphertext."""
    if not key:
        raise ValueError("Key must not be empty")
    plaintext_bytes = plaintext.encode("utf-8")
    key_bytes = key.encode("utf-8")
    ciphertext = repeating_key_xor(plaintext_bytes, key_bytes)
    return ciphertext.hex()


def decrypt_from_hex(ciphertext_hex: str, key: str) -> str:
    """Decrypt hex ciphertext encrypted with repeating-key XOR."""
    if not key:
        raise ValueError("Key must not be empty")
    try:
        ciphertext_bytes = bytes.fromhex(ciphertext_hex)
    except ValueError as exc:
        raise ValueError("Invalid hexadecimal ciphertext") from exc

    key_bytes = key.encode("utf-8")
    plaintext_bytes = repeating_key_xor(ciphertext_bytes, key_bytes)
    return plaintext_bytes.decode("utf-8")


def sha256_of_ciphertext(ciphertext_hex: str) -> str:
    """Compute SHA-256 digest of ciphertext bytes represented by hex."""
    try:
        ciphertext_bytes = bytes.fromhex(ciphertext_hex)
    except ValueError as exc:
        raise ValueError("Invalid hexadecimal ciphertext") from exc
    return hashlib.sha256(ciphertext_bytes).hexdigest()


if __name__ == "__main__":
    message = "Attack at dawn! Rendezvous at 0600."
    key = "cipher"

    ciphertext_hex = encrypt_to_hex(message, key)
    digest = sha256_of_ciphertext(ciphertext_hex)
    decrypted = decrypt_from_hex(ciphertext_hex, key)

    print("Ciphertext (hex):", ciphertext_hex)
    print("SHA-256:", digest)
    print("Decrypted:", decrypted)
    print("Match:", decrypted == message)

from html.parser import HTMLParser


class ArticleHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.articles = []
        self.current_article = None
        self.in_h2 = False
        self.capture_title = False

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)

        if tag == 'article':
            article_id = attrs_dict.get('id')
            if article_id:
                self.current_article = {
                    'id': article_id,
                    'title': '',
                    'links': []
                }

        elif self.current_article is not None:
            if tag == 'h2' and not self.current_article['title']:
                self.in_h2 = True
                self.capture_title = True
            elif tag == 'a':
                href = attrs_dict.get('href')
                if href:
                    self.current_article['links'].append(href)

    def handle_data(self, data):
        if self.current_article is not None and self.in_h2 and self.capture_title:
            text = data.strip()
            if text:
                if self.current_article['title']:
                    self.current_article['title'] += ' ' + text
                else:
                    self.current_article['title'] = text

    def handle_endtag(self, tag):
        if tag == 'h2':
            self.in_h2 = False
            self.capture_title = False
        elif tag == 'article' and self.current_article is not None:
            self.articles.append(self.current_article)
            self.current_article = None


def extract_article_data(html_text):
    parser = ArticleHTMLParser()
    parser.feed(html_text)
    return parser.articles


