class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_word = False


class PrefixTrie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_word = True

    def search(self, word):
        node = self._find_node(word)
        return node is not None and node.is_word

    def starts_with(self, prefix):
        return self._find_node(prefix) is not None

    def autocomplete(self, prefix):
        start_node = self._find_node(prefix)
        if start_node is None:
            return []

        results = []
        self._collect_words(start_node, prefix, results)
        return results

    def _find_node(self, text):
        node = self.root
        for char in text:
            if char not in node.children:
                return None
            node = node.children[char]
        return node

    def _collect_words(self, node, path, results):
        if node.is_word:
            results.append(path)

        for char in sorted(node.children):
            self._collect_words(node.children[char], path + char, results)


def main():
    trie = PrefixTrie()
    words = ["app", "apple", "apply", "apt", "bat", "bath", "banana"]

    for word in words:
        trie.insert(word)

    print(trie.search("apple"))      # True
    print(trie.search("appl"))       # False
    print(trie.starts_with("app"))   # True
    print(trie.starts_with("cat"))   # False
    print(trie.autocomplete("ap"))   # ['app', 'apple', 'apply', 'apt']
    print(trie.autocomplete("bat"))  # ['bat', 'bath']


