import hashlib


class User:
    def __init__(self, username: str, password: str, role: str):
        self.username = username
        self.password_hash = self._hash_password(password)
        self.role = role

    @staticmethod
    def _hash_password(password: str) -> str:
        return hashlib.sha256(password.encode('utf-8')).hexdigest()

    def verify_password(self, password: str) -> bool:
        return self.password_hash == self._hash_password(password)


class AuthSystem:
    def __init__(self):
        self.users = {}
        self.logged_in_users = set()
        self.permissions = {
            'admin': {'delete', 'edit', 'view'},
            'user': {'view'}
        }

    def register_user(self, username: str, password: str, role: str) -> bool:
        if username in self.users or role not in self.permissions:
            return False
        self.users[username] = User(username, password, role)
        return True

    def login(self, username: str, password: str) -> bool:
        user = self.users.get(username)
        if not user or not user.verify_password(password):
            return False
        self.logged_in_users.add(username)
        return True

    def is_authorized(self, username: str, action: str) -> bool:
        if username not in self.logged_in_users:
            return False
        user = self.users[username]
        return action in self.permissions.get(user.role, set())


if __name__ == '__main__':
    auth = AuthSystem()

    # Register users
    auth.register_user('alice', 'adminpass123', 'admin')
    auth.register_user('bob', 'userpass456', 'user')

    # Test logins
    print('Alice login (correct):', auth.login('alice', 'adminpass123'))
    print('Bob login (incorrect):', auth.login('bob', 'wrongpassword'))
    print('Bob login (correct):', auth.login('bob', 'userpass456'))

    # Test authorization
    actions = ['view', 'edit', 'delete']
    for username in ['alice', 'bob']:
        for action in actions:
            print(f'{username} can {action}:', auth.is_authorized(username, action))

