import hashlib
import hmac
import json
import time
from typing import Dict, Any


def handle_webhook(headers: dict, body: bytes, secret: str, tolerance_seconds: int = 300) -> dict:
    """Validate and parse a signed webhook request.

    Expected headers:
      - X-Signature: hex-encoded HMAC-SHA256 digest
      - X-Timestamp: Unix timestamp as a string
    """
    signature = headers.get("X-Signature")
    timestamp_raw = headers.get("X-Timestamp")

    if not signature:
        raise ValueError("Missing X-Signature header")
    if not timestamp_raw:
        raise ValueError("Missing X-Timestamp header")

    try:
        timestamp = int(timestamp_raw)
    except (TypeError, ValueError):
        raise ValueError("Invalid X-Timestamp header")

    now = int(time.time())
    if abs(now - timestamp) > tolerance_seconds:
        raise ValueError("Expired webhook timestamp")

    signed_payload = f"{timestamp}.".encode("utf-8") + body
    expected_signature = hmac.new(
        secret.encode("utf-8"),
        signed_payload,
        hashlib.sha256,
    ).hexdigest()

    # Use constant-time comparison to prevent timing attacks.
    if not hmac.compare_digest(signature, expected_signature):
        raise ValueError("Invalid webhook signature")

    try:
        payload = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError("Invalid JSON body")

    if not isinstance(payload, dict):
        raise ValueError("Webhook body must be a JSON object")

    event = payload.get("event")
    event_id = payload.get("id")

    if not isinstance(event, str) or not event:
        raise ValueError("Field 'event' must be a non-empty string")
    if not isinstance(event_id, str) or not event_id:
        raise ValueError("Field 'id' must be a non-empty string")

    return {
        "id": event_id,
        "event": event,
        "payload": payload,
    }

import hashlib


class BloomFilter:
    def __init__(self, size: int, num_hashes: int):
        if size <= 0 or num_hashes <= 0:
            raise ValueError("size and num_hashes must be positive")
        self.size = size
        self.num_hashes = num_hashes
        self.bits = bytearray(size)

    def _hashes(self, item: str):
        data = item.encode('utf-8')
        # Use double hashing to derive multiple hash values efficiently.
        h1 = int(hashlib.sha256(data).hexdigest(), 16)
        h2 = int(hashlib.md5(data).hexdigest(), 16)
        for i in range(self.num_hashes):
            yield (h1 + i * h2) % self.size

    def add(self, item: str) -> None:
        for index in self._hashes(item):
            self.bits[index] = 1

    def might_contain(self, item: str) -> bool:
        return all(self.bits[index] for index in self._hashes(item))


if __name__ == '__main__':
    bloom = BloomFilter(size=1000, num_hashes=4)

    for word in ['apple', 'banana', 'orange', 'grape']:
        bloom.add(word)

    tests = ['apple', 'grape', 'melon', 'pear']
    for word in tests:
        print(f"{word}: {bloom.might_contain(word)}")

import threading
import multiprocessing
import time


def count_divisible_by_7(limit):
    """Count how many numbers from 1 to limit are divisible by 7."""
    count = 0
    for i in range(1, limit + 1):
        if i % 7 == 0:
            count += 1
    return count


def thread_task(limit, results, index):
    """Store the result of the calculation in a shared list."""
    results[index] = count_divisible_by_7(limit)


def process_task(limit, queue):
    """Put the result into a multiprocessing queue."""
    queue.put(count_divisible_by_7(limit))


def run_threads(limit):
    results = [0, 0]
    threads = [
        threading.Thread(target=thread_task, args=(limit, results, 0)),
        threading.Thread(target=thread_task, args=(limit, results, 1)),
    ]

    start = time.time()
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
    end = time.time()

    print('Threading results:', results)
    print('Threading time: {:.4f} seconds'.format(end - start))


def run_processes(limit):
    queue = multiprocessing.Queue()
    processes = [
        multiprocessing.Process(target=process_task, args=(limit, queue)),
        multiprocessing.Process(target=process_task, args=(limit, queue)),
    ]

    start = time.time()
    for process in processes:
        process.start()
    for process in processes:
        process.join()
    results = [queue.get(), queue.get()]
    end = time.time()

    print('Multiprocessing results:', results)
    print('Multiprocessing time: {:.4f} seconds'.format(end - start))


if __name__ == '__main__':
    LIMIT = 500000

    print('Running threading example...')
    run_threads(LIMIT)

    print('\nRunning multiprocessing example...')
    run_processes(LIMIT)

