import time


class LogBlock:
    def __init__(self, log_path, block_name):
        self.log_path = log_path
        self.block_name = block_name
        self.start_time = None

    def _write_log(self, message):
        # Append a single log line to the file.
        with open(self.log_path, 'a', encoding='utf-8') as file:
            file.write(message + '\n')

    def __enter__(self):
        self.start_time = time.time()
        self._write_log(f"START: {self.block_name}")
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        if exc_type is None:
            elapsed = round(time.time() - self.start_time, 3)
            self._write_log(f"END: {self.block_name} ({elapsed}s)")
        else:
            self._write_log(f"ERROR: {self.block_name} - {exc_value}")

        # Return False so exceptions are not suppressed.
        return False


def main():
    log_file = 'execution.log'

    # Example of a successful block.
    with LogBlock(log_file, 'successful task'):
        time.sleep(0.2)
        result = sum(range(1000))
        print('Successful result:', result)

    # Example of a failing block.
    try:
        with LogBlock(log_file, 'failing task'):
            time.sleep(0.1)
            raise ValueError('Something went wrong')
    except ValueError as error:
        print('Caught exception:', error)


if __name__ == '__main__':
    main()
}

class TextEditor:
    def __init__(self):
        self.content = ""

    def add_text(self, text):
        self.content += text

    def delete_text(self, count):
        deleted = self.content[-count:]
        self.content = self.content[:-count]
        return deleted


class Command:
    def execute(self):
        raise NotImplementedError

    def undo(self):
        raise NotImplementedError


class AddTextCommand(Command):
    def __init__(self, editor, text):
        self.editor = editor
        self.text = text

    def execute(self):
        self.editor.add_text(self.text)

    def undo(self):
        self.editor.delete_text(len(self.text))


class DeleteTextCommand(Command):
    def __init__(self, editor, count):
        self.editor = editor
        self.count = count
        self.deleted_text = ""

    def execute(self):
        self.deleted_text = self.editor.delete_text(self.count)

    def undo(self):
        self.editor.add_text(self.deleted_text)


class CommandManager:
    def __init__(self):
        self.history = []

    def run_command(self, command):
        command.execute()
        self.history.append(command)

    def undo_last(self):
        if self.history:
            command = self.history.pop()
            command.undo()


