import argparse
import os

TASKS_FILE = 'tasks.txt'


def load_tasks():
    """Load tasks from the file, returning a list of task strings."""
    if not os.path.exists(TASKS_FILE):
        return []
    with open(TASKS_FILE, 'r', encoding='utf-8') as file:
        return [line.strip() for line in file if line.strip()]


def save_tasks(tasks):
    """Save the task list back to the file."""
    with open(TASKS_FILE, 'w', encoding='utf-8') as file:
        for task in tasks:
            file.write(task + '\n')


def main():
    parser = argparse.ArgumentParser(description='Simple CLI to-do list manager')
    parser.add_argument('action', choices=['add', 'list', 'remove'], help='Action to perform')
    parser.add_argument('--task', help='Task text for adding a new task')
    parser.add_argument('--index', type=int, help='1-based task number to remove')

    args = parser.parse_args()
    tasks = load_tasks()

    if args.action == 'add':
        if not args.task:
            parser.error("the 'add' action requires --task")
        tasks.append(args.task)
        save_tasks(tasks)
        print(f'Added task: {args.task}')

    elif args.action == 'list':
        if not tasks:
            print('No tasks found.')
        else:
            for i, task in enumerate(tasks, start=1):
                print(f'{i}. {task}')

    elif args.action == 'remove':
        if args.index is None:
            parser.error("the 'remove' action requires --index")
        if args.index < 1 or args.index > len(tasks):
            print('Error: invalid task index.')
            return
        removed = tasks.pop(args.index - 1)
        save_tasks(tasks)
        print(f'Removed task: {removed}')


if __name__ == '__main__':
    main()
}

class MaxQueueStack:
    """Queue implemented with two stacks, supporting O(1) amortized max()."""

    def __init__(self):
        # Each stack stores tuples: (value, current_max_in_that_stack)
        self._in = []
        self._out = []

    def _push_with_max(self, stack, value):
        current_max = value if not stack else max(value, stack[-1][1])
        stack.append((value, current_max))

    def _transfer(self):
        # Move items from _in to _out, reversing order for queue behavior
        while self._in:
            value = self._in.pop()[0]
            self._push_with_max(self._out, value)

    def enqueue(self, x):
        self._push_with_max(self._in, x)

    def dequeue(self):
        if self.empty():
            raise IndexError('dequeue from empty queue')
        if not self._out:
            self._transfer()
        return self._out.pop()[0]

    def front(self):
        if self.empty():
            raise IndexError('front from empty queue')
        if not self._out:
            self._transfer()
        return self._out[-1][0]

    def max(self):
        if self.empty():
            raise IndexError('max from empty queue')
        if not self._in:
            return self._out[-1][1]
        if not self._out:
            return self._in[-1][1]
        return max(self._in[-1][1], self._out[-1][1])

    def empty(self):
        return not self._in and not self._out

    def size(self):
        return len(self._in) + len(self._out)


# Example usage
if __name__ == '__main__':
    q = MaxQueueStack()
    q.enqueue(3)
    q.enqueue(1)
    q.enqueue(5)
    q.enqueue(2)

    print(q.front())   # 3
    print(q.max())     # 5
    print(q.dequeue()) # 3
    print(q.max())     # 5
    print(q.dequeue()) # 1
    print(q.front())   # 5
    print(q.size())    # 2

import hashlib


class BloomFilter:
    def __init__(self, size: int, hash_count: int):
        if size <= 0 or hash_count <= 0:
            raise ValueError('size and hash_count must be positive integers')
        self.size = size
        self.hash_count = hash_count
        self.bits = bytearray((size + 7) // 8)
        self._set_bits = 0

    def _hashes(self, item: str):
        if not isinstance(item, str):
            raise TypeError('BloomFilter only supports string items')
        data = item.encode('utf-8')
        h1 = int.from_bytes(hashlib.sha256(data).digest(), 'big')
        h2 = int.from_bytes(hashlib.md5(data).digest(), 'big') or 1
        for i in range(self.hash_count):
            yield (h1 + i * h2) % self.size

    def _get_bit(self, index: int) -> int:
        byte_index, bit_index = divmod(index, 8)
        return (self.bits[byte_index] >> bit_index) & 1

    def _set_bit(self, index: int):
        byte_index, bit_index = divmod(index, 8)
        mask = 1 << bit_index
        if not self.bits[byte_index] & mask:
            self.bits[byte_index] |= mask
            self._set_bits += 1

    def add(self, item: str):
        for index in self._hashes(item):
            self._set_bit(index)

    def __contains__(self, item: str) -> bool:
        return all(self._get_bit(index) for index in self._hashes(item))

    @property
    def fill_ratio(self) -> float:
        return self._set_bits / self.size


if __name__ == '__main__':
    bf = BloomFilter(size=1024, hash_count=4)
    for word in ['apple', 'banana', 'cherry']:
        bf.add(word)

    print('apple' in bf)   # True
    print('grape' in bf)   # Probably False
    print(round(bf.fill_ratio, 4))

class NonNegative:
    """Descriptor that allows only non-negative numbers."""

    def __set_name__(self, owner, name):
        self.private_name = '_' + name

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, (int, float)):
            raise TypeError(f"{self.private_name[1:]} must be a number")
        if value < 0:
            raise ValueError(f"{self.private_name[1:]} cannot be negative")
        setattr(instance, self.private_name, value)


class Product:
    price = NonNegative()
    stock = NonNegative()

    def __init__(self, name, price, stock):
        self.name = name      # Uses the property setter
        self.price = price    # Uses the descriptor
        self.stock = stock    # Uses the descriptor

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        cleaned = value.strip()
        if not cleaned:
            raise ValueError('name cannot be empty')
        self._name = cleaned

    @property
    def total_value(self):
        return self.price * self.stock


# Example usage
