import csv
from datetime import datetime
from io import StringIO
from typing import List, Dict


def etl_orders(csv_text: str) -> List[Dict]:
    """Extract, transform, and load order records from CSV text."""
    reader = csv.DictReader(StringIO(csv_text))
    required = {"order_id", "customer_id", "order_date", "amount", "status"}

    if not reader.fieldnames or not required.issubset({h.strip() for h in reader.fieldnames if h}):
        raise ValueError("CSV is missing one or more required columns")

    latest_by_order_id = {}

    for raw_row in reader:
        # Normalize whitespace and missing values
        row = {k.strip(): (v.strip() if v is not None else "") for k, v in raw_row.items() if k is not None}

        # Skip incomplete rows
        if any(not row.get(col, "") for col in required):
            continue

        status = row["status"].lower()
        if status not in {"paid", "shipped"}:
            continue

        # Parse and validate typed fields
        try:
            order_date = datetime.strptime(row["order_date"], "%Y-%m-%d").date()
            amount = float(row["amount"])
        except (ValueError, TypeError):
            continue

        record = {
            "order_id": row["order_id"],
            "customer_id": row["customer_id"],
            "order_date": order_date,
            "amount": amount,
            "status": status,
        }

        # Deduplicate by keeping the most recent order_date per order_id
        existing = latest_by_order_id.get(record["order_id"])
        if existing is None or record["order_date"] > existing["order_date"]:
            latest_by_order_id[record["order_id"]] = record

    # Prepare final sorted output
    result = []
    for record in sorted(latest_by_order_id.values(), key=lambda r: r["order_date"]):
        result.append({
            "order_id": record["order_id"],
            "customer_id": record["customer_id"],
            "order_date": record["order_date"].isoformat(),
            "amount": record["amount"],
            "status": record["status"],
            "amount_with_tax": round(record["amount"] * 1.2, 2),
        })

    return result

from functools import reduce, cmp_to_key, lru_cache


def build_report(events):
    """Build aggregated analytics from a list of event dictionaries."""

    def sum_by_field(items, field):
        # Use reduce to accumulate totals for the requested grouping field.
        return reduce(
            lambda acc, event: {
                **acc,
                event[field]: acc.get(event[field], 0) + event.get('value', 0)
            },
            items,
            {}
        )

    totals_by_user = sum_by_field(events, 'user')
    totals_by_category = sum_by_field(events, 'category')

    def compare_users(a, b):
        # Sort by total descending, then user name ascending for stable tie-breaking.
        if a[1] != b[1]:
            return b[1] - a[1]
        return (a[0] > b[0]) - (a[0] < b[0])

    sorted_users = sorted(totals_by_user.items(), key=cmp_to_key(compare_users))
    top_user = sorted_users[0][0] if sorted_users else None

    @lru_cache(maxsize=None)
    def cached_lookup(user):
        return totals_by_user.get(user, 0)

    return {
        'totals_by_user': totals_by_user,
        'totals_by_category': totals_by_category,
        'top_user': top_user,
        'cached_lookup': cached_lookup,
    }


if __name__ == '__main__':
    sample_events = [
        {'user': 'alice', 'category': 'books', 'value': 15},
        {'user': 'bob', 'category': 'games', 'value': 40},
        {'user': 'alice', 'category': 'games', 'value': 10},
        {'user': 'carol', 'category': 'books', 'value': 25},
        {'user': 'bob', 'category': 'books', 'value': 5},
    ]

    report = build_report(sample_events)
    print(report['totals_by_user'])
    print(report['totals_by_category'])
    print(report['top_user'])
    print(report['cached_lookup']('alice'))
    print(report['cached_lookup']('unknown'))

import json
from pathlib import Path


def load_config(path):
    """Load and validate a JSON config file."""
    config_path = Path(path)

    if not config_path.exists():
        raise FileNotFoundError(f"Config file not found: {path}")

    try:
        with config_path.open("r", encoding="utf-8") as file:
            data = json.load(file)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON in config file: {exc.msg}") from exc
    except OSError as exc:
        raise ValueError(f"Could not read config file: {exc}") from exc

    required_fields = {
        "host": str,
        "port": int,
        "debug": bool,
    }

    for field, expected_type in required_fields.items():
        if field not in data:
            raise ValueError(f"Missing required field: {field}")
        if not isinstance(data[field], expected_type):
            raise ValueError(
                f"Field '{field}' must be of type {expected_type.__name__}"
            )

    return data


def main():
    path = "config.json"

    try:
        config = load_config(path)
    except FileNotFoundError as exc:
        print(f"Error: {exc}")
    except ValueError as exc:
        print(f"Configuration error: {exc}")
    else:
        print("Configuration loaded successfully:")
        print(config)


if __name__ == "__main__":
    main()

import requests
from requests import RequestException


class APIClient:
    """Simple REST API client for JSONPlaceholder."""

    def __init__(self, base_url, timeout=5):
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.session = requests.Session()

    def get(self, endpoint, params=None):
        """Send a GET request and return parsed JSON data."""
        url = f"{self.base_url}/{endpoint.lstrip('/')}"
        try:
            response = self.session.get(url, params=params, timeout=self.timeout)
            response.raise_for_status()
            return response.json()
        except RequestException as exc:
            raise RuntimeError(f"GET request failed for {url}: {exc}") from exc
        except ValueError as exc:
            raise RuntimeError(f"Invalid JSON response from {url}") from exc

    def get_posts_by_user(self, user_id):
        """Fetch all posts for a specific user ID."""
        return self.get("posts", params={"userId": user_id})


def main():
    client = APIClient("https://jsonplaceholder.typicode.com")

    try:
        posts = client.get_posts_by_user(1)
    except RuntimeError as err:
        print(f"Error: {err}")
        return

    for post in posts:
        print(f"{post['id']}: {post['title']}")


if __name__ == "__main__":
