class TextEditor:
    def __init__(self):
        self.text = ""

    def append(self, value):
        self.text += value

    def delete_last(self, count):
        self.text = self.text[:-count] if count <= len(self.text) else ""


class AppendCommand:
    def __init__(self, editor, value):
        self.editor = editor
        self.value = value

    def execute(self):
        self.editor.append(self.value)


class DeleteLastCommand:
    def __init__(self, editor, count):
        self.editor = editor
        self.count = count

    def execute(self):
        self.editor.delete_last(self.count)


class Invoker:
    def __init__(self):
        self.commands = []

    def add_command(self, command):
        self.commands.append(command)

    def run(self):
        for command in self.commands:
            command.execute()


if __name__ == "__main__":
    editor = TextEditor()
    invoker = Invoker()

    # Queue up commands
    invoker.add_command(AppendCommand(editor, "Hello"))
    invoker.add_command(AppendCommand(editor, " World"))
    invoker.add_command(DeleteLastCommand(editor, 3))
    invoker.add_command(AppendCommand(editor, "ld!"))

    # Execute all commands
    invoker.run()

    print("Final text:", editor.text)

import re
from typing import Any, Dict, List

ORDER_ID_RE = re.compile(r'^ORD-\d{6}$')
EMAIL_RE = re.compile(r'^[^@\s]+@[^@\s]+\.[^@\s]+$')
SKU_RE = re.compile(r'^[A-Z0-9-]+$')


def validate_orders(payload: Any) -> List[Dict[str, Any]]:
    if not isinstance(payload, list):
        raise ValueError('orders: expected a list')

    normalized = []
    for i, order in enumerate(payload):
        path = f'orders[{i}]'
        if not isinstance(order, dict):
            raise ValueError(f'{path}: expected object')

        required = {'order_id', 'customer', 'items'}
        missing = required - order.keys()
        if missing:
            raise ValueError(f"{path}.{sorted(missing)[0]}: missing required field")

        order_id = order['order_id']
        if not isinstance(order_id, str) or not ORDER_ID_RE.match(order_id):
            raise ValueError(f'{path}.order_id: invalid format')

        customer = order['customer']
        if not isinstance(customer, dict):
            raise ValueError(f'{path}.customer: expected object')
        for field in ('name', 'email'):
            if field not in customer:
                raise ValueError(f'{path}.customer.{field}: missing required field')

        name = customer['name']
        if not isinstance(name, str) or not name.strip():
            raise ValueError(f'{path}.customer.name: must be a non-empty string')

        email = customer['email']
        if not isinstance(email, str) or not EMAIL_RE.match(email):
            raise ValueError(f'{path}.customer.email: invalid email')

        items = order['items']
        if not isinstance(items, list) or not items:
            raise ValueError(f'{path}.items: must be a non-empty list')

        normalized_items = []
        subtotal = 0.0
        for j, item in enumerate(items):
            item_path = f'{path}.items[{j}]'
            if not isinstance(item, dict):
                raise ValueError(f'{item_path}: expected object')
            for field in ('sku', 'quantity', 'price'):
                if field not in item:
                    raise ValueError(f'{item_path}.{field}: missing required field')

            sku = item['sku']
            if not isinstance(sku, str) or not SKU_RE.match(sku.upper()):
                raise ValueError(f'{item_path}.sku: invalid format')

            quantity = item['quantity']
            if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity <= 0:
                raise ValueError(f'{item_path}.quantity: must be an integer > 0')

            price = item['price']
            if not isinstance(price, (int, float)) or isinstance(price, bool) or price < 0:
                raise ValueError(f'{item_path}.price: must be a non-negative number')

            price = round(float(price), 2)
            subtotal += quantity * price
            normalized_items.append({
                'sku': sku.upper(),
                'quantity': quantity,
                'price': price,
            })

        discount = order.get('discount', 0)
        if not isinstance(discount, (int, float)) or isinstance(discount, bool) or not (0 <= discount <= 100):
            raise ValueError(f'{path}.discount: must be a number between 0 and 100')

        total = round(subtotal * (1 - float(discount) / 100), 2)
        normalized.append({
            'order_id': order_id,
            'customer': {
                'name': name.strip(),
                'email': email.lower(),
            },
            'items': normalized_items,
            'discount': float(discount),
            'total': total,
        })

    return normalized

def count_bytes_in_file(input_path):
    # Create a list of 256 counters, one for each possible byte value
    counts = [0] * 256
    total_bytes = 0

    with open(input_path, 'rb') as file:
        while True:
            chunk = file.read(4096)
            if not chunk:
                break

            total_bytes += len(chunk)
            for byte in chunk:
                counts[byte] += 1

    return counts, total_bytes


def write_counts_to_file(output_path, counts):
    with open(output_path, 'w', encoding='utf-8') as file:
        for value, count in enumerate(counts):
            file.write(f'{value}: {count}\n')


def main():
    input_file = 'input.bin'
    output_file = 'byte_counts.txt'

    try:
        counts, total_bytes = count_bytes_in_file(input_file)
        write_counts_to_file(output_file, counts)
        print(f'Total bytes read: {total_bytes}')
        print(f'Byte counts written to {output_file}')
    except FileNotFoundError:
        print(f'Error: {input_file} was not found.')
    except OSError as error:
        print(f'File error: {error}')


if __name__ == '__main__':
    main()
}

def even_squares(limit):
    """Yield squares of even numbers from 0 to limit inclusive."""
    for number in range(0, limit + 1, 2):
        yield number * number


def print_first_n_values(generator, count):
    """Print up to `count` values from a generator lazily."""
    printed = 0
    for value in generator:
        print(value)
        printed += 1
        if printed == count:
            break


