import time
from collections import OrderedDict
from functools import wraps
from threading import RLock


def ttl_lru_memoize(maxsize=128, ttl=5.0):
    """Thread-safe memoization with TTL expiration and LRU eviction."""
    def decorator(func):
        cache = OrderedDict()
        lock = RLock()
        stats = {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}

        def make_key(args, kwargs):
            # Deterministic, hashable key for args + kwargs
            return args, tuple(sorted(kwargs.items()))

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = time.monotonic()

            with lock:
                if key in cache:
                    value, expires_at = cache[key]
                    if now < expires_at:
                        cache.move_to_end(key)  # mark as recently used
                        stats["hits"] += 1
                        return value
                    # Expired entry
                    del cache[key]
                    stats["expirations"] += 1

                stats["misses"] += 1

            # Compute outside the lock to avoid blocking other threads
            result = func(*args, **kwargs)
            expires_at = time.monotonic() + ttl

            with lock:
                cache[key] = (result, expires_at)
                cache.move_to_end(key)
                if len(cache) > maxsize:
                    cache.popitem(last=False)  # evict LRU
                    stats["evictions"] += 1
            return result

        def cache_info():
            with lock:
                return {
                    "size": len(cache),
                    "maxsize": maxsize,
                    "ttl": ttl,
                    **stats,
                }

        def cache_clear():
            with lock:
                cache.clear()
                for k in stats:
                    stats[k] = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator


@ttl_lru_memoize(maxsize=32, ttl=2.0)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)


if __name__ == "__main__":
    print(fib(20))
    print(fib.cache_info())
    time.sleep(2.1)
    print(fib(20))
    print(fib.cache_info())

import json


def handle_webhook(payload):
    """Process a webhook JSON payload and return a result dictionary."""
    try:
        data = json.loads(payload)
    except json.JSONDecodeError:
        return {"status": "error", "message": "Invalid JSON payload"}

    # Required fields for a valid webhook event
    required_fields = ["event", "user", "timestamp"]
    missing_fields = [field for field in required_fields if field not in data]

    if missing_fields:
        return {
            "status": "error",
            "message": f"Missing required fields: {', '.join(missing_fields)}"
        }

    return {
        "status": "success",
        "message": f"Processed {data['event']} for {data['user']}"
    }


