import base64
import hashlib
import hmac
import json
from typing import Set, Dict, Any

SECRET_KEY = b"super-secret-shared-key"
ROLE_SCOPES = {
    "admin": {"read", "write", "delete"},
    "editor": {"read", "write"},
    "viewer": {"read"},
}


def b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def b64url_decode(data: str) -> bytes:
    padding = "=" * (-len(data) % 4)
    return base64.urlsafe_b64decode(data + padding)


def sign_payload(payload_b64: str) -> str:
    sig = hmac.new(SECRET_KEY, payload_b64.encode("ascii"), hashlib.sha256).digest()
    return b64url_encode(sig)


def create_token(payload: Dict[str, Any]) -> str:
    payload_json = json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8")
    payload_b64 = b64url_encode(payload_json)
    return f"{payload_b64}.{sign_payload(payload_b64)}"


def authorize(token: str, required_scopes: Set[str], now: int) -> Dict[str, Any]:
    try:
        payload_b64, sig_b64 = token.split(".", 1)
    except ValueError:
        return {"ok": False, "error": "malformed token"}

    expected_sig = sign_payload(payload_b64)
    if not hmac.compare_digest(sig_b64, expected_sig):
        return {"ok": False, "error": "invalid signature"}

    try:
        payload = json.loads(b64url_decode(payload_b64).decode("utf-8"))
    except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
        return {"ok": False, "error": "invalid payload"}

    sub = payload.get("sub")
    exp = payload.get("exp")
    roles = payload.get("roles", [])
    scopes = set(payload.get("scopes", []))

    if not isinstance(sub, str) or not isinstance(exp, int):
        return {"ok": False, "error": "missing required claims"}
    if now >= exp:
        return {"ok": False, "error": "token expired"}
    if not isinstance(roles, list) or not isinstance(payload.get("scopes", []), list):
        return {"ok": False, "error": "invalid roles or scopes"}

    effective_scopes = set(scopes)
    for role in roles:
        if isinstance(role, str):
            effective_scopes.update(ROLE_SCOPES.get(role, set()))

    if not required_scopes.issubset(effective_scopes):
        return {"ok": False, "error": "insufficient scope"}

    return {
        "ok": True,
        "sub": sub,
        "scopes": sorted(effective_scopes),
    }


if __name__ == "__main__":
    current_time = 1_700_000_000

    token_ok = create_token({
        "sub": "user-123",
        "exp": current_time + 3600,
        "roles": ["editor"],
        "scopes": ["comment"],
    })
    print(authorize(token_ok, {"read", "write"}, current_time))
