import os
from dataclasses import dataclass, asdict


@dataclass
class Config:
    app_host: str
    app_port: int
    debug: bool
    api_key: str


def parse_bool(value: str, default: bool = False) -> bool:
    """Convert common environment variable boolean strings to bool."""
    if value is None:
        return default

    value = value.strip().lower()
    if value in {"1", "true", "yes", "on"}:
        return True
    if value in {"0", "false", "no", "off"}:
        return False
    raise ValueError(f"Invalid boolean value: {value!r}")


def parse_port(value: str) -> int:
    """Validate that the port is a valid integer TCP port."""
    try:
        port = int(value)
    except (TypeError, ValueError):
        raise ValueError("APP_PORT must be an integer") from None

    if not (1 <= port <= 65535):
        raise ValueError("APP_PORT must be between 1 and 65535")
    return port


def mask_secret(secret: str) -> str:
    """Mask all but the last 4 characters of a secret."""
    if len(secret) <= 4:
        return "*" * len(secret)
    return "*" * (len(secret) - 4) + secret[-4:]


def load_config() -> Config:
    app_host = os.getenv("APP_HOST", "127.0.0.1")
    app_port = parse_port(os.getenv("APP_PORT", "8000"))
    debug = parse_bool(os.getenv("DEBUG"), default=False)

    api_key = os.getenv("API_KEY")
    if api_key is None or not api_key.strip():
        raise ValueError("API_KEY is required and cannot be blank")

    return Config(
        app_host=app_host,
        app_port=app_port,
        debug=debug,
        api_key=api_key.strip(),
    )


def main() -> None:
    config = load_config()
    output = asdict(config)
    output["api_key"] = mask_secret(config.api_key)
    print(output)


if __name__ == "__main__":
    main()

class DisjointSet:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.components = n

    def find(self, x):
        # Path compression
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a, b):
        # Returns True if a merge happened, False if already connected
        root_a = self.find(a)
        root_b = self.find(b)

        if root_a == root_b:
            return False

        # Union by rank
        if self.rank[root_a] < self.rank[root_b]:
            self.parent[root_a] = root_b
        elif self.rank[root_a] > self.rank[root_b]:
            self.parent[root_b] = root_a
        else:
            self.parent[root_b] = root_a
            self.rank[root_a] += 1

        self.components -= 1
        return True


def count_networks_and_redundant(n, connections):
    dsu = DisjointSet(n)
    redundant = 0

    for a, b in connections:
        if not dsu.union(a, b):
            redundant += 1

    return dsu.components, redundant


# Example usage
if __name__ == "__main__":
    n = 7
    connections = [[0, 1], [1, 2], [3, 4], [2, 0], [5, 6], [4, 3], [2, 3]]
    print(count_networks_and_redundant(n, connections))  # Output: (2, 2)

import struct
import zlib


def build_record(record_type: int, payload: bytes) -> bytes:
    """Build a single binary record with CRC32 over the payload."""
    if not (0 <= record_type <= 255):
        raise ValueError("record_type must fit in one byte")
    if len(payload) > 0xFFFF:
        raise ValueError("payload too large for 2-byte length field")

    crc = zlib.crc32(payload) & 0xFFFFFFFF
    return struct.pack(">HB", len(payload), record_type) + payload + struct.pack(">I", crc)


def parse_records(data: bytes) -> list[dict]:
    """Parse a stream of binary records into Python dictionaries."""
    records = []
    offset = 0
    total = len(data)

    while offset < total:
        # Need at least: 2 bytes length + 1 byte type + 4 bytes CRC
        if total - offset < 7:
            raise ValueError(f"truncated record header at offset {offset}")

        payload_len, record_type = struct.unpack_from(">HB", data, offset)
        offset += 3

        if total - offset < payload_len + 4:
            raise ValueError(f"truncated payload or CRC at offset {offset}")

        payload = data[offset:offset + payload_len]
        offset += payload_len

        (stored_crc,) = struct.unpack_from(">I", data, offset)
        offset += 4

        actual_crc = zlib.crc32(payload) & 0xFFFFFFFF
        if actual_crc != stored_crc:
            raise ValueError(f"CRC mismatch for record at offset {offset - payload_len - 7}")

        if record_type == 1:
            try:
                value = payload.decode("utf-8")
            except UnicodeDecodeError as e:
                raise ValueError("invalid UTF-8 payload") from e
            records.append({"type": "text", "value": value})

        elif record_type == 2:
            if payload_len % 4 != 0:
                raise ValueError("integer record payload length must be divisible by 4")
            count = payload_len // 4
            value = list(struct.unpack(f">{count}i", payload))
            records.append({"type": "int32_list", "value": value})

        elif record_type == 3:
            records.append({"type": "hex", "value": payload.hex()})

        else:
            raise ValueError(f"unknown record type: {record_type}")

    return records


if __name__ == "__main__":
    text_record = build_record(1, "hello binary".encode("utf-8"))
    int_payload = struct.pack(">3i", 42, -7, 1024)
    int_record = build_record(2, int_payload)

    blob = text_record + int_record
    print(parse_records(blob))

from __future__ import annotations

from collections import defaultdict, deque
from dataclasses import dataclass
from datetime import datetime
from typing import Any, Deque, Dict, Iterable, List, Optional, Union


@dataclass(frozen=True)
class BuildRecord:
    pipeline_name: str
    stage_name: str
    status: str
    duration_seconds: float
    timestamp: datetime


class PipelineMonitor:
    VALID_STATUSES = {"success", "failed", "running", "canceled", "skipped"}

    def __init__(self, max_records_per_pipeline: Optional[int] = None) -> None:
        self.max_records_per_pipeline = max_records_per_pipeline
        self._records_by_pipeline: Dict[str, Deque[BuildRecord]] = defaultdict(
            lambda: deque(maxlen=max_records_per_pipeline)
        )
        self._all_records: List[BuildRecord] = []

    def add_record(
        self,
        pipeline_name: str,
        stage_name: str,
        status: str,
        duration_seconds: Union[int, float],
        timestamp: Union[str, datetime],
    ) -> bool:
        try:
            record = self._validate_and_build_record(
                pipeline_name, stage_name, status, duration_seconds, timestamp
            )
        except (TypeError, ValueError):
            return False

        self._records_by_pipeline[record.pipeline_name].append(record)
        self._all_records.append(record)
        return True

    def add_records(self, records: Iterable[dict]) -> int:
        added = 0
        for item in records:
            if not isinstance(item, dict):
                continue
            if self.add_record(
                item.get("pipeline_name"),
                item.get("stage_name"),
                item.get("status"),
                item.get("duration_seconds"),
                item.get("timestamp"),
            ):
                added += 1
        return added

    def success_rates(self, last_n: int) -> Dict[str, float]:
        if not isinstance(last_n, int) or last_n <= 0:
            return {}

        rates: Dict[str, float] = {}
        for pipeline, records in self._records_by_pipeline.items():
            recent = list(records)[-last_n:]
            completed = [r for r in recent if r.status in {"success", "failed"}]
            if not completed:
                rates[pipeline] = 0.0
                continue
            successes = sum(1 for r in completed if r.status == "success")
            rates[pipeline] = round((successes / len(completed)) * 100, 2)

        return dict(sorted(rates.items(), key=lambda item: item[0].lower()))

    def slowest_stage_per_pipeline(self) -> Dict[str, Dict[str, Any]]:
        result: Dict[str, Dict[str, Any]] = {}

        for pipeline, records in self._records_by_pipeline.items():
            if not records:
                continue

            stage_totals: Dict[str, List[float]] = defaultdict(list)
            for record in records:
                stage_totals[record.stage_name].append(record.duration_seconds)

            ranked = sorted(
                (
                    (
                        stage,
                        sum(durations) / len(durations),
                        max(durations),
                        len(durations),
                    )
                    for stage, durations in stage_totals.items()
                ),
                key=lambda item: (-item[1], -item[2], item[0].lower()),
            )

            if ranked:
                stage, avg_duration, max_duration, count = ranked[0]
                result[pipeline] = {
                    "stage_name": stage,
                    "average_duration_seconds": round(avg_duration, 2),
                    "max_duration_seconds": round(max_duration, 2),
                    "sample_count": count,
                }

        return dict(sorted(result.items(), key=lambda item: item[0].lower()))

    def failed_jobs(
        self,
        pipeline_name: Optional[str] = None,
        stage_name: Optional[str] = None,
        since: Optional[Union[str, datetime]] = None,
    ) -> List[BuildRecord]:
        parsed_since = self._parse_timestamp(since) if since is not None else None

        failed_filter = lambda r: (
            r.status == "failed"
            and (pipeline_name is None or r.pipeline_name == pipeline_name)
            and (stage_name is None or r.stage_name == stage_name)
            and (parsed_since is None or r.timestamp >= parsed_since)
        )

        filtered = list(filter(failed_filter, self._all_records))
        return sorted(filtered, key=lambda r: (r.timestamp, r.pipeline_name, r.stage_name))

    def get_pipeline_records(self, pipeline_name: str) -> List[BuildRecord]:
        if not isinstance(pipeline_name, str) or not pipeline_name.strip():
            return []
        return list(self._records_by_pipeline.get(pipeline_name.strip(), []))

    def summary(self, last_n: int) -> Dict[str, Any]:
        return {
            "success_rates": self.success_rates(last_n),
            "slowest_stages": self.slowest_stage_per_pipeline(),
            "failed_jobs_count": len(self.failed_jobs()),
            "total_records": len(self._all_records),
            "pipelines": sorted(self._records_by_pipeline.keys(), key=str.lower),
        }

    def _validate_and_build_record(
        self,
        pipeline_name: Any,
        stage_name: Any,
        status: Any,
        duration_seconds: Any,
        timestamp: Any,
    ) -> BuildRecord:
        if not isinstance(pipeline_name, str) or not pipeline_name.strip():
            raise ValueError("Invalid pipeline name")
        if not isinstance(stage_name, str) or not stage_name.strip():
            raise ValueError("Invalid stage name")
        if not isinstance(status, str):
            raise ValueError("Invalid status")

        normalized_status = status.strip().lower()
        if normalized_status not in self.VALID_STATUSES:
            raise ValueError("Unsupported status")

        try:
            duration = float(duration_seconds)
        except (TypeError, ValueError) as exc:
            raise ValueError("Invalid duration") from exc

        if duration < 0:
            raise ValueError("Duration cannot be negative")

        parsed_timestamp = self._parse_timestamp(timestamp)

        return BuildRecord(
            pipeline_name=pipeline_name.strip(),
            stage_name=stage_name.strip(),
            status=normalized_status,
            duration_seconds=duration,
            timestamp=parsed_timestamp,
        )

    @staticmethod
    def _parse_timestamp(value: Union[str, datetime, None]) -> datetime:
        if isinstance(value, datetime):
            return value
        if isinstance(value, str) and value.strip():
            text = value.strip()
            try:
                return datetime.fromisoformat(text.replace("Z", "+00:00"))
            except ValueError as exc:
                raise ValueError("Invalid timestamp format") from exc
        raise ValueError("Timestamp must be a datetime or ISO formatted string")


if __name__ == "__main__":
    monitor = PipelineMonitor(max_records_per_pipeline=100)

    sample_records = [
