import re
import json
from collections import Counter

STOPWORDS = {
    'the', 'a', 'an', 'and', 'or', 'but', 'if', 'then', 'than', 'so', 'to', 'of', 'in', 'on',
    'for', 'with', 'at', 'by', 'from', 'up', 'about', 'into', 'over', 'after', 'is', 'are',
    'was', 'were', 'be', 'been', 'being', 'it', 'its', 'as', 'that', 'this', 'these', 'those',
    'i', 'you', 'he', 'she', 'they', 'we', 'them', 'his', 'her', 'our', 'your', 'their', 'my'
}

POSITIVE = {'good', 'great', 'excellent', 'happy', 'love', 'effective', 'fast', 'clear', 'robust', 'useful'}
NEGATIVE = {'bad', 'poor', 'terrible', 'sad', 'hate', 'slow', 'bug', 'error', 'confusing', 'fragile'}


def tokenize(text):
    # Keep alphabetic tokens and internal apostrophes, e.g. don't, it's
    return re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?", text.lower())


def analyze_text(text):
    # Split sentences on ., !, ? while trimming whitespace
    sentences = [s.strip() for s in re.split(r'[.!?]+', text) if s.strip()]

    all_tokens = tokenize(text)
    filtered_tokens = [t for t in all_tokens if t not in STOPWORDS]
    freqs = Counter(filtered_tokens)

    sentiment_data = []
    for sentence in sentences:
        tokens = tokenize(sentence)
        pos_count = sum(1 for t in tokens if t in POSITIVE)
        neg_count = sum(1 for t in tokens if t in NEGATIVE)
        score = pos_count - neg_count
        sentiment_data.append((sentence, score))

    most_positive = max(sentiment_data, key=lambda x: x[1], default=(None, 0))
    most_negative = min(sentiment_data, key=lambda x: x[1], default=(None, 0))

    return {
        'total_sentences': len(sentences),
        'total_tokens': len(all_tokens),
        'vocabulary_size': len(set(all_tokens)),
        'top_terms': freqs.most_common(5),
        'most_positive_sentence': {
            'text': most_positive[0],
            'score': most_positive[1]
        },
        'most_negative_sentence': {
            'text': most_negative[0],
            'score': most_negative[1]
        }
    }


if __name__ == '__main__':
    sample_text = (
        "The new search feature is fast, clear, and incredibly useful. "
        "I love how effective the interface feels, although one confusing error still appears sometimes. "
        "Overall, the system is robust and good, but a slow response on mobile is bad. "
        "The documentation is excellent and makes the workflow great."
    )

    result = analyze_text(sample_text)
    print(json.dumps(result, indent=2))

from datetime import datetime
from typing import List, Optional

from pydantic import BaseModel, EmailStr, ValidationError, field_validator, model_validator


class Item(BaseModel):
    sku: str
    quantity: int
    price: float

    @field_validator('sku')
    @classmethod
    def sku_must_not_be_blank(cls, value: str) -> str:
        value = value.strip()
        if not value:
            raise ValueError('sku must not be empty')
        return value

    @field_validator('quantity')
    @classmethod
    def quantity_must_be_positive(cls, value: int) -> int:
        if value <= 0:
            raise ValueError('quantity must be greater than 0')
        return value

    @field_validator('price')
    @classmethod
    def price_must_be_positive(cls, value: float) -> float:
        if value <= 0:
            raise ValueError('price must be greater than 0')
        return value


class Order(BaseModel):
    order_id: int
    customer_email: EmailStr
    items: List[Item]
    created_at: datetime

    @field_validator('order_id')
    @classmethod
    def order_id_must_be_positive(cls, value: int) -> int:
        if value <= 0:
            raise ValueError('order_id must be a positive integer')
        return value

    @field_validator('items')
    @classmethod
    def items_must_not_be_empty(cls, value: List[Item]) -> List[Item]:
        if not value:
            raise ValueError('items must contain at least one item')
        return value

    @model_validator(mode='after')
    def total_must_be_at_least_minimum(self) -> 'Order':
        total = sum(item.quantity * item.price for item in self.items)
        if total < 10.0:
            raise ValueError('total order value must be at least 10.0')
        return self


def validate_order(payload: dict) -> dict:
    try:
        order = Order.model_validate(payload)
        return {
            'success': True,
            'data': order.model_dump(mode='json'),  # datetime serialized to ISO string
            'errors': []
        }
    except ValidationError as exc:
        errors = []
        for err in exc.errors():
            location = '.'.join(str(part) for part in err['loc'])
            errors.append(f"{location}: {err['msg']}")
        return {
            'success': False,
            'data': None,
            'errors': errors
        }


if __name__ == '__main__':
    sample_payload = {
        'order_id': 101,
        'customer_email': 'buyer@example.com',
        'items': [
            {'sku': 'ABC-123', 'quantity': 2, 'price': 6.5},
            {'sku': 'XYZ-999', 'quantity': 1, 'price': 3.0}
        ],
        'created_at': '2025-04-01T10:30:00'
    }

    result = validate_order(sample_payload)
    print(result)

from collections import defaultdict
from typing import Callable, Dict, List, Type


class Event:
    """Base type for all events."""
    pass


class EventBus:
    def __init__(self) -> None:
        # Maps event types to subscribed handlers.
        self._handlers: Dict[Type[Event], List[Callable[[Event], None]]] = defaultdict(list)

    def subscribe(self, event_type: Type[Event], handler: Callable[[Event], None]) -> None:
        """Register a handler for an event type without duplicates."""
        handlers = self._handlers[event_type]
        if handler not in handlers:
            handlers.append(handler)

    def unsubscribe(self, event_type: Type[Event], handler: Callable[[Event], None]) -> None:
        """Remove a handler if it exists."""
        handlers = self._handlers.get(event_type)
        if handlers and handler in handlers:
            handlers.remove(handler)
            if not handlers:
                del self._handlers[event_type]

    def publish(self, event: Event) -> None:
        """Dispatch an event to handlers of its class and parent Event classes."""
        seen = set()
        for cls in type(event).mro():
            if not issubclass(cls, Event):
                continue
            for handler in self._handlers.get(cls, []):
                # Avoid calling the same handler twice if subscribed on multiple levels.
                if handler not in seen:
                    handler(event)
                    seen.add(handler)


# Usage example
class UserEvent(Event):
    def __init__(self, username: str) -> None:
        self.username = username


class UserCreated(UserEvent):
    pass


class UserDeleted(UserEvent):
    pass


def log_any_user_event(event: UserEvent) -> None:
    print(f"[audit] user event for {event.username}: {type(event).__name__}")


def welcome_user(event: UserCreated) -> None:
    print(f"[welcome] Hello, {event.username}!")


bus = EventBus()
bus.subscribe(UserEvent, log_any_user_event)
bus.subscribe(UserCreated, welcome_user)
bus.subscribe(UserCreated, welcome_user)  # Duplicate ignored

bus.publish(UserCreated("alice"))
bus.publish(UserDeleted("bob"))

bus.unsubscribe(UserCreated, welcome_user)
bus.publish(UserCreated("charlie"))

import heapq
from collections import defaultdict


class EventLoop:
    def __init__(self):
        self._handlers = defaultdict(list)
        self._queue = []  # (time, insertion_order, event_name, payload)
        self._time = 0
        self._counter = 0

    def on(self, event, handler):
        """Register a handler for an event name."""
        self._handlers[event].append(handler)

    def emit(self, event, **data):
        """Queue an event to run at the current time."""
        self.call_later(0, event, **data)

    def call_later(self, delay, event, **data):
        """Schedule an event after a non-negative delay."""
        if delay < 0:
            raise ValueError("delay must be non-negative")
        self._counter += 1
        scheduled_time = self._time + delay
        heapq.heappush(self._queue, (scheduled_time, self._counter, event, data))

    def run(self):
        """Process events until the queue is empty."""
        while self._queue:
            scheduled_time, _, event, data = heapq.heappop(self._queue)
            self._time = scheduled_time
            for handler in list(self._handlers[event]):
                handler(self, **data)


