import os


def _parse_bool(value):
    """Convert common string representations to bool."""
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in {"1", "true", "yes", "on"}:
        return True
    if text in {"0", "false", "no", "off"}:
        return False
    raise ValueError(f"Invalid boolean value: {value!r}")



def _convert_value(raw_value, default):
    """Convert raw string input to the type implied by the default."""
    if default is None or isinstance(default, str):
        return raw_value
    if isinstance(default, bool):
        return _parse_bool(raw_value)
    if isinstance(default, int) and not isinstance(default, bool):
        return int(raw_value)
    if isinstance(default, list):
        return [item.strip() for item in str(raw_value).split(",") if item.strip()]
    return raw_value



def load_config(required_keys, optional_defaults=None, env=None):
    """
    Load configuration from environment variables.

    - required_keys: iterable of required environment variable names
    - optional_defaults: mapping of optional keys to default values
    - env: optional environment mapping, defaults to os.environ
    """
    env = os.environ if env is None else env
    optional_defaults = optional_defaults or {}

    missing = [key for key in required_keys if not str(env.get(key, "")).strip()]
    if missing:
        raise ValueError(f"Missing required environment variables: {', '.join(sorted(missing))}")

    config = {}

    # Load required values as strings.
    for key in required_keys:
        config[key] = env[key]

    # Load optional values, applying defaults and type conversions.
    for key, default in optional_defaults.items():
        raw_value = env.get(key)
        if raw_value is None or str(raw_value).strip() == "":
            config[key] = default
        else:
            config[key] = _convert_value(raw_value, default)

    return config



def masked_config(config, secret_keywords=None):
    """Return a copy of config with sensitive values masked."""
    secret_keywords = secret_keywords or ["SECRET", "TOKEN", "KEY", "PASSWORD"]
    masked = {}

    for key, value in config.items():
        if any(word in key.upper() for word in secret_keywords):
            text = str(value)
            masked[key] = "***" if len(text) <= 4 else text[:2] + "***" + text[-2:]
        else:
            masked[key] = value

    return masked

import re


def render_template(template, context):
    """Replace {{ key }} placeholders using values from context.

    Supports nested lookup with dot notation, e.g. {{ user.name }}.
    Missing keys are left unchanged.
    """
    pattern = re.compile(r"\{\{\s*([a-zA-Z_][a-zA-Z0-9_\.]*)\s*\}\}")

    def resolve(path, data):
        value = data
        for part in path.split('.'):
            if isinstance(value, dict) and part in value:
                value = value[part]
            else:
                raise KeyError(path)
        return value

    def replacer(match):
        key = match.group(1)
        try:
            return str(resolve(key, context))
        except KeyError:
            return match.group(0)

    return pattern.sub(replacer, template)


def main():
    template = (
        "Hello {{ user.name }},\n\n"
        "Your order #{{ order.id }} has been shipped to {{ user.address.city }}.\n"
        "Tracking code: {{ order.tracking }}\n"
        "Support contact: {{ support.email }}\n"
        "Unknown field stays as-is: {{ order.missing }}\n"
    )

    context = {
        "user": {
            "name": "Ava",
            "email": "ava@example.com",
            "address": {"city": "Seattle"}
        },
        "order": {
            "id": 1042,
            "tracking": "ZX81-TRACK"
        },
        "support": {
            "email": "support@shop.com"
        }
    }

    rendered = render_template(template, context)
    print(rendered)


