import asyncio


async def fetch(service_name: str, delay: float, fail: bool = False) -> dict:
    """Simulate an async service call."""
    await asyncio.sleep(delay)
    if fail:
        raise ValueError(f"{service_name} failed")
    return {"service": service_name, "status": "ok"}


async def gather_results() -> dict:
    """Run service calls concurrently and summarize outcomes."""
    tasks = [
        fetch("users", 1.0),
        fetch("payments", 0.5, fail=True),
        fetch("notifications", 0.8),
    ]

    # return_exceptions=True keeps all tasks running even if one fails
    results = await asyncio.gather(*tasks, return_exceptions=True)

    summary = {"successes": [], "errors": []}
    for result in results:
        if isinstance(result, Exception):
            summary["errors"].append({
                "type": type(result).__name__,
                "message": str(result),
            })
        else:
            summary["successes"].append(result)

    return summary


def main() -> None:
    summary = asyncio.run(gather_results())
    print(summary)


