def load_scores(file_path):
    """Load integer scores from a file, reporting invalid lines clearly."""
    scores = []
    invalid_lines = []

    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            for line_number, raw_line in enumerate(file, start=1):
                line = raw_line.strip()

                # Ignore empty lines
                if not line:
                    continue

                try:
                    scores.append(int(line))
                except ValueError:
                    invalid_lines.append((line_number, line))
    except FileNotFoundError as exc:
        raise FileNotFoundError(f"Score file not found: {file_path}") from exc

    if invalid_lines:
        details = ", ".join(
            f"line {line_number}: '{content}'"
            for line_number, content in invalid_lines
        )
        raise ValueError(f"Invalid score entries found: {details}")

    return scores


