from typing import List, Dict, Any


def chunked(records: List[Dict[str, Any]], batch_size: int):
    """Yield successive batches from the input records."""
    for i in range(0, len(records), batch_size):
        yield records[i:i + batch_size]


def validate(record: Dict[str, Any]) -> None:
    """Raise ValueError if the record is invalid."""
    payload = record.get("payload")
    if not isinstance(payload, str) or not payload.strip():
        raise ValueError("payload must be a non-empty string")


def process_record(record: Dict[str, Any], max_retries: int) -> Dict[str, Any]:
    """Process one record with retry handling for transient failures."""
    attempts = 0

    while attempts <= max_retries:
        attempts += 1
        try:
            validate(record)

            # Simulate transient failures until the final allowed attempt.
            if record.get("should_fail") and attempts <= max_retries:
                raise RuntimeError("transient processing error")

            return {
                "id": record.get("id"),
                "status": "success",
                "attempts": attempts,
                "output": record["payload"].upper(),
            }
        except ValueError:
            # Validation errors are permanent; do not retry.
            return {
                "id": record.get("id"),
                "status": "failed",
                "attempts": attempts,
                "output": None,
            }
        except RuntimeError:
            if attempts > max_retries:
                return {
                    "id": record.get("id"),
                    "status": "failed",
                    "attempts": attempts,
                    "output": None,
                }

    # Defensive fallback; should not be reached.
    return {
        "id": record.get("id"),
        "status": "failed",
        "attempts": attempts,
        "output": None,
    }


def run_pipeline(records: List[Dict[str, Any]], batch_size: int = 4, max_retries: int = 2) -> Dict[str, Any]:
    """Run the batch processing pipeline and return a summary."""
    results = []

    for batch in chunked(records, batch_size):
        for record in batch:
            results.append(process_record(record, max_retries))

    processed = sum(1 for item in results if item["status"] == "success")
    failed = len(results) - processed

    return {
        "processed": processed,
        "failed": failed,
        "batches": (len(records) + batch_size - 1) // batch_size,
        "results": results,
    }


if __name__ == "__main__":
    sample_records = [
        {"id": 1, "payload": "alpha"},
        {"id": 2, "payload": "beta", "should_fail": True},
        {"id": 3, "payload": ""},
        {"id": 4, "payload": "delta"},
        {"id": 5, "payload": "echo", "should_fail": True},
    ]

    summary = run_pipeline(sample_records, batch_size=2, max_retries=2)
    print(summary)
}

from typing import Dict, List
import re

from pydantic import BaseModel, Field, ValidationError, field_validator, model_validator


class DeploymentConfig(BaseModel):
    service_name: str
    replicas: int = Field(ge=1, le=20)
    image: str
    env: Dict[str, str]
    ports: List[int]

    @field_validator("service_name")
    @classmethod
    def validate_service_name(cls, value: str) -> str:
        if not re.fullmatch(r"[a-z0-9-]+", value):
            raise ValueError("service_name must contain only lowercase letters, numbers, and hyphens")
        return value

    @field_validator("image")
    @classmethod
    def validate_image(cls, value: str) -> str:
        if not re.fullmatch(r"[\w.-]+/[\w.-]+:[\w.-]+", value):
            raise ValueError("image must match the format 'repo/name:tag'")
        return value

    @field_validator("env")
    @classmethod
    def validate_env(cls, value: Dict[str, str]) -> Dict[str, str]:
        if not value:
            return value
        for key, val in value.items():
            if not re.fullmatch(r"[A-Z_][A-Z0-9_]*", key):
                raise ValueError(f"invalid env key: {key}")
            if not isinstance(val, str) or not val.strip():
                raise ValueError(f"env value for {key} must be a non-empty string")
        return value

    @field_validator("ports")
    @classmethod
    def validate_ports(cls, value: List[int]) -> List[int]:
        if not value:
            raise ValueError("ports must be a non-empty list")
        if len(set(value)) != len(value):
            raise ValueError("ports must contain unique values")
        for port in value:
            if not 1 <= port <= 65535:
                raise ValueError(f"invalid port: {port}")
        return value

    @model_validator(mode="after")
    def validate_cross_fields(self) -> "DeploymentConfig":
        if self.replicas > 10 and self.env.get("SCALE_MODE") != "high":
            raise ValueError("env must include SCALE_MODE='high' when replicas > 10")
        if 80 in self.ports and not self.service_name.startswith("web-"):
            raise ValueError("service_name must start with 'web-' when port 80 is exposed")
        return self


def validate_config(data: dict) -> dict:
    try:
        config = DeploymentConfig.model_validate(data)
        return config.model_dump()
    except ValidationError as exc:
        messages = []
        for err in exc.errors():
            location = ".".join(str(part) for part in err["loc"]) or "model"
            messages.append(f"{location}: {err['msg']}")
        raise ValueError("; ".join(messages)) from None


