    print(validate_config(sample))

from typing import Iterable, Iterator, Callable, TypeVar, Generic, List, Any, Dict

T = TypeVar('T')
U = TypeVar('U')


class LazyLogStream(Generic[T]):
    """A small lazy pipeline wrapper around any iterable."""

    def __init__(self, source: Iterable[T]):
        self._source = source

    def __iter__(self) -> Iterator[T]:
        # Yield from the wrapped source only when iteration begins.
        yield from self._source

    def filter(self, predicate: Callable[[T], bool]) -> 'LazyLogStream[T]':
        def generator() -> Iterator[T]:
            for item in self:
                if predicate(item):
                    yield item
        return LazyLogStream(generator())

    def map(self, transform: Callable[[T], U]) -> 'LazyLogStream[U]':
        def generator() -> Iterator[U]:
            for item in self:
                yield transform(item)
        return LazyLogStream(generator())

    def take(self, n: int) -> 'LazyLogStream[T]':
        def generator() -> Iterator[T]:
            if n <= 0:
                return
            count = 0
            for item in self:
                yield item
                count += 1
                if count >= n:
                    break
        return LazyLogStream(generator())

    def collect(self) -> List[T]:
        return list(self)


def top_slow_error_services(logs: Iterable[Dict[str, Any]], n: int) -> List[str]:
    def is_error_with_latency(log: Dict[str, Any]) -> bool:
        latency = log.get('latency')
        return (
            log.get('level') == 'ERROR'
            and isinstance(latency, (int, float))
        )

    return (
        LazyLogStream(logs)
        .filter(is_error_with_latency)
        .map(lambda log: log.get('service', 'unknown'))
        .take(n)
        .collect()
    )


