class Document:
    def __init__(self):
        self.content = ""

    def add_text(self, text):
        self.content += text

    def delete_last(self):
        if self.content:
            self.content = self.content[:-1]


class Command:
    def execute(self):
        raise NotImplementedError("Subclasses must implement execute()")


class AddTextCommand(Command):
    def __init__(self, document, text):
        self.document = document
        self.text = text

    def execute(self):
        self.document.add_text(self.text)


class DeleteLastCharacterCommand(Command):
    def __init__(self, document):
        self.document = document

    def execute(self):
        self.document.delete_last()


class CommandInvoker:
    def __init__(self):
        self.commands = []

    def add_command(self, command):
        self.commands.append(command)

    def run(self):
        for command in self.commands:
            command.execute()


# Create receiver
my_document = Document()

# Create commands
command1 = AddTextCommand(my_document, "Hello")
command2 = AddTextCommand(my_document, " World")
command3 = DeleteLastCharacterCommand(my_document)
command4 = AddTextCommand(my_document, "!")

# Create invoker and add commands
invoker = CommandInvoker()
invoker.add_command(command1)
invoker.add_command(command2)
invoker.add_command(command3)
invoker.add_command(command4)

# Execute all commands
invoker.run()

# Show final result
print("Final document content:", my_document.content)

from __future__ import annotations

from datetime import datetime, timezone
from uuid import UUID

ALLOWED_SOURCES = {"web", "mobile", "api"}
PRIMITIVE_TYPES = (str, int, float, bool, type(None))


def _require_dict(value, field_name: str) -> dict:
    if not isinstance(value, dict):
        raise ValueError(f"{field_name} must be a dictionary")
    return value


def _validate_uuid(value: object, field_name: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field_name} must be a non-empty UUID string")
    try:
        return str(UUID(value))
    except Exception:
        raise ValueError(f"{field_name} must be a valid UUID")


def _validate_timestamp(value: object, field_name: str) -> datetime:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field_name} must be a non-empty ISO 8601 string")
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        raise ValueError(f"{field_name} must be a valid ISO 8601 datetime")
    if dt.tzinfo is None:
        raise ValueError(f"{field_name} must include timezone information")
    return dt.astimezone(timezone.utc)


def _validate_user(user: object) -> dict:
    user = _require_dict(user, "user")
    if set(user) != {"id", "email"}:
        raise ValueError("user must contain exactly 'id' and 'email'")

    user_id = user.get("id")
    if not isinstance(user_id, int) or isinstance(user_id, bool) or user_id <= 0:
        raise ValueError("user.id must be an integer greater than 0")

    email = user.get("email")
    if not isinstance(email, str) or not email.strip() or "@" not in email:
        raise ValueError("user.email must be a non-empty email-like string")

    return {"id": user_id, "email": email.strip()}


def _validate_metadata(metadata: object) -> dict:
    metadata = _require_dict(metadata, "metadata")
    normalized = {}
    for key, value in metadata.items():
        if not isinstance(key, str):
            raise ValueError("metadata keys must be strings")
        if not isinstance(value, PRIMITIVE_TYPES):
            raise ValueError(f"metadata['{key}'] must be a primitive value")
        normalized[key] = value
    return normalized


def validate_event(payload: object) -> dict:
    payload = _require_dict(payload, "payload")

    allowed_keys = {"event_id", "timestamp", "source", "user", "metadata"}
    required_keys = {"event_id", "timestamp", "source", "user"}

    missing = required_keys - payload.keys()
    if missing:
        raise ValueError(f"missing required field(s): {', '.join(sorted(missing))}")

    extra = payload.keys() - allowed_keys
    if extra:
        raise ValueError(f"unexpected field(s): {', '.join(sorted(extra))}")

    source = payload.get("source")
    if source not in ALLOWED_SOURCES:
        raise ValueError("source must be one of: web, mobile, api")

    result = {
        "event_id": _validate_uuid(payload.get("event_id"), "event_id"),
        "timestamp": _validate_timestamp(payload.get("timestamp"), "timestamp"),
        "source": source,
        "user": _validate_user(payload.get("user")),
    }

    if "metadata" in payload:
        result["metadata"] = _validate_metadata(payload["metadata"])

    return result

from datetime import datetime
from zoneinfo import ZoneInfo


def _parse_interval(item, tz):
    """Parse and normalize a single interval into the target timezone."""
    try:
        start = datetime.fromisoformat(item['start'])
        end = datetime.fromisoformat(item['end'])
    except (KeyError, TypeError, ValueError):
        return None

    # Require timezone-aware datetimes for reliable conversion.
    if start.tzinfo is None or end.tzinfo is None:
        return None

    start = start.astimezone(tz)
    end = end.astimezone(tz)

    # Ignore invalid or zero-length intervals.
    if end <= start:
        return None

    return start, end


def find_overlaps(events_a, events_b, tz_name):
    """Return merged overlaps between two schedules in the target timezone."""
    tz = ZoneInfo(tz_name)

    intervals_a = []
    intervals_b = []

    for item in events_a:
        parsed = _parse_interval(item, tz)
        if parsed:
            intervals_a.append(parsed)

    for item in events_b:
        parsed = _parse_interval(item, tz)
        if parsed:
            intervals_b.append(parsed)

    overlaps = []
    for a_start, a_end in intervals_a:
        for b_start, b_end in intervals_b:
            start = max(a_start, b_start)
            end = min(a_end, b_end)
            if start < end:
                overlaps.append((start, end))

    if not overlaps:
        return []

    # Merge touching or overlapping overlap intervals.
    overlaps.sort(key=lambda x: x[0])
    merged = [overlaps[0]]

    for start, end in overlaps[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    result = []
    for start, end in merged:
        minutes = int((end - start).total_seconds() // 60)
        result.append({
            'start': start.isoformat(),
            'end': end.isoformat(),
            'minutes': minutes,
        })

    return result


if __name__ == '__main__':
    events_a = [
        {'start': '2025-03-10T09:00:00-04:00', 'end': '2025-03-10T11:30:00-04:00'},
        {'start': '2025-03-10T13:00:00+00:00', 'end': '2025-03-10T15:00:00+00:00'},
    ]
    events_b = [
        {'start': '2025-03-10T14:00:00+01:00', 'end': '2025-03-10T16:30:00+01:00'},
        {'start': '2025-03-10T10:30:00-04:00', 'end': '2025-03-10T12:00:00-04:00'},
    ]

    print(find_overlaps(events_a, events_b, 'America/New_York'))

class Book:
    def __init__(self, title, author):
        self.title = title
        self.author = author
        self.available = True


class Library:
    def __init__(self):
        self.books = []

    def add_book(self, book):
        self.books.append(book)

    def borrow_book(self, title):
        book = self._find_book(title)
        if book is None or not book.available:
            return False
        book.available = False
        return True

    def return_book(self, title):
        book = self._find_book(title)
        if book is None or book.available:
            return False
        book.available = True
        return True

    def list_available_books(self):
        return [book.title for book in self.books if book.available]

    def _find_book(self, title):
        # Helper method to locate a book by title
        for book in self.books:
            if book.title == title:
                return book
        return None


# Example usage
if __name__ == "__main__":
    library = Library()
    library.add_book(Book("1984", "George Orwell"))
    library.add_book(Book("Dune", "Frank Herbert"))

    print(library.list_available_books())  # ['1984', 'Dune']
    print(library.borrow_book("1984"))    # True
    print(library.borrow_book("1984"))    # False
    print(library.list_available_books())  # ['Dune']
    print(library.return_book("1984"))    # True
    print(library.list_available_books())  # ['1984', 'Dune']

import json
from pathlib import Path


def load_config(path):
    """Load and validate a JSON configuration file."""
    try:
        with open(path, 'r', encoding='utf-8') as file:
            data = json.load(file)
    except FileNotFoundError as exc:
        raise FileNotFoundError(f'Configuration file not found: {path}') from exc
    except json.JSONDecodeError as exc:
        raise ValueError(f'Invalid JSON in configuration file: {path}') from exc
    except OSError as exc:
        raise ValueError(f'Could not read configuration file: {path}') from exc

    if not isinstance(data, dict):
        raise ValueError('Configuration must be a JSON object')

    required_keys = ('host', 'port', 'debug')
    missing = [key for key in required_keys if key not in data]
    if missing:
        raise ValueError(f'Missing required configuration keys: {", ".join(missing)}')

    host = data['host']
    port = data['port']
    debug = data['debug']

    if not isinstance(host, str) or not host.strip():
        raise ValueError('"host" must be a non-empty string')
    if not isinstance(port, int) or isinstance(port, bool) or not (1 <= port <= 65535):
        raise ValueError('"port" must be an integer between 1 and 65535')
    if not isinstance(debug, bool):
        raise ValueError('"debug" must be a boolean')

    return {
        'host': host.strip(),
        'port': port,
        'debug': debug,
    }


if __name__ == '__main__':
    config_path = Path('config.json')

    try:
        config = load_config(config_path)
    except (FileNotFoundError, ValueError) as error:
        print(f'Error: {error}')
    else:
        print('Loaded config:', config)

from itertools import combinations


def hamming_distance(a: bytes, b: bytes) -> int:
    """Return the number of differing bits between two byte strings."""
    if len(a) != len(b):
        raise ValueError("Inputs must have equal length")
    return sum((x ^ y).bit_count() for x, y in zip(a, b))


def english_score(data: bytes) -> float:
    """Score text by rough English character frequency and printability."""
    freq = {
        'e': 12.7, 't': 9.1, 'a': 8.2, 'o': 7.5, 'i': 7.0, 'n': 6.7,
        ' ': 13.0, 's': 6.3, 'h': 6.1, 'r': 6.0, 'd': 4.3, 'l': 4.0,
        'u': 2.8
    }
    score = 0.0
    for b in data:
        ch = chr(b).lower()
        if ch in freq:
            score += freq[ch]
        elif 32 <= b <= 126 or b in (9, 10, 13):
            score += 0.2
        else:
            score -= 5.0
    return score


def single_byte_xor_crack(block: bytes) -> tuple[int, bytes, float]:
    """Find the best single-byte XOR key for a block."""
    best_key = 0
    best_plain = b''
    best_score = float('-inf')
    for key in range(256):
        plain = bytes(b ^ key for b in block)
        score = english_score(plain)
        if score > best_score:
            best_key, best_plain, best_score = key, plain, score
    return best_key, best_plain, best_score


def estimate_keysize(data: bytes, max_keysize: int) -> int:
    """Estimate key size using normalized Hamming distance."""
    candidates = []
    for keysize in range(2, min(max_keysize, len(data) // 2) + 1):
        blocks = [data[i:i + keysize] for i in range(0, keysize * 6, keysize)]
        blocks = [b for b in blocks if len(b) == keysize]
        if len(blocks) < 4:
            continue
        distances = []
        for x, y in combinations(blocks[:4], 2):
            distances.append(hamming_distance(x, y) / keysize)
        candidates.append((sum(distances) / len(distances), keysize))
    if not candidates:
        raise ValueError("Ciphertext too short to estimate key size")
    return min(candidates)[1]


def break_repeating_xor(cipher_hex: str, max_keysize: int = 40) -> dict:
    """Recover key and plaintext from repeating-key XOR encrypted hex ciphertext."""
    data = bytes.fromhex(cipher_hex)
    keysize = estimate_keysize(data, max_keysize)

    # Group bytes encrypted by the same key byte.
    transposed = [data[i::keysize] for i in range(keysize)]

    key_bytes = bytearray()
    for block in transposed:
        key_byte, _, _ = single_byte_xor_crack(block)
        key_bytes.append(key_byte)

    plaintext = bytes(data[i] ^ key_bytes[i % keysize] for i in range(len(data)))
    return {
        'key': key_bytes.decode('latin1'),
        'plaintext': plaintext.decode('latin1'),
        'keysize': keysize,
    }


if __name__ == '__main__':
    # Example usage with a known repeating-key XOR sample.
    sample_plain = (
        b"Cryptography is the practice and study of techniques for secure communication."
    )
    sample_key = b"ICE"
    sample_cipher = bytes(
        sample_plain[i] ^ sample_key[i % len(sample_key)]
        for i in range(len(sample_plain))
    ).hex()

    result = break_repeating_xor(sample_cipher)
    print(result)

from collections import deque


def error_messages(lines):
    """Lazily yield only the message part of ERROR log lines."""
    prefix = "ERROR: "
    for line in lines:
        if line.startswith(prefix):
            yield line[len(prefix):]


def windowed_unique_errors(lines, window_size):
    """
    Lazily yield (start_index, unique_errors) for each full sliding window.

    unique_errors preserves the order of first appearance of distinct ERROR
    messages inside the current window.
    """
    if window_size <= 0:
        raise ValueError("window_size must be positive")

    window = deque()

    for i, line in enumerate(lines):
        window.append(line)

        # Keep only the last `window_size` lines.
        if len(window) > window_size:
            window.popleft()

        # Once the window is full, compute distinct errors for it.
        if len(window) == window_size:
            seen = set()
            unique = []
            for msg in error_messages(window):
                if msg not in seen:
                    seen.add(msg)
                    unique.append(msg)

            yield (i - window_size + 1, unique)


