        print(start, errors)

from collections import defaultdict
from typing import Callable, Dict, List, Type


class Event:
    """Base class for all events."""
    pass


class UserCreatedEvent(Event):
    def __init__(self, username: str):
        self.username = username


class AdminCreatedEvent(UserCreatedEvent):
    def __init__(self, username: str, level: int):
        super().__init__(username)
        self.level = level


class OrderPlacedEvent(Event):
    def __init__(self, order_id: int):
        self.order_id = order_id


class EventDispatcher:
    def __init__(self):
        # Maps event classes to handlers interested in that class.
        self._subscribers: Dict[Type[Event], List[Callable[[Event], None]]] = defaultdict(list)

    def subscribe(self, event_type: Type[Event], handler: Callable[[Event], None]) -> None:
        """Register a handler once for a specific event type."""
        handlers = self._subscribers[event_type]
        if handler not in handlers:
            handlers.append(handler)

    def unsubscribe(self, event_type: Type[Event], handler: Callable[[Event], None]) -> None:
        """Remove a handler if it exists."""
        handlers = self._subscribers.get(event_type, [])
        if handler in handlers:
            handlers.remove(handler)

    def dispatch(self, event: Event) -> None:
        """Invoke handlers for the event's class and its base Event classes."""
        seen = set()
        for cls in type(event).mro():
            if not issubclass(cls, Event):
                continue
            for handler in self._subscribers.get(cls, []):
                # Avoid calling the same handler twice if subscribed via multiple classes.
                if handler not in seen:
                    handler(event)
                    seen.add(handler)


# Usage example
if __name__ == "__main__":
    dispatcher = EventDispatcher()

    def log_any_user_created(event: UserCreatedEvent) -> None:
        print(f"User created: {event.username}")

    def log_admin(event: AdminCreatedEvent) -> None:
        print(f"Admin level {event.level}: {event.username}")

    def log_order(event: OrderPlacedEvent) -> None:
        print(f"Order placed: #{event.order_id}")

    dispatcher.subscribe(UserCreatedEvent, log_any_user_created)
    dispatcher.subscribe(AdminCreatedEvent, log_admin)
    dispatcher.subscribe(OrderPlacedEvent, log_order)
    dispatcher.subscribe(UserCreatedEvent, log_any_user_created)  # Duplicate ignored

    dispatcher.dispatch(AdminCreatedEvent("alice", 3))  # Calls both user and admin handlers
    dispatcher.dispatch(OrderPlacedEvent(101))

import requests

API_URL = 'https://jsonplaceholder.typicode.com/posts'


def fetch_posts():
    """Fetch posts from the API and return them as JSON."""
    try:
        response = requests.get(API_URL, timeout=5)
        response.raise_for_status()  # Raise an error for bad HTTP status codes
        return response.json()
    except requests.exceptions.HTTPError:
        print(f'Error: API returned status code {response.status_code}')
    except requests.exceptions.RequestException as e:
        print(f'Network error: {e}')
    return None


