import time
from enum import Enum


class CircuitOpenError(Exception):
    pass


class State(Enum):
    CLOSED = "closed"
    OPEN = "open"
    HALF_OPEN = "half_open"


class CircuitBreaker:
    def __init__(self, failure_threshold=3, recovery_timeout=2.0):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.state = State.CLOSED
        self.failure_count = 0
        self.opened_at = None

    def before_call(self):
        if self.state == State.OPEN:
            if time.monotonic() - self.opened_at >= self.recovery_timeout:
                self.state = State.HALF_OPEN
            else:
                raise CircuitOpenError("Circuit is open")

    def record_success(self):
        self.failure_count = 0
        self.state = State.CLOSED
        self.opened_at = None

    def record_failure(self):
        if self.state == State.HALF_OPEN:
            self.state = State.OPEN
            self.opened_at = time.monotonic()
            return

        self.failure_count += 1
        if self.failure_count >= self.failure_threshold:
            self.state = State.OPEN
            self.opened_at = time.monotonic()


def retry_request(func, breaker, retries=5, base_delay=0.2, exceptions=(Exception,)):
    last_error = None

    for attempt in range(retries):
        breaker.before_call()
        try:
            result = func()
            breaker.record_success()
            return result
        except exceptions as exc:
            last_error = exc
            breaker.record_failure()
            if attempt == retries - 1:
                break
            time.sleep(base_delay * (2 ** attempt))

    raise last_error


if __name__ == "__main__":
    outcomes = iter([False, False, False, True, False, True])

    def flaky_operation():
        ok = next(outcomes)
        if not ok:
            raise ValueError("temporary failure")
        return "success"

    breaker = CircuitBreaker(failure_threshold=3, recovery_timeout=1.0)

    for i in range(6):
        try:
            value = retry_request(flaky_operation, breaker, retries=2, base_delay=0.1, exceptions=(ValueError,))
            print(f"Call {i}: {value} (state={breaker.state.value})")
        except Exception as e:
            print(f"Call {i}: {type(e).__name__}: {e} (state={breaker.state.value})")
        time.sleep(0.4)

class AIDiagnosticTool:
    def __init__(self, name, age, temperature, heart_rate, symptoms=None):
        self.name = str(name)
        self.age = int(age)
        self.temperature = float(temperature)
        self.heart_rate = int(heart_rate)
        self.symptoms = symptoms if symptoms is not None else []

    def add_symptom(self, symptom):
        symptom_text = str(symptom).strip()
        if symptom_text:
            self.symptoms.append(symptom_text)

    def display_patient_data(self):
        print("=== Patient Information ===")
        print(f"Name: {self.name}")
        print(f"Age: {self.age}")
        print(f"Temperature: {self.temperature:.1f}Â°C")
        print(f"Heart Rate: {self.heart_rate} bpm")
        print("Symptoms:")
        if self.symptoms:
            for symptom in self.symptoms:
                print(f"- {symptom}")
        else:
            print("- None reported")

    def generate_diagnostic_suggestion(self):
        suggestions = []
        urgent_symptoms = ["chest pain", "shortness of breath"]

        if self.temperature > 38.0:
            suggestions.append("Possible Fever")

        lower_symptoms = [symptom.lower() for symptom in self.symptoms]
        if any(symptom in lower_symptoms for symptom in urgent_symptoms):
            suggestions.append("Needs Further Checkup")

        if self.heart_rate > 100:
            suggestions.append("Elevated Heart Rate")

        if not suggestions:
            suggestions.append("No immediate concerns based on basic checks")

        print("\n=== Diagnostic Suggestion ===")
        for suggestion in suggestions:
            print(f"- {suggestion}")


if __name__ == "__main__":
    patient = AIDiagnosticTool(
        name="John Doe",
        age=30,
        temperature=38.5,
        heart_rate=105,
        symptoms=["cough", "headache"]
    )

    patient.add_symptom("chest pain")
    patient.display_patient_data()
    patient.generate_diagnostic_suggestion()

#!/usr/bin/env python3
from __future__ import annotations

import argparse
import json
import math
import sys
from dataclasses import dataclass, field, asdict
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np
import pandas as pd

try:
    import yaml  # type: ignore
except ImportError:
    yaml = None


class DriftToolError(Exception):
    pass


class ConfigError(DriftToolError):
    pass


class SchemaValidationError(DriftToolError):
    pass


class DataLoadError(DriftToolError):
    pass


@dataclass
class Thresholds:
    psi: float = 0.2
    js_divergence: float = 0.1
    missing_rate_change: float = 0.05
    feature_alert_count: int = 1


@dataclass
class Settings:
    numeric_bins: int = 10
    categorical_top_k: int = 50
    epsilon: float = 1e-12
    sample_rows: Optional[int] = None
    strict_schema: bool = True


@dataclass
class Config:
    thresholds: Thresholds = field(default_factory=Thresholds)
    settings: Settings = field(default_factory=Settings)


@dataclass
class FeatureDriftResult:
    feature: str
    feature_type: str
    psi: Optional[float]
    js_divergence: Optional[float]
    missing_rate_baseline: float
    missing_rate_recent: float
    missing_rate_change: float
    alerts: List[str]
    details: Dict[str, Any] = field(default_factory=dict)


@dataclass
class DriftSummary:
    total_features: int
    drifted_features: int
    features_exceeding_thresholds: List[str]
    overall_status: str


def load_config(config_path: Path) -> Config:
    if not config_path.exists():
        raise ConfigError(f"Configuration file not found: {config_path}")

    suffix = config_path.suffix.lower()
    try:
        with config_path.open("r", encoding="utf-8") as f:
            if suffix == ".json":
                raw = json.load(f)
            elif suffix in {".yaml", ".yml"}:
                if yaml is None:
                    raise ConfigError("PyYAML is required to load YAML configuration files.")
                raw = yaml.safe_load(f)
            else:
                raise ConfigError("Unsupported config format. Use JSON or YAML.")
    except (OSError, json.JSONDecodeError) as exc:
        raise ConfigError(f"Failed to load configuration: {exc}") from exc

    if raw is None:
        raw = {}

    thresholds_raw = raw.get("thresholds", {})
    settings_raw = raw.get("settings", {})

    thresholds = Thresholds(
        psi=float(thresholds_raw.get("psi", 0.2)),
        js_divergence=float(thresholds_raw.get("js_divergence", 0.1)),
        missing_rate_change=float(thresholds_raw.get("missing_rate_change", 0.05)),
        feature_alert_count=int(thresholds_raw.get("feature_alert_count", 1)),
    )
    settings = Settings(
        numeric_bins=int(settings_raw.get("numeric_bins", 10)),
        categorical_top_k=int(settings_raw.get("categorical_top_k", 50)),
        epsilon=float(settings_raw.get("epsilon", 1e-12)),
        sample_rows=(
            int(settings_raw["sample_rows"])
            if settings_raw.get("sample_rows") is not None
            else None
        ),
        strict_schema=bool(settings_raw.get("strict_schema", True)),
    )

    if thresholds.psi < 0 or thresholds.js_divergence < 0 or thresholds.missing_rate_change < 0:
        raise ConfigError("Threshold values must be non-negative.")
    if settings.numeric_bins < 2:
        raise ConfigError("settings.numeric_bins must be at least 2.")
    if settings.categorical_top_k < 1:
        raise ConfigError("settings.categorical_top_k must be at least 1.")

    return Config(thresholds=thresholds, settings=settings)


def load_dataset(path: Path, sample_rows: Optional[int] = None) -> pd.DataFrame:
    if not path.exists():
        raise DataLoadError(f"Dataset file not found: {path}")

    suffix = path.suffix.lower()
    try:
        with path.open("rb") as f:
            if suffix == ".csv":
                df = pd.read_csv(f, nrows=sample_rows)
            elif suffix in {".parquet", ".pq"}:
                df = pd.read_parquet(f)
                if sample_rows is not None:
                    df = df.head(sample_rows)
            elif suffix == ".json":
                df = pd.read_json(f)
                if sample_rows is not None:
                    df = df.head(sample_rows)
            else:
                raise DataLoadError("Unsupported dataset format. Use CSV, Parquet, or JSON.")
    except Exception as exc:
        raise DataLoadError(f"Failed to load dataset '{path}': {exc}") from exc

    if df.empty:
        raise DataLoadError(f"Dataset is empty: {path}")

    return df


def normalize_dtype(series: pd.Series) -> str:
    if pd.api.types.is_numeric_dtype(series):
        return "numeric"
    return "categorical"


def validate_schema(
    baseline: pd.DataFrame,
    recent: pd.DataFrame,
    strict_schema: bool = True,
) -> Tuple[List[str], Dict[str, str]]:
    baseline_cols = list(baseline.columns)
    recent_cols = list(recent.columns)

    missing_in_recent = [c for c in baseline_cols if c not in recent_cols]
    extra_in_recent = [c for c in recent_cols if c not in baseline_cols]

    if strict_schema and (missing_in_recent or extra_in_recent):
        raise SchemaValidationError(
            f"Schema mismatch. Missing in recent: {missing_in_recent}; Extra in recent: {extra_in_recent}"
        )

    common_cols = [c for c in baseline_cols if c in recent_cols]
    if not common_cols:
        raise SchemaValidationError("No common columns found between baseline and recent datasets.")

    feature_types: Dict[str, str] = {}
    incompatible: List[str] = []
    for col in common_cols:
        b_type = normalize_dtype(baseline[col])
        r_type = normalize_dtype(recent[col])
        if b_type != r_type:
            incompatible.append(col)
        else:
            feature_types[col] = b_type

    if incompatible:
        raise SchemaValidationError(
            f"Incompatible column types detected for columns: {incompatible}"
        )

    return common_cols, feature_types


def safe_probabilities(values: np.ndarray, epsilon: float) -> np.ndarray:
    values = np.asarray(values, dtype=float)
    values = np.where(np.isnan(values), 0.0, values)
    values = np.clip(values, 0.0, None)
    total = values.sum()
    if total <= 0:
        values = np.full_like(values, 1.0 / len(values), dtype=float)
    else:
        values = values / total
    values = np.clip(values, epsilon, None)
    values = values / values.sum()
    return values


def compute_psi(expected: np.ndarray, actual: np.ndarray, epsilon: float) -> float:
    e = safe_probabilities(expected, epsilon)
    a = safe_probabilities(actual, epsilon)
    return float(np.sum((a - e) * np.log(a / e)))


def compute_js_divergence(p: np.ndarray, q: np.ndarray, epsilon: float) -> float:
    p = safe_probabilities(p, epsilon)
    q = safe_probabilities(q, epsilon)
    m = 0.5 * (p + q)
    kl_pm = np.sum(p * np.log(p / m))
    kl_qm = np.sum(q * np.log(q / m))
    return float(0.5 * (kl_pm + kl_qm))


def numeric_distributions(
    baseline: pd.Series,
    recent: pd.Series,
    bins: int,
) -> Tuple[np.ndarray, np.ndarray, Dict[str, Any]]:
    b = pd.to_numeric(baseline, errors="coerce")
    r = pd.to_numeric(recent, errors="coerce")

    b_non_null = b.dropna()
    r_non_null = r.dropna()

    if b_non_null.empty and r_non_null.empty:
        baseline_counts = np.ones(bins, dtype=float)
        recent_counts = np.ones(bins, dtype=float)
        return baseline_counts, recent_counts, {"bins": []}

    if b_non_null.nunique() <= 1:
        min_val = float(b_non_null.min()) if not b_non_null.empty else 0.0
        max_val = float(b_non_null.max()) if not b_non_null.empty else 1.0
        if math.isclose(min_val, max_val):
            max_val = min_val + 1.0
        edges = np.linspace(min_val, max_val, bins + 1)
    else:
        try:
            _, edges = pd.qcut(
                b_non_null,
                q=min(bins, max(2, b_non_null.nunique())),
                retbins=True,
                duplicates="drop",
            )
            edges = np.unique(edges)
            if len(edges) < 2:
                min_val = float(b_non_null.min())
                max_val = float(b_non_null.max())
                if math.isclose(min_val, max_val):
                    max_val = min_val + 1.0
                edges = np.linspace(min_val, max_val, bins + 1)
        except ValueError:
            min_val = float(b_non_null.min()) if not b_non_null.empty else 0.0
            max_val = float(b_non_null.max()) if not b_non_null.empty else 1.0
            if math.isclose(min_val, max_val):
                max_val = min_val + 1.0
            edges = np.linspace(min_val, max_val, bins + 1)

    if len(edges) < 2:
        edges = np.array([0.0, 1.0], dtype=float)

    baseline_counts, _ = np.histogram(b_non_null, bins=edges)
    recent_counts, _ = np.histogram(r_non_null, bins=edges)

    details = {"bins": [float(x) for x in edges.tolist()]}
    return baseline_counts.astype(float), recent_counts.astype(float), details


def categorical_distributions(
    baseline: pd.Series,
    recent: pd.Series,
    top_k: int,
) -> Tuple[np.ndarray, np.ndarray, Dict[str, Any]]:
    b = baseline.astype("object").where(~baseline.isna(), "__MISSING__")
    r = recent.astype("object").where(~recent.isna(), "__MISSING__")

    top_categories = b.value_counts(dropna=False).head(top_k).index.tolist()
    category_set = set(top_categories)
    if "__OTHER__" in category_set:
        category_set.remove("__OTHER__")

    def map_categories(s: pd.Series) -> pd.Series:
        return s.apply(lambda x: x if x in category_set else "__OTHER__")

    b_mapped = map_categories(b)
    r_mapped = map_categories(r)

    categories = list(top_categories)
    if any(val not in category_set for val in r.unique().tolist()):
        if "__OTHER__" not in categories:
            categories.append("__OTHER__")
    elif "__OTHER__" in b_mapped.values or "__OTHER__" in r_mapped.values:
        if "__OTHER__" not in categories:
            categories.append("__OTHER__")

    baseline_counts = b_mapped.value_counts().reindex(categories, fill_value=0).values.astype(float)
    recent_counts = r_mapped.value_counts().reindex(categories, fill_value=0).values.astype(float)

    details = {"categories": [str(x) for x in categories]}
    return baseline_counts, recent_counts, details


def compute_missing_rate_change(baseline: pd.Series, recent: pd.Series) -> Tuple[float, float, float]:
    b_rate = float(baseline.isna().mean())
    r_rate = float(recent.isna().mean())
    return b_rate, r_rate, abs(r_rate - b_rate)


def evaluate_feature_drift(
    feature: str,
    baseline: pd.Series,
    recent: pd.Series,
    feature_type: str,
    config: Config,
) -> FeatureDriftResult:
    alerts: List[str] = []
    psi_value: Optional[float] = None
    js_value: Optional[float] = None
    details: Dict[str, Any] = {}

    b_missing, r_missing, missing_change = compute_missing_rate_change(baseline, recent)

    if feature_type == "numeric":
        b_dist, r_dist, dist_details = numeric_distributions(
            baseline, recent, config.settings.numeric_bins
        )
    else:
        b_dist, r_dist, dist_details = categorical_distributions(
            baseline, recent, config.settings.categorical_top_k
        )

    details.update(dist_details)

    psi_value = compute_psi(b_dist, r_dist, config.settings.epsilon)
    js_value = compute_js_divergence(b_dist, r_dist, config.settings.epsilon)

    if psi_value > config.thresholds.psi:
        alerts.append("psi")
    if js_value > config.thresholds.js_divergence:
        alerts.append("js_divergence")
    if missing_change > config.thresholds.missing_rate_change:
        alerts.append("missing_rate_change")

    return FeatureDriftResult(
        feature=feature,
        feature_type=feature_type,
        psi=psi_value,
        js_divergence=js_value,
        missing_rate_baseline=b_missing,
        missing_rate_recent=r_missing,
        missing_rate_change=missing_change,
        alerts=alerts,
        details=details,
    )


def build_summary(results: Sequence[FeatureDriftResult], config: Config) -> DriftSummary:
    exceeded = [r.feature for r in results if len(r.alerts) >= config.thresholds.feature_alert_count]
    drifted_features = len(exceeded)
    total_features = len(results)
    overall_status = "ALERT" if drifted_features > 0 else "OK"
    return DriftSummary(
        total_features=total_features,
        drifted_features=drifted_features,
        features_exceeding_thresholds=exceeded,
        overall_status=overall_status,
    )


def write_report(
    output_path: Path,
    baseline_path: Path,
    recent_path: Path,
    config_path: Path,
    results: Sequence[FeatureDriftResult],
    summary: DriftSummary,
) -> None:
    report = {
        "metadata": {
            "baseline_dataset": str(baseline_path),
            "recent_dataset": str(recent_path),
            "config_file": str(config_path),
        },
        "summary": asdict(summary),
        "features": [asdict(r) for r in results],
    }

    try:
        output_path.parent.mkdir(parents=True, exist_ok=True)
        with output_path.open("w", encoding="utf-8") as f:
            json.dump(report, f, indent=2)
    except OSError as exc:
        raise DriftToolError(f"Failed to write report to '{output_path}': {exc}") from exc


def print_console_summary(summary: DriftSummary, results: Sequence[FeatureDriftResult]) -> None:
    print("=" * 72)
    print("MODEL DRIFT SUMMARY")
    print("=" * 72)
    print(f"Overall status     : {summary.overall_status}")
    print(f"Total features     : {summary.total_features}")
    print(f"Drifted features   : {summary.drifted_features}")
    print("-" * 72)

    flagged = [r for r in results if r.feature in summary.features_exceeding_thresholds]
    if not flagged:
        print("No features exceeded configured drift thresholds.")
        return

    print("Features exceeding thresholds:")
    for r in flagged:
        psi_str = f"{r.psi:.6f}" if r.psi is not None else "n/a"
        js_str = f"{r.js_divergence:.6f}" if r.js_divergence is not None else "n/a"
        print(
            f"- {r.feature} [{r.feature_type}] "
            f"alerts={','.join(r.alerts)} "
            f"psi={psi_str} "
            f"js={js_str} "
            f"missing_change={r.missing_rate_change:.6f}"
        )


def parse_args(argv: Optional[Sequence[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Monitor and evaluate machine learning model drift between baseline and recent datasets."
    )
    parser.add_argument(
        "--baseline",
        required=True,
        type=Path,
        help="Path to baseline reference dataset (CSV, Parquet, or JSON).",
    )
    parser.add_argument(
        "--recent",
        required=True,
        type=Path,
        help="Path to recent inference dataset (CSV, Parquet, or JSON).",
    )
    parser.add_argument(
        "--config",
        required=True,
        type=Path,
        help="Path to configuration file (JSON or YAML).",
    )
    parser.add_argument(
        "--output",
        required=True,
        type=Path,
        help="Path to output JSON report.",
    )
    return parser.parse_args(argv)


def run(args: argparse.Namespace) -> int:
    config = load_config(args.config)
    baseline_df = load_dataset(args.baseline, sample_rows=config.settings.sample_rows)
    recent_df = load_dataset(args.recent, sample_rows=config.settings.sample_rows)

    common_cols, feature_types = validate_schema(
        baseline_df, recent_df, strict_schema=config.settings.strict_schema
    )

    results: List[FeatureDriftResult] = []
    for col in common_cols:
        result = evaluate_feature_drift(
            feature=col,
            baseline=baseline_df[col],
            recent=recent_df[col],
            feature_type=feature_types[col],
            config=config,
        )
        results.append(result)

    summary = build_summary(results, config)
    write_report(args.output, args.baseline, args.recent, args.config, results, summary)
    print_console_summary(summary, results)
    return 0


def main() -> int:
    try:
        args = parse_args()
        return run(args)
    except DriftToolError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2
    except KeyboardInterrupt:
        print("ERROR: Interrupted by user.", file=sys.stderr)
        return 130
    except Exception as exc:
        print(f"ERROR: Unexpected failure: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

