from datetime import datetime
from zoneinfo import ZoneInfo


def find_overlaps(events_a, events_b, tz_name):
    """Return overlapping intervals between two event lists in the given timezone."""
    target_tz = ZoneInfo(tz_name)

    def normalize(events):
        normalized = []
        for event in events:
            try:
                start = datetime.fromisoformat(event['start'])
                end = datetime.fromisoformat(event['end'])
            except (KeyError, ValueError, TypeError):
                continue

            # Skip naive datetimes and invalid ranges
            if start.tzinfo is None or end.tzinfo is None or end <= start:
                continue

            normalized.append((start.astimezone(target_tz), end.astimezone(target_tz)))

        normalized.sort(key=lambda x: x[0])
        return normalized

    a = normalize(events_a)
    b = normalize(events_b)

    overlaps = []
    i = j = 0

    # Two-pointer sweep through sorted intervals
    while i < len(a) and j < len(b):
        start_a, end_a = a[i]
        start_b, end_b = b[j]

        overlap_start = max(start_a, start_b)
        overlap_end = min(end_a, end_b)

        if overlap_start < overlap_end:
            minutes = int((overlap_end - overlap_start).total_seconds() // 60)
            overlaps.append({
                'start': overlap_start.isoformat(),
                'end': overlap_end.isoformat(),
                'minutes': minutes
            })

        # Advance the interval that ends first
        if end_a <= end_b:
            i += 1
        else:
            j += 1

    return overlaps


