from pathlib import Path
import hashlib
from collections import defaultdict


def sha256_file(path: Path, chunk_size: int = 65536) -> str:
    """Compute the SHA-256 hash of a file in chunks."""
    hasher = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            hasher.update(chunk)
    return hasher.hexdigest()


def find_duplicate_files(root: str | Path) -> dict[str, list[str]]:
    """Find duplicate files under root, grouped by content hash.

    Skips symlinks, non-files, and unreadable files.
    Returns only hashes that have at least two matching files.
    """
    root_path = Path(root).expanduser().resolve()
    groups: dict[str, list[str]] = defaultdict(list)

    for path in root_path.rglob('*'):
        try:
            if path.is_symlink() or not path.is_file():
                continue
            file_hash = sha256_file(path)
            groups[file_hash].append(str(path))
        except (OSError, PermissionError):
            # Skip unreadable or inaccessible files
            continue

    # Keep only actual duplicates and sort their paths for stable output
    duplicates = {
        file_hash: sorted(paths)
        for file_hash, paths in groups.items()
        if len(paths) >= 2
    }
    return duplicates


if __name__ == '__main__':
    root_dir = Path('.')
    duplicates = find_duplicate_files(root_dir)

    if not duplicates:
        print('No duplicate files found.')
    else:
        for file_hash, paths in duplicates.items():
            print(f'{file_hash}:')
            for p in paths:
                print(f'  {p}')

