import json
import os
from copy import deepcopy


def parse_value(value: str):
    """Convert strings from environment variables into useful Python types."""
    lowered = value.strip().lower()
    if lowered == 'null':
        return None
    if lowered == 'true':
        return True
    if lowered == 'false':
        return False

    try:
        return int(value)
    except ValueError:
        pass

    try:
        return float(value)
    except ValueError:
        pass

    return value


def deep_merge(base, updates):
    """Recursively merge updates into base and return the merged dict."""
    result = deepcopy(base)
    for key, value in updates.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = deep_merge(result[key], value)
        else:
            result[key] = value
    return result


def build_env_overrides(prefix='APP_'):
    """Build a nested override dictionary from prefixed environment variables."""
    overrides = {}
    for env_key, env_value in os.environ.items():
        if not env_key.startswith(prefix):
            continue

        path = env_key[len(prefix):].split('__')
        current = overrides
        for part in path[:-1]:
            current = current.setdefault(part, {})
        current[path[-1]] = parse_value(env_value)
    return overrides


def load_config(path):
    """Load JSON config safely, returning an empty dict on failure."""
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
            return data if isinstance(data, dict) else {}
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return {}


def main():
    config = load_config('config.json')
    overrides = build_env_overrides('APP_')
    final_config = deep_merge(config, overrides)
    print(json.dumps(final_config, indent=2, sort_keys=True))


if __name__ == '__main__':
    main()
}

import re
from typing import Any, Dict


EXPR_RE = re.compile(r"\{\{\s*(.*?)\s*\}\}")
DEFAULT_RE = re.compile(r"^([a-zA-Z_][\w\.]*)(?:\s*\|\s*default\((['\"])(.*?)\2\))?$")


def resolve_path(context: Dict[str, Any], path: str) -> Any:
    """Resolve a dotted path inside nested dictionaries."""
    value: Any = context
    current_path = []

    for part in path.split('.'):
        current_path.append(part)
        if not isinstance(value, dict) or part not in value:
            raise KeyError('.'.join(current_path))
        value = value[part]

    return value


def render_template(template: str, context: Dict[str, Any]) -> str:
    """Render placeholders like {{ user.name }} with optional defaults."""

    def replace(match: re.Match) -> str:
        expr = match.group(1).strip()
        parsed = DEFAULT_RE.match(expr)
        if not parsed:
            raise ValueError(f"Invalid template expression: {expr}")

        path, _, default_value = parsed.groups()

        try:
            value = resolve_path(context, path)
        except KeyError as exc:
            if default_value is not None:
                return default_value
            raise KeyError(str(exc).strip("'")) from None

        return str(value)

    return EXPR_RE.sub(replace, template)


if __name__ == "__main__":
    template = """
Hello {{ user.name }},
Your role is {{ user.role | default('guest') }}.
Email: {{ user.contact.email }}
City: {{ user.address.city | default("Unknown") }}
""".strip()

    context = {
        "user": {
            "name": "Ava",
            "contact": {
                "email": "ava@example.com"
            }
        }
    }

    print(render_template(template, context))

import time
from typing import Callable, Dict, List, Any

Request = Dict[str, Any]
Response = Dict[str, Any]
Middleware = Callable[[Request, Callable[[Request], Response]], Response]


def build_pipeline(middlewares: List[Middleware], handler: Callable[[Request], Response]) -> Callable[[Request], Response]:
    """Compose middlewares around the final handler."""
    pipeline = handler

    # Wrap in reverse so the first middleware runs first.
    for middleware in reversed(middlewares):
        next_func = pipeline

        def make_wrapper(mw: Middleware, nxt: Callable[[Request], Response]) -> Callable[[Request], Response]:
            return lambda request: mw(request, nxt)

        pipeline = make_wrapper(middleware, next_func)

    return pipeline


def logging_middleware(request: Request, next_func: Callable[[Request], Response]) -> Response:
    print(f"[LOG] Request path: {request.get('path', '/')}")
    return next_func(request)


def auth_middleware(request: Request, next_func: Callable[[Request], Response]) -> Response:
    if 'user' not in request or not request['user']:
        return {'status': 401, 'error': 'Unauthorized'}
    return next_func(request)


def timing_middleware(request: Request, next_func: Callable[[Request], Response]) -> Response:
    start = time.perf_counter()
    response = next_func(request)
    duration_ms = round((time.perf_counter() - start) * 1000, 3)
    response['duration_ms'] = duration_ms
    return response


def hello_handler(request: Request) -> Response:
    return {
        'status': 200,
        'message': f"Hello, {request['user']}"
    }


if __name__ == '__main__':
    pipeline = build_pipeline(
        [logging_middleware, auth_middleware, timing_middleware],
        hello_handler
    )

    authorized_request = {'path': '/hello', 'user': 'Alice'}
    unauthorized_request = {'path': '/hello'}

    print('Authorized response:', pipeline(authorized_request))
    print('Unauthorized response:', pipeline(unauthorized_request))

import re
