from __future__ import annotations

from abc import ABC, abstractmethod
from collections import defaultdict
from dataclasses import dataclass
from typing import DefaultDict, List, Type


# --- Event model -----------------------------------------------------------
@dataclass(frozen=True)
class Event:
    source: str


@dataclass(frozen=True)
class UserEvent(Event):
    username: str


@dataclass(frozen=True)
class LoginEvent(UserEvent):
    success: bool


# --- Listener contract -----------------------------------------------------
class Listener(ABC):
    @abstractmethod
    def handle(self, event: Event) -> None:
        pass


# --- Event bus -------------------------------------------------------------
class EventBus:
    def __init__(self) -> None:
        self._listeners: DefaultDict[Type[Event], List[Listener]] = defaultdict(list)

    def register(self, event_type: Type[Event], listener: Listener) -> None:
        if listener not in self._listeners[event_type]:
            self._listeners[event_type].append(listener)

    def unregister(self, event_type: Type[Event], listener: Listener) -> None:
        if listener in self._listeners[event_type]:
            self._listeners[event_type].remove(listener)

    def dispatch(self, event: Event) -> None:
        # Notify listeners registered for the exact type and all base event types.
        notified = set()
        for cls in type(event).mro():
            if not issubclass(cls, Event):
                continue
            for listener in self._listeners.get(cls, []):
                if id(listener) not in notified:
                    listener.handle(event)
                    notified.add(id(listener))


# --- Concrete listeners ----------------------------------------------------
class AuditListener(Listener):
    def __init__(self, output: List[str]) -> None:
        self.output = output

    def handle(self, event: Event) -> None:
        self.output.append(f"AUDIT:{type(event).__name__}:{event.source}")


class UserListener(Listener):
    def __init__(self, output: List[str]) -> None:
        self.output = output

    def handle(self, event: Event) -> None:
        if isinstance(event, UserEvent):
            self.output.append(f"USER:{event.username}")


class LoginListener(Listener):
    def __init__(self, output: List[str]) -> None:
        self.output = output

    def handle(self, event: Event) -> None:
        if isinstance(event, LoginEvent):
            status = "ok" if event.success else "fail"
            self.output.append(f"LOGIN:{event.username}:{status}")


# --- Demonstration ---------------------------------------------------------
if __name__ == "__main__":
    results: List[str] = []
    bus = EventBus()

    audit = AuditListener(results)
    user = UserListener(results)
    login = LoginListener(results)

    bus.register(Event, audit)
    bus.register(UserEvent, user)
    bus.register(LoginEvent, login)

    bus.dispatch(UserEvent(source="web", username="alice"))
    bus.dispatch(LoginEvent(source="mobile", username="bob", success=True))

    bus.unregister(UserEvent, user)
    bus.dispatch(LoginEvent(source="api", username="charlie", success=False))

    print(results)

def apply_discount(price, percent):
    """Return the discounted price rounded to 2 decimals.

    Args:
        price (float): Original item price, must be non-negative.
        percent (float): Discount percentage from 0 to 100 inclusive.

    Raises:
        ValueError: If inputs are outside allowed ranges.
    """
    if price < 0:
        raise ValueError("price must be non-negative")
    if not 0 <= percent <= 100:
        raise ValueError("percent must be between 0 and 100")

    discounted = price * (1 - percent / 100)
    return round(discounted, 2)


# ----------------------
# Pytest unit tests below
# Run with: pytest <filename>.py
# ----------------------

def test_apply_discount_regular_case():
    assert apply_discount(200, 25) == 150.0


def test_apply_discount_zero_percent():
    assert apply_discount(19.99, 0) == 19.99


def test_apply_discount_full_discount():
    assert apply_discount(49.99, 100) == 0.0


def test_apply_discount_rounding():
    assert apply_discount(10, 33.3333) == 6.67


