import json
from collections import OrderedDict
from urllib.parse import urljoin

import requests
from bs4 import BeautifulSoup

BASE_URL = 'https://quotes.toscrape.com/'
HEADERS = {
    'User-Agent': 'Mozilla/5.0 (compatible; QuoteScraper/1.0; +https://example.com/bot)'
}
MAX_PAGES = 3


def fetch_page(url):
    """Download a page and return its parsed BeautifulSoup object."""
    response = requests.get(url, headers=HEADERS, timeout=10)
    response.raise_for_status()
    return BeautifulSoup(response.text, 'html.parser')


def parse_quotes(soup):
    """Extract quote data from a page."""
    items = []
    for quote in soup.select('div.quote'):
        text = quote.select_one('span.text').get_text(strip=True)
        author = quote.select_one('small.author').get_text(strip=True)
        tags = [tag.get_text(strip=True) for tag in quote.select('div.tags a.tag')]
        items.append({
            'text': text,
            'author': author,
            'tags': tags,
        })
    return items


def find_next_page(soup, current_url):
    """Return absolute URL for the next page, or None if unavailable."""
    next_link = soup.select_one('li.next a')
    return urljoin(current_url, next_link['href']) if next_link else None


def scrape_quotes(start_url, max_pages=3):
    """Scrape quotes across paginated pages and deduplicate by quote text."""
    seen = OrderedDict()
    url = start_url
    pages_scraped = 0

    while url and pages_scraped < max_pages:
        soup = fetch_page(url)
        for item in parse_quotes(soup):
            seen.setdefault(item['text'], item)  # preserve first occurrence order
        url = find_next_page(soup, url)
        pages_scraped += 1

    return list(seen.values())


def main():
    data = scrape_quotes(BASE_URL, MAX_PAGES)
    print(json.dumps(data, indent=2, ensure_ascii=False))


if __name__ == '__main__':
    main()
}

import hashlib


def verify_download(file_path, expected_sha256):
    """Return True if the file's SHA-256 matches the expected checksum."""
    sha256 = hashlib.sha256()

    try:
        with open(file_path, 'rb') as file:
            # Read in chunks to support large files efficiently
            for chunk in iter(lambda: file.read(8192), b''):
                sha256.update(chunk)
    except FileNotFoundError:
        return False
    except OSError:
        return False

    computed_checksum = sha256.hexdigest()
    return computed_checksum.lower() == expected_sha256.strip().lower()


def main():
    file_path = input('Enter file path: ').strip()
    expected_sha256 = input('Enter expected SHA-256 checksum: ').strip()

    if verify_download(file_path, expected_sha256):
        print('Checksum verified')
    else:
        print('Checksum mismatch')


if __name__ == '__main__':
    main()
}

import hashlib
import secrets


class UserAuth:
    def __init__(self):
        # username -> {password_hash, role}
        self.users = {}
        # token -> username
        self.sessions = {}

    def _hash_password(self, password: str) -> str:
        return hashlib.sha256(password.encode('utf-8')).hexdigest()

    def register_user(self, username: str, password: str, role: str) -> None:
        if username in self.users:
            raise ValueError('Username already exists')
        self.users[username] = {
            'password_hash': self._hash_password(password),
            'role': role
        }

    def authenticate(self, username: str, password: str):
        user = self.users.get(username)
        if not user:
            return None
        if user['password_hash'] != self._hash_password(password):
            return None

        token = secrets.token_hex(16)
        self.sessions[token] = username
        return token

    def authorize(self, token: str, required_role: str) -> bool:
        username = self.sessions.get(token)
        if not username:
            return False
        return self.users[username]['role'] == required_role


if __name__ == '__main__':
