    auth.register_user('alice', 'secure123', 'admin')
    auth.register_user('bob', 'password456', 'user')

    alice_token = auth.authenticate('alice', 'secure123')
    bob_token = auth.authenticate('bob', 'wrong-password')

    print(alice_token is not None)              # True
    print(bob_token is None)                    # True
    print(auth.authorize(alice_token, 'admin')) # True
    print(auth.authorize(alice_token, 'user'))  # False
    print(auth.authorize('invalid', 'admin'))   # False

from functools import wraps


def retry(max_attempts):
    """Decorator factory that retries a function on failure."""
    def decorator(func):
        call_counter = 0  # Stored in closure, shared across wrapper calls

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal call_counter
            last_error = None

            for _ in range(max_attempts):
                call_counter += 1
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    last_error = exc

            raise last_error

        # Expose the closure-backed count via an attribute
        def get_call_count():
            return call_counter

        wrapper.call_count = get_call_count
        return wrapper

    return decorator


@retry(max_attempts=3)
def unstable_divide(a, b):
    """Divide two numbers, raising an error if b is zero."""
    return a / b


if __name__ == "__main__":
    test_cases = [(10, 2), (5, 0), (9, 3)]

    for a, b in test_cases:
        try:
            result = unstable_divide(a, b)
            print(f"unstable_divide({a}, {b}) = {result}")
        except Exception as e:
            print(f"unstable_divide({a}, {b}) failed: {e}")

    print("Total wrapped function attempts:", unstable_divide.call_count())

import random


def genetic_knapsack(items, capacity, population_size=60, generations=120, mutation_rate=0.02):
    n = len(items)

    def fitness(chromosome):
        total_value = sum(gene * item[0] for gene, item in zip(chromosome, items))
        total_weight = sum(gene * item[1] for gene, item in zip(chromosome, items))
        return total_value if total_weight <= capacity else 0

    def total_weight(chromosome):
        return sum(gene * item[1] for gene, item in zip(chromosome, items))

    def tournament_selection(population, k=3):
        candidates = random.sample(population, k)
        return max(candidates, key=fitness)

    def crossover(parent1, parent2):
        if n < 2:
            return parent1[:], parent2[:]
        point = random.randint(1, n - 1)
        child1 = parent1[:point] + parent2[point:]
        child2 = parent2[:point] + parent1[point:]
        return child1, child2

    def mutate(chromosome):
        for i in range(n):
            if random.random() < mutation_rate:
                chromosome[i] ^= 1
        return chromosome

    # Initialize random population
    population = [[random.randint(0, 1) for _ in range(n)] for _ in range(population_size)]

    for _ in range(generations):
        # Elitism: keep the current best
        best = max(population, key=fitness)
        new_population = [best[:]]

        while len(new_population) < population_size:
            parent1 = tournament_selection(population)
            parent2 = tournament_selection(population)
            child1, child2 = crossover(parent1, parent2)
            new_population.append(mutate(child1))
            if len(new_population) < population_size:
                new_population.append(mutate(child2))

        population = new_population

    best = max(population, key=fitness)
    return best, fitness(best), total_weight(best)


if __name__ == "__main__":
    items = [(60, 10), (100, 20), (120, 30), (80, 15), (30, 5), (50, 8)]
    capacity = 50

    chromosome, value, weight = genetic_knapsack(items, capacity)
    print("Best chromosome:", chromosome)
    print("Total value:", value)
    print("Total weight:", weight)
    print("Selected items:", [items[i] for i, bit in enumerate(chromosome) if bit])

import hashlib
import zlib


def verify_files(file_map):
    """
    Compute SHA-256 and CRC32 for each file's text content.

    Args:
        file_map: dict[str, str] mapping file names to text content

    Returns:
        dict[str, dict[str, str]] with 'sha256' and 'crc32' hex values
    """
    results = {}

    for filename, content in file_map.items():
        data = content.encode('utf-8')

        sha256_hash = hashlib.sha256(data).hexdigest()
        crc32_checksum = format(zlib.crc32(data) & 0xFFFFFFFF, '08x')

        results[filename] = {
            'sha256': sha256_hash,
            'crc32': crc32_checksum,
        }

    return results


def main():
    sample_files = {
        'notes.txt': 'Hashing helps verify file integrity.',
        'config.json': '{"debug": true, "version": 2}',
        'readme.md': '# Project\nThis is a sample file.'
    }

    checksums = verify_files(sample_files)

    for filename, values in checksums.items():
        print(f'{filename}:')
        print(f'  sha256: {values["sha256"]}')
        print(f'  crc32:  {values["crc32"]}')


if __name__ == '__main__':
    main()

class BSTNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None


class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        self.root = self._insert(self.root, value)

    def _insert(self, node, value):
        if node is None:
            return BSTNode(value)
        if value < node.value:
            node.left = self._insert(node.left, value)
        elif value > node.value:
            node.right = self._insert(node.right, value)
        # Ignore duplicates
        return node

    def search(self, value):
        return self._search(self.root, value)

    def _search(self, node, value):
        if node is None:
            return False
        if value == node.value:
            return True
        if value < node.value:
            return self._search(node.left, value)
        return self._search(node.right, value)

    def delete(self, value):
        self.root = self._delete(self.root, value)

    def _delete(self, node, value):
        if node is None:
            return None

        if value < node.value:
            node.left = self._delete(node.left, value)
        elif value > node.value:
            node.right = self._delete(node.right, value)
        else:
            # Node with one child or no child
            if node.left is None:
                return node.right
            if node.right is None:
                return node.left

            # Node with two children: replace with inorder successor
            successor = self._min_value_node(node.right)
            node.value = successor.value
            node.right = self._delete(node.right, successor.value)

        return node

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

    def inorder(self):
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, node, result):
        if node is not None:
            self._inorder(node.left, result)
            result.append(node.value)
            self._inorder(node.right, result)


# Example usage
if __name__ == '__main__':
    bst = BinarySearchTree()
    for value in [50, 30, 70, 20, 40, 60, 80]:
        bst.insert(value)

    print(bst.inorder())      # [20, 30, 40, 50, 60, 70, 80]
    print(bst.search(40))     # True
    print(bst.search(100))    # False

    bst.delete(30)
    print(bst.inorder())      # [20, 40, 50, 60, 70, 80]

    bst.delete(50)
    print(bst.inorder())      # [20, 40, 60, 70, 80]

class ConnectionFSM:
    """Table-driven finite state machine for a TCP-like connection lifecycle."""

    # Transition table: {state: {event: next_state}}
    _TRANSITIONS = {
        'CLOSED': {
            'passive_open': 'LISTEN',
            'active_open': 'SYN_SENT',
        },
        'LISTEN': {
            'send': 'SYN_SENT',
            'recv_syn': 'SYN_RECEIVED',
            'close': 'CLOSED',
        },
        'SYN_SENT': {
            'recv_syn': 'SYN_RECEIVED',
            'recv_syn_ack': 'ESTABLISHED',
            'close': 'CLOSED',
        },
        'SYN_RECEIVED': {
            'recv_ack': 'ESTABLISHED',
            'close': 'FIN_WAIT_1',
        },
        'ESTABLISHED': {
            'close': 'FIN_WAIT_1',
            'recv_fin': 'CLOSE_WAIT',
        },
        'FIN_WAIT_1': {
            'recv_ack': 'FIN_WAIT_2',
            'recv_fin': 'CLOSING',
        },
        'FIN_WAIT_2': {
            'recv_fin': 'TIME_WAIT',
        },
        'CLOSING': {
            'recv_ack': 'TIME_WAIT',
        },
        'TIME_WAIT': {
            'timeout': 'CLOSED',
        },
        'CLOSE_WAIT': {
            'close': 'LAST_ACK',
        },
        'LAST_ACK': {
            'recv_ack': 'CLOSED',
        },
    }

    def __init__(self):
        self.state = 'CLOSED'
        self._visited = [self.state]

    def handle(self, event: str) -> str:
        """Process an event and return the new state.

        Raises:
            ValueError: if the event is invalid for the current state.
        """
        next_state = self._TRANSITIONS.get(self.state, {}).get(event)
        if next_state is None:
            raise ValueError(f"Invalid transition: state={self.state!r}, event={event!r}")

        self.state = next_state
        self._visited.append(self.state)
        return self.state

    def history(self):
        """Return the ordered list of visited states, including the initial state."""
        return list(self._visited)


# Example usage
if __name__ == '__main__':
    fsm = ConnectionFSM()
    for event in ('active_open', 'recv_syn_ack', 'close', 'recv_ack', 'recv_fin', 'timeout'):
        print(f"{event} -> {fsm.handle(event)}")
    print('History:', fsm.history())

from abc import ABC, abstractmethod


class Notification(ABC):
    def __init__(self):
        self.recipient = ""
        self.title = ""
        self.body = ""

    @abstractmethod
    def send(self):
        pass


class EmailNotification(Notification):
    def send(self):
        return f"EMAIL to {self.recipient} | Subject: {self.title} | Body: {self.body}"


class SMSNotification(Notification):
    def send(self):
        return f"SMS to {self.recipient} | Message: {self.title} - {self.body}"


class PushNotification(Notification):
    def send(self):
        return f"PUSH to {self.recipient} | {self.title}: {self.body}"


class NotificationFactory:
    @staticmethod
    def create(channel):
        channel = channel.lower()
        if channel == "email":
            return EmailNotification()
        if channel == "sms":
            return SMSNotification()
        if channel == "push":
            return PushNotification()
        raise ValueError(f"Unsupported channel: {channel}")


class NotificationBuilder:
    def __init__(self):
        self._recipient = ""
        self._title = ""
        self._body = ""

    def recipient(self, value):
        self._recipient = value
        return self

    def title(self, value):
        self._title = value
        return self

    def body(self, value):
        self._body = value
        return self

    def build(self, channel):
        notification = NotificationFactory.create(channel)
        notification.recipient = self._recipient
        notification.title = self._title
        notification.body = self._body
        return notification


if __name__ == "__main__":
    email = (
        NotificationBuilder()
        .recipient("alice@example.com")
        .title("Welcome")
        .body("Thanks for signing up!")
        .build("email")
    )

    sms = (
        NotificationBuilder()
        .recipient("+123456789")
        .title("Code")
        .body("Your verification code is 4821")
        .build("sms")
    )

    push = (
        NotificationBuilder()
        .recipient("user_42")
        .title("Reminder")
        .body("Your meeting starts in 10 minutes")
        .build("push")
    )

    print(email.send())
    print(sms.send())
    print(push.send())

import json
import csv
import io


def json_to_csv(json_data: str) -> str:
    """Convert product records from a JSON string to a CSV string."""
    required_fields = ["id", "name", "price", "in_stock"]

    try:
        records = json.loads(json_data)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON input: {e.msg}") from e

    if not isinstance(records, list):
        raise ValueError("JSON input must be a list of product records")

    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise ValueError(f"Record at index {index} must be an object")

        missing = [field for field in required_fields if field not in record]
        if missing:
            raise ValueError(
                f"Record at index {index} is missing required fields: {', '.join(missing)}"
            )

    output = io.StringIO()
    writer = csv.DictWriter(output, fieldnames=required_fields)
    writer.writeheader()
    writer.writerows(records)

    return output.getvalue()


if __name__ == "__main__":
    sample_json = json.dumps([
        {"id": 1, "name": "Laptop", "price": 999.99, "in_stock": True},
        {"id": 2, "name": "Mouse", "price": 25.5, "in_stock": False}
    ])

    try:
        csv_result = json_to_csv(sample_json)
        print(csv_result)
    except ValueError as err:
        print(f"Error: {err}")

from typing import Dict, Iterable, Iterator, List, Any


SEVERITY_RANK = {
    'DEBUG': 10,
    'INFO': 20,
    'WARN': 30,
    'ERROR': 40,
    'CRITICAL': 50,
}


def lazy_pipeline(
    records: Iterable[Dict[str, Any]],
    min_severity: str,
    keyword: str,
) -> Iterator[Dict[str, Any]]:
    """Lazily filter and transform log records."""
    min_rank = SEVERITY_RANK[min_severity.upper()]
    keyword_lower = keyword.lower()

    for record in records:
        # Demonstration hook: this prints only when a record is actually consumed.
        print(f"Inspecting record {record['id']}")

        severity = str(record['severity']).upper()
        message = str(record['message'])

        if SEVERITY_RANK.get(severity, 0) < min_rank:
            continue
        if keyword_lower not in message.lower():
            continue

        yield {
            **record,
            'severity': severity,
            'summary': message[:20],
        }


def take(n: int, iterable: Iterable[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Consume at most n items from an iterable and return them as a list."""
    result = []
    for item in iterable:
        if len(result) >= n:
            break
        result.append(item)
    return result


def generate_logs() -> Iterator[Dict[str, Any]]:
    """Example log source that is itself lazy."""
    logs = [
        {'id': 1, 'severity': 'INFO', 'message': 'System boot complete'},
        {'id': 2, 'severity': 'ERROR', 'message': 'Database timeout while syncing'},
        {'id': 3, 'severity': 'WARN', 'message': 'High memory usage detected'},
        {'id': 4, 'severity': 'CRITICAL', 'message': 'Timeout caused service outage'},
        {'id': 5, 'severity': 'ERROR', 'message': 'User request failed due to timeout'},
    ]
    for log in logs:
        print(f"Producing record {log['id']}")
        yield log


if __name__ == '__main__':
    pipeline = lazy_pipeline(generate_logs(), min_severity='WARN', keyword='timeout')

    first_two = take(2, pipeline)
    print('\nCollected results:')
    for item in first_two:
        print(item)

from google.protobuf.json_format import MessageToJson
from google.protobuf.message import DecodeError


def _is_field_present(msg, field):
    """Return True if a field is meaningfully set on the message."""
    if field.label == field.LABEL_REPEATED:
        return len(getattr(msg, field.name)) > 0

    if field.cpp_type == field.CPPTYPE_MESSAGE:
        return msg.HasField(field.name)

    if field.containing_oneof is not None:
        return msg.WhichOneof(field.containing_oneof.name) == field.name

    # Proto3 scalars do not support HasField; treat non-default as present.
    value = getattr(msg, field.name)
    return value != field.default_value


def merge_proto_messages(primary_bytes, fallback_bytes, message_cls):
    """
    Merge fallback into primary, filling only fields missing in primary.

    Repeated fields are copied from fallback only if the primary repeated field is empty.
    Singular message fields are recursively merged.
    """
    try:
        primary = message_cls()
        fallback = message_cls()
        primary.ParseFromString(primary_bytes)
        fallback.ParseFromString(fallback_bytes)
    except DecodeError as exc:
        raise ValueError(f"Failed to parse protobuf payload: {exc}") from exc

    result = message_cls()
    result.CopyFrom(primary)

    for field in result.DESCRIPTOR.fields:
        primary_value = getattr(result, field.name)
        fallback_value = getattr(fallback, field.name)

        if field.label == field.LABEL_REPEATED:
            if len(primary_value) == 0 and len(fallback_value) > 0:
                if field.cpp_type == field.CPPTYPE_MESSAGE:
                    for item in fallback_value:
                        primary_value.add().CopyFrom(item)
                else:
                    primary_value.extend(fallback_value)
            continue

        if field.cpp_type == field.CPPTYPE_MESSAGE:
            if not result.HasField(field.name) and fallback.HasField(field.name):
                primary_value.CopyFrom(fallback_value)
            elif result.HasField(field.name) and fallback.HasField(field.name):
                # Recursively merge nested messages.
                merged_nested = merge_proto_messages(
                    primary_value.SerializeToString(),
                    fallback_value.SerializeToString(),
                    primary_value.__class__,
                )
                primary_value.ParseFromString(merged_nested)
            continue

        if not _is_field_present(result, field) and _is_field_present(fallback, field):
            setattr(result, field.name, fallback_value)

    return result.SerializeToString()


def merged_message_json(primary_bytes, fallback_bytes, message_cls):
    """Return the merged protobuf message as formatted JSON for debugging."""
    merged = message_cls()
    merged.ParseFromString(merge_proto_messages(primary_bytes, fallback_bytes, message_cls))
    return MessageToJson(merged, indent=2, sort_keys=True)

import time
from typing import Callable, Any


class CircuitOpenError(Exception):
    pass


class CircuitBreaker:
    CLOSED = 'closed'
    OPEN = 'open'
    HALF_OPEN = 'half_open'

    def __init__(self, failure_threshold: int = 3, recovery_timeout: float = 2.0):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.failure_count = 0
        self.state = self.CLOSED
        self.opened_at = 0.0

    def before_call(self) -> None:
        if self.state == self.OPEN:
            if time.monotonic() - self.opened_at >= self.recovery_timeout:
                self.state = self.HALF_OPEN
            else:
                raise CircuitOpenError('Circuit is open')

    def record_success(self) -> None:
        self.failure_count = 0
        self.state = self.CLOSED

    def record_failure(self) -> None:
        self.failure_count += 1
        if self.failure_count >= self.failure_threshold or self.state == self.HALF_OPEN:
            self.state = self.OPEN
            self.opened_at = time.monotonic()


def call_with_retry(func: Callable[[], Any], breaker: CircuitBreaker, max_attempts: int = 4) -> Any:
    delay = 0.1
    last_error = None

    for attempt in range(1, max_attempts + 1):
        breaker.before_call()
        try:
            result = func()
            breaker.record_success()
            print(f'attempt={attempt}, state={breaker.state}, success')
            return result
        except Exception as exc:
            last_error = exc
            breaker.record_failure()
            print(f'attempt={attempt}, state={breaker.state}, error={exc}, next_backoff={delay}')
            if breaker.state == CircuitBreaker.OPEN:
                break
            delay *= 2  # simulated exponential backoff; no sleep

    raise last_error


class FlakyService:
    def __init__(self, failures_before_success: int):
        self.failures_left = failures_before_success

    def call(self) -> str:
        if self.failures_left > 0:
            self.failures_left -= 1
            raise RuntimeError('temporary service failure')
        return 'service response'


if __name__ == '__main__':
    breaker = CircuitBreaker(failure_threshold=3, recovery_timeout=1.0)
    service = FlakyService(failures_before_success=5)

    for i in range(1, 6):
        try:
            result = call_with_retry(service.call, breaker)
            print(f'call {i}: {result}')
        except Exception as e:
            print(f'call {i}: failed ({type(e).__name__}: {e})')

        if i == 3:
            print('waiting for recovery timeout...')
            time.sleep(1.1)

        print(f'breaker_state_after_call={breaker.state}\n')

class PluginManager:
    def __init__(self):
        self._plugins = {}   # name -> function
        self._enabled = {}   # name -> bool
        self._order = []     # registration order

    def register(self, name):
        """Decorator to register a plugin function under a unique name."""
        def decorator(func):
            if name in self._plugins:
                raise ValueError(f"Plugin '{name}' is already registered")
            self._plugins[name] = func
            self._enabled[name] = True
            self._order.append(name)
            return func
        return decorator

    def enable(self, name):
        if name not in self._plugins:
            raise ValueError(f"Unknown plugin: {name}")
        self._enabled[name] = True

    def disable(self, name):
        if name not in self._plugins:
            raise ValueError(f"Unknown plugin: {name}")
        self._enabled[name] = False

    def run(self, text):
        """Execute all enabled plugins in registration order."""
        result = text
        for name in self._order:
            if self._enabled[name]:
                result = self._plugins[name](result)
        return result


manager = PluginManager()


@manager.register('strip')
def strip_text(text):
    return text.strip()


@manager.register('uppercase')
def uppercase_text(text):
    return text.upper()


@manager.register('exclaim')
def add_exclamation(text):
    return text + '!!!'


sample = '  hello plugin world  '
print(manager.run(sample))  # HELLO PLUGIN WORLD!!!

manager.disable('uppercase')
print(manager.run(sample))  # hello plugin world!!!

import requests


class APIClient:
    """Simple REST API client for JSON-based services."""

    def __init__(self, base_url: str, timeout: int = 5):
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout

    def _get(self, path: str, params=None):
        url = f"{self.base_url}/{path.lstrip('/')}"
        try:
            response = requests.get(url, params=params, timeout=self.timeout)
            response.raise_for_status()
            return response.json()
        except requests.RequestException as exc:
            raise RuntimeError(f"GET request failed for {url}: {exc}") from exc

    def get_posts(self):
        """Fetch all posts."""
        return self._get("posts")

    def get_post(self, post_id: int):
        """Fetch a single post by ID."""
        return self._get(f"posts/{post_id}")


def main():
    client = APIClient("https://jsonplaceholder.typicode.com", timeout=10)

    posts = client.get_posts()
    if posts:
        print("First post title:", posts[0]["title"])

    post = client.get_post(1)
    print("Post 1 title:", post["title"])


if __name__ == "__main__":
    main()
