import time
from collections import deque
from functools import wraps


def rate_limited(max_calls, period_seconds):
    """Decorator factory that limits calls per rolling time window."""
    if max_calls <= 0 or period_seconds <= 0:
        raise ValueError("max_calls and period_seconds must be positive")

    def decorator(func):
        # Closure state: each decorated function gets its own history.
        call_times = deque()

        @wraps(func)
        def wrapper(*args, **kwargs):
            now = time.monotonic()
            window_start = now - period_seconds

            # Remove timestamps that are outside the rolling window.
            while call_times and call_times[0] <= window_start:
                call_times.popleft()

            if len(call_times) >= max_calls:
                oldest_relevant = call_times[0]
                retry_after = period_seconds - (now - oldest_relevant)
                raise RuntimeError(
                    f"Rate limit exceeded for {func.__name__}: "
                    f"max {max_calls} calls per {period_seconds} seconds. "
                    f"Try again in {max(retry_after, 0):.2f}s."
                )

            call_times.append(now)
            return func(*args, **kwargs)

        def reset():
            """Clear call history for this wrapped function."""
            call_times.clear()

        wrapper.reset = reset
        return wrapper

    return decorator


@rate_limited(2, 1.5)
def fetch_data(source):
    return f"Fetched from {source}"


@rate_limited(1, 1.5)
def send_heartbeat():
    return "heartbeat sent"


if __name__ == "__main__":
