    except RuntimeError as exc:
        print(exc)

    # Independent state: this function has its own separate limit.
    print(send_heartbeat())
    try:
        print(send_heartbeat())
    except RuntimeError as exc:
        print(exc)

    fetch_data.reset()
    print(fetch_data("db after reset"))

from dataclasses import dataclass, field
from typing import List, Optional


@dataclass
class Product:
    id: int
    name: str
    price: float
    quantity: int


@dataclass
class Inventory:
    products: List[Product] = field(default_factory=list)

    def add_product(self, product: Product) -> None:
        """Add a product to the inventory."""
        self.products.append(product)

    def total_value(self) -> float:
        """Calculate the total value of all items in inventory."""
        return sum(product.price * product.quantity for product in self.products)

    def find_product_by_id(self, product_id: int) -> Optional[Product]:
        """Return the product with the given id, or None if not found."""
        for product in self.products:
            if product.id == product_id:
                return product
        return None

    def low_stock_products(self, threshold: int) -> List[Product]:
        """Return all products with quantity below the given threshold."""
        return [product for product in self.products if product.quantity < threshold]


if __name__ == "__main__":
