import time
from functools import wraps
from collections import deque


def rate_limiter(max_calls, period_seconds):
    """Return a decorator that limits calls to max_calls per period_seconds."""
    if max_calls <= 0 or period_seconds <= 0:
        raise ValueError("max_calls and period_seconds must be positive")

    def decorator(func):
        call_times = deque()  # closure state: timestamps of recent calls

        @wraps(func)
        def wrapper(*args, **kwargs):
            now = time.monotonic()

            # Remove timestamps outside the active sliding window
            while call_times and now - call_times[0] >= period_seconds:
                call_times.popleft()

            if len(call_times) >= max_calls:
                retry_after = period_seconds - (now - call_times[0])
                raise RuntimeError(
                    f"Rate limit exceeded for {func.__name__}: "
                    f"allowed {max_calls} calls per {period_seconds} seconds. "
                    f"Try again in {retry_after:.2f}s."
                )

            call_times.append(now)
            return func(*args, **kwargs)

        return wrapper

    return decorator


@rate_limiter(3, 2)
def fetch_data(item_id, verbose=False):
    """Example function protected by the rate limiter."""
    return {"item_id": item_id, "verbose": verbose, "status": "ok"}


if __name__ == "__main__":
    for i in range(4):
        try:
            result = fetch_data(i, verbose=True)
            print("Call allowed:", result)
        except RuntimeError as exc:
            print("Call blocked:", exc)
        time.sleep(0.4)

    print("Waiting for the window to reset...")
    time.sleep(2)

    try:
        print("Call allowed after reset:", fetch_data(99))
    except RuntimeError as exc:
        print("Unexpected block:", exc)

import base64
import hashlib
import hmac
import json
import os
import time


class AuthService:
    def __init__(self, secret_key: bytes):
        self.secret_key = secret_key
        self.users = {}  # username -> {salt, password_hash, roles}

    def register(self, username: str, password: str, roles):
        if username in self.users:
            raise ValueError("duplicate user")
        salt = os.urandom(16)
        password_hash = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 100_000)
        self.users[username] = {
            "salt": salt,
            "password_hash": password_hash,
            "roles": set(roles),
        }

    def login(self, username: str, password: str, ttl_seconds: int = 3600) -> str:
        user = self.users.get(username)
        if not user:
            raise ValueError("unknown user")

        candidate = hashlib.pbkdf2_hmac("sha256", password.encode(), user["salt"], 100_000)
        if not hmac.compare_digest(candidate, user["password_hash"]):
            raise ValueError("invalid credentials")

        payload = {
            "sub": username,
            "exp": int(time.time()) + ttl_seconds,
            "roles": sorted(user["roles"]),
        }
        payload_bytes = json.dumps(payload, separators=(",", ":")).encode()
        payload_b64 = base64.urlsafe_b64encode(payload_bytes).rstrip(b"=")
        signature = hmac.new(self.secret_key, payload_b64, hashlib.sha256).digest()
        sig_b64 = base64.urlsafe_b64encode(signature).rstrip(b"=")
        return f"{payload_b64.decode()}.{sig_b64.decode()}"

    def authorize(self, token: str, required_role: str) -> bool:
        try:
            payload_b64, sig_b64 = token.split(".", 1)
        except ValueError:
            raise ValueError("malformed token")

        expected_sig = hmac.new(self.secret_key, payload_b64.encode(), hashlib.sha256).digest()
        actual_sig = self._b64decode(sig_b64)
        if not hmac.compare_digest(expected_sig, actual_sig):
            raise ValueError("bad signature")

        payload = json.loads(self._b64decode(payload_b64).decode())
        if payload.get("exp", 0) < int(time.time()):
            raise ValueError("expired session")

        username = payload.get("sub")
        user = self.users.get(username)
        if not user:
            raise ValueError("unknown user")
        return required_role in user["roles"]

    @staticmethod
    def _b64decode(data: str) -> bytes:
        padding = "=" * (-len(data) % 4)
        try:
            return base64.urlsafe_b64decode(data + padding)
        except Exception as exc:
            raise ValueError("malformed token") from exc


if __name__ == "__main__":
    auth = AuthService(b"super-secret-signing-key")
    auth.register("alice", "S3curePass!", {"admin", "editor"})
    token = auth.login("alice", "S3curePass!", ttl_seconds=60)
    print(auth.authorize(token, "admin"))  # True
    print(auth.authorize(token, "viewer"))  # False

def flatten_nested_sum(data):
    """Recursively sum all integers in a nested list."""
    total = 0

    for item in data:
        if isinstance(item, list):
            # Recurse into sublists
            total += flatten_nested_sum(item)
        elif isinstance(item, int):
            total += item
        else:
            raise TypeError(f"Unsupported element type: {type(item).__name__}")

    return total


