from __future__ import annotations

from dataclasses import dataclass


class Document:
    def __init__(self, text: str = ""):
        self.text = text


class Command:
    def execute(self) -> None:
        raise NotImplementedError

    def undo(self) -> None:
        raise NotImplementedError


@dataclass
class InsertCommand(Command):
    doc: Document
    index: int
    value: str

    def execute(self) -> None:
        self.doc.text = self.doc.text[:self.index] + self.value + self.doc.text[self.index:]

    def undo(self) -> None:
        end = self.index + len(self.value)
        self.doc.text = self.doc.text[:self.index] + self.doc.text[end:]


@dataclass
class DeleteCommand(Command):
    doc: Document
    index: int
    length: int
    deleted: str = ""

    def execute(self) -> None:
        self.deleted = self.doc.text[self.index:self.index + self.length]
        self.doc.text = self.doc.text[:self.index] + self.doc.text[self.index + self.length:]

    def undo(self) -> None:
        self.doc.text = self.doc.text[:self.index] + self.deleted + self.doc.text[self.index:]


@dataclass
class ReplaceCommand(Command):
    doc: Document
    index: int
    length: int
    value: str
    original: str = ""

    def execute(self) -> None:
        self.original = self.doc.text[self.index:self.index + self.length]
        self.doc.text = (
            self.doc.text[:self.index] + self.value + self.doc.text[self.index + self.length:]
        )

    def undo(self) -> None:
        end = self.index + len(self.value)
        self.doc.text = self.doc.text[:self.index] + self.original + self.doc.text[end:]


class CommandManager:
    def __init__(self):
        self._undo_stack: list[Command] = []
        self._redo_stack: list[Command] = []

    def run(self, command: Command) -> None:
        command.execute()
        self._undo_stack.append(command)
        self._redo_stack.clear()  # New action invalidates redo history.

    def undo(self) -> None:
        if not self._undo_stack:
            return
        command = self._undo_stack.pop()
        command.undo()
        self._redo_stack.append(command)

    def redo(self) -> None:
        if not self._redo_stack:
            return
        command = self._redo_stack.pop()
        command.execute()
        self._undo_stack.append(command)


if __name__ == "__main__":
    doc = Document("Hello World")
    manager = CommandManager()

    def show(step: str) -> None:
        print(f"{step}: {doc.text}")

    show("Initial")
    manager.run(InsertCommand(doc, 5, ","))
    show("After insert")
    manager.run(DeleteCommand(doc, 6, 1))
    show("After delete")
    manager.run(ReplaceCommand(doc, 6, 5, "Universe"))
    show("After replace")

    manager.undo()
    show("After undo 1")
    manager.undo()
    show("After undo 2")
    manager.redo()
    show("After redo 1")

    manager.run(InsertCommand(doc, len(doc.text), "!"))
    show("After new insert")
    manager.redo()  # No effect because redo stack was cleared.
    show("After redo attempt")

from collections import defaultdict
from typing import Callable, Dict, List, Any


class EventBus:
    """A simple publish/subscribe event bus."""

    def __init__(self) -> None:
        self._subscribers: Dict[str, List[Callable[[Any], None]]] = defaultdict(list)

    def subscribe(self, topic: str, callback: Callable[[Any], None]) -> None:
        """Register a callback for a topic."""
        if callback not in self._subscribers[topic]:
            self._subscribers[topic].append(callback)

    def unsubscribe(self, topic: str, callback: Callable[[Any], None]) -> None:
        """Remove a callback from a topic if present."""
        if callback in self._subscribers[topic]:
            self._subscribers[topic].remove(callback)
            if not self._subscribers[topic]:
                del self._subscribers[topic]

    def publish(self, topic: str, message: Any) -> None:
        """Send a message to all subscribers of a topic."""
        for callback in list(self._subscribers.get(topic, [])):
            callback(message)


class TemperatureSensor:
    """Publishes temperature updates through the event bus."""

    def __init__(self, bus: EventBus, sensor_name: str) -> None:
        self.bus = bus
        self.sensor_name = sensor_name

    def read_temperature(self, value: float) -> None:
        event = {
            "sensor": self.sensor_name,
            "temperature": value,
        }
        self.bus.publish("temperature", event)


