class OrderStateMachine:
    # Transition table: state -> event -> next_state
    TRANSITIONS = {
        "new": {"pay": "paid", "cancel": "canceled"},
        "paid": {"ship": "shipped", "refund": "refunded"},
        "shipped": {"deliver": "delivered", "return": "returned"},
    }

    TERMINAL_STATES = {"canceled", "refunded", "delivered", "returned"}
    VALID_STATES = set(TRANSITIONS) | TERMINAL_STATES

    def __init__(self, state="new"):
        if state not in self.VALID_STATES:
            raise ValueError(f"Unknown initial state: {state}")
        self.state = state
        self._history = []

    def can_trigger(self, event):
        return event in self.TRANSITIONS.get(self.state, {})

    def trigger(self, event):
        if not self.can_trigger(event):
            raise ValueError(f"Invalid event '{event}' from state '{self.state}'")

        from_state = self.state
        to_state = self.TRANSITIONS[from_state][event]
        self.state = to_state
        self._history.append((from_state, event, to_state))
        return to_state

    def is_terminal(self):
        return self.state in self.TERMINAL_STATES

    def history(self):
        return list(self._history)

    def replay(self, events):
        # Apply all events atomically; rollback on failure.
        original_state = self.state
        original_history = list(self._history)

        try:
            for event in events:
                self.trigger(event)
        except ValueError:
            self.state = original_state
            self._history = original_history
            raise

        return self.state


if __name__ == "__main__":
    fsm = OrderStateMachine()
    print(fsm.trigger("pay"))      # paid
    print(fsm.can_trigger("ship")) # True
    print(fsm.replay(["ship", "deliver"]))
    print(fsm.is_terminal())
    print(fsm.history())

def analyze_permissions(records):
    """Analyze access logs and summarize user/resource relationships."""
    user_permissions = {}
    resource_users = {}

    for record in records:
        # Validate record structure and types
        if not isinstance(record, dict):
            continue
        if not all(k in record for k in ("user", "resource", "actions")):
            continue

        user = record["user"]
        resource = record["resource"]
        actions = record["actions"]

        if not isinstance(user, str) or not isinstance(resource, str) or not isinstance(actions, list):
            continue
        if not all(isinstance(action, str) for action in actions):
            continue

        action_set = set(actions)

        # Accumulate actions per user
        user_permissions.setdefault(user, set()).update(action_set)

        # Accumulate users per resource
        resource_users.setdefault(resource, set()).add(user)

    # Find users who have both granted and revoked permissions
    conflicts = {
        user
        for user, actions in user_permissions.items()
        if {"grant", "revoke"}.intersection(actions) == {"grant", "revoke"}
    }

    return {
        "user_permissions": user_permissions,
        "resource_users": resource_users,
        "conflicts": conflicts,
    }


# Example usage
if __name__ == "__main__":
    logs = [
        {"user": "alice", "resource": "server1", "actions": ["read", "grant"]},
        {"user": "bob", "resource": "server1", "actions": ["read", "write"]},
        {"user": "alice", "resource": "server2", "actions": ["revoke", "write"]},
        {"user": "carol", "resource": "server2", "actions": ["read"]},
        {"user": "eve", "resource": "server3", "actions": "read"},  # invalid
    ]

    result = analyze_permissions(logs)
    for key, value in result.items():
        print(f"{key}: {value}")

import pytest


def apply_discount(price, percent):
    """Return price after applying a percentage discount."""
    if price < 0:
        raise ValueError("price must be non-negative")
    if not 0 <= percent <= 100:
        raise ValueError("percent must be between 0 and 100")
    discounted = price * (1 - percent / 100)
    return round(discounted, 2)


def final_prices(items, percent):
    """Apply the same discount to every price in a list."""
    return [apply_discount(price, percent) for price in items]


