class DisjointSet:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        # Path compression
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)

        if root_a == root_b:
            return False

        # Union by rank
        if self.rank[root_a] < self.rank[root_b]:
            self.parent[root_a] = root_b
        elif self.rank[root_a] > self.rank[root_b]:
            self.parent[root_b] = root_a
        else:
            self.parent[root_b] = root_a
            self.rank[root_a] += 1

        return True


def count_networks(n, connections):
    dsu = DisjointSet(n)

    for a, b in connections:
        dsu.union(a, b)

    # Count unique roots to find number of separate networks
    roots = {dsu.find(i) for i in range(n)}
    return len(roots)


if __name__ == '__main__':
    n = 7
    connections = [[0, 1], [1, 2], [3, 4], [5, 6], [4, 3]]
    print(count_networks(n, connections))  # Output: 3

from typing import List


def min_path_cost_with_coupons(grid: List[List[int]], k: int) -> int:
    """
    Return the minimum path cost from top-left to bottom-right in a grid,
    moving only right or down, while using at most k coupons.
    A coupon makes the cost of one visited cell equal to 0.
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    INF = float('inf')

    # dp[i][j][c] = minimum cost to reach cell (i, j)
    # having used exactly c coupons so far.
    dp = [[[INF] * (k + 1) for _ in range(cols)] for _ in range(rows)]

    # Initialize starting cell: either pay for it or use a coupon on it.
    dp[0][0][0] = grid[0][0]
    if k > 0:
        dp[0][0][1] = 0

    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                continue

            cost = grid[i][j]
            for used in range(k + 1):
                best = INF

                # Transition from top or left without using a coupon here.
                if i > 0:
                    best = min(best, dp[i - 1][j][used] + cost)
                if j > 0:
                    best = min(best, dp[i][j - 1][used] + cost)
                dp[i][j][used] = min(dp[i][j][used], best)

                # Transition from top or left using a coupon on current cell.
                if used > 0:
                    if i > 0:
                        dp[i][j][used] = min(dp[i][j][used], dp[i - 1][j][used - 1])
                    if j > 0:
                        dp[i][j][used] = min(dp[i][j][used], dp[i][j - 1][used - 1])

    return min(dp[rows - 1][cols - 1])


# Example usage
if __name__ == '__main__':
    grid = [
        [5, 1, 4],
        [2, 0, 7],
        [3, 6, 1]
    ]
    k = 2
    print(min_path_cost_with_coupons(grid, k))

from abc import ABC, abstractmethod
from typing import List, Tuple


class ReportBuilder(ABC):
    @abstractmethod
    def add_title(self, title: str) -> None:
        pass

    @abstractmethod
    def add_line(self, line: str) -> None:
        pass

    @abstractmethod
    def build(self) -> str:
        pass


class TextReportBuilder(ReportBuilder):
    def __init__(self) -> None:
        self.parts: List[str] = []

    def add_title(self, title: str) -> None:
        self.parts.append(f"=== {title} ===")

    def add_line(self, line: str) -> None:
        self.parts.append(line)

    def build(self) -> str:
        return "\n".join(self.parts)


class HtmlReportBuilder(ReportBuilder):
    def __init__(self) -> None:
        self.title = ""
        self.lines: List[str] = []

    def add_title(self, title: str) -> None:
        self.title = f"<h1>{title}</h1>"

    def add_line(self, line: str) -> None:
        self.lines.append(f"<li>{line}</li>")

    def build(self) -> str:
        return f"<html><body>{self.title}<ul>{''.join(self.lines)}</ul></body></html>"


class ReportBuilderFactory:
    @staticmethod
    def create_builder(format_type: str) -> ReportBuilder:
        builders = {
            "text": TextReportBuilder,
            "html": HtmlReportBuilder,
        }
        try:
            return builders[format_type.lower()]()
        except KeyError:
            raise ValueError(f"Unsupported format: {format_type}")


def build_sales_report(format_type: str, title: str, items: List[Tuple[str, float]]) -> str:
    builder = ReportBuilderFactory.create_builder(format_type)
    builder.add_title(title)

    total = 0.0
    for name, amount in items:
        total += amount
        builder.add_line(f"{name}: ${amount:.2f}")

    builder.add_line(f"Total: ${total:.2f}")
    return builder.build()


if __name__ == "__main__":
    sales = [("Laptop", 1200.0), ("Mouse", 25.5), ("Keyboard", 75.0)]
    print(build_sales_report("text", "Daily Sales", sales))
    print()
    print(build_sales_report("html", "Daily Sales", sales))

