from collections import defaultdict, deque
from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any, Deque, Dict, Iterable, List, Optional, Set, TextIO, Tuple


class FraudDetectionError(Exception):
    """Base exception for fraud detection errors."""


class InvalidSchemaError(FraudDetectionError):
    """Raised when the CSV schema is invalid or required columns are missing."""


class CorruptedInputDataError(FraudDetectionError):
    """Raised when the input data is corrupted in a way that prevents processing."""


@dataclass(frozen=True)
class DetectionConfig:
    amount_threshold: Decimal
    min_outgoing_transactions: int = 5
    min_distinct_destinations: int = 3
    rolling_window: timedelta = timedelta(minutes=10)
    source_account_field: str = "source_account_id"
    destination_account_field: str = "destination_account_id"
    amount_field: str = "amount"
    timestamp_field: str = "timestamp"
    csv_encoding: str = "utf-8"
    csv_dialect: str = "excel"

    def __post_init__(self) -> None:
        if self.amount_threshold < 0:
            raise ValueError("amount_threshold must be non-negative")
        if self.min_outgoing_transactions <= 0:
            raise ValueError("min_outgoing_transactions must be positive")
        if self.min_distinct_destinations <= 0:
            raise ValueError("min_distinct_destinations must be positive")
        if self.rolling_window.total_seconds() <= 0:
            raise ValueError("rolling_window must be positive")


@dataclass(frozen=True)
class TransactionRecord:
    source_account_id: str
    destination_account_id: str
    amount: Decimal
    timestamp: datetime
    row_number: int


@dataclass(frozen=True)
class MalformedRow:
    row_number: int
    raw_row: Dict[str, Any]
    error: str


@dataclass
class AccountDetection:
    account_id: str
    first_detected_at: datetime
    transaction_count: int
    distinct_destination_count: int
    total_amount: Decimal
    window_start: datetime
    window_end: datetime
    destination_accounts: Tuple[str, ...] = field(default_factory=tuple)


@dataclass
class FraudDetectionResult:
    flagged_accounts: Dict[str, AccountDetection]
    malformed_rows: List[MalformedRow]
    processed_rows: int
    valid_transactions: int


def _parse_timestamp(value: str) -> datetime:
    text = value.strip()
    if not text:
        raise ValueError("empty timestamp")
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        dt = datetime.fromisoformat(text)
    except ValueError as exc:
        raise ValueError(f"invalid ISO timestamp: {value!r}") from exc
    if dt.tzinfo is None:
        raise ValueError("timestamp must be timezone-aware")
    return dt.astimezone(timezone.utc)


def _parse_amount(value: str) -> Decimal:
    text = value.strip()
    if not text:
        raise ValueError("empty amount")
    try:
        amount = Decimal(text)
    except (InvalidOperation, ValueError) as exc:
        raise ValueError(f"invalid amount: {value!r}") from exc
    if not amount.is_finite():
        raise ValueError(f"non-finite amount: {value!r}")
    if amount < 0:
        raise ValueError(f"negative amount: {value!r}")
    return amount


def _validate_schema(fieldnames: Optional[List[str]], config: DetectionConfig) -> None:
    if not fieldnames:
        raise InvalidSchemaError("CSV header is missing or empty")
    required = {
        config.source_account_field,
        config.destination_account_field,
        config.amount_field,
        config.timestamp_field,
    }
    missing = required.difference(fieldnames)
    if missing:
        raise InvalidSchemaError(f"CSV is missing required columns: {sorted(missing)}")


def _parse_transaction_row(
    row: Dict[str, Any],
    row_number: int,
    config: DetectionConfig,
) -> TransactionRecord:
    try:
        source = str(row[config.source_account_field]).strip()
        destination = str(row[config.destination_account_field]).strip()
        amount_raw = str(row[config.amount_field])
        timestamp_raw = str(row[config.timestamp_field])
    except KeyError as exc:
        raise InvalidSchemaError(f"missing required column in row {row_number}: {exc}") from exc

    if not source:
        raise ValueError("empty source_account_id")
    if not destination:
        raise ValueError("empty destination_account_id")

    amount = _parse_amount(amount_raw)
    timestamp = _parse_timestamp(timestamp_raw)

    return TransactionRecord(
        source_account_id=source,
        destination_account_id=destination,
        amount=amount,
        timestamp=timestamp,
        row_number=row_number,
    )


def _iter_transactions(
    file_obj: TextIO,
    config: DetectionConfig,
) -> Tuple[Iterable[TransactionRecord], List[MalformedRow], int]:
    malformed_rows: List[MalformedRow] = []
    processed_rows = 0

    try:
        reader = csv.DictReader(file_obj, dialect=config.csv_dialect)
    except csv.Error as exc:
        raise CorruptedInputDataError(f"failed to initialize CSV reader: {exc}") from exc

    _validate_schema(reader.fieldnames, config)

    def generator() -> Iterable[TransactionRecord]:
        nonlocal processed_rows
        for row_number, row in enumerate(reader, start=2):
            processed_rows += 1
            if row is None:
                malformed_rows.append(
                    MalformedRow(
                        row_number=row_number,
                        raw_row={},
                        error="encountered null row",
                    )
                )
                continue
            try:
                yield _parse_transaction_row(row, row_number, config)
            except (ValueError, TypeError) as exc:
                malformed_rows.append(
                    MalformedRow(
                        row_number=row_number,
                        raw_row=dict(row),
                        error=str(exc),
                    )
                )
            except csv.Error as exc:
                raise CorruptedInputDataError(
                    f"CSV parsing error at row {row_number}: {exc}"
                ) from exc

    return generator(), malformed_rows, processed_rows


def detect_rapid_transfer_laundering(
    csv_path: str | Path,
    *,
    amount_threshold: Decimal | str | int | float,
    min_outgoing_transactions: int = 5,
    min_distinct_destinations: int = 3,
    rolling_window_minutes: int = 10,
    source_account_field: str = "source_account_id",
    destination_account_field: str = "destination_account_id",
    amount_field: str = "amount",
    timestamp_field: str = "timestamp",
    csv_encoding: str = "utf-8",
    csv_dialect: str = "excel",
) -> FraudDetectionResult:
    config = DetectionConfig(
        amount_threshold=Decimal(str(amount_threshold)),
        min_outgoing_transactions=min_outgoing_transactions,
        min_distinct_destinations=min_distinct_destinations,
        rolling_window=timedelta(minutes=rolling_window_minutes),
        source_account_field=source_account_field,
        destination_account_field=destination_account_field,
        amount_field=amount_field,
        timestamp_field=timestamp_field,
        csv_encoding=csv_encoding,
        csv_dialect=csv_dialect,
    )

    path = Path(csv_path)
    if not path.exists():
        raise FileNotFoundError(f"CSV file not found: {path}")
    if not path.is_file():
        raise FileNotFoundError(f"path is not a file: {path}")

    flagged_accounts: Dict[str, AccountDetection] = {}
    account_windows: Dict[str, Deque[TransactionRecord]] = defaultdict(deque)
    valid_transactions = 0

    try:
        with path.open("r", encoding=config.csv_encoding, newline="") as file_obj:
            transactions, malformed_rows, processed_rows_ref = _iter_transactions(file_obj, config)

            processed_rows = 0
            for tx in transactions:
                valid_transactions += 1
                processed_rows += 1
                window = account_windows[tx.source_account_id]
                window.append(tx)

                cutoff = tx.timestamp - config.rolling_window
                while window and window[0].timestamp < cutoff:
                    window.popleft()

                if tx.source_account_id in flagged_accounts:
                    continue

                transaction_count = len(window)
                if transaction_count < config.min_outgoing_transactions:
                    continue

                distinct_destinations: Set[str] = {item.destination_account_id for item in window}
                if len(distinct_destinations) < config.min_distinct_destinations:
                    continue

                total_amount = sum((item.amount for item in window), Decimal("0"))
                if total_amount <= config.amount_threshold:
                    continue

                flagged_accounts[tx.source_account_id] = AccountDetection(
                    account_id=tx.source_account_id,
                    first_detected_at=tx.timestamp,
                    transaction_count=transaction_count,
                    distinct_destination_count=len(distinct_destinations),
                    total_amount=total_amount,
                    window_start=window[0].timestamp,
                    window_end=window[-1].timestamp,
                    destination_accounts=tuple(sorted(distinct_destinations)),
                )

            return FraudDetectionResult(
                flagged_accounts=flagged_accounts,
                malformed_rows=malformed_rows,
                processed_rows=processed_rows_ref,
                valid_transactions=valid_transactions,
            )
    except UnicodeDecodeError as exc:
        raise CorruptedInputDataError(f"failed to decode CSV input: {exc}") from exc
    except csv.Error as exc:
        raise CorruptedInputDataError(f"CSV parsing failed: {exc}") from exc


__all__ = [
    "FraudDetectionError",
    "InvalidSchemaError",
    "CorruptedInputDataError",
    "DetectionConfig",
    "TransactionRecord",
