]

class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            print(f"Deposited ${amount}. New balance: ${self.balance}")
        else:
            print("Deposit amount must be positive.")

    def withdraw(self, amount):
        if amount <= 0:
            print("Withdrawal amount must be positive.")
        elif amount > self.balance:
            print("Insufficient funds.")
        else:
            self.balance -= amount
            print(f"Withdrew ${amount}. New balance: ${self.balance}")

    def display_info(self):
        print(f"Account owner: {self.owner}")
        print(f"Current balance: ${self.balance}")


# Example usage
account = BankAccount("Alice", 100)
account.display_info()
print()

account.deposit(50)
account.withdraw(30)
account.withdraw(150)
account.deposit(-10)
print()

account.display_info()

import time
from collections import deque
from functools import wraps


def rate_limited_cache(max_calls, window_seconds):
    """Decorator factory that adds caching and sliding-window rate limiting."""
    def decorator(func):
        cache = {}
        call_times = deque()  # Timestamps of real executions
        hits = 0
        misses = 0

        def make_key(args, kwargs):
            # Build a hashable cache key from positional and keyword arguments.
            return args, tuple(sorted(kwargs.items()))

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = make_key(args, kwargs)

            # Cached results do not consume rate limit.
            if key in cache:
                hits += 1
                return cache[key]

            now = time.monotonic()

            # Drop timestamps outside the active time window.
            while call_times and now - call_times[0] >= window_seconds:
                call_times.popleft()

            if len(call_times) >= max_calls:
                raise RuntimeError(
                    f"Rate limit exceeded: max {max_calls} calls per {window_seconds} seconds"
                )

            result = func(*args, **kwargs)
            cache[key] = result
            call_times.append(now)
            misses += 1
            return result

        def cache_clear():
            cache.clear()
            call_times.clear()

        def stats():
            return {
                "hits": hits,
                "misses": misses,
                "cached_keys": len(cache),
            }

        wrapper.cache_clear = cache_clear
        wrapper.stats = stats
        return wrapper

    return decorator


# Example usage
@rate_limited_cache(max_calls=3, window_seconds=5)
def expensive_add(a, b, scale=1):
    return (a + b) * scale

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_word = False
        self.prefix_count = 0  # Number of words passing through this node


class PrefixTrie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            node.prefix_count += 1
        node.is_word = True

    def search(self, word: str) -> bool:
        node = self._find_node(word)
        return node is not None and node.is_word

    def starts_with(self, prefix: str) -> bool:
        return self._find_node(prefix) is not None

    def count_prefix(self, prefix: str) -> int:
        node = self._find_node(prefix)
        return node.prefix_count if node else 0

    def _find_node(self, text: str):
        node = self.root
        for ch in text:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node


def main():
    trie = PrefixTrie()
    words = ["apple", "app", "apex", "bat", "batch", "banana"]

    for word in words:
        trie.insert(word)

    print(trie.search("app"))         # True
    print(trie.search("apply"))       # False
    print(trie.starts_with("ap"))     # True
    print(trie.starts_with("cat"))    # False
    print(trie.count_prefix("app"))   # 2
    print(trie.count_prefix("ba"))    # 3
    print(trie.count_prefix("z"))     # 0


if __name__ == "__main__":
    main()
}

class TextEditor:
    def __init__(self):
        self.content = ""

    def append(self, text):
        self.content += text

    def delete(self, count):
        removed = self.content[-count:] if count <= len(self.content) else self.content
        self.content = self.content[:-count] if count <= len(self.content) else ""
        return removed


class Command:
    def execute(self):
        raise NotImplementedError

    def undo(self):
        raise NotImplementedError


class AppendCommand(Command):
    def __init__(self, editor, text):
        self.editor = editor
        self.text = text

    def execute(self):
        self.editor.append(self.text)

    def undo(self):
        self.editor.delete(len(self.text))


class DeleteCommand(Command):
    def __init__(self, editor, count):
        self.editor = editor
        self.count = count
        self.deleted_text = ""

    def execute(self):
        self.deleted_text = self.editor.delete(self.count)

    def undo(self):
        self.editor.append(self.deleted_text)


class CommandManager:
    def __init__(self):
        self.history = []

    def run(self, command):
        command.execute()
        self.history.append(command)

    def undo(self):
        if self.history:
            command = self.history.pop()
            command.undo()


if __name__ == "__main__":
    editor = TextEditor()
    manager = CommandManager()

    manager.run(AppendCommand(editor, "Hello"))
    print(editor.content)  # Hello

    manager.run(AppendCommand(editor, " World"))
    print(editor.content)  # Hello World

    manager.run(DeleteCommand(editor, 6))
    print(editor.content)  # Hello

    manager.undo()
    print(editor.content)  # Hello World

    manager.undo()
    print(editor.content)  # Hello

class LogParser:
    """Iterates over parsed ERROR log entries from a list of log lines."""

    def __init__(self, lines):
        self.lines = lines
        self.index = 0

    def __iter__(self):
        return self

    def __next__(self):
        while self.index < len(self.lines):
            line = self.lines[self.index]
            self.index += 1

            parts = line.strip().split("|", 2)
            if len(parts) != 3:
                continue  # Skip malformed lines

            date, level, message = parts
            if level != "ERROR":
                continue  # Skip non-error entries

            return {
                "date": date,
                "level": level,
                "message": message
            }

        raise StopIteration


def error_messages(parser):
    """Yield uppercase messages from parsed ERROR log entries."""
    for entry in parser:
        yield entry["message"].upper()


if __name__ == "__main__":
    logs = [
        "2024-01-10|INFO|System started",
        "2024-01-10|ERROR|Disk space low",
        "invalid log line",
        "2024-01-11|WARNING|High memory usage",
        "2024-01-11|ERROR|Connection timeout",
        "2024-01-12|ERROR|Failed to load config"
    ]

    parser = LogParser(logs)
    for message in error_messages(parser):
        print(message)

class Car:
    def describe(self):
        return "Car: 4 wheels, good for families."


class Bike:
    def describe(self):
        return "Bike: 2 wheels, easy to park."


class VehicleFactory:
    def create_vehicle(self, vehicle_type):
        """Return a vehicle object based on the given type."""
        if vehicle_type == "car":
            return Car()
        elif vehicle_type == "bike":
            return Bike()
        else:
            raise ValueError(f"Unknown vehicle type: {vehicle_type}")


class ReportBuilder:
    def __init__(self):
        self.parts = []

    def add_title(self, title):
        self.parts.append(f"=== {title} ===")
        return self  # Allow method chaining

    def add_vehicle(self, vehicle):
        self.parts.append(vehicle.describe())
        return self

    def build(self):
        return "\n".join(self.parts)


if __name__ == "__main__":
    factory = VehicleFactory()

    # Create vehicles using the factory pattern
    car = factory.create_vehicle("car")
    bike = factory.create_vehicle("bike")

    # Build a report using the builder pattern
    report = (
        ReportBuilder()
        .add_title("Vehicle Report")
        .add_vehicle(car)
        .add_vehicle(bike)
        .build()
    )

    print(report)

from __future__ import annotations

from dataclasses import dataclass
from datetime import date, datetime
from typing import Any, Dict, Iterable, List, Optional, Union


DateLike = Union[str, date, datetime]


@dataclass(frozen=True)
class Transaction:
    date: date
    description: str
    amount: float
    category: str

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "Transaction":
        return cls(
            date=cls._parse_date(data["date"]),
            description=str(data.get("description", "")),
            amount=float(data.get("amount", 0.0)),
            category=str(data.get("category", "Uncategorized")),
        )

    @staticmethod
    def _parse_date(value: DateLike) -> date:
        if isinstance(value, datetime):
            return value.date()
        if isinstance(value, date):
            return value
        if isinstance(value, str):
            for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%m/%d/%Y", "%d/%m/%Y"):
                try:
                    return datetime.strptime(value, fmt).date()
                except ValueError:
                    continue
        raise ValueError(f"Unsupported date format: {value!r}")

    @property
    def is_income(self) -> bool:
        return self.amount > 0

    @property
    def spending_amount(self) -> float:
        return abs(self.amount) if self.amount < 0 else 0.0


class BudgetAnalyzer:
    def __init__(self, transactions: Iterable[Union[Transaction, Dict[str, Any]]], budget_config: Dict[str, float]):
        self.transactions: List[Transaction] = [self._to_transaction(t) for t in transactions]
        self.budget_config: Dict[str, float] = {
            str(category): float(limit) for category, limit in budget_config.items()
        }

    @staticmethod
    def _to_transaction(item: Union[Transaction, Dict[str, Any]]) -> Transaction:
        if isinstance(item, Transaction):
            return item
        if isinstance(item, dict):
            return Transaction.from_dict(item)
        raise TypeError("Each transaction must be a Transaction instance or a dictionary.")

    def analyze_month(self, year: int, month: int) -> Dict[str, Any]:
        if not 1 <= month <= 12:
            raise ValueError("month must be between 1 and 12")

        monthly_transactions = [
            t for t in self.transactions
            if t.date.year == year and t.date.month == month
        ]

        spending_by_category: Dict[str, float] = {}
        income_count = 0

        for transaction in monthly_transactions:
            if transaction.is_income:
                income_count += 1
                continue

            category = transaction.category or "Uncategorized"
            spending_by_category[category] = spending_by_category.get(category, 0.0) + transaction.spending_amount

        all_categories = set(spending_by_category.keys()) | set(self.budget_config.keys())
        category_summaries: List[Dict[str, Any]] = []

        for category in sorted(all_categories):
            spent = round(spending_by_category.get(category, 0.0), 2)
            budget = self.budget_config.get(category)
            over_budget = budget is not None and spent > budget

            if budget is None:
                budget_used_pct: Optional[float] = None
                remaining_budget: Optional[float] = None
            elif budget == 0:
                budget_used_pct = 100.0 if spent > 0 else 0.0
                remaining_budget = round(-spent, 2) if spent > 0 else 0.0
            else:
                budget_used_pct = round((spent / budget) * 100, 2)
                remaining_budget = round(budget - spent, 2)

            category_summaries.append(
                {
                    "category": category,
                    "spent": spent,
                    "budget": round(budget, 2) if budget is not None else None,
                    "budget_used_pct": budget_used_pct,
                    "over_budget": over_budget,
                    "remaining_budget": remaining_budget,
                    "has_budget": budget is not None,
                }
            )

        total_spent = round(sum(spending_by_category.values()), 2)
        total_budget = round(sum(self.budget_config.values()), 2) if self.budget_config else 0.0
        over_budget_categories = [item["category"] for item in category_summaries if item["over_budget"]]

        return {
            "month": f"{year:04d}-{month:02d}",
            "total_spent": total_spent,
            "total_budget": total_budget,
            "categories": category_summaries,
            "over_budget_categories": over_budget_categories,
            "transaction_count": len(monthly_transactions),
            "expense_transaction_count": sum(1 for t in monthly_transactions if not t.is_income),
            "income_transaction_count": income_count,
        }


def summarize_monthly_budget(
    transactions: Iterable[Union[Transaction, Dict[str, Any]]],
    budget_config: Dict[str, float],
    year: int,
    month: int,
) -> Dict[str, Any]:
    analyzer = BudgetAnalyzer(transactions, budget_config)
    return analyzer.analyze_month(year, month)

class BloomFilter:
    def __init__(self, size, num_hashes):
        # Size of the bit array and number of hash functions
        self.size = size
        self.num_hashes = num_hashes
        self.bits = [0] * size

    def _get_positions(self, item):
        # Generate multiple positions for the item
        positions = []
        for i in range(self.num_hashes):
            # Combine item with index to simulate different hash functions
            position = hash(f"{item}-{i}") % self.size
            positions.append(position)
        return positions

    def add(self, item):
        # Set all relevant bit positions to 1
        for pos in self._get_positions(item):
            self.bits[pos] = 1

    def might_contain(self, item):
        # If any required bit is 0, the item is definitely not present
        for pos in self._get_positions(item):
            if self.bits[pos] == 0:
                return False
        return True


# Example usage
if __name__ == "__main__":
    bloom = BloomFilter(size=20, num_hashes=3)

    words_to_add = ["apple", "banana", "grape"]
    for word in words_to_add:
        bloom.add(word)

    test_words = ["apple", "banana", "orange", "melon", "grape"]
    for word in test_words:
        print(f"{word}: {bloom.might_contain(word)}")

class BasicTradingBot:
    def __init__(self, prices, starting_cash=1000.0):
        self.prices = prices
        self.cash_balance = float(starting_cash)
        self.shares_owned = 0
        self.trade_log = []

    def _is_valid_price_list(self):
        return isinstance(self.prices, list) and len(self.prices) > 0

    def update_balance_after_trade(self, action, price, day):
        if action == "BUY":
            self.cash_balance -= price
            self.shares_owned += 1
        elif action == "SELL":
            self.cash_balance += price
            self.shares_owned -= 1

        self.trade_log.append(
            {
                "day": day,
                "action": action,
                "price": price,
                "cash_balance": round(self.cash_balance, 2),
                "shares_owned": self.shares_owned,
            }
        )

    def run_strategy(self):
        if not self._is_valid_price_list():
            raise ValueError("Price list cannot be empty and must be a list.")

        if len(self.prices) == 1:
            return self.trade_log

        for day in range(1, len(self.prices)):
            previous_price = self.prices[day - 1]
            current_price = self.prices[day]

            if current_price < previous_price:
                if self.cash_balance >= current_price:
                    self.update_balance_after_trade("BUY", current_price, day)
            elif current_price > previous_price:
                if self.shares_owned > 0:
                    self.update_balance_after_trade("SELL", current_price, day)

        return self.trade_log

    def get_final_portfolio_value(self):
        if not self._is_valid_price_list():
            raise ValueError("Price list cannot be empty and must be a list.")

        last_price = self.prices[-1]
        return round(self.cash_balance + (self.shares_owned * last_price), 2)


if __name__ == "__main__":
