        print(trade)

    print("\nFinal Cash Balance:", round(bot.cash_balance, 2))
    print("Shares Owned:", bot.shares_owned)
    print("Final Portfolio Value:", bot.get_final_portfolio_value())

import re
from typing import Callable, Dict, List, Optional, Pattern, Tuple


class Router:
    # Supported path converters and their regex/type casters.
    CONVERTERS = {
        'str': (r'[^/]+', str),
        'int': (r'\d+', int),
        'slug': (r'[a-z0-9]+(?:-[a-z0-9]+)*', str),
    }

    def __init__(self) -> None:
        self._routes: List[Tuple[Pattern[str], Dict[str, Callable[[str], object]], str]] = []

    def add_route(self, pattern: str, handler_name: str) -> None:
        regex_parts = ['^']
        casters: Dict[str, Callable[[str], object]] = {}
        pos = 0

        # Find placeholders like <int:user_id> or <name> (defaults to str).
        for match in re.finditer(r'<(?:(\w+):)?(\w+)>', pattern):
            start, end = match.span()
            converter_name, param_name = match.groups()
            converter_name = converter_name or 'str'

            if converter_name not in self.CONVERTERS:
                raise ValueError(f'Unsupported converter: {converter_name}')
            if param_name in casters:
                raise ValueError(f'Duplicate parameter name: {param_name}')

            regex_parts.append(re.escape(pattern[pos:start]))
            regex_pattern, caster = self.CONVERTERS[converter_name]
            regex_parts.append(f'(?P<{param_name}>{regex_pattern})')
            casters[param_name] = caster
            pos = end

        regex_parts.append(re.escape(pattern[pos:]))
        regex_parts.append('$')
        compiled = re.compile(''.join(regex_parts))
        self._routes.append((compiled, casters, handler_name))

    def match(self, path: str) -> Optional[Tuple[str, Dict[str, object]]]:
        for regex, casters, handler_name in self._routes:
            match = regex.match(path)
            if not match:
                continue

            params = {
                name: casters[name](value)
                for name, value in match.groupdict().items()
            }
            return handler_name, params
        return None


if __name__ == '__main__':
    router = Router()
    router.add_route('/users/<int:user_id>', 'user_detail')
    router.add_route('/users/<int:user_id>/posts/<slug:post_slug>', 'post_detail')
    router.add_route('/assets/<path>', 'invalid_example') if False else None  # ignored example
    router.add_route('/pages/<page_name>', 'page_detail')

    test_paths = [
        '/users/42',
        '/users/42/posts/advanced-routing-patterns',
        '/pages/about',
        '/users/not-a-number',
        '/missing/path',
    ]

    for path in test_paths:
        print(f'{path} -> {router.match(path)}')

import json
from html.parser import HTMLParser
import xml.etree.ElementTree as ET

HTML_DOC = """
<html><body>
  <table>
    <tr><th>ID</th><th>Value</th></tr>
    <tr><td>1</td><td>Ignore me</td></tr>
  </table>
  <table>
    <tr><th>Email</th><th>Name</th><th>Department</th><th>Role</th></tr>
    <tr><td>alice@example.com</td><td>Alice Smith</td><td>Engineering</td><td>Developer</td></tr>
    <tr><td>bob@example.com</td><td>Bob Jones</td><td>Support</td><td>Analyst</td></tr>
    <tr><td>carol@example.com</td><td>Carol White</td><td>HR</td><td>Manager</td></tr>
  </table>
</body></html>
"""

XML_DOC = """
<employees>
  <employee><name>Alice Smith</name><status>active</status></employee>
  <employee><name>Bob Jones</name><status>inactive</status></employee>
  <employee><name>Carol White</name><status>active</status></employee>
</employees>
"""


class TableExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tables = []
        self.current_table = None
        self.current_row = None
        self.current_cell = None
        self.in_cell = False

    def handle_starttag(self, tag, attrs):
        if tag == 'table':
            self.current_table = []
        elif tag == 'tr' and self.current_table is not None:
            self.current_row = []
        elif tag in ('th', 'td') and self.current_row is not None:
            self.in_cell = True
            self.current_cell = []

    def handle_data(self, data):
        if self.in_cell:
            self.current_cell.append(data)

    def handle_endtag(self, tag):
        if tag in ('th', 'td') and self.in_cell:
            text = ''.join(self.current_cell).strip()
            self.current_row.append(text)
            self.in_cell = False
        elif tag == 'tr' and self.current_row is not None:
            self.current_table.append(self.current_row)
            self.current_row = None
        elif tag == 'table' and self.current_table is not None:
            self.tables.append(self.current_table)
            self.current_table = None


def normalize(text):
    return ' '.join(text.strip().lower().split())


def extract_target_table(html):
    parser = TableExtractor()
    parser.feed(html)
    required = {'name', 'role', 'email'}

    for table in parser.tables:
        if not table:
            continue
        headers = [normalize(h) for h in table[0]]
        if required.issubset(headers):
            indices = {h: headers.index(h) for h in required}
            rows = []
            for row in table[1:]:
                record = {}
                for key, idx in indices.items():
                    record[key] = row[idx].strip() if idx < len(row) else ''
                rows.append(record)
            return rows
    return []


def parse_employee_statuses(xml_text):
    root = ET.fromstring(xml_text)
    statuses = {}
    for emp in root.findall('employee'):
        name = emp.findtext('name', default='').strip()
        status = emp.findtext('status', default='').strip()
        if name:
            statuses[normalize(name)] = status
    return statuses


def merge_records(html_records, status_map):
    for record in html_records:
        record['status'] = status_map.get(normalize(record['name']), 'unknown')
    return html_records


def main():
    html_records = extract_target_table(HTML_DOC)
    status_map = parse_employee_statuses(XML_DOC)
    merged = merge_records(html_records, status_map)
    print(json.dumps(merged, indent=2))


if __name__ == '__main__':
    main()
}

from math import sqrt


def mean(values):
    return sum(values) / len(values)


def sample_std(values):
    n = len(values)
    if n < 2:
        raise ValueError("At least two values are required for sample standard deviation.")
    mu = mean(values)
    variance = sum((x - mu) ** 2 for x in values) / (n - 1)
    return sqrt(variance)


def correlation(x, y):
    if len(x) != len(y) or len(x) < 2:
        raise ValueError("Series must have the same length and contain at least two values.")
    mx, my = mean(x), mean(y)
    sx, sy = sample_std(x), sample_std(y)
    if sx == 0 or sy == 0:
        raise ValueError("Correlation is undefined for a series with zero variance.")
    cov = sum((a - mx) * (b - my) for a, b in zip(x, y)) / (len(x) - 1)
    return cov / (sx * sy)


def historical_var(returns, confidence=0.95):
    if not returns:
        raise ValueError("Return series cannot be empty.")
    sorted_returns = sorted(returns)
    rank = max(1, int((1 - confidence) * len(sorted_returns) + 0.9999999999))
    percentile_value = sorted_returns[rank - 1]
    return max(0.0, -percentile_value)


def main():
    assets = {
        "Equity": [0.012, -0.018, 0.007, 0.021, -0.004, 0.015, -0.011, 0.009],
        "Bonds": [0.004, 0.006, 0.005, 0.003, 0.004, 0.005, 0.002, 0.004],
        "Gold": [-0.003, 0.011, 0.008, -0.002, 0.014, -0.001, 0.006, 0.007],
        "REIT": [0.009, -0.012, 0.004, 0.016, -0.003, 0.011, -0.007, 0.005],
    }

    lengths = {len(series) for series in assets.values()}
    if len(lengths) != 1 or 0 in lengths:
        raise ValueError("All assets must have equal, nonzero-length return series.")

    asset_names = list(assets.keys())
    periods = len(next(iter(assets.values())))
    weight = 1 / len(asset_names)

    asset_stats = {}
    for name, series in assets.items():
        asset_stats[name] = {
            "mean": mean(series),
            "std": sample_std(series),
        }

    portfolio_returns = [
        sum(assets[name][i] * weight for name in asset_names)
        for i in range(periods)
    ]

    portfolio_mean = mean(portfolio_returns)
    portfolio_std = sample_std(portfolio_returns)
    portfolio_var_95 = historical_var(portfolio_returns, confidence=0.95)

    corr_matrix = {
        a: {b: correlation(assets[a], assets[b]) for b in asset_names}
        for a in asset_names
    }

    print("ASSET STATISTICS")
    print(f"{'Asset':<10}{'Mean':>12}{'Std Dev':>12}")
    for name in asset_names:
        print(f"{name:<10}{asset_stats[name]['mean']:>12.4f}{asset_stats[name]['std']:>12.4f}")

    print("\nPORTFOLIO STATISTICS")
    print(f"Equal weight per asset: {weight:.4f}")
    print(f"Mean return:           {portfolio_mean:.4f}")
    print(f"Sample std dev:        {portfolio_std:.4f}")
    print(f"95% historical VaR:    {portfolio_var_95:.4f}")

    print("\nCORRELATION MATRIX")
    print(f"{'':<10}" + "".join(f"{name:>10}" for name in asset_names))
    for a in asset_names:
        row = f"{a:<10}" + "".join(f"{corr_matrix[a][b]:>10.4f}" for b in asset_names)
        print(row)


if __name__ == "__main__":
    main()

from abc import ABC, abstractmethod


class Notifier(ABC):
    """Abstract base class for all notification channels."""

    @property
    @abstractmethod
    def channel(self) -> str:
        """Return the channel name (e.g. 'email', 'sms')."""
        raise NotImplementedError

    @abstractmethod
    def send(self, message: str) -> str:
        """Send a message and return a delivery description."""
        raise NotImplementedError

    @staticmethod
    def notify_all(message: str, notifiers: list["Notifier"]) -> list[str]:
        """Send the same message through each notifier."""
        return [notifier.send(message) for notifier in notifiers]


class EmailNotifier(Notifier):
    def __init__(self, email: str) -> None:
        if "@" not in email or email.startswith("@") or email.endswith("@"):
            raise ValueError("Invalid email address")
        self._email = email

    @property
    def channel(self) -> str:
        return "email"

    def send(self, message: str) -> str:
        return f"[{self.channel}] Sent to {self._email}: {message}"


class SMSNotifier(Notifier):
    def __init__(self, phone_number: str) -> None:
        digits = phone_number.replace("+", "", 1)
        if not digits.isdigit() or len(digits) < 10:
            raise ValueError("Invalid phone number")
        self._phone_number = phone_number

    @property
    def channel(self) -> str:
        return "sms"

    def send(self, message: str) -> str:
        return f"[{self.channel}] Sent to {self._phone_number}: {message}"


def main() -> None:
    notifiers: list[Notifier] = [
        EmailNotifier("user@example.com"),
        SMSNotifier("+12345678901"),
    ]

    results = Notifier.notify_all("System maintenance at 10 PM.", notifiers)
    for result in results:
        print(result)


if __name__ == "__main__":
    main()

