def parse_comment_count(text: str) -> int:
    text = text.strip().lower()
    if text == 'discuss':
        return 0
    try:
        return int(text.split()[0])
    except (ValueError, IndexError):
        return 0


def fetch_html(url: str) -> str:
    response = requests.get(url, headers=HEADERS, timeout=10)
    response.raise_for_status()
    return response.text


def scrape_hacker_news() -> list:
    html = fetch_html(BASE_URL)
    soup = BeautifulSoup(html, 'html.parser')
    stories = []

    for row in soup.select('tr.athing'):
        rank_el = row.select_one('span.rank')
        title_el = row.select_one('span.titleline > a')
        subtext_row = row.find_next_sibling('tr')

        rank = int(rank_el.get_text(strip=True).rstrip('.')) if rank_el else None
        title = title_el.get_text(strip=True) if title_el else None
        story_url = urljoin(BASE_URL, title_el['href']) if title_el and title_el.has_attr('href') else None

        score_el = subtext_row.select_one('span.score') if subtext_row else None
        author_el = subtext_row.select_one('a.hnuser') if subtext_row else None
        age_el = subtext_row.select_one('span.age') if subtext_row else None
        links = subtext_row.select('a') if subtext_row else []
        comments_el = links[-1] if links else None

        score = 0
        if score_el:
            try:
                score = int(score_el.get_text(strip=True).split()[0])
            except (ValueError, IndexError):
                score = 0

        stories.append({
            'rank': rank,
            'title': title,
            'url': story_url,
            'score': score,
            'author': author_el.get_text(strip=True) if author_el else None,
            'age': age_el.get_text(strip=True) if age_el else None,
            'comments': parse_comment_count(comments_el.get_text(strip=True)) if comments_el else 0
        })

    return sorted(stories, key=lambda item: item['rank'] if item['rank'] is not None else float('inf'))


if __name__ == '__main__':
    data = scrape_hacker_news()
    print(json.dumps(data, indent=2, ensure_ascii=False))

class PositiveNumber:
    """Descriptor that ensures assigned values are positive numbers."""

    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, (int, float)):
            raise TypeError(f"{self.private_name[1:]} must be a number")
        if value <= 0:
            raise ValueError(f"{self.private_name[1:]} must be positive")
        setattr(instance, self.private_name, float(value))


class Product:
    price = PositiveNumber()
    weight = PositiveNumber()

    def __init__(self, name, price, weight, discount=0):
        self.name = name
        self.price = price
        self.weight = weight
        self._discount = 0
        self.discount = discount

    @property
    def discount(self):
        return self._discount

    @discount.setter
    def discount(self, value):
        if not isinstance(value, (int, float)):
            raise TypeError("discount must be a number")
        if not 0 <= value <= 50:
            raise ValueError("discount must be between 0 and 50")
        self._discount = float(value)

    @property
    def final_price(self):
        return self.price * (1 - self.discount / 100)


