from __future__ import annotations

from dataclasses import dataclass, replace
from typing import Mapping, Any


@dataclass(frozen=True)
class AppConfig:
    host: str = "127.0.0.1"
    port: int = 8000
    debug: bool = False
    tags: tuple[str, ...] = ()

    @classmethod
    def from_dict(cls, data: Mapping[str, object]) -> "AppConfig":
        return cls(
            host=cls._parse_host(data.get("host", cls.host)),
            port=cls._parse_port(data.get("port", cls.port)),
            debug=cls._parse_debug(data.get("debug", cls.debug)),
            tags=cls._parse_tags(data.get("tags", cls.tags)),
        )

    def merged(self, overrides: Mapping[str, object]) -> "AppConfig":
        # Re-validate by parsing only provided keys, then use replace for immutability.
        updates: dict[str, Any] = {}
        if "host" in overrides:
            updates["host"] = self._parse_host(overrides["host"])
        if "port" in overrides:
            updates["port"] = self._parse_port(overrides["port"])
        if "debug" in overrides:
            updates["debug"] = self._parse_debug(overrides["debug"])
        if "tags" in overrides:
            updates["tags"] = self._parse_tags(overrides["tags"])
        return replace(self, **updates)

    @staticmethod
    def _parse_host(value: object) -> str:
        if isinstance(value, str) and value.strip():
            return value.strip()
        raise ValueError("host must be a non-empty string")

    @staticmethod
    def _parse_port(value: object) -> int:
        if isinstance(value, int) and not isinstance(value, bool):
            port = value
        elif isinstance(value, str) and value.strip().isdigit():
            port = int(value.strip())
        else:
            raise ValueError("port must be an integer or numeric string")
        if not (1 <= port <= 65535):
            raise ValueError("port must be between 1 and 65535")
        return port

    @staticmethod
    def _parse_debug(value: object) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            normalized = value.strip().lower()
            if normalized in {"true", "1", "yes", "on"}:
                return True
            if normalized in {"false", "0", "no", "off"}:
                return False
        raise ValueError("debug must be a bool or a common boolean string")

    @staticmethod
    def _parse_tags(value: object) -> tuple[str, ...]:
        if isinstance(value, str):
            items = [part.strip() for part in value.split(",") if part.strip()]
            return tuple(items)
        if isinstance(value, (list, tuple)):
            if not all(isinstance(item, str) and item.strip() for item in value):
                raise ValueError("tags must contain only non-empty strings")
            return tuple(item.strip() for item in value)
        raise ValueError("tags must be a comma-separated string or a list/tuple of strings")


if __name__ == "__main__":
    raw = {"host": "localhost", "port": "8080", "debug": "true", "tags": "api,v1"}
    config = AppConfig.from_dict(raw)
    updated = config.merged({"port": 9090, "tags": ["api", "v2"]})
    print(config)
    print(updated)

import hashlib
from pathlib import Path


def sha256_file(file_path, chunk_size=8192):
    """Compute the SHA-256 checksum of a file by reading it in chunks."""
    hasher = hashlib.sha256()
    with open(file_path, 'rb') as f:
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            hasher.update(chunk)
    return hasher.hexdigest()


def verify_files(file_paths, expected_checksums):
    """
    Verify a list of files against expected SHA-256 checksums.

    Returns a dictionary mapping each file path to one of:
    - 'OK'
    - 'MISMATCH'
    - 'MISSING_CHECKSUM'
    - 'FILE_NOT_FOUND'
    """
    results = {}

    for file_path in file_paths:
        path = Path(file_path)

        if not path.is_file():
            results[file_path] = 'FILE_NOT_FOUND'
            continue

        expected = expected_checksums.get(file_path)
        if expected is None:
            results[file_path] = 'MISSING_CHECKSUM'
            continue

        actual = sha256_file(file_path)
        results[file_path] = 'OK' if actual.lower() == expected.lower() else 'MISMATCH'

    return results


def main():
    files = ['example1.txt', 'example2.txt', 'missing.txt']

    # Example expected checksums (replace with real values for actual use)
    expected = {
