        'example2.txt': 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'
    }

    results = verify_files(files, expected)
    for file_path, status in results.items():
        print(f'{file_path}: {status}')


if __name__ == '__main__':
