import re
from typing import Callable, Dict, List, Pattern, Tuple, Any


class Router:
    """A tiny web-style router with typed path parameters."""

    _CONVERTERS = {
        "int": (r"[0-9]+", int),
        "str": (r"[^/]+", str),
        "path": (r".+", str),
    }

    def __init__(self) -> None:
        self._routes: List[Tuple[Pattern[str], Callable[..., Any], Dict[str, Callable[[str], Any]]]] = []

    def route(self, pattern: str) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
        """Decorator to register a handler for a URL pattern."""
        regex, converters = self._compile_pattern(pattern)

        def decorator(func: Callable[..., Any]) -> Callable[..., Any]:
            self._routes.append((regex, func, converters))
            return func

        return decorator

    def resolve(self, path: str) -> Tuple[Callable[..., Any], Dict[str, Any]]:
        """Return the first matching handler and converted params for the given path."""
        for regex, handler, converters in self._routes:
            match = regex.fullmatch(path)
            if not match:
                continue

            params = {
                name: converters[name](value)
                for name, value in match.groupdict().items()
            }
            return handler, params

        raise ValueError(f"No route matches path: {path}")

    def _compile_pattern(self, pattern: str) -> Tuple[Pattern[str], Dict[str, Callable[[str], Any]]]:
        parts = pattern.strip("/").split("/") if pattern != "/" else []
        regex_parts: List[str] = []
        converters: Dict[str, Callable[[str], Any]] = {}

        for part in parts:
            if part.startswith("<") and part.endswith(">"):
                type_name, param_name = part[1:-1].split(":", 1)
                if type_name not in self._CONVERTERS:
                    raise ValueError(f"Unknown converter: {type_name}")
                expr, caster = self._CONVERTERS[type_name]
                regex_parts.append(f"(?P<{param_name}>{expr})")
                converters[param_name] = caster
            else:
                regex_parts.append(re.escape(part))

        regex = r"^/" + "/".join(regex_parts) + r"$"
        if pattern == "/":
            regex = r"^/$"
        return re.compile(regex), converters


# Demonstration
router = Router()


@router.route("/")
def home() -> str:
    return "home"


@router.route("/users/<int:user_id>")
def get_user(user_id: int) -> str:
