from functools import reduce, cmp_to_key


def group_and_sort_records(records):
    """
    Group sales records by category, sum their amounts,
    and return sorted (category, total_amount) tuples.
    """

    def reducer(acc, record):
        category = record['category']
        amount = record['amount']
        acc[category] = acc.get(category, 0) + amount
        return acc

    # Build a dictionary of category -> total amount
    totals = reduce(reducer, records, {})

    def compare(a, b):
        # Sort by total descending
        if a[1] > b[1]:
            return -1
        if a[1] < b[1]:
            return 1
        # If totals are equal, sort category names alphabetically
        if a[0] < b[0]:
            return -1
        if a[0] > b[0]:
            return 1
        return 0

    return sorted(totals.items(), key=cmp_to_key(compare))


def main():
    records = [
        {'category': 'Books', 'item': 'Novel', 'amount': 12.5},
        {'category': 'Electronics', 'item': 'Mouse', 'amount': 25},
        {'category': 'Books', 'item': 'Notebook', 'amount': 7.5},
        {'category': 'Groceries', 'item': 'Apples', 'amount': 10},
        {'category': 'Electronics', 'item': 'Keyboard', 'amount': 45},
        {'category': 'Groceries', 'item': 'Milk', 'amount': 5},
    ]

    result = group_and_sort_records(records)
    print(result)


if __name__ == '__main__':
    main()
}

class ServiceRegistry:
    """Singleton registry for application services."""

    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._services = {}
        return cls._instance

    def register(self, name, service):
        """Register a service under a unique name."""
        if name in self._services:
            raise ValueError(f"Service '{name}' is already registered")
        self._services[name] = service

    def get(self, name):
        """Retrieve a service by name."""
        return self._services.get(name)

    def list_services(self):
        """Return all registered service names in sorted order."""
        return sorted(self._services.keys())


