import time
from typing import Callable, Dict, Any, List

Request = Dict[str, Any]
Response = Dict[str, Any]
Middleware = Callable[[Request, Callable[[Request], Response]], Response]
Handler = Callable[[Request], Response]


class Pipeline:
    def __init__(self, handler: Handler):
        self._handler = handler
        self._middleware: List[Middleware] = []

    def add_middleware(self, middleware: Middleware) -> None:
        self._middleware.append(middleware)

    def execute(self, request: Request) -> Response:
        # Build the middleware chain from inside out.
        next_call = self._handler
        for middleware in reversed(self._middleware):
            current_next = next_call

            def make_wrapper(mw: Middleware, nxt: Handler) -> Handler:
                return lambda req: mw(req, nxt)

            next_call = make_wrapper(middleware, current_next)
        return next_call(request)


def logging_middleware(request: Request, next_call: Callable[[Request], Response]) -> Response:
    print(f"[LOG] Incoming request: {request}")
    response = next_call(request)
    print(f"[LOG] Outgoing response: {response}")
    return response


def auth_middleware(request: Request, next_call: Callable[[Request], Response]) -> Response:
    if request.get("token") != "secret-token":
        return {"status": 401, "error": "Unauthorized"}
    request = dict(request)  # Avoid mutating caller-owned input.
    request["user"] = "authorized-user"
    return next_call(request)


def timing_middleware(request: Request, next_call: Callable[[Request], Response]) -> Response:
    start = time.perf_counter()
    response = next_call(request)
    elapsed_ms = round((time.perf_counter() - start) * 1000, 3)
    response = dict(response)
    response["duration_ms"] = elapsed_ms
    return response


def final_handler(request: Request) -> Response:
    return {
        "status": 200,
        "message": f"Processed action '{request.get('action', 'unknown')}'",
        "user": request.get("user")
    }


if __name__ == "__main__":
    pipeline = Pipeline(final_handler)
    pipeline.add_middleware(logging_middleware)
    pipeline.add_middleware(auth_middleware)
    pipeline.add_middleware(timing_middleware)

    valid_request = {"action": "generate-report", "token": "secret-token"}
    invalid_request = {"action": "generate-report", "token": "bad-token"}

    print("Valid request result:")
    print(pipeline.execute(valid_request))

    print("\nInvalid request result:")
    print(pipeline.execute(invalid_request))

from abc import ABC, abstractmethod


class Notification(ABC):
    def __init__(self, name: str):
        self.name = name
        self.sent_count = 0

    @abstractmethod
    def send(self, message: str) -> str:
        """Send a message and return the formatted output."""
        pass

    def _mark_sent(self):
        self.sent_count += 1


class EmailNotification(Notification):
    def send(self, message: str) -> str:
        self._mark_sent()
        return f"[EMAIL] Subject: Alert | Body: {message}"


class SMSNotification(Notification):
    def send(self, message: str) -> str:
        self._mark_sent()
        return f"[SMS] {message[:20]}..." if len(message) > 20 else f"[SMS] {message}"


class PushNotification(Notification):
    def send(self, message: str) -> str:
        self._mark_sent()
        return f"[PUSH] >>> {message.upper()}"


class NotificationManager:
    def __init__(self):
        self.channels = []

    def register(self, channel: Notification):
        self.channels.append(channel)

    def broadcast(self, message: str):
        outputs = []
        for channel in self.channels:
            outputs.append(channel.send(message))
        return outputs

    def report(self):
        return {channel.name: channel.sent_count for channel in self.channels}


if __name__ == "__main__":
    manager = NotificationManager()
    manager.register(EmailNotification("email"))
    manager.register(SMSNotification("sms"))
    manager.register(PushNotification("push"))

    for result in manager.broadcast("System maintenance starts at 10 PM tonight."):
        print(result)

    print(manager.report())

def validate_user(record):
    """Validate a user record against a simple schema."""
    errors = []

    # Check required fields
    required_fields = ["name", "age", "email"]
    for field in required_fields:
        if field not in record:
            errors.append(f"Missing required field: {field}")

    # Stop early if required fields are missing
    if errors:
        return False, errors

    # Validate name
    if not isinstance(record["name"], str) or not record["name"].strip():
        errors.append("'name' must be a non-empty string")

    # Validate age
    if not isinstance(record["age"], int) or not (0 <= record["age"] <= 120):
        errors.append("'age' must be an integer between 0 and 120")

    # Validate email
    if not isinstance(record["email"], str) or "@" not in record["email"]:
        errors.append("'email' must be a string containing '@'")

    return len(errors) == 0, errors


def main():
    users = [
        {"name": "Alice", "age": 30, "email": "alice@example.com"},
        {"name": "", "age": 25, "email": "bob@example.com"},
        {"name": "Charlie", "age": 130, "email": "charlie@example.com"},
        {"name": "Dana", "age": 22, "email": "danaexample.com"},
        {"age": 40, "email": "eve@example.com"},
    ]

    for i, user in enumerate(users, start=1):
        is_valid, errors = validate_user(user)
        print(f"User {i}: {user}")
        print(f"Valid: {is_valid}")
        if errors:
            print("Errors:")
            for error in errors:
                print(f"- {error}")
        print()


if __name__ == "__main__":
    main()

class Router:
