from collections import deque


class PeekableIterator:
    """Wrap an iterable to allow peeking at the next item without consuming it."""

    def __init__(self, iterable):
        self._iterator = iter(iterable)
        self._has_buffer = False
        self._buffer = None

    def __iter__(self):
        return self

    def __next__(self):
        if self._has_buffer:
            self._has_buffer = False
            return self._buffer
        return next(self._iterator)

    def peek(self):
        if not self._has_buffer:
            self._buffer = next(self._iterator)  # May raise StopIteration
            self._has_buffer = True
        return self._buffer


def round_robin(*iterables):
    """Yield items from each iterable in turn until all are exhausted."""
    active = deque(iter(it) for it in iterables)

    while active:
        current = active.popleft()
        try:
            yield next(current)
            active.append(current)
        except StopIteration:
            # Silently drop exhausted iterators.
            pass


def countdown(n):
    """Example finite generator."""
    while n > 0:
        yield n
        n -= 1


def main():
    # Demonstrate lazy round-robin merging.
    merged = round_robin([1, 2, 3], countdown(4), ["A", "B"])
    print(list(merged))

    # Demonstrate peekable iteration.
    it = PeekableIterator(countdown(3))
    print(it.peek())   # 3
    print(next(it))    # 3
    print(it.peek())   # 2
    print(next(it))    # 2
    print(next(it))    # 1

    try:
        print(it.peek())
    except StopIteration:
        print("Iterator exhausted")


if __name__ == "__main__":
    main()
}

from collections import Counter


def top_k_frequent_sorted(nums, k):
    # Count occurrences of each number
    freq = Counter(nums)
    items = list(freq.items())  # (value, count)

    if k <= 0:
        return []
    if k >= len(items):
        selected = items[:]
    else:
        # Higher frequency is better; for ties, smaller value is better
        def better(a, b):
            return a[1] > b[1] or (a[1] == b[1] and a[0] < b[0])

        def partition(left, right, pivot_index):
            pivot = items[pivot_index]
            items[pivot_index], items[right] = items[right], items[pivot_index]
            store = left
            for i in range(left, right):
                if better(items[i], pivot):
                    items[store], items[i] = items[i], items[store]
                    store += 1
            items[right], items[store] = items[store], items[right]
            return store

        def quickselect(left, right, target):
            while left <= right:
                pivot_index = (left + right) // 2
                pivot_index = partition(left, right, pivot_index)
                if pivot_index == target:
                    return
                if pivot_index < target:
                    left = pivot_index + 1
                else:
                    right = pivot_index - 1

        # Place the top-k elements in the first k positions (unordered)
        quickselect(0, len(items) - 1, k - 1)
        selected = items[:k]

    # Manual binary-insertion sort for only the selected candidates
    def comes_before(a, b):
        return a[1] > b[1] or (a[1] == b[1] and a[0] < b[0])

    result = []
    for item in selected:
        lo, hi = 0, len(result)
        while lo < hi:
            mid = (lo + hi) // 2
            if comes_before(item, result[mid]):
                hi = mid
            else:
                lo = mid + 1
        result.insert(lo, item)

    return [value for value, _ in result[:k]]


if __name__ == '__main__':
    data = [4, 1, 2, 2, 3, 3, 3, 4, 4, 4, 5, 5, 1, 1, 1, 2]
    print(top_k_frequent_sorted(data, 3))  # Expected: [1, 4, 2]

from __future__ import annotations

import json
import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Set, Tuple

try:
    import yaml
except ImportError as exc:
    raise ImportError("PyYAML is required to parse YAML CloudFormation templates.") from exc


class TemplateValidationError(Exception):
    pass


class MalformedTemplateError(TemplateValidationError):
    pass


class UnsupportedResourceDefinitionError(TemplateValidationError):
    pass


class MissingDependentFileError(TemplateValidationError):
    pass


class CircularStackReferenceError(TemplateValidationError):
    pass


@dataclass(frozen=True)
class ValidationIssue:
    code: str
    message: str
    property_name: Optional[str] = None


@dataclass
class ResourceCompliance:
    logical_id: str
    resource_type: str
    compliant: bool
    issues: List[ValidationIssue] = field(default_factory=list)
    properties_checked: Dict[str, bool] = field(default_factory=dict)


@dataclass
class TemplateCompliance:
    template_path: str
    compliant: bool
    resources: List[ResourceCompliance] = field(default_factory=list)
    nested_templates: List[str] = field(default_factory=list)


@dataclass
class ComplianceReport:
    compliant: bool
    templates: Dict[str, TemplateCompliance] = field(default_factory=dict)


class _CfnLoader(yaml.SafeLoader):
    pass


def _unknown_tag_constructor(loader: yaml.Loader, tag_suffix: str, node: yaml.Node) -> Any:
    tag_name = tag_suffix.lstrip("!")
    if isinstance(node, yaml.ScalarNode):
        value = loader.construct_scalar(node)
    elif isinstance(node, yaml.SequenceNode):
        value = loader.construct_sequence(node)
    elif isinstance(node, yaml.MappingNode):
        value = loader.construct_mapping(node)
    else:
        value = loader.construct_object(node)
    return {f"Fn::{tag_name}" if tag_name not in {"Ref", "Condition"} else tag_name: value}


_CfnLoader.add_multi_constructor("!", _unknown_tag_constructor)


def _load_template_file(path: Path) -> Dict[str, Any]:
    if not path.exists():
        raise MissingDependentFileError(f"Template file does not exist: {path}")
    if not path.is_file():
        raise MissingDependentFileError(f"Template path is not a file: {path}")

    suffix = path.suffix.lower()
    try:
        with path.open("r", encoding="utf-8") as fh:
            content = fh.read()
    except OSError as exc:
        raise MissingDependentFileError(f"Unable to read template file: {path}") from exc

    try:
        if suffix == ".json":
            data = json.loads(content)
        elif suffix in {".yaml", ".yml"}:
            data = yaml.load(content, Loader=_CfnLoader)
        else:
            stripped = content.lstrip()
            if stripped.startswith("{") or stripped.startswith("["):
                data = json.loads(content)
            else:
                data = yaml.load(content, Loader=_CfnLoader)
    except (json.JSONDecodeError, yaml.YAMLError) as exc:
        raise MalformedTemplateError(f"Malformed template file '{path}': {exc}") from exc

    if not isinstance(data, dict):
        raise MalformedTemplateError(f"Template root must be a mapping/object: {path}")

    return data


def _is_intrinsic(value: Any) -> bool:
    if not isinstance(value, dict) or len(value) != 1:
        return False
    key = next(iter(value))
    return key == "Ref" or key.startswith("Fn::")


def _static_scalar_present(value: Any, expected_type: Optional[type] = None) -> bool:
    if value is None:
        return False

    if expected_type is None:
        if isinstance(value, (str, int, float, bool)):
            return True
        if _is_intrinsic(value):
            return _intrinsic_statically_resolvable(value)
        return False

    if isinstance(value, expected_type):
        if expected_type is str:
            return bool(value.strip())
        return True

    if _is_intrinsic(value):
        resolved = _resolve_intrinsic_static(value)
        if resolved is _UNRESOLVABLE:
            return False
        if isinstance(resolved, expected_type):
            if expected_type is str:
                return bool(resolved.strip())
            return True
        return False

    return False


_UNRESOLVABLE = object()


def _resolve_intrinsic_static(value: Any) -> Any:
    if not _is_intrinsic(value):
        return value

    key, payload = next(iter(value.items()))

    if key == "Ref":
        if isinstance(payload, str) and payload.strip():
            return payload
        return _UNRESOLVABLE

    if key == "Fn::Sub":
        if isinstance(payload, str):
            return payload if payload.strip() else _UNRESOLVABLE
        if isinstance(payload, list) and payload:
            template_str = payload[0]
            if isinstance(template_str, str) and template_str.strip():
                return template_str
        return _UNRESOLVABLE

    if key == "Fn::Join":
        if (
            isinstance(payload, list)
            and len(payload) == 2
            and isinstance(payload[0], str)
            and isinstance(payload[1], list)
        ):
            parts: List[str] = []
            for item in payload[1]:
                resolved = _resolve_intrinsic_static(item) if _is_intrinsic(item) else item
                if not isinstance(resolved, str):
                    return _UNRESOLVABLE
                parts.append(resolved)
            return payload[0].join(parts)
        return _UNRESOLVABLE

    if key == "Fn::If":
        if isinstance(payload, list) and len(payload) == 3:
            true_val = _resolve_intrinsic_static(payload[1]) if _is_intrinsic(payload[1]) else payload[1]
            false_val = _resolve_intrinsic_static(payload[2]) if _is_intrinsic(payload[2]) else payload[2]
            if true_val is _UNRESOLVABLE or false_val is _UNRESOLVABLE:
                return _UNRESOLVABLE
            if type(true_val) is type(false_val):
                return true_val
        return _UNRESOLVABLE

    if key == "Fn::Select":
        if isinstance(payload, list) and len(payload) == 2:
            index, options = payload
            idx = _resolve_intrinsic_static(index) if _is_intrinsic(index) else index
            opts = _resolve_intrinsic_static(options) if _is_intrinsic(options) else options
            if isinstance(idx, int) and isinstance(opts, list) and 0 <= idx < len(opts):
                selected = opts[idx]
                return _resolve_intrinsic_static(selected) if _is_intrinsic(selected) else selected
        return _UNRESOLVABLE

    if key == "Fn::Split":
        if isinstance(payload, list) and len(payload) == 2:
            delimiter, source = payload
            delim = _resolve_intrinsic_static(delimiter) if _is_intrinsic(delimiter) else delimiter
            src = _resolve_intrinsic_static(source) if _is_intrinsic(source) else source
            if isinstance(delim, str) and isinstance(src, str):
                return src.split(delim)
        return _UNRESOLVABLE

    if key == "Fn::FindInMap":
        return _UNRESOLVABLE

    if key == "Fn::ImportValue":
        resolved = _resolve_intrinsic_static(payload) if _is_intrinsic(payload) else payload
        if isinstance(resolved, str) and resolved.strip():
            return resolved
        return _UNRESOLVABLE

    if key == "Fn::GetAtt":
        if isinstance(payload, list) and len(payload) == 2 and all(isinstance(x, str) and x.strip() for x in payload):
            return ".".join(payload)
        if isinstance(payload, str) and payload.strip():
            return payload
        return _UNRESOLVABLE

    return _UNRESOLVABLE


def _intrinsic_statically_resolvable(value: Dict[str, Any]) -> bool:
    return _resolve_intrinsic_static(value) is not _UNRESOLVABLE


def _validate_lambda_resource(logical_id: str, resource: Dict[str, Any]) -> ResourceCompliance:
    resource_type = resource.get("Type")
    props = resource.get("Properties")

    if props is None:
        raise UnsupportedResourceDefinitionError(
            f"Lambda resource '{logical_id}' is missing the 'Properties' section."
        )
    if not isinstance(props, dict):
        raise UnsupportedResourceDefinitionError(
            f"Lambda resource '{logical_id}' has non-mapping 'Properties'."
        )

    issues: List[ValidationIssue] = []
    checked: Dict[str, bool] = {}

    runtime_ok = _static_scalar_present(props.get("Runtime"), str)
    checked["Runtime"] = runtime_ok
    if not runtime_ok:
        issues.append(
            ValidationIssue(
                code="MISSING_OR_UNRESOLVABLE_RUNTIME",
                message="Lambda function must define an explicit Runtime that is statically resolvable.",
                property_name="Runtime",
            )
        )

    timeout_ok = _static_scalar_present(props.get("Timeout"), int)
    checked["Timeout"] = timeout_ok
    if not timeout_ok:
        issues.append(
            ValidationIssue(
                code="MISSING_OR_UNRESOLVABLE_TIMEOUT",
                message="Lambda function must define an explicit Timeout as an integer or statically resolvable integer.",
                property_name="Timeout",
            )
        )

    memory_ok = _static_scalar_present(props.get("MemorySize"), int)
    checked["MemorySize"] = memory_ok
    if not memory_ok:
        issues.append(
            ValidationIssue(
                code="MISSING_OR_UNRESOLVABLE_MEMORY_SIZE",
                message="Lambda function must define an explicit MemorySize as an integer or statically resolvable integer.",
                property_name="MemorySize",
            )
        )

    role_ok = _static_scalar_present(props.get("Role"), str)
    checked["Role"] = role_ok
    if not role_ok:
        issues.append(
            ValidationIssue(
                code="MISSING_OR_UNRESOLVABLE_ROLE",
                message="Lambda function must define an explicit IAM execution Role that is statically resolvable.",
                property_name="Role",
            )
        )

    return ResourceCompliance(
        logical_id=logical_id,
        resource_type=resource_type,
        compliant=not issues,
        issues=issues,
        properties_checked=checked,
    )


def _extract_nested_stack_paths(template: Dict[str, Any], template_path: Path) -> List[Path]:
    resources = template.get("Resources", {})
    if resources is None:
        return []
    if not isinstance(resources, dict):
        raise MalformedTemplateError(f"'Resources' must be a mapping in template: {template_path}")

    nested_paths: List[Path] = []
    for logical_id, resource in resources.items():
        if not isinstance(resource, dict):
            raise UnsupportedResourceDefinitionError(
                f"Resource '{logical_id}' in template '{template_path}' must be a mapping."
            )
        resource_type = resource.get("Type")
        if resource_type != "AWS::CloudFormation::Stack":
            continue

        props = resource.get("Properties")
        if props is None or not isinstance(props, dict):
            raise UnsupportedResourceDefinitionError(
                f"Nested stack resource '{logical_id}' in template '{template_path}' must have mapping 'Properties'."
            )

        template_url = props.get("TemplateURL")
        if template_url is None:
            raise UnsupportedResourceDefinitionError(
                f"Nested stack resource '{logical_id}' in template '{template_path}' is missing 'TemplateURL'."
            )

        resolved = _resolve_template_url_local(template_url, template_path.parent)
        if resolved is None:
            raise UnsupportedResourceDefinitionError(
                f"Nested stack resource '{logical_id}' in template '{template_path}' has unsupported "
                f"or non-local 'TemplateURL' definition."
            )
        nested_paths.append(resolved)

    return nested_paths


def _resolve_template_url_local(template_url: Any, base_dir: Path) -> Optional[Path]:
    candidate = template_url
    if _is_intrinsic(template_url):
        candidate = _resolve_intrinsic_static(template_url)
        if candidate is _UNRESOLVABLE:
            return None

    if not isinstance(candidate, str) or not candidate.strip():
        return None

    value = candidate.strip()

    if value.startswith(("s3://", "http://", "https://")):
        return None

    path = Path(value)
    if not path.is_absolute():
        path = (base_dir / path).resolve()
    else:
        path = path.resolve()
    return path


class CloudFormationComplianceValidator:
    def __init__(self) -> None:
        self._template_cache: Dict[Path, Dict[str, Any]] = {}
        self._report_templates: Dict[str, TemplateCompliance] = {}

    def validate_templates(self, template_files: Iterable[str | os.PathLike[str]]) -> ComplianceReport:
        normalized_roots = [Path(p).resolve() for p in template_files]
        visiting: Set[Path] = set()
        visited: Set[Path] = set()

        for template_path in normalized_roots:
            self._walk_template(template_path, visiting, visited)

        overall_compliant = all(t.compliant for t in self._report_templates.values())
        return ComplianceReport(compliant=overall_compliant, templates=self._report_templates)

    def _walk_template(self, template_path: Path, visiting: Set[Path], visited: Set[Path]) -> None:
        if template_path in visited:
            return
        if template_path in visiting:
            cycle = " -> ".join(str(p) for p in list(visiting) + [template_path])
            raise CircularStackReferenceError(f"Circular nested stack reference detected: {cycle}")

        visiting.add(template_path)
        template = self._get_template(template_path)
        template_report = self._validate_single_template(template_path, template)
        self._report_templates[str(template_path)] = template_report

        nested_paths = _extract_nested_stack_paths(template, template_path)
        template_report.nested_templates.extend(str(p) for p in nested_paths)

        for nested_path in nested_paths:
            if not nested_path.exists():
                raise MissingDependentFileError(
                    f"Nested stack template referenced from '{template_path}' not found: {nested_path}"
                )
            self._walk_template(nested_path, visiting, visited)

        template_report.compliant = (
            template_report.compliant
            and all(self._report_templates[str(p)].compliant for p in nested_paths if str(p) in self._report_templates)
        )

        visiting.remove(template_path)
        visited.add(template_path)

    def _get_template(self, template_path: Path) -> Dict[str, Any]:
        cached = self._template_cache.get(template_path)
        if cached is not None:
            return cached
        template = _load_template_file(template_path)
        self._template_cache[template_path] = template
        return template

    def _validate_single_template(self, template_path: Path, template: Dict[str, Any]) -> TemplateCompliance:
        resources = template.get("Resources", {})
        if resources is None:
            resources = {}
        if not isinstance(resources, dict):
            raise MalformedTemplateError(f"'Resources' must be a mapping in template: {template_path}")

        resource_reports: List[ResourceCompliance] = []

        for logical_id, resource in resources.items():
            if not isinstance(resource, dict):
                raise UnsupportedResourceDefinitionError(
                    f"Resource '{logical_id}' in template '{template_path}' must be a mapping."
                )

            resource_type = resource.get("Type")
            if not isinstance(resource_type, str) or not resource_type.strip():
                raise UnsupportedResourceDefinitionError(
                    f"Resource '{logical_id}' in template '{template_path}' must define a string 'Type'."
                )

            if resource_type == "AWS::Lambda::Function":
                resource_reports.append(_validate_lambda_resource(logical_id, resource))

        compliant = all(r.compliant for r in resource_reports)
        return TemplateCompliance(
            template_path=str(template_path),
            compliant=compliant,
            resources=resource_reports,
            nested_templates=[],
        )


def validate_cloudformation_lambda_compliance(
    template_files: Iterable[str | os.PathLike[str]],
) -> Dict[str, Any]:
    validator = CloudFormationComplianceValidator()
    report = validator.validate_templates(template_files)
