class Node:
    def __init__(self, value):
        self.value = value
        self.next = None


class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, value):
        """Add a new node to the end of the linked list."""
        new_node = Node(value)

        if self.head is None:
            self.head = new_node
            return

        current = self.head
        while current.next is not None:
            current = current.next
        current.next = new_node

    def display(self):
        """Return the linked list values as a formatted string."""
        values = []
        current = self.head

        while current is not None:
            values.append(str(current.value))
            current = current.next

        return ' -> '.join(values)


