import time


class CircuitOpenError(Exception):
    pass


class CircuitBreaker:
    def __init__(self, failure_threshold=3, reset_timeout=2):
        self.failure_threshold = failure_threshold
        self.reset_timeout = reset_timeout
        self.failure_count = 0
        self.state = 'CLOSED'  # CLOSED, OPEN, HALF_OPEN
        self.opened_at = None

    def before_call(self):
        if self.state == 'OPEN':
            if time.time() - self.opened_at >= self.reset_timeout:
                self.state = 'HALF_OPEN'
            else:
                raise CircuitOpenError('Circuit is open; call blocked')

    def record_success(self):
        self.failure_count = 0
        self.state = 'CLOSED'
        self.opened_at = None

    def record_failure(self):
        self.failure_count += 1
        if self.state == 'HALF_OPEN' or self.failure_count >= self.failure_threshold:
            self.state = 'OPEN'
            self.opened_at = time.time()


def call_with_retry(func, breaker, retries=3, delay=0.2):
    last_error = None
    breaker.before_call()

    for attempt in range(1, retries + 1):
        try:
            result = func()
            breaker.record_success()
            return result
        except Exception as exc:
            last_error = exc
            if attempt < retries:
                time.sleep(delay)

    breaker.record_failure()
    raise last_error


class FlakyService:
    def __init__(self, failures_before_success):
        self.failures_left = failures_before_success

    def call(self):
        if self.failures_left > 0:
            self.failures_left -= 1
            raise RuntimeError('Temporary service failure')
        return 'Service response OK'


if __name__ == '__main__':
    breaker = CircuitBreaker(failure_threshold=2, reset_timeout=1.5)
    service = FlakyService(failures_before_success=5)

    for i in range(6):
        try:
            print(f'Call {i + 1}:', call_with_retry(service.call, breaker))
        except Exception as e:
            print(f'Call {i + 1} failed:', e, f'(state={breaker.state})')
        time.sleep(0.4)

import json
from abc import ABC, abstractmethod


class Report(ABC):
    def __init__(self):
        self.title = ""
        self.sections = []
        self.metadata = {}

    @abstractmethod
    def render(self) -> str:
        pass


class JSONReport(Report):
    def render(self) -> str:
        return json.dumps(
            {
                "title": self.title,
                "metadata": self.metadata,
                "sections": self.sections,
            },
            indent=2,
        )


class TextReport(Report):
    def render(self) -> str:
        lines = []
        if self.title:
            lines.append(f"=== {self.title} ===")
        if self.metadata:
            lines.append("Metadata:")
            for key, value in self.metadata.items():
                lines.append(f"- {key}: {value}")
        if self.sections:
            lines.append("Sections:")
            for i, section in enumerate(self.sections, 1):
                lines.append(f"{i}. {section}")
        return "\n".join(lines)


class ReportFactory:
    @staticmethod
    def create_report(report_type: str) -> Report:
        report_type = report_type.lower()
        if report_type == "json":
            return JSONReport()
        if report_type == "text":
            return TextReport()
        raise ValueError(f"Unsupported report type: {report_type}")


class ReportBuilder:
    def __init__(self, report: Report):
        self.report = report

    def set_title(self, title: str):
        self.report.title = title
        return self

    def add_section(self, content: str):
        self.report.sections.append(content)
        return self

    def add_metadata(self, key: str, value):
        self.report.metadata[key] = value
        return self

    def build(self) -> str:
        return self.report.render()


