from urllib.parse import urlsplit, urlunsplit, parse_qsl, urlencode

TRACKING_PARAMS = {
    'utm_source',
    'utm_medium',
    'utm_campaign',
    'utm_term',
    'utm_content',
    'gclid',
    'fbclid',
}


def _normalize_path(path: str) -> str:
    """Collapse repeated slashes and resolve dot segments, preserving intent."""
    if not path:
        return ''

    is_absolute = path.startswith('/')
    had_trailing_slash = path.endswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            elif not is_absolute:
                stack.append('..')
        else:
            stack.append(part)

    normalized = ('/' if is_absolute else '') + '/'.join(stack)

    if had_trailing_slash and normalized not in ('', '/'):
        normalized += '/'
    elif is_absolute and normalized == '':
        normalized = '/'

    return normalized


def normalize_tracking_url(url: str, allowed_params: set[str] | None = None) -> str:
    """Return a normalized URL with tracking parameters removed and components canonicalized."""
    allowed_params = allowed_params or set()
    split = urlsplit(url)

    scheme = split.scheme.lower()
    hostname = (split.hostname or '').lower()
    port = split.port

    # Remove default ports for common web schemes.
    if (scheme == 'http' and port == 80) or (scheme == 'https' and port == 443):
        port = None

    # Rebuild netloc, preserving user info if present.
    userinfo = ''
    if split.username is not None:
        userinfo = split.username
        if split.password is not None:
            userinfo += f':{split.password}'
        userinfo += '@'

    netloc = userinfo + hostname
    if port is not None:
        netloc += f':{port}'

    path = _normalize_path(split.path)

    # Keep repeated params, remove tracking params unless explicitly allowed.
    params = parse_qsl(split.query, keep_blank_values=True)
    filtered = [
        (k, v)
        for k, v in params
        if k not in TRACKING_PARAMS or k in allowed_params
    ]
    filtered.sort(key=lambda item: (item[0], item[1]))
    query = urlencode(filtered, doseq=True)

    return urlunsplit((scheme, netloc, path, query, split.fragment))


if __name__ == '__main__':
    examples = [
        'HTTPS://Example.COM:443//shop/./items/../?b=2&utm_source=google&a=1#top',
        'http://User:Pass@Example.com:80/a//b/../c/?fbclid=abc&id=7&id=3',
        'https://example.com/path//to/page/?utm_campaign=spring&ref=newsletter&gclid=123',
    ]

    for url in examples:
        print(normalize_tracking_url(url))

import base64
import hashlib
import hmac
import json
import secrets
import time


class AuthService:
    ROLES = {
        'admin': {'read', 'write', 'delete'},
        'editor': {'read', 'write'},
        'viewer': {'read'},
    }

    def __init__(self, secret_key: bytes):
        self._secret_key = secret_key
        self._users = {}  # username -> {salt, password_hash, role}

    def register(self, username: str, password: str, role: str):
        if role not in self.ROLES:
            raise ValueError('invalid role')
        if username in self._users:
            raise ValueError('duplicate user')

        salt = secrets.token_bytes(16)
        password_hash = self._hash_password(password, salt)
        self._users[username] = {
            'salt': salt,
            'password_hash': password_hash,
            'role': role,
        }

    def login(self, username: str, password: str, ttl_seconds: int = 3600) -> str:
        user = self._users.get(username)
        if not user:
            raise ValueError('bad credentials')

        expected = user['password_hash']
        actual = self._hash_password(password, user['salt'])
        if not hmac.compare_digest(expected, actual):
            raise ValueError('bad credentials')

        payload = {
            'sub': username,
            'role': user['role'],
            'exp': int(time.time()) + int(ttl_seconds),
        }
        return self._sign_token(payload)

    def verify_token(self, token: str) -> dict:
        try:
            payload_b64, sig_b64 = token.split('.')
            payload_bytes = self._b64decode(payload_b64)
            sent_sig = self._b64decode(sig_b64)
        except Exception:
            raise ValueError('invalid token')

        expected_sig = hmac.new(self._secret_key, payload_bytes, hashlib.sha256).digest()
        if not hmac.compare_digest(sent_sig, expected_sig):
            raise ValueError('invalid token')

        try:
            payload = json.loads(payload_bytes.decode('utf-8'))
        except Exception:
            raise ValueError('invalid token')

        if int(payload.get('exp', 0)) < int(time.time()):
            raise ValueError('expired token')

        username = payload.get('sub')
        role = payload.get('role')
        if username not in self._users or role not in self.ROLES:
            raise ValueError('invalid token')

        return payload

    def can(self, token: str, action: str) -> bool:
        all_actions = {'read', 'write', 'delete'}
        if action not in all_actions:
            raise ValueError('unknown action')

        payload = self.verify_token(token)
        return action in self.ROLES[payload['role']]

    def _hash_password(self, password: str, salt: bytes) -> bytes:
        return hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 200_000)

    def _sign_token(self, payload: dict) -> str:
        payload_bytes = json.dumps(payload, separators=(',', ':'), sort_keys=True).encode('utf-8')
        sig = hmac.new(self._secret_key, payload_bytes, hashlib.sha256).digest()
        return f"{self._b64encode(payload_bytes)}.{self._b64encode(sig)}"

    @staticmethod
    def _b64encode(data: bytes) -> str:
        return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

    @staticmethod
    def _b64decode(data: str) -> bytes:
        padding = '=' * (-len(data) % 4)
        return base64.urlsafe_b64decode(data + padding)


if __name__ == '__main__':
    auth = AuthService(secret_key=secrets.token_bytes(32))
    auth.register('alice', 'S3curePass!', 'admin')
    token = auth.login('alice', 'S3curePass!', ttl_seconds=60)
    print(auth.verify_token(token))
    print('can delete:', auth.can(token, 'delete'))
    print('can write:', auth.can(token, 'write'))
    print('can read:', auth.can(token, 'read'))

def merge_access_logs(logs):
    required_keys = {"user", "resource", "action", "tags"}
    summary = {}

    for entry in logs:
        # Skip malformed entries
        if not required_keys.issubset(entry):
            continue

        user = entry["user"]
        resource = entry["resource"]
        action = entry["action"]
        tags = set(entry["tags"])

        if user not in summary:
            summary[user] = {
                "resources": set(),
                "actions": {},
                "common_tags": tags.copy()
            }
        else:
            # Keep only tags common to all of this user's entries
            summary[user]["common_tags"] &= tags

        summary[user]["resources"].add(resource)
        summary[user]["actions"][action] = summary[user]["actions"].get(action, 0) + 1

    # Return dictionary with users sorted alphabetically
    return {user: summary[user] for user in sorted(summary)}


