from __future__ import annotations


def parse_tlv_stream(data: bytes) -> list[dict]:
    records = []
    offset = 0

    while offset < len(data):
        # Need at least 3 bytes for type (1) + length (2)
        if len(data) - offset < 3:
            raise ValueError(f"Incomplete TLV header at offset {offset}")

        record_type = data[offset]
        length = int.from_bytes(data[offset + 1:offset + 3], "big")
        offset += 3

        # Ensure the payload exists fully in the stream
        if len(data) - offset < length:
            raise ValueError(f"Truncated payload at offset {offset} for type {record_type}")

        payload = data[offset:offset + length]
        offset += length

        # Decode based on type
        if record_type == 1:
            try:
                value = payload.decode("ascii")
            except UnicodeDecodeError as e:
                raise ValueError(f"Non-ASCII payload for type 1 at offset {offset - length}") from e
        elif record_type == 2:
            value = int.from_bytes(payload, "big")
        elif record_type == 3:
            value = payload.hex()
        else:
            value = payload

        records.append({
            "type": record_type,
            "length": length,
            "value": value,
        })

    return records


def main() -> None:
    # Sample stream:
    # type=1, len=5, value='HELLO'
    # type=2, len=3, value=0x010203
    # type=3, len=4, value=b'\xde\xad\xbe\xef'
    sample = (
        b"\x01\x00\x05HELLO"
        b"\x02\x00\x03\x01\x02\x03"
        b"\x03\x00\x04\xde\xad\xbe\xef"
    )

    parsed = parse_tlv_stream(sample)
    for record in parsed:
        print(record)


