import csv
import io
import json


def canonicalize_records(data: str, fmt: str) -> str:
    def normalize_tags(tags):
        if isinstance(tags, str):
            raw_tags = tags.split(';')
        elif isinstance(tags, list):
            raw_tags = tags
        else:
            raise ValueError('Malformed input: tags must be a string or list')

        seen = set()
        cleaned = []
        for tag in raw_tags:
            if not isinstance(tag, str):
                raise ValueError('Malformed input: tag values must be strings')
            t = tag.strip()
            if not t:
                continue
            key = t.casefold()
            if key not in seen:
                seen.add(key)
                cleaned.append(t)
        return sorted(cleaned, key=str.casefold)

    def normalize_record(record):
        if not isinstance(record, dict):
            raise ValueError('Malformed input: each record must be an object')
        try:
            record_id = int(record['id'])
            name = str(record['name']).strip()
            tags = normalize_tags(record['tags'])
        except KeyError as e:
            raise ValueError(f'Malformed input: missing field {e.args[0]}') from None
        except (TypeError, ValueError):
            raise ValueError('Malformed input: invalid field types') from None
        return {'id': record_id, 'name': name, 'tags': tags}

    try:
        if fmt == 'json':
            parsed = json.loads(data)
            if not isinstance(parsed, list):
                raise ValueError('Malformed input: JSON root must be a list')
            records = [normalize_record(r) for r in parsed]
        elif fmt == 'csv':
            reader = csv.DictReader(io.StringIO(data))
            required = {'id', 'name', 'tags'}
            if reader.fieldnames is None or not required.issubset(reader.fieldnames):
                raise ValueError('Malformed input: CSV must contain id,name,tags headers')
            records = [normalize_record(row) for row in reader]
        else:
            raise ValueError('Unsupported format')
    except json.JSONDecodeError:
        raise ValueError('Malformed input: invalid JSON') from None
    except csv.Error:
        raise ValueError('Malformed input: invalid CSV') from None

    records.sort(key=lambda r: r['id'])
    return json.dumps(records, separators=(',', ':'))


if __name__ == '__main__':
    sample_csv = 'id,name,tags\n2, Alice ,python; Data ;python\n1,Bob,api;JSON;api; '\n    print(canonicalize_records(sample_csv, 'csv'))

