        response = session.get(url, timeout=10)
        response.raise_for_status()
        return BeautifulSoup(response.text, "html.parser")
    except requests.RequestException as exc:
        print(f"Failed to fetch {url}: {exc}")
        return None


def parse_quotes(soup):
    """Extract quote data from a page."""
    results = []
    for block in soup.select("div.quote"):
        text_el = block.select_one("span.text")
        author_el = block.select_one("small.author")
        tag_els = block.select("div.tags a.tag")

        if not text_el or not author_el:
            continue

        results.append({
            "text": text_el.get_text(strip=True),
            "author": author_el.get_text(strip=True),
            "tags": [tag.get_text(strip=True) for tag in tag_els],
        })
    return results


def find_next_url(soup, current_url):
    """Return the absolute URL for the next page, if present."""
    next_link = soup.select_one("li.next > a")
    return urljoin(current_url, next_link["href"]) if next_link and next_link.get("href") else None


def main():
    session = requests.Session()
    session.headers.update(HEADERS)

    url = BASE_URL
    page_count = 0
    seen_texts = set()
    filtered_quotes = []

    while url and page_count < MAX_PAGES:
        soup = fetch_soup(session, url)
        if soup is None:
            break

        for quote in parse_quotes(soup):
            if quote["text"] in seen_texts:
                continue
            seen_texts.add(quote["text"])

            if quote["author"].startswith(("A", "J")):
                filtered_quotes.append(quote)

        url = find_next_url(soup, url)
        page_count += 1

    print(json.dumps(filtered_quotes, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()

from datetime import datetime, time, timedelta
from zoneinfo import ZoneInfo


def merge_busy_intervals(events, timezone_name):
    tz = ZoneInfo(timezone_name)
    daily_segments = {}

    for event in events:
        start = datetime.fromisoformat(event['start']).astimezone(tz)
        end = datetime.fromisoformat(event['end']).astimezone(tz)

        if end <= start:
            continue

        current = start
        while current.date() < end.date():
            next_midnight = datetime.combine(
                current.date() + timedelta(days=1), time.min, tzinfo=tz
            )
            daily_segments.setdefault(current.date().isoformat(), []).append(
                (current, next_midnight)
            )
            current = next_midnight

        if current < end:
            daily_segments.setdefault(current.date().isoformat(), []).append(
                (current, end)
            )

    merged_by_day = {}

    for day, intervals in sorted(daily_segments.items()):
        intervals.sort(key=lambda pair: pair[0])
        merged = []

        for start, end in intervals:
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            else:
                merged[-1][1] = max(merged[-1][1], end)

        merged_by_day[day] = [
            [s.strftime('%H:%M'), e.strftime('%H:%M')] for s, e in merged if s < e
        ]

    return merged_by_day


