from typing import Iterable, Iterator, List, Dict


def parse_errors(lines: Iterable[str]) -> Iterator[Dict[str, str]]:
    """Yield parsed dictionaries for ERROR log lines only."""
    for line in lines:
        parts = [part.strip() for part in line.split("|")]
        if len(parts) != 3:
            continue  # Skip malformed lines

        timestamp, level, message = parts
        if level == "ERROR":
            yield {
                "timestamp": timestamp,
                "level": level,
                "message": message,
            }


class ErrorWindow:
    """Iterator that groups error records into fixed-size batches."""

    def __init__(self, records: Iterable[Dict[str, str]], size: int):
        if size <= 0:
            raise ValueError("size must be greater than 0")
        self._iterator = iter(records)
        self._size = size

    def __iter__(self):
        return self

    def __next__(self) -> List[Dict[str, str]]:
        batch = []
        for _ in range(self._size):
            try:
                batch.append(next(self._iterator))
            except StopIteration:
                break

        if not batch:
            raise StopIteration
        return batch


