def parse_bool(value: str) -> bool:
    """Convert common string representations to boolean."""
    normalized = value.strip().lower()
    truthy = {"true", "1", "yes", "y", "on"}
    falsy = {"false", "0", "no", "n", "off"}

    if normalized in truthy:
        return True
    if normalized in falsy:
        return False
    raise ValueError(
        f"Invalid boolean value for APP_DEBUG: {value!r}. "
        "Use true/false, 1/0, yes/no, on/off."
    )


def load_config() -> dict:
    """Load, validate, and normalize configuration from environment variables."""
    config = {
        "host": os.getenv("APP_HOST", "127.0.0.1"),
        "port": 8000,
        "debug": False,
        "timeout": 30.0,
    }

    raw_port = os.getenv("APP_PORT")
    if raw_port is not None:
        try:
            port = int(raw_port)
        except ValueError as exc:
            raise ValueError(f"APP_PORT must be an integer, got {raw_port!r}") from exc
        if not (1 <= port <= 65535):
            raise ValueError(f"APP_PORT must be between 1 and 65535, got {port}")
        config["port"] = port

    raw_debug = os.getenv("APP_DEBUG")
    if raw_debug is not None:
        config["debug"] = parse_bool(raw_debug)

    raw_timeout = os.getenv("APP_TIMEOUT")
    if raw_timeout is not None:
        try:
            timeout = float(raw_timeout)
        except ValueError as exc:
            raise ValueError(f"APP_TIMEOUT must be a number, got {raw_timeout!r}") from exc
        if timeout <= 0:
            raise ValueError(f"APP_TIMEOUT must be positive, got {timeout}")
        config["timeout"] = timeout

    return config


def main() -> None:
    config = load_config()
    print(json.dumps(config, indent=2))


