def analyze_access_logs(records):
    # Resource -> set of users who accessed it
    users_by_resource = {}
    # Resource -> set of all tags seen for that resource
    tags_by_resource = {}
    # User -> set of resources accessed
    resources_by_user = {}
    # Users who performed a delete action at least once
    delete_users = set()

    for record in records:
        user = record['user']
        resource = record['resource']
        action = record['action']
        tags = set(record.get('tags', []))  # Deduplicate tags within a record

        users_by_resource.setdefault(resource, set()).add(user)
        tags_by_resource.setdefault(resource, set()).update(tags)
        resources_by_user.setdefault(user, set()).add(resource)

        if action == 'delete':
            delete_users.add(user)

    # Convert resource user sets to sorted lists
    users_by_resource_out = {
        resource: sorted(users)
        for resource, users in users_by_resource.items()
    }

    # Tags common to every resource; empty if there are no resources
    if tags_by_resource:
        common = set.intersection(*(tags for tags in tags_by_resource.values()))
    else:
        common = set()
    common_tags = sorted(common)

    # Users who accessed multiple resources and deleted at least once
    suspicious_users = sorted(
        user for user, resources in resources_by_user.items()
        if len(resources) > 1 and user in delete_users
    )

    # Count in how many distinct resources each tag appears
    tag_resource_count = {}
    for tags in tags_by_resource.values():
        for tag in tags:
            tag_resource_count[tag] = tag_resource_count.get(tag, 0) + 1

    # For each resource, keep tags unique to that resource
    resource_tag_summary = {
        resource: sorted(tag for tag in tags if tag_resource_count[tag] == 1)
        for resource, tags in tags_by_resource.items()
    }

    return {
        'users_by_resource': users_by_resource_out,
        'common_tags': common_tags,
        'suspicious_users': suspicious_users,
        'resource_tag_summary': resource_tag_summary,
    }


