class PositiveNumber:
    """Descriptor that allows only positive numeric values."""

    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, (int, float)):
            raise TypeError(f"{self.private_name[1:]} must be a number")
        if value <= 0:
            raise ValueError(f"{self.private_name[1:]} must be greater than zero")
        setattr(instance, self.private_name, float(value))


class Product:
    price = PositiveNumber()
    weight = PositiveNumber()

    def __init__(self, name, price, weight):
        self.name = name          # validated by property
        self.price = price        # validated by descriptor
        self.weight = weight      # validated by descriptor

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        if not isinstance(value, str):
            raise TypeError("name must be a string")
        cleaned = value.strip()
        if not cleaned:
            raise ValueError("name cannot be empty")
        self._name = cleaned

    @property
    def shipping_cost(self):
        """Read-only computed property based on weight."""
        return self.weight * 1.5

    def __repr__(self):
        return (
            f"Product(name={self.name!r}, price={self.price:.2f}, "
            f"weight={self.weight:.2f}, shipping_cost={self.shipping_cost:.2f})"
        )


