from datetime import datetime, timezone
from typing import Any, Dict, List, Optional


def _parse_timestamp(value: Any) -> Optional[datetime]:
    """Parse Unix seconds or ISO-8601 timestamp into a timezone-aware datetime."""
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return datetime.fromtimestamp(value, tz=timezone.utc)
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return None
        if value.isdigit():
            return datetime.fromtimestamp(int(value), tz=timezone.utc)
        try:
            # Support trailing Z for UTC
            return datetime.fromisoformat(value.replace('Z', '+00:00'))
        except ValueError:
            return None
    return None


def _parse_amount(value: Any) -> Optional[float]:
    """Parse numeric amount from int/float or strings like '1,234.56'."""
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.replace(',', '').strip())
        except ValueError:
            return None
    return None


def transform_events(records: List[Dict[str, Any]], eur_to_usd: float) -> List[Dict[str, Any]]:
    latest_by_event_id: Dict[str, Dict[str, Any]] = {}

    for r in records:
        event_id = r.get('event_id') or r.get('id')
        user_id = r.get('user_id') or r.get('user')
        event_type = r.get('event_type') or r.get('type')
        source = r.get('source', 'unknown')
        ts = _parse_timestamp(r.get('event_ts') or r.get('timestamp') or r.get('ts'))
        amount = _parse_amount(r.get('amount'))
        currency = str(r.get('currency', 'USD')).upper()

        # Validate required fields
        if not all([event_id, user_id, event_type, ts]) or amount is None:
            continue
        if currency not in {'USD', 'EUR'}:
            continue

        amount_usd = round(amount * eur_to_usd, 2) if currency == 'EUR' else round(amount, 2)
        cleaned = {
            'event_id': str(event_id),
            'user_id': str(user_id),
            'event_type': str(event_type),
            'event_ts': ts.astimezone(timezone.utc).isoformat(),
            'amount_usd': amount_usd,
            'source': str(source),
        }

        # Deduplicate by event_id, keeping the newest timestamp
        existing = latest_by_event_id.get(cleaned['event_id'])
        if not existing or cleaned['event_ts'] > existing['event_ts']:
            latest_by_event_id[cleaned['event_id']] = cleaned

    return sorted(latest_by_event_id.values(), key=lambda x: x['event_ts'])


