def analyze_purchases(orders):
    # Build a mapping from customer to the set of all items they purchased
    customer_items = {}
    for order in orders:
        customer = order['customer']
        items = order['items']

        if customer not in customer_items:
            customer_items[customer] = set()

        customer_items[customer].update(items)

    # Convert sets to sorted lists for the final output
    unique_items_per_customer = {
        customer: sorted(items)
        for customer, items in customer_items.items()
    }

    # Find items purchased by every customer
    all_item_sets = list(customer_items.values())
    if all_item_sets:
        common_items = sorted(set.intersection(*all_item_sets))
    else:
        common_items = []

    # Count how many customers purchased each item
    item_customer_count = {}
    for items in customer_items.values():
        for item in items:
            item_customer_count[item] = item_customer_count.get(item, 0) + 1

    # Items are exclusive if they appear in exactly one customer's set
    exclusive_items = {}
    for customer, items in customer_items.items():
        exclusive_items[customer] = sorted(
            item for item in items if item_customer_count[item] == 1
        )

    return {
        'unique_items_per_customer': unique_items_per_customer,
        'common_items': common_items,
        'exclusive_items': exclusive_items,
    }


