class InvalidTransitionError(Exception):
    """Raised when an event is not valid for the current state."""


class StateMachine:
    def __init__(self, initial_state):
        self.state = initial_state
        self.states = {}
        self.transitions = {}
        self.history = [initial_state]

    def add_state(self, name, on_enter=None, on_exit=None):
        self.states[name] = {
            'on_enter': on_enter,
            'on_exit': on_exit,
        }

    def add_transition(self, from_state, event, to_state):
        self.transitions[(from_state, event)] = to_state

    def dispatch(self, event, payload=None):
        key = (self.state, event)
        if key not in self.transitions:
            raise InvalidTransitionError(
                f"Event '{event}' is not valid from state '{self.state}'"
            )

        old_state = self.state
        new_state = self.transitions[key]

        # Run exit callback for current state.
        exit_cb = self.states.get(old_state, {}).get('on_exit')
        if exit_cb:
            exit_cb(old_state, event, payload)

        self.state = new_state
        self.history.append(new_state)

        # Run enter callback for new state.
        enter_cb = self.states.get(new_state, {}).get('on_enter')
        if enter_cb:
            enter_cb(new_state, event, payload)

        return new_state


def log_enter(state, event, payload):
    print(f"-> entered {state} via {event}, payload={payload}")


def log_exit(state, event, payload):
    print(f"<- leaving {state} via {event}")


if __name__ == '__main__':
    sm = StateMachine('draft')

    for name in ['draft', 'review', 'approved', 'rejected']:
        sm.add_state(name, on_enter=log_enter, on_exit=log_exit)

    sm.add_transition('draft', 'submit', 'review')
    sm.add_transition('review', 'approve', 'approved')
    sm.add_transition('review', 'reject', 'rejected')
    sm.add_transition('rejected', 'reset', 'draft')

    sm.dispatch('submit', {'author': 'Alice'})
    sm.dispatch('reject', {'reason': 'Missing tests'})
    sm.dispatch('reset')
    sm.dispatch('submit')
    sm.dispatch('approve', {'reviewer': 'Bob'})

    print('current state:', sm.state)
    print('history:', sm.history)

    try:
        sm.dispatch('submit')
    except InvalidTransitionError as e:
        print('error:', e)

