import argparse
import re
from collections import Counter
from pathlib import Path


def count_words(file_path: Path) -> Counter:
    """Read a text file and return a counter of normalized words."""
    text = file_path.read_text(encoding='utf-8')
    words = re.findall(r"\b\w+\b", text.lower())
    return Counter(words)


def main() -> None:
    parser = argparse.ArgumentParser(
        description='Print the most frequent words in a text file.'
    )
    parser.add_argument('file', help='Path to the input text file')
    parser.add_argument(
        '--top',
        type=int,
        default=10,
        help='Number of top results to show (default: 10)'
    )
    args = parser.parse_args()

    if args.top <= 0:
        parser.error('--top must be a positive integer')

    file_path = Path(args.file)
    if not file_path.is_file():
        parser.error(f'File not found: {file_path}')

    counts = count_words(file_path)
    for word, count in counts.most_common(args.top):
        print(f'{word}: {count}')


if __name__ == '__main__':
    main()
}

import re

USERNAME_PATTERN = re.compile(r'^\w{3,20}$')
EMAIL_PATTERN = re.compile(r'^[^@\s]+@[^@\s]+\.[^@\s]+$')


def validate_user_record(record):
    errors = []

    # Validate required fields
    username = record.get('username')
    if not isinstance(username, str) or not USERNAME_PATTERN.match(username):
        errors.append("'username' must be a string of 3-20 letters, digits, or underscores")

    email = record.get('email')
    if not isinstance(email, str) or not EMAIL_PATTERN.match(email):
        errors.append("'email' must be a valid email address")

    age = record.get('age')
    if not isinstance(age, int) or isinstance(age, bool) or not (13 <= age <= 120):
        errors.append("'age' must be an integer between 13 and 120")

    # Validate optional tags
    if 'tags' in record:
        tags = record['tags']
        if not isinstance(tags, list):
            errors.append("'tags' must be a list of non-empty strings")
        else:
            if any(not isinstance(tag, str) or not tag.strip() for tag in tags):
                errors.append("each tag must be a non-empty string")
            normalized = [tag.strip() for tag in tags if isinstance(tag, str)]
            if len(normalized) != len(set(normalized)):
                errors.append("'tags' must not contain duplicates")

    return {
        'valid': len(errors) == 0,
        'errors': errors,
    }


