from itertools import islice, count


class LazyPipeline:
    def __init__(self, iterable, ops=None):
        self._iterable = iterable
        self._ops = ops or []

    def _clone_with(self, op):
        return LazyPipeline(self._iterable, self._ops + [op])

    def map(self, func):
        return self._clone_with(("map", func))

    def filter(self, predicate):
        return self._clone_with(("filter", predicate))

    def take(self, n):
        return self._clone_with(("take", n))

    def drop(self, n):
        return self._clone_with(("drop", n))

    def flat_map(self, func):
        return self._clone_with(("flat_map", func))

    def __iter__(self):
        it = iter(self._iterable)

        # Apply each transformation lazily by wrapping the iterator.
        for kind, arg in self._ops:
            if kind == "map":
                it = map(arg, it)
            elif kind == "filter":
                it = filter(arg, it)
            elif kind == "take":
                it = islice(it, arg)
            elif kind == "drop":
                it = islice(it, arg, None)
            elif kind == "flat_map":
                it = self._flat_map_iter(it, arg)
            else:
                raise ValueError(f"Unknown operation: {kind}")

        return it

    @staticmethod
    def _flat_map_iter(iterable, func):
        for item in iterable:
            yield from func(item)

    def first(self, default=None):
        return next(iter(self), default)


if __name__ == "__main__":
    # Infinite stream of integers starting at 1.
    numbers = count(1)

    pipeline = (
        LazyPipeline(numbers)
        .map(lambda x: x * x)
        .filter(lambda x: x % 2 == 0)
        .drop(3)
        .take(5)
    )

    print(list(pipeline))
    print(pipeline.first(default="no value"))

def log_action(func):
    """Decorator that logs before and after a login check."""
    def wrapper(username, success):
        print(f"Checking login for {username}...")
        result = func(username, success)
        print(f"Finished login check for {username}.\n")
        return result
    return wrapper


def make_login_tracker(max_attempts):
    """Closure that keeps track of failed login attempts per user."""
    failed_attempts = {}

    @log_action
    def track_login(username, success):
        if username not in failed_attempts:
            failed_attempts[username] = 0

        if success:
            failed_attempts[username] = 0
            return f"{username} logged in successfully. Attempts reset."
        else:
            failed_attempts[username] += 1
            if failed_attempts[username] >= max_attempts:
                return f"{username} is locked out after {failed_attempts[username]} failed attempts."
            return f"{username} failed login attempt {failed_attempts[username]}."

    return track_login


