from functools import lru_cache


def word_break_count(s, words):
    """Count the number of valid segmentations of s using words."""
    word_set = set(words)  # Faster membership checks
    n = len(s)

    @lru_cache(maxsize=None)
    def count_from(index):
        # Reached the end: one complete valid segmentation
        if index == n:
            return 1

        total = 0
        # Try every possible next word starting at index
        for end in range(index + 1, n + 1):
            piece = s[index:end]
            if piece in word_set:
                total += count_from(end)
        return total

    return count_from(0)


def main():
    s = "pineapplepenapple"
    words = ["apple", "pen", "applepen", "pine", "pineapple"]
    result = word_break_count(s, words)
    print(result)  # Expected: 3


