class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_word = False


class PrefixTrie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_word = True

    def search(self, word: str) -> bool:
        node = self._find_node(word)
        return node is not None and node.is_word

    def starts_with(self, prefix: str):
        node = self._find_node(prefix)
        if node is None:
            return []

        results = []
        self._collect_words(node, prefix, results)
        return results

    def _find_node(self, text: str):
        node = self.root
        for ch in text:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

    def _collect_words(self, node, path, results):
        if node.is_word:
            results.append(path)

        for ch in sorted(node.children):
            self._collect_words(node.children[ch], path + ch, results)


def main():
    trie = PrefixTrie()
    words = ["app", "apple", "apex", "bat", "batch", "bar"]

    for word in words:
        trie.insert(word)

    print(trie.search("apple"))   # True
    print(trie.search("apply"))   # False
    print(trie.starts_with("ap")) # ['apex', 'app', 'apple']
    print(trie.starts_with("ba")) # ['bar', 'bat', 'batch']
    print(trie.starts_with("cat"))# []


