from typing import Callable, Iterable, Iterator


def lazy_filter_map(
    numbers: Iterable[int],
    predicate: Callable[[int], bool],
    transform: Callable[[int], int],
    limit: int,
) -> Iterator[int]:
    """Lazily filter and transform values, yielding at most `limit` results."""
    if limit <= 0:
        return

    produced = 0
    for number in numbers:
        if predicate(number):
            yield transform(number)
            produced += 1
            if produced >= limit:
                return


def number_source() -> Iterator[int]:
    """Example source generator that shows when values are pulled."""
    for i in range(1, 11):
        print(f"reading {i}")
        yield i


