def summarize_follow_up_needs(appointments: List[Dict[str, Any]]) -> Dict[str, Any]:
    completed_appointments = [
        appointment
        for appointment in appointments
        if appointment.get("appointment_status") == "completed"
    ]

    completed_count = len(completed_appointments)

    average_duration = (
        sum(appointment.get("consultation_duration", 0) for appointment in completed_appointments) / completed_count
        if completed_count > 0
        else 0.0
    )

    follow_up_patients = [
        appointment.get("patient_id")
        for appointment in completed_appointments
        if appointment.get("consultation_duration", 0) < 10
        or any(
            symptom.lower() in {"chest pain", "shortness of breath"}
            for symptom in appointment.get("reported_symptoms", [])
            if isinstance(symptom, str)
        )
    ]

    return {
        "completed_count": completed_count,
        "average_duration": average_duration,
        "follow_up_patients": follow_up_patients,
    }

def validate_records(records):
    """Validate a list of user records against a simple schema."""
    results = []

    for record in records:
        errors = []

        # Check that the record itself is a dictionary
        if not isinstance(record, dict):
            results.append({
                'valid': False,
                'errors': ['Record must be a dictionary']
            })
            continue

        # Validate name
        if 'name' not in record:
            errors.append("Missing field: name")
        elif not isinstance(record['name'], str) or not record['name'].strip():
            errors.append("'name' must be a non-empty string")

        # Validate age
        if 'age' not in record:
            errors.append("Missing field: age")
        elif not isinstance(record['age'], int) or not (0 <= record['age'] <= 120):
            errors.append("'age' must be an integer between 0 and 120")

        # Validate email
        if 'email' not in record:
            errors.append("Missing field: email")
        elif not isinstance(record['email'], str) or '@' not in record['email']:
            errors.append("'email' must be a string containing '@'")

        results.append({
            'valid': len(errors) == 0,
            'errors': errors
        })

    return results


