    weight = PositiveNumber()

    def __init__(self, name, price, weight, discount_percent=0):
        self.name = name
        self.price = price
        self.weight = weight
        self.discount_percent = discount_percent

    @property
    def discount_percent(self):
        return self._discount_percent

    @discount_percent.setter
    def discount_percent(self, value):
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("discount_percent must be an integer")
        if not 0 <= value <= 90:
            raise ValueError("discount_percent must be between 0 and 90")
        self._discount_percent = value

    @property
    def final_price(self):
        discounted = self.price * (1 - self.discount_percent / 100)
        return round(discounted, 2)

