from abc import ABC, abstractmethod


class Notification(ABC):
    def __init__(self, recipient: str, message: str, priority: str = "normal"):
        self.recipient = recipient
        self.message = message
        self.priority = priority

    @abstractmethod
    def send(self) -> None:
        pass


class EmailNotification(Notification):
    def send(self) -> None:
        print(f"[EMAIL] To: {self.recipient} | Priority: {self.priority} | Message: {self.message}")


class SMSNotification(Notification):
    def send(self) -> None:
        print(f"[SMS] To: {self.recipient} | Priority: {self.priority} | Message: {self.message}")


class PushNotification(Notification):
    def send(self) -> None:
        print(f"[PUSH] To: {self.recipient} | Priority: {self.priority} | Message: {self.message}")


class NotificationFactory:
    @staticmethod
    def create(notification_type: str, recipient: str, message: str, priority: str = "normal") -> Notification:
        notification_type = notification_type.lower()
        mapping = {
            "email": EmailNotification,
            "sms": SMSNotification,
            "push": PushNotification,
        }

        if notification_type not in mapping:
            raise ValueError(f"Unsupported notification type: {notification_type}")

        return mapping[notification_type](recipient, message, priority)


class NotificationBuilder:
    def __init__(self, notification_type: str):
        self.notification_type = notification_type
        self._recipient = None
        self._message = None
        self._priority = "normal"

    def recipient(self, recipient: str):
        self._recipient = recipient
        return self

    def message(self, message: str):
        self._message = message
        return self

    def priority(self, priority: str):
        self._priority = priority
        return self

    def build(self) -> Notification:
        if not self._recipient or not self._message:
            raise ValueError("Recipient and message must be provided before building.")
        return NotificationFactory.create(
            self.notification_type,
            self._recipient,
            self._message,
            self._priority,
        )


if __name__ == "__main__":
    notifications = [
        NotificationBuilder("email")
        .recipient("alice@example.com")
        .message("Your report is ready.")
        .priority("high")
        .build(),

        NotificationBuilder("sms")
        .recipient("+123456789")
        .message("Your verification code is 4821.")
        .build(),

        NotificationBuilder("push")
        .recipient("user_42")
        .message("You have a new follower.")
        .priority("low")
        .build(),
    ]

    for notification in notifications:
        notification.send()

