    return False


def parse_origins(value: str) -> list[str]:
    seen = set()
    origins = []
    for item in value.split(','):
        origin = item.strip()
        if origin and origin not in seen:
            seen.add(origin)
            origins.append(origin)
    return origins


def load_config() -> Config:
    errors = []

    host = os.getenv("APP_HOST", "127.0.0.1").strip() or "127.0.0.1"

    port_raw = os.getenv("APP_PORT", "8000")
    try:
        port = int(port_raw)
        if not (1 <= port <= 65535):
            errors.append("APP_PORT must be between 1 and 65535")
    except ValueError:
        errors.append(f"APP_PORT must be an integer, got {port_raw!r}")
        port = 8000

    debug_raw = os.getenv("APP_DEBUG", "false")
    debug = parse_bool("APP_DEBUG", debug_raw, errors)

    timeout_raw = os.getenv("APP_TIMEOUT", "30.0")
    try:
        timeout = float(timeout_raw)
        if timeout <= 0:
            errors.append("APP_TIMEOUT must be positive")
    except ValueError:
        errors.append(f"APP_TIMEOUT must be a number, got {timeout_raw!r}")
        timeout = 30.0

    origins_raw = os.getenv("APP_ALLOWED_ORIGINS", "")
    allowed_origins = parse_origins(origins_raw)

    if errors:
        raise ValueError("Configuration validation failed: " + "; ".join(errors))

    return Config(
        host=host,
        port=port,
        debug=debug,
        timeout=timeout,
        allowed_origins=allowed_origins,
    )


