import random


def evolve_knapsack(items, capacity, population_size=80, generations=120,
                     mutation_rate=0.02, elite_size=4, seed=None):
    if seed is not None:
        random.seed(seed)

    n = len(items)

    def fitness(chrom):
        weight = sum(g * items[i][0] for i, g in enumerate(chrom))
        value = sum(g * items[i][1] for i, g in enumerate(chrom))
        # Strong penalty for infeasible solutions
        return value if weight <= capacity else value - 10 * (weight - capacity)

    def stats(chrom):
        weight = sum(g * items[i][0] for i, g in enumerate(chrom))
        value = sum(g * items[i][1] for i, g in enumerate(chrom))
        return weight, value

    def tournament_select(pop, k=3):
        contenders = random.sample(pop, k)
        return max(contenders, key=fitness)

    def crossover(a, b):
        if n < 2:
            return a[:], b[:]
        point = random.randint(1, n - 1)
        return a[:point] + b[point:], b[:point] + a[point:]

    def mutate(chrom):
        for i in range(n):
            if random.random() < mutation_rate:
                chrom[i] ^= 1
        return chrom

    # Initialize random population
    population = [[random.randint(0, 1) for _ in range(n)] for _ in range(population_size)]
    history = []

    for _ in range(generations):
        population.sort(key=fitness, reverse=True)
        history.append(fitness(population[0]))

        # Preserve elites
        new_population = [ind[:] for ind in population[:elite_size]]

        while len(new_population) < population_size:
            p1 = tournament_select(population)
            p2 = tournament_select(population)
            c1, c2 = crossover(p1, p2)
            new_population.append(mutate(c1))
            if len(new_population) < population_size:
                new_population.append(mutate(c2))

        population = new_population

    # Prefer feasible best solution if available
    feasible = [c for c in population if stats(c)[0] <= capacity]
    best = max(feasible, key=lambda c: stats(c)[1]) if feasible else max(population, key=fitness)
    best_weight, best_value = stats(best)

    return {
        'best_chromosome': best,
        'best_value': best_value,
        'best_weight': best_weight,
        'history': history,
    }

from pathlib import Path


def analyze_log(file_path: str) -> None:
    path = Path(file_path)

    if not path.exists():
        print(f"Log file not found: {file_path}")
        return

    counts = {"INFO": 0, "WARNING": 0, "ERROR": 0}
    latest_error = None

    with path.open("r", encoding="utf-8") as log_file:
        for line in log_file:
            line = line.strip()
            if not line:
                continue  # Skip empty lines

            for level in counts:
                if level in line:
                    counts[level] += 1
                    if level == "ERROR":
                        latest_error = line
                    break

    print("Log Summary")
    print(f"INFO: {counts['INFO']}")
    print(f"WARNING: {counts['WARNING']}")
    print(f"ERROR: {counts['ERROR']}")

    if latest_error:
        print(f"Most recent ERROR: {latest_error}")
    else:
        print("Most recent ERROR: None")


