from collections import Counter
from functools import lru_cache
from typing import List, Tuple


def top_k_frequent_words(texts: List[str], k: int) -> List[Tuple[str, int]]:
    """Return the k most frequent normalized words across all input texts."""

    @lru_cache(maxsize=None)
    def normalize(token: str) -> str:
        # Lowercase and remove non-alphanumeric characters from both ends.
        return token.lower().strip(".,!?;:'\"()[]{}<>-_/")

    counts = Counter()

    for text in texts:
        for raw_token in text.split():
            word = normalize(raw_token)
            if word:  # Ignore empty results after normalization.
                counts[word] += 1

    # Sort by descending frequency, then alphabetically.
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ranked[:k]


