    connections = [[0, 1], [1, 2], [3, 4]]
    print(count_groups(n, connections))  # Output: 3

from collections import OrderedDict
from functools import wraps
from threading import RLock


def memoize(maxsize=None):
    """Thread-safe memoization decorator with optional LRU eviction."""
    def decorator(func):
        cache = OrderedDict()
        lock = RLock()
        stats = {"hits": 0, "misses": 0}

        def make_key(args, kwargs):
            # Assumes all arguments are hashable as required by the task.
            if kwargs:
                return args + (object(),) + tuple(sorted(kwargs.items()))
            return args

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)

            with lock:
                if key in cache:
                    stats["hits"] += 1
                    cache.move_to_end(key)  # Mark as recently used.
                    return cache[key]
                stats["misses"] += 1

            # Compute outside the lock to avoid blocking other threads.
            result = func(*args, **kwargs)

            with lock:
                cache[key] = result
                cache.move_to_end(key)
                if maxsize is not None and len(cache) > maxsize:
                    cache.popitem(last=False)  # Evict least recently used.
            return result

        def cache_info():
            with lock:
                return {
                    "hits": stats["hits"],
                    "misses": stats["misses"],
                    "current_size": len(cache),
                    "maxsize": maxsize,
                }

        def cache_clear():
            with lock:
                cache.clear()
                stats["hits"] = 0
                stats["misses"] = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator


@memoize(maxsize=128)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)


if __name__ == "__main__":
    print(fib(35))
    print(fib.cache_info())
    fib.cache_clear()
    print(fib.cache_info())

import time
from typing import Any, Dict, List, Optional

import requests


class ApiClientError(Exception):
    """Raised for API client errors."""


class ApiClient:
    def __init__(
        self,
        base_url: str,
        token: Optional[str] = None,
        timeout: float = 5.0,
        max_retries: int = 3,
        backoff_factor: float = 0.5,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.max_retries = max_retries
        self.backoff_factor = backoff_factor
        self.session = requests.Session()
        self.session.headers.update({"Accept": "application/json"})
        if token:
            self.session.headers["Authorization"] = f"Bearer {token}"

    def _request(self, method: str, endpoint: str, **kwargs: Any) -> requests.Response:
        url = f"{self.base_url}/{endpoint.lstrip('/')}"
        last_error = None

        for attempt in range(self.max_retries + 1):
            try:
                response = self.session.request(method, url, timeout=self.timeout, **kwargs)
                if response.status_code == 429 or 500 <= response.status_code < 600:
                    if attempt < self.max_retries:
                        delay = self.backoff_factor * (2 ** attempt)
                        time.sleep(delay)
                        continue
                if response.status_code >= 400:
                    raise ApiClientError(
                        f"HTTP {response.status_code} error for {url}: {response.text[:200]}"
                    )
                return response
            except requests.RequestException as exc:
                last_error = exc
                if attempt < self.max_retries:
                    delay = self.backoff_factor * (2 ** attempt)
                    time.sleep(delay)
                    continue
                break

        raise ApiClientError(f"Request failed for {url}: {last_error}")

    def get_json(self, endpoint: str, params: Optional[Dict[str, Any]] = None) -> Any:
        response = self._request("GET", endpoint, params=params)
        try:
            return response.json()
        except ValueError as exc:
            raise ApiClientError(f"Invalid JSON response from {response.url}") from exc

    def get_all_pages(self, endpoint: str, page_param: str = "page") -> List[Any]:
        results: List[Any] = []
        page = 1

        while True:
            data = self.get_json(endpoint, params={page_param: page})
            if not isinstance(data, list):
                raise ApiClientError("Paginated endpoint must return a JSON list")
            if not data:
                break
            results.extend(data)
            page += 1

        return results


if __name__ == "__main__":
