import os
import time
import hmac
import json
import base64
import hashlib


class AuthService:
    def __init__(self, secret_key: bytes):
        self.secret_key = secret_key
        self.users = {}  # username -> {salt, password_hash, roles}

    def _b64encode(self, data: bytes) -> str:
        return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

    def _b64decode(self, data: str) -> bytes:
        padding = '=' * (-len(data) % 4)
        return base64.urlsafe_b64decode(data + padding)

    def _hash_password(self, password: str, salt: bytes) -> bytes:
        return hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100_000)

    def register_user(self, username: str, password: str, roles):
        if username in self.users:
            raise ValueError('User already exists')
        salt = os.urandom(16)
        password_hash = self._hash_password(password, salt)
        self.users[username] = {
            'salt': salt,
            'password_hash': password_hash,
            'roles': set(roles),
        }

    def login(self, username: str, password: str, ttl_seconds: int = 3600) -> str:
        user = self.users.get(username)
        if not user:
            raise ValueError('Invalid credentials')

        candidate_hash = self._hash_password(password, user['salt'])
        if not hmac.compare_digest(candidate_hash, user['password_hash']):
            raise ValueError('Invalid credentials')

        payload = {
            'sub': username,
            'exp': int(time.time()) + ttl_seconds,
        }
        payload_bytes = json.dumps(payload, separators=(',', ':'), sort_keys=True).encode('utf-8')
        payload_b64 = self._b64encode(payload_bytes)
        signature = hmac.new(self.secret_key, payload_b64.encode('ascii'), hashlib.sha256).digest()
        return f'{payload_b64}.{self._b64encode(signature)}'

    def authorize(self, token: str, required_role: str) -> bool:
        try:
            payload_b64, sig_b64 = token.split('.', 1)
            expected_sig = hmac.new(self.secret_key, payload_b64.encode('ascii'), hashlib.sha256).digest()
            actual_sig = self._b64decode(sig_b64)
            if not hmac.compare_digest(expected_sig, actual_sig):
                return False

            payload = json.loads(self._b64decode(payload_b64).decode('utf-8'))
            if payload.get('exp', 0) < int(time.time()):
                return False

            username = payload.get('sub')
            user = self.users.get(username)
            return bool(user and required_role in user['roles'])
        except Exception:
            return False


if __name__ == '__main__':
    auth = AuthService(secret_key=b'super-secret-key')
    auth.register_user('alice', 'S3curePass!', ['admin', 'editor'])
    token = auth.login('alice', 'S3curePass!', ttl_seconds=60)
    print(auth.authorize(token, 'admin'))   # True
    print(auth.authorize(token, 'viewer'))  # False

