class DisjointSet:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])  # Path compression
        return self.parent[x]

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        # Union by rank
        if self.rank[ra] < self.rank[rb]:
            self.parent[ra] = rb
        elif self.rank[ra] > self.rank[rb]:
            self.parent[rb] = ra
        else:
            self.parent[rb] = ra
            self.rank[ra] += 1
        return True


def max_removable_edges(n, edges, threshold):
    """
    Count how many edges with weight <= threshold are redundant.

    An eligible edge is redundant if adding it does not connect two previously
    separate components among the eligible edges.
    """
    dsu = DisjointSet(n)
    removable = 0

    for u, v, w in edges:
        if w <= threshold:
            if not dsu.union(u, v):
                removable += 1

    return removable


