import time
from functools import wraps


def retry_with_backoff(max_attempts=3, base_delay=0.1, exceptions=(Exception,), on_retry=None):
    # Configuration is captured by the decorator factory closure.
    def decorator(func):
        # Runtime state is preserved per wrapped function via closure variables.
        stats = {
            'total_calls': 0,
            'total_retries': 0,
            'total_failures': 0,
        }

        @wraps(func)
        def wrapper(*args, **kwargs):
            stats['total_calls'] += 1
            last_error = None

            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_error = exc
                    if attempt == max_attempts:
                        stats['total_failures'] += 1
                        raise

                    stats['total_retries'] += 1
                    delay = base_delay * (2 ** (attempt - 1))

                    if on_retry is not None:
                        on_retry(func.__name__, attempt, delay, exc)

                    time.sleep(delay)

            # Defensive fallback; normally unreachable because final attempt raises.
            raise last_error

        def get_stats():
            return dict(stats)

        wrapper.get_stats = get_stats
        return wrapper

    return decorator


# Demo callback for retry events.
def log_retry(name, attempt, delay, exc):
    print(f'Retrying {name}: attempt={attempt}, delay={delay:.2f}s, error={exc}')


def make_flaky_divide(failures_before_success):
    remaining_failures = failures_before_success

    @retry_with_backoff(max_attempts=5, base_delay=0.05, exceptions=(ZeroDivisionError,), on_retry=log_retry)
    def flaky_divide(a, b):
        nonlocal remaining_failures
        if remaining_failures > 0:
            remaining_failures -= 1
            raise ZeroDivisionError('Simulated transient division failure')
        return a / b

    return flaky_divide


