    result = divide(10, 2)
    print('Result:', result)
    print('Stats:', divide.get_stats())

def find_nested_value(data, target_key):
    """Recursively search nested dictionaries and lists for the first value of target_key."""
    if isinstance(data, dict):
        # Check current dictionary first
        if target_key in data:
            return data[target_key]

        # Then search nested values in insertion order
        for value in data.values():
            result = find_nested_value(value, target_key)
            if result is not None:
                return result

    elif isinstance(data, list):
        # Search each item in the list from left to right
        for item in data:
            result = find_nested_value(item, target_key)
            if result is not None:
                return result

    # Primitive value or key not found
    return None


