    def __init__(self):
        self.routes = []

    def add_route(self, pattern, handler):
        """Register a route pattern with its handler name."""
        segments = self._split_path(pattern)
        self.routes.append((segments, handler))

    def resolve(self, path):
        """Match a path and return handler + extracted params, or None."""
        path_segments = self._split_path(path)

        for pattern_segments, handler in self.routes:
            if len(pattern_segments) != len(path_segments):
                continue

            params = {}
            matched = True

            for pattern_seg, path_seg in zip(pattern_segments, path_segments):
                if self._is_dynamic(pattern_seg):
                    param_name = pattern_seg[1:-1]
                    params[param_name] = path_seg
                elif pattern_seg != path_seg:
                    matched = False
                    break

            if matched:
                return {"handler": handler, "params": params}

        return None

    @staticmethod
    def _split_path(path):
        """Normalize and split a path into segments."""
        stripped = path.strip("/")
        return [] if stripped == "" else stripped.split("/")

    @staticmethod
    def _is_dynamic(segment):
        """Check whether a segment is a dynamic placeholder like <id>."""
        return segment.startswith("<") and segment.endswith(">") and len(segment) > 2


