class TransactionError(Exception):
    """Base class for all transaction-related errors."""


class InvalidCurrencyError(TransactionError):
    """Raised when a transaction uses an unsupported currency."""


class InvalidAmountError(TransactionError):
    """Raised when a transaction amount is zero or negative."""


class InsufficientFundsError(TransactionError):
    """Raised when the account balance is too low for the transaction."""


class FraudDetectedError(TransactionError):
    """Raised when the transaction is flagged as potentially fraudulent."""


def process_transaction(account_balance, amount, currency, allowed_currencies, fraud_score):
    """Validate and process a payment transaction.

    Validation order:
    1. Currency must be supported.
    2. Amount must be positive.
    3. Fraud score must not exceed 0.8.
    4. Account must have sufficient funds.
    """
    if currency not in allowed_currencies:
        raise InvalidCurrencyError(f"Unsupported currency: {currency}")

    if amount <= 0:
        raise InvalidAmountError(f"Amount must be positive, got {amount}")

    if fraud_score > 0.8:
        raise FraudDetectedError(f"Fraud score too high: {fraud_score}")

    if amount > account_balance:
        raise InsufficientFundsError(
            f"Insufficient funds: balance={account_balance}, amount={amount}"
        )

    return account_balance - amount


def safe_process(account_balance, amount, currency, allowed_currencies, fraud_score):
    """Run transaction processing and return a structured result."""
    try:
        new_balance = process_transaction(
            account_balance, amount, currency, allowed_currencies, fraud_score
        )
        return {"status": "success", "balance": new_balance}
    except TransactionError as exc:
        return {
            "status": "error",
            "error_type": type(exc).__name__,
            "message": str(exc),
        }

from typing import List, Dict, Any


def chunked(records: List[Dict[str, Any]], batch_size: int):
    """Yield successive batches from the input records."""
    for i in range(0, len(records), batch_size):
        yield records[i:i + batch_size]


class BatchPipeline:
    def __init__(self, batch_size: int = 3):
        if batch_size <= 0:
            raise ValueError("batch_size must be greater than 0")
        self.batch_size = batch_size

    def validate_and_transform(self, record: Dict[str, Any]) -> Dict[str, Any]:
        """Validate a record and return a transformed copy."""
        email = str(record.get("email", "")).strip()
        if "@" not in email:
            raise ValueError("invalid email")

        try:
            amount = float(record.get("amount"))
        except (TypeError, ValueError):
            raise ValueError("amount must be a number")

        if amount <= 0:
            raise ValueError("amount must be positive")

        return {
            "id": record.get("id"),
            "name": str(record.get("name", "")).strip().title(),
            "email": email,
            "amount": round(amount, 2),
        }

    def process(self, records: List[Dict[str, Any]]) -> Dict[str, Any]:
        valid_records = []
        rejected_records = []

        for batch in chunked(records, self.batch_size):
            for record in batch:
                try:
                    transformed = self.validate_and_transform(record)
                    valid_records.append(transformed)
                except ValueError as exc:
                    rejected_records.append({
                        "record": record,
                        "error": str(exc),
                    })

        return {
            "total_records": len(records),
            "valid_count": len(valid_records),
            "invalid_count": len(rejected_records),
            "valid_records": valid_records,
            "rejected_records": rejected_records,
        }


