class TrieNode:
    def __init__(self):
        self.children = {}
        self.pass_count = 0   # number of words passing through this node
        self.end_count = 0    # number of words ending at this node


class PrefixTrie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        node.pass_count += 1
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            node.pass_count += 1
        node.end_count += 1

    def contains(self, word: str) -> bool:
        node = self.root
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.end_count > 0

    def delete(self, word: str) -> bool:
        if not self.contains(word):
            return False

        node = self.root
        node.pass_count -= 1
        stack = []  # (parent, char, child)

        for ch in word:
            child = node.children[ch]
            stack.append((node, ch, child))
            child.pass_count -= 1
            node = child

        node.end_count -= 1

        # Prune unused nodes from the end of the word backward.
        for parent, ch, child in reversed(stack):
            if child.pass_count == 0 and child.end_count == 0 and not child.children:
                del parent.children[ch]
            else:
                break
        return True

    def count_prefix(self, prefix: str) -> int:
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return 0
            node = node.children[ch]
        return node.pass_count

    def suggest(self, prefix: str, k: int):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]

        result = []

        def dfs(curr_node, path):
            if len(result) >= k:
                return

            # Add the full word as many times as its frequency allows.
            if curr_node.end_count:
                take = min(curr_node.end_count, k - len(result))
                result.extend([prefix + path] * take)
                if len(result) >= k:
                    return

            for ch in sorted(curr_node.children):
                dfs(curr_node.children[ch], path + ch)
                if len(result) >= k:
                    return

        dfs(node, "")
        return result


