    print(trie.count_prefix("ap"))     # 5
    print(trie.suggest("ap", 4))       # ['ape', 'apex', 'app', 'app']
    trie.delete("app")
    print(trie.suggest("app", 3))      # ['app', 'apple']

class Temperature:
    def __init__(self, celsius):
        self.celsius = celsius  # Uses the property setter for validation

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError("Temperature cannot be below absolute zero.")
        self._celsius = float(value)

    @property
    def fahrenheit(self):
        return (self._celsius * 9 / 5) + 32

    @fahrenheit.setter
    def fahrenheit(self, value):
        self.celsius = (value - 32) * 5 / 9  # Reuse Celsius validation


