def parse_kv_record(line: str) -> dict:
    """Parse semicolon-separated key=value pairs with quoted value support."""
    result = {}
    i, n = 0, len(line)

    while i < n:
        # Skip whitespace and empty pairs (;;)
        while i < n and line[i].isspace():
            i += 1
        while i < n and line[i] == ';':
            i += 1
            while i < n and line[i].isspace():
                i += 1
        if i >= n:
            break

        # Parse key
        key_start = i
        while i < n and line[i] not in '=;':
            i += 1
        key = line[key_start:i].strip()
        if not key:
            raise ValueError('Missing key')
        if i >= n or line[i] != '=':
            raise ValueError(f"Missing '=' after key: {key!r}")
        i += 1

        # Skip whitespace before value
        while i < n and line[i].isspace():
            i += 1
        if i >= n:
            result[key] = ''
            break

        # Parse value
        if line[i] == '"':
            i += 1
            chars = []
            while i < n:
                ch = line[i]
                if ch == '\\':
                    i += 1
                    if i >= n:
                        raise ValueError('Dangling escape in quoted value')
                    esc = line[i]
                    if esc in {'\\', '"'}:
                        chars.append(esc)
                    else:
                        chars.append(esc)  # preserve other escaped chars literally
                    i += 1
                elif ch == '"':
                    i += 1
                    break
                else:
                    chars.append(ch)
                    i += 1
            else:
                raise ValueError('Unterminated quoted value')

            # After quoted value, only whitespace then semicolon/end is allowed
            while i < n and line[i].isspace():
                i += 1
            if i < n and line[i] != ';':
                raise ValueError('Unexpected characters after quoted value')
            value = ''.join(chars)
        else:
            value_start = i
            while i < n and line[i] != ';':
                i += 1
            value = line[value_start:i].strip()

        result[key] = value

        # Consume pair separator if present
        if i < n and line[i] == ';':
            i += 1

    return result


