from collections import defaultdict


class EventBus:
    def __init__(self):
        self._subscribers = defaultdict(list)

    def subscribe(self, event_name, callback):
        self._subscribers[event_name].append(callback)

    def unsubscribe(self, event_name, callback):
        if event_name in self._subscribers:
            self._subscribers[event_name] = [cb for cb in self._subscribers[event_name] if cb != callback]

    def emit(self, event_name, **data):
        for callback in list(self._subscribers.get(event_name, [])):
            callback(**data)


class Scheduler:
    def __init__(self):
        self.bus = EventBus()
        self.jobs = {}
        self.bus.subscribe("job_completed", self._on_job_completed)

    def add_job(self, job_id, dependencies=None):
        if job_id in self.jobs:
            raise ValueError(f"Duplicate job: {job_id}")

        dependencies = set(dependencies or [])
        unknown = dependencies - self.jobs.keys()
        if unknown:
            raise ValueError(f"Unknown dependencies: {sorted(unknown)}")

        status = "ready" if not dependencies else "blocked"
        self.jobs[job_id] = {
            "dependencies": dependencies,
            "completed_dependencies": set(),
            "status": status,
        }

    def complete_job(self, job_id):
        job = self.jobs.get(job_id)
        if not job:
            raise ValueError(f"Unknown job: {job_id}")
        if job["status"] == "completed":
            return
        if job["status"] == "blocked":
            raise ValueError(f"Job is still blocked: {job_id}")

        job["status"] = "completed"
        self.bus.emit("job_completed", job_id=job_id)

    def _on_job_completed(self, job_id):
        for other_id, job in self.jobs.items():
            if job["status"] != "blocked":
                continue
            if job_id in job["dependencies"]:
                job["completed_dependencies"].add(job_id)
                if job["completed_dependencies"] == job["dependencies"]:
                    job["status"] = "ready"

    def list_jobs(self, status=None):
        if status is None:
            return {job_id: info["status"] for job_id, info in self.jobs.items()}
        return [job_id for job_id, info in self.jobs.items() if info["status"] == status]


if __name__ == "__main__":
