import threading
import multiprocessing


def count_evens(limit, results, index):
    """Count how many numbers from 1 to limit are even."""
    count = 0
    for number in range(1, limit + 1):
        if number % 2 == 0:
            count += 1
    results[index] = count


def run_with_threads(limit):
    results = [0, 0]
    threads = [
        threading.Thread(target=count_evens, args=(limit, results, 0)),
        threading.Thread(target=count_evens, args=(limit, results, 1)),
    ]

    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()

    print('Threading results:', results)


def run_with_processes(limit):
    results = multiprocessing.Array('i', 2)
    processes = [
        multiprocessing.Process(target=count_evens, args=(limit, results, 0)),
        multiprocessing.Process(target=count_evens, args=(limit, results, 1)),
    ]

    for process in processes:
        process.start()
    for process in processes:
        process.join()

    print('Multiprocessing results:', list(results))


if __name__ == '__main__':
    limit = 1_000_000
    run_with_threads(limit)
    run_with_processes(limit)

def logging_middleware(request, response):
    """Log the request path."""
    print(f"[LOG] Request path: {request.get('path')}")
    return True  # Continue to next middleware


def auth_middleware(request, response):
    """Check if the user is authenticated."""
    user = request.get('user', {})
    if not user.get('authenticated', False):
        response['status'] = 401
        response['body'] = 'Unauthorized'
        return False  # Stop the pipeline
    return True


def header_middleware(request, response):
    """Add a default response header."""
    response.setdefault('headers', {})['Content-Type'] = 'text/plain'
    return True


def run_pipeline(request, middleware_list):
    """Run middleware in order and stop if any middleware returns False."""
    response = {
        'status': 200,
        'body': 'Request processed successfully',
        'headers': {}
    }

    for middleware in middleware_list:
        should_continue = middleware(request, response)
        if not should_continue:
            break

    return response


