class Router:
    def __init__(self):
        self.routes = []

    def add_route(self, pattern, handler):
        # Store each route pattern with its handler function
        self.routes.append((pattern, handler))

    def match(self, path):
        # Try to find the first matching route
        for pattern, handler in self.routes:
            params = self._match_pattern(pattern, path)
            if params is not None:
                return handler(**params)
        return f"404 Not Found: {path}"

    def _match_pattern(self, pattern, path):
        pattern_parts = pattern.strip('/').split('/') if pattern.strip('/') else []
        path_parts = path.strip('/').split('/') if path.strip('/') else []

        if len(pattern_parts) != len(path_parts):
            return None

        params = {}
        for pattern_part, path_part in zip(pattern_parts, path_parts):
            if pattern_part.startswith('<') and pattern_part.endswith('>'):
                param_name = pattern_part[1:-1]
                params[param_name] = path_part
            elif pattern_part != path_part:
                return None

        return params


