class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.components = n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False

        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1

        self.components -= 1
        return True


def min_operations_to_connect(n: int, edges: list[list[int]]) -> int:
    # Kruskal's algorithm with Union-Find
    uf = UnionFind(n)
    total_cost = 0

    for u, v, w in sorted(edges, key=lambda e: e[2]):
        if uf.union(u, v):
            total_cost += w
            if uf.components == 1:
                return total_cost

    return -1 if n > 0 and uf.components != 1 else total_cost


