import re
from typing import Callable, Dict, List, Optional, Tuple


class Router:
    _CONVERTERS = {
        'str': (r'[^/]+', str),
        'int': (r'\d+', int),
        'slug': (r'[a-z0-9-]+', str),
    }

    def __init__(self):
        self._routes: List[Dict] = []

    def add_route(self, method: str, pattern: str, handler: Callable) -> None:
        method = method.upper()
        regex_parts = ['^']
        param_converters: Dict[str, Callable] = {}
        static_count = 0
        typed_count = 0

        for segment in pattern.strip('/').split('/') if pattern.strip('/') else []:
            regex_parts.append('/')
            if segment.startswith('<') and segment.endswith('>'):
                conv_name, param_name = segment[1:-1].split(':', 1)
                if conv_name not in self._CONVERTERS:
                    raise ValueError(f'Unknown converter: {conv_name}')
                regex, converter = self._CONVERTERS[conv_name]
                regex_parts.append(f'(?P<{param_name}>{regex})')
                param_converters[param_name] = converter
                typed_count += 1
            else:
                regex_parts.append(re.escape(segment))
                static_count += 1

        if pattern == '/':
            regex_parts.append('/')

        regex_parts.append('$')
        compiled = re.compile(''.join(regex_parts))

        self._routes.append({
            'method': method,
            'pattern': pattern,
            'handler': handler,
            'regex': compiled,
            'converters': param_converters,
            # Higher specificity wins: more static segments, then fewer typed params.
            'priority': (static_count, -typed_count),
        })

    def resolve(self, method: str, path: str) -> Optional[Tuple[Callable, Dict[str, object]]]:
        method = method.upper()
        candidates = []

        for route in self._routes:
            if route['method'] != method:
                continue
            match = route['regex'].match(path)
            if not match:
                continue

            params = {
                name: route['converters'][name](value)
                for name, value in match.groupdict().items()
            }
            candidates.append((route['priority'], route['handler'], params))

        if not candidates:
            return None

        _, handler, params = max(candidates, key=lambda item: item[0])
        return handler, params


