import random
import math


def estimate_pi(num_samples, seed=None):
    """Estimate pi using Monte Carlo sampling inside a unit square."""
    if num_samples <= 0:
        raise ValueError("num_samples must be a positive integer")

    if seed is not None:
        random.seed(seed)

    inside_circle = 0

    for _ in range(num_samples):
        x = random.uniform(-1, 1)
        y = random.uniform(-1, 1)

        if x * x + y * y <= 1.0:
            inside_circle += 1

    return 4 * inside_circle / num_samples


def main():
    samples = 100000
    estimated_pi = estimate_pi(samples, seed=42)
    error = abs(math.pi - estimated_pi)

    print(f"Samples: {samples}")
    print(f"Estimated pi: {estimated_pi:.6f}")
    print(f"Actual pi:    {math.pi:.6f}")
    print(f"Absolute error: {error:.6f}")


if __name__ == "__main__":
    main()
}

class ConfigRegistry:
    """Singleton registry for application configuration settings."""

    _instance = None

    def __new__(cls):
        # Ensure only one instance of the registry is ever created.
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._settings = {}
        return cls._instance

    def register(self, key, value):
        """Add or update a configuration setting."""
        self._settings[key] = value

    def get(self, key, default=None):
        """Retrieve a setting, returning default if missing."""
        return self._settings.get(key, default)

    def all_settings(self):
        """Return a copy of all registered settings."""
        return dict(self._settings)


if __name__ == "__main__":
    registry_a = ConfigRegistry()
    registry_b = ConfigRegistry()

    registry_a.register("host", "localhost")
    registry_b.register("port", 8080)

    print("Same instance:", registry_a is registry_b)
    print("Host:", registry_b.get("host"))
    print("Port:", registry_a.get("port"))
    print("All settings:", registry_a.all_settings())

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import List


class DiscountStrategy(ABC):
    """Strategy interface for computing a discounted total."""

    @abstractmethod
    def apply(self, subtotal: float) -> float:
        pass


class NoDiscount(DiscountStrategy):
    def apply(self, subtotal: float) -> float:
        return subtotal


@dataclass
class PercentageDiscount(DiscountStrategy):
    percent: float  # e.g. 15 for 15%

    def apply(self, subtotal: float) -> float:
        return subtotal * (1 - self.percent / 100)


@dataclass
class FixedAmountDiscount(DiscountStrategy):
    amount: float

    def apply(self, subtotal: float) -> float:
        return max(0.0, subtotal - self.amount)


@dataclass
class BulkDiscount(DiscountStrategy):
    threshold: float
    amount: float

    def apply(self, subtotal: float) -> float:
        if subtotal >= self.threshold:
            return max(0.0, subtotal - self.amount)
        return subtotal


@dataclass
class Cart:
    strategy: DiscountStrategy = field(default_factory=NoDiscount)
    items: List[float] = field(default_factory=list)

    def add_item(self, price: float) -> None:
        if price < 0:
            raise ValueError("Item price cannot be negative")
        self.items.append(price)

    def set_strategy(self, strategy: DiscountStrategy) -> None:
        self.strategy = strategy

    def subtotal(self) -> float:
        return sum(self.items)

    def total(self) -> float:
        discounted = self.strategy.apply(self.subtotal())
        return round(discounted, 2)


if __name__ == "__main__":
    cart = Cart()
    for price in (29.99, 15.50, 60.00):
        cart.add_item(price)

    print("Subtotal:", round(cart.subtotal(), 2))
    print("No discount:", cart.total())

    cart.set_strategy(PercentageDiscount(10))
    print("10% off:", cart.total())

    cart.set_strategy(FixedAmountDiscount(20))
    print("$20 off:", cart.total())

    cart.set_strategy(BulkDiscount(threshold=100, amount=25))
    print("Bulk discount:", cart.total())

class Router:
    def __init__(self):
        # Store routes as path -> handler function
        self.routes = {}

    def add_route(self, path, handler):
        # Register a new route
        self.routes[path] = handler

    def resolve(self, path):
        # Return handler result if path exists, otherwise 404 message
        handler = self.routes.get(path)
        if handler is None:
            return '404 Not Found'
        return handler()


