from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Union
from collections import defaultdict, Counter


REQUIRED_FIELDS = {
    "patient_id",
    "encounter_date",
    "diagnosis_codes",
    "medication_list",
    "allergy_list",
    "lab_results",
}


class ValidationError(ValueError):
    pass


@dataclass(frozen=True)
class Alert:
    encounter_date: Any
    alert_type: str
    explanation: str

    def to_dict(self) -> Dict[str, Any]:
        return {
            "encounter_date": self.encounter_date,
            "alert_type": self.alert_type,
            "explanation": self.explanation,
        }


@dataclass
class Encounter:
    patient_id: Any
    encounter_date: Any
    diagnosis_codes: List[str] = field(default_factory=list)
    medication_list: List[str] = field(default_factory=list)
    allergy_list: List[str] = field(default_factory=list)
    lab_results: Dict[str, Any] = field(default_factory=dict)

    @classmethod
    def from_input(cls, data: Union["Encounter", Mapping[str, Any], Any]) -> "Encounter":
        if isinstance(data, cls):
            data.validate()
            return data

        if hasattr(data, "__dict__") and not isinstance(data, Mapping):
            raw = {
                "patient_id": getattr(data, "patient_id", None),
                "encounter_date": getattr(data, "encounter_date", None),
                "diagnosis_codes": getattr(data, "diagnosis_codes", None),
                "medication_list": getattr(data, "medication_list", None),
                "allergy_list": getattr(data, "allergy_list", None),
                "lab_results": getattr(data, "lab_results", None),
            }
        elif isinstance(data, Mapping):
            raw = dict(data)
        else:
            raise ValidationError("Each encounter must be a dict-like object or Encounter instance.")

        missing = [field for field in REQUIRED_FIELDS if field not in raw or raw[field] is None]
        if missing:
            raise ValidationError(f"Encounter missing required fields: {', '.join(sorted(missing))}")

        encounter = cls(
            patient_id=raw["patient_id"],
            encounter_date=raw["encounter_date"],
            diagnosis_codes=_ensure_list_of_strings(raw["diagnosis_codes"], "diagnosis_codes"),
            medication_list=_ensure_list_of_strings(raw["medication_list"], "medication_list"),
            allergy_list=_ensure_list_of_strings(raw["allergy_list"], "allergy_list"),
            lab_results=_ensure_lab_results(raw["lab_results"]),
        )
        encounter.validate()
        return encounter

    def validate(self) -> None:
        if self.patient_id is None or self.patient_id == "":
            raise ValidationError("patient_id must not be empty.")
        if self.encounter_date is None or self.encounter_date == "":
            raise ValidationError("encounter_date must not be empty.")
        _ensure_list_of_strings(self.diagnosis_codes, "diagnosis_codes")
        _ensure_list_of_strings(self.medication_list, "medication_list")
        _ensure_list_of_strings(self.allergy_list, "allergy_list")
        _ensure_lab_results(self.lab_results)


class AlertRule:
    alert_type: str = "generic"

    def evaluate(self, encounter: Encounter, context: Optional[Dict[str, Any]] = None) -> List[Alert]:
        raise NotImplementedError


class MedicationAllergyConflictRule(AlertRule):
    alert_type = "medication_allergy_conflict"

    def __init__(self, medication_allergy_map: Optional[Mapping[str, Sequence[str]]] = None) -> None:
        self.medication_allergy_map = {
            _normalize_text(med): {_normalize_text(a) for a in allergies}
            for med, allergies in (medication_allergy_map or {}).items()
        }

    def evaluate(self, encounter: Encounter, context: Optional[Dict[str, Any]] = None) -> List[Alert]:
        alerts: List[Alert] = []
        allergies_normalized = {_normalize_text(a): a for a in encounter.allergy_list}
        if not allergies_normalized:
            return alerts

        for medication in encounter.medication_list:
            med_norm = _normalize_text(medication)
            matched_allergies: List[str] = []

            if med_norm in allergies_normalized:
                matched_allergies.append(allergies_normalized[med_norm])

            mapped_allergies = self.medication_allergy_map.get(med_norm, set())
            for allergy_norm in mapped_allergies:
                if allergy_norm in allergies_normalized:
                    matched_allergies.append(allergies_normalized[allergy_norm])

            if matched_allergies:
                unique_matches = sorted(set(matched_allergies), key=str.lower)
                alerts.append(
                    Alert(
                        encounter_date=encounter.encounter_date,
                        alert_type=self.alert_type,
                        explanation=(
                            f"Medication '{medication}' may conflict with recorded allergy/allergies: "
                            f"{', '.join(unique_matches)}."
                        ),
                    )
                )
        return alerts


class AbnormalLabRule(AlertRule):
    alert_type = "abnormal_lab"

    def __init__(self, reference_ranges: Mapping[str, Mapping[str, Any]]) -> None:
        self.reference_ranges = {
            _normalize_text(test_name): dict(range_info)
            for test_name, range_info in reference_ranges.items()
        }

    def evaluate(self, encounter: Encounter, context: Optional[Dict[str, Any]] = None) -> List[Alert]:
        alerts: List[Alert] = []

        for lab_name, result in encounter.lab_results.items():
            lab_key = _normalize_text(lab_name)
            if lab_key not in self.reference_ranges:
                continue

            ref = self.reference_ranges[lab_key]
            value = _extract_lab_value(result)
            if value is None:
                continue

            low = ref.get("low")
            high = ref.get("high")
            unit = _extract_lab_unit(result) or ref.get("unit")

            abnormal = False
            direction = None

            if low is not None and value < low:
                abnormal = True
                direction = "low"
            elif high is not None and value > high:
                abnormal = True
                direction = "high"

            if abnormal:
                range_text = _format_reference_range(low, high, unit)
                value_text = f"{value}{(' ' + unit) if unit else ''}"
                alerts.append(
                    Alert(
                        encounter_date=encounter.encounter_date,
                        alert_type=self.alert_type,
                        explanation=(
                            f"Lab '{lab_name}' is abnormal ({direction}): {value_text}. "
                            f"Reference range: {range_text}."
                        ),
                    )
                )

        return alerts


class DuplicateDiagnosisRule(AlertRule):
    alert_type = "duplicate_diagnosis"

    def evaluate(self, encounter: Encounter, context: Optional[Dict[str, Any]] = None) -> List[Alert]:
        normalized_codes = [_normalize_text(code) for code in encounter.diagnosis_codes]
        counts = Counter(normalized_codes)
        duplicates = [code for code, count in counts.items() if code and count > 1]

        if not duplicates:
            return []

        original_by_normalized: Dict[str, str] = {}
        for code in encounter.diagnosis_codes:
            norm = _normalize_text(code)
            if norm not in original_by_normalized:
                original_by_normalized[norm] = code

        duplicate_labels = [original_by_normalized[code] for code in sorted(duplicates)]
        return [
            Alert(
                encounter_date=encounter.encounter_date,
                alert_type=self.alert_type,
                explanation=f"Duplicate diagnosis code(s) recorded in the same encounter: {', '.join(duplicate_labels)}.",
            )
        ]


class AlertEngine:
    def __init__(self, rules: Sequence[AlertRule]) -> None:
        self.rules = list(rules)

    def process_encounter(self, encounter: Encounter) -> List[Alert]:
        alerts: List[Alert] = []
        for rule in self.rules:
            alerts.extend(rule.evaluate(encounter))
        return alerts

    def process_encounters(self, encounters: Iterable[Union[Encounter, Mapping[str, Any], Any]]) -> Dict[Any, List[Dict[str, Any]]]:
        grouped_alerts: Dict[Any, List[Dict[str, Any]]] = defaultdict(list)

        for raw_encounter in encounters:
            encounter = Encounter.from_input(raw_encounter)
            alerts = self.process_encounter(encounter)
            if alerts:
                grouped_alerts[encounter.patient_id].extend(alert.to_dict() for alert in alerts)
            else:
                grouped_alerts.setdefault(encounter.patient_id, [])

        return dict(grouped_alerts)


def process_patient_encounters(
    encounters: Iterable[Union[Encounter, Mapping[str, Any], Any]],
    reference_ranges: Mapping[str, Mapping[str, Any]],
    medication_allergy_map: Optional[Mapping[str, Sequence[str]]] = None,
) -> Dict[Any, List[Dict[str, Any]]]:
    if encounters is None:
        raise ValidationError("encounters must not be None.")
    if not isinstance(reference_ranges, Mapping):
        raise ValidationError("reference_ranges must be a mapping.")

    engine = AlertEngine(
        rules=[
            MedicationAllergyConflictRule(medication_allergy_map=medication_allergy_map),
            AbnormalLabRule(reference_ranges=reference_ranges),
            DuplicateDiagnosisRule(),
        ]
    )
    return engine.process_encounters(encounters)


def _normalize_text(value: Any) -> str:
    return str(value).strip().lower()


def _ensure_list_of_strings(value: Any, field_name: str) -> List[str]:
    if not isinstance(value, list):
        raise ValidationError(f"{field_name} must be a list.")
    normalized: List[str] = []
    for item in value:
        if item is None:
            raise ValidationError(f"{field_name} must not contain None.")
        normalized.append(str(item))
    return normalized


def _ensure_lab_results(value: Any) -> Dict[str, Any]:
    if not isinstance(value, Mapping):
        raise ValidationError("lab_results must be a dictionary or mapping.")
    return dict(value)


def _extract_lab_value(result: Any) -> Optional[float]:
    if isinstance(result, Mapping):
        raw_value = result.get("value")
    else:
        raw_value = result

    try:
        return float(raw_value)
    except (TypeError, ValueError):
        return None


def _extract_lab_unit(result: Any) -> Optional[str]:
    if isinstance(result, Mapping):
        unit = result.get("unit")
        if unit is not None:
            return str(unit)
    return None


def _format_reference_range(low: Any, high: Any, unit: Optional[str]) -> str:
    suffix = f" {unit}" if unit else ""
    if low is not None and high is not None:
        return f"{low} - {high}{suffix}"
    if low is not None:
        return f">= {low}{suffix}"
    if high is not None:
        return f"<= {high}{suffix}"
    return f"not specified{suffix}".strip()


