import threading
import time
from functools import wraps


def ttl_memoize(ttl_seconds: float):
    """Thread-safe memoization decorator with TTL expiration."""
    def decorator(func):
        cache = {}
        lock = threading.RLock()
        stats = {"hits": 0, "misses": 0, "evictions": 0}

        def make_key(args, kwargs):
            # kwargs are normalized to make logically equivalent calls share a key
            return args, tuple(sorted(kwargs.items()))

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = time.monotonic()

            with lock:
                entry = cache.get(key)
                if entry is not None:
                    value, expires_at = entry
                    if now < expires_at:
                        stats["hits"] += 1
                        return value
                    # Expired entry: remove and count as eviction
                    del cache[key]
                    stats["evictions"] += 1

                stats["misses"] += 1

            # Compute outside the lock to avoid blocking unrelated callers
            result = func(*args, **kwargs)
            expires_at = time.monotonic() + ttl_seconds

            with lock:
                cache[key] = (result, expires_at)
            return result

        def cache_info():
            with lock:
                return {
                    "hits": stats["hits"],
                    "misses": stats["misses"],
                    "size": len(cache),
                    "evictions": stats["evictions"],
                }

        def cache_clear():
            with lock:
                cache.clear()
                stats["hits"] = stats["misses"] = stats["evictions"] = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator


@ttl_memoize(ttl_seconds=2.0)
def fib(n: int) -> int:
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)


@ttl_memoize(ttl_seconds=1.0)
def expensive_sum(a: int, b: int, scale: int = 1) -> int:
    time.sleep(0.2)  # Simulate expensive work
    return (a + b) * scale


if __name__ == "__main__":
    print("fib(35):", fib(35))
    print("fib cache info:", fib.cache_info())
    print("fib(35) again:", fib(35))
    print("fib cache info:", fib.cache_info())

    print("expensive_sum first call:", expensive_sum(3, 4, scale=10))
    print("expensive_sum second call (cached):", expensive_sum(3, 4, scale=10))
    print("expensive_sum cache info:", expensive_sum.cache_info())

    time.sleep(1.1)  # Let expensive_sum cache expire
    print("expensive_sum after TTL expiry:", expensive_sum(3, 4, scale=10))
    print("expensive_sum cache info:", expensive_sum.cache_info())

import hashlib


class BloomFilter:
    def __init__(self, size: int, hash_count: int):
        if size <= 0 or hash_count <= 0:
            raise ValueError("size and hash_count must be positive")
        self.size = size
        self.hash_count = hash_count
        self.bits = [0] * size

    def _hashes(self, item: str):
        # Generate multiple stable hash positions using salted SHA-256.
        item_bytes = item.encode("utf-8")
        for i in range(self.hash_count):
            digest = hashlib.sha256(i.to_bytes(2, "little") + item_bytes).digest()
            yield int.from_bytes(digest, "big") % self.size

    def add(self, item: str) -> None:
        for index in self._hashes(item):
            self.bits[index] = 1

    def __contains__(self, item: str) -> bool:
        return all(self.bits[index] for index in self._hashes(item))

    def estimated_false_positive_rate(self, num_items: int) -> float:
        # Standard Bloom filter approximation: (1 - e^(-k*n/m))^k
        from math import exp
        m = self.size
        k = self.hash_count
        n = num_items
        return (1 - exp(-k * n / m)) ** k


def main():
    bf = BloomFilter(size=100, hash_count=3)
    inserted = ["apple", "banana", "orange"]
    for word in inserted:
        bf.add(word)

    tests = ["apple", "grape", "banana", "melon"]
    for word in tests:
        print(f"{word}: {word in bf}")

    print("Estimated false positive rate:", round(bf.estimated_false_positive_rate(len(inserted)), 4))


if __name__ == "__main__":
    main()
