class TypedField:
    """Descriptor that validates assigned values by type and optional emptiness."""

    def __init__(self, expected_type, *, allow_empty=True):
        self.expected_type = expected_type
        self.allow_empty = allow_empty
        self.private_name = None

    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, self.expected_type):
            raise TypeError(f"Expected {self.expected_type.__name__}, got {type(value).__name__}")
        if not self.allow_empty and isinstance(value, str) and value == "":
            raise ValueError("String value cannot be empty")
        setattr(instance, self.private_name, value)


class ConfigEntry:
    key = TypedField(str, allow_empty=False)
    value_type = TypedField(type)

    def __init__(self, key, value_type, value=None):
        self.key = key
        self.value_type = value_type
        self._value = None
        self._is_set = False
        if value is not None:
            self.value = value

    @property
    def value(self):
        if not self._is_set:
            raise AttributeError(f"No value has been set for '{self.key}'")
        return self._value

    @value.setter
    def value(self, new_value):
        if not isinstance(new_value, self.value_type):
            raise TypeError(
                f"Value for '{self.key}' must be of type {self.value_type.__name__}"
            )
        self._value = new_value
        self._is_set = True

    @property
    def is_set(self):
        return self._is_set


