import json
from pathlib import Path


def load_app_config(path):
    """Load, validate, and normalize application configuration from a JSON file."""
    config_path = Path(path)

    if not config_path.is_file():
        raise ValueError(f"Configuration file not found: {path}")

    try:
        with config_path.open("r", encoding="utf-8") as f:
            config = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in configuration file: {e.msg}") from e
    except OSError as e:
        raise ValueError(f"Could not read configuration file: {e}") from e

    if not isinstance(config, dict):
        raise ValueError("Configuration must be a JSON object")

    required_keys = ["host", "port", "debug"]
    missing = [key for key in required_keys if key not in config]
    if missing:
        raise ValueError(f"Missing required configuration keys: {', '.join(missing)}")

    # Apply defaults for optional settings
    normalized = {
        "host": config["host"],
        "port": config["port"],
        "debug": config["debug"],
        "timeout": config.get("timeout", 30),
        "retries": config.get("retries", 3),
    }

    # Validate host
    if not isinstance(normalized["host"], str) or not normalized["host"].strip():
        raise ValueError("'host' must be a non-empty string")

    # Validate port (bool is excluded because bool is a subclass of int)
    port = normalized["port"]
    if not isinstance(port, int) or isinstance(port, bool) or not (1 <= port <= 65535):
        raise ValueError("'port' must be an integer between 1 and 65535")

    # Validate debug
    if not isinstance(normalized["debug"], bool):
        raise ValueError("'debug' must be a boolean")

    # Validate optional numeric fields
    if not isinstance(normalized["timeout"], int) or isinstance(normalized["timeout"], bool) or normalized["timeout"] < 0:
        raise ValueError("'timeout' must be a non-negative integer")

    if not isinstance(normalized["retries"], int) or isinstance(normalized["retries"], bool) or normalized["retries"] < 0:
        raise ValueError("'retries' must be a non-negative integer")

    return normalized


