from abc import ABC, abstractmethod


class PaymentStrategy(ABC):
    """Strategy interface for different payment methods."""

    @abstractmethod
    def pay(self, amount: float) -> str:
        pass


class CreditCardPayment(PaymentStrategy):
    def __init__(self, card_holder: str, last4: str):
        self.card_holder = card_holder
        self.last4 = last4

    def pay(self, amount: float) -> str:
        return f"Charged ${amount:.2f} to credit card ending in {self.last4} for {self.card_holder}."


class PayPalPayment(PaymentStrategy):
    def __init__(self, email: str):
        self.email = email

    def pay(self, amount: float) -> str:
        return f"Processed PayPal payment of ${amount:.2f} using account {self.email}."


class CryptoPayment(PaymentStrategy):
    def __init__(self, wallet_address: str, currency: str):
        self.wallet_address = wallet_address
        self.currency = currency

    def pay(self, amount: float) -> str:
        short_wallet = f"{self.wallet_address[:6]}...{self.wallet_address[-4:]}"
        return f"Transferred ${amount:.2f} worth of {self.currency} from wallet {short_wallet}."


class Checkout:
    """Context that uses a payment strategy and can switch it dynamically."""

    def __init__(self, strategy: PaymentStrategy):
        self._strategy = strategy

    def set_strategy(self, strategy: PaymentStrategy) -> None:
        self._strategy = strategy

    def process(self, amount: float) -> str:
        if amount <= 0:
            raise ValueError("Amount must be positive")
        return self._strategy.pay(amount)


if __name__ == "__main__":
