import math
import hashlib


class BloomFilter:
    def __init__(self, capacity: int, false_positive_rate: float):
        if capacity <= 0:
            raise ValueError('capacity must be > 0')
        if not (0 < false_positive_rate < 1):
            raise ValueError('false_positive_rate must be between 0 and 1')

        self.capacity = capacity
        self.target_fpr = false_positive_rate

        # Optimal Bloom filter parameters:
        # m = -(n * ln(p)) / (ln(2)^2), k = (m / n) * ln(2)
        self.size = max(1, math.ceil(-(capacity * math.log(false_positive_rate)) / (math.log(2) ** 2)))
        self.hash_count = max(1, round((self.size / capacity) * math.log(2)))

        self.bits = bytearray((self.size + 7) // 8)
        self.count = 0

    def _set_bit(self, index: int) -> None:
        self.bits[index // 8] |= 1 << (index % 8)

    def _get_bit(self, index: int) -> bool:
        return bool(self.bits[index // 8] & (1 << (index % 8)))

    def _hashes(self, item: str):
        data = item.encode('utf-8') if isinstance(item, str) else bytes(item)

        # Double hashing: h_i(x) = h1(x) + i * h2(x)
        h1 = int.from_bytes(hashlib.sha256(data).digest(), 'big')
        h2 = int.from_bytes(hashlib.blake2b(data, digest_size=16).digest(), 'big') or 1

        for i in range(self.hash_count):
            yield (h1 + i * h2) % self.size

    def add(self, item: str) -> None:
        for idx in self._hashes(item):
            self._set_bit(idx)
        self.count += 1

    def __contains__(self, item: str) -> bool:
        return all(self._get_bit(idx) for idx in self._hashes(item))

    def estimated_false_positive_rate(self) -> float:
        # Approximate current FPR after inserting self.count items.
        return (1 - math.exp(-self.hash_count * self.count / self.size)) ** self.hash_count

    def __repr__(self) -> str:
        return (
            f'BloomFilter(capacity={self.capacity}, size={self.size}, '
            f'hash_count={self.hash_count}, inserted={self.count})'
        )


if __name__ == '__main__':
    bf = BloomFilter(capacity=1000, false_positive_rate=0.01)

    for word in ['apple', 'banana', 'cherry', 'date']:
        bf.add(word)

    print(bf)
    print('apple' in bf)    # Expected: likely True
    print('banana' in bf)   # Expected: likely True
    print('grape' in bf)    # Expected: usually False
    print('melon' in bf)    # Expected: usually False
    print(f'Estimated FPR: {bf.estimated_false_positive_rate():.6f}')

class PositiveNumber:
    """Descriptor that ensures assigned values are positive numbers."""

    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, (int, float)):
            raise TypeError(f"{self.private_name[1:]} must be a number")
        if value <= 0:
            raise ValueError(f"{self.private_name[1:]} must be positive")
        setattr(instance, self.private_name, float(value))


class Product:
    price = PositiveNumber()
    weight = PositiveNumber()

    def __init__(self, name, price, weight):
        self.name = name
        self.price = price
        self.weight = weight
        self._discount_rate = 0.0  # stored as a fraction, e.g. 0.2 for 20%

    @property
    def shipping_cost(self):
        """Read-only shipping cost based on weight."""
        return self.weight * 1.5

    @property
    def discounted_price(self):
        """Price after applying the current discount rate."""
        return self.price * (1 - self._discount_rate)

    @discounted_price.setter
    def discounted_price(self, percent):
        """Set discount using a percentage between 0 and 100."""
        if not isinstance(percent, (int, float)):
            raise TypeError("discount percent must be a number")
        if not 0 <= percent <= 100:
            raise ValueError("discount percent must be between 0 and 100")
        self._discount_rate = percent / 100


# Demonstration
