import csv
import sys
from collections import Counter, defaultdict, deque
from dataclasses import dataclass
from datetime import datetime, timedelta
from typing import Dict, List, Optional, Set, Tuple


@dataclass
class Transaction:
    transaction_id: str
    account_id: str
    timestamp: datetime
    amount: float
    merchant_category: str
    country: str
    is_chargeback: bool


def parse_bool(value: str) -> Optional[bool]:
    if value is None:
        return None
    normalized = value.strip().lower()
    truthy = {"1", "true", "yes", "y", "t"}
    falsy = {"0", "false", "no", "n", "f"}
    if normalized in truthy:
        return True
    if normalized in falsy:
        return False
    return None


def parse_timestamp(value: str) -> Optional[datetime]:
    if not value:
        return None

    value = value.strip()
    formats = [
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%dT%H:%M:%S.%f",
        "%Y-%m-%d",
    ]

    for fmt in formats:
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            continue

    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None


def parse_row(row: Dict[str, str], row_num: int) -> Optional[Transaction]:
    required_fields = [
        "transaction_id",
        "account_id",
        "timestamp",
        "amount",
        "merchant_category",
        "country",
        "is_chargeback",
    ]

    if any(field not in row for field in required_fields):
        print(f"Skipping row {row_num}: missing required columns", file=sys.stderr)
        return None

    try:
        transaction_id = (row.get("transaction_id") or "").strip()
        account_id = (row.get("account_id") or "").strip()
        merchant_category = (row.get("merchant_category") or "").strip()
        country = (row.get("country") or "").strip().upper()

        if not transaction_id or not account_id or not merchant_category or not country:
            raise ValueError("empty required field")

        timestamp = parse_timestamp(row.get("timestamp", ""))
        if timestamp is None:
            raise ValueError("invalid timestamp")

        amount = float((row.get("amount") or "").strip())
        is_chargeback = parse_bool(row.get("is_chargeback", ""))
        if is_chargeback is None:
            raise ValueError("invalid is_chargeback value")

        return Transaction(
            transaction_id=transaction_id,
            account_id=account_id,
            timestamp=timestamp,
            amount=amount,
            merchant_category=merchant_category,
            country=country,
            is_chargeback=is_chargeback,
        )
    except (ValueError, TypeError) as exc:
        print(f"Skipping row {row_num}: {exc}", file=sys.stderr)
        return None


def load_transactions(csv_path: str) -> List[Transaction]:
    transactions: List[Transaction] = []
    with open(csv_path, "r", newline="", encoding="utf-8") as csvfile:
        reader = csv.DictReader(csvfile)
        for row_num, row in enumerate(reader, start=2):
            transaction = parse_row(row, row_num)
            if transaction is not None:
                transactions.append(transaction)
    return transactions


def detect_fraud(
    transactions: List[Transaction],
    amount_threshold: float,
    high_risk_countries: Set[str],
    max_txn_per_hour: int,
) -> Dict[str, List[str]]:
    flagged: Dict[str, List[str]] = defaultdict(list)

    for txn in transactions:
        if txn.amount > amount_threshold:
            flagged[txn.transaction_id].append(
                f"amount_exceeds_threshold:{txn.amount:.2f}>{amount_threshold:.2f}"
            )
        if txn.country in high_risk_countries:
            flagged[txn.transaction_id].append(f"high_risk_country:{txn.country}")

    transactions_by_account: Dict[str, List[Transaction]] = defaultdict(list)
    for txn in transactions:
        transactions_by_account[txn.account_id].append(txn)

    one_hour = timedelta(hours=1)

    for account_id, account_txns in transactions_by_account.items():
        sorted_txns = sorted(account_txns, key=lambda t: t.timestamp)
        window: deque[Transaction] = deque()

        for txn in sorted_txns:
            while window and (txn.timestamp - window[0].timestamp) > one_hour:
                window.popleft()

            window.append(txn)

            if len(window) > max_txn_per_hour:
                for window_txn in window:
                    reason = (
                        f"high_velocity_account:{account_id}:"
                        f"{len(window)}txns_within_1h"
                    )
                    if reason not in flagged[window_txn.transaction_id]:
                        flagged[window_txn.transaction_id].append(reason)

    return dict(flagged)


def calculate_metrics(
    transactions: List[Transaction], flagged: Dict[str, List[str]]
) -> Tuple[float, float, int, int, int]:
    actual_positive = {txn.transaction_id for txn in transactions if txn.is_chargeback}
    predicted_positive = set(flagged.keys())

    true_positive = len(predicted_positive & actual_positive)
    false_positive = len(predicted_positive - actual_positive)
    false_negative = len(actual_positive - predicted_positive)

    precision = (
        true_positive / (true_positive + false_positive)
        if (true_positive + false_positive) > 0
        else 0.0
    )
    recall = (
        true_positive / (true_positive + false_negative)
        if (true_positive + false_negative) > 0
        else 0.0
    )

    return precision, recall, true_positive, false_positive, false_negative


def top_flagged_accounts(
    transactions: List[Transaction], flagged: Dict[str, List[str]], top_n: int = 5
) -> List[Tuple[str, int]]:
    txn_to_account = {txn.transaction_id: txn.account_id for txn in transactions}
    flagged_accounts = [
        txn_to_account[txn_id] for txn_id in flagged.keys() if txn_id in txn_to_account
    ]
    counts = Counter(flagged_accounts)
    return counts.most_common(top_n)


def print_report(
    transactions: List[Transaction],
    flagged: Dict[str, List[str]],
    precision: float,
    recall: float,
) -> None:
    flagged_records = [
        (txn_id, reasons) for txn_id, reasons in flagged.items() if len(reasons) > 0
    ]
    flagged_records.sort(key=lambda item: item[0])

    print("1. Flagged Transactions")
    if not flagged_records:
        print("No transactions were flagged.")
    else:
        for txn_id, reasons in flagged_records:
            print(f"{txn_id}: {', '.join(reasons)}")

    print("\n2. Top 5 Accounts with Highest Number of Flagged Transactions")
    top_accounts = top_flagged_accounts(transactions, flagged, top_n=5)
    if not top_accounts:
        print("No flagged accounts.")
    else:
        for account_id, count in top_accounts:
            print(f"{account_id}: {count}")

    print("\n3. Rule Performance Metrics")
    print(f"Precision: {precision:.4f}")
    print(f"Recall: {recall:.4f}")


def main() -> None:
    csv_path = sys.argv[1] if len(sys.argv) > 1 else "transactions.csv"

    amount_threshold = 1000.0
    high_risk_countries = {"NG", "RU", "KP", "IR", "SY"}
    max_txn_per_hour = 5

    transactions = load_transactions(csv_path)
    flagged = detect_fraud(
        transactions=transactions,
        amount_threshold=amount_threshold,
        high_risk_countries=high_risk_countries,
        max_txn_per_hour=max_txn_per_hour,
    )
    precision, recall, _, _, _ = calculate_metrics(transactions, flagged)
    print_report(transactions, flagged, precision, recall)


if __name__ == "__main__":
    main()

def handle_webhook(payload, secret):
    """Process a simple webhook payload after validating required fields and signature."""
    required_keys = {'event', 'data', 'signature'}

    # Check that all required fields are present
    if not isinstance(payload, dict) or not required_keys.issubset(payload.keys()):
        return {'status': 'error', 'message': 'Missing required fields'}

    event = payload['event']
    data = payload['data']
    signature = payload['signature']

    # Build the expected signature format
    expected_signature = f"{secret}:{event}"

    # Validate the signature
    if signature != expected_signature:
        return {'status': 'error', 'message': 'Invalid signature'}

    # Simulate successful webhook processing
    return {
        'status': 'success',
        'message': f'Processed {event}',
        'data': data
    }


