    print('\nInvalid payload result:')
    print(handle_webhook(invalid_payload, secret))

from datetime import date


def get_next_birthday(today, birth_date):
    # Try birthday in the current year first
    try:
        next_birthday = date(today.year, birth_date.month, birth_date.day)
    except ValueError:
        # Handle Feb 29 on non-leap years by using Feb 28
        next_birthday = date(today.year, 2, 28)

    if next_birthday < today:
        try:
            next_birthday = date(today.year + 1, birth_date.month, birth_date.day)
        except ValueError:
            next_birthday = date(today.year + 1, 2, 28)

    return next_birthday


def calculate_age(today, birth_date):
    age = today.year - birth_date.year
    if (today.month, today.day) < (birth_date.month, birth_date.day):
        age -= 1
    return age


def main():
    user_input = input('Enter your birth date (YYYY-MM-DD): ')

    try:
        year, month, day = map(int, user_input.split('-'))
        birth_date = date(year, month, day)
    except ValueError:
        print('Invalid date format. Please use YYYY-MM-DD.')
        return

    today = date.today()
    age = calculate_age(today, birth_date)
    next_birthday = get_next_birthday(today, birth_date)
    days_until_birthday = (next_birthday - today).days

    print(f'You are {age} years old.')

    if days_until_birthday == 0:
        print('Happy Birthday! Today is your birthday!')
    else:
        print(f'There are {days_until_birthday} day(s) until your next birthday.')


if __name__ == '__main__':
    main()

from datetime import datetime


def parse_timestamp(value):
    """Convert a timestamp string into a datetime object."""
    return datetime.strptime(value, "%Y-%m-%d %H:%M")


def format_minutes(total_minutes):
    """Format minutes as '<hours>h <minutes>m'."""
    hours, minutes = divmod(total_minutes, 60)
    return f"{hours}h {minutes}m"


def summarize_events(events):
    processed = []
    total_minutes = 0

    for event in events:
        start = parse_timestamp(event["start"])
        end = parse_timestamp(event["end"])

        if end < start:
            raise ValueError(f"End time is before start time for event: {event['name']}")

        duration_minutes = int((end - start).total_seconds() // 60)
        crosses_midnight = start.date() != end.date()
        total_minutes += duration_minutes

        processed.append({
            "name": event["name"],
            "start": start,
            "end": end,
            "duration": duration_minutes,
            "crosses_midnight": crosses_midnight,
        })

    processed.sort(key=lambda item: item["start"])

    for item in processed:
        midnight_note = "Yes" if item["crosses_midnight"] else "No"
        print(
            f"{item['name']}: {item['start'].strftime('%Y-%m-%d %H:%M')} -> "
            f"{item['end'].strftime('%Y-%m-%d %H:%M')} | "
            f"Duration: {item['duration']} minutes | Crosses midnight: {midnight_note}"
        )

    print(f"\nTotal time spent: {format_minutes(total_minutes)}")


