import re
from collections import OrderedDict
from typing import Callable, Dict


class PluginManager:
    def __init__(self) -> None:
        # name -> {"func": callable, "enabled": bool}
        self._plugins: Dict[str, dict] = OrderedDict()

    def register(self, name: str) -> Callable:
        """Decorator to register a plugin under a unique name."""
        def decorator(func: Callable[[str], str]) -> Callable[[str], str]:
            if name in self._plugins:
                raise ValueError(f"Plugin '{name}' is already registered")
            self._plugins[name] = {"func": func, "enabled": True}
            return func
        return decorator

    def enable(self, name: str) -> None:
        if name not in self._plugins:
            raise ValueError(f"Plugin '{name}' not found")
        self._plugins[name]["enabled"] = True

    def disable(self, name: str) -> None:
        if name not in self._plugins:
            raise ValueError(f"Plugin '{name}' not found")
        self._plugins[name]["enabled"] = False

    def run(self, text: str) -> str:
        """Run all enabled plugins in registration order."""
        for plugin in self._plugins.values():
            if plugin["enabled"]:
                text = plugin["func"](text)
        return text

    def list_plugins(self) -> Dict[str, bool]:
        """Return plugin names and their enabled state."""
        return {name: meta["enabled"] for name, meta in self._plugins.items()}


manager = PluginManager()


@manager.register("trim")
def trim_whitespace(text: str) -> str:
    return text.strip()


@manager.register("normalize_spaces")
def normalize_spaces(text: str) -> str:
    return re.sub(r"\s+", " ", text)


@manager.register("uppercase")
def to_uppercase(text: str) -> str:
    return text.upper()


if __name__ == "__main__":
    sample = "   hello    plugin   world   "
    print(manager.run(sample))  # HELLO PLUGIN WORLD

    manager.disable("uppercase")
    print(manager.run(sample))  # hello plugin world

    manager.enable("uppercase")
    print(manager.list_plugins())

import time


class Timer:
    """Context manager for measuring execution time of a code block."""

    def __init__(self, label):
        self.label = label
        self.start_time = None

    def __enter__(self):
        self.start_time = time.perf_counter()
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        elapsed = time.perf_counter() - self.start_time
        print(f"{self.label}: {elapsed:.6f} seconds")
        # Return False so any exception inside the block is not suppressed
        return False


def sum_of_squares(n):
    return sum(i * i for i in range(1, n + 1))


if __name__ == "__main__":
    with Timer("Sum of squares"):
        result = sum_of_squares(100000)

    print("Result:", result)

import threading
import time
from functools import wraps


def ttl_cache(seconds):
    """Thread-safe TTL cache decorator for pure functions."""
    def decorator(func):
        cache = {}
        stats = {"hits": 0, "misses": 0}
        lock = threading.RLock()

        def make_key(args, kwargs):
            # Sort kwargs so call order does not affect the cache key.
            return args, tuple(sorted(kwargs.items()))

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = time.monotonic()

            with lock:
                entry = cache.get(key)
                if entry is not None:
                    value, expires_at = entry
                    if now < expires_at:
                        stats["hits"] += 1
                        return value
                    # Expired entry: remove it and recompute.
                    del cache[key]

                stats["misses"] += 1

            # Compute outside the lock to avoid blocking other threads.
            value = func(*args, **kwargs)

            with lock:
                cache[key] = (value, time.monotonic() + seconds)
            return value

        def cache_info():
            now = time.monotonic()
            with lock:
                # Purge expired entries before reporting size.
                expired = [k for k, (_, exp) in cache.items() if now >= exp]
                for k in expired:
                    del cache[k]
                return {
                    "hits": stats["hits"],
                    "misses": stats["misses"],
                    "size": len(cache),
                }

        wrapper.cache_info = cache_info
        return wrapper

    return decorator


@ttl_cache(seconds=5)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)


if __name__ == "__main__":
    result = fib(30)
    print("fib(30) =", result)
    print("cache_info =", fib.cache_info())

