from __future__ import annotations

import hashlib
import json
import re
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Set, Tuple, Union

try:
    import yaml
except ImportError as exc:
    raise ImportError(
        "PyYAML is required to run this module. Install it with: pip install pyyaml"
    ) from exc


FULL_SHA_RE = re.compile(r"^[0-9a-fA-F]{40}$")
LOCAL_WORKFLOW_RE = re.compile(r"^\.github/workflows/[^@]+$")
THIRD_PARTY_ACTION_RE = re.compile(r"^[^/\s]+/[^@\s]+@.+$")
REUSABLE_WORKFLOW_REMOTE_RE = re.compile(r"^[^/\s]+/[^@\s]+/\.github/workflows/[^@\s]+@.+$")


@dataclass
class StepOffense:
    step_name: Optional[str]
    step_index: int
    action: str
    version: Optional[str]
    reason: str
    severity: int


@dataclass
class JobCompliance:
    job_id: str
    job_name: Optional[str]
    risk_level: str
    offenses: List[StepOffense] = field(default_factory=list)


@dataclass
class WorkflowComplianceReport:
    workflow_name: str
    file_path: str
    valid_yaml: bool
    parse_error: Optional[str] = None
    jobs_scanned: int = 0
    third_party_references_scanned: int = 0
    severity_score: int = 0
    compliant: bool = True
    offending_jobs: List[JobCompliance] = field(default_factory=list)
    nested_reports: List["WorkflowComplianceReport"] = field(default_factory=list)


def _safe_load_yaml(path: Union[str, Path]) -> Tuple[Optional[Dict[str, Any]], Optional[str]]:
    try:
        with Path(path).open("r", encoding="utf-8") as fh:
            data = yaml.safe_load(fh)
        if data is None:
            return {}, None
        if not isinstance(data, dict):
            return None, "Top-level YAML structure must be a mapping/object."
        return data, None
    except FileNotFoundError:
        return None, f"File not found: {path}"
    except PermissionError:
        return None, f"Permission denied: {path}"
    except yaml.YAMLError as exc:
        return None, f"Malformed YAML: {exc}"
    except OSError as exc:
        return None, f"I/O error while reading {path}: {exc}"


def _split_uses(uses_value: str) -> Tuple[str, Optional[str]]:
    if "@" not in uses_value:
        return uses_value.strip(), None
    ref_target, version = uses_value.rsplit("@", 1)
    return ref_target.strip(), version.strip()


def _is_full_commit_sha(version: Optional[str]) -> bool:
    return bool(version and FULL_SHA_RE.fullmatch(version))


def _is_local_action_or_workflow(ref_target: str) -> bool:
    return ref_target.startswith("./")


def _is_remote_reusable_workflow(uses_value: str) -> bool:
    return bool(REUSABLE_WORKFLOW_REMOTE_RE.fullmatch(uses_value.strip()))


def _is_third_party_action(uses_value: str) -> bool:
    uses_value = uses_value.strip()
    if _is_local_action_or_workflow(uses_value):
        return False
    if _is_remote_reusable_workflow(uses_value):
        return True
    return bool(THIRD_PARTY_ACTION_RE.fullmatch(uses_value))


def _risk_level_for_job(job: Dict[str, Any]) -> str:
    permissions = job.get("permissions")
    environment = job.get("environment")
    runs_on = job.get("runs-on")
    if environment or permissions in ("write-all", {"contents": "write"}):
        return "high"
    if isinstance(runs_on, str) and "self-hosted" in runs_on.lower():
        return "high"
    if isinstance(runs_on, list) and any(
        isinstance(item, str) and "self-hosted" in item.lower() for item in runs_on
    ):
        return "high"
    if permissions:
        return "medium"
    return "low"


def _severity_for_offense(job_risk: str, action_ref: str, version: Optional[str], reason: str) -> int:
    base = {"low": 3, "medium": 6, "high": 9}.get(job_risk, 3)
    if version is None:
        base += 2
    elif version.lower() in {"main", "master", "latest", "stable", "dev"}:
        base += 3
    elif re.fullmatch(r"v?\d+(\.\d+){0,2}", version):
        base += 2
    elif len(version) < 40:
        base += 2
    if "/.github/workflows/" in action_ref:
        base += 1
    if "docker://" in action_ref:
        base += 1
    return min(base, 10)


def _workflow_name(data: Dict[str, Any], path: Union[str, Path]) -> str:
    name = data.get("name")
    if isinstance(name, str) and name.strip():
        return name.strip()
    return Path(path).stem


def _normalize_steps(job: Dict[str, Any]) -> List[Dict[str, Any]]:
    steps = job.get("steps", [])
    if isinstance(steps, list):
        return [step for step in steps if isinstance(step, dict)]
    return []


def _resolve_local_reusable_workflow(base_dir: Path, uses_value: str) -> Optional[Path]:
    ref_target, _ = _split_uses(uses_value)
    if not ref_target.startswith("./"):
        return None
    candidate = (base_dir / ref_target).resolve()
    return candidate if candidate.exists() and candidate.is_file() else None


def _make_cycle_key(path: Path) -> str:
    try:
        return str(path.resolve())
    except OSError:
        return str(path)


def parse_and_validate_workflow(
    workflow_file: Union[str, Path],
    *,
    repository_root: Optional[Union[str, Path]] = None,
    _visited: Optional[Set[str]] = None,
) -> WorkflowComplianceReport:
    workflow_path = Path(workflow_file)
    repo_root = Path(repository_root).resolve() if repository_root else workflow_path.resolve().parents[2] if len(workflow_path.resolve().parents) >= 3 else workflow_path.resolve().parent
    visited = _visited if _visited is not None else set()

    cycle_key = _make_cycle_key(workflow_path)
    if cycle_key in visited:
        return WorkflowComplianceReport(
            workflow_name=workflow_path.stem,
            file_path=str(workflow_path),
            valid_yaml=True,
            parse_error="Cycle detected in nested reusable workflow references.",
            compliant=False,
            severity_score=1,
        )

    visited.add(cycle_key)
    data, error = _safe_load_yaml(workflow_path)
    if error or data is None:
        return WorkflowComplianceReport(
            workflow_name=workflow_path.stem,
            file_path=str(workflow_path),
            valid_yaml=False,
            parse_error=error,
            compliant=False,
            severity_score=5,
        )

    report = WorkflowComplianceReport(
        workflow_name=_workflow_name(data, workflow_path),
        file_path=str(workflow_path),
        valid_yaml=True,
    )

    jobs = data.get("jobs", {})
    if not isinstance(jobs, dict):
        report.valid_yaml = False
        report.parse_error = "Missing or invalid 'jobs' mapping."
        report.compliant = False
        report.severity_score = 4
        return report

    for job_id, job in jobs.items():
        if not isinstance(job, dict):
            continue

        report.jobs_scanned += 1
        job_name = job.get("name") if isinstance(job.get("name"), str) else None
        risk_level = _risk_level_for_job(job)
        job_report = JobCompliance(job_id=job_id, job_name=job_name, risk_level=risk_level)

        job_uses = job.get("uses")
        if isinstance(job_uses, str):
            report.third_party_references_scanned += 1
            ref_target, version = _split_uses(job_uses)
            if _is_remote_reusable_workflow(job_uses) and not _is_full_commit_sha(version):
                severity = _severity_for_offense(risk_level, ref_target, version, "Reusable workflow is not pinned to a full commit SHA.")
                job_report.offenses.append(
                    StepOffense(
                        step_name="__job_uses__",
                        step_index=-1,
                        action=ref_target,
                        version=version,
                        reason="Reusable workflow is not pinned to a full commit SHA.",
                        severity=severity,
                    )
                )
                report.severity_score += severity

            local_nested = _resolve_local_reusable_workflow(workflow_path.parent, job_uses)
            if local_nested:
                nested_report = parse_and_validate_workflow(
                    local_nested,
                    repository_root=repo_root,
                    _visited=visited.copy(),
                )
                report.nested_reports.append(nested_report)
                report.severity_score += nested_report.severity_score
                if not nested_report.compliant:
                    report.compliant = False

        for idx, step in enumerate(_normalize_steps(job)):
            uses_value = step.get("uses")
            if not isinstance(uses_value, str):
                continue
            uses_value = uses_value.strip()
            if not uses_value:
                continue

            if _is_local_action_or_workflow(uses_value):
                local_nested = _resolve_local_reusable_workflow(workflow_path.parent, uses_value)
                if local_nested and ".github/workflows" in str(local_nested).replace("\\", "/"):
                    nested_report = parse_and_validate_workflow(
                        local_nested,
                        repository_root=repo_root,
                        _visited=visited.copy(),
                    )
                    report.nested_reports.append(nested_report)
                    report.severity_score += nested_report.severity_score
                    if not nested_report.compliant:
                        report.compliant = False
                continue

            if not _is_third_party_action(uses_value):
                continue

            report.third_party_references_scanned += 1
            ref_target, version = _split_uses(uses_value)
            if not _is_full_commit_sha(version):
                reason = "Action is not pinned to a full commit SHA."
                severity = _severity_for_offense(risk_level, ref_target, version, reason)
                job_report.offenses.append(
                    StepOffense(
                        step_name=step.get("name") if isinstance(step.get("name"), str) else None,
                        step_index=idx,
                        action=ref_target,
                        version=version,
                        reason=reason,
                        severity=severity,
                    )
                )
                report.severity_score += severity

        if job_report.offenses:
            report.offending_jobs.append(job_report)

    report.compliant = report.valid_yaml and not report.offending_jobs and all(
        nested.compliant for nested in report.nested_reports
    )
    return report


def scan_workflow_files(
    workflow_files: Iterable[Union[str, Path]],
    *,
    repository_root: Optional[Union[str, Path]] = None,
) -> Dict[str, Any]:
    reports: List[WorkflowComplianceReport] = []
    total_severity = 0
    total_jobs = 0
    total_refs = 0
    invalid_files = 0

    for wf in workflow_files:
        report = parse_and_validate_workflow(wf, repository_root=repository_root)
        reports.append(report)
        total_severity += report.severity_score
        total_jobs += report.jobs_scanned
        total_refs += report.third_party_references_scanned
        if not report.valid_yaml:
            invalid_files += 1

    return {
        "summary": {
            "files_scanned": len(reports),
            "invalid_files": invalid_files,
            "jobs_scanned": total_jobs,
            "third_party_references_scanned": total_refs,
            "total_severity_score": total_severity,
            "compliant": all(r.compliant for r in reports),
            "scan_id": hashlib.sha256(
                json.dumps([str(Path(r.file_path)) for r in reports], sort_keys=True).encode("utf-8")
            ).hexdigest(),
        },
        "reports": [report_to_dict(r) for r in reports],
    }


def discover_workflow_files(repository_root: Union[str, Path]) -> List[Path]:
    root = Path(repository_root)
    workflow_dir = root / ".github" / "workflows"
    if not workflow_dir.exists() or not workflow_dir.is_dir():
        return []
    return sorted(
        [
            path
            for path in workflow_dir.rglob("*")
            if path.is_file() and path.suffix.lower() in {".yml", ".yaml"}
        ]
    )


def report_to_dict(report: WorkflowComplianceReport) -> Dict[str, Any]:
    data = asdict(report)
    data["nested_reports"] = [report_to_dict_obj(nr) for nr in report.nested_reports]
    return data


def report_to_dict_obj(report: WorkflowComplianceReport) -> Dict[str, Any]:
    return {
        "workflow_name": report.workflow_name,
        "file_path": report.file_path,
        "valid_yaml": report.valid_yaml,
        "parse_error": report.parse_error,
        "jobs_scanned": report.jobs_scanned,
        "third_party_references_scanned": report.third_party_references_scanned,
        "severity_score": report.severity_score,
        "compliant": report.compliant,
        "offending_jobs": [
            {
                "job_id": job.job_id,
                "job_name": job.job_name,
                "risk_level": job.risk_level,
                "offenses": [
                    {
                        "step_name": offense.step_name,
                        "step_index": offense.step_index,
                        "action": offense.action,
                        "version": offense.version,
                        "reason": offense.reason,
                        "severity": offense.severity,
                    }
                    for offense in job.offenses
                ],
            }
            for job in report.offending_jobs
        ],
        "nested_reports": [report_to_dict_obj(nr) for nr in report.nested_reports],
    }


def scan_repository(repository_root: Union[str, Path]) -> Dict[str, Any]:
    workflow_files = discover_workflow_files(repository_root)
    return scan_workflow_files(workflow_files, repository_root=repository_root)


if __name__ == "__main__":
