class PluginManager:
    def __init__(self):
        # Store plugins in a dictionary by name
        self.plugins = {}

    def register(self, name, func):
        """Register a plugin function under a given name."""
        self.plugins[name] = func

    def run(self, name, text):
        """Run a registered plugin on the provided text."""
        if name not in self.plugins:
            raise ValueError(f"Plugin '{name}' not found")
        return self.plugins[name](text)


