class EventBus:
    def __init__(self):
        self._listeners = {}

    def subscribe(self, event_name, listener):
        """Register a listener function for an event."""
        self._listeners.setdefault(event_name, []).append(listener)

    def unsubscribe(self, event_name, listener):
        """Remove a listener function from an event if present."""
        listeners = self._listeners.get(event_name, [])
        if listener in listeners:
            listeners.remove(listener)
        if not listeners and event_name in self._listeners:
            del self._listeners[event_name]

    def emit(self, event_name, **data):
        """Call all listeners registered for an event."""
        for listener in self._listeners.get(event_name, []):
            listener(**data)


