from __future__ import annotations

from dataclasses import dataclass, field, replace
from typing import Dict, Tuple


@dataclass(frozen=True, slots=True)
class Product:
    sku: str
    name: str
    price: float
    tags: Tuple[str, ...] = ()

    def discounted(self, percent: float) -> Product:
        if not 0 <= percent <= 100:
            raise ValueError("discount must be between 0 and 100")
        new_price = round(self.price * (1 - percent / 100), 2)
        return replace(self, price=new_price)


@dataclass(slots=True)
class Inventory:
    products: Dict[str, Product] = field(default_factory=dict)

    def add_product(self, product: Product) -> None:
        if product.sku in self.products:
            raise ValueError(f"duplicate SKU: {product.sku}")
        self.products[product.sku] = product

    def apply_discount_by_tag(self, tag: str, percent: float) -> None:
        if not 0 <= percent <= 100:
            raise ValueError("discount must be between 0 and 100")

        for sku, product in list(self.products.items()):
            if tag in product.tags:
                self.products[sku] = product.discounted(percent)

    def total_value(self) -> float:
        return round(sum(product.price for product in self.products.values()), 2)


if __name__ == "__main__":
    inventory = Inventory()
    inventory.add_product(Product("A100", "Keyboard", 79.99, ("electronics", "office")))
    inventory.add_product(Product("B200", "Mouse", 39.5, ("electronics",)))
    inventory.add_product(Product("C300", "Notebook", 12.0, ("office", "paper")))

    inventory.apply_discount_by_tag("office", 10)
    print(inventory.total_value())
    print(inventory.products)

def build_pipeline(middlewares, handler):
    """Build a middleware pipeline around the final handler."""
    def execute(request):
        def call_next(index, current_request):
            if index == len(middlewares):
                return handler(current_request)
            return middlewares[index](current_request, lambda req: call_next(index + 1, req))

        return call_next(0, request)

    return execute


def logging_middleware(request, next_func):
    print(f"[LOG] Incoming request: {request}")
    return next_func(request)


def add_default_user_middleware(request, next_func):
    # Copy the request so we do not modify the original directly
    request = request.copy()
    if "user" not in request:
        request["user"] = "guest"
    return next_func(request)


def validate_path_middleware(request, next_func):
    path = request.get("path", "")
    if not path.startswith("/"):
        return "Error: Invalid path. Path must start with '/'."
    return next_func(request)


def final_handler(request):
    return f"Handled request for {request['user']} at {request['path']}"


# Create the pipeline
pipeline = build_pipeline(
    [logging_middleware, add_default_user_middleware, validate_path_middleware],
    final_handler
)


# Example 1: valid request
valid_request = {"path": "/home"}
print(pipeline(valid_request))

# Example 2: invalid request
invalid_request = {"path": "home", "user": "Alice"}
print(pipeline(invalid_request))

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List, Tuple


@dataclass(frozen=True)
class Event:
    id: str
    title: str
    start_minute: int
    end_minute: int
    tags: Tuple[str, ...]

    def __post_init__(self) -> None:
        if self.end_minute <= self.start_minute:
            raise ValueError("end_minute must be greater than start_minute")
        if len(set(self.tags)) != len(self.tags):
            raise ValueError("tags must not contain duplicates")

    @property
    def duration(self) -> int:
        return self.end_minute - self.start_minute


@dataclass
class Schedule:
    events: Dict[str, Event] = field(default_factory=dict)

    def add_event(self, event: Event) -> None:
        if event.id in self.events:
            raise ValueError(f"duplicate event id: {event.id}")

        for existing in self.events.values():
            overlaps = event.start_minute < existing.end_minute and existing.start_minute < event.end_minute
            if overlaps:
                raise ValueError(
                    f"event {event.id} overlaps with existing event {existing.id}"
                )

        self.events[event.id] = event

    def events_by_tag(self, tag: str) -> List[Event]:
        matches = [event for event in self.events.values() if tag in event.tags]
        return sorted(matches, key=lambda event: event.start_minute)

    def total_duration(self) -> int:
        return sum(event.duration for event in self.events.values())


if __name__ == "__main__":
    schedule = Schedule()
    schedule.add_event(Event("e1", "Planning", 540, 600, ("work", "team")))
    schedule.add_event(Event("e2", "Lunch", 720, 780, ("personal",)))
    schedule.add_event(Event("e3", "Review", 810, 870, ("work",)))

    print([event.title for event in schedule.events_by_tag("work")])
    print(schedule.total_duration())

