from flask import Flask, request, jsonify

app = Flask(__name__)
WEBHOOK_SECRET = "super-secret-token"
SUPPORTED_EVENTS = {"user.created", "user.deleted"}


def error_response(message, status_code):
    """Build a consistent JSON error response."""
    return jsonify({"ok": False, "error": message}), status_code


@app.post("/webhook")
def handle_webhook():
    # Verify shared secret token from headers
    token = request.headers.get("X-Webhook-Token")
    if token != WEBHOOK_SECRET:
        return error_response("invalid webhook token", 401)

    # Parse JSON safely
    payload = request.get_json(silent=True)
    if payload is None:
        return error_response("malformed or missing JSON body", 400)

    # Validate required fields
    event = payload.get("event")
    data = payload.get("data")
    if not event or not isinstance(data, dict):
        return error_response("payload must include 'event' and object 'data' fields", 400)

    if event not in SUPPORTED_EVENTS:
        return error_response(f"unsupported event: {event}", 422)

    user_id = data.get("id")
    if user_id is None:
        return error_response("data must include 'id'", 400)

    # Handle supported events
    if event == "user.created":
        message = f"processed creation for user {user_id}"
    else:  # user.deleted
        message = f"processed deletion for user {user_id}"

    return jsonify({
        "ok": True,
        "event": event,
        "message": message
    }), 200


if __name__ == "__main__":
    app.run(debug=True)

import random


def genetic_knapsack(items, capacity, population_size=60, generations=100,
                     mutation_rate=0.02, crossover_rate=0.8, tournament_size=3):
    n = len(items)

    def random_chromosome():
        return [random.randint(0, 1) for _ in range(n)]

    def evaluate(chromosome):
        total_value = sum(gene * item[0] for gene, item in zip(chromosome, items))
        total_weight = sum(gene * item[1] for gene, item in zip(chromosome, items))
        fitness = total_value if total_weight <= capacity else 0
        return fitness, total_value, total_weight

    def tournament_select(population):
        contenders = random.sample(population, tournament_size)
        return max(contenders, key=lambda c: evaluate(c)[0])[:]

    def crossover(parent1, parent2):
        if n < 2 or random.random() > crossover_rate:
            return parent1[:], parent2[:]
        point = random.randint(1, n - 1)
        child1 = parent1[:point] + parent2[point:]
        child2 = parent2[:point] + parent1[point:]
        return child1, child2

    def mutate(chromosome):
        for i in range(n):
            if random.random() < mutation_rate:
                chromosome[i] ^= 1
        return chromosome

    population = [random_chromosome() for _ in range(population_size)]

    for _ in range(generations):
        best = max(population, key=lambda c: evaluate(c)[0])[:]
        new_population = [best]  # Elitism

        while len(new_population) < population_size:
            p1 = tournament_select(population)
            p2 = tournament_select(population)
            c1, c2 = crossover(p1, p2)
            new_population.append(mutate(c1))
            if len(new_population) < population_size:
                new_population.append(mutate(c2))

        population = new_population

    best = max(population, key=lambda c: evaluate(c)[0])
    fitness, total_value, total_weight = evaluate(best)
    return {
        'chromosome': best,
        'value': total_value if fitness > 0 else 0,
        'weight': total_weight,
    }


if __name__ == '__main__':
    items = [(60, 10), (100, 20), (120, 30), (80, 15), (30, 5), (50, 8)]
    result = genetic_knapsack(items, capacity=40, population_size=80, generations=150)
    print(result)

class PositiveNumber:
    """Descriptor that enforces a strictly positive numeric value."""

    def __set_name__(self, owner, name):
        self.public_name = name
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, (int, float)):
            raise TypeError(f"{self.public_name} must be a number")
        if value <= 0:
            raise ValueError(f"{self.public_name} must be greater than zero")
        setattr(instance, self.private_name, float(value))


class Product:
    price = PositiveNumber()
    weight = PositiveNumber()

    def __init__(self, name, price, weight, discount_percent=0):
        self.name = name
        self.price = price
        self.weight = weight
        self.discount_percent = discount_percent

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        if not isinstance(value, str):
            raise TypeError("name must be a string")
        value = value.strip()
        if not value:
            raise ValueError("name cannot be empty")
        self._name = value

    @property
    def discount_percent(self):
        return self._discount_percent

    @discount_percent.setter
    def discount_percent(self, value):
        if not isinstance(value, (int, float)):
            raise TypeError("discount_percent must be a number")
        if not 0 <= value <= 100:
            raise ValueError("discount_percent must be between 0 and 100")
        self._discount_percent = float(value)

    @property
    def final_price(self):
        """Read-only computed property for discounted price."""
        return self.price * (1 - self.discount_percent / 100)


if __name__ == "__main__":
    laptop = Product("Laptop", 1200, 2.5, 15)
    phone = Product("Phone", 800, 0.4)

    phone.discount_percent = 10

    print(laptop.name, laptop.price, laptop.weight, laptop.final_price)
    print(phone.name, phone.price, phone.weight, phone.final_price)

    try:
