        phone.discount_percent = 150
    except Exception as exc:
        print(type(exc).__name__, exc)

from html.parser import HTMLParser
import xml.etree.ElementTree as ET


def extract_news_items(xml_data: str, html_data: str) -> list[dict]:
    """Parse XML and HTML, then merge news items by URL."""

    def local_name(tag: str) -> str:
        return tag.split('}', 1)[-1] if '}' in tag else tag

    def child_text(elem, name: str) -> str:
        for child in elem:
            if local_name(child.tag) == name:
                return (child.text or '').strip()
        return ''

    # Parse XML safely and tolerate namespaces by matching local tag names.
    root = ET.fromstring(xml_data)
    xml_items = {}
    for elem in root.iter():
        if local_name(elem.tag) == 'item':
            title = child_text(elem, 'title')
            link = child_text(elem, 'link')
            pub_date = child_text(elem, 'pubDate')
            if link:
                xml_items[link] = {
                    'title': title,
                    'url': link,
                    'published': pub_date,
                }

    class ArticleParser(HTMLParser):
        def __init__(self):
            super().__init__()
            self.articles = {}
            self.current_url = None
            self.in_h2 = False
            self.capture_text = False
            self.text_parts = []

        def handle_starttag(self, tag, attrs):
            attrs = dict(attrs)
            if tag == 'article' and 'data-url' in attrs:
                self.current_url = attrs['data-url']
                self.text_parts = []
            elif self.current_url and tag == 'h2' and not self.articles.get(self.current_url):
                self.in_h2 = True
                self.capture_text = True

        def handle_data(self, data):
            if self.capture_text:
                self.text_parts.append(data)

        def handle_endtag(self, tag):
            if tag == 'h2' and self.in_h2:
                headline = ' '.join(''.join(self.text_parts).split())
                if self.current_url and headline:
                    self.articles[self.current_url] = headline
                self.in_h2 = False
                self.capture_text = False
                self.text_parts = []
            elif tag == 'article':
                self.current_url = None
                self.in_h2 = False
                self.capture_text = False
                self.text_parts = []

    parser = ArticleParser()
    parser.feed(html_data)

    merged = []
    for url, item in xml_items.items():
        if url in parser.articles:
            merged.append({
                **item,
                'html_headline': parser.articles[url],
            })
    return merged

def _shift_char(char, shift):
    """Shift a single alphabetic character while preserving case."""
    if 'a' <= char <= 'z':
        base = ord('a')
    elif 'A' <= char <= 'Z':
        base = ord('A')
    else:
        return char

    normalized_shift = shift % 26
    return chr(base + (ord(char) - base + normalized_shift) % 26)


def encrypt_caesar(text, shift):
    """Encrypt text using a Caesar cipher."""
    return ''.join(_shift_char(char, shift) for char in text)


def decrypt_caesar(text, shift):
    """Decrypt text encrypted with a Caesar cipher."""
    return ''.join(_shift_char(char, -shift) for char in text)


if __name__ == '__main__':
    message = 'Hello, World! Caesar Cipher 123.'
    shift = 5

    encrypted = encrypt_caesar(message, shift)
    decrypted = decrypt_caesar(encrypted, shift)

    print('Original :', message)
    print('Encrypted:', encrypted)
    print('Decrypted:', decrypted)

import time


def call_with_resilience(operation, max_retries=3, failure_threshold=2, reset_timeout=5):
    """Execute an operation with retry logic and a simple circuit breaker."""
    # Initialize persistent state on the function itself.
    if not hasattr(call_with_resilience, "state"):
        call_with_resilience.state = {
            "failures": 0,
            "circuit_open": False,
            "opened_at": None,
        }

    state = call_with_resilience.state
    now = time.time()

    # If circuit is open, only allow a retry after the reset timeout.
    if state["circuit_open"]:
        if now - state["opened_at"] < reset_timeout:
            raise RuntimeError("Circuit breaker is open")
        # Half-open behavior: allow one attempt after timeout.
        state["circuit_open"] = False

    delay = 1
    last_error = None

    for attempt in range(max_retries + 1):
        try:
            result = operation()
            # Success resets the breaker state.
            state["failures"] = 0
            state["circuit_open"] = False
            state["opened_at"] = None
            return result
        except Exception as exc:
            last_error = exc
            if attempt < max_retries:
                time.sleep(delay)
                delay *= 2

    # Count one failed call after all retries are exhausted.
    state["failures"] += 1
    if state["failures"] >= failure_threshold:
        state["circuit_open"] = True
        state["opened_at"] = time.time()

    raise last_error


if __name__ == '__main__':
    attempts = {"count": 0}

    def flaky_operation():
        attempts["count"] += 1
        print(f"Operation attempt {attempts['count']}")
        # Fail the first 4 attempts, then succeed.
        if attempts["count"] <= 4:
            raise ValueError("Temporary API failure")
        return "Success"

    for i in range(4):
        try:
            result = call_with_resilience(
                flaky_operation,
                max_retries=1,
                failure_threshold=2,
                reset_timeout=3,
            )
            print("Result:", result)
        except Exception as e:
            print("Call failed:", e)
        time.sleep(0.5)

    print("Waiting for circuit breaker reset...")
    time.sleep(3.5)

    try:
        result = call_with_resilience(
            flaky_operation,
            max_retries=1,
            failure_threshold=2,
            reset_timeout=3,
        )
        print("Final result:", result)
    except Exception as e:
        print("Final call failed:", e)

from typing import Any, Dict, List


def validate(schema: Dict[str, dict], data: Dict[str, Any], allow_extra: bool = False, path: str = "") -> List[str]:
    errors: List[str] = []

    if not isinstance(data, dict):
        return [f"{path or 'root'}: expected dict, got {type(data).__name__}"]

    # Reject unexpected fields unless explicitly allowed.
    if not allow_extra:
        for key in data:
            if key not in schema:
                field_path = f"{path}.{key}" if path else key
                errors.append(f"{field_path}: unexpected field")

    for field, rules in schema.items():
        field_path = f"{path}.{field}" if path else field
        required = rules.get("required", True)
        nullable = rules.get("nullable", False)

        if field not in data:
            if required:
                errors.append(f"{field_path}: missing required field")
            continue

        value = data[field]
        if value is None:
            if not nullable:
                errors.append(f"{field_path}: null is not allowed")
            continue

        expected_type = rules["type"]
        # Prevent bool from passing as int.
        if expected_type is int:
            type_ok = isinstance(value, int) and not isinstance(value, bool)
        elif expected_type is float:
            type_ok = isinstance(value, (int, float)) and not isinstance(value, bool)
        else:
            type_ok = isinstance(value, expected_type)

        if not type_ok:
            errors.append(
                f"{field_path}: expected {expected_type.__name__}, got {type(value).__name__}"
            )
            continue

        if "allowed" in rules and value not in rules["allowed"]:
            errors.append(f"{field_path}: value {value!r} not in allowed set {rules['allowed']}")

        if expected_type in (str, list):
            if "min" in rules and len(value) < rules["min"]:
                errors.append(f"{field_path}: length must be >= {rules['min']}")
            if "max" in rules and len(value) > rules["max"]:
                errors.append(f"{field_path}: length must be <= {rules['max']}")
        elif expected_type in (int, float):
            if "min" in rules and value < rules["min"]:
                errors.append(f"{field_path}: must be >= {rules['min']}")
            if "max" in rules and value > rules["max"]:
                errors.append(f"{field_path}: must be <= {rules['max']}")

        if expected_type is dict and "schema" in rules:
            errors.extend(validate(rules["schema"], value, allow_extra=allow_extra, path=field_path))

        if expected_type is list and "items" in rules:
            item_rules = rules["items"]
            item_type = item_rules["type"]
            for i, item in enumerate(value):
                item_path = f"{field_path}[{i}]"

                if item is None:
                    if not item_rules.get("nullable", False):
                        errors.append(f"{item_path}: null is not allowed")
                    continue

                if item_type is int:
                    item_ok = isinstance(item, int) and not isinstance(item, bool)
                elif item_type is float:
                    item_ok = isinstance(item, (int, float)) and not isinstance(item, bool)
                else:
                    item_ok = isinstance(item, item_type)

                if not item_ok:
                    errors.append(
                        f"{item_path}: expected {item_type.__name__}, got {type(item).__name__}"
                    )
                    continue

                if "allowed" in item_rules and item not in item_rules["allowed"]:
                    errors.append(
                        f"{item_path}: value {item!r} not in allowed set {item_rules['allowed']}"
                    )

                if item_type in (str, list):
                    if "min" in item_rules and len(item) < item_rules["min"]:
                        errors.append(f"{item_path}: length must be >= {item_rules['min']}")
                    if "max" in item_rules and len(item) > item_rules["max"]:
                        errors.append(f"{item_path}: length must be <= {item_rules['max']}")
                elif item_type in (int, float):
                    if "min" in item_rules and item < item_rules["min"]:
                        errors.append(f"{item_path}: must be >= {item_rules['min']}")
                    if "max" in item_rules and item > item_rules["max"]:
                        errors.append(f"{item_path}: must be <= {item_rules['max']}")

                if item_type is dict and "schema" in item_rules:
                    errors.extend(validate(item_rules["schema"], item, allow_extra=allow_extra, path=item_path))

    return errors


