import os


def parse_bool(value: str) -> bool:
    """Convert a string environment value to a boolean."""
    value = value.strip().lower()
    truthy = {"true", "1", "yes", "on"}
    falsy = {"false", "0", "no", "off"}

    if value in truthy:
        return True
    if value in falsy:
        return False
    raise ValueError(f"Invalid boolean value: {value!r}")


def load_config() -> dict:
    """Load and validate application config from environment variables."""
    required_vars = ["APP_HOST", "APP_PORT", "APP_DEBUG"]
    missing = [name for name in required_vars if os.getenv(name) is None]

    if missing:
        raise ValueError(f"Missing required environment variables: {', '.join(missing)}")

    host = os.environ["APP_HOST"]

    try:
        port = int(os.environ["APP_PORT"])
    except ValueError:
        raise ValueError("APP_PORT must be a valid integer")

    if not (1 <= port <= 65535):
        raise ValueError("APP_PORT must be between 1 and 65535")

    debug = parse_bool(os.environ["APP_DEBUG"])

    return {
        "host": host,
        "port": port,
        "debug": debug,
    }


if __name__ == "__main__":
    config = load_config()
    print(config)

from copy import deepcopy


class TransactionalDict:
    """A context manager that provides nested transactional updates to a dict."""

    def __init__(self, data):
        self._root = data
        self._stack = []

    def __enter__(self):
        # Start a new transaction level from the current visible state.
        base = self._stack[-1] if self._stack else self._root
        self._stack.append(deepcopy(base))
        return self

    def __exit__(self, exc_type, exc, tb):
        current = self._stack.pop()

        if exc_type is not None:
            # Roll back only this transaction level.
            return False

        if self._stack:
            # Commit into the parent transaction.
            self._stack[-1] = current
        else:
            # Commit into the real underlying dictionary.
            self._root.clear()
            self._root.update(current)
        return False

    def _current(self):
        if not self._stack:
            raise RuntimeError('Transactional operations require an active context')
        return self._stack[-1]

    # Dictionary-like helpers for the active transaction state.
    def __getitem__(self, key):
        return self._current()[key]

    def __setitem__(self, key, value):
        self._current()[key] = value

    def __delitem__(self, key):
        del self._current()[key]

    def get(self, key, default=None):
        return self._current().get(key, default)

    def update(self, other=None, **kwargs):
        self._current().update(other or {}, **kwargs)

    def snapshot(self):
        return deepcopy(self._current())


def main():
    data = {'balance': 100, 'status': 'active'}
    tx = TransactionalDict(data)

    with tx:
        tx['balance'] += 50
        tx['note'] = 'monthly bonus'

        try:
            with tx:
                tx['balance'] -= 1000
                tx['status'] = 'overdrawn'
                raise ValueError('simulated failure in nested transaction')
        except ValueError:
            pass

        with tx:
            tx['status'] = 'vip'

    print(data)


if __name__ == '__main__':
    main()

class NewsPublisher:
    def __init__(self):
        # Store subscriber callback functions
        self._subscribers = []

    def subscribe(self, callback):
        # Add subscriber only if not already subscribed
        if callback not in self._subscribers:
            self._subscribers.append(callback)

    def unsubscribe(self, callback):
        # Remove subscriber if present
        if callback in self._subscribers:
            self._subscribers.remove(callback)

    def publish(self, article_title):
        # Notify all subscribers about the new article
        for subscriber in self._subscribers:
            subscriber(article_title)


