class BulkFetchError(Exception):
    """Raised when no user profiles could be fetched successfully."""

    def __init__(self, errors):
        super().__init__("All user profile fetches failed")
        self.errors = errors


def fetch_user_profiles(fetchers, user_ids):
    """
    Try multiple profile fetchers for each user ID.

    Returns:
        (profiles, errors)
        - profiles: {user_id: profile_dict}
        - errors: {user_id: {"fatal": bool, "messages": [str, ...]}}
    """
    profiles = {}
    errors = {}

    for user_id in user_ids:
        messages = []
        fatal = False

        for fetcher in fetchers:
            try:
                profile = fetcher(user_id)
                profiles[user_id] = profile
                break
            except (TimeoutError, ConnectionError) as exc:
                # Retryable error: record and try the next fetcher.
                messages.append(f"{fetcher.__name__}: retryable: {exc}")
            except ValueError as exc:
                # Fatal validation error: stop trying for this user.
                messages.append(f"{fetcher.__name__}: fatal: {exc}")
                fatal = True
                break
            except Exception as exc:
                # Unexpected errors are recorded and treated as non-fatal.
                messages.append(f"{fetcher.__name__}: unexpected {type(exc).__name__}: {exc}")
        else:
            # No fetcher succeeded; keep fatal as-is.
            pass

        if user_id not in profiles:
            errors[user_id] = {
                "fatal": fatal,
                "messages": messages or ["No fetchers available"]
            }

    if not profiles and user_ids:
        raise BulkFetchError(errors)

    return profiles, errors


# Example fetchers for local testing.
