import requests


class ApiError(Exception):
    """Raised when the API returns a non-successful response."""

    def __init__(self, status_code: int, message: str):
        super().__init__(f"API error {status_code}: {message}")
        self.status_code = status_code
        self.message = message


class RestClient:
    RETRY_STATUS_CODES = {429, 500, 502, 503, 504}

    def __init__(self, base_url: str, token: str, timeout: float = 5.0, max_retries: int = 3):
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.max_retries = max_retries
        self.session = requests.Session()
        self.session.headers.update({
            "Authorization": f"Bearer {token}",
            "Accept": "application/json",
            "Content-Type": "application/json",
        })

    def get(self, path: str, params: Optional[Dict[str, Any]] = None) -> Any:
        return self._request("GET", path, params=params)

    def post(self, path: str, json: Optional[Dict[str, Any]] = None) -> Any:
        return self._request("POST", path, json=json)

    def _request(self, method: str, path: str, **kwargs: Any) -> Any:
        url = f"{self.base_url}/{path.lstrip('/')}"
        last_error = None

        for attempt in range(self.max_retries + 1):
            try:
                response = self.session.request(method, url, timeout=self.timeout, **kwargs)

                if 200 <= response.status_code < 300:
                    if not response.content:
                        return None
                    return response.json()

                if response.status_code in self.RETRY_STATUS_CODES and attempt < self.max_retries:
                    delay = 2 ** attempt
                    retry_after = response.headers.get("Retry-After")
                    if retry_after and retry_after.isdigit():
                        delay = int(retry_after)
                    time.sleep(delay)
                    continue

                message = self._extract_error_message(response)
                raise ApiError(response.status_code, message)

            except (requests.Timeout, requests.ConnectionError) as exc:
                last_error = exc
                if attempt < self.max_retries:
                    time.sleep(2 ** attempt)
                    continue
                raise ApiError(0, str(exc)) from exc
            except requests.RequestException as exc:
                raise ApiError(0, str(exc)) from exc

        raise ApiError(0, str(last_error) if last_error else "Unknown request failure")

    @staticmethod
    def _extract_error_message(response: requests.Response) -> str:
        try:
            data = response.json()
            if isinstance(data, dict):
                return str(data.get("error") or data.get("message") or data)
            return str(data)
        except ValueError:
            return response.text.strip() or "No error details provided"


