from dataclasses import dataclass, fields, replace
from typing import Any


@dataclass(frozen=True)
class AppConfig:
    host: str
    port: int
    debug: bool = False
    tags: tuple[str, ...] = ()

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "AppConfig":
        allowed = {f.name for f in fields(cls)}
        required = {"host", "port"}

        unknown = set(data) - allowed
        if unknown:
            raise ValueError(f"Unknown field(s): {', '.join(sorted(unknown))}")

        missing = required - set(data)
        if missing:
            raise ValueError(f"Missing required field(s): {', '.join(sorted(missing))}")

        host = data["host"]
        if not isinstance(host, str) or not host.strip():
            raise ValueError("host must be a non-empty string")

        port = data["port"]
        if not isinstance(port, int) or isinstance(port, bool):
            raise ValueError("port must be an integer")
        if not (1 <= port <= 65535):
            raise ValueError("port must be between 1 and 65535")

        debug = data.get("debug", False)
        if not isinstance(debug, bool):
            raise ValueError("debug must be a boolean")

        raw_tags = data.get("tags", ())
        if isinstance(raw_tags, list):
            tags = tuple(raw_tags)
        elif isinstance(raw_tags, tuple):
            tags = raw_tags
        else:
            raise ValueError("tags must be a list or tuple of strings")
        if not all(isinstance(tag, str) for tag in tags):
            raise ValueError("tags must contain only strings")

        return cls(host=host, port=port, debug=debug, tags=tags)

    def merge(self, overrides: dict[str, Any]) -> "AppConfig":
        allowed = {f.name for f in fields(self)}
        unknown = set(overrides) - allowed
        if unknown:
            raise ValueError(f"Unknown field(s): {', '.join(sorted(unknown))}")

        merged_data: dict[str, Any] = {
            "host": self.host,
            "port": self.port,
            "debug": self.debug,
            "tags": self.tags,
        }
        merged_data.update(overrides)
        validated = self.from_dict(merged_data)
        return replace(self, **validated.__dict__)

from heapq import heappush, heappop
from itertools import count


class PeekableLogIterator:
    """Wrap an iterable and support peeking the next item without consuming it."""

    def __init__(self, iterable):
        self._iterator = iter(iterable)
        self._has_peeked = False
        self._peeked_value = None

    def peek(self):
        if not self._has_peeked:
            self._peeked_value = next(self._iterator)  # May raise StopIteration
            self._has_peeked = True
        return self._peeked_value

    def __iter__(self):
        return self

    def __next__(self):
        if self._has_peeked:
            self._has_peeked = False
            value = self._peeked_value
            self._peeked_value = None
            return value
        return next(self._iterator)


def merge_sorted_logs(*sources):
    """
    Lazily merge multiple sorted log iterables.

    Each log entry must be a tuple: (timestamp, source_name, message)
    Entries are yielded in ascending timestamp order.
    For equal timestamps, source order is preserved from left to right.
    """
    heap = []
    sequence = count()  # Ensures stable ordering within the same source over time

    # Initialize heap with the first item from each source
    for source_index, source in enumerate(sources):
        it = PeekableLogIterator(source)
        try:
            entry = next(it)
            timestamp = entry[0]
            heappush(heap, (timestamp, source_index, next(sequence), entry, it))
        except StopIteration:
            continue

    # Repeatedly yield the smallest item and refill from the same iterator
    while heap:
        _, source_index, _, entry, it = heappop(heap)
        yield entry
        try:
            next_entry = next(it)
            heappush(heap, (next_entry[0], source_index, next(sequence), next_entry, it))
        except StopIteration:
            pass


def generate_logs(source_name, entries):
    """Example generator producing log tuples."""
    for timestamp, message in entries:
        yield (timestamp, source_name, message)


if __name__ == "__main__":
    app_logs = generate_logs("app", [
        (1, "App started"),
        (4, "User login"),
        (7, "Request processed"),
    ])

    db_logs = generate_logs("db", [
        (2, "Connection opened"),
        (4, "Query executed"),
        (8, "Connection closed"),
    ])

    cache_logs = [
        (3, "cache", "Cache warmup"),
        (4, "cache", "Cache hit"),
        (6, "cache", "Cache eviction"),
    ]

    for log in merge_sorted_logs(app_logs, db_logs, cache_logs):
        print(log)
}

