from datetime import datetime, timedelta, timezone
from typing import Literal, Optional
from uuid import UUID

from pydantic import BaseModel, ConfigDict, Field, ValidationError, field_validator, model_validator


class Metadata(BaseModel):
    model_config = ConfigDict(extra='forbid')

    user_id: int = Field(gt=0)
    amount: Optional[float] = Field(default=None, gt=0)
    currency: Optional[str] = None

    @field_validator('currency')
    @classmethod
    def normalize_currency(cls, value: Optional[str]) -> Optional[str]:
        return value.upper() if value is not None else value


class EventPayload(BaseModel):
    model_config = ConfigDict(extra='forbid')

    event_id: UUID
    source: Literal['api', 'mobile', 'web']
    event_type: Literal['click', 'view', 'purchase']
    timestamp: datetime
    metadata: Metadata

    @field_validator('timestamp')
    @classmethod
    def validate_timestamp(cls, value: datetime) -> datetime:
        if value.tzinfo is None or value.utcoffset() is None:
            raise ValueError('timestamp must include timezone information')
        now = datetime.now(timezone.utc)
        if value.astimezone(timezone.utc) > now + timedelta(minutes=5):
            raise ValueError('timestamp must not be more than 5 minutes in the future')
        return value

    @model_validator(mode='after')
    def validate_purchase_fields(self) -> 'EventPayload':
        has_amount = self.metadata.amount is not None
        has_currency = self.metadata.currency is not None

        if self.event_type == 'purchase':
            if not (has_amount and has_currency):
                raise ValueError('purchase events require both metadata.amount and metadata.currency')
        elif has_amount or has_currency:
            raise ValueError('metadata.amount and metadata.currency are only allowed for purchase events')

        return self


def validate_event(payload: dict) -> dict:
    """Validate and normalize an event payload."""
    event = EventPayload.model_validate(payload)
    return event.model_dump(mode='json')


