import re


def render_template(template, context):
    """
    Render placeholders in the form {{key}} or {{key|default value}}.

    Rules:
    - If key exists in context, replace with str(context[key]).
    - If key is missing and a default is provided, use the default.
    - If key is missing and no default is provided, leave placeholder unchanged.
    - Escaped placeholders like \{{key}} are left literal as {{key}}.
    """
    pattern = re.compile(r'(\\)?\{\{\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*(?:\|\s*([^}]*?)\s*)?\}\}')

    def replace(match):
        escape, key, default = match.groups()

        # Keep escaped placeholders literal, dropping the escape backslash.
        if escape:
            return match.group(0)[1:]

        if key in context:
            return str(context[key])

        if default is not None:
            return default

        return match.group(0)

    return pattern.sub(replace, template)


