from __future__ import annotations

from abc import ABC, abstractmethod


class Command(ABC):
    @abstractmethod
    def execute(self, editor: "TextEditor") -> None:
        pass

    @abstractmethod
    def undo(self, editor: "TextEditor") -> None:
        pass


class TextEditor:
    def __init__(self, text: str = ""):
        self.text = text


class InsertCommand(Command):
    def __init__(self, position: int, value: str):
        self.position = position
        self.value = value

    def execute(self, editor: TextEditor) -> None:
        editor.text = editor.text[:self.position] + self.value + editor.text[self.position:]

    def undo(self, editor: TextEditor) -> None:
        end = self.position + len(self.value)
        editor.text = editor.text[:self.position] + editor.text[end:]


class DeleteCommand(Command):
    def __init__(self, position: int, length: int):
        self.position = position
        self.length = length
        self.deleted = ""

    def execute(self, editor: TextEditor) -> None:
        self.deleted = editor.text[self.position:self.position + self.length]
        editor.text = editor.text[:self.position] + editor.text[self.position + self.length:]

    def undo(self, editor: TextEditor) -> None:
        editor.text = editor.text[:self.position] + self.deleted + editor.text[self.position:]


class ReplaceCommand(Command):
    def __init__(self, position: int, length: int, value: str):
        self.position = position
        self.length = length
        self.value = value
        self.original = ""

    def execute(self, editor: TextEditor) -> None:
        self.original = editor.text[self.position:self.position + self.length]
        editor.text = (
            editor.text[:self.position] + self.value + editor.text[self.position + self.length:]
        )

    def undo(self, editor: TextEditor) -> None:
        end = self.position + len(self.value)
        editor.text = editor.text[:self.position] + self.original + editor.text[end:]


class CommandManager:
    def __init__(self, editor: TextEditor):
        self.editor = editor
        self.undo_stack: list[Command] = []
        self.redo_stack: list[Command] = []

    def execute(self, command: Command) -> None:
        command.execute(self.editor)
        self.undo_stack.append(command)
        self.redo_stack.clear()

    def undo(self) -> None:
        if not self.undo_stack:
            return
        command = self.undo_stack.pop()
        command.undo(self.editor)
        self.redo_stack.append(command)

    def redo(self) -> None:
        if not self.redo_stack:
            return
        command = self.redo_stack.pop()
        command.execute(self.editor)
        self.undo_stack.append(command)


if __name__ == "__main__":
    editor = TextEditor("Hello World")
    manager = CommandManager(editor)

    actions = [
        InsertCommand(5, ","),
        ReplaceCommand(6, 5, " Earth"),
        DeleteCommand(0, 6),
    ]

    print("Start:", editor.text)
    for action in actions:
        manager.execute(action)
        print("After execute:", editor.text)

    manager.undo()
    print("After undo 1:", editor.text)
    manager.undo()
    print("After undo 2:", editor.text)
    manager.redo()
    print("After redo 1:", editor.text)

import math
import re
from collections import Counter, defaultdict


STOPWORDS = {
    'a', 'an', 'and', 'are', 'as', 'at', 'be', 'but', 'by', 'for', 'from',
    'has', 'have', 'he', 'in', 'is', 'it', 'its', 'of', 'on', 'that', 'the',
    'to', 'was', 'were', 'will', 'with', 'this', 'these', 'those', 'or', 'if',
    'not', 'their', 'there', 'then', 'than', 'you', 'your', 'we', 'our', 'they'
}


def tokenize(text):
    """Lowercase text, keep alphabetic tokens only, and remove stopwords."""
    tokens = re.findall(r"[a-zA-Z]+", text.lower())
    return [tok for tok in tokens if tok not in STOPWORDS]


def extract_keywords(texts, top_k=10):
    """Extract corpus-level keywords using summed TF-IDF scores."""
    if not texts:
        return []

    tokenized_docs = [tokenize(text) for text in texts]
    doc_count = len(tokenized_docs)

    # Compute document frequency for each token.
    df = Counter()
    for doc in tokenized_docs:
        df.update(set(doc))

    # Compute smoothed IDF.
    idf = {
        token: math.log((1 + doc_count) / (1 + freq)) + 1
        for token, freq in df.items()
    }

    # Sum TF-IDF scores across documents.
    scores = defaultdict(float)
    for doc in tokenized_docs:
        tf = Counter(doc)
        doc_len = len(doc)
        if doc_len == 0:
            continue
        for token, count in tf.items():
            term_freq = count / doc_len
            scores[token] += term_freq * idf[token]

    return sorted(scores.items(), key=lambda x: (-x[1], x[0]))[:top_k]


if __name__ == '__main__':
    documents = [
        'Natural language processing enables computers to analyze text and extract meaning from documents.',
        'Keyword extraction and text analysis are common NLP tasks in document processing pipelines.',
        'TF IDF is a simple but powerful baseline for ranking important terms in a text corpus.'
    ]

    keywords = extract_keywords(documents, top_k=10)
    for token, score in keywords:
        print(f'{token}: {score:.4f}')

import os


def get_config():
    """Read configuration from environment variables with defaults."""
    app_mode = os.getenv("APP_MODE", "development")
    app_port = os.getenv("APP_PORT", "8000")
    return app_mode, app_port


def validate_config(app_mode, app_port):
    """Validate mode and port values."""
    valid_modes = {"development", "testing", "production"}

    if app_mode not in valid_modes:
        return False, f"Error: APP_MODE must be one of {', '.join(sorted(valid_modes))}."

    if not app_port.isdigit():
        return False, "Error: APP_PORT must be a valid number."

    port_number = int(app_port)
    if not (1 <= port_number <= 65535):
        return False, "Error: APP_PORT must be between 1 and 65535."

    return True, port_number


def main():
    app_mode, app_port = get_config()
    is_valid, result = validate_config(app_mode, app_port)

    if not is_valid:
        print(result)
        return

    # result contains the validated port number
    print("Configuration loaded successfully:")
    print(f"- APP_MODE: {app_mode}")
    print(f"- APP_PORT: {result}")


if __name__ == "__main__":
    main()

import random


def create_individual(length):
    return [random.randint(0, 1) for _ in range(length)]


def fitness(individual):
    # Target is all 1s, so fitness is the number of 1s
    return sum(individual)


def crossover(parent1, parent2):
    point = random.randint(1, len(parent1) - 1)
    child1 = parent1[:point] + parent2[point:]
    child2 = parent2[:point] + parent1[point:]
    return child1, child2


def mutate(individual, mutation_rate):
    for i in range(len(individual)):
        if random.random() < mutation_rate:
            individual[i] = 1 - individual[i]
    return individual


def genetic_algorithm(length=10, population_size=6, generations=20, mutation_rate=0.1):
    population = [create_individual(length) for _ in range(population_size)]

    for generation in range(generations):
        population.sort(key=fitness, reverse=True)
        best = population[0]
        best_score = fitness(best)

        print(f"Generation {generation}: best = {''.join(map(str, best))}, fitness = {best_score}")

        if best_score == length:
            print("Perfect solution found early!")
            return best

        # Select the top 2 individuals as parents
        parent1, parent2 = population[0], population[1]

        new_population = [parent1[:], parent2[:]]  # Keep the best two

        while len(new_population) < population_size:
            child1, child2 = crossover(parent1, parent2)
            new_population.append(mutate(child1, mutation_rate))
            if len(new_population) < population_size:
                new_population.append(mutate(child2, mutation_rate))

        population = new_population

    population.sort(key=fitness, reverse=True)
    return population[0]


best_solution = genetic_algorithm()
print("Final best solution:", ''.join(map(str, best_solution)))
print("Final fitness:", fitness(best_solution))

class Logger:
    """Singleton logger that stores messages in memory."""
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance.messages = []
        return cls._instance

    def log(self, message):
        self.messages.append(message)


class PluginRegistry:
    """Registry for plugin classes."""
    def __init__(self):
        self._plugins = {}
        self._logger = Logger()

    def register(self, name, plugin_cls):
        if name in self._plugins:
            raise ValueError(f"Plugin '{name}' is already registered")
        self._plugins[name] = plugin_cls
        self._logger.log(f"Registered plugin: {name}")

    def get(self, name):
        if name not in self._plugins:
            raise KeyError(f"Plugin '{name}' not found")
        return self._plugins[name]

    def list_plugins(self):
        return sorted(self._plugins.keys())


class CsvPlugin:
    def run(self):
        return "Processing CSV data"


class JsonPlugin:
    def run(self):
        return "Processing JSON data"


if __name__ == "__main__":
    registry = PluginRegistry()
    logger = Logger()

    registry.register("csv", CsvPlugin)
    registry.register("json", JsonPlugin)

    print("Registered plugins:", registry.list_plugins())
    print("Log messages:")
    for entry in logger.messages:
        print("-", entry)

    plugin_class = registry.get("json")
    plugin = plugin_class()
    print("Example plugin output:", plugin.run())

import math
import time
import threading
import multiprocessing as mp


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    limit = int(math.isqrt(n))
    for i in range(3, limit + 1, 2):
        if n % i == 0:
            return False
    return True


def count_primes_in_range(start: int, end: int) -> int:
    return sum(1 for n in range(start, end + 1) if is_prime(n))


def worker(task, results, progress):
    start, end = task
    count = count_primes_in_range(start, end)
    results.put((task, count))
    with progress.get_lock():
        progress.value += 1


def progress_reporter(progress, total, stop_event):
    while not stop_event.is_set():
        with progress.get_lock():
            done = progress.value
        print(f'Progress: {done}/{total} ranges completed')
        if done >= total:
            return
        time.sleep(0.2)


def main():
    ranges = [(10_000, 12_000), (12_001, 14_000), (14_001, 16_000), (16_001, 18_000)]

    results = mp.Queue()
    progress = mp.Value('i', 0)
    stop_event = threading.Event()

    reporter = threading.Thread(
        target=progress_reporter,
        args=(progress, len(ranges), stop_event),
        daemon=True,
    )
    reporter.start()

    processes = [
        mp.Process(target=worker, args=(task, results, progress))
        for task in ranges
    ]

    for p in processes:
        p.start()

    output = {}
    for _ in ranges:
        task, count = results.get()
        output[task] = count

    for p in processes:
        p.join()

    stop_event.set()
    reporter.join()

    print('Final result:', output)
    return output


if __name__ == '__main__':
    main()

from collections import deque


def parse_errors(lines):
    """Yield parsed dictionaries for log lines with level ERROR."""
    for line in lines:
        parts = [part.strip() for part in line.split("|")]
        if len(parts) != 3:
            continue  # Skip malformed lines

        timestamp, level, message = parts
        if level == "ERROR":
            yield {
                "timestamp": timestamp,
                "level": level,
                "message": message,
            }


class RecentErrors:
    """Iterator that returns the last N error entries from a log stream."""

    def __init__(self, lines, limit):
        self._buffer = deque(maxlen=limit)
        for entry in parse_errors(lines):
            self._buffer.append(entry)
        self._iter = iter(self._buffer)

    def __iter__(self):
        return self

    def __next__(self):
        return next(self._iter)


