class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False


class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        """Insert a word into the trie."""
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end = True

    def search(self, word):
        """Return True if the exact word exists in the trie."""
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end

    def starts_with(self, prefix):
        """Return True if any word in the trie starts with the prefix."""
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True


if __name__ == "__main__":
    trie = Trie()

    words = ["cat", "car", "cart", "dog"]
    for word in words:
        trie.insert(word)

    print(trie.search("cat"))      # True
    print(trie.search("can"))      # False
    print(trie.search("car"))      # True
    print(trie.starts_with("ca"))  # True
    print(trie.starts_with("do"))  # True
    print(trie.starts_with("bat")) # False

from typing import Any, Dict, List, Optional, Sequence


def analyze_patient_records(
    records: Any,
    top_n: int = 5,
    thresholds: Optional[Dict[str, float]] = None,
) -> List[Dict[str, Any]]:
    """
    Analyze patient diagnostic records and return a prioritized summary
    of high-risk cases.

    Each valid record must include:
      - patient_id
      - age
      - symptom_severity_score
      - confidence_score
      - risk_factors

    Weighted risk score:
      severity * 0.6 + confidence * 0.4

    Risk categories are assigned using configurable thresholds:
      - Critical: score >= thresholds["critical"]
      - Moderate: score >= thresholds["moderate"]
      - Low: otherwise
    """
    default_thresholds = {"moderate": 40.0, "critical": 75.0}
    if thresholds is None:
        thresholds = default_thresholds
    else:
        thresholds = {
            "moderate": float(thresholds.get("moderate", default_thresholds["moderate"])),
            "critical": float(thresholds.get("critical", default_thresholds["critical"])),
        }

    if thresholds["moderate"] > thresholds["critical"]:
        thresholds["moderate"], thresholds["critical"] = (
            thresholds["critical"],
            thresholds["moderate"],
        )

    if not isinstance(records, Sequence) or isinstance(records, (str, bytes)):
        return []

    try:
        top_n = int(top_n)
    except (TypeError, ValueError):
        top_n = 5

    if top_n <= 0:
        return []

    required_fields = {
        "patient_id",
        "age",
        "symptom_severity_score",
        "confidence_score",
        "risk_factors",
    }

    def is_number(value: Any) -> bool:
        return isinstance(value, (int, float)) and not isinstance(value, bool)

    def categorize(score: float) -> str:
        if score >= thresholds["critical"]:
            return "Critical"
        if score >= thresholds["moderate"]:
            return "Moderate"
        return "Low"

    valid_patients: List[Dict[str, Any]] = []

    for record in records:
        if not isinstance(record, dict):
            continue
        if not required_fields.issubset(record.keys()):
            continue

        patient_id = record.get("patient_id")
        age = record.get("age")
        severity = record.get("symptom_severity_score")
        confidence = record.get("confidence_score")
        risk_factors = record.get("risk_factors")

        if patient_id in (None, ""):
            continue
        if not is_number(age) or age < 0:
            continue
        if not is_number(severity) or not is_number(confidence):
            continue
        if not isinstance(risk_factors, list):
            continue

        weighted_score = float(severity) * 0.6 + float(confidence) * 0.4

        valid_patients.append(
            {
                "patient_id": patient_id,
                "age": int(age) if float(age).is_integer() else float(age),
                "symptom_severity_score": float(severity),
                "confidence_score": float(confidence),
                "risk_factors": risk_factors,
                "computed_score": round(weighted_score, 2),
                "risk_category": categorize(weighted_score),
            }
        )

    valid_patients.sort(key=lambda patient: patient["computed_score"], reverse=True)
    return valid_patients[:top_n]


if __name__ == "__main__":
    sample_records = [
        {
            "patient_id": "P001",
            "age": 67,
            "symptom_severity_score": 88,
            "confidence_score": 92,
            "risk_factors": ["hypertension", "diabetes"],
        },
        {
            "patient_id": "P002",
            "age": 45,
            "symptom_severity_score": 55,
            "confidence_score": 60,
            "risk_factors": ["smoker"],
        },
        {
            "patient_id": "P003",
            "age": 30,
            "symptom_severity_score": 25,
            "confidence_score": 35,
            "risk_factors": [],
        },
        {
            "patient_id": "P004",
            "age": 72,
            "symptom_severity_score": 95,
            "confidence_score": 85,
            "risk_factors": ["cardiovascular disease"],
        },
        {
            "patient_id": "P005",
            "age": None,
            "symptom_severity_score": 80,
            "confidence_score": 70,
            "risk_factors": ["asthma"],
        },
        "invalid_record",
    ]

    result = analyze_patient_records(
        sample_records,
        top_n=3,
        thresholds={"moderate": 50, "critical": 80},
    )

    for patient in result:
        print(patient)

import re
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional


def parse_pipeline_log(raw_log_text: str) -> Dict[str, Any]:
    """
    Parse CI/CD pipeline logs from tools such as Jenkins or GitLab CI and return
    a JSON-serializable summary of stages and overall pipeline health.

    Returns a dictionary with:
      - pipeline_status: "success", "failed", "partial", or "unknown"
      - started_at: ISO-8601 timestamp or None
      - ended_at: ISO-8601 timestamp or None
      - duration_seconds: float or None
      - stages: list of stage summaries
      - failed_stages: list of failed stage summaries
      - errors: parser-level issues encountered
    """
    if not isinstance(raw_log_text, str):
        return {
            "pipeline_status": "unknown",
            "started_at": None,
            "ended_at": None,
            "duration_seconds": None,
            "stages": [],
            "failed_stages": [],
            "errors": ["Input must be a string containing raw log text."],
        }

    lines = raw_log_text.splitlines()
    parser_errors: List[str] = []
    stages: List[Dict[str, Any]] = []
    active_stage: Optional[Dict[str, Any]] = None

    pipeline_started_at: Optional[datetime] = None
    pipeline_ended_at: Optional[datetime] = None

    stage_start_patterns = [
        re.compile(r"^\s*(?:\[Pipeline\]\s+)?stage\s*\(\s*[\"']?(?P<name>[^\"')\]]+)[\"']?\s*\)", re.IGNORECASE),
        re.compile(r"^\s*(?:Entering|Starting)\s+stage[:\s-]+(?P<name>.+?)\s*$", re.IGNORECASE),
        re.compile(r"^\s*section_start:\d+:[^\r\n]*?(?P<name>[A-Za-z0-9_.\-/ ]+)", re.IGNORECASE),
        re.compile(r"^\s*==+\s*Stage[:\s-]+(?P<name>.+?)\s*==+\s*$", re.IGNORECASE),
    ]

    stage_end_patterns = [
        re.compile(r"^\s*(?:Exiting|Finished|Completed)\s+stage[:\s-]+(?P<name>.+?)\s*$", re.IGNORECASE),
        re.compile(r"^\s*section_end:\d+:[^\r\n]*?(?P<name>[A-Za-z0-9_.\-/ ]+)", re.IGNORECASE),
    ]

    success_patterns = [
        re.compile(r"\b(?:SUCCESS|PASSED|OK|completed successfully|Job succeeded)\b", re.IGNORECASE),
    ]

    failure_patterns = [
        re.compile(r"\b(?:FAILURE|FAILED|ERROR|ABORTED|Job failed|script returned exit code \d+)\b", re.IGNORECASE),
    ]

    error_line_patterns = [
        re.compile(r"\bERROR\b[:\s-]*(?P<msg>.+)", re.IGNORECASE),
        re.compile(r"\bException\b[:\s-]*(?P<msg>.+)", re.IGNORECASE),
        re.compile(r"\bTraceback\b", re.IGNORECASE),
        re.compile(r"\bscript returned exit code \d+\b", re.IGNORECASE),
    ]

    def normalize_stage_name(name: str) -> str:
        return re.sub(r"\s+", " ", name.strip(" -:\t\r\n[]")).strip()

    def parse_timestamp(line: str) -> Optional[datetime]:
        candidates = [
            r"(?P<ts>\d{4}-\d{2}-\d{2}[T ][0-2]\d:[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-][0-2]\d:?[0-5]\d)?)",
            r"(?P<ts>\d{4}-\d{2}-\d{2} [0-2]\d:[0-5]\d:[0-5]\d)",
            r"(?P<ts>\d{2}:\d{2}:\d{2})",
            r"^\s*\[(?P<ts>\d{2}:\d{2}:\d{2})\]",
        ]
        for pattern in candidates:
            match = re.search(pattern, line)
            if not match:
                continue
            raw_ts = match.group("ts")
            dt = _coerce_datetime(raw_ts)
            if dt:
                return dt
        return None

    def _coerce_datetime(value: str) -> Optional[datetime]:
        value = value.strip()
        try:
            if value.endswith("Z"):
                return datetime.fromisoformat(value.replace("Z", "+00:00"))
            return datetime.fromisoformat(value)
        except ValueError:
            pass

        fmts = [
            "%Y-%m-%d %H:%M:%S",
            "%H:%M:%S",
        ]
        for fmt in fmts:
            try:
                dt = datetime.strptime(value, fmt)
                if fmt == "%H:%M:%S":
                    today = datetime.now().date()
                    return datetime.combine(today, dt.time()).replace(tzinfo=timezone.utc)
                return dt.replace(tzinfo=timezone.utc)
            except ValueError:
                continue
        return None

    def isoformat_or_none(dt: Optional[datetime]) -> Optional[str]:
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.isoformat()

    def duration_seconds(start: Optional[datetime], end: Optional[datetime]) -> Optional[float]:
        if start is None or end is None:
            return None
        try:
            delta = (end - start).total_seconds()
            return max(delta, 0.0)
        except Exception:
            return None

    def new_stage(name: str, started_at: Optional[datetime]) -> Dict[str, Any]:
        return {
            "stage_name": normalize_stage_name(name) or "unknown",
            "status": "running",
            "started_at": isoformat_or_none(started_at),
            "ended_at": None,
            "duration_seconds": None,
            "error_messages": [],
            "_start_dt": started_at,
            "_end_dt": None,
        }

    def finalize_stage(stage: Dict[str, Any], ended_at: Optional[datetime], status_hint: Optional[str] = None) -> None:
        if ended_at is not None:
            stage["_end_dt"] = ended_at
            stage["ended_at"] = isoformat_or_none(ended_at)
        if status_hint in {"success", "failed", "aborted"}:
            stage["status"] = status_hint
        elif stage["status"] == "running":
            stage["status"] = "success" if not stage["error_messages"] else "failed"
        stage["duration_seconds"] = duration_seconds(stage.get("_start_dt"), stage.get("_end_dt"))

    def line_indicates_success(line: str) -> bool:
        return any(p.search(line) for p in success_patterns)

    def line_indicates_failure(line: str) -> bool:
        return any(p.search(line) for p in failure_patterns)

    def extract_error_message(line: str) -> Optional[str]:
        for pattern in error_line_patterns:
            match = pattern.search(line)
            if match:
                msg = match.groupdict().get("msg")
                return (msg or line.strip())[:1000]
        return None

    for idx, line in enumerate(lines):
        ts = parse_timestamp(line)
        if ts:
            if pipeline_started_at is None:
                pipeline_started_at = ts
            pipeline_ended_at = ts

        started = False
        for pattern in stage_start_patterns:
            match = pattern.search(line)
            if match:
                stage_name = normalize_stage_name(match.group("name"))
                if active_stage is not None:
                    finalize_stage(active_stage, ts, "failed" if active_stage["error_messages"] else "success")
                    stages.append(active_stage)
                active_stage = new_stage(stage_name, ts)
                started = True
                break
        if started:
            continue

        ended = False
        for pattern in stage_end_patterns:
            match = pattern.search(line)
            if match:
                stage_name = normalize_stage_name(match.group("name"))
                if active_stage is None:
                    parser_errors.append(
                        f"Encountered stage end for '{stage_name}' on line {idx + 1} without an active stage."
                    )
                else:
                    if stage_name and active_stage["stage_name"].lower() != stage_name.lower():
                        parser_errors.append(
                            f"Stage end name '{stage_name}' on line {idx + 1} does not match active stage "
                            f"'{active_stage['stage_name']}'."
                        )
                    status_hint = "failed" if active_stage["error_messages"] or line_indicates_failure(line) else (
                        "success" if line_indicates_success(line) else None
                    )
                    finalize_stage(active_stage, ts, status_hint)
                    stages.append(active_stage)
                    active_stage = None
                ended = True
                break
        if ended:
            continue

        if active_stage is not None:
            if line_indicates_failure(line):
                active_stage["status"] = "failed"
            elif line_indicates_success(line) and active_stage["status"] == "running":
                active_stage["status"] = "success"

            error_msg = extract_error_message(line)
            if error_msg:
                active_stage["error_messages"].append(error_msg)
                active_stage["status"] = "failed"

    if active_stage is not None:
        finalize_stage(active_stage, pipeline_ended_at, "failed" if active_stage["error_messages"] else None)
        stages.append(active_stage)

    if not stages and raw_log_text.strip():
        inferred_stage = new_stage("pipeline", pipeline_started_at)
        if any(line_indicates_failure(line) for line in lines):
            inferred_stage["status"] = "failed"
            inferred_stage["error_messages"] = [
                msg for msg in (extract_error_message(line) for line in lines) if msg
            ]
        elif any(line_indicates_success(line) for line in lines):
            inferred_stage["status"] = "success"
        else:
            inferred_stage["status"] = "unknown"
        finalize_stage(inferred_stage, pipeline_ended_at, inferred_stage["status"] if inferred_stage["status"] in {"success", "failed"} else None)
        stages.append(inferred_stage)

    for stage in stages:
        stage.pop("_start_dt", None)
        stage.pop("_end_dt", None)
        if stage["status"] == "running":
            stage["status"] = "unknown"

    failed_stages = [stage for stage in stages if stage.get("status") in {"failed", "aborted"}]

    if stages:
        if failed_stages:
            pipeline_status = "failed"
        elif all(stage.get("status") == "success" for stage in stages):
            pipeline_status = "success"
        elif any(stage.get("status") == "success" for stage in stages):
            pipeline_status = "partial"
        else:
            pipeline_status = "unknown"
    else:
        pipeline_status = "unknown"

    if pipeline_started_at is None:
        for stage in stages:
            if stage.get("started_at"):
                pipeline_started_at = datetime.fromisoformat(stage["started_at"])
                break

    if pipeline_ended_at is None:
        for stage in reversed(stages):
            if stage.get("ended_at"):
                pipeline_ended_at = datetime.fromisoformat(stage["ended_at"])
                break

    return {
        "pipeline_status": pipeline_status,
        "started_at": isoformat_or_none(pipeline_started_at),
        "ended_at": isoformat_or_none(pipeline_ended_at),
        "duration_seconds": duration_seconds(pipeline_started_at, pipeline_ended_at),
        "stages": stages,
        "failed_stages": failed_stages,
        "errors": parser_errors,
    }

