class TransactionalDict:
    # Sentinel to mark deleted keys inside a transaction layer
    _DELETED = object()

    def __init__(self, initial=None, _base=None, _stack=None):
        self._base = dict(initial or {}) if _base is None else _base
        self._stack = [] if _stack is None else _stack

    def __enter__(self):
        # Push a new transaction layer
        self._stack.append({})
        return self

    def __exit__(self, exc_type, exc, tb):
        layer = self._stack.pop()
        if exc_type is not None:
            # Roll back this layer by discarding it
            return False

        if self._stack:
            # Commit into parent transaction layer
            self._stack[-1].update(layer)
        else:
            # Commit into base dictionary
            for key, value in layer.items():
                if value is self._DELETED:
                    self._base.pop(key, None)
                else:
                    self._base[key] = value
        return False

    def __setitem__(self, key, value):
        if self._stack:
            self._stack[-1][key] = value
        else:
            self._base[key] = value

    def __getitem__(self, key):
        for layer in reversed(self._stack):
            if key in layer:
                if layer[key] is self._DELETED:
                    break
                return layer[key]
        if key in self._base:
            return self._base[key]
        raise KeyError(key)

    def __delitem__(self, key):
        # Ensure the key is currently visible before deleting
        self[key]
        if self._stack:
            self._stack[-1][key] = self._DELETED
        else:
            del self._base[key]

    def __contains__(self, key):
        try:
            self[key]
            return True
        except KeyError:
            return False

    def to_dict(self):
        # Build the visible state by applying layers in order
        result = dict(self._base)
        for layer in self._stack:
            for key, value in layer.items():
                if value is self._DELETED:
                    result.pop(key, None)
                else:
                    result[key] = value
        return result


# Example usage
if __name__ == '__main__':
    store = TransactionalDict({'a': 1, 'b': 2})

    with store:
        store['a'] = 10
        store['c'] = 3
        with store:
            del store['b']
            store['d'] = 4
        # inner transaction committed here

    print(store.to_dict())  # {'a': 10, 'c': 3, 'd': 4}

from abc import ABC, abstractmethod


class NotificationChannel(ABC):
    """Strategy interface for sending notifications."""

    @abstractmethod
    def send(self, recipient: str, message: str) -> str:
        pass


class EmailChannel(NotificationChannel):
    def send(self, recipient: str, message: str) -> str:
        return f"Email sent to {recipient}: {message}"


class SMSChannel(NotificationChannel):
    def send(self, recipient: str, message: str) -> str:
        return f"SMS sent to {recipient}: {message}"


class PushChannel(NotificationChannel):
    def send(self, recipient: str, message: str) -> str:
        return f"Push notification sent to {recipient}: {message}"


class Notifier:
    """Uses a notification strategy that can be changed at runtime."""

    def __init__(self, channel: NotificationChannel):
        self.set_channel(channel)

    def set_channel(self, channel: NotificationChannel) -> None:
        if not isinstance(channel, NotificationChannel):
            raise ValueError("channel must be an instance of NotificationChannel")
        self._channel = channel

    def notify(self, recipient: str, message: str) -> str:
        return self._channel.send(recipient, message)


if __name__ == "__main__":
    notifier = Notifier(EmailChannel())
    print(notifier.notify("alice@example.com", "Your report is ready."))

    notifier.set_channel(SMSChannel())
    print(notifier.notify("+123456789", "Your verification code is 4821."))

    notifier.set_channel(PushChannel())
    print(notifier.notify("user_42", "You have a new follower."))

