from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timedelta


@dataclass(frozen=True, slots=True)
class Event:
    id: int
    title: str
    start: datetime
    duration_minutes: int
    tags: frozenset[str]

    @property
    def end(self) -> datetime:
        return self.start + timedelta(minutes=self.duration_minutes)


@dataclass(slots=True)
class Scheduler:
    events: dict[int, Event] = field(default_factory=dict)

    def add_event(self, event: Event) -> None:
        if event.id in self.events:
            raise ValueError(f"Event with id {event.id} already exists")

        for existing in self.events.values():
            # Two events overlap if each starts before the other ends.
            if event.start < existing.end and existing.start < event.end:
                raise ValueError(
                    f"Event {event.id} overlaps with existing event {existing.id}"
                )

        self.events[event.id] = event

    def get_events_by_tag(self, tag: str) -> list[Event]:
        matched = [event for event in self.events.values() if tag in event.tags]
        return sorted(matched, key=lambda event: event.start)

    def total_minutes_by_tag(self) -> dict[str, int]:
        totals: dict[str, int] = {}
        for event in self.events.values():
            for tag in event.tags:
                totals[tag] = totals.get(tag, 0) + event.duration_minutes
        return totals


if __name__ == "__main__":
