    print(scheduler.total_minutes_by_tag())

import hashlib


class BloomFilter:
    def __init__(self, size: int, hash_count: int):
        if size <= 0 or hash_count <= 0:
            raise ValueError("size and hash_count must be positive")
        self.size = size
        self.hash_count = hash_count
        self.bits = [0] * size

    def _hashes(self, item: str):
        # Generate multiple deterministic hashes by salting the item.
        for i in range(self.hash_count):
            data = f"{i}:{item}".encode("utf-8")
            digest = hashlib.sha256(data).digest()
            yield int.from_bytes(digest, "big") % self.size

    def add(self, item: str):
        for index in self._hashes(item):
            self.bits[index] = 1

    def contains(self, item: str) -> bool:
        return all(self.bits[index] for index in self._hashes(item))


if __name__ == "__main__":
    bf = BloomFilter(size=100, hash_count=3)

    inserted_words = ["apple", "banana", "grape", "orange"]
    for word in inserted_words:
        bf.add(word)

    test_words = ["apple", "banana", "cherry", "melon", "grape"]
    for word in test_words:
        print(f"{word}: {bf.contains(word)}")

class Router:
    def __init__(self):
        # Store routes as (pattern_parts, handler_name)
        self._routes = []

    def add_route(self, pattern, handler_name):
        """Register a route pattern with its handler name."""
        pattern_parts = self._split_path(pattern)
        self._routes.append((pattern_parts, handler_name))

    def match(self, path):
        """Match a path against registered routes in order."""
        path_parts = self._split_path(path)

        for pattern_parts, handler_name in self._routes:
            if len(pattern_parts) != len(path_parts):
                continue

            params = {}
            matched = True

            for pattern_part, path_part in zip(pattern_parts, path_parts):
                if self._is_param(pattern_part):
                    param_name = pattern_part[1:-1]
                    params[param_name] = path_part
                elif pattern_part != path_part:
                    matched = False
                    break

            if matched:
                return {
                    'handler': handler_name,
                    'params': params
                }

        return None

    @staticmethod
    def _split_path(path):
        """Normalize and split a path into parts."""
        stripped = path.strip('/')
        return [] if not stripped else stripped.split('/')

    @staticmethod
    def _is_param(part):
        """Check if a route segment is a dynamic parameter."""
        return part.startswith('<') and part.endswith('>') and len(part) > 2


# Example usage
if __name__ == '__main__':
    router = Router()
    router.add_route('/users/<id>', 'user_detail')
    router.add_route('/posts/<post_id>/comments/<comment_id>', 'comment_detail')
    router.add_route('/about', 'about_page')

    print(router.match('/users/42'))
    print(router.match('/posts/10/comments/5'))
    print(router.match('/about'))
    print(router.match('/missing'))

import socket
import selectors

HOST = '127.0.0.1'
PORT = 9000
sel = selectors.DefaultSelector()


def accept(sock):
    conn, addr = sock.accept()
    conn.setblocking(False)
    sel.register(conn, selectors.EVENT_READ, data=addr)
    print(f'Connected: {addr}')


def close_connection(conn):
    try:
        addr = sel.get_key(conn).data
    except KeyError:
        addr = 'unknown'
    print(f'Closed: {addr}')
    sel.unregister(conn)
    conn.close()


def service(conn):
    try:
        data = conn.recv(1024)
    except ConnectionResetError:
        close_connection(conn)
        return

    if not data:
        close_connection(conn)
        return

    message = data.decode('utf-8').strip()
    if message == 'quit':
        close_connection(conn)
        return

    response = f'echo: {message}\n'.encode('utf-8')
    conn.sendall(response)


def main():
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server.bind((HOST, PORT))
    server.listen()
    server.setblocking(False)
    sel.register(server, selectors.EVENT_READ)

    print(f'Server listening on {HOST}:{PORT}')
    try:
        while True:
            for key, _ in sel.select():
                if key.fileobj is server:
                    accept(server)
                else:
                    service(key.fileobj)
    except KeyboardInterrupt:
        print('\nShutting down server...')
    finally:
        sel.close()
        server.close()


if __name__ == '__main__':
    main()
}

from html.parser import HTMLParser
import xml.etree.ElementTree as ET
import re


class ProductHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.products = []
        self.current = None
        self.in_title = False
        self.in_price = False

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == 'div' and attrs.get('class') == 'product' and 'data-sku' in attrs:
            self.current = {'sku': attrs['data-sku'], 'title': '', 'price': None}
        elif self.current and tag == 'h2':
            self.in_title = True
        elif self.current and tag == 'span' and attrs.get('class') == 'price':
            self.in_price = True

    def handle_endtag(self, tag):
        if tag == 'h2':
            self.in_title = False
        elif tag == 'span':
            self.in_price = False
        elif tag == 'div' and self.current:
            if self.current['title'] and self.current['price'] is not None:
                self.products.append(self.current)
            self.current = None

    def handle_data(self, data):
        if not self.current:
            return
        text = data.strip()
        if not text:
            return
        if self.in_title:
            self.current['title'] += (text if not self.current['title'] else ' ' + text)
        elif self.in_price:
            match = re.search(r'\$\s*([0-9]+(?:\.[0-9]+)?)', text)
            if match:
                self.current['price'] = float(match.group(1))


def extract_catalog(html: str, xml_data: str) -> list[dict]:
    # Parse HTML product data
    html_parser = ProductHTMLParser()
    html_parser.feed(html)
    html_products = {item['sku']: item for item in html_parser.products}

    # Parse XML inventory data
    root = ET.fromstring(xml_data)
    xml_products = {}
    for item in root.findall('.//item'):
        sku = item.get('sku')
        stock_text = item.findtext('stock', default='').strip()
        category = item.findtext('category', default='').strip()
        if not sku or not stock_text or not category:
            continue
        try:
            xml_products[sku] = {
                'stock': int(stock_text),
                'category': category,
            }
        except ValueError:
            continue

    # Merge matching products from both sources
    merged = []
    for sku in sorted(set(html_products) & set(xml_products)):
        merged.append({
            'sku': sku,
            'title': html_products[sku]['title'],
            'price': html_products[sku]['price'],
            'stock': xml_products[sku]['stock'],
            'category': xml_products[sku]['category'],
        })

    return merged

from typing import Dict, Literal
import re

from pydantic import BaseModel, Field, field_validator, model_validator, ValidationError


IMAGE_RE = re.compile(r"^[a-z0-9._-]+/[a-z0-9._-]+:[A-Za-z0-9._-]+$")
ENV_KEY_RE = re.compile(r"^[A-Z_][A-Z0-9_]*$")
APP_NAME_RE = re.compile(r"^[a-z][a-z0-9-]{2,29}$")


class DeploymentConfig(BaseModel):
    app_name: str
    replicas: int = Field(ge=1, le=20)
    environment: Literal["dev", "staging", "prod"]
    image: str
    env_vars: Dict[str, str]

    @field_validator("app_name")
    @classmethod
    def validate_app_name(cls, value: str) -> str:
        value = value.lower()
        if not APP_NAME_RE.fullmatch(value):
            raise ValueError(
                "app_name must be 3-30 chars, start with a letter, and contain only lowercase letters, digits, or hyphens"
            )
        return value

    @field_validator("image")
    @classmethod
    def validate_image(cls, value: str) -> str:
        if not IMAGE_RE.fullmatch(value):
            raise ValueError("image must match 'repo/name:tag'")
        return value

    @field_validator("env_vars")
    @classmethod
    def validate_env_vars(cls, value: Dict[str, str]) -> Dict[str, str]:
        normalized = {}
        for key, val in value.items():
            if not ENV_KEY_RE.fullmatch(key):
                raise ValueError(f"invalid env var name: {key}")
            if not isinstance(val, str) or not val.strip():
                raise ValueError(f"env var '{key}' must have a non-empty string value")
            normalized[key] = val
        return normalized

    @model_validator(mode="after")
    def validate_cross_fields(self) -> "DeploymentConfig":
        if self.environment == "prod" and self.replicas < 3:
            raise ValueError("prod deployments must have at least 3 replicas")
        if self.environment == "prod" and self.env_vars.get("DEBUG", "").lower() == "true":
            raise ValueError("DEBUG=true is not allowed in prod")
        return self


def validate_config(payload: dict) -> dict:
    config = DeploymentConfig.model_validate(payload)
    data = config.model_dump()
    data["env_vars"] = dict(sorted(data["env_vars"].items()))
    return data


if __name__ == "__main__":
    sample = {
        "app_name": "My-Service",
        "replicas": 3,
        "environment": "staging",
        "image": "backend/api:v1.2.0",
        "env_vars": {
            "LOG_LEVEL": "info",
            "DEBUG": "false",
            "API_KEY": "secret"
        }
    }

    try:
        print(validate_config(sample))
    except ValidationError as e:
        print(e.json())

from html.parser import HTMLParser
from xml.etree import ElementTree as ET
import re


class CatalogParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_catalog = False
        self.in_row = False
        self.current_field = None
        self.current_product = None
        self.products = []
        self.field_buffer = []
        self.current_tags = []
        self.capture_xml = False
        self.xml_parts = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == 'table' and attrs.get('id') == 'catalog':
            self.in_catalog = True
        elif self.in_catalog and tag == 'tr':
            sku = attrs.get('data-sku', '').strip()
            self.in_row = True
            self.current_product = {'sku': sku, 'name': '', 'price': None, 'tags': []}
        elif self.in_row and tag == 'td':
            cls = attrs.get('class', '')
            if cls in {'name', 'price', 'tags'}:
                self.current_field = cls
                self.field_buffer = []
                if cls == 'tags':
                    self.current_tags = []
        elif self.current_field == 'tags' and tag == 'span':
            self.field_buffer = []
        elif tag == 'script' and attrs.get('type') == 'application/xml' and attrs.get('id') == 'metadata':
            self.capture_xml = True
            self.xml_parts = []

    def handle_endtag(self, tag):
        if tag == 'table' and self.in_catalog:
            self.in_catalog = False
        elif tag == 'tr' and self.in_row:
            self.in_row = False
            if self.current_field == 'tags':
                self.current_product['tags'] = self.current_tags
            if self.current_product:
                self.products.append(self.current_product)
            self.current_product = None
            self.current_field = None
        elif tag == 'td' and self.in_row and self.current_field:
            text = ''.join(self.field_buffer).strip()
            if self.current_field == 'name':
                self.current_product['name'] = text
            elif self.current_field == 'price':
                match = re.search(r'-?\d+(?:\.\d+)?', text.replace(',', ''))
                self.current_product['price'] = float(match.group()) if match else None
            elif self.current_field == 'tags':
                self.current_product['tags'] = self.current_tags
            self.current_field = None
            self.field_buffer = []
        elif tag == 'span' and self.current_field == 'tags':
            text = ''.join(self.field_buffer).strip()
            if text:
                self.current_tags.append(text)
            self.field_buffer = []
        elif tag == 'script' and self.capture_xml:
            self.capture_xml = False

    def handle_data(self, data):
        if self.capture_xml:
            self.xml_parts.append(data)
        elif self.in_row and self.current_field:
            self.field_buffer.append(data)


def extract_catalog(html: str) -> list[dict]:
    parser = CatalogParser()
    parser.feed(html)

    metadata = {}
    xml_text = ''.join(parser.xml_parts).strip()
    if xml_text:
        try:
            root = ET.fromstring(xml_text)
            for item in root.findall('.//item'):
                sku = (item.get('sku') or '').strip()
                if not sku:
                    continue
                entry = {}
                if item.get('category'):
                    entry['category'] = item.get('category').strip()
                if item.get('stock'):
                    try:
                        entry['stock'] = int(item.get('stock'))
                    except ValueError:
                        pass
                metadata[sku] = entry
        except ET.ParseError:
            pass

    result = []
    for product in parser.products:
        if not product['sku'] or not product['name'] or product['price'] is None:
            continue
        merged = {
            'sku': product['sku'],
            'name': product['name'],
            'price': product['price'],
            'tags': product['tags'],
        }
        merged.update(metadata.get(product['sku'], {}))
        result.append(merged)

    return sorted(result, key=lambda x: x['sku'])

class AgeValidationError(Exception):
    """Base exception for age validation errors."""
    pass


class TooYoungError(AgeValidationError):
    """Raised when the age is below the allowed minimum."""
    pass


class TooOldError(AgeValidationError):
    """Raised when the age is above the allowed maximum."""
    pass


def validate_age(age):
    """Validate an age and return a success message if it is acceptable."""
    if age < 18:
        raise TooYoungError(f"Age {age} is too young. Minimum age is 18.")
    if age > 120:
        raise TooOldError(f"Age {age} is too old. Maximum age is 120.")
    return f"Age {age} is valid."


