        print(result)
    except TooYoungError as e:
        print(f"TooYoungError: {e}")
    except TooOldError as e:
        print(f"TooOldError: {e}")
    except AgeValidationError as e:
        print(f"AgeValidationError: {e}")

SECRET_TOKEN = "my-secret-token"


def handle_webhook(headers, payload):
    """Process a simulated webhook request."""
    token = headers.get("X-Webhook-Token")

    # Reject requests with a missing or invalid token
    if token != SECRET_TOKEN:
        return {"status": "error", "message": "unauthorized"}

    event = payload.get("event")

    # Handle known event types
    if event == "user.created":
        user = payload.get("data", {})
        name = user.get("name", "unknown")
        return {"status": "success", "message": f"User created: {name}"}

    if event == "order.paid":
        order = payload.get("data", {})
        order_id = order.get("order_id", "unknown")
