class NonNegative:
    """Descriptor that ensures a numeric attribute is never negative."""

    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if value < 0:
            raise ValueError(f"{self.private_name[1:]} cannot be negative")
        setattr(instance, self.private_name, value)


class Product:
    # Use the descriptor for validation
    price = NonNegative()
    stock = NonNegative()

    def __init__(self, name, price, stock):
        self.name = name
        self.price = price
        self.stock = stock

    @property
    def total_value(self):
        """Return the total value of all items in stock."""
        return self.price * self.stock

    @total_value.setter
    def total_value(self, new_total):
        """Update price so that price * stock equals the new total."""
        if new_total < 0:
            raise ValueError("total_value cannot be negative")
        if self.stock == 0:
            raise ValueError("Cannot set total_value when stock is zero")
        self.price = new_total / self.stock


# Example usage
product = Product("Notebook", 5.0, 20)
print("Initial total value:", product.total_value)

product.total_value = 200
print("Updated price:", product.price)
print("Updated total value:", product.total_value)

from abc import ABC, abstractmethod


class PaymentMethod(ABC):
    @abstractmethod
    def authorize(self, amount):
        pass

    @abstractmethod
    def capture(self, amount):
        pass

    @abstractmethod
    def refund(self, amount):
        pass


class CreditCardPayment(PaymentMethod):
    def __init__(self):
        self.authorized = 0.0
        self.captured = 0.0
        self.refunded = 0.0

    def authorize(self, amount):
        if amount <= 0:
            raise ValueError("Authorization amount must be positive")
        self.authorized += amount
        return True

    def capture(self, amount):
        if amount <= 0:
            raise ValueError("Capture amount must be positive")
        if self.captured + amount > self.authorized:
            raise ValueError("Cannot capture more than authorized amount")
        self.captured += amount
        return True

    def refund(self, amount):
        if amount <= 0:
            raise ValueError("Refund amount must be positive")
        if self.refunded + amount > self.captured:
            raise ValueError("Cannot refund more than captured amount")
        self.refunded += amount
        return True


class GiftCardPayment(PaymentMethod):
    def __init__(self, balance):
        if balance < 0:
            raise ValueError("Initial balance cannot be negative")
        self.balance = float(balance)
        self.authorized = 0.0
        self.captured = 0.0
        self.refunded = 0.0

    def authorize(self, amount):
        if amount <= 0:
            raise ValueError("Authorization amount must be positive")
        if amount > self.balance:
            raise ValueError("Insufficient gift card balance")
        self.balance -= amount
        self.authorized += amount
        return True

    def capture(self, amount):
        if amount <= 0:
            raise ValueError("Capture amount must be positive")
        if self.captured + amount > self.authorized:
            raise ValueError("Cannot capture more than authorized amount")
        self.captured += amount
        return True

    def refund(self, amount):
        if amount <= 0:
            raise ValueError("Refund amount must be positive")
        if self.refunded + amount > self.captured:
            raise ValueError("Cannot refund more than captured amount")
        self.refunded += amount
        self.balance += amount
        return True


def process_order(payment_method, auth_amount, capture_amount, refund_amount):
    payment_method.authorize(auth_amount)
    payment_method.capture(capture_amount)
    payment_method.refund(refund_amount)

    summary = {
        "type": payment_method.__class__.__name__,
        "authorized": payment_method.authorized,
        "captured": payment_method.captured,
        "refunded": payment_method.refunded,
    }

    if hasattr(payment_method, "balance"):
        summary["balance"] = payment_method.balance

    return summary


if __name__ == "__main__":
    cc = CreditCardPayment()
    gc = GiftCardPayment(balance=100)

    print(process_order(cc, 120, 90, 20))
    print(process_order(gc, 50, 30, 10))

import sys
import string
from collections import Counter


def count_words(file_path):
    """Count word frequencies by streaming the file line by line."""
    counts = Counter()
    translator = str.maketrans('', '', string.punctuation)

    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            # Normalize case and remove punctuation before splitting into words
            cleaned = line.lower().translate(translator)
            counts.update(cleaned.split())

    return dict(counts)


def main():
    if len(sys.argv) != 2:
        print('Usage: python word_count.py <file_path>')
        sys.exit(1)

    file_path = sys.argv[1]

    try:
        counts = count_words(file_path)
    except FileNotFoundError:
        print(f'Error: file not found: {file_path}')
        sys.exit(1)
    except OSError as e:
        print(f'Error reading file: {e}')
        sys.exit(1)

    top_words = Counter(counts).most_common(10)
    for word, count in top_words:
        print(f'{word}: {count}')


if __name__ == '__main__':
    main()

