Trade = Dict[str, Any]


def select_best_trade(trades: List[Trade], min_volume: int) -> Optional[Trade]:
    valid_trades = list(
        filter(
            lambda trade: trade.get("volume", 0) >= min_volume and trade.get("risk", 0) != 0,
            trades,
        )
