import random
import time


class CircuitOpenError(Exception):
    pass


class CircuitBreaker:
    def __init__(self, failure_threshold=3, recovery_timeout=5):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.failure_count = 0
        self.state = 'CLOSED'  # CLOSED, OPEN, HALF_OPEN
        self.opened_at = None

    def before_call(self):
        if self.state == 'OPEN':
            elapsed = time.time() - self.opened_at
            if elapsed >= self.recovery_timeout:
                self.state = 'HALF_OPEN'
            else:
                raise CircuitOpenError('Circuit is open; call blocked')

    def record_success(self):
        self.failure_count = 0
        self.state = 'CLOSED'
        self.opened_at = None

    def record_failure(self):
        self.failure_count += 1
        if self.state == 'HALF_OPEN' or self.failure_count >= self.failure_threshold:
            self.state = 'OPEN'
            self.opened_at = time.time()


def call_with_retry(operation, breaker, retries=3, delay=0.5):
    for attempt in range(1, retries + 1):
        try:
            breaker.before_call()
            result = operation()
            breaker.record_success()
            print(f'Attempt {attempt}: success -> {result}')
            return result
        except CircuitOpenError as e:
            print(f'Attempt {attempt}: blocked -> {e}')
            raise
        except Exception as e:
            breaker.record_failure()
            print(f'Attempt {attempt}: failed -> {e}')
            if attempt == retries:
                raise
            time.sleep(delay)


def unreliable_operation():
    # Simulate a flaky external service.
    if random.random() < 0.7:
        raise RuntimeError('Temporary service error')
    return 'OK'


if __name__ == '__main__':
    random.seed(42)
    breaker = CircuitBreaker(failure_threshold=3, recovery_timeout=5)

    for i in range(10):
        print(f'\nCall #{i + 1} | circuit state: {breaker.state}')
        try:
            call_with_retry(unreliable_operation, breaker, retries=3, delay=0.5)
        except Exception as e:
            print(f'Final result: {type(e).__name__}: {e}')
        time.sleep(1)

from typing import Callable, Dict, List


class PluginManager:
    def __init__(self) -> None:
        self._plugins: Dict[str, Callable[[str], str]] = {}

    def register(self, name: str, plugin: Callable[[str], str]) -> None:
        if not callable(plugin):
            raise TypeError("plugin must be callable")
        self._plugins[name] = plugin

    def unregister(self, name: str) -> None:
        if name not in self._plugins:
            raise KeyError(f"Plugin '{name}' not found")
        del self._plugins[name]

    def list_plugins(self) -> List[str]:
        return sorted(self._plugins.keys())

    def run(self, name: str, text: str) -> str:
        if name not in self._plugins:
            raise KeyError(f"Plugin '{name}' not found")
        return self._plugins[name](text)


