class TransactionError(Exception):
    """Base class for all transaction-related validation errors."""


class InvalidAmountError(TransactionError):
    """Raised when a transaction amount is zero or negative."""


class UnsupportedCurrencyError(TransactionError):
    """Raised when a transaction currency is not supported."""


class AccountFrozenError(TransactionError):
    """Raised when a transaction is attempted on a frozen account."""


SUPPORTED_CURRENCIES = {"USD", "EUR", "JPY"}


def validate_transaction(amount, currency, frozen_accounts, account_id):
    """Validate a single transaction or raise a specific TransactionError."""
    if amount <= 0:
        raise InvalidAmountError(f"Amount must be positive, got {amount}.")
    if currency not in SUPPORTED_CURRENCIES:
        raise UnsupportedCurrencyError(
            f"Currency '{currency}' is not supported."
        )
    if account_id in frozen_accounts:
        raise AccountFrozenError(f"Account '{account_id}' is frozen.")


def process_transactions(transactions, frozen_accounts):
    """Process a batch of transactions and collect successes and failures."""
    summary = {"processed": [], "errors": []}

    for tx in transactions:
        try:
            validate_transaction(
                amount=tx["amount"],
                currency=tx["currency"],
                frozen_accounts=frozen_accounts,
                account_id=tx["account_id"],
            )
            summary["processed"].append(tx["id"])
        except TransactionError as exc:
            summary["errors"].append(
                {
                    "id": tx.get("id"),
                    "error": type(exc).__name__,
                    "message": str(exc),
                }
            )

    return summary


if __name__ == "__main__":
    transactions = [
        {"id": "t1", "amount": 150, "currency": "USD", "account_id": "A100"},
        {"id": "t2", "amount": -20, "currency": "EUR", "account_id": "A101"},
        {"id": "t3", "amount": 75, "currency": "GBP", "account_id": "A102"},
        {"id": "t4", "amount": 40, "currency": "JPY", "account_id": "A999"},
    ]
    frozen_accounts = {"A999"}

    result = process_transactions(transactions, frozen_accounts)
    print(result)
}

