import os
import json
import hashlib
import zipfile
from pathlib import Path


def sha256_file(path, chunk_size=65536):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            h.update(chunk)
    return h.hexdigest()


def build_deduplicated_zip(source_dir, zip_path):
    source = Path(source_dir).resolve()
    manifest = {}
    stored_hashes = set()

    with zipfile.ZipFile(zip_path, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
        for file_path in sorted(source.rglob('*')):
            if not file_path.is_file():
                continue

            rel_path = file_path.relative_to(source).as_posix()
            file_hash = sha256_file(file_path)
            stat = file_path.stat()

            manifest[rel_path] = {
                'hash': file_hash,
                'size': stat.st_size,
                'mtime': int(stat.st_mtime)
            }

            if file_hash not in stored_hashes:
                zf.write(file_path, arcname=f'.data/{file_hash}')
                stored_hashes.add(file_hash)

        zf.writestr('manifest.json', json.dumps(manifest, indent=2, sort_keys=True))


if __name__ == '__main__':
    import sys

    if len(sys.argv) != 3:
        print(f'Usage: {sys.argv[0]} <source_dir> <output.zip>')
        raise SystemExit(1)

    build_deduplicated_zip(sys.argv[1], sys.argv[2])
    print(f'Created archive: {sys.argv[2]}')

import json
import math
import heapq
import threading
from collections import defaultdict, deque
from concurrent.futures import ThreadPoolExecutor
from queue import Queue
from typing import Any, Deque, Dict, Iterable, List, Optional, Tuple


def compute_inference_analytics(
    log_lines: Iterable[str],
    window_seconds: int,
    *,
    max_workers: Optional[int] = None,
    queue_maxsize: int = 10000,
    confidence_bins: int = 20,
) -> Dict[str, Any]:
    if window_seconds <= 0:
        raise ValueError("window_seconds must be > 0")
    if confidence_bins <= 1:
        raise ValueError("confidence_bins must be > 1")

    SENTINEL = object()

    def _safe_float(value: Any) -> Optional[float]:
        try:
            if value is None:
                return None
            result = float(value)
            if math.isnan(result) or math.isinf(result):
                return None
            return result
        except (TypeError, ValueError):
            return None

    def _safe_int(value: Any) -> Optional[int]:
        try:
            if value is None:
                return None
            return int(value)
        except (TypeError, ValueError):
            return None

    def _normalize_status(record: Dict[str, Any]) -> str:
        status = record.get("status")
        if isinstance(status, str):
            s = status.strip().lower()
            if s in {"success", "ok", "passed"}:
                return "success"
            if s in {"error", "failed", "failure"}:
                return "error"

        error_flag = record.get("error")
        if isinstance(error_flag, bool):
            return "error" if error_flag else "success"

        code = record.get("status_code")
        code_int = _safe_int(code)
        if code_int is not None:
            return "success" if 200 <= code_int < 400 else "error"

        success_flag = record.get("success")
        if isinstance(success_flag, bool):
            return "success" if success_flag else "error"

        return "error"

    def _extract_timestamp(record: Dict[str, Any]) -> Optional[float]:
        for key in ("timestamp", "ts", "time", "event_time"):
            if key in record:
                ts = _safe_float(record.get(key))
                if ts is not None:
                    return ts
        return None

    def _extract_latency_ms(record: Dict[str, Any]) -> Optional[float]:
        for key in ("latency_ms", "latency", "response_time_ms", "duration_ms"):
            if key in record:
                latency = _safe_float(record.get(key))
                if latency is not None and latency >= 0:
                    return latency
        return None

    def _extract_confidence(record: Dict[str, Any]) -> Optional[float]:
        for key in ("confidence", "prediction_confidence", "score", "probability"):
            if key in record:
                conf = _safe_float(record.get(key))
                if conf is not None:
                    if conf < 0.0:
                        conf = 0.0
                    elif conf > 1.0:
                        conf = 1.0
                    return conf
        return None

    def _extract_model(record: Dict[str, Any]) -> Optional[str]:
        model = record.get("model")
        if model is None:
            model = record.get("model_name")
        if model is None:
            return None
        model_str = str(model).strip()
        return model_str if model_str else None

    def _extract_version(record: Dict[str, Any]) -> Optional[str]:
        version = record.get("model_version")
        if version is None:
            version = record.get("version")
        if version is None:
            return None
        version_str = str(version).strip()
        return version_str if version_str else None

    def _extract_endpoint(record: Dict[str, Any]) -> Optional[str]:
        endpoint = record.get("endpoint")
        if endpoint is None:
            endpoint = record.get("route")
        if endpoint is None:
            endpoint = record.get("path")
        if endpoint is None:
            return None
        endpoint_str = str(endpoint).strip()
        return endpoint_str if endpoint_str else None

    def _parse_line(line: str) -> Optional[Tuple[float, str, str, str, float, Optional[float]]]:
        try:
            record = json.loads(line)
        except (json.JSONDecodeError, TypeError, ValueError):
            return None

        if not isinstance(record, dict):
            return None

        ts = _extract_timestamp(record)
        model = _extract_model(record)
        version = _extract_version(record)
        endpoint = _extract_endpoint(record)
        latency_ms = _extract_latency_ms(record)
        confidence = _extract_confidence(record)
        status = _normalize_status(record)

        if ts is None or model is None or version is None or endpoint is None or latency_ms is None:
            return None

        model_key = f"{model}:{version}"
        return ts, model_key, endpoint, status, latency_ms, confidence

    class WindowStats:
        __slots__ = (
            "count",
            "success_count",
            "error_count",
            "latency_sum",
            "latencies",
            "confidence_hist",
        )

        def __init__(self, bins: int) -> None:
            self.count = 0
            self.success_count = 0
            self.error_count = 0
            self.latency_sum = 0.0
            self.latencies: List[float] = []
            self.confidence_hist = [0] * bins

        def add(self, status: str, latency_ms: float, confidence: Optional[float], bins: int) -> None:
            self.count += 1
            if status == "success":
                self.success_count += 1
            else:
                self.error_count += 1
            self.latency_sum += latency_ms
            self.latencies.append(latency_ms)
            if confidence is not None:
                idx = min(int(confidence * bins), bins - 1)
                self.confidence_hist[idx] += 1

    class GroupAggregate:
        __slots__ = (
            "window_seconds",
            "bins",
            "windows",
            "total_count",
            "success_count",
            "error_count",
            "latency_sum",
            "latencies",
            "min_window",
            "max_window",
        )

        def __init__(self, window_seconds: int, bins: int) -> None:
            self.window_seconds = window_seconds
            self.bins = bins
            self.windows: Dict[int, WindowStats] = {}
            self.total_count = 0
            self.success_count = 0
            self.error_count = 0
            self.latency_sum = 0.0
            self.latencies: List[float] = []
            self.min_window: Optional[int] = None
            self.max_window: Optional[int] = None

        def add_record(
            self,
            timestamp: float,
            status: str,
            latency_ms: float,
            confidence: Optional[float],
        ) -> None:
            window_id = int(timestamp // self.window_seconds)
            ws = self.windows.get(window_id)
            if ws is None:
                ws = WindowStats(self.bins)
                self.windows[window_id] = ws
            ws.add(status, latency_ms, confidence, self.bins)

            self.total_count += 1
            if status == "success":
                self.success_count += 1
            else:
                self.error_count += 1
            self.latency_sum += latency_ms
            self.latencies.append(latency_ms)

            if self.min_window is None or window_id < self.min_window:
                self.min_window = window_id
            if self.max_window is None or window_id > self.max_window:
                self.max_window = window_id

        @staticmethod
        def _percentile(sorted_values: List[float], q: float) -> float:
            if not sorted_values:
                return 0.0
            if len(sorted_values) == 1:
                return float(sorted_values[0])
            pos = q * (len(sorted_values) - 1)
            lower = int(math.floor(pos))
            upper = int(math.ceil(pos))
            if lower == upper:
                return float(sorted_values[lower])
            weight = pos - lower
            return float(sorted_values[lower] * (1.0 - weight) + sorted_values[upper] * weight)

        @staticmethod
        def _normalize_hist(hist: List[int]) -> List[float]:
            total = sum(hist)
            if total == 0:
                return [0.0] * len(hist)
            return [v / total for v in hist]

        @staticmethod
        def _drift_score(prev_hist: List[int], curr_hist: List[int]) -> float:
            p = GroupAggregate._normalize_hist(prev_hist)
            c = GroupAggregate._normalize_hist(curr_hist)
            return 0.5 * sum(abs(a - b) for a, b in zip(p, c))

        def finalize(self) -> Dict[str, Any]:
            sorted_latencies = sorted(self.latencies)
            avg_latency = self.latency_sum / self.total_count if self.total_count else 0.0
            p95_latency = self._percentile(sorted_latencies, 0.95)

            if self.min_window is None or self.max_window is None:
                active_window_count = 0
            else:
                active_window_count = (self.max_window - self.min_window) + 1

            total_duration_seconds = active_window_count * self.window_seconds
            throughput = (
                self.total_count / total_duration_seconds if total_duration_seconds > 0 else 0.0
            )

            drift_by_window: List[Dict[str, Any]] = []
            sorted_window_ids = sorted(self.windows.keys())
            prev_hist: Optional[List[int]] = None
            for window_id in sorted_window_ids:
                curr_hist = self.windows[window_id].confidence_hist
                drift = None if prev_hist is None else self._drift_score(prev_hist, curr_hist)
                drift_by_window.append(
                    {
                        "window_start": window_id * self.window_seconds,
                        "window_end": (window_id + 1) * self.window_seconds,
                        "drift_score": drift,
                    }
                )
                prev_hist = curr_hist

            return {
                "total_request_count": self.total_count,
                "success_count": self.success_count,
                "error_count": self.error_count,
                "average_latency_ms": avg_latency,
                "p95_latency_ms": p95_latency,
                "throughput_rps": throughput,
                "drift": {
                    "confidence_bins": self.bins,
                    "window_scores": drift_by_window,
                    "latest_score": drift_by_window[-1]["drift_score"] if drift_by_window else None,
                },
            }

    parse_queue: "Queue[Tuple[int, str] | object]" = Queue(maxsize=queue_maxsize)
    parsed_results: Dict[int, Optional[Tuple[float, str, str, str, float, Optional[float]]]] = {}
    parsed_lock = threading.Lock()

    def _worker() -> None:
        while True:
            item = parse_queue.get()
            try:
                if item is SENTINEL:
                    return
                idx, line = item  # type: ignore[misc]
                parsed = _parse_line(line)
                with parsed_lock:
                    parsed_results[idx] = parsed
            finally:
                parse_queue.task_done()

    worker_count = max_workers
    if worker_count is None:
        worker_count = min(32, (threading.active_count() or 1) + 4)
    worker_count = max(1, worker_count)

    threads: List[threading.Thread] = []
    for _ in range(worker_count):
        t = threading.Thread(target=_worker, daemon=True)
        t.start()
        threads.append(t)

    total_lines = 0
    for idx, line in enumerate(log_lines):
        parse_queue.put((idx, line))
        total_lines += 1

    for _ in range(worker_count):
        parse_queue.put(SENTINEL)

    parse_queue.join()

    for t in threads:
        t.join()

    groups: Dict[Tuple[str, str], GroupAggregate] = {}
    malformed_count = 0

    for idx in range(total_lines):
        parsed = parsed_results.get(idx)
        if parsed is None:
            malformed_count += 1
            continue
        ts, model_key, endpoint, status, latency_ms, confidence = parsed
        group_key = (model_key, endpoint)
        agg = groups.get(group_key)
        if agg is None:
            agg = GroupAggregate(window_seconds, confidence_bins)
            groups[group_key] = agg
        agg.add_record(ts, status, latency_ms, confidence)

    sorted_models: Dict[str, Dict[str, Any]] = {}
    for (model_key, endpoint) in sorted(groups.keys(), key=lambda x: (x[0], x[1])):
        if model_key not in sorted_models:
            sorted_models[model_key] = {}
        sorted_models[model_key][endpoint] = groups[(model_key, endpoint)].finalize()

    return {
        "window_seconds": window_seconds,
        "malformed_records_discarded": malformed_count,
        "models": sorted_models,
    }

from collections import defaultdict
from pathlib import Path

INPUT_FILE = Path("access.log")
OUTPUT_FILE = Path("user_totals.csv")


def parse_line(line):
    """Parse a log line and return (username, bytes_transferred) or None if invalid."""
    parts = line.strip().split(",")
    if len(parts) != 3:
        return None

    _, username, byte_text = parts
    username = username.strip()
    byte_text = byte_text.strip()

    if not username:
        return None

    try:
        bytes_transferred = int(byte_text)
        if bytes_transferred < 0:
            return None
    except ValueError:
        return None

    return username, bytes_transferred


def aggregate_user_totals(input_path):
    """Read the log file and compute total bytes per user."""
    totals = defaultdict(int)

    with input_path.open("r", encoding="utf-8") as infile:
        for line in infile:
            parsed = parse_line(line)
            if parsed is None:
                continue  # Skip malformed lines silently
            username, bytes_transferred = parsed
            totals[username] += bytes_transferred

    return totals


def write_totals(output_path, totals):
    """Write aggregated totals sorted by descending bytes, then username."""
    sorted_items = sorted(totals.items(), key=lambda item: (-item[1], item[0]))

    with output_path.open("w", encoding="utf-8") as outfile:
        for username, total_bytes in sorted_items:
            outfile.write(f"{username},{total_bytes}\n")


def main():
    if not INPUT_FILE.exists():
        print(f"Error: input file '{INPUT_FILE}' does not exist.")
        return

    totals = aggregate_user_totals(INPUT_FILE)
    write_totals(OUTPUT_FILE, totals)


if __name__ == "__main__":
    main()
