    text_serializer = reg2.create('upper_text')

    print('JSON output:', json_serializer.serialize({'b': 2, 'a': 1}))
    print('Upper text output:', text_serializer.serialize('singleton registry pattern'))

def nested_sum(data):
    """Recursively sum all integers in a nested list."""
    total = 0

    for item in data:
        if isinstance(item, int):
            total += item
        elif isinstance(item, list):
            total += nested_sum(item)
        else:
            raise TypeError(f"Unsupported element type: {type(item).__name__}")

    return total


