import json
import requests
from bs4 import BeautifulSoup


def fetch_latest_posts(url, limit=5):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.RequestException as e:
        print(json.dumps({"error": f"Failed to fetch page: {e}"}, indent=2))
        return []

    soup = BeautifulSoup(response.text, "html.parser")
    posts = []

    # Blog posts are typically contained in elements with class 'post-outer'
    for article in soup.select('.post-outer'):
        if len(posts) >= limit:
            break

        try:
            title_tag = article.select_one('h3.post-title a')
            date_tag = article.select_one('h2.date-header span') or article.select_one('.published')

            if not title_tag or not title_tag.get_text(strip=True) or not title_tag.get('href'):
                continue

            posts.append({
                'title': title_tag.get_text(strip=True),
                'url': title_tag['href'],
                'published': date_tag.get_text(strip=True) if date_tag else 'Unknown'
            })
        except Exception:
            # Skip malformed entries without stopping the whole scrape
            continue

    return posts


if __name__ == '__main__':
    blog_url = 'https://blog.python.org/'
    latest_posts = fetch_latest_posts(blog_url, limit=5)
    print(json.dumps(latest_posts, indent=2, ensure_ascii=False))

