import json
import os
import re
from copy import deepcopy

_ENV_PATTERN = re.compile(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}")


def _expand_env(value):
    """Recursively expand ${VAR} placeholders in strings."""
    if isinstance(value, str):
        def replace(match):
            var_name = match.group(1)
            if var_name not in os.environ:
                raise ValueError(f"Missing environment variable: {var_name}")
            return os.environ[var_name]
        return _ENV_PATTERN.sub(replace, value)
    if isinstance(value, dict):
        return {k: _expand_env(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_expand_env(item) for item in value]
    return value


def load_and_validate_config(path: str) -> dict:
    """Load, normalize, and validate a JSON config file."""
    if not os.path.exists(path):
        raise FileNotFoundError(path)

    try:
        with open(path, "r", encoding="utf-8") as f:
            config = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON: {e.msg}") from e

    if not isinstance(config, dict):
        raise ValueError("Top-level configuration must be a JSON object")

    config = _expand_env(deepcopy(config))

    # Apply defaults
    config.setdefault("debug", False)
    config.setdefault("allowed_origins", [])
    if "database" in config:
        if not isinstance(config["database"], dict):
            raise ValueError("'database' must be an object")
        config["database"].setdefault("pool_size", 5)

    # Validate service section
    service = config.get("service")
    if not isinstance(service, dict):
        raise ValueError("Missing or invalid 'service' object")

    host = service.get("host")
    port = service.get("port")

    if not isinstance(host, str) or not host.strip():
        raise ValueError("'service.host' must be a non-empty string")
    if not isinstance(port, int) or isinstance(port, bool) or not (1 <= port <= 65535):
        raise ValueError("'service.port' must be an integer between 1 and 65535")

    if not isinstance(config["debug"], bool):
        raise ValueError("'debug' must be a boolean")
    if not isinstance(config["allowed_origins"], list) or not all(isinstance(x, str) for x in config["allowed_origins"]):
        raise ValueError("'allowed_origins' must be a list of strings")
    if "database" in config:
        pool_size = config["database"].get("pool_size")
        if not isinstance(pool_size, int) or isinstance(pool_size, bool) or pool_size <= 0:
            raise ValueError("'database.pool_size' must be a positive integer")

    return config

import json
from collections import Counter
from datetime import datetime


def parse_log_line(line):
    """Parse one log line into (timestamp, level, message) or return None if invalid."""
    parts = [part.strip() for part in line.split("|", 2)]
    if len(parts) != 3:
        return None

    timestamp_str, level, message = parts
    try:
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return None

    if not level or not message:
        return None

    return timestamp, level, message


def build_report(input_path, output_path):
    level_counts = Counter()
    total_valid = 0
    earliest = None
    latest = None
    sample_errors = []

    with open(input_path, "r", encoding="utf-8") as infile:
        for raw_line in infile:
            line = raw_line.strip()
            if not line:
                continue

            parsed = parse_log_line(line)
            if parsed is None:
                continue

            timestamp, level, message = parsed
            total_valid += 1
            level_counts[level] += 1

            if earliest is None or timestamp < earliest:
                earliest = timestamp
            if latest is None or timestamp > latest:
                latest = timestamp

            if level == "ERROR" and len(sample_errors) < 5:
                sample_errors.append(message)

    report = {
        "total_valid_lines": total_valid,
        "levels": dict(sorted(level_counts.items())),
        "earliest_timestamp": earliest.strftime("%Y-%m-%d %H:%M:%S") if earliest else None,
        "latest_timestamp": latest.strftime("%Y-%m-%d %H:%M:%S") if latest else None,
        "sample_errors": sample_errors,
    }

    with open(output_path, "w", encoding="utf-8") as outfile:
        json.dump(report, outfile, indent=2)


if __name__ == "__main__":
    build_report("server.log", "report.json")

