from time import perf_counter


def build_pipeline(middlewares, handler):
    """Compose middlewares around a final handler.

    Each middleware receives (context, next_step) and must call next_step(context)
    at most once. The returned function starts the chain.
    """
    def pipeline(context):
        def dispatch(index, ctx):
            if index == len(middlewares):
                return handler(ctx)

            called = False

            def next_step(next_ctx):
                nonlocal called
                if called:
                    raise RuntimeError(f"Middleware at index {index} called next_step more than once")
                called = True
                return dispatch(index + 1, next_ctx)

            return middlewares[index](ctx, next_step)

        return dispatch(0, context)

    return pipeline


# Example middlewares

def logging_middleware(context, next_step):
    context.setdefault("log", []).append("before:logging")
    result = next_step(context)
    context["log"].append("after:logging")
    return result


def timing_middleware(context, next_step):
    start = perf_counter()
    result = next_step(context)
    context["duration_ms"] = round((perf_counter() - start) * 1000, 3)
    return result


def auth_middleware(context, next_step):
    if "user" not in context or not context["user"]:
        raise ValueError("Missing required context['user']")
    context.setdefault("log", []).append("validated:user")
    return next_step(context)


# Final handler

def greet_handler(context):
    context.setdefault("log", []).append("handler")
    return f"Hello, {context['user']}!"


if __name__ == "__main__":
    pipeline = build_pipeline(
        [logging_middleware, timing_middleware, auth_middleware],
        greet_handler,
    )

    ctx = {"user": "Alice"}
    result = pipeline(ctx)

    print(result)
    print(ctx)

def call_limiter(max_calls):
    """Decorator factory that limits how many times a function can be called."""
    def decorator(func):
        call_count = 0  # Stored in the closure

        def wrapper(*args, **kwargs):
            nonlocal call_count
            if call_count >= max_calls:
                return "Call limit exceeded"

            call_count += 1
            return func(*args, **kwargs)

        return wrapper
    return decorator


@call_limiter(3)
def send_notification(user):
