class AppointmentRequest:
    VALID_STATUSES = {"Scheduled", "Canceled"}

    def __init__(self, patient_name, doctor_name, appointment_date, status="Scheduled"):
        self.patient_name = ""
        self.doctor_name = ""
        self.appointment_date = ""
        self.status = "Scheduled"

        self.schedule_appointment(patient_name, doctor_name, appointment_date, status)

    def _validate_name(self, name, field_name):
        if not isinstance(name, str) or not name.strip():
            raise ValueError(f"{field_name} cannot be empty.")
        return name.strip()

    def _validate_date(self, appointment_date):
        if not isinstance(appointment_date, str) or not appointment_date.strip():
            raise ValueError("Appointment date cannot be empty.")
        return appointment_date.strip()

    def _validate_status(self, status):
        if status not in self.VALID_STATUSES:
            raise ValueError('Status must be either "Scheduled" or "Canceled".')
        return status

    def schedule_appointment(self, patient_name, doctor_name, appointment_date, status="Scheduled"):
        self.patient_name = self._validate_name(patient_name, "Patient name")
        self.doctor_name = self._validate_name(doctor_name, "Doctor name")
        self.appointment_date = self._validate_date(appointment_date)
        self.status = self._validate_status(status)

    def cancel_appointment(self):
        self.status = "Canceled"

    def display_details(self):
        return (
            "Appointment Details\n"
            f"Patient Name     : {self.patient_name}\n"
            f"Doctor Name      : {self.doctor_name}\n"
            f"Appointment Date : {self.appointment_date}\n"
            f"Status           : {self.status}"
