class MaxQueue:
    """Queue implemented with two stacks, supporting O(1) amortized max()."""

    def __init__(self):
        # Each stack stores tuples: (value, current_max_at_this_level)
        self._in_stack = []
        self._out_stack = []

    def _push(self, stack, value):
        current_max = value if not stack else max(value, stack[-1][1])
        stack.append((value, current_max))

    def _transfer(self):
        # Move elements only when needed to preserve amortized O(1)
        while self._in_stack:
            value, _ = self._in_stack.pop()
            self._push(self._out_stack, value)

    def enqueue(self, x):
        self._push(self._in_stack, x)

    def dequeue(self):
        if not self._out_stack and not self._in_stack:
            raise IndexError('dequeue from empty queue')
        if not self._out_stack:
            self._transfer()
        return self._out_stack.pop()[0]

    def max(self):
        if not self._out_stack and not self._in_stack:
            raise IndexError('max from empty queue')
        if not self._out_stack:
            return self._in_stack[-1][1]
        if not self._in_stack:
            return self._out_stack[-1][1]
        return max(self._in_stack[-1][1], self._out_stack[-1][1])

    def __len__(self):
        return len(self._in_stack) + len(self._out_stack)


# Example usage
if __name__ == '__main__':
    q = MaxQueue()
    q.enqueue(3)
    q.enqueue(1)
    q.enqueue(5)
    print(q.max())      # 5
    print(q.dequeue())  # 3
    print(q.max())      # 5
    q.enqueue(2)
    print(q.dequeue())  # 1
    print(q.max())      # 5
    print(len(q))       # 2

def parse_config(text: str) -> dict:
    """Parse a mini INI-like configuration format into a nested dictionary."""

    def strip_inline_comment(line: str) -> str:
        in_quotes = False
        escaped = False
        result = []
        for ch in line:
            if escaped:
                result.append(ch)
                escaped = False
                continue
            if ch == '\\' and in_quotes:
                result.append(ch)
                escaped = True
                continue
            if ch == '"':
                in_quotes = not in_quotes
                result.append(ch)
                continue
            if ch == '#' and not in_quotes:
                break
            result.append(ch)
        return ''.join(result).strip()

    def parse_value(raw: str, line_no: int) -> str:
        raw = raw.strip()
        if not raw:
            return ''
        if raw.startswith('"'):
            if len(raw) < 2 or not raw.endswith('"'):
                raise ValueError(f'Line {line_no}: unterminated quoted value')
            inner = raw[1:-1]
            out = []
            i = 0
            while i < len(inner):
                ch = inner[i]
                if ch != '\\':
                    out.append(ch)
                    i += 1
                    continue
                if i + 1 >= len(inner):
                    raise ValueError(f'Line {line_no}: invalid escape sequence')
                nxt = inner[i + 1]
                mapping = {'n': '\n', 't': '\t', '"': '"', '\\': '\\'}
                if nxt not in mapping:
                    raise ValueError(f'Line {line_no}: invalid escape sequence')
                out.append(mapping[nxt])
                i += 2
            return ''.join(out)
        return raw

    config = {'__global__': {}}
    current_section = '__global__'

    for line_no, original_line in enumerate(text.splitlines(), start=1):
        line = strip_inline_comment(original_line)
        if not line:
            continue

        if line.startswith('['):
            if not line.endswith(']') or len(line) < 3:
                raise ValueError(f'Line {line_no}: malformed section header')
            section = line[1:-1].strip()
            if not section or '[' in section or ']' in section:
                raise ValueError(f'Line {line_no}: malformed section header')
            current_section = section
            config.setdefault(section, {})
            continue

        if '=' not in line:
            raise ValueError(f'Line {line_no}: invalid key-value line')

        key, value = line.split('=', 1)
        key = key.strip()
        if not key:
            raise ValueError(f'Line {line_no}: invalid key-value line')
        if key in config[current_section]:
            raise ValueError(f'Line {line_no}: duplicate key')

        config[current_section][key] = parse_value(value, line_no)

    return config

class TransactionError(Exception):
    """Base class for all transaction validation errors."""

    def __init__(self, message, transaction_id=None):
        super().__init__(message)
        self.transaction_id = transaction_id
        self.message = message

    def __str__(self):
        prefix = f"Transaction {self.transaction_id}: " if self.transaction_id is not None else ""
        return prefix + self.message


class InvalidCurrencyError(TransactionError):
    def __init__(self, currency, transaction_id=None):
        self.currency = currency
        super().__init__(f"unsupported currency '{currency}'", transaction_id)


class AmountLimitError(TransactionError):
    def __init__(self, amount, transaction_id=None):
        self.amount = amount
        super().__init__(f"invalid amount {amount}; must be between 0 and 10000", transaction_id)


class FraudSuspicionError(TransactionError):
    def __init__(self, country, transaction_id=None):
        self.country = country
        super().__init__(f"transaction blocked due to blacklisted country '{country}'", transaction_id)


ALLOWED_CURRENCIES = {"USD", "EUR", "GBP"}
BLACKLISTED_COUNTRIES = {"NK", "IR"}
MAX_AMOUNT = 10000


def validate_transaction(transaction: dict) -> None:
    """Validate a single transaction or raise a specific TransactionError."""
    tx_id = transaction.get("id")
    currency = transaction.get("currency")
    amount = transaction.get("amount")
    country = transaction.get("country")

    if currency not in ALLOWED_CURRENCIES:
        raise InvalidCurrencyError(currency, tx_id)

    if not isinstance(amount, (int, float)) or amount <= 0 or amount > MAX_AMOUNT:
        raise AmountLimitError(amount, tx_id)

    if country in BLACKLISTED_COUNTRIES:
        raise FraudSuspicionError(country, tx_id)


def process_transactions(transactions: list[dict]) -> dict:
    """Process transactions and summarize successes and errors by type."""
    summary = {
        "successful": 0,
        "errors": {}
    }

    for transaction in transactions:
        try:
            validate_transaction(transaction)
            summary["successful"] += 1
        except TransactionError as exc:
            error_type = type(exc).__name__
            summary["errors"].setdefault(error_type, []).append(str(exc))

    return summary


if __name__ == "__main__":
