def merge_sort(students):
    # Sort by score descending, then name ascending
    if len(students) <= 1:
        return students

    mid = len(students) // 2
    left = merge_sort(students[:mid])
    right = merge_sort(students[mid:])

    return merge(left, right)


def merge(left, right):
    merged = []
    i = j = 0

    while i < len(left) and j < len(right):
        left_item = left[i]
        right_item = right[j]

        if left_item[1] > right_item[1]:
            merged.append(left_item)
            i += 1
        elif left_item[1] < right_item[1]:
            merged.append(right_item)
            j += 1
        else:
            if left_item[0] <= right_item[0]:
                merged.append(left_item)
                i += 1
            else:
                merged.append(right_item)
                j += 1

    merged.extend(left[i:])
    merged.extend(right[j:])
    return merged


def binary_search_score(students, target_score):
    # Binary search on descending scores
    low, high = 0, len(students) - 1

    while low <= high:
        mid = (low + high) // 2
        score = students[mid][1]

        if score == target_score:
            return mid
        elif score < target_score:
            high = mid - 1
        else:
            low = mid + 1

    return -1


def main():
    students = [
        ("Liam", 88),
        ("Emma", 95),
        ("Noah", 72),
        ("Olivia", 88),
        ("Ava", 91),
        ("Sophia", 95),
        ("Mason", 67),
        ("Isabella", 79)
    ]

    sorted_students = merge_sort(students)
    print("Sorted students:")
    for i, student in enumerate(sorted_students):
        print(f"{i}: {student}")

    target_score = 88
    index = binary_search_score(sorted_students, target_score)
    print(f"\nSearch result for score {target_score}: {index}")


if __name__ == "__main__":
    main()

from __future__ import annotations

from collections import OrderedDict, defaultdict, deque
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import (
    Any,
    Deque,
    DefaultDict,
    Dict,
    Generator,
    Iterable,
    Iterator,
    List,
    Mapping,
    MutableMapping,
    Optional,
    Sequence,
    Set,
    Tuple,
    Union,
)
import heapq


TimestampLike = Union[int, float, str, datetime]


@dataclass(frozen=True)
class Event:
    event_id: str
    timestamp: float
    service: str
    event_type: str
    tenant_id: str
    region: str
    resource_id: str
    dependency_chain: Tuple[str, ...] = field(default_factory=tuple)
    payload: Mapping[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class FailureStepRule:
    service: Optional[str] = None
    event_type: Optional[str] = None

    def matches(self, event: Event) -> bool:
        if self.service is not None and event.service != self.service:
            return False
        if self.event_type is not None and event.event_type != self.event_type:
            return False
        return True


@dataclass(frozen=True)
class IncidentRule:
    sequence: Tuple[FailureStepRule, ...]
    threshold: int
    interval_seconds: float
    name: str = "cascading_failure"

    def __post_init__(self) -> None:
        if not self.sequence:
            raise ValueError("IncidentRule.sequence must not be empty")
        if self.threshold <= 0:
            raise ValueError("IncidentRule.threshold must be > 0")
        if self.interval_seconds <= 0:
            raise ValueError("IncidentRule.interval_seconds must be > 0")


@dataclass(frozen=True)
class IncidentWindow:
    rule_name: str
    tenant_id: str
    region: str
    resource_id: str
    dependency_chain: Tuple[str, ...]
    start_time: float
    end_time: float
    matched_event_ids: Tuple[str, ...]
    matched_services: Tuple[str, ...]
    matched_event_types: Tuple[str, ...]
    count: int


@dataclass
class PartialMatch:
    start_time: float
    end_time: float
    event_ids: Tuple[str, ...]
    services: Tuple[str, ...]
    event_types: Tuple[str, ...]
    next_index: int


@dataclass
class KeyState:
    partials_by_rule: Dict[int, Deque[PartialMatch]] = field(default_factory=dict)
    emitted_starts_by_rule: Dict[int, Set[float]] = field(default_factory=dict)
    last_seen_ts: float = float("-inf")


class LRUSet:
    def __init__(self, max_size: int) -> None:
        if max_size <= 0:
            raise ValueError("max_size must be > 0")
        self.max_size = max_size
        self._data: "OrderedDict[str, None]" = OrderedDict()

    def add(self, value: str) -> bool:
        if value in self._data:
            self._data.move_to_end(value)
            return False
        self._data[value] = None
        if len(self._data) > self.max_size:
            self._data.popitem(last=False)
        return True

    def __contains__(self, value: str) -> bool:
        return value in self._data

    def __len__(self) -> int:
        return len(self._data)


def _parse_timestamp(value: TimestampLike) -> Optional[float]:
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, datetime):
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        return value.timestamp()
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return None
        try:
            return float(text)
        except ValueError:
            pass
        try:
            if text.endswith("Z"):
                text = text[:-1] + "+00:00"
            dt = datetime.fromisoformat(text)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt.timestamp()
        except ValueError:
            return None
    return None


def _normalize_dependency_chain(value: Any) -> Tuple[str, ...]:
    if value is None:
        return ()
    if isinstance(value, (list, tuple)):
        return tuple(str(x) for x in value if x is not None)
    return (str(value),)


def _parse_event(record: Mapping[str, Any]) -> Optional[Event]:
    try:
        event_id = str(record["event_id"]).strip()
        service = str(record["service"]).strip()
        event_type = str(record["event_type"]).strip()
        tenant_id = str(record["tenant_id"]).strip()
        region = str(record["region"]).strip()
        resource_id = str(record["resource_id"]).strip()
        timestamp = _parse_timestamp(record["timestamp"])
        if not all([event_id, service, event_type, tenant_id, region, resource_id]):
            return None
        if timestamp is None:
            return None
        dependency_chain = _normalize_dependency_chain(record.get("dependency_chain"))
        payload = record.get("payload", {})
        if not isinstance(payload, Mapping):
            payload = {"raw_payload": payload}
        return Event(
            event_id=event_id,
            timestamp=timestamp,
            service=service,
            event_type=event_type,
            tenant_id=tenant_id,
            region=region,
            resource_id=resource_id,
            dependency_chain=dependency_chain,
            payload=payload,
        )
    except (KeyError, TypeError, ValueError):
        return None


def _make_key(event: Event) -> Tuple[str, str, str, Tuple[str, ...]]:
    return (event.tenant_id, event.region, event.resource_id, event.dependency_chain)


class CascadingFailureDetector:
    def __init__(
        self,
        rules: Sequence[IncidentRule],
        *,
        allowed_lateness_seconds: float = 30.0,
        dedup_cache_size: int = 100_000,
    ) -> None:
        if not rules:
            raise ValueError("At least one rule is required")
        if allowed_lateness_seconds < 0:
            raise ValueError("allowed_lateness_seconds must be >= 0")
        self.rules: Tuple[IncidentRule, ...] = tuple(rules)
        self.allowed_lateness_seconds = float(allowed_lateness_seconds)
        self.max_interval = max(rule.interval_seconds for rule in self.rules)
        self._dedup = LRUSet(dedup_cache_size)
        self._buffer: List[Tuple[float, int, Event]] = []
        self._seq = 0
        self._max_event_time = float("-inf")
        self._states: Dict[Tuple[str, str, str, Tuple[str, ...]], KeyState] = {}

    def process(
        self, events: Iterable[Mapping[str, Any]]
    ) -> Iterator[IncidentWindow]:
        for record in events:
            event = _parse_event(record)
            if event is None:
                continue
            if event.event_id in self._dedup:
                continue
            self._dedup.add(event.event_id)

            self._max_event_time = max(self._max_event_time, event.timestamp)
            heapq.heappush(self._buffer, (event.timestamp, self._seq, event))
            self._seq += 1

            watermark = self._max_event_time - self.allowed_lateness_seconds
            yield from self._drain_until(watermark)

        yield from self._drain_all()

    def _drain_until(self, watermark: float) -> Iterator[IncidentWindow]:
        while self._buffer and self._buffer[0][0] <= watermark:
            _, _, event = heapq.heappop(self._buffer)
            yield from self._process_event(event, watermark)
        self._cleanup_states(watermark)

    def _drain_all(self) -> Iterator[IncidentWindow]:
        final_watermark = float("inf")
        while self._buffer:
            _, _, event = heapq.heappop(self._buffer)
            yield from self._process_event(event, final_watermark)
        self._cleanup_states(final_watermark)

    def _process_event(self, event: Event, watermark: float) -> Iterator[IncidentWindow]:
        key = _make_key(event)
        state = self._states.get(key)
        if state is None:
            state = KeyState()
            self._states[key] = state
        state.last_seen_ts = max(state.last_seen_ts, event.timestamp)

        for rule_idx, rule in enumerate(self.rules):
            partials = state.partials_by_rule.setdefault(rule_idx, deque())
            emitted = state.emitted_starts_by_rule.setdefault(rule_idx, set())

            while partials and partials[0].start_time < event.timestamp - rule.interval_seconds:
                partials.popleft()

            new_partials: List[PartialMatch] = []

            first_step = rule.sequence[0]
            if first_step.matches(event):
                new_partials.append(
                    PartialMatch(
                        start_time=event.timestamp,
                        end_time=event.timestamp,
                        event_ids=(event.event_id,),
                        services=(event.service,),
                        event_types=(event.event_type,),
                        next_index=1,
                    )
                )

            for pm in list(partials):
                if pm.next_index >= len(rule.sequence):
                    continue
                if rule.sequence[pm.next_index].matches(event):
                    advanced = PartialMatch(
                        start_time=pm.start_time,
                        end_time=event.timestamp,
                        event_ids=pm.event_ids + (event.event_id,),
                        services=pm.services + (event.service,),
                        event_types=pm.event_types + (event.event_type,),
                        next_index=pm.next_index + 1,
                    )
                    if advanced.end_time - advanced.start_time <= rule.interval_seconds:
                        if advanced.next_index == len(rule.sequence):
                            if advanced.start_time not in emitted:
                                emitted.add(advanced.start_time)
                                yield IncidentWindow(
                                    rule_name=rule.name,
                                    tenant_id=event.tenant_id,
                                    region=event.region,
                                    resource_id=event.resource_id,
                                    dependency_chain=event.dependency_chain,
                                    start_time=advanced.start_time,
                                    end_time=advanced.end_time,
                                    matched_event_ids=advanced.event_ids,
                                    matched_services=advanced.services,
                                    matched_event_types=advanced.event_types,
                                    count=rule.threshold,
                                )
                        else:
                            new_partials.append(advanced)

            for pm in new_partials:
                partials.append(pm)

            self._compress_partials(partials, rule)

    def _compress_partials(self, partials: Deque[PartialMatch], rule: IncidentRule) -> None:
        if not partials:
            return
        best: Dict[Tuple[int, float], PartialMatch] = {}
        for pm in partials:
            key = (pm.next_index, pm.start_time)
            existing = best.get(key)
            if existing is None or pm.end_time < existing.end_time:
                best[key] = pm
        ordered = sorted(best.values(), key=lambda p: (p.start_time, p.end_time, p.next_index))
        partials.clear()
        partials.extend(ordered)

    def _cleanup_states(self, watermark: float) -> None:
        expire_before = watermark - self.max_interval
        dead_keys: List[Tuple[str, str, str, Tuple[str, ...]]] = []

        for key, state in self._states.items():
            for rule_idx, rule in enumerate(self.rules):
                partials = state.partials_by_rule.get(rule_idx)
                if partials is not None:
                    while partials and partials[0].start_time < watermark - rule.interval_seconds:
                        partials.popleft()
                    if not partials:
                        state.partials_by_rule.pop(rule_idx, None)

                emitted = state.emitted_starts_by_rule.get(rule_idx)
                if emitted:
                    state.emitted_starts_by_rule[rule_idx] = {
                        ts for ts in emitted if ts >= watermark - rule.interval_seconds
                    }
                    if not state.emitted_starts_by_rule[rule_idx]:
                        state.emitted_starts_by_rule.pop(rule_idx, None)

            if (
                state.last_seen_ts < expire_before
                and not state.partials_by_rule
                and not state.emitted_starts_by_rule
            ):
                dead_keys.append(key)

        for key in dead_keys:
            self._states.pop(key, None)


def detect_cascading_failures(
    events: Iterable[Mapping[str, Any]],
    rules: Sequence[IncidentRule],
    *,
    allowed_lateness_seconds: float = 30.0,
    dedup_cache_size: int = 100_000,
) -> Iterator[IncidentWindow]:
    detector = CascadingFailureDetector(
        rules,
        allowed_lateness_seconds=allowed_lateness_seconds,
        dedup_cache_size=dedup_cache_size,
    )
    return detector.process(events)


def build_rule(
    sequence: Sequence[Mapping[str, Optional[str]]],
    *,
    interval_seconds: float,
    threshold: Optional[int] = None,
    name: str = "cascading_failure",
) -> IncidentRule:
    steps = tuple(
        FailureStepRule(
            service=step.get("service"),
            event_type=step.get("event_type"),
        )
        for step in sequence
    )
    if threshold is None:
        threshold = len(steps)
    return IncidentRule(
        sequence=steps,
        threshold=threshold,
        interval_seconds=interval_seconds,
        name=name,
    )


