import re


def count_words(text):
    # Extract words made of letters, numbers, and apostrophes
    words = re.findall(r"[A-Za-z0-9']+", text.lower())

    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1

    return counts


def main():
    sentence = input("Enter a sentence: ")
    word_counts = count_words(sentence)

    if not word_counts:
        print("No words found.")
        return

    print("Word counts:")
    for word in sorted(word_counts):
        print(f"{word}: {word_counts[word]}")


if __name__ == "__main__":
    main()

from abc import ABC, abstractmethod


class ShippingStrategy(ABC):
    """Strategy interface for shipping cost calculation."""

    @abstractmethod
    def calculate(self, weight: float) -> float:
        pass


class StandardShipping(ShippingStrategy):
    def calculate(self, weight: float) -> float:
        return 5.0 + weight * 1.2


class ExpressShipping(ShippingStrategy):
    def calculate(self, weight: float) -> float:
        return 10.0 + weight * 2.0


class OvernightShipping(ShippingStrategy):
    def calculate(self, weight: float) -> float:
        return 20.0 + weight * 3.5


class ShippingContext:
    """Context that uses a selected shipping strategy."""

    def __init__(self, strategy: ShippingStrategy):
        self.strategy = strategy

    def set_strategy(self, strategy: ShippingStrategy) -> None:
        self.strategy = strategy

    def get_cost(self, weight: float) -> float:
        return self.strategy.calculate(weight)


if __name__ == "__main__":
    weight = 3.5
    context = ShippingContext(StandardShipping())

    strategies = [
        ("Standard", StandardShipping()),
        ("Express", ExpressShipping()),
        ("Overnight", OvernightShipping()),
    ]

    for name, strategy in strategies:
        context.set_strategy(strategy)
        cost = context.get_cost(weight)
        print(f"{name} shipping for {weight} kg: ${cost:.2f}")

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class AppConfig:
    host: str
    port: int
    debug: bool = False
    tags: tuple[str, ...] = ()

    @classmethod
    def from_dict(cls, data: dict[str, object]) -> "AppConfig":
        allowed_keys = {"host", "port", "debug", "tags"}
        unknown_keys = set(data) - allowed_keys
        if unknown_keys:
            raise ValueError(f"Unknown keys: {', '.join(sorted(unknown_keys))}")

        if "host" not in data:
            raise ValueError("Missing required field: host")
        if "port" not in data:
            raise ValueError("Missing required field: port")

        host = data["host"]
        if not isinstance(host, str) or not host:
            raise ValueError("Field 'host' must be a non-empty string")

        port = data["port"]
        if not isinstance(port, int) or isinstance(port, bool):
            raise ValueError("Field 'port' must be an integer")
        if not (1 <= port <= 65535):
            raise ValueError("Field 'port' must be between 1 and 65535")

        debug = data.get("debug", False)
        if not isinstance(debug, bool):
            raise ValueError("Field 'debug' must be a boolean")

        raw_tags = data.get("tags", ())
        if not isinstance(raw_tags, (list, tuple)):
            raise ValueError("Field 'tags' must be a list or tuple of strings")
        if not all(isinstance(tag, str) for tag in raw_tags):
            raise ValueError("Field 'tags' must contain only strings")
        tags = tuple(raw_tags)

        return cls(host=host, port=port, debug=debug, tags=tags)

    def as_connection_url(self) -> str:
        scheme = "https" if self.debug else "http"
        return f"{scheme}://{self.host}:{self.port}"

from abc import ABC, abstractmethod


class PaymentStrategy(ABC):
    """Abstract strategy for different payment methods."""

    @abstractmethod
    def pay(self, amount):
        pass


class CreditCardPayment(PaymentStrategy):
