import json
import sys
from collections import defaultdict

import msgpack


def convert_ndjson_to_grouped_msgpack(input_path, output_path):
    grouped = defaultdict(list)

    with open(input_path, 'r', encoding='utf-8') as f:
        for line_number, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue

            try:
                record = json.loads(line)
            except json.JSONDecodeError:
                # Skip malformed JSON lines
                continue

            if not isinstance(record, dict):
                continue

            category = record.get('category')
            record_id = record.get('id')

            if not isinstance(category, str) or not category.strip():
                continue
            if not isinstance(record_id, int):
                continue
            if 'payload' not in record:
                continue

            grouped[category].append({
                'id': record_id,
                'payload': record['payload']
            })

    # Convert defaultdict to regular dict for serialization clarity
    result = dict(grouped)

    with open(output_path, 'wb') as f:
        msgpack.pack(result, f, use_bin_type=True)


def main():
    if len(sys.argv) != 3:
        print('Usage: python script.py input.ndjson output.msgpack')
        sys.exit(1)

    input_path, output_path = sys.argv[1], sys.argv[2]
    convert_ndjson_to_grouped_msgpack(input_path, output_path)


if __name__ == '__main__':
    main()

