    def __post_init__(self) -> None:
        if not isinstance(self.name, str) or not self.name.strip():
            raise ValueError("name must be a non-empty string")

        if not isinstance(self.patient_id, str) or not self.patient_id.strip():
            raise ValueError("patient_id must be a non-empty string")

        if not isinstance(self.age, int) or self.age < 0:
            raise ValueError("age must be a non-negative integer")

        if not isinstance(self.current_medications, list):
            raise ValueError("current_medications must be a list of strings")

        cleaned_medications = []
        for medication in self.current_medications:
            if not isinstance(medication, str) or not medication.strip():
                raise ValueError("each medication must be a non-empty string")
            cleaned_medications.append(medication.strip())

        self.name = self.name.strip()
        self.patient_id = self.patient_id.strip()
        self.current_medications = cleaned_medications


def get_senior_patients_on_medication(
    patient_records: List[PatientRecord], medication_name: str
) -> List[str]:
    if not isinstance(patient_records, list):
        raise ValueError("patient_records must be a list of PatientRecord objects")

    if not isinstance(medication_name, str) or not medication_name.strip():
        raise ValueError("medication_name must be a non-empty string")

    for record in patient_records:
        if not isinstance(record, PatientRecord):
            raise ValueError("all items in patient_records must be PatientRecord objects")

    medication_name = medication_name.strip().lower()
    matching_patient_names = []

    for record in patient_records:
        medications_lower = [med.lower() for med in record.current_medications]
        if record.age >= 65 and medication_name in medications_lower:
