from concurrent.futures import ThreadPoolExecutor, as_completed


def chunked(items, size):
    """Yield successive chunks from items of length size."""
    for i in range(0, len(items), size):
        yield items[i:i + size]


def process_job(job):
    """Process a single job and return a normalized result."""
    job_id = job.get('id')
    try:
        if job.get('fail'):
            raise RuntimeError('job marked to fail')

        records = job.get('records')
        if not isinstance(records, list) or not all(isinstance(x, int) for x in records):
            raise ValueError('records must be a list of integers')

        total = sum(x * x for x in records)
        return {
            'id': job_id,
            'status': 'success',
            'result': total,
        }
    except Exception as exc:
        return {
            'id': job_id,
            'status': 'failed',
            'error': str(exc),
        }


def run_pipeline(jobs, batch_size=3, max_workers=4):
    """Process jobs in batches with per-batch parallel execution."""
    indexed_results = {}

    for batch in chunked(list(enumerate(jobs)), batch_size):
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_to_index = {
                executor.submit(process_job, job): index
                for index, job in batch
            }

            for future in as_completed(future_to_index):
                index = future_to_index[future]
                try:
                    indexed_results[index] = future.result()
                except Exception as exc:
                    # Defensive fallback; process_job already handles most errors.
                    indexed_results[index] = {
                        'id': jobs[index].get('id'),
                        'status': 'failed',
                        'error': f'unexpected executor error: {exc}',
                    }

    ordered_results = [indexed_results[i] for i in range(len(jobs))]
    succeeded = sum(1 for r in ordered_results if r['status'] == 'success')
    failed = len(ordered_results) - succeeded

    return {
        'total_jobs': len(jobs),
        'succeeded': succeeded,
        'failed': failed,
        'results': ordered_results,
    }


if __name__ == '__main__':
    sample_jobs = [
        {'id': 'a1', 'records': [1, 2, 3]},
        {'id': 'b2', 'records': [4, 5], 'fail': True},
        {'id': 'c3', 'records': [2, 2, 2]},
        {'id': 'd4', 'records': 'bad-data'},
        {'id': 'e5', 'records': [7, 1]},
    ]

    summary = run_pipeline(sample_jobs, batch_size=2, max_workers=3)
    from pprint import pprint
