# In-memory event store
EVENTS = []
REQUIRED_FIELDS = {"event_type", "timestamp", "data"}


@app.post('/webhook')
def webhook_handler():
    # Ensure the request contains JSON
    if not request.is_json:
        return jsonify({"error": "Request must be application/json"}), 400

    payload = request.get_json(silent=True)
    if payload is None:
        return jsonify({"error": "Invalid JSON body"}), 400

    # Validate required fields
    missing = sorted(REQUIRED_FIELDS - payload.keys())
    if missing:
        return jsonify({"error": "Missing required fields", "missing": missing}), 422

    event = {
        "event_type": payload["event_type"],
        "timestamp": payload["timestamp"],
        "data": payload["data"],
    }
    EVENTS.append(event)

    return jsonify({"status": "accepted", "stored_events": len(EVENTS)}), 200


@app.get('/events')
def list_events():
    return jsonify({"events": EVENTS}), 200


