from collections import defaultdict


class EventBus:
    def __init__(self):
        self._exact_subscribers = defaultdict(list)
        self._wildcard_subscribers = []  # (prefix, callback)

    def subscribe(self, topic, callback):
        """Subscribe a callback to an exact topic or a wildcard prefix like 'user.*'."""
        if topic.endswith("*"):
            prefix = topic[:-1]
            self._wildcard_subscribers.append((prefix, callback))
        else:
            self._exact_subscribers[topic].append(callback)

    def unsubscribe(self, topic, callback):
        """Remove a previously registered callback."""
        if topic.endswith("*"):
            prefix = topic[:-1]
            self._wildcard_subscribers = [
                (p, cb) for p, cb in self._wildcard_subscribers
                if not (p == prefix and cb == callback)
            ]
        else:
            self._exact_subscribers[topic] = [
                cb for cb in self._exact_subscribers[topic] if cb != callback
            ]

    def publish(self, topic, data):
        """Notify all matching subscribers."""
        for callback in self._exact_subscribers[topic]:
            callback(topic, data)
        for prefix, callback in self._wildcard_subscribers:
            if topic.startswith(prefix):
                callback(topic, data)


