import json
from typing import Iterable, Callable, Any, Dict, List


def process_batches(lines: Iterable[str], batch_size: int, transform: Callable[[Dict[str, Any]], Any], max_retries: int = 2) -> Dict[str, Any]:
    if batch_size <= 0:
        raise ValueError("batch_size must be greater than 0")

    summary = {
        "total_lines": 0,
        "parsed_records": 0,
        "successful_records": 0,
        "failed_records": 0,
        "batches_processed": 0,
        "results": [],
    }

    batch: List[Dict[str, Any]] = []

    def flush_batch() -> None:
        nonlocal batch
        if not batch:
            return

        summary["batches_processed"] += 1
        for record in batch:
            success = False
            for _ in range(max_retries + 1):
                try:
                    summary["results"].append(transform(record))
                    summary["successful_records"] += 1
                    success = True
                    break
                except Exception:
                    pass

            if not success:
                summary["failed_records"] += 1

        batch = []

    for line in lines:
        summary["total_lines"] += 1
        try:
            record = json.loads(line)
            if not isinstance(record, dict):
                raise ValueError("Record must be a JSON object")
            summary["parsed_records"] += 1
            batch.append(record)
        except Exception:
            summary["failed_records"] += 1
            continue

        if len(batch) >= batch_size:
            flush_batch()

    flush_batch()
    return summary


