    ]

    def transform(record: Dict[str, Any]) -> Dict[str, Any]:
        if record["value"] < 0:
            raise ValueError("Negative values are not allowed")
        return {"id": record["id"], "processed_value": record["value"] * 2}

    result = process_batches(sample_lines, batch_size=2, transform=transform, max_retries=2)
    print(json.dumps(result, indent=2))

class LazyLogPipeline:
    def __init__(self, source):
        self._source = source

    def __iter__(self):
        # Delegate iteration to the wrapped iterable/generator.
        yield from self._source

    def map(self, func):
        def gen():
            for item in self:
                yield func(item)
        return LazyLogPipeline(gen())

    def filter(self, predicate):
        def gen():
            for item in self:
                if predicate(item):
                    yield item
        return LazyLogPipeline(gen())

    def take(self, n):
        def gen():
            count = 0
            for item in self:
                if count >= n:
                    break
                yield item
                count += 1
        return LazyLogPipeline(gen())

    def batch(self, size):
        if size <= 0:
            raise ValueError('batch size must be positive')

        def gen():
            bucket = []
            for item in self:
                bucket.append(item)
                if len(bucket) == size:
                    yield bucket
                    bucket = []
            if bucket:
                yield bucket
        return LazyLogPipeline(gen())

    def first(self, default=None):
        for item in self:
            return item
        return default


