class TrafficLight:
    """Simple traffic light state machine."""

    # Define valid transitions for each state
    TRANSITIONS = {
        "RED": "GREEN",
        "GREEN": "YELLOW",
        "YELLOW": "RED",
    }

    def __init__(self):
        self.state = "RED"

    def next_state(self):
        """Advance to the next state in the cycle."""
        self.state = self.TRANSITIONS[self.state]
        return self.state

    def can_go(self):
        """Return True only when cars are allowed to go."""
        return self.state == "GREEN"

    def __str__(self):
        return f"TrafficLight(state={self.state})"


def main():
