class MaxStack:
    def __init__(self):
        # Each item stores: (value, max_up_to_here)
        self._data = []

    def push(self, x):
        current_max = x if not self._data else max(x, self._data[-1][1])
        self._data.append((x, current_max))

    def pop(self):
        if not self._data:
            return "EMPTY"
        return self._data.pop()[0]

    def max(self):
        if not self._data:
            return "EMPTY"
        return self._data[-1][1]

    def __len__(self):
        return len(self._data)


class QueueWithTwoStacks:
    def __init__(self):
        self._in = []
        self._out = []

    def enqueue(self, x):
        self._in.append(x)

    def _shift(self):
        if not self._out:
            while self._in:
                self._out.append(self._in.pop())

    def dequeue(self):
        self._shift()
        if not self._out:
            return "EMPTY"
        return self._out.pop()

    def front(self):
        self._shift()
        if not self._out:
            return "EMPTY"
        return self._out[-1]

    def __len__(self):
        return len(self._in) + len(self._out)


class MaxQueueStackProcessor:
    def __init__(self):
        self.stack = MaxStack()
        self.queue = QueueWithTwoStacks()

    def process(self, commands):
        outputs = []

        for command in commands:
            parts = command.split()
            op = parts[0]

            if op == "PUSH_STACK":
                self.stack.push(int(parts[1]))
            elif op == "POP_STACK":
                outputs.append(self.stack.pop())
            elif op == "MAX_STACK":
                outputs.append(self.stack.max())
            elif op == "ENQUEUE":
                self.queue.enqueue(int(parts[1]))
            elif op == "DEQUEUE":
                outputs.append(self.queue.dequeue())
            elif op == "FRONT_QUEUE":
                outputs.append(self.queue.front())
            elif op == "SIZE":
                outputs.append(len(self.stack) + len(self.queue))
            else:
                raise ValueError(f"Unknown command: {command}")

        return outputs


