from urllib.parse import urlsplit, urlunsplit, parse_qsl, urlencode


def normalize_tracking_url(url: str, extra_remove: set[str] | None = None) -> str:
    """Return a normalized URL with tracking query parameters removed."""
    parts = urlsplit(url)

    if not parts.scheme or not parts.hostname:
        raise ValueError("URL must include both scheme and hostname")

    scheme = parts.scheme.lower()
    hostname = parts.hostname.lower()
    port = parts.port

    # Drop default ports.
    if (scheme == "http" and port == 80) or (scheme == "https" and port == 443):
        port = None

    # Rebuild netloc, preserving userinfo if present.
    userinfo = ""
    if parts.username is not None:
        userinfo = parts.username
        if parts.password is not None:
            userinfo += f":{parts.password}"
        userinfo += "@"

    netloc = f"{userinfo}{hostname}"
    if port is not None:
        netloc += f":{port}"

    path = parts.path or "/"

    # Parse decoded query pairs, filter tracking params, then sort deterministically.
    base_remove = {"fbclid", "gclid", "mc_cid", "mc_eid"}
    extra_remove = {x.lower() for x in (extra_remove or set())}

    filtered = []
    for key, value in parse_qsl(parts.query, keep_blank_values=True):
        key_lower = key.lower()
        if key_lower.startswith("utm_") or key_lower in base_remove or key_lower in extra_remove:
            continue
        filtered.append((key, value))

    filtered.sort(key=lambda kv: (kv[0], kv[1]))
    query = urlencode(filtered, doseq=True)

    return urlunsplit((scheme, netloc, path, query, parts.fragment))


if __name__ == "__main__":
    examples = [
        "HTTPS://Example.COM:443/shop?id=2&utm_source=newsletter&b=2&a=1",
        "http://user:pass@Example.com:80?fbclid=abc&item=book&item=pen",
