        "https://example.com?x=1;y=2&gclid=zzz",
    ]

    for u in examples:
        print(normalize_tracking_url(u, extra_remove={"name"}))

def chunk_orders(orders, batch_size):
    """Split the orders into smaller batches."""
    for i in range(0, len(orders), batch_size):
        yield orders[i:i + batch_size]


def process_batch(batch):
    """Process one batch of orders and return processed results."""
    processed = []
    for order in batch:
        total_cost = order['item_count'] * order['price_per_item']
        processed.append({
            'id': order['id'],
            'customer': order['customer'],
            'total_cost': total_cost
        })
    return processed


