from dataclasses import dataclass, field
from typing import List


@dataclass
class Book:
    title: str
    author: str
    year: int
    available_copies: int


@dataclass
class Library:
    books: List[Book] = field(default_factory=list)

    def add_book(self, book: Book) -> None:
        """Add a new book to the library."""
        self.books.append(book)

    def borrow_book(self, title: str) -> bool:
        """Borrow a book if it exists and has available copies."""
        for book in self.books:
            if book.title == title and book.available_copies > 0:
                book.available_copies -= 1
                return True
        return False

    def return_book(self, title: str) -> bool:
        """Return a book if it exists in the library."""
        for book in self.books:
            if book.title == title:
                book.available_copies += 1
                return True
        return False

    def available_books_after(self, year: int) -> List[Book]:
        """List books published after the given year with at least one available copy."""
        return [
            book for book in self.books
            if book.year > year and book.available_copies > 0
        ]


def main() -> None:
    library = Library()

    library.add_book(Book("Clean Code", "Robert C. Martin", 2008, 3))
    library.add_book(Book("The Pragmatic Programmer", "Andrew Hunt", 1999, 2))
    library.add_book(Book("Fluent Python", "Luciano Ramalho", 2015, 1))

    print(library.borrow_book("Fluent Python"))  # True
    print(library.borrow_book("Fluent Python"))  # False
    print(library.return_book("Fluent Python"))  # True

    recent_books = library.available_books_after(2000)
    for book in recent_books:
        print(f"{book.title} by {book.author} ({book.year}) - {book.available_copies} copies")


if __name__ == "__main__":
