    def __init__(self):
        self.children = {}
        self.word_count = 0      # Number of times this exact word was inserted
        self.subtree_count = 0   # Total word occurrences in this subtree


class PrefixDictionary:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        node.subtree_count += 1
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            node.subtree_count += 1
        node.word_count += 1

    def delete(self, word: str) -> bool:
        # First verify the word exists and store the path.
        node = self.root
        path = [self.root]
        chars = []
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
            path.append(node)
            chars.append(ch)
        if node.word_count == 0:
            return False

        # Decrement counts along the path.
        node.word_count -= 1
        for n in path:
            n.subtree_count -= 1

        # Prune unused nodes from bottom to top.
        parent = self.root
        for i, ch in enumerate(chars):
            child = parent.children[ch]
            if child.subtree_count == 0:
                del parent.children[ch]
                break
            parent = child
        return True

    def count_prefix(self, prefix: str) -> int:
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return 0
            node = node.children[ch]
        return node.subtree_count

    def autocomplete(self, prefix: str, limit: int):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]

        results = []

        def dfs(curr: TrieNode, path: list):
            if curr.word_count > 0:
                results.append((prefix + ''.join(path), curr.word_count))
            for ch in sorted(curr.children):
                path.append(ch)
                dfs(curr.children[ch], path)
                path.pop()

        dfs(node, [])
        results.sort(key=lambda x: (-x[1], x[0]))
        return [word for word, _ in results[:limit]]


# Example usage:
if __name__ == '__main__':
    pd = PrefixDictionary()
    for word in ['app', 'apple', 'app', 'apply', 'apt', 'apple']:
        pd.insert(word)

    print(pd.count_prefix('app'))       # 5
    print(pd.autocomplete('app', 3))    # ['app', 'apple', 'apply']
    pd.delete('app')
    print(pd.autocomplete('app', 3))    # ['apple', 'app', 'apply']

class StateMachine:
    def __init__(self, initial_state, context=None):
        self.state = initial_state
        self.context = context or {}
        self._transitions = {}

    def add_transition(self, source, event, target, guard=None, action=None):
        self._transitions[(source, event)] = {
            'target': target,
            'guard': guard,
            'action': action,
        }

    def trigger(self, event):
        key = (self.state, event)
        if key not in self._transitions:
            raise ValueError(f"Invalid transition: {self.state} --{event}-->")

        transition = self._transitions[key]
        guard = transition['guard']
        if guard is not None and not guard(self.context):
            raise ValueError(f"Guard blocked transition: {self.state} --{event}-->")

        self.state = transition['target']
        action = transition['action']
        if action is not None:
            action(self.context, self.state)
        return self.state

    def run(self, events):
        visited = [self.state]
        for event in events:
            visited.append(self.trigger(event))
        return visited


def inc_attempts(ctx, _state):
    ctx['attempts'] = ctx.get('attempts', 0) + 1


def reset_attempts(ctx, _state):
    ctx['attempts'] = 0


def can_try(ctx):
    return ctx.get('attempts', 0) < 3


def fail_to_locked(ctx):
    return ctx.get('attempts', 0) < 2


def fail_to_blocked(ctx):
    return ctx.get('attempts', 0) == 2


if __name__ == '__main__':
    sm = StateMachine('LOCKED', {'attempts': 0})

    # Authentication workflow transitions
    sm.add_transition('LOCKED', 'enter_pin', 'AUTHENTICATING', guard=can_try)
    sm.add_transition('AUTHENTICATING', 'success', 'AUTHENTICATED')
    sm.add_transition('AUTHENTICATING', 'fail', 'LOCKED', guard=fail_to_locked, action=inc_attempts)
    sm.add_transition('AUTHENTICATING', 'fail_last', 'BLOCKED', guard=fail_to_blocked, action=inc_attempts)
    sm.add_transition('AUTHENTICATED', 'logout', 'LOCKED', action=reset_attempts)

    # Example sequence: two failed attempts, then block on third
    events = [
        'enter_pin', 'fail',
        'enter_pin', 'fail',
        'enter_pin', 'fail_last'
    ]
    print(sm.run(events))
    print(sm.context)

    # Fresh machine showing successful login and logout
    sm2 = StateMachine('LOCKED', {'attempts': 0})
    sm2.add_transition('LOCKED', 'enter_pin', 'AUTHENTICATING', guard=can_try)
    sm2.add_transition('AUTHENTICATING', 'success', 'AUTHENTICATED')
    sm2.add_transition('AUTHENTICATING', 'fail', 'LOCKED', guard=fail_to_locked, action=inc_attempts)
    sm2.add_transition('AUTHENTICATING', 'fail_last', 'BLOCKED', guard=fail_to_blocked, action=inc_attempts)
    sm2.add_transition('AUTHENTICATED', 'logout', 'LOCKED', action=reset_attempts)

    print(sm2.run(['enter_pin', 'success', 'logout']))
    print(sm2.context)

import time
from functools import wraps


def retry_with_backoff(max_attempts, exceptions, base_delay=0.1, factor=2.0):
    """Decorator factory that retries a function with exponential backoff.

    Tracks cumulative statistics for each decorated function using a closure.
    """
    if max_attempts < 1:
        raise ValueError("max_attempts must be at least 1")
    if base_delay < 0:
        raise ValueError("base_delay must be non-negative")
    if factor < 1:
        raise ValueError("factor must be at least 1")

    def decorator(func):
        # Closure-backed stats, unique per decorated function.
        stats = {
            "total_calls": 0,
            "successful_calls": 0,
            "failed_calls": 0,
            "total_retries": 0,
        }

        @wraps(func)
        def wrapper(*args, **kwargs):
            stats["total_calls"] += 1
            delay = base_delay
            last_error = None

            for attempt in range(1, max_attempts + 1):
                try:
                    result = func(*args, **kwargs)
                    stats["successful_calls"] += 1
                    return result
                except exceptions as exc:
                    last_error = exc
                    if attempt == max_attempts:
                        stats["failed_calls"] += 1
                        raise

                    stats["total_retries"] += 1
                    time.sleep(delay)
                    delay *= factor

            # Defensive fallback; normally unreachable because of return/raise above.
            if last_error is not None:
                stats["failed_calls"] += 1
                raise last_error

        def get_stats():
            # Return a copy so callers cannot mutate internal closure state.
            return dict(stats)

        wrapper.get_stats = get_stats
        return wrapper

    return decorator


# Example usage:
if __name__ == "__main__":
    state = {"count": 0}

    @retry_with_backoff(max_attempts=4, exceptions=(ValueError,), base_delay=0.01, factor=2)
    def flaky_task():
        state["count"] += 1
        if state["count"] < 3:
            raise ValueError("Temporary failure")
        return "done"

    print(flaky_task())
    print(flaky_task.get_stats())

import re
import smtplib
from email.message import EmailMessage
from typing import List, Dict, Any


EMAIL_RE = re.compile(r'^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$')


def is_valid_email(address: str) -> bool:
    """Return True if the email address looks valid."""
    return bool(EMAIL_RE.fullmatch(address or ""))



def send_bulk_email(
    smtp_host: str,
    smtp_port: int,
    username: str,
    password: str,
    sender: str,
    recipients: List[str],
    subject: str,
    body: str,
    use_tls: bool = True,
) -> Dict[str, Any]:
    """Send an email to multiple recipients and return a delivery summary."""
    if not is_valid_email(sender):
        raise ValueError(f"Invalid sender email address: {sender}")

    valid_recipients = []
    summary = {
        "sent": 0,
        "failed": 0,
        "skipped": 0,
        "results": {}
    }

    # Filter invalid recipient addresses first.
    for recipient in recipients:
        if is_valid_email(recipient):
            valid_recipients.append(recipient)
        else:
            summary["skipped"] += 1
            summary["results"][recipient] = {
                "status": "skipped",
                "error": "Invalid email address"
            }

    if not valid_recipients:
        raise ValueError("No valid recipients to send to.")

    # Open one SMTP session and send messages one by one.
    with smtplib.SMTP(smtp_host, smtp_port, timeout=10) as server:
        server.ehlo()
        if use_tls:
            server.starttls()
            server.ehlo()
        if username:
            server.login(username, password)

        for recipient in valid_recipients:
            msg = EmailMessage()
            msg["From"] = sender
            msg["To"] = recipient
            msg["Subject"] = subject
            msg.set_content(body)

            try:
                server.send_message(msg)
                summary["sent"] += 1
                summary["results"][recipient] = {
                    "status": "sent",
                    "error": None
                }
            except smtplib.SMTPException as exc:
                summary["failed"] += 1
                summary["results"][recipient] = {
                    "status": "failed",
                    "error": str(exc)
                }

    return summary


if __name__ == "__main__":
    # Example usage; replace with real SMTP credentials before running.
    report = send_bulk_email(
        smtp_host="smtp.example.com",
        smtp_port=587,
        username="user@example.com",
        password="secret",
        sender="user@example.com",
        recipients=["alice@example.com", "bad-address", "bob@example.com"],
        subject="System Notification",
        body="This is a test email sent individually to each recipient.",
        use_tls=True,
    )
    print(report)

from __future__ import annotations

import csv
import io
from dataclasses import dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Sequence, TextIO, Union


class EHRIngestionError(Exception):
    """Base exception for EHR ingestion errors."""


class FileAccessError(EHRIngestionError):
    """Raised when a CSV file cannot be safely accessed."""


class ValidationError(EHRIngestionError):
    """Raised for record validation issues."""


class PersistenceError(EHRIngestionError):
    """Raised when persistence fails."""


@dataclass(frozen=True)
class EncounterRecord:
    patient_id: str
    encounter_id: str
    provider_id: str
    diagnosis_codes: tuple[str, ...]
    admission_timestamp_utc: datetime
    discharge_timestamp_utc: datetime
    source_row_number: int
    raw_data: Dict[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class AuditRecordDecision:
    encounter_id: str
    patient_id: Optional[str]
    status: str
    reasons: tuple[str, ...]


@dataclass(frozen=True)
class AuditEntry:
    imported_by: str
    imported_at_utc: datetime
    source_name: str
    accepted_count: int
    rejected_count: int
    decisions: tuple[AuditRecordDecision, ...]


class InMemoryEncounterRepository:
    def __init__(self) -> None:
        self._records_by_encounter_id: Dict[str, EncounterRecord] = {}

    def exists(self, encounter_id: str) -> bool:
        return encounter_id in self._records_by_encounter_id

    def save_many(self, records: Sequence[EncounterRecord]) -> None:
        for record in records:
            if self.exists(record.encounter_id):
                raise PersistenceError(
                    f"Encounter '{record.encounter_id}' already exists in repository."
                )
        for record in records:
            self._records_by_encounter_id[record.encounter_id] = record

    def get(self, encounter_id: str) -> Optional[EncounterRecord]:
        return self._records_by_encounter_id.get(encounter_id)

    def list_all(self) -> List[EncounterRecord]:
        return list(self._records_by_encounter_id.values())


class InMemoryAuditRepository:
    def __init__(self) -> None:
        self._entries: List[AuditEntry] = []

    def append(self, entry: AuditEntry) -> None:
        self._entries.append(entry)

    def list_all(self) -> List[AuditEntry]:
        return list(self._entries)


class SafeCSVReader:
    def __init__(self, source: Union[str, Path, TextIO]) -> None:
        self._source = source
        self._handle: Optional[TextIO] = None
        self._should_close = False
        self.source_name = self._derive_source_name(source)

    @staticmethod
    def _derive_source_name(source: Union[str, Path, TextIO]) -> str:
        if hasattr(source, "name"):
            return str(getattr(source, "name"))
        return str(source)

    def __enter__(self) -> TextIO:
        try:
            if hasattr(self._source, "read"):
                self._handle = self._source  # type: ignore[assignment]
                self._should_close = False
            else:
                self._handle = open(self._source, mode="r", encoding="utf-8", newline="")
                self._should_close = True
            return self._handle
        except OSError as exc:
            raise FileAccessError(f"Unable to access CSV source '{self.source_name}'.") from exc

    def __exit__(self, exc_type, exc, tb) -> bool:
        if self._handle is not None and self._should_close:
            self._handle.close()
        return False


class AuditSession:
    def __init__(self, audit_repository: InMemoryAuditRepository, imported_by: str, source_name: str) -> None:
        self._audit_repository = audit_repository
        self._imported_by = imported_by
        self._source_name = source_name
        self._started_at = datetime.now(timezone.utc)
        self._decisions: List[AuditRecordDecision] = []
        self._committed = False

    def record_accept(self, encounter_id: str, patient_id: Optional[str] = None) -> None:
        self._decisions.append(
            AuditRecordDecision(
                encounter_id=encounter_id,
                patient_id=patient_id,
                status="ACCEPTED",
                reasons=(),
            )
        )

    def record_reject(
        self,
        encounter_id: str,
        reasons: Iterable[str],
        patient_id: Optional[str] = None,
    ) -> None:
        self._decisions.append(
            AuditRecordDecision(
                encounter_id=encounter_id,
                patient_id=patient_id,
                status="REJECTED",
                reasons=tuple(reasons),
            )
        )

    def commit(self) -> AuditEntry:
        accepted_count = sum(1 for d in self._decisions if d.status == "ACCEPTED")
        rejected_count = sum(1 for d in self._decisions if d.status == "REJECTED")
        entry = AuditEntry(
            imported_by=self._imported_by,
            imported_at_utc=self._started_at,
            source_name=self._source_name,
            accepted_count=accepted_count,
            rejected_count=rejected_count,
            decisions=tuple(self._decisions),
        )
        self._audit_repository.append(entry)
        self._committed = True
        return entry

    def __enter__(self) -> AuditSession:
        return self

    def __exit__(self, exc_type, exc, tb) -> bool:
        if exc_type is None and not self._committed:
            self.commit()
        return False


class EHRIngestionManager:
    REQUIRED_FIELDS: tuple[str, ...] = (
        "patient_id",
        "encounter_id",
        "provider_id",
        "diagnosis_codes",
        "admission_timestamp",
        "discharge_timestamp",
    )

    def __init__(
        self,
        encounter_repository: Optional[InMemoryEncounterRepository] = None,
        audit_repository: Optional[InMemoryAuditRepository] = None,
    ) -> None:
        self._encounter_repository = encounter_repository or InMemoryEncounterRepository()
        self._audit_repository = audit_repository or InMemoryAuditRepository()
        self._last_validation_errors: Dict[str, List[str]] = {}

    @property
    def encounter_repository(self) -> InMemoryEncounterRepository:
        return self._encounter_repository

    @property
    def audit_repository(self) -> InMemoryAuditRepository:
        return self._audit_repository

    def load_records(
        self,
        source: Union[str, Path, TextIO],
        imported_by: str,
        persist_valid: bool = True,
    ) -> List[EncounterRecord]:
        if not imported_by or not imported_by.strip():
            raise ValueError("imported_by must be a non-empty string.")

        self._last_validation_errors = {}
        valid_records: List[EncounterRecord] = []
        seen_in_batch: set[str] = set()

        with SafeCSVReader(source) as handle, AuditSession(
            self._audit_repository,
            imported_by=imported_by.strip(),
            source_name=SafeCSVReader._derive_source_name(source),
        ) as audit_session:
            reader = csv.DictReader(handle)
            self._validate_header(reader.fieldnames)

            for row_number, row in enumerate(reader, start=2):
                try:
                    record, errors = self._parse_and_validate_row(
                        row=row,
                        row_number=row_number,
                        seen_in_batch=seen_in_batch,
                    )
                    encounter_key = self._encounter_key_from_row(row, row_number)
                    if errors:
                        self._last_validation_errors[encounter_key] = errors
                        audit_session.record_reject(
                            encounter_id=encounter_key,
                            patient_id=self._safe_strip(row.get("patient_id")),
                            reasons=errors,
                        )
                        continue

                    assert record is not None
                    valid_records.append(record)
                    seen_in_batch.add(record.encounter_id)
                    audit_session.record_accept(
                        encounter_id=record.encounter_id,
                        patient_id=record.patient_id,
                    )
                except Exception as exc:
                    encounter_key = self._encounter_key_from_row(row, row_number)
                    error_message = f"Unexpected processing error: {exc}"
                    self._last_validation_errors.setdefault(encounter_key, []).append(error_message)
                    audit_session.record_reject(
                        encounter_id=encounter_key,
                        patient_id=self._safe_strip(row.get("patient_id")),
                        reasons=[error_message],
                    )

            if persist_valid and valid_records:
                self._encounter_repository.save_many(valid_records)

        return valid_records

    def get_validation_errors(self) -> Dict[str, List[str]]:
        return {k: list(v) for k, v in self._last_validation_errors.items()}

    def get_audit_trail(self) -> List[AuditEntry]:
        return self._audit_repository.list_all()

    def _validate_header(self, fieldnames: Optional[Sequence[Optional[str]]]) -> None:
        if not fieldnames:
            raise ValidationError("CSV file is missing a header row.")
        normalized = {name.strip() for name in fieldnames if name is not None}
        missing = [field for field in self.REQUIRED_FIELDS if field not in normalized]
        if missing:
            raise ValidationError(f"CSV header missing required fields: {', '.join(missing)}")

    def _parse_and_validate_row(
        self,
        row: Dict[str, Any],
        row_number: int,
        seen_in_batch: set[str],
    ) -> tuple[Optional[EncounterRecord], List[str]]:
        errors: List[str] = []

        patient_id = self._safe_strip(row.get("patient_id"))
        encounter_id = self._safe_strip(row.get("encounter_id"))
        provider_id = self._safe_strip(row.get("provider_id"))
        diagnosis_codes_raw = self._safe_strip(row.get("diagnosis_codes"))
        admission_raw = self._safe_strip(row.get("admission_timestamp"))
        discharge_raw = self._safe_strip(row.get("discharge_timestamp"))

        mandatory_values = {
            "patient_id": patient_id,
            "encounter_id": encounter_id,
            "provider_id": provider_id,
            "diagnosis_codes": diagnosis_codes_raw,
            "admission_timestamp": admission_raw,
            "discharge_timestamp": discharge_raw,
        }

        for field_name, value in mandatory_values.items():
            if not value:
                errors.append(f"Missing mandatory field: {field_name}")

        diagnosis_codes: tuple[str, ...] = ()
        if diagnosis_codes_raw:
            diagnosis_codes = tuple(code.strip() for code in diagnosis_codes_raw.split(";") if code.strip())
            if not diagnosis_codes:
                errors.append("diagnosis_codes must contain at least one diagnosis code.")

        admission_dt: Optional[datetime] = None
        discharge_dt: Optional[datetime] = None

        if admission_raw:
            try:
                admission_dt = self._parse_timestamp_to_utc(admission_raw)
            except ValueError as exc:
                errors.append(f"Invalid admission_timestamp: {exc}")

        if discharge_raw:
            try:
                discharge_dt = self._parse_timestamp_to_utc(discharge_raw)
            except ValueError as exc:
                errors.append(f"Invalid discharge_timestamp: {exc}")

        if admission_dt and discharge_dt and discharge_dt < admission_dt:
            errors.append("Business rule violation: discharge time cannot precede admission time.")

        if encounter_id:
            if encounter_id in seen_in_batch:
                errors.append(f"Duplicate encounter detected in import batch: {encounter_id}")
            if self._encounter_repository.exists(encounter_id):
                errors.append(f"Duplicate encounter detected in repository: {encounter_id}")

        if errors:
            return None, errors

        assert patient_id is not None
        assert encounter_id is not None
        assert provider_id is not None
        assert admission_dt is not None
        assert discharge_dt is not None

        record = EncounterRecord(
            patient_id=patient_id,
            encounter_id=encounter_id,
            provider_id=provider_id,
            diagnosis_codes=diagnosis_codes,
            admission_timestamp_utc=admission_dt,
            discharge_timestamp_utc=discharge_dt,
            source_row_number=row_number,
            raw_data=dict(row),
        )
        return record, []

    @staticmethod
    def _safe_strip(value: Any) -> Optional[str]:
        if value is None:
            return None
        text = str(value).strip()
        return text if text else None

    @staticmethod
    def _parse_timestamp_to_utc(value: str) -> datetime:
        normalized = value.strip()
        if normalized.endswith("Z"):
            normalized = normalized[:-1] + "+00:00"
        try:
            parsed = datetime.fromisoformat(normalized)
        except ValueError as exc:
            raise ValueError(f"timestamp '{value}' is not a valid ISO-8601 value") from exc

        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)

    @staticmethod
    def _encounter_key_from_row(row: Dict[str, Any], row_number: int) -> str:
        encounter_id = row.get("encounter_id")
        if encounter_id is not None and str(encounter_id).strip():
            return str(encounter_id).strip()
        return f"row_{row_number}"


if __name__ == "__main__":
    sample_csv = io.StringIO(
        """patient_id,encounter_id,provider_id,diagnosis_codes,admission_timestamp,discharge_timestamp
P001,E001,DR100,I10;E11,2025-03-01T08:00:00-05:00,2025-03-02T10:00:00-05:00
P002,E002,DR101,J20,2025-03-05T09:00:00Z,2025-03-04T09:00:00Z
P003,E001,DR102,M54,2025-03-06T12:00:00+01:00,2025-03-06T14:00:00+01:00
P004,E004,DR103,,2025-03-07T12:00:00,2025-03-07T13:00:00
"""
    )
