from functools import lru_cache


def min_subset_sum_difference(nums, k):
    """
    Partition nums into exactly k non-empty subsets minimizing
    max(subset_sums) - min(subset_sums).

    Uses DP with bitmasking over subsets.
    """
    n = len(nums)
    if not (1 <= k <= n):
        raise ValueError("k must satisfy 1 <= k <= len(nums)")

    full_mask = (1 << n) - 1

    # Precompute sum for every subset mask.
    subset_sum = [0] * (1 << n)
    for mask in range(1, 1 << n):
        lsb = mask & -mask
        bit = lsb.bit_length() - 1
        subset_sum[mask] = subset_sum[mask ^ lsb] + nums[bit]

    @lru_cache(maxsize=None)
    def dp(mask, parts_left):
        """
        Returns a set of (min_sum, max_sum) pairs achievable by partitioning
        elements in 'mask' into exactly 'parts_left' non-empty subsets.
        Dominated states are pruned.
        """
        count = mask.bit_count()
        if count < parts_left or parts_left == 0:
            return tuple()
        if parts_left == 1:
            s = subset_sum[mask]
            return ((s, s),)

        results = []

        # Fix the lowest set bit to avoid generating the same partition
        # in different orders.
        first_bit = mask & -mask
        sub = mask
        while sub:
            # Candidate subset must include first_bit and leave enough elements.
            if (sub & first_bit) and sub != mask:
                remaining = mask ^ sub
                if remaining.bit_count() >= parts_left - 1:
                    current_sum = subset_sum[sub]
                    for mn, mx in dp(remaining, parts_left - 1):
                        results.append((min(current_sum, mn), max(current_sum, mx)))
            sub = (sub - 1) & mask

        if not results:
            return tuple()

        # Prune dominated states: keep only pairs where no other pair has
        # min >= current min and max <= current max.
        results.sort(key=lambda x: (-x[0], x[1]))
        pruned = []
        best_max = float('inf')
        for mn, mx in results:
            if mx < best_max:
                pruned.append((mn, mx))
                best_max = mx

        return tuple(pruned)

    states = dp(full_mask, k)
    return min(mx - mn for mn, mx in states)


