    print(min_subset_sum_difference(nums, k))

def analyze_orders(orders):
    """Analyze a list of order dictionaries and summarize completed/cancelled activity."""
    completed_by_customer = {}
    unique_items = set()
    customers_with_cancelled = set()

    for order in orders:
        # Skip malformed records safely
        if not isinstance(order, dict):
            continue

        customer = order.get('customer')
        items = order.get('items')
        status = order.get('status')

        if not isinstance(customer, str) or not isinstance(status, str):
            continue

        if status == 'completed':
            completed_by_customer[customer] = completed_by_customer.get(customer, 0) + 1

            if isinstance(items, list):
                for item in items:
                    if isinstance(item, str):
                        unique_items.add(item)

        elif status == 'cancelled':
            customers_with_cancelled.add(customer)

    # Use a set comprehension to find repeat customers
    repeat_completed_customers = {
        customer for customer, count in completed_by_customer.items() if count >= 2
    }

    return {
        'completed_by_customer': completed_by_customer,
        'unique_items': unique_items,
        'customers_with_cancelled': customers_with_cancelled,
        'repeat_completed_customers': repeat_completed_customers,
    }


