class ValidationError(Exception):
    """Base class for validation-related errors."""
    pass


class AgeTooLowError(ValidationError):
    """Raised when age is below the allowed range."""
    pass


class AgeTooHighError(ValidationError):
    """Raised when age is above the allowed range."""
    pass


def validate_age(age):
    """Validate that age is within a realistic human range."""
    if age < 0:
        raise AgeTooLowError(f"Age {age} is too low.")
    if age > 130:
        raise AgeTooHighError(f"Age {age} is too high.")
    return f"Age {age} is valid."


