    except AgeTooHighError as error:
        print(f"High age error: {error}")
    except ValidationError as error:
        print(f"Validation error: {error}")

class CleanMessageIterator:
    """Custom iterator that yields stripped messages one by one."""

    def __init__(self, messages):
        self._messages = iter(messages)

    def __iter__(self):
        return self

    def __next__(self):
        return next(self._messages).strip()


def filter_errors(lines):
    """Yield only log lines that start with 'ERROR:' lazily."""
    for line in lines:
        if line.startswith('ERROR:'):
            yield line


def extract_messages(lines):
    """Yield the message part after the first colon."""
    for line in lines:
        _, message = line.split(':', 1)
        yield message


def main():
    log_lines = [
        'INFO: System started',
        'ERROR: Disk space low   ',
        'WARNING: High memory usage',
        'ERROR:  Failed to connect to database',
        'INFO: Retrying operation',
        'ERROR: Timeout while waiting for response   '
    ]

    # Build a lazy processing pipeline
    error_lines = filter_errors(log_lines)
    error_messages = extract_messages(error_lines)
    cleaned_messages = CleanMessageIterator(error_messages)

    for message in cleaned_messages:
        print(message)


if __name__ == '__main__':
    main()

from collections import defaultdict


def parse_line(line):
    """Parse a log line and return (username, bytes_transferred) or None if invalid."""
    parts = [part.strip() for part in line.split(',')]
    if len(parts) != 3:
        return None

    date_str, username, byte_str = parts
    if not date_str or not username:
        return None

    try:
        bytes_transferred = int(byte_str)
        if bytes_transferred < 0:
            return None
    except ValueError:
        return None

    return username, bytes_transferred


def generate_report(input_file, output_file):
    totals = defaultdict(int)

    # Read and aggregate valid records
    with open(input_file, 'r', encoding='utf-8') as infile:
        for raw_line in infile:
            line = raw_line.strip()
            if not line:
                continue

            parsed = parse_line(line)
            if parsed is None:
                continue

            username, bytes_transferred = parsed
            totals[username] += bytes_transferred

    # Sort users by total bytes descending, then username ascending for stability
    sorted_users = sorted(totals.items(), key=lambda item: (-item[1], item[0]))

    # Write the report
    with open(output_file, 'w', encoding='utf-8') as outfile:
        if not sorted_users:
            outfile.write('TOP_USER,NONE,0\n')
            return

        for username, total_bytes in sorted_users:
            outfile.write(f'{username},{total_bytes}\n')

        top_user, top_total = sorted_users[0]
        outfile.write(f'TOP_USER,{top_user},{top_total}\n')


if __name__ == '__main__':
    generate_report('access.log', 'usage_report.txt')

from collections import deque
from itertools import islice


class RoundRobinMerge:
    """Iterate over multiple iterables in round-robin order."""

    def __init__(self, *iterables):
        # Store iterators only; this allows support for lazy inputs.
        self._iterators = deque(iter(it) for it in iterables)

    def __iter__(self):
        return self

    def __next__(self):
        # Keep rotating until we either find a value or all iterators are exhausted.
        while self._iterators:
            it = self._iterators.popleft()
            try:
                value = next(it)
            except StopIteration:
                # Exhausted iterator is discarded.
                continue
            else:
                # Still active; put it back at the end for round-robin scheduling.
                self._iterators.append(it)
                return value
        raise StopIteration

    def active_count(self):
        # Number of iterators not yet proven exhausted.
        return len(self._iterators)


def chunked(iterable, size):
    """Yield tuples containing up to 'size' items from iterable."""
    if size <= 0:
        raise ValueError("size must be a positive integer")

    it = iter(iterable)
    while True:
        chunk = tuple(islice(it, size))
        if not chunk:
            break
        yield chunk


