class MaxStack:
    def __init__(self):
        # Each entry stores (value, current_max_at_this_level)
        self._data = []

    def push(self, x):
        current_max = x if not self._data else max(x, self._data[-1][1])
        self._data.append((x, current_max))

    def pop(self):
        if not self._data:
            raise IndexError('pop from empty stack')
        return self._data.pop()[0]

    def max(self):
        if not self._data:
            raise IndexError('max from empty stack')
        return self._data[-1][1]

    def empty(self):
        return not self._data


class MaxQueue:
    def __init__(self):
        # in_stack receives new elements, out_stack serves dequeues
        self._in_stack = MaxStack()
        self._out_stack = MaxStack()

    def enqueue(self, x):
        self._in_stack.push(x)

    def _shift(self):
        # Move elements only when needed to keep amortized O(1)
        if self._out_stack.empty():
            while not self._in_stack.empty():
                self._out_stack.push(self._in_stack.pop())

    def dequeue(self):
        self._shift()
        if self._out_stack.empty():
            raise IndexError('dequeue from empty queue')
        return self._out_stack.pop()

    def max(self):
        if self._in_stack.empty() and self._out_stack.empty():
            raise IndexError('max from empty queue')
        if self._in_stack.empty():
            return self._out_stack.max()
        if self._out_stack.empty():
            return self._in_stack.max()
        return max(self._in_stack.max(), self._out_stack.max())


class MaxQueueStackSystem:
    def __init__(self):
        self.queue = MaxQueue()
        self.stack = MaxStack()

    def process(self, operations):
        results = []
        for op in operations:
            name = op[0]

            if name == 'enqueue':
                self.queue.enqueue(op[1])
            elif name == 'dequeue':
                results.append(self.queue.dequeue())
            elif name == 'max_queue':
                results.append(self.queue.max())
            elif name == 'push':
                self.stack.push(op[1])
            elif name == 'pop_stack':
                results.append(self.stack.pop())
            elif name == 'max_stack':
                results.append(self.stack.max())
            else:
                raise ValueError(f'Unknown operation: {name}')

        return results


