class Drink:
    def __init__(self, name, sugar=0, milk=False):
        self.name = name
        self.sugar = sugar
        self.milk = milk

    def describe(self):
        milk_text = 'with milk' if self.milk else 'without milk'
        return f'{self.name} with {self.sugar} sugar(s), {milk_text}'


class Tea(Drink):
    def __init__(self):
        super().__init__('Tea')


class Coffee(Drink):
    def __init__(self):
        super().__init__('Coffee')


class DrinkFactory:
    def create_drink(self, drink_type):
        drink_type = drink_type.lower()
        if drink_type == 'tea':
            return Tea()
        if drink_type == 'coffee':
            return Coffee()
        raise ValueError('Unknown drink type')


class DrinkBuilder:
    def __init__(self):
        self.name = 'Custom Drink'
        self.sugar = 0
        self.milk = False

    def set_base(self, name):
        self.name = name
        return self

    def set_sugar(self, sugar):
        self.sugar = sugar
        return self

    def add_milk(self, milk=True):
        self.milk = milk
        return self

    def build(self):
        return Drink(self.name, self.sugar, self.milk)


# Demonstrate Factory pattern
