    .add_milk(True)
    .build()
)
print('Built drink:', custom_drink.describe())

from datetime import datetime
import re

EVENT_ID_RE = re.compile(r"^EVT-[0-9]{4}$")
ALLOWED_TYPES = {"click", "view", "purchase"}
ALLOWED_TOP_LEVEL = {"event_id", "timestamp", "type", "user", "amount", "tags", "metadata"}
META_VALUE_TYPES = (str, int, float, bool, type(None))


def validate_event(payload: dict) -> dict:
    if not isinstance(payload, dict):
        raise ValueError("payload must be a dictionary")

    unknown = set(payload) - ALLOWED_TOP_LEVEL
    if unknown:
        raise ValueError(f"unknown top-level fields: {sorted(unknown)}")

    # Validate required primitive fields
    event_id = payload.get("event_id")
    if not isinstance(event_id, str) or not event_id or not EVENT_ID_RE.match(event_id):
        raise ValueError("event_id must be a non-empty string like 'EVT-1234'")

    raw_timestamp = payload.get("timestamp")
    if not isinstance(raw_timestamp, str):
        raise ValueError("timestamp must be an ISO 8601 datetime string")
    try:
        timestamp = datetime.fromisoformat(raw_timestamp.replace("Z", "+00:00"))
    except ValueError as e:
        raise ValueError("timestamp must be a valid ISO 8601 datetime string") from e

    event_type = payload.get("type")
    if not isinstance(event_type, str):
        raise ValueError("type must be a string")
    event_type = event_type.lower()
    if event_type not in ALLOWED_TYPES:
        raise ValueError(f"type must be one of {sorted(ALLOWED_TYPES)}")

    # Validate nested user object
    user = payload.get("user")
    if not isinstance(user, dict):
        raise ValueError("user must be a dictionary")
    if "id" not in user or not isinstance(user["id"], int) or user["id"] <= 0:
        raise ValueError("user.id must be a positive integer")

    normalized_user = {"id": user["id"]}
    if "email" in user:
        email = user["email"]
        if not isinstance(email, str) or "@" not in email:
            raise ValueError("user.email must be a valid email-like string")
        normalized_user["email"] = email.lower()

    # Conditional amount validation
    normalized = {
        "event_id": event_id,
        "timestamp": timestamp,
        "type": event_type,
        "user": normalized_user,
    }
    if event_type == "purchase":
        if "amount" not in payload:
            raise ValueError("amount is required when type is 'purchase'")
    if "amount" in payload:
        amount = payload["amount"]
        if not isinstance(amount, (int, float)) or isinstance(amount, bool) or amount <= 0:
            raise ValueError("amount must be a positive number")
        normalized["amount"] = float(amount)

    # Normalize tags: trim, remove empties, deduplicate preserving order
    if "tags" in payload:
        tags = payload["tags"]
        if not isinstance(tags, list):
            raise ValueError("tags must be a list of unique non-empty strings")
        seen = set()
        normalized_tags = []
        for tag in tags:
            if not isinstance(tag, str):
                raise ValueError("each tag must be a string")
            cleaned = tag.strip()
            if not cleaned:
                raise ValueError("tags cannot contain empty strings")
            if cleaned not in seen:
                seen.add(cleaned)
                normalized_tags.append(cleaned)
        normalized["tags"] = normalized_tags

    if "metadata" in payload:
        metadata = payload["metadata"]
        if not isinstance(metadata, dict):
            raise ValueError("metadata must be a dictionary")
        for k, v in metadata.items():
            if not isinstance(k, str):
                raise ValueError("metadata keys must be strings")
            if not isinstance(v, META_VALUE_TYPES):
                raise ValueError(f"metadata value for '{k}' has unsupported type")
        normalized["metadata"] = dict(metadata)

    return normalized

def parse_config(text: str) -> dict:
    def unescape_quoted(s: str, line_no: int) -> str:
        result = []
        i = 0
        while i < len(s):
            ch = s[i]
            if ch == '\\':
                i += 1
                if i >= len(s):
                    raise ValueError(f"Line {line_no}: unterminated quoted value")
                esc = s[i]
                mapping = {'n': '\n', 't': '\t', '"': '"', '\\': '\\'}
                result.append(mapping.get(esc, esc))
            else:
                result.append(ch)
            i += 1
        return ''.join(result)

    config = {'_global': {}}
    current_section = '_global'

    for line_no, raw_line in enumerate(text.splitlines(), start=1):
        line = raw_line.strip()

        if not line or line.startswith('#'):
            continue

        if line.startswith('['):
            if not line.endswith(']') or len(line) < 3:
                raise ValueError(f"Line {line_no}: malformed section header")
            section = line[1:-1].strip()
            if not section:
                raise ValueError(f"Line {line_no}: malformed section header")
            current_section = section
            config.setdefault(current_section, {})
            continue

        if '=' not in line:
            raise ValueError(f"Line {line_no}: missing '='")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key:
            raise ValueError(f"Line {line_no}: empty key")

        if value.startswith('"'):
            if len(value) < 2 or not value.endswith('"'):
                raise ValueError(f"Line {line_no}: unterminated quoted value")
            inner = value[1:-1]
            parsed_value = unescape_quoted(inner, line_no)
        else:
            parsed_value = value

        config[current_section][key] = parsed_value

    return config


