class TypedField:
    """Reusable validating descriptor with optional transform and predicate."""

    def __init__(self, expected_type, *, default=None, transform=None, validator=None):
        self.expected_type = expected_type
        self.default = default
        self.transform = transform
        self.validator = validator

    def __set_name__(self, owner, name):
        self.name = name
        self.storage_name = f"_{owner.__name__}__{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        if not hasattr(instance, self.storage_name):
            if self.default is None:
                raise AttributeError(f"{self.name} has not been set")
            value = self.default() if callable(self.default) else self.default
            setattr(instance, self.storage_name, value)
        return getattr(instance, self.storage_name)

    def __set__(self, instance, value):
        if self.transform is not None:
            value = self.transform(value)
        if not isinstance(value, self.expected_type):
            raise TypeError(f"{self.name} must be of type {self.expected_type.__name__}")
        if self.validator is not None and not self.validator(value):
            raise ValueError(f"Invalid value for {self.name}: {value!r}")
        setattr(instance, self.storage_name, value)


class DatabaseConfig:
    host = TypedField(
        str,
        transform=lambda v: v.strip(),
        validator=lambda v: len(v) > 0,
    )
    port = TypedField(
        int,
        validator=lambda v: 1 <= v <= 65535,
    )
    timeout = TypedField(
        float,
        default=5.0,
        transform=float,
        validator=lambda v: v > 0,
    )

    def __init__(self, host, port, timeout=5.0, secure=False):
        self.host = host
        self.port = port
        self.timeout = timeout
        self.secure = secure

    @property
    def dsn(self):
        return f"{self.host}:{self.port}?timeout={self.timeout}"

    @property
    def secure(self):
        return getattr(self, "_secure", False)

    @secure.setter
    def secure(self, value):
        if not isinstance(value, bool):
            raise TypeError("secure must be a bool")
        self._secure = value


