    print(config.dsn)

import random

# Fixed knapsack instance: (value, weight)
ITEMS = [(20, 6), (14, 5), (33, 10), (8, 3), (16, 7), (25, 8), (9, 4), (30, 9)]
CAPACITY = 25
POP_SIZE = 60
GENERATIONS = 120
MUTATION_RATE = 0.03
TOURNAMENT_SIZE = 4
ELITE_COUNT = 2


def fitness(chromosome):
    total_value = sum(gene * item[0] for gene, item in zip(chromosome, ITEMS))
    total_weight = sum(gene * item[1] for gene, item in zip(chromosome, ITEMS))
    return total_value if total_weight <= CAPACITY else 0


def weight(chromosome):
    return sum(gene * item[1] for gene, item in zip(chromosome, ITEMS))


def random_chromosome():
    return [random.randint(0, 1) for _ in ITEMS]


def tournament_selection(population):
    contenders = random.sample(population, TOURNAMENT_SIZE)
    return max(contenders, key=fitness)


def crossover(parent1, parent2):
    point = random.randint(1, len(parent1) - 1)
    child1 = parent1[:point] + parent2[point:]
    child2 = parent2[:point] + parent1[point:]
    return child1, child2


def mutate(chromosome):
    for i in range(len(chromosome)):
        if random.random() < MUTATION_RATE:
            chromosome[i] ^= 1
    return chromosome


def genetic_algorithm():
    population = [random_chromosome() for _ in range(POP_SIZE)]

    for _ in range(GENERATIONS):
        population.sort(key=fitness, reverse=True)
        new_population = population[:ELITE_COUNT]  # Keep the best individuals

        while len(new_population) < POP_SIZE:
            parent1 = tournament_selection(population)
            parent2 = tournament_selection(population)
            child1, child2 = crossover(parent1, parent2)
            new_population.append(mutate(child1[:]))
            if len(new_population) < POP_SIZE:
                new_population.append(mutate(child2[:]))

        population = new_population

    best = max(population, key=fitness)
    print('Best chromosome:', best)
    print('Total value:', fitness(best))
    print('Total weight:', weight(best))


if __name__ == '__main__':
    random.seed(42)
    genetic_algorithm()

class PositiveNumber:
    """Descriptor that validates positive numeric values and stores them per instance."""

    def __init__(self, default=None):
        self.default = default
        self.private_name = None

    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        if not hasattr(instance, self.private_name):
            if self.default is None:
                raise AttributeError(f"{self.private_name[1:]} has not been set")
            setattr(instance, self.private_name, self.default)
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError(f"{self.private_name[1:]} must be a number")
        if value <= 0:
            raise ValueError(f"{self.private_name[1:]} must be positive")
        setattr(instance, self.private_name, float(value))


class Product:
    price = PositiveNumber()
    weight = PositiveNumber(default=1.0)

    def __init__(self, name, price, weight=None):
        self.name = name
        self.price = price
        if weight is not None:
            self.weight = weight

    @property
    def shipping_cost(self):
        """Read-only derived value based on weight."""
        return self.weight * 1.25

    @property
    def total_cost(self):
        """Combined cost of product price and shipping."""
        return self.price + self.shipping_cost

    @total_cost.setter
    def total_cost(self, value):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("total_cost must be a number")
        new_price = value - self.shipping_cost
        self.price = new_price  # Reuse descriptor validation

    def __repr__(self):
        return (
            f"Product(name={self.name!r}, price={self.price:.2f}, "
            f"weight={self.weight:.2f})"
        )


if __name__ == "__main__":
    book = Product("Book", 12.0, 2.0)
    print(book)
    print("shipping_cost:", book.shipping_cost)
    print("total_cost:", book.total_cost)

    # Update total cost; only price changes.
    book.total_cost = 20.0
    print("updated:", book)
    print("new total_cost:", book.total_cost)

    # Weight uses descriptor default if omitted.
    pen = Product("Pen", 3.5)
    print(pen)
    print("pen shipping_cost:", pen.shipping_cost)

import json
import csv
from datetime import datetime, timezone
from collections import defaultdict

INPUT_FILE = 'events.jsonl'
OUTPUT_FILE = 'aggregated_events.csv'


def parse_ts(value: str) -> datetime:
    """Parse ISO-8601 timestamps and normalize to UTC."""
    if not value:
        return datetime.min.replace(tzinfo=timezone.utc)
    value = value.replace('Z', '+00:00')
    dt = datetime.fromisoformat(value)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def extract_record(raw: dict) -> dict | None:
    """Flatten and validate a raw event record."""
    user = raw.get('user', {}) if isinstance(raw.get('user'), dict) else {}
    event = {
        'event_id': raw.get('event_id'),
        'user_id': raw.get('user_id') or user.get('id'),
        'event_type': raw.get('event_type'),
        'timestamp': parse_ts(raw.get('timestamp')),
    }
    if not event['user_id'] or not event['event_type']:
        return None
    return event


def load_and_deduplicate(path: str) -> list[dict]:
    """Read JSONL, clean records, and keep latest row per event_id."""
    deduped = {}
    with open(path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                raw = json.loads(line)
                record = extract_record(raw)
                if not record:
                    continue
                key = record['event_id'] or f"no-id:{record['user_id']}:{record['event_type']}:{record['timestamp'].isoformat()}"
                if key not in deduped or record['timestamp'] > deduped[key]['timestamp']:
                    deduped[key] = record
            except (json.JSONDecodeError, ValueError, TypeError):
                # Skip malformed rows
                continue
    return list(deduped.values())


def aggregate(records: list[dict]) -> list[dict]:
    """Aggregate event counts and latest timestamp by user and event type."""
    stats = defaultdict(lambda: {'event_count': 0, 'latest_event_ts': datetime.min.replace(tzinfo=timezone.utc)})
    for r in records:
        key = (r['user_id'], r['event_type'])
        stats[key]['event_count'] += 1
        if r['timestamp'] > stats[key]['latest_event_ts']:
            stats[key]['latest_event_ts'] = r['timestamp']

    result = []
    for (user_id, event_type), values in sorted(stats.items()):
        result.append({
            'user_id': user_id,
            'event_type': event_type,
            'event_count': values['event_count'],
            'latest_event_ts': values['latest_event_ts'].isoformat(),
        })
    return result


def write_csv(rows: list[dict], path: str) -> None:
    with open(path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['user_id', 'event_type', 'event_count', 'latest_event_ts'])
        writer.writeheader()
        writer.writerows(rows)


if __name__ == '__main__':
    records = load_and_deduplicate(INPUT_FILE)
    aggregated = aggregate(records)
    write_csv(aggregated, OUTPUT_FILE)
    print(f'Wrote {len(aggregated)} aggregated rows to {OUTPUT_FILE}')

class StreamParserFSM:
    """Finite state machine for parsing messages like <TYPE:PAYLOAD|AF>."""

    def __init__(self):
        self.reset()

    def reset(self):
        self.state = 'WAIT_START'
        self.msg_type = []
        self.payload = []
        self.checksum = []

    def _fail(self):
        """Reset parser after malformed input."""
        self.reset()

    def feed(self, ch):
        """Consume one character. Return parsed message dict when complete, else None."""
        if self.state == 'WAIT_START':
            if ch == '<':
                self.state = 'TYPE'

        elif self.state == 'TYPE':
            if ch.isupper():
                self.msg_type.append(ch)
            elif ch == ':' and self.msg_type:
                self.state = 'PAYLOAD'
            else:
                self._fail()
                if ch == '<':  # allow immediate restart
                    self.state = 'TYPE'

        elif self.state == 'PAYLOAD':
            if ch == '|':
                self.state = 'CHECKSUM'
            elif ch == '>':
                self._fail()
            else:
                self.payload.append(ch)

        elif self.state == 'CHECKSUM':
            if ch in '0123456789abcdefABCDEF' and len(self.checksum) < 2:
                self.checksum.append(ch.upper())
                if len(self.checksum) == 2:
                    self.state = 'END'
            else:
                self._fail()
                if ch == '<':
                    self.state = 'TYPE'

        elif self.state == 'END':
            if ch == '>':
                result = {
                    'type': ''.join(self.msg_type),
                    'payload': ''.join(self.payload),
                    'checksum': ''.join(self.checksum),
                }
                self.reset()
                return result
            else:
                self._fail()
                if ch == '<':
                    self.state = 'TYPE'

        return None

    def feed_many(self, text):
        """Process a full string and collect all valid parsed messages."""
        messages = []
        for ch in text:
            msg = self.feed(ch)
            if msg is not None:
                messages.append(msg)
        return messages


# Example usage
if __name__ == '__main__':
    parser = StreamParserFSM()
    stream = 'junk<MSG:hello world|AF><PING:ok|1C>bad<ERR:oops|ZZ><DATA:123|0F>'
    print(parser.feed_many(stream))

import json
from typing import Callable, List, Any, Dict


class DataFormatError(Exception):
    """Raised when a fetcher returns invalid JSON."""


class FetchError(Exception):
    """Raised when all fetch attempts fail."""

    def __init__(self, errors: List[Dict[str, str]]):
        self.errors = errors
        message = "All fetch attempts failed: " + "; ".join(
            f"attempt {e['attempt']} ({e['type']}): {e['message']}" for e in errors
        )
        super().__init__(message)


def fetch_json_with_retry(fetchers: List[Callable[[], str]]) -> Any:
    """Try fetchers in order until one returns valid JSON."""
    errors = []

    for index, fetcher in enumerate(fetchers, start=1):
        try:
            raw = fetcher()
            try:
                return json.loads(raw)
            except json.JSONDecodeError as exc:
                raise DataFormatError(f"invalid JSON: {exc.msg}") from exc

        except TimeoutError as exc:
            # Timeout is considered retryable; continue to next fetcher.
            errors.append({
                "attempt": str(index),
                "type": type(exc).__name__,
                "message": str(exc),
            })
        except ConnectionError as exc:
            # Connection errors are skipped and recorded.
            errors.append({
                "attempt": str(index),
                "type": type(exc).__name__,
                "message": str(exc),
            })
        except DataFormatError as exc:
            # Invalid data is also recorded before trying the next source.
            errors.append({
                "attempt": str(index),
                "type": type(exc).__name__,
                "message": str(exc),
            })
        except Exception as exc:
            # Unexpected exceptions are preserved and recorded too.
            errors.append({
                "attempt": str(index),
                "type": type(exc).__name__,
                "message": str(exc),
            })

    raise FetchError(errors)


if __name__ == "__main__":
    def slow_service():
        raise TimeoutError("request timed out after 2s")

    def offline_service():
        raise ConnectionError("host unreachable")

    def bad_payload_service():
        return "{bad json}"

    def healthy_service():
        return '{"status": "ok", "items": [1, 2, 3]}'

    services = [slow_service, offline_service, bad_payload_service, healthy_service]

    try:
        result = fetch_json_with_retry(services)
        print("Success:", result)
    except FetchError as exc:
        print(str(exc))
        print("Detailed errors:", exc.errors)

