import json
from pathlib import Path


def load_app_config(path):
    """Load, validate, and normalize application configuration from a JSON file."""
    config_path = Path(path)

    if not config_path.is_file():
        raise ValueError(f"Configuration file not found: {path}")

    try:
        with config_path.open("r", encoding="utf-8") as f:
            config = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in configuration file: {e.msg}") from e
    except OSError as e:
        raise ValueError(f"Could not read configuration file: {e}") from e

    if not isinstance(config, dict):
        raise ValueError("Configuration must be a JSON object")

    required_keys = ["host", "port", "debug"]
    missing_keys = [key for key in required_keys if key not in config]
    if missing_keys:
        raise ValueError(f"Missing required configuration keys: {', '.join(missing_keys)}")

    # Apply defaults for optional settings
    config.setdefault("timeout", 30)
    config.setdefault("log_level", "INFO")

    # Validate values
    if not isinstance(config["host"], str) or not config["host"].strip():
        raise ValueError("'host' must be a non-empty string")

    if not isinstance(config["port"], int) or isinstance(config["port"], bool):
        raise ValueError("'port' must be an integer")
    if not (1 <= config["port"] <= 65535):
        raise ValueError("'port' must be between 1 and 65535")

    if not isinstance(config["debug"], bool):
        raise ValueError("'debug' must be a boolean")

    if not isinstance(config["timeout"], int) or isinstance(config["timeout"], bool) or config["timeout"] <= 0:
        raise ValueError("'timeout' must be a positive integer")

    if not isinstance(config["log_level"], str) or not config["log_level"].strip():
        raise ValueError("'log_level' must be a non-empty string")

    return config


if __name__ == "__main__":
    # Example usage
    try:
        settings = load_app_config("config.json")
        print("Loaded configuration:")
        print(settings)
    except ValueError as e:
        print(f"Error: {e}")

from functools import reduce, lru_cache, cmp_to_key


def build_event_index(events):
    """Aggregate total value per (user, type) pair using reduce."""
    def reducer(acc, event):
        key = (event['user'], event['type'])
        acc[key] = acc.get(key, 0) + event['value']
        return acc

    return reduce(reducer, events, {})


def freeze_index(index):
    """Convert a dict into a stable, hashable representation for caching."""
    return tuple(sorted(index.items()))


@lru_cache(maxsize=128)
def _cached_user_summary(frozen_index, user):
    """Internal cached implementation operating on a hashable index."""
    summary = {}
    for (event_user, event_type), total in frozen_index:
        if event_user == user:
            summary[event_type] = summary.get(event_type, 0) + total
    return sorted(summary.items(), key=lambda item: (-item[1], item[0]))


def get_user_summary(index, user):
    """Public API that accepts a normal dict and uses the cached backend."""
    return _cached_user_summary(freeze_index(index), user)


def compare_events(a, b):
    """Order by user asc, value desc, type asc."""
    if a['user'] != b['user']:
        return -1 if a['user'] < b['user'] else 1
    if a['value'] != b['value']:
        return -1 if a['value'] > b['value'] else 1
    if a['type'] != b['type']:
        return -1 if a['type'] < b['type'] else 1
    return 0


def sort_events(events):
    return sorted(events, key=cmp_to_key(compare_events))


if __name__ == '__main__':
    events = [
        {'user': 'alice', 'type': 'click', 'value': 3},
        {'user': 'bob', 'type': 'view', 'value': 5},
        {'user': 'alice', 'type': 'view', 'value': 7},
        {'user': 'alice', 'type': 'click', 'value': 4},
        {'user': 'bob', 'type': 'click', 'value': 2},
        {'user': 'bob', 'type': 'view', 'value': 1},
    ]

    index = build_event_index(events)
    print('Index:', index)
    print('Alice summary:', get_user_summary(index, 'alice'))
    print('Bob summary:', get_user_summary(index, 'bob'))
    print('Sorted events:', sort_events(events))

import csv
import json
from collections import defaultdict
from datetime import datetime, timezone

INPUT_FILE = 'events.jsonl'
OUTPUT_FILE = 'daily_metrics.csv'
RATES = {'USD': 1.0, 'EUR': 1.1, 'GBP': 1.25}
REQUIRED_FIELDS = {'event_id', 'user_id', 'event_type', 'amount', 'currency', 'timestamp'}


def parse_timestamp(value):
    """Parse ISO timestamp and normalize to UTC date string."""
    try:
        dt = datetime.fromisoformat(value.replace('Z', '+00:00'))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc).date().isoformat()
    except Exception:
        return None


def transform_record(record):
    """Validate and transform a single input record."""
    if not REQUIRED_FIELDS.issubset(record):
        return None
    day = parse_timestamp(str(record['timestamp']))
    if not day:
        return None
    currency = str(record['currency']).upper()
    if currency not in RATES:
        return None
    try:
        amount_usd = float(record['amount']) * RATES[currency]
    except (TypeError, ValueError):
        return None
    return {
        'day': day,
        'event_type': str(record['event_type']).strip().lower(),
        'user_id': str(record['user_id']),
        'amount_usd': amount_usd,
    }


def etl(input_file, output_file):
    aggregates = defaultdict(lambda: {'total_events': 0, 'users': set(), 'total_amount_usd': 0.0})

    with open(input_file, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                raw = json.loads(line)
            except json.JSONDecodeError:
                continue
            record = transform_record(raw)
            if not record:
                continue

            key = (record['day'], record['event_type'])
            aggregates[key]['total_events'] += 1
            aggregates[key]['users'].add(record['user_id'])
            aggregates[key]['total_amount_usd'] += record['amount_usd']

    with open(output_file, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['day', 'event_type', 'total_events', 'unique_users', 'total_amount_usd'])
        for (day, event_type) in sorted(aggregates):
            stats = aggregates[(day, event_type)]
            writer.writerow([
                day,
                event_type,
                stats['total_events'],
                len(stats['users']),
                round(stats['total_amount_usd'], 2),
            ])


if __name__ == '__main__':
    etl(INPUT_FILE, OUTPUT_FILE)

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import date, datetime
from typing import Dict, List, Optional, Any


class BudgetError(Exception):
    """Base exception for budget-related errors."""


class ValidationError(BudgetError):
    """Raised when invalid input is provided."""


@dataclass
class Transaction:
    amount: float
    category: str
    transaction_type: str  # income, fixed_expense, variable_expense, savings
    description: str = ""
    transaction_date: date = field(default_factory=date.today)

    def __post_init__(self) -> None:
        if not isinstance(self.amount, (int, float)):
            raise ValidationError("Transaction amount must be numeric.")
        if self.amount <= 0:
            raise ValidationError("Transaction amount must be greater than zero.")
        if not isinstance(self.category, str) or not self.category.strip():
            raise ValidationError("Transaction category must be a non-empty string.")
        if self.transaction_type not in {
            "income",
            "fixed_expense",
            "variable_expense",
            "savings",
        }:
            raise ValidationError(
                "Transaction type must be one of: income, fixed_expense, variable_expense, savings."
            )
        if not isinstance(self.description, str):
            raise ValidationError("Description must be a string.")
        if not isinstance(self.transaction_date, date):
            raise ValidationError("transaction_date must be a datetime.date instance.")

        self.category = self.category.strip()
        self.description = self.description.strip()


class MonthlyBudget:
    def __init__(
        self,
        year: int,
        month: int,
        budget_limits: Optional[Dict[str, float]] = None,
        savings_goal: float = 0.0,
    ) -> None:
        self.year = self._validate_year(year)
        self.month = self._validate_month(month)
        self.budget_limits: Dict[str, float] = {}
        self.transactions: List[Transaction] = []
        self.savings_goal = self._validate_non_negative_number(
            savings_goal, "savings_goal"
        )

        if budget_limits:
            for category, limit in budget_limits.items():
                self.set_budget_limit(category, limit)

    @staticmethod
    def _validate_year(year: int) -> int:
        if not isinstance(year, int) or year < 1:
            raise ValidationError("Year must be a positive integer.")
        return year

    @staticmethod
    def _validate_month(month: int) -> int:
        if not isinstance(month, int) or not 1 <= month <= 12:
            raise ValidationError("Month must be an integer between 1 and 12.")
        return month

    @staticmethod
    def _validate_non_negative_number(value: Any, field_name: str) -> float:
        if not isinstance(value, (int, float)):
            raise ValidationError(f"{field_name} must be numeric.")
        if value < 0:
            raise ValidationError(f"{field_name} must be non-negative.")
        return float(value)

    @staticmethod
    def _validate_positive_number(value: Any, field_name: str) -> float:
        if not isinstance(value, (int, float)):
            raise ValidationError(f"{field_name} must be numeric.")
        if value <= 0:
            raise ValidationError(f"{field_name} must be greater than zero.")
        return float(value)

    @staticmethod
    def _validate_category(category: str) -> str:
        if not isinstance(category, str) or not category.strip():
            raise ValidationError("Category must be a non-empty string.")
        return category.strip()

    def set_budget_limit(self, category: str, limit: float) -> None:
        category = self._validate_category(category)
        limit = self._validate_non_negative_number(limit, "limit")
        self.budget_limits[category] = limit

    def set_savings_goal(self, amount: float) -> None:
        self.savings_goal = self._validate_non_negative_number(amount, "savings_goal")

    def add_transaction(
        self,
        amount: float,
        category: str,
        transaction_type: str,
        description: str = "",
        transaction_date: Optional[date] = None,
    ) -> Transaction:
        if transaction_date is None:
            transaction_date = date(self.year, self.month, 1)
        elif isinstance(transaction_date, datetime):
            transaction_date = transaction_date.date()

        if not isinstance(transaction_date, date):
            raise ValidationError("transaction_date must be a datetime.date instance.")

        if transaction_date.year != self.year or transaction_date.month != self.month:
            raise ValidationError(
                "Transaction date must match the monthly budget's year and month."
            )

        transaction = Transaction(
            amount=self._validate_positive_number(amount, "amount"),
            category=self._validate_category(category),
            transaction_type=transaction_type,
            description=description,
            transaction_date=transaction_date,
        )
        self.transactions.append(transaction)
        return transaction

    def categorize_expense(
        self, transaction_index: int, new_category: str, new_type: Optional[str] = None
    ) -> None:
        if not isinstance(transaction_index, int):
            raise ValidationError("transaction_index must be an integer.")
        if transaction_index < 0 or transaction_index >= len(self.transactions):
            raise ValidationError("transaction_index is out of range.")

        transaction = self.transactions[transaction_index]
        if transaction.transaction_type == "income":
            raise ValidationError("Income transactions cannot be categorized as expenses.")

        transaction.category = self._validate_category(new_category)
        if new_type is not None:
            if new_type not in {"fixed_expense", "variable_expense", "savings"}:
                raise ValidationError(
                    "new_type must be one of: fixed_expense, variable_expense, savings."
                )
            transaction.transaction_type = new_type

    def get_total_by_type(self, transaction_type: str) -> float:
        if transaction_type not in {
            "income",
            "fixed_expense",
            "variable_expense",
            "savings",
        }:
            raise ValidationError("Invalid transaction type.")
        return round(
            sum(t.amount for t in self.transactions if t.transaction_type == transaction_type),
            2,
        )

    def get_total_spending(self) -> float:
        return round(
            self.get_total_by_type("fixed_expense")
            + self.get_total_by_type("variable_expense"),
            2,
        )

    def get_total_spent_by_category(self, category: str) -> float:
        category = self._validate_category(category)
        return round(
            sum(
                t.amount
                for t in self.transactions
                if t.category == category
                and t.transaction_type in {"fixed_expense", "variable_expense"}
            ),
            2,
        )

    def get_remaining_budget_by_category(self, category: str) -> Optional[float]:
        category = self._validate_category(category)
        if category not in self.budget_limits:
            return None
        remaining = self.budget_limits[category] - self.get_total_spent_by_category(category)
        return round(remaining, 2)

    def get_savings_progress(self) -> Dict[str, float]:
        current_savings = self.get_total_by_type("savings")
        goal = self.savings_goal
        progress_percent = 100.0 if goal == 0 else round((current_savings / goal) * 100, 2)
        return {
            "current_savings": round(current_savings, 2),
            "savings_goal": round(goal, 2),
            "progress_percent": progress_percent,
            "remaining_to_goal": round(max(goal - current_savings, 0.0), 2),
        }

    def get_net_balance(self) -> float:
        income = self.get_total_by_type("income")
        spending = self.get_total_spending()
        savings = self.get_total_by_type("savings")
        return round(income - spending - savings, 2)

    def get_budget_alerts(self) -> List[str]:
        alerts: List[str] = []
        for category, limit in self.budget_limits.items():
            spent = self.get_total_spent_by_category(category)
            if spent > limit:
                alerts.append(
                    f"Alert: Category '{category}' exceeded its budget by {round(spent - limit, 2):.2f}."
                )
            elif limit > 0 and spent == limit:
                alerts.append(f"Notice: Category '{category}' has reached its budget limit.")
        return alerts

    def summary_report(self) -> Dict[str, Any]:
        category_summary: Dict[str, Dict[str, float]] = {}
        all_categories = set(self.budget_limits.keys()) | {
            t.category for t in self.transactions if t.transaction_type in {"fixed_expense", "variable_expense"}
        }

        for category in sorted(all_categories):
            spent = self.get_total_spent_by_category(category)
            limit = self.budget_limits.get(category)
            remaining = None if limit is None else round(limit - spent, 2)
            category_summary[category] = {
                "spent": round(spent, 2),
                "budget_limit": None if limit is None else round(limit, 2),
                "remaining": remaining,
            }

        return {
            "period": f"{self.year:04d}-{self.month:02d}",
            "income": self.get_total_by_type("income"),
            "fixed_expenses": self.get_total_by_type("fixed_expense"),
            "variable_expenses": self.get_total_by_type("variable_expense"),
