class PersonalFinanceApp:
    def __init__(self, user_name: str) -> None:
        if not isinstance(user_name, str) or not user_name.strip():
            raise ValidationError("user_name must be a non-empty string.")
        self.user_name = user_name.strip()
        self.monthly_budgets: Dict[str, MonthlyBudget] = {}

    @staticmethod
    def _make_key(year: int, month: int) -> str:
        if not isinstance(year, int) or year < 1:
            raise ValidationError("Year must be a positive integer.")
        if not isinstance(month, int) or not 1 <= month <= 12:
            raise ValidationError("Month must be an integer between 1 and 12.")
        return f"{year:04d}-{month:02d}"

    def create_monthly_budget(
        self,
        year: int,
        month: int,
        budget_limits: Optional[Dict[str, float]] = None,
        savings_goal: float = 0.0,
        overwrite: bool = False,
    ) -> MonthlyBudget:
        key = self._make_key(year, month)
        if key in self.monthly_budgets and not overwrite:
            raise ValidationError(f"Budget for {key} already exists.")
        budget = MonthlyBudget(
            year=year,
            month=month,
            budget_limits=budget_limits,
            savings_goal=savings_goal,
        )
        self.monthly_budgets[key] = budget
        return budget

    def get_monthly_budget(self, year: int, month: int) -> MonthlyBudget:
        key = self._make_key(year, month)
        if key not in self.monthly_budgets:
            raise ValidationError(f"No budget found for {key}.")
        return self.monthly_budgets[key]

    def add_transaction(
        self,
        year: int,
        month: int,
        amount: float,
        category: str,
        transaction_type: str,
        description: str = "",
        transaction_date: Optional[date] = None,
    ) -> Transaction:
        budget = self.get_monthly_budget(year, month)
        return budget.add_transaction(
            amount=amount,
            category=category,
            transaction_type=transaction_type,
            description=description,
            transaction_date=transaction_date,
        )

    def set_budget_limit(self, year: int, month: int, category: str, limit: float) -> None:
        budget = self.get_monthly_budget(year, month)
        budget.set_budget_limit(category, limit)

    def set_savings_goal(self, year: int, month: int, amount: float) -> None:
        budget = self.get_monthly_budget(year, month)
        budget.set_savings_goal(amount)

    def generate_monthly_report(self, year: int, month: int) -> Dict[str, Any]:
        budget = self.get_monthly_budget(year, month)
        report = budget.summary_report()
        report["user_name"] = self.user_name
        return report

    def generate_overall_report(self) -> Dict[str, Any]:
        monthly_reports = {
            key: self.monthly_budgets[key].summary_report()
            for key in sorted(self.monthly_budgets.keys())
        }

        total_income = round(sum(r["income"] for r in monthly_reports.values()), 2)
        total_spending = round(sum(r["total_spending"] for r in monthly_reports.values()), 2)
        total_savings = round(sum(r["savings"] for r in monthly_reports.values()), 2)
        total_net_balance = round(sum(r["net_balance"] for r in monthly_reports.values()), 2)

        return {
            "user_name": self.user_name,
            "months_tracked": len(self.monthly_budgets),
            "total_income": total_income,
            "total_spending": total_spending,
            "total_savings": total_savings,
            "total_net_balance": total_net_balance,
            "monthly_reports": monthly_reports,
        }


