import re


class Router:
    # Supported converters: regex pattern + value converter
    CONVERTERS = {
        'int': (r'\d+', int),
        'slug': (r'[A-Za-z0-9_-]+', str),
        'path': (r'.+', str),
    }

    def __init__(self):
        self._routes = []

    def add_route(self, pattern, handler):
        """Register a route pattern with a handler name."""
        regex_parts = ['^']
        converters = {}
        pos = 0

        # Find tokens like <int:id> or <slug>
        token_re = re.compile(r'<(?:(int|slug|path):)?([A-Za-z_][A-Za-z0-9_]*)>')

        for match in token_re.finditer(pattern):
            start, end = match.span()
            type_name, param_name = match.groups()
            type_name = type_name or 'slug'

            if type_name not in self.CONVERTERS:
                raise ValueError(f'Unsupported converter: {type_name}')

            # Escape literal text between tokens
            regex_parts.append(re.escape(pattern[pos:start]))
            regex_pattern, converter = self.CONVERTERS[type_name]
            regex_parts.append(f'(?P<{param_name}>{regex_pattern})')
            converters[param_name] = converter
            pos = end

        # Add remaining literal text and close regex
        regex_parts.append(re.escape(pattern[pos:]))
        regex_parts.append('$')
        compiled = re.compile(''.join(regex_parts))

        self._routes.append({
            'regex': compiled,
            'handler': handler,
            'converters': converters,
        })

    def match(self, url_path):
        """Return matched handler and converted params, or None."""
        for route in self._routes:
            match = route['regex'].match(url_path)
            if not match:
                continue

            params = {}
            for key, value in match.groupdict().items():
                params[key] = route['converters'][key](value)

            return {
                'handler': route['handler'],
                'params': params,
            }
        return None


if __name__ == '__main__':
    router = Router()
    router.add_route('/users/<int:id>', 'get_user')
    router.add_route('/files/<path:rest>', 'serve_file')
    router.add_route('/posts/<slug>', 'show_post')

    tests = [
        '/users/42',
        '/files/css/site/main.css',
        '/posts/hello-world_123',
        '/users/not-a-number',
    ]

    for path in tests:
        print(path, '->', router.match(path))

from typing import Iterable, Iterator, List


def filter_by_level(lines: Iterable[str], level: str) -> Iterator[str]:
    """Yield messages from log lines that match the given level."""
    prefix = f"{level}:"
    for line in lines:
        if line.startswith(prefix):
            # Split only once to preserve colons in the message
            _, message = line.split(":", 1)
            yield message.strip()


def batch_items(items: Iterable[str], batch_size: int) -> Iterator[List[str]]:
    """Yield items in batches of the given size."""
    if batch_size <= 0:
        raise ValueError("batch_size must be greater than 0")

    batch = []
    for item in items:
        batch.append(item)
        if len(batch) == batch_size:
            yield batch
            batch = []

    # Yield any remaining items
    if batch:
        yield batch


def main() -> None:
    log_lines = [
        "INFO: Application started",
        "ERROR: Failed to connect to database",
        "WARNING: Low disk space",
        "ERROR: Timeout while reading response",
        "INFO: Retrying request",
        "ERROR: Invalid configuration detected",
    ]

    error_messages = filter_by_level(log_lines, "ERROR")
    error_batches = batch_items(error_messages, 2)

    for index, batch in enumerate(error_batches, start=1):
        print(f"Batch {index}: {batch}")


if __name__ == "__main__":
    main()

from itertools import combinations


def hamming_distance(a: bytes, b: bytes) -> int:
    """Return the number of differing bits between two byte strings."""
    if len(a) != len(b):
        raise ValueError("Inputs must have equal length")
    return sum((x ^ y).bit_count() for x, y in zip(a, b))


def english_score(data: bytes) -> float:
    """Heuristic score: rewards common English characters, penalizes unlikely bytes."""
    freq = {
        ord('e'): 12.7, ord('t'): 9.1, ord('a'): 8.2, ord('o'): 7.5,
        ord('i'): 7.0, ord('n'): 6.7, ord(' '): 13.0,
    }
    score = 0.0
    for b in data.lower():
        if b in freq:
            score += freq[b]
        elif 32 <= b <= 126 or b in (9, 10, 13):
            score += 0.2  # printable but less informative
        else:
            score -= 8.0  # strong penalty for non-printable bytes
    return score


def repeating_xor(data: bytes, key: bytes) -> bytes:
    return bytes(b ^ key[i % len(key)] for i, b in enumerate(data))


def guess_keysizes(cipher: bytes, max_keysize: int, top_n: int = 3) -> list[int]:
    """Rank key sizes by average normalized Hamming distance."""
    candidates = []
    for keysize in range(2, min(max_keysize, len(cipher) // 2) + 1):
        blocks = [cipher[i:i + keysize] for i in range(0, keysize * 6, keysize)]
        blocks = [b for b in blocks if len(b) == keysize]
        if len(blocks) < 4:
            continue
        distances = [hamming_distance(x, y) / keysize for x, y in combinations(blocks[:4], 2)]
        candidates.append((sum(distances) / len(distances), keysize))
    candidates.sort()
    return [k for _, k in candidates[:top_n]]


def break_single_byte_xor(block: bytes) -> tuple[int, float]:
    """Find the best single-byte XOR key for a block."""
    best_key, best_score = 0, float('-inf')
    for key in range(256):
        decoded = bytes(b ^ key for b in block)
        score = english_score(decoded)
        if score > best_score:
            best_key, best_score = key, score
    return best_key, best_score


def break_repeating_xor(cipher_hex: str, max_keysize: int = 40) -> dict:
    cipher = bytes.fromhex(cipher_hex)
    best_result = {"key": "", "plaintext": "", "score": float('-inf')}

    for keysize in guess_keysizes(cipher, max_keysize):
        key_bytes = bytearray()
        for i in range(keysize):
            block = cipher[i::keysize]  # transpose blocks
            key_byte, _ = break_single_byte_xor(block)
            key_bytes.append(key_byte)

        plaintext = repeating_xor(cipher, key_bytes)
        score = english_score(plaintext)
        if score > best_result["score"]:
            best_result = {
                "key": key_bytes.decode('latin1'),
                "plaintext": plaintext.decode('latin1'),
                "score": score,
            }

    return best_result


if __name__ == "__main__":
    message = (
        b"Cryptography basics include understanding XOR, key reuse, and frequency "
        b"analysis. This demo shows how repeating-key XOR can be attacked."
    )
    secret_key = b"ICE"
    cipher = repeating_xor(message, secret_key)
    cipher_hex = cipher.hex()

    result = break_repeating_xor(cipher_hex)
    print("Recovered key:", result["key"])
    print("Recovered plaintext:", result["plaintext"])

