class NoValidRecordsError(Exception):
    """Raised when a file contains no valid student records."""


def load_scores(path):
    """
    Read student scores from a file.

    Expected line format: name,score
    Returns: (scores_dict, errors_list)
    Raises: NoValidRecordsError if no valid records are found.
    """
    scores = {}
    errors = []

    try:
        with open(path, "r", encoding="utf-8") as file:
            for line_number, raw_line in enumerate(file, start=1):
                line = raw_line.strip()

                if not line:
                    continue  # Skip blank lines

                try:
                    name, score_text = [part.strip() for part in line.split(",", 1)]
                    if not name:
                        raise ValueError("missing name")

                    score = int(score_text)
                    scores[name] = score
                except ValueError as exc:
                    errors.append(f"Line {line_number}: {exc} -> {line!r}")
    except FileNotFoundError:
        errors.append(f"File not found: {path}")
    except OSError as exc:
        errors.append(f"Could not read file {path}: {exc}")

    if not scores:
        raise NoValidRecordsError("No valid student records were loaded.")

    return scores, errors


def main():
    path = "scores.txt"

    try:
        scores, errors = load_scores(path)
        print("Loaded scores:")
        for name, score in scores.items():
            print(f"- {name}: {score}")

        if errors:
            print("\nWarnings/errors:")
            for error in errors:
                print(f"- {error}")
    except NoValidRecordsError as exc:
        print(f"Failed to load scores: {exc}")


if __name__ == "__main__":
    main()

class MaxStack:
    def __init__(self):
        # Each item is stored as (value, current_max)
        self._data = []

    def push(self, x):
        current_max = x if not self._data else max(x, self._data[-1][1])
        self._data.append((x, current_max))

    def pop(self):
        if not self._data:
            return None
        return self._data.pop()[0]

    def max(self):
        return None if not self._data else self._data[-1][1]

    def is_empty(self):
        return not self._data


class MaxQueue:
    def __init__(self):
        # Queue implemented with two max-stacks
        self._in = MaxStack()
        self._out = MaxStack()

    def enqueue(self, x):
        self._in.push(x)

    def _transfer(self):
        while not self._in.is_empty():
            self._out.push(self._in.pop())

    def dequeue(self):
        if self._out.is_empty():
            self._transfer()
        return self._out.pop()

    def max(self):
        in_max = self._in.max()
        out_max = self._out.max()
        if in_max is None:
            return out_max
        if out_max is None:
            return in_max
        return max(in_max, out_max)


class MaxQueueStackProcessor:
    def __init__(self):
        self.queue = MaxQueue()
        self.stack = MaxStack()

    def process(self, operations):
        results = []

        for op in operations:
            command = op[0]

            if command == 'enqueue':
                self.queue.enqueue(op[1])
            elif command == 'dequeue':
                results.append(self.queue.dequeue())
            elif command == 'push':
                self.stack.push(op[1])
            elif command == 'pop':
                results.append(self.stack.pop())
            elif command == 'max_queue':
                results.append(self.queue.max())
            elif command == 'max_stack':
                results.append(self.stack.max())
            else:
                raise ValueError(f'Unknown operation: {command}')

        return results


# Example usage:
if __name__ == '__main__':
    ops = [
        ('enqueue', 3),
        ('enqueue', 1),
        ('max_queue',),
        ('dequeue',),
        ('max_queue',),
