import hashlib


class BloomFilter:
    def __init__(self, size, hash_count):
        self.size = size
        self.hash_count = hash_count
        self.bits = [0] * size

    def _hashes(self, item):
        """Generate multiple hash positions for the given string item."""
        item_bytes = item.encode('utf-8')
        for i in range(self.hash_count):
            data = item_bytes + str(i).encode('utf-8')
            digest = hashlib.sha256(data).hexdigest()
            yield int(digest, 16) % self.size

    def add(self, item):
        """Mark the item as present in the Bloom filter."""
        for position in self._hashes(item):
            self.bits[position] = 1

    def contains(self, item):
        """Return True if item may be present, False if definitely not."""
        return all(self.bits[position] == 1 for position in self._hashes(item))


if __name__ == '__main__':
