        print(f"{word}: {bloom.contains(word)}")

class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None


class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        self.root = self._insert(self.root, value)

    def _insert(self, node, value):
        if node is None:
            return Node(value)
        if value < node.value:
            node.left = self._insert(node.left, value)
        elif value > node.value:
            node.right = self._insert(node.right, value)
        return node  # Ignore duplicates

    def search(self, value):
        return self._search(self.root, value)

    def _search(self, node, value):
        if node is None:
            return False
        if value == node.value:
            return True
        if value < node.value:
            return self._search(node.left, value)
        return self._search(node.right, value)

    def delete(self, value):
        self.root = self._delete(self.root, value)

    def _delete(self, node, value):
        if node is None:
            return None

        if value < node.value:
            node.left = self._delete(node.left, value)
        elif value > node.value:
            node.right = self._delete(node.right, value)
        else:
            # Node found: handle deletion cases
            if node.left is None:
                return node.right
            if node.right is None:
                return node.left

            # Node with two children: replace with inorder successor
            successor = self._min_value_node(node.right)
            node.value = successor.value
            node.right = self._delete(node.right, successor.value)

        return node

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

    def inorder(self):
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, node, result):
        if node is not None:
            self._inorder(node.left, result)
            result.append(node.value)
            self._inorder(node.right, result)


if __name__ == '__main__':
    bst = BinarySearchTree()
    for value in [50, 30, 70, 20, 40, 60, 80]:
        bst.insert(value)

    print('In-order before deletion:', bst.inorder())
    print('Search 40:', bst.search(40))
    print('Search 90:', bst.search(90))

    bst.delete(50)  # Delete node with two children
    print('In-order after deleting 50:', bst.inorder())

def analyze_orders(orders):
    # Track unique completed items per customer
    customer_items = {}

    # Track all unique items from completed orders
    all_completed_items = set()

    # Track customers with at least one cancelled order
    cancelled_customers = set()

    for order in orders:
        customer = order.get('customer')
        items = order.get('items', [])
        status = order.get('status')

        if status == 'completed':
            # Ensure the customer has a set to collect unique items
            customer_items.setdefault(customer, set()).update(items)
            all_completed_items.update(items)
        elif status == 'cancelled':
            cancelled_customers.add(customer)

    # Convert customer item sets into counts
    customer_item_counts = {
        customer: len(items)
        for customer, items in customer_items.items()
    }

    return {
        'customer_item_counts': customer_item_counts,
        'all_completed_items': sorted(all_completed_items),
        'cancelled_customers': sorted(cancelled_customers)
    }


# Example usage
if __name__ == '__main__':
    sample_orders = [
        {'customer': 'Alice', 'items': ['laptop', 'mouse'], 'status': 'completed'},
        {'customer': 'Bob', 'items': ['keyboard'], 'status': 'cancelled'},
        {'customer': 'Alice', 'items': ['mouse', 'monitor'], 'status': 'completed'},
        {'customer': 'Cara', 'items': ['desk', 'lamp'], 'status': 'completed'},
        {'customer': 'Alice', 'items': ['chair'], 'status': 'cancelled'}
    ]

    result = analyze_orders(sample_orders)
    print(result)

import heapq
import sys


def top_longest_lines(file_path, limit=10):
    """Return the longest lines from a file using limited memory."""
    heap = []  # Min-heap of (length, line)

    with open(file_path, 'r', encoding='utf-8') as f:
        for raw_line in f:
            line = raw_line.rstrip('\n')
            item = (len(line), line)

            if len(heap) < limit:
                heapq.heappush(heap, item)
            elif item[0] > heap[0][0]:
                heapq.heapreplace(heap, item)

    # Sort longest lines in descending order by length, then alphabetically
    return sorted(heap, key=lambda x: (-x[0], x[1]))


def main():
    file_path = sys.stdin.readline().strip()
    if not file_path:
        print('No file path provided.', file=sys.stderr)
        return

    try:
        results = top_longest_lines(file_path)
        for length, line in results:
            print(f"{length}: {line}")
    except FileNotFoundError:
        print('File not found.', file=sys.stderr)
    except OSError as e:
        print(f'Error reading file: {e}', file=sys.stderr)


if __name__ == '__main__':
