import json
from pathlib import Path


class ConfigError(Exception):
    """Base class for configuration-related errors."""


class ConfigFileError(ConfigError):
    """Raised when the config file cannot be accessed."""


class ConfigParseError(ConfigError):
    """Raised when the config file contains invalid JSON."""


class ConfigValidationError(ConfigError):
    """Raised when the config data is missing fields or has invalid types."""


def fetch_config(path: str) -> dict:
    try:
        text = Path(path).read_text(encoding="utf-8")
    except OSError as exc:
        raise ConfigFileError(f"Unable to read config file: {path}") from exc

    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ConfigParseError(f"Invalid JSON in config file: {path}") from exc

    required = {
        "host": str,
        "port": int,
        "debug": bool,
    }

    if not isinstance(data, dict):
        raise ConfigValidationError("Configuration root must be a JSON object")

    missing = [key for key in required if key not in data]
    if missing:
        raise ConfigValidationError(f"Missing required keys: {', '.join(missing)}")

    wrong_types = [
        f"{key} must be {expected.__name__}"
        for key, expected in required.items()
        if not isinstance(data[key], expected)
    ]
    if wrong_types:
        raise ConfigValidationError("; ".join(wrong_types))

    return {key: data[key] for key in required}


def main() -> None:
    path = "config.json"
    try:
        config = fetch_config(path)
    except ConfigFileError as exc:
        print(f"File error: {exc}")
    except ConfigParseError as exc:
        print(f"Parse error: {exc}")
    except ConfigValidationError as exc:
        print(f"Validation error: {exc}")
    else:
        print("Loaded config:", config)


if __name__ == "__main__":
    main()

def nested_sum(data):
    """Recursively sum all integers in a nested list."""
    total = 0

    for item in data:
        if isinstance(item, list):
            # Recurse into sublists
            total += nested_sum(item)
        elif isinstance(item, int):
            total += item
        else:
            raise TypeError(f"Unsupported element type: {type(item).__name__}")

    return total


def main():
    values = [1, [2, 3], [4, [5, 6]], 7]
    result = nested_sum(values)
    print(f"Sum: {result}")


if __name__ == "__main__":
