def validate_profile(profile):
    """Validate a user profile dictionary against a simple schema."""
    errors = []

    # Check required fields
    required_fields = ["name", "age", "email"]
    for field in required_fields:
        if field not in profile:
            errors.append(f"Missing required field: {field}")

    # Stop early if required fields are missing
    if errors:
        return errors

    # Validate name
    if not isinstance(profile["name"], str) or not profile["name"].strip():
        errors.append("'name' must be a non-empty string")

    # Validate age
    if not isinstance(profile["age"], int) or not (0 <= profile["age"] <= 120):
        errors.append("'age' must be an integer between 0 and 120")

    # Validate email
    if not isinstance(profile["email"], str) or "@" not in profile["email"]:
        errors.append("'email' must be a valid email string containing '@'")

    return errors


