import json
from copy import deepcopy


def _deep_merge(base, override):
    """Recursively merge override into base and return the merged dict."""
    result = deepcopy(base)
    for key, value in override.items():
        if (
            key in result
            and isinstance(result[key], dict)
            and isinstance(value, dict)
        ):
            result[key] = _deep_merge(result[key], value)
        else:
            result[key] = deepcopy(value)
    return result


def _validate_config(config):
    required = {
        'host': str,
        'port': int,
        'debug': bool,
        'database': dict,
    }

    for key, expected_type in required.items():
        if key not in config:
            raise ValueError(f"Missing required config key: {key}")
        if not isinstance(config[key], expected_type):
            raise ValueError(
                f"Invalid type for '{key}': expected {expected_type.__name__}"
            )

    db_required = {'name': str, 'user': str, 'password': str}
    for key, expected_type in db_required.items():
        if key not in config['database']:
            raise ValueError(f"Missing required database config key: {key}")
        if not isinstance(config['database'][key], expected_type):
            raise ValueError(
                f"Invalid type for database '{key}': expected {expected_type.__name__}"
            )



def load_app_config(path, env=None):
    with open(path, 'r', encoding='utf-8') as f:
        raw = json.load(f)

    if not isinstance(raw, dict):
        raise ValueError('Top-level configuration must be a JSON object')

    base_config = {k: v for k, v in raw.items() if k != 'environments'}

    if env is not None:
        environments = raw.get('environments', {})
        if not isinstance(environments, dict):
            raise ValueError("'environments' must be an object if provided")
        if env not in environments:
            raise ValueError(f"Unknown environment: {env}")
        if not isinstance(environments[env], dict):
            raise ValueError(f"Environment override for '{env}' must be an object")
        base_config = _deep_merge(base_config, environments[env])

    _validate_config(base_config)
    return base_config


if __name__ == '__main__':
