from pydantic import BaseModel, EmailStr, Field, ValidationError, field_validator
import re


class UserRegistration(BaseModel):
    username: str = Field(min_length=3, max_length=20)
    email: EmailStr
    age: int = Field(ge=18, le=120)
    referral_code: Optional[str] = None

    @field_validator('username')
    @classmethod
    def validate_username(cls, value: str) -> str:
        value = value.strip()
        if not re.fullmatch(r'\w+', value):
            raise ValueError('username must contain only letters, numbers, and underscores')
        return value

    @field_validator('referral_code')
    @classmethod
    def validate_referral_code(cls, value: Optional[str]) -> Optional[str]:
        if value is None:
            return value
        value = value.strip()
        if not re.fullmatch(r'[A-Z0-9]{6}', value):
            raise ValueError('referral_code must be exactly 6 uppercase letters or digits')
        return value


def validate_registrations(records: List[Dict[str, Any]]) -> Dict[str, List[Dict[str, Any]]]:
    valid = []
    errors = []

    for index, record in enumerate(records):
        try:
            user = UserRegistration(**record)
            valid.append(user.model_dump())
        except ValidationError as exc:
            errors.append({
                'index': index,
                'messages': [err['msg'] for err in exc.errors()]
            })

    return {'valid': valid, 'errors': errors}


