from typing import Callable, Dict, Iterable, Iterator, Optional, TypeVar, Any

T = TypeVar('T')
U = TypeVar('U')


def take(n: int, iterable: Iterable[T]) -> Iterator[T]:
    """Lazily yield at most n items from iterable."""
    if n <= 0:
        return
    count = 0
    for item in iterable:
        if count >= n:
            break
        yield item
        count += 1


def lazy_filter_map(
    records: Iterable[Dict[str, Any]],
    predicate: Callable[[Dict[str, Any]], bool],
    transform: Callable[[Dict[str, Any]], U],
    limit: Optional[int] = None,
) -> Iterator[U]:
    """Lazily filter and transform records, optionally stopping after limit outputs."""
    yielded = 0
    for record in records:
        if predicate(record):
            yield transform(record)
            yielded += 1
            if limit is not None and yielded >= limit:
                return


def generate_logs() -> Iterator[Dict[str, Any]]:
    """Simulate a stream of log records produced on demand."""
    levels = ['INFO', 'DEBUG', 'ERROR', 'WARNING', 'ERROR', 'INFO', 'ERROR']
    messages = [
        'startup complete',
        'cache warmup',
        'database timeout',
        'disk space low',
        'invalid auth token',
        'heartbeat ok',
        'queue processing failed',
    ]
    for i, (level, message) in enumerate(zip(levels, messages), start=1):
        print(f'Producing log #{i}')  # Shows laziness during iteration
        yield {'id': i, 'level': level, 'message': message}


def main() -> None:
    records = generate_logs()

    errors = lazy_filter_map(
        records,
        predicate=lambda r: r['level'] == 'ERROR',
        transform=lambda r: f"ERROR#{r['id']}: {r['message'].upper()}",
    )

    first_three = list(take(3, errors))
    print(first_three)


if __name__ == '__main__':
