from collections import defaultdict


class Event:
    """Base class for all events."""
    pass


class UserCreated(Event):
    def __init__(self, username: str):
        self.username = username


class OrderPlaced(Event):
    def __init__(self, order_id: int, total: float):
        self.order_id = order_id
        self.total = total


class EventBus:
    def __init__(self):
        # Maps event classes to subscribed handlers.
        self._handlers = defaultdict(list)

    def subscribe(self, event_type, handler):
        if handler not in self._handlers[event_type]:
            self._handlers[event_type].append(handler)

    def unsubscribe(self, event_type, handler):
        if handler in self._handlers[event_type]:
            self._handlers[event_type].remove(handler)

    def publish(self, event: Event):
        called = set()
        # Walk the MRO so base-class subscriptions also receive subclass events.
        for cls in type(event).__mro__:
            if not issubclass(cls, Event):
                continue
            for handler in self._handlers.get(cls, []):
                if handler not in called:
                    handler(event)
                    called.add(handler)


def log_all(event: Event):
    print(f"LOG: received {type(event).__name__}")


def welcome_user(event: UserCreated):
    print(f"Welcome, {event.username}!")


def process_order(event: OrderPlaced):
    print(f"Processing order #{event.order_id} for ${event.total:.2f}")


bus = EventBus()
bus.subscribe(Event, log_all)
bus.subscribe(UserCreated, welcome_user)
bus.subscribe(OrderPlaced, process_order)

bus.publish(UserCreated("alice"))
bus.publish(OrderPlaced(101, 59.99))

bus.unsubscribe(Event, log_all)
print("-- after unsubscribe --")
bus.publish(UserCreated("bob"))

import time
from typing import Any, Dict, List, Optional

import requests
from requests import Response
from requests.exceptions import RequestException


class APIClientError(Exception):
    """Raised when the API client encounters a non-recoverable error."""


def _parse_retry_after(response: Response) -> Optional[float]:
    value = response.headers.get("Retry-After")
    if not value:
        return None
    try:
        return max(0.0, float(value))
    except ValueError:
        return None


def _get_with_retries(session: requests.Session, url: str, headers: Dict[str, str], max_retries: int = 3) -> Response:
    last_error = None
    for attempt in range(max_retries + 1):
        try:
            response = session.get(url, headers=headers, timeout=10)
        except RequestException as exc:
            last_error = exc
            if attempt == max_retries:
                raise APIClientError(f"Request failed after retries: {exc}") from exc
            time.sleep(2 ** attempt)
            continue

        if response.status_code == 429 or 500 <= response.status_code < 600:
            if attempt == max_retries:
                raise APIClientError(f"Retriable HTTP error after retries: {response.status_code} {response.text}")
            delay = _parse_retry_after(response)
            time.sleep(delay if delay is not None else 2 ** attempt)
            continue

        if 400 <= response.status_code < 500:
            raise APIClientError(f"Non-retriable HTTP error: {response.status_code} {response.text}")

        return response

    raise APIClientError(f"Unexpected retry failure: {last_error}")


def fetch_all_items(base_url: str, token: str) -> List[Any]:
    headers = {
        "Authorization": f"Bearer {token}",
        "Accept": "application/json",
    }
    items: List[Any] = []
    next_url: Optional[str] = base_url

    with requests.Session() as session:
        while next_url:
            response = _get_with_retries(session, next_url, headers)
            try:
                payload = response.json()
            except ValueError as exc:
                raise APIClientError("Response was not valid JSON") from exc

            if not isinstance(payload, dict):
                raise APIClientError("Malformed response: expected a JSON object")
            if "items" not in payload or "next" not in payload:
                raise APIClientError("Malformed response: missing 'items' or 'next' fields")
            if not isinstance(payload["items"], list):
                raise APIClientError("Malformed response: 'items' must be a list")
            if payload["next"] is not None and not isinstance(payload["next"], str):
                raise APIClientError("Malformed response: 'next' must be a string or null")

            items.extend(payload["items"])
            next_url = payload["next"]

    return items

def fib(n, cache):
    # Return cached result if already computed
    if n in cache:
        return cache[n]

    # Compute and store the result in the cache
    cache[n] = fib(n - 1, cache) + fib(n - 2, cache)
    return cache[n]


def main():
    # Base cases are pre-filled in the cache
    cache = {0: 0, 1: 1}

    print('Fibonacci numbers from 0 to 10:')
    for i in range(11):
        print(f'fib({i}) = {fib(i, cache)}')

    print('\nCache contents:')
    for key in sorted(cache):
        print(f'{key}: {cache[key]}')


if __name__ == '__main__':
    main()

from collections import OrderedDict
from typing import Callable, Dict


class PluginManager:
    def __init__(self) -> None:
        # Preserve registration order for deterministic processing.
        self._plugins: Dict[str, Callable[[str], str]] = OrderedDict()
        self._enabled: Dict[str, bool] = {}

    def register(self, name: str, plugin: Callable[[str], str]) -> None:
        if name in self._plugins:
            raise ValueError(f"Plugin '{name}' is already registered")
        if not callable(plugin):
            raise ValueError("Plugin must be callable")
        self._plugins[name] = plugin
        self._enabled[name] = True

    def enable(self, name: str) -> None:
        if name not in self._plugins:
            raise ValueError(f"Unknown plugin: '{name}'")
        self._enabled[name] = True

    def disable(self, name: str) -> None:
        if name not in self._plugins:
            raise ValueError(f"Unknown plugin: '{name}'")
        self._enabled[name] = False

    def process(self, text: str) -> str:
        result = text
        for name, plugin in self._plugins.items():
            if self._enabled[name]:
                result = plugin(result)
        return result


# Example plugins

def strip_spaces(text: str) -> str:
    return text.strip()


def to_upper(text: str) -> str:
    return text.upper()


def add_prefix(text: str) -> str:
    return f"[PROCESSED] {text}"


if __name__ == "__main__":
    manager = PluginManager()
    manager.register("strip", strip_spaces)
    manager.register("upper", to_upper)
    manager.register("prefix", add_prefix)

    # Disable one plugin to demonstrate runtime control.
    manager.disable("upper")

    input_text = "   plugin systems are powerful   "
    output_text = manager.process(input_text)
    print(output_text)

    manager.enable("upper")
    print(manager.process(input_text))

