from dataclasses import dataclass, replace
from typing import Any, Mapping


@dataclass(frozen=True)
class AppConfig:
    host: str
    port: int
    debug: bool
    tags: tuple[str, ...]

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "AppConfig":
        return cls(
            host=cls._parse_host(data.get("host")),
            port=cls._parse_port(data.get("port")),
            debug=cls._parse_debug(data.get("debug")),
            tags=cls._parse_tags(data.get("tags", ())),
        )

    def merge(self, overrides: Mapping[str, Any]) -> "AppConfig":
        updates: dict[str, Any] = {}
        if "host" in overrides:
            updates["host"] = self._parse_host(overrides["host"])
        if "port" in overrides:
            updates["port"] = self._parse_port(overrides["port"])
        if "debug" in overrides:
            updates["debug"] = self._parse_debug(overrides["debug"])
        if "tags" in overrides:
            updates["tags"] = self._parse_tags(overrides["tags"])
        return replace(self, **updates)

    @staticmethod
    def _parse_host(value: Any) -> str:
        if not isinstance(value, str) or not value.strip():
            raise ValueError("host must be a non-empty string")
        return value.strip()

    @staticmethod
    def _parse_port(value: Any) -> int:
        if isinstance(value, int) and not isinstance(value, bool):
            port = value
        elif isinstance(value, str) and value.strip().isdigit():
            port = int(value.strip())
        else:
            raise ValueError("port must be an integer or numeric string")
        if not (1 <= port <= 65535):
            raise ValueError("port must be between 1 and 65535")
        return port

    @staticmethod
    def _parse_debug(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            normalized = value.strip().lower()
            if normalized == "true":
                return True
            if normalized == "false":
                return False
        raise ValueError("debug must be a bool or 'true'/'false'")

    @staticmethod
    def _parse_tags(value: Any) -> tuple[str, ...]:
        if isinstance(value, str):
            parts = [part.strip() for part in value.split(",")]
            return tuple(tag for tag in parts if tag)
        if isinstance(value, list):
            if not all(isinstance(item, str) for item in value):
                raise ValueError("tags list must contain only strings")
            return tuple(item.strip() for item in value if item.strip())
        if isinstance(value, tuple) and all(isinstance(item, str) for item in value):
            return tuple(item.strip() for item in value if item.strip())
        raise ValueError("tags must be a list of strings or a comma-separated string")


