from dataclasses import dataclass, fields, MISSING
from typing import Any, Optional, Union, get_args, get_origin, get_type_hints


@dataclass
class Schema:
    @classmethod
    def from_dict(cls, data: dict):
        if not isinstance(data, dict):
            raise ValueError(f"Expected dict for {cls.__name__}, got {type(data).__name__}")

        hints = get_type_hints(cls)
        values = {}

        for f in fields(cls):
            name = f.name
            expected_type = hints[name]

            if name not in data:
                if f.default is not MISSING or f.default_factory is not MISSING:
                    continue  # dataclass will apply default
                raise ValueError(f"Missing required field: {cls.__name__}.{name}")

            values[name] = cls._validate_value(data[name], expected_type, f"{cls.__name__}.{name}")

        return cls(**values)

    @staticmethod
    def _validate_value(value: Any, expected_type: Any, path: str):
        origin = get_origin(expected_type)
        args = get_args(expected_type)

        # Optional[T] / Union[T, None]
        if origin is Union and type(None) in args:
            non_none = [t for t in args if t is not type(None)]
            if value is None:
                return None
            return Schema._validate_value(value, non_none[0], path)

        # list[T]
        if origin is list:
            if not isinstance(value, list):
                raise ValueError(f"{path}: expected list, got {type(value).__name__}")
            item_type = args[0] if args else Any
            return [Schema._validate_value(item, item_type, f"{path}[{i}]") for i, item in enumerate(value)]

        # Nested schema
        if isinstance(expected_type, type) and issubclass(expected_type, Schema):
            if not isinstance(value, dict):
                raise ValueError(f"{path}: expected dict for nested schema, got {type(value).__name__}")
            return expected_type.from_dict(value)

        # Any accepts everything
        if expected_type is Any:
            return value

        # Primitive / regular class checks
        if not isinstance(value, expected_type):
            raise ValueError(f"{path}: expected {expected_type.__name__}, got {type(value).__name__}")
        return value


@dataclass
class AddressSchema(Schema):
    street: str
    city: str
    zip_code: str


