class RegistrationError(Exception):
    """Base exception for registration validation errors."""


class UsernameError(RegistrationError):
    """Raised when the username is invalid."""


class EmailError(RegistrationError):
    """Raised when the email is invalid."""


class PasswordError(RegistrationError):
    """Raised when the password is invalid."""


def validate_registration(username, email, password):
    """Validate registration data and return cleaned values."""
    username = username.strip()
    email = email.strip().lower()

    if len(username) < 3:
        raise UsernameError("Username must be at least 3 characters long.")
    if not username.isalnum():
        raise UsernameError("Username must contain only letters and numbers.")

    if email.count("@") != 1:
        raise EmailError("Email must contain exactly one '@' symbol.")
    local_part, domain_part = email.split("@")
    if not local_part or "." not in domain_part:
        raise EmailError("Email must have a valid domain with a dot.")

    if len(password) < 8:
        raise PasswordError("Password must be at least 8 characters long.")
    if not any(char.isdigit() for char in password):
        raise PasswordError("Password must contain at least one digit.")

    return {
        "username": username,
        "email": email,
        "password": password,
    }


if __name__ == "__main__":
    samples = [
        ("ab", "user@example.com", "secret123"),
        ("john_doe", "john@example.com", "pass1234"),
        ("Alice1", "aliceexample.com", "password1"),
