class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        return True


def max_bottleneck_queries(n, edges, queries):
    # Build maximum spanning forest with Kruskal.
    dsu = DSU(n)
    graph = [[] for _ in range(n)]
    for u, v, w in sorted(edges, key=lambda e: -e[2]):
        if dsu.union(u, v):
            graph[u].append((v, w))
            graph[v].append((u, w))

    # Binary lifting tables.
    log = max(1, n.bit_length())
    up = [[-1] * n for _ in range(log)]
    mn = [[float('inf')] * n for _ in range(log)]
    depth = [-1] * n
    comp = [-1] * n

    # BFS each tree in the forest.
    comp_id = 0
    for start in range(n):
        if depth[start] != -1:
            continue
        depth[start] = 0
        comp[start] = comp_id
        q = deque([start])
        while q:
            u = q.popleft()
            for v, w in graph[u]:
                if depth[v] == -1:
                    depth[v] = depth[u] + 1
                    comp[v] = comp_id
                    up[0][v] = u
                    mn[0][v] = w
                    q.append(v)
        comp_id += 1

    # Precompute ancestors and minimum edge weights to ancestors.
    for k in range(1, log):
        for v in range(n):
            p = up[k - 1][v]
            if p != -1:
                up[k][v] = up[k - 1][p]
                mn[k][v] = min(mn[k - 1][v], mn[k - 1][p])

    def query(a, b):
        if comp[a] != comp[b]:
            return -1
        if a == b:
            return float('inf')

        ans = float('inf')
        if depth[a] < depth[b]:
            a, b = b, a

        # Lift a to depth of b.
        diff = depth[a] - depth[b]
        for k in range(log):
            if diff & (1 << k):
                ans = min(ans, mn[k][a])
                a = up[k][a]

        if a == b:
            return ans

        # Lift both until just below LCA.
        for k in range(log - 1, -1, -1):
            if up[k][a] != up[k][b]:
                ans = min(ans, mn[k][a], mn[k][b])
                a = up[k][a]
                b = up[k][b]

        # Include final step to LCA.
        ans = min(ans, mn[0][a], mn[0][b])
        return ans

    result = []
    for a, b in queries:
        val = query(a, b)
        result.append(-1 if val == float('inf') and a != b else val)
    return result


# Example usage:
if __name__ == "__main__":
    n = 6
    edges = [
        (0, 1, 5), (1, 2, 3), (0, 2, 4),
        (2, 3, 6), (3, 4, 2), (4, 5, 7)
    ]
    queries = [(0, 3), (1, 5), (0, 5), (0, 0)]
    print(max_bottleneck_queries(n, edges, queries))

