from dataclasses import dataclass, field
from typing import List


@dataclass
class Book:
    title: str
    author: str
    year: int
    available_copies: int = 1


@dataclass
class Library:
    books: List[Book] = field(default_factory=list)

    def add_book(self, book: Book) -> None:
        """Add a book to the library catalog."""
        self.books.append(book)

    def find_by_author(self, author: str) -> List[Book]:
        """Return all books written by the given author."""
        return [book for book in self.books if book.author.lower() == author.lower()]

    def borrow_book(self, title: str) -> bool:
        """Borrow a book if a copy is available; return True on success."""
        for book in self.books:
            if book.title.lower() == title.lower() and book.available_copies > 0:
                book.available_copies -= 1
                return True
        return False


