from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Iterable, List


class PaymentStrategy(ABC):
    """Strategy interface for different payment methods."""

    @abstractmethod
    def pay(self, amount: float) -> str:
        pass


class CreditCardPayment(PaymentStrategy):
    def __init__(self, card_holder: str, last4: str) -> None:
        self.card_holder = card_holder
        self.last4 = last4

    def pay(self, amount: float) -> str:
        return f"Charged ${amount:.2f} to credit card ending in {self.last4} for {self.card_holder}."


class PayPalPayment(PaymentStrategy):
    def __init__(self, email: str) -> None:
        self.email = email

    def pay(self, amount: float) -> str:
        return f"Processed PayPal payment of ${amount:.2f} using account {self.email}."


class CryptoPayment(PaymentStrategy):
    def __init__(self, wallet_address: str, coin: str = "BTC") -> None:
        self.wallet_address = wallet_address
        self.coin = coin

    def pay(self, amount: float) -> str:
        masked = f"{self.wallet_address[:6]}...{self.wallet_address[-4:]}"
        return f"Sent ${amount:.2f} equivalent in {self.coin} from wallet {masked}."


class Checkout:
    """Context that uses a payment strategy to process a cart."""

    def __init__(self, strategy: PaymentStrategy) -> None:
        self._strategy = strategy

    def set_strategy(self, strategy: PaymentStrategy) -> None:
        self._strategy = strategy

    def process_cart(self, item_prices: Iterable[float]) -> str:
        prices: List[float] = list(item_prices)
        if any(price < 0 for price in prices):
            raise ValueError("Item prices cannot be negative.")

        total = sum(prices)
        return self._strategy.pay(total)


