class Node:
    def __init__(self, key, left=None, right=None):
        self.key = key
        self.left = left
        self.right = right


def is_valid_bst(node, low=float('-inf'), high=float('inf')):
    """Validate BST using range constraints."""
    if not node:
        return True
    if not (low < node.key < high):
        return False
    return (
        is_valid_bst(node.left, low, node.key) and
        is_valid_bst(node.right, node.key, high)
    )


def find_min(node):
    """Return the node with the smallest key in a subtree."""
    while node.left:
        node = node.left
    return node


def delete_node(root, key):
    """Delete a single key from the BST and return new root."""
    if not root:
        return None

    if key < root.key:
        root.left = delete_node(root.left, key)
    elif key > root.key:
        root.right = delete_node(root.right, key)
    else:
        # Node with only one child or no child
        if not root.left:
            return root.right
        if not root.right:
            return root.left

        # Node with two children: replace with inorder successor
        successor = find_min(root.right)
        root.key = successor.key
        root.right = delete_node(root.right, successor.key)

    return root


def delete_range(root, low, high):
    """Remove all nodes with low <= key <= high while preserving BST."""
    if not root:
        return None

    root.left = delete_range(root.left, low, high)
    root.right = delete_range(root.right, low, high)

    if low <= root.key <= high:
        return delete_node(root, root.key)
    return root


def inorder(node):
    """Return in-order traversal as a list."""
    if not node:
        return []
    return inorder(node.left) + [node.key] + inorder(node.right)


# Example usage
if __name__ == '__main__':
    # Construct a BST manually
    root = Node(10,
        Node(5,
            Node(3),
            Node(7)
        ),
        Node(15,
            Node(12),
            Node(18)
        )
    )

    if not is_valid_bst(root):
        raise ValueError('Input tree is not a valid BST')

    root = delete_range(root, 6, 15)
    print(inorder(root))  # Output: [3, 5, 18]

