class PositiveNumber:
    """Descriptor that ensures assigned values are positive numbers."""

    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, (int, float)):
            raise ValueError(f"{self.private_name[1:]} must be a number")
        if value <= 0:
            raise ValueError(f"{self.private_name[1:]} must be positive")
        setattr(instance, self.private_name, float(value))


class Product:
    price = PositiveNumber()
    weight = PositiveNumber()

    def __init__(self, name, price, weight):
        self.name = name
        self.price = price
        self.weight = weight
        self._discount_percent = 0.0

    @property
    def shipping_cost(self):
        """Read-only computed property based on weight."""
        return self.weight * 1.5

    @property
    def discounted_price(self):
        """Return price after applying the current discount percentage."""
        return self.price * (1 - self._discount_percent / 100)

    @discounted_price.setter
    def discounted_price(self, percent):
        """Set the discount percentage (0 to 100)."""
        if not isinstance(percent, (int, float)):
            raise ValueError("discount percentage must be a number")
        if not 0 <= percent <= 100:
            raise ValueError("discount percentage must be between 0 and 100")
        self._discount_percent = float(percent)


