from itertools import islice

LEVELS = {
    'DEBUG': 10,
    'INFO': 20,
    'WARNING': 30,
    'ERROR': 40,
    'CRITICAL': 50,
}


def parse_line(line):
    """Parse a single log line into a dictionary, or return None if invalid."""
    parts = line.rstrip('\n').split('|', 2)
    if len(parts) != 3:
        return None

    level, timestamp, message = parts
    level = level.strip().upper()
    if level not in LEVELS:
        return None

    return {
        'level': level,
        'timestamp': timestamp.strip(),
        'message': message.strip(),
    }


def lazy_log_pipeline(lines, min_level, keyword):
    """Lazily filter and transform log lines into structured records."""
    min_value = LEVELS[min_level.upper()]
    keyword = keyword.lower()

    for line in lines:
        record = parse_line(line)
        if record is None:
            continue
        if LEVELS[record['level']] < min_value:
            continue
        if keyword not in record['message'].lower():
            continue
        yield record


def take(iterable, n):
    """Collect the first n items from an iterable without consuming the rest."""
    return list(islice(iterable, n))


if __name__ == '__main__':
    logs = [
        'DEBUG|2024-01-01T10:00:00|startup complete',
