import json
import os
import re
from copy import deepcopy

PLACEHOLDER_RE = re.compile(r"\$\{([A-Z0-9_]+)\}")


def load_config(path, env_prefix='APP_'):
    """Load JSON config, resolve ${VAR} placeholders, and apply env overrides."""
    if not os.path.exists(path):
        raise FileNotFoundError(f'Config file not found: {path}')

    try:
        with open(path, 'r', encoding='utf-8') as f:
            config = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f'Invalid JSON in config file: {e}') from e

    config = deepcopy(config)
    _resolve_placeholders(config)
    _apply_env_overrides(config, env_prefix)
    _ensure_no_placeholders(config)
    return config


def _resolve_placeholders(value):
    if isinstance(value, dict):
        for k, v in value.items():
            value[k] = _resolve_placeholders(v)
        return value
    if isinstance(value, list):
        for i, item in enumerate(value):
            value[i] = _resolve_placeholders(item)
        return value
    if isinstance(value, str):
        def repl(match):
            var_name = match.group(1)
            return os.environ.get(var_name, match.group(0))
        return PLACEHOLDER_RE.sub(repl, value)
    return value


def _apply_env_overrides(config, env_prefix):
    for env_key, env_value in os.environ.items():
        if not env_key.startswith(env_prefix):
            continue
        path = env_key[len(env_prefix):].split('__')
        if not all(path):
            continue
        _set_nested(config, path, _parse_scalar(env_value))



def _set_nested(obj, path, value):
    current = obj
    for key in path[:-1]:
        if key not in current or not isinstance(current[key], dict):
            current[key] = {}
        current = current[key]
    current[path[-1]] = value



def _parse_scalar(value):
    lowered = value.lower()
    if lowered == 'true':
        return True
    if lowered == 'false':
        return False
    if lowered == 'null':
        return None
    try:
        if '.' in value:
            return float(value)
        return int(value)
    except ValueError:
        return value



def _ensure_no_placeholders(value):
    if isinstance(value, dict):
        for v in value.values():
            _ensure_no_placeholders(v)
    elif isinstance(value, list):
        for item in value:
            _ensure_no_placeholders(item)
    elif isinstance(value, str) and PLACEHOLDER_RE.search(value):
        raise ValueError(f'Unresolved placeholder found: {value}')


if __name__ == '__main__':
    # Example usage:
    # export DB_HOST=prod-db
    # export APP_database__port=5433
    cfg = load_config('config.json')
    print(json.dumps(cfg, indent=2))

class ConnectionFSM:
    # State constants
    DISCONNECTED = "DISCONNECTED"
    CONNECTING = "CONNECTING"
    CONNECTED = "CONNECTED"
    RETRY_WAIT = "RETRY_WAIT"
    CLOSED = "CLOSED"

    def __init__(self):
        self.state = self.DISCONNECTED
        self.failures = 0
        self.history = []

        # Table-driven transitions: state -> event -> next_state
        self.transitions = {
            self.DISCONNECTED: {
                "connect": self.CONNECTING,
                "close": self.CLOSED,
            },
            self.CONNECTING: {
                "success": self.CONNECTED,
                "fail": self.RETRY_WAIT,
                "timeout": self.RETRY_WAIT,
                "disconnect": self.DISCONNECTED,
                "close": self.CLOSED,
            },
            self.CONNECTED: {
                "disconnect": self.DISCONNECTED,
                "close": self.CLOSED,
            },
            self.RETRY_WAIT: {
                "retry": self.CONNECTING,
                "disconnect": self.DISCONNECTED,
                "close": self.CLOSED,
            },
            self.CLOSED: {},
        }

    def trigger(self, event):
        """Apply an event to the FSM and update state/history."""
        state_transitions = self.transitions.get(self.state, {})
        if event not in state_transitions:
            valid = sorted(state_transitions.keys())
            raise ValueError(
                f"Invalid event '{event}' for state '{self.state}'. Valid events: {valid}"
            )

        old_state = self.state
        new_state = state_transitions[event]

        # Side effect: count connection failures only while connecting
        if old_state == self.CONNECTING and event in {"fail", "timeout"}:
            self.failures += 1

        self.state = new_state
        self.history.append((old_state, event, new_state))
        return new_state


if __name__ == "__main__":
    fsm = ConnectionFSM()

    # Example lifecycle with retries and eventual success
    events = ["connect", "fail", "retry", "timeout", "retry", "success", "disconnect", "close"]

    for event in events:
        fsm.trigger(event)

    print("Final state:", fsm.state)
    print("Failure count:", fsm.failures)
    print("History:")
    for step in fsm.history:
        print(step)

