    def send(self, recipient: str, message: str) -> str:
        return f"EMAIL to {recipient}: {message}"


class SMSChannel(NotificationChannel):
    @property
    def name(self) -> str:
        return "sms"

    def send(self, recipient: str, message: str) -> str:
        return f"SMS to {recipient}: {message}"


class NotificationManager:
    def __init__(self, channels: list[NotificationChannel]):
        self._channels: dict[str, NotificationChannel] = {}
        for channel in channels:
            if channel.name in self._channels:
                raise ValueError(f"Duplicate channel name: {channel.name}")
            self._channels[channel.name] = channel

    def broadcast(self, recipients_by_channel: dict[str, list[str]], message: str) -> dict[str, list[str]]:
        results: dict[str, list[str]] = {}

        for channel_name, recipients in recipients_by_channel.items():
            channel = self._channels.get(channel_name)
            if channel is None:
                # Ignore unknown channels not registered in the manager.
                continue

            results[channel_name] = [channel.send(recipient, message) for recipient in recipients]

        return results


