from collections import deque


def sliding_window(iterable, size):
    """Yield consecutive windows of length `size` from `iterable` lazily."""
    if size < 1:
        raise ValueError("size must be at least 1")

    it = iter(iterable)
    window = deque(maxlen=size)

    # Fill the first window
    for _ in range(size):
        try:
            window.append(next(it))
        except StopIteration:
            return  # Not enough items for one full window

    yield tuple(window)

    # Slide the window one item at a time
    for item in it:
        window.append(item)
        yield tuple(window)


def main():
    # Example with a list
    numbers = [1, 2, 3, 4, 5]
    print("Windows from list:")
    for w in sliding_window(numbers, 3):
        print(w)

    # Example with a generator
    squares = (i * i for i in range(6))
    print("\nWindows from generator:")
    for w in sliding_window(squares, 2):
        print(w)


