def validate_user_record(record):
    """Validate a user record against a simple schema."""
    errors = []

    # Record must be a dictionary
    if not isinstance(record, dict):
        return {"valid": False, "errors": ["Record must be a dictionary"]}

    # Required fields
    required_fields = ["id", "name", "email"]
    for field in required_fields:
        if field not in record:
            errors.append(f"Missing required field: {field}")

    # Validate id
    if "id" in record:
        if not isinstance(record["id"], int) or isinstance(record["id"], bool) or record["id"] <= 0:
            errors.append("'id' must be a positive integer")

    # Validate name
    if "name" in record:
        if not isinstance(record["name"], str) or not record["name"].strip():
            errors.append("'name' must be a non-empty string")

    # Validate email
    if "email" in record:
        email = record["email"]
        if not isinstance(email, str) or email.count("@") != 1:
            errors.append("'email' must be a string containing exactly one '@'")

    # Validate optional age
    if "age" in record:
        age = record["age"]
        if not isinstance(age, int) or isinstance(age, bool) or not (0 <= age <= 120):
            errors.append("'age' must be an integer between 0 and 120")

    # Validate optional tags
    if "tags" in record:
        tags = record["tags"]
        if not isinstance(tags, list):
            errors.append("'tags' must be a list of strings")
        elif not all(isinstance(tag, str) for tag in tags):
            errors.append("'tags' must be a list of strings")

    return {"valid": len(errors) == 0, "errors": errors}


