from pathlib import Path
import json
from datetime import datetime


def build_txt_report(root_dir: str, output_file: str) -> int:
    """Scan root_dir recursively for .txt files and write a JSON report."""
    root = Path(root_dir).resolve()
    output = Path(output_file).resolve()

    if not root.exists() or not root.is_dir():
        raise ValueError(f"Invalid root directory: {root}")

    records = []

    # Walk through all items under the root directory.
    for path in root.rglob("*"):
        try:
            if path.is_file() and path.suffix.lower() == ".txt":
                stat = path.stat()
                records.append({
                    "relative_path": str(path.relative_to(root)),
                    "size_bytes": stat.st_size,
                    "modified_time": datetime.fromtimestamp(stat.st_mtime).isoformat()
                })
        except (PermissionError, OSError):
            # Skip files that cannot be accessed.
            continue

    # Ensure the output directory exists.
    output.parent.mkdir(parents=True, exist_ok=True)

    report = {
        "root_directory": str(root),
        "text_file_count": len(records),
        "files": sorted(records, key=lambda item: item["relative_path"])
    }

    with output.open("w", encoding="utf-8") as f:
        json.dump(report, f, indent=2)

    return len(records)


if __name__ == "__main__":
    root_dir = input("Enter the root directory to scan: ").strip()
    output_file = input("Enter the output JSON file path: ").strip()

    try:
        count = build_txt_report(root_dir, output_file)
        print(f"Report saved successfully. Recorded {count} text file(s).")
    except ValueError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")

