from pydantic import BaseModel, ConfigDict, EmailStr, ValidationError, field_validator, model_validator


class WebhookData(BaseModel):
    model_config = ConfigDict(extra='forbid')

    amount: int
    currency: str
    customer_email: EmailStr
    failure_code: Optional[str] = None

    @field_validator('amount')
    @classmethod
    def validate_amount(cls, value: int) -> int:
        if value <= 0:
            raise ValueError('amount must be a positive integer')
        return value

    @field_validator('currency')
    @classmethod
    def validate_currency(cls, value: str) -> str:
        if len(value) != 3 or not value.isalpha() or value.upper() != value:
            raise ValueError('currency must be a 3-letter uppercase code')
        return value


class WebhookEvent(BaseModel):
    model_config = ConfigDict(extra='forbid')

    event_id: UUID
    event_type: Literal['payment.succeeded', 'payment.failed', 'refund.created']
    created_at: datetime
    data: WebhookData

    @field_validator('created_at')
    @classmethod
    def validate_created_at(cls, value: datetime) -> datetime:
        if value.tzinfo is None or value.utcoffset() is None:
            raise ValueError('created_at must be timezone-aware')
        return value

    @model_validator(mode='after')
    def validate_event_rules(self) -> 'WebhookEvent':
        if self.event_type == 'payment.failed' and not self.data.failure_code:
            raise ValueError("failure_code is required for 'payment.failed'")

        if self.event_type != 'payment.failed' and self.data.failure_code is not None:
            raise ValueError('failure_code is only allowed for payment.failed events')

        if self.event_type == 'refund.created' and self.data.amount > 100000:
            raise ValueError("refund amount must not exceed 100000 for 'refund.created'")

        return self


def validate_webhook(payload: dict) -> dict:
    event = WebhookEvent.model_validate(payload)
    return event.model_dump(mode='json')


