import time
from typing import List, Optional

import requests


class APIClient:
    def __init__(self, token: str, timeout: float = 5.0, max_retries: int = 4):
        self.timeout = timeout
        self.max_retries = max_retries
        self.session = requests.Session()
        self.session.headers.update({
            "Authorization": f"Bearer {token}",
            "Accept": "application/json",
        })

    def _request_with_retries(self, url: str) -> requests.Response:
        last_error = None
        for attempt in range(self.max_retries + 1):
            try:
                response = self.session.get(url, timeout=self.timeout)
                if response.status_code == 429 or 500 <= response.status_code < 600:
                    if attempt == self.max_retries:
                        response.raise_for_status()
                    retry_after = response.headers.get("Retry-After")
                    delay = float(retry_after) if retry_after and retry_after.isdigit() else 2 ** attempt
                    time.sleep(delay)
                    continue
                response.raise_for_status()
                return response
            except requests.RequestException as exc:
                last_error = exc
                if attempt == self.max_retries:
                    raise
                time.sleep(2 ** attempt)
        raise last_error

    @staticmethod
    def _next_link(response: requests.Response) -> Optional[str]:
        # requests parses RFC5988 Link headers into response.links
        return response.links.get("next", {}).get("url")

    def fetch_all(self, base_url: str) -> List[dict]:
        items = []
        url = base_url
        while url:
            response = self._request_with_retries(url)
            data = response.json()
            if not isinstance(data, list):
                raise ValueError("Expected each page to return a JSON list")
            items.extend(data)
            url = self._next_link(response)
        return items


def fetch_all_items(base_url: str, token: str) -> List[dict]:
    client = APIClient(token)
    return client.fetch_all(base_url)

class EventDispatcher:
    def __init__(self):
        # Store event names and their listener functions
        self.listeners = {}

    def add_listener(self, event_name, listener):
        # Create a list for the event if it does not exist
        if event_name not in self.listeners:
            self.listeners[event_name] = []
        self.listeners[event_name].append(listener)

    def dispatch(self, event_name, data=None):
        # Call all listeners registered for the event
        if event_name in self.listeners:
            for listener in self.listeners[event_name]:
                listener(data)


