from abc import ABC, abstractmethod


class EventHandler(ABC):
    @property
    @abstractmethod
    def event_type(self) -> str:
        """Return the event type this handler supports."""
        pass

    @abstractmethod
    def handle(self, event: dict) -> str:
        """Process an event and return a status message."""
        pass


class LoginEventHandler(EventHandler):
    @property
    def event_type(self) -> str:
        return "login"

    def handle(self, event: dict) -> str:
        user = event.get("user", "unknown")
        ip = event.get("ip", "unknown")
        return f"User '{user}' logged in from {ip}."


class PurchaseEventHandler(EventHandler):
    @property
    def event_type(self) -> str:
        return "purchase"

    def handle(self, event: dict) -> str:
        user = event.get("user", "unknown")
        item = event.get("item", "unspecified item")
        amount = event.get("amount", 0)
        return f"User '{user}' purchased '{item}' for ${amount}."


class EventDispatcher:
    def __init__(self, handlers: list[EventHandler]):
        self._handlers = {}
        for handler in handlers:
            if handler.event_type in self._handlers:
                raise ValueError(f"Duplicate handler for event type: {handler.event_type}")
            self._handlers[handler.event_type] = handler

    def dispatch(self, event: dict) -> str:
        event_type = event.get("type")
        if not event_type:
            raise ValueError("Event must include a 'type' field")
        if event_type not in self._handlers:
            raise ValueError(f"No handler registered for event type: {event_type}")
        return self._handlers[event_type].handle(event)


if __name__ == "__main__":
