import hashlib
import sys


def compute_sha256(file_path, chunk_size=8192):
    """Compute the SHA-256 checksum of a file by reading it in chunks."""
    sha256 = hashlib.sha256()

    with open(file_path, 'rb') as f:
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            sha256.update(chunk)

    return sha256.hexdigest()


def verify_file_integrity(file_path, expected_sha256):
    """Return True if the file's SHA-256 matches the expected checksum."""
    computed = compute_sha256(file_path)
    return computed.lower() == expected_sha256.strip().lower()


def main():
    if len(sys.argv) != 3:
        print('Usage: python script.py <file_path> <expected_sha256>')
        sys.exit(1)

    file_path = sys.argv[1]
    expected_sha256 = sys.argv[2]

    try:
        computed_hash = compute_sha256(file_path)
        print(f'Computed SHA-256: {computed_hash}')

        if verify_file_integrity(file_path, expected_sha256):
            print('Integrity check passed.')
        else:
            print('Integrity check failed.')
    except FileNotFoundError:
        print(f'Error: File not found: {file_path}')
        sys.exit(1)
    except OSError as e:
        print(f'Error reading file: {e}')
        sys.exit(1)


if __name__ == '__main__':
