from collections import defaultdict


def count_logs_by_service(logs):
    """Count log levels for each service."""
    counts = defaultdict(lambda: {"INFO": 0, "WARNING": 0, "ERROR": 0})

    for entry in logs:
        service = entry.get("service", "unknown")
        level = entry.get("level", "INFO")
        if level in counts[service]:
            counts[service][level] += 1

    return dict(counts)



def find_alert_services(counts, error_threshold):
    """Return services with ERROR counts above the threshold."""
    alerts = []
    for service, level_counts in counts.items():
        if level_counts["ERROR"] > error_threshold:
            alerts.append(service)
    return alerts



