from datetime import datetime


def parse_events(events):
    """Convert datetime strings to datetime objects and sort events by start time."""
    parsed = []
    for event in events:
        start = datetime.strptime(event['start'], '%Y-%m-%d %H:%M')
        end = datetime.strptime(event['end'], '%Y-%m-%d %H:%M')
        if end < start:
            raise ValueError(f"Event '{event['name']}' ends before it starts.")
        parsed.append({
            'name': event['name'],
            'start': start,
            'end': end,
            'duration_minutes': int((end - start).total_seconds() // 60)
        })
    return sorted(parsed, key=lambda e: e['start'])


def find_overlaps(events):
    """Return a list of tuples containing names of overlapping events."""
    overlaps = []
    for i in range(len(events)):
        for j in range(i + 1, len(events)):
            if events[j]['start'] < events[i]['end']:
                overlaps.append((events[i]['name'], events[j]['name']))
            else:
                break  # Events are sorted, so no later events will overlap with events[i]
    return overlaps


def print_report(events, overlaps):
    """Print a readable summary of events and overlaps."""
    print('Event Summary:')
    for event in events:
        print(
            f"- {event['name']}: {event['start'].strftime('%Y-%m-%d %H:%M')} to "
            f"{event['end'].strftime('%Y-%m-%d %H:%M')} "
            f"({event['duration_minutes']} minutes)"
        )

    print('\nOverlapping Events:')
    if overlaps:
        for first, second in overlaps:
            print(f"- {first} overlaps with {second}")
    else:
        print('- None')


if __name__ == '__main__':
    sample_events = [
        {'name': 'Team Meeting', 'start': '2025-04-10 09:00', 'end': '2025-04-10 10:00'},
        {'name': 'Code Review', 'start': '2025-04-10 09:30', 'end': '2025-04-10 10:15'},
