    ]

    parsed_events = parse_events(sample_events)
    overlaps = find_overlaps(parsed_events)
    print_report(parsed_events, overlaps)

from dataclasses import dataclass
import os


@dataclass(frozen=True)
class AppConfig:
    host: str
    port: int
    debug: bool
    timeout: float


def _parse_bool(value: str) -> bool:
    normalized = value.strip().lower()
    if normalized in {"1", "true", "yes", "on"}:
        return True
    if normalized in {"0", "false", "no", "off"}:
        return False
    raise ValueError(f"invalid boolean value: {value!r}")


def load_config(prefix: str = "APP_") -> AppConfig:
    errors = []

    host_key = f"{prefix}HOST"
    port_key = f"{prefix}PORT"
    debug_key = f"{prefix}DEBUG"
    timeout_key = f"{prefix}TIMEOUT"

    host_raw = os.getenv(host_key)
    port_raw = os.getenv(port_key)
    debug_raw = os.getenv(debug_key, "false")
    timeout_raw = os.getenv(timeout_key, "30.0")

    # Validate required host
    if host_raw is None or not host_raw.strip():
        errors.append(f"{host_key} is required and must be a non-empty string")
    else:
        host = host_raw.strip()

    # Validate required port
    if port_raw is None:
        errors.append(f"{port_key} is required")
    else:
        try:
            port = int(port_raw)
            if not (1 <= port <= 65535):
                raise ValueError
        except ValueError:
            errors.append(f"{port_key} must be an integer between 1 and 65535")

    # Validate optional debug
    try:
        debug = _parse_bool(debug_raw)
    except ValueError:
        errors.append(f"{debug_key} must be one of: true/false, yes/no, on/off, 1/0")

    # Validate optional timeout
    try:
        timeout = float(timeout_raw)
        if timeout <= 0:
            raise ValueError
    except ValueError:
        errors.append(f"{timeout_key} must be a positive float")

    if errors:
        raise ValueError("Configuration error(s): " + "; ".join(errors))

    return AppConfig(host=host, port=port, debug=debug, timeout=timeout)

class BloomFilter:
    def __init__(self, size=20):
        # Bit array to store membership information
        self.size = size
        self.bits = [0] * size
        self.salts = ["salt1", "salt2", "salt3"]

    def _hashes(self, item):
        # Generate multiple hash positions for the item
        positions = []
        for salt in self.salts:
            position = hash(salt + item) % self.size
            positions.append(position)
        return positions

    def add(self, item):
        # Set the bits at all hash positions to 1
        for position in self._hashes(item):
            self.bits[position] = 1

    def might_contain(self, item):
        # If any required bit is 0, the item is definitely not present
        for position in self._hashes(item):
            if self.bits[position] == 0:
                return False
        return True


# Demonstration
bloom = BloomFilter(size=20)
words_to_add = ["apple", "banana", "grape"]
words_to_check = ["apple", "banana", "orange", "melon", "grape"]

for word in words_to_add:
    bloom.add(word)

print("Bloom filter bits:", bloom.bits)
print()

for word in words_to_check:
    if bloom.might_contain(word):
        print(f"{word}: might be in the filter")
    else:
        print(f"{word}: definitely not in the filter")

