class UsernameError(Exception):
    """Base exception for username validation errors."""
    pass


class UsernameTooShortError(UsernameError):
    """Raised when the username is shorter than 5 characters."""
    pass


class UsernameContainsSpaceError(UsernameError):
    """Raised when the username contains a space."""
    pass


def validate_username(username):
    """Validate a username based on simple rules."""
    if len(username) < 5:
        raise UsernameTooShortError("Username must be at least 5 characters long.")
    if " " in username:
        raise UsernameContainsSpaceError("Username must not contain spaces.")
    return True


