import json
import requests
from bs4 import BeautifulSoup

HN_URL = "https://news.ycombinator.com/"
HEADERS = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                  "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
}


def fetch_page(url):
    """Download HTML content and return a BeautifulSoup object."""
    response = requests.get(url, headers=HEADERS, timeout=10)
    response.raise_for_status()
    return BeautifulSoup(response.text, "html.parser")


def parse_subtext(subtext):
    """Extract points, author, and comments from a story subtext row."""
    points_tag = subtext.select_one(".score")
    author_tag = subtext.select_one(".hnuser")
    links = subtext.select("a")

    points = int(points_tag.text.split()[0]) if points_tag else 0
    author = author_tag.text if author_tag else None

    comments = 0
    if links:
        last_text = links[-1].text.strip()
        if "comment" in last_text and last_text != "discuss":
            comments = int(last_text.split()[0])

    return {
        "points": points,
        "author": author,
        "comments": comments
    }


def scrape_top_stories(limit=10):
    """Scrape the top stories from Hacker News."""
    soup = fetch_page(HN_URL)
    story_rows = soup.select("tr.athing")
    subtext_rows = soup.select("td.subtext")

    stories = []
    for story_row, subtext in zip(story_rows[:limit], subtext_rows[:limit]):
        title_tag = story_row.select_one("span.titleline > a")
        if not title_tag:
            continue

        story = {
            "title": title_tag.text.strip(),
            "url": title_tag.get("href"),
        }
        story.update(parse_subtext(subtext))
        stories.append(story)

    return stories


if __name__ == "__main__":
    top_stories = scrape_top_stories(limit=10)
    print(json.dumps(top_stories, indent=2, ensure_ascii=False))

from datetime import datetime
from zoneinfo import ZoneInfo


def merge_busy_intervals(events, target_tz='UTC'):
    """Convert event intervals to target_tz, validate, and merge overlaps."""
    target_zone = ZoneInfo(target_tz)
    intervals = []

    for i, event in enumerate(events):
        try:
            start_str = event['start']
            end_str = event['end']
        except KeyError as exc:
            raise ValueError(f"Event {i} is missing required field: {exc.args[0]}") from None

        source_tz = event.get('tz', target_tz)
        source_zone = ZoneInfo(source_tz)

        # Parse naive local times, then attach the declared source timezone.
        start_dt = datetime.strptime(start_str, '%Y-%m-%d %H:%M').replace(tzinfo=source_zone)
        end_dt = datetime.strptime(end_str, '%Y-%m-%d %H:%M').replace(tzinfo=source_zone)

        if end_dt <= start_dt:
            raise ValueError(f"Event {i} has non-positive duration")

        # Normalize into the target timezone for reliable comparison/merging.
        start_dt = start_dt.astimezone(target_zone)
        end_dt = end_dt.astimezone(target_zone)
        intervals.append((start_dt, end_dt))

    if not intervals:
        return []

    intervals.sort(key=lambda pair: pair[0])
    merged = [intervals[0]]

    for current_start, current_end in intervals[1:]:
        last_start, last_end = merged[-1]

        # Merge overlapping or directly adjacent intervals.
        if current_start <= last_end:
            merged[-1] = (last_start, max(last_end, current_end))
        else:
            merged.append((current_start, current_end))

    return [
        (
            start.strftime('%Y-%m-%d %H:%M'),
            end.strftime('%Y-%m-%d %H:%M')
        )
        for start, end in merged
    ]


if __name__ == '__main__':
    sample_events = [
        {'start': '2024-07-01 09:00', 'end': '2024-07-01 10:30', 'tz': 'America/New_York'},
