def calculate_total(prices):
    """Return the total of a list of prices rounded to 2 decimals.

    Args:
        prices: A list of numeric item prices.

    Returns:
        float: The rounded total.

    Raises:
        ValueError: If any price is negative.
    """
    if not prices:
        return 0.0

    for price in prices:
        if price < 0:
            raise ValueError("Prices cannot be negative")

    return round(sum(prices), 2)


# Pytest tests

def test_calculate_total_normal_case():
    assert calculate_total([10.0, 5.5, 4.5]) == 20.0


def test_calculate_total_empty_list():
    assert calculate_total([]) == 0.0


def test_calculate_total_rounding():
    assert calculate_total([1.111, 2.225]) == 3.34


def test_calculate_total_negative_price_raises_error():
    import pytest

    with pytest.raises(ValueError):
        calculate_total([10.0, -2.0, 3.0])

from __future__ import annotations

from dataclasses import dataclass, replace
from typing import Any


@dataclass(frozen=True)
class AppConfig:
    host: str
    port: int
    debug: bool
    tags: tuple[str, ...]
    metadata: dict[str, str]

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> AppConfig:
        return cls(
            host=cls._parse_host(data.get("host")),
            port=cls._parse_port(data.get("port")),
            debug=cls._parse_debug(data.get("debug", False)),
            tags=cls._parse_tags(data.get("tags", ())),
            metadata=cls._parse_metadata(data.get("metadata", {})),
        )

    def with_updates(self, **updates: Any) -> AppConfig:
        parsers: dict[str, Any] = {
            "host": self._parse_host,
            "port": self._parse_port,
            "debug": self._parse_debug,
            "tags": self._parse_tags,
            "metadata": self._parse_metadata,
        }

        unknown = set(updates) - set(parsers)
        if unknown:
            raise ValueError(f"Unknown field(s): {', '.join(sorted(unknown))}")

        validated = {name: parsers[name](value) for name, value in updates.items()}
        return replace(self, **validated)

    @staticmethod
    def _parse_host(value: Any) -> str:
        if not isinstance(value, str) or not value.strip():
            raise ValueError("host must be a non-empty string")
        return value

    @staticmethod
    def _parse_port(value: Any) -> int:
        if not isinstance(value, int) or isinstance(value, bool) or not (1 <= value <= 65535):
            raise ValueError("port must be an integer between 1 and 65535")
        return value

    @staticmethod
    def _parse_debug(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            normalized = value.strip().lower()
            if normalized == "true":
                return True
            if normalized == "false":
                return False
        raise ValueError("debug must be a bool or 'true'/'false'")

    @staticmethod
    def _parse_tags(value: Any) -> tuple[str, ...]:
        if not isinstance(value, (list, tuple)):
            raise ValueError("tags must be a list or tuple of strings")
        if not all(isinstance(item, str) for item in value):
            raise ValueError("tags must contain only strings")
        return tuple(value)

    @staticmethod
    def _parse_metadata(value: Any) -> dict[str, str]:
        if not isinstance(value, dict):
            raise ValueError("metadata must be a dict[str, str]")
        if not all(isinstance(k, str) and isinstance(v, str) for k, v in value.items()):
            raise ValueError("metadata must contain only string keys and string values")
        return dict(value)


if __name__ == "__main__":
    config = AppConfig.from_dict(
        {
            "host": "localhost",
            "port": 8080,
            "debug": "true",
            "tags": ["api", "v1"],
            "metadata": {"env": "dev"},
        }
    )
    updated = config.with_updates(port=9090, tags=("api", "v2"))
    print(config)
    print(updated)
}

import sys
import json
import csv
import math


def is_number(value):
    try:
        num = float(value)
        return math.isfinite(num)
    except (TypeError, ValueError):
        return False


def main():
    try:
        data = json.load(sys.stdin)
    except json.JSONDecodeError:
        return

    if not isinstance(data, list):
        return

    rows = []

    for order in data:
        if not isinstance(order, dict):
            continue

        order_id = order.get('order_id')
        customer = order.get('customer')
        items = order.get('items')

        if order_id is None or customer is None or not isinstance(items, list):
            continue

        for item in items:
            if not isinstance(item, dict):
                continue

            sku = item.get('sku')
            quantity = item.get('quantity')
            unit_price = item.get('unit_price')

            if sku is None or not is_number(quantity) or not is_number(unit_price):
                continue

            quantity = float(quantity)
            unit_price = float(unit_price)
            line_total = round(quantity * unit_price, 2)

            rows.append({
                'order_id': str(order_id),
                'customer': str(customer),
                'sku': str(sku),
                'quantity': quantity,
                'unit_price': unit_price,
                'line_total': f'{line_total:.2f}'
            })

    rows.sort(key=lambda r: (r['order_id'], r['sku']))

    writer = csv.DictWriter(
        sys.stdout,
        fieldnames=['order_id', 'customer', 'sku', 'quantity', 'unit_price', 'line_total']
    )
    writer.writeheader()
    writer.writerows(rows)


if __name__ == '__main__':
    main()

from abc import ABC, abstractmethod
import math


class Shape(ABC):
    """Abstract base class for all shapes."""

    @abstractmethod
    def area(self):
        """Return the area of the shape."""
        pass


class Rectangle(Shape):
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height


class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return math.pi * self.radius ** 2


