from abc import ABC, abstractmethod


# Factory Pattern: notifier interface and concrete notifiers
class Notifier(ABC):
    @abstractmethod
    def send(self, message: dict) -> str:
        pass


class EmailNotifier(Notifier):
    def send(self, message: dict) -> str:
        return f"EMAIL -> [{message['priority']}] {message['title']}: {message['body']}"


class SMSNotifier(Notifier):
    def send(self, message: dict) -> str:
        return f"SMS -> [{message['priority']}] {message['title']}: {message['body']}"


class PushNotifier(Notifier):
    def send(self, message: dict) -> str:
        return f"PUSH -> [{message['priority']}] {message['title']}: {message['body']}"


class NotificationFactory:
    @staticmethod
    def create_notifier(channel: str) -> Notifier:
        channel = channel.lower()
        if channel == 'email':
            return EmailNotifier()
        if channel == 'sms':
            return SMSNotifier()
        if channel == 'push':
            return PushNotifier()
        raise ValueError(f"Unsupported notification channel: {channel}")


# Builder Pattern: construct message objects step by step
class MessageBuilder:
    def __init__(self):
        self.reset()

    def reset(self):
        self._message = {
            'title': 'Untitled',
            'body': '',
            'priority': 'normal'
        }

    def set_title(self, title: str):
        self._message['title'] = title
        return self

    def set_body(self, body: str):
        self._message['body'] = body
        return self

    def set_priority(self, priority: str):
        self._message['priority'] = priority.lower()
        return self

    def build(self) -> dict:
        result = self._message.copy()
        self.reset()  # Ready to build another message
        return result


if __name__ == '__main__':
    builder = MessageBuilder()

    message1 = (
        builder
        .set_title('Server Alert')
        .set_body('CPU usage exceeded 90%.')
        .set_priority('high')
        .build()
    )

    message2 = (
        builder
        .set_title('Welcome')
        .set_body('Your account has been created successfully.')
        .set_priority('normal')
        .build()
    )

    email_notifier = NotificationFactory.create_notifier('email')
    sms_notifier = NotificationFactory.create_notifier('sms')

    print(email_notifier.send(message1))
    print(sms_notifier.send(message2))

class ConnectionFSM:
    MAX_FAILURES = 3

    def __init__(self):
        self.state = 'IDLE'
        self.failures = 0

        # Transition table: current_state -> event -> next_state
        self.transitions = {
            'IDLE': {
                'connect': 'CONNECTING',
                'close': 'CLOSED',
            },
            'CONNECTING': {
                'success': 'CONNECTED',
                'fail': 'RETRY_WAIT',
                'timeout': 'RETRY_WAIT',
                'close': 'CLOSED',
            },
            'CONNECTED': {
                'timeout': 'RETRY_WAIT',
                'close': 'CLOSED',
            },
            'RETRY_WAIT': {
                'retry': 'CONNECTING',
                'close': 'CLOSED',
            },
            'CLOSED': {}
        }

    def handle(self, event):
        """Process an event and update the FSM state."""
        if event not in self.transitions.get(self.state, {}):
            raise ValueError(f'Invalid transition: state={self.state}, event={event}')

        next_state = self.transitions[self.state][event]

        # Update failure count based on outcome events
        if self.state == 'CONNECTING' and event in ('fail', 'timeout'):
            self.failures += 1
            if self.failures >= self.MAX_FAILURES:
                self.state = 'CLOSED'
                return self.state

        elif self.state == 'CONNECTING' and event == 'success':
            self.failures = 0

        self.state = next_state
        return self.state

    def status(self):
        return {'state': self.state, 'failures': self.failures}


# Example usage
if __name__ == '__main__':
    fsm = ConnectionFSM()
    events = ['connect', 'fail', 'retry', 'timeout', 'retry', 'fail']

    for event in events:
        try:
            new_state = fsm.handle(event)
            print(f'Event: {event:<7} -> State: {new_state}, Status: {fsm.status()}')
        except ValueError as e:
            print(e)
            break

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.size = [1] * n
        self.components = n

    def find(self, x: int) -> int:
        # Path compression by halving
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False

        # Union by size
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra

        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.components -= 1
        return True


def earliest_full_connectivity(n: int, logs: list[tuple[int, int, int]]) -> int:
    if n <= 1:
        return 0

    uf = UnionFind(n)

    # Process events in chronological order
    for timestamp, a, b in sorted(logs):
        if not (0 <= a < n and 0 <= b < n):
            raise ValueError("Node index out of range")

        uf.union(a, b)
        if uf.components == 1:
            return timestamp

    return -1


