        (20190301, 0, 1),
        (20190110, 2, 3),
        (20190214, 1, 2),
        (20190420, 3, 4),
        (20190101, 0, 4),
    ]
    print(earliest_full_connectivity(5, sample_logs))  # 20190214

import random
import time


def unreliable_service():
    """Simulate a service that fails randomly."""
    if random.random() < 0.6:
        raise ValueError("Service failed")
    return "Service succeeded"


def retry_call(func, retries=3, delay=0.5):
    """Try calling a function multiple times before raising the last error."""
    last_error = None
    for attempt in range(1, retries + 1):
        try:
            print(f"  Attempt {attempt}...")
            return func()
        except Exception as error:
            last_error = error
            print(f"  Attempt {attempt} failed: {error}")
            if attempt < retries:
                time.sleep(delay)
    raise last_error


class CircuitBreaker:
    def __init__(self, failure_threshold=2, cooldown=2):
        self.failure_threshold = failure_threshold
        self.cooldown = cooldown
        self.failure_count = 0
        self.state = "CLOSED"
        self.opened_at = None

    def call(self, func):
        """Call a function unless the circuit is open."""
        if self.state == "OPEN":
            elapsed = time.time() - self.opened_at
            if elapsed < self.cooldown:
                raise RuntimeError("Circuit is OPEN. Call blocked.")
            print("Cooldown finished. Closing circuit.")
            self.state = "CLOSED"
            self.failure_count = 0

        try:
            result = func()
            self.failure_count = 0
            return result
        except Exception:
            self.failure_count += 1
            if self.failure_count >= self.failure_threshold:
                self.state = "OPEN"
                self.opened_at = time.time()
                print("Circuit opened due to repeated failures.")
            raise


if __name__ == "__main__":
    random.seed(1)
    breaker = CircuitBreaker(failure_threshold=2, cooldown=2)

    for call_number in range(1, 8):
        print(f"\nCall {call_number}:")
        try:
            result = breaker.call(lambda: retry_call(unreliable_service, retries=3, delay=0.3))
            print("Result:", result)
        except Exception as error:
            print("Final outcome:", error)
        time.sleep(0.7)

from typing import Any, Dict, List, Tuple, Union

SchemaValue = Union[type, Tuple[type, bool], Dict[str, Any]]
Schema = Dict[str, SchemaValue]


def validate(schema: Schema, data: Dict[str, Any], path: str = "") -> List[str]:
    """Validate a nested dictionary against a simple schema."""
    errors: List[str] = []

    if not isinstance(data, dict):
        location = path or "<root>"
        return [f"{location}: expected dict, got {type(data).__name__}"]

    # Report unknown fields.
    for key in data:
        if key not in schema:
            location = f"{path}.{key}" if path else key
            errors.append(f"{location}: unknown field")

    for key, rule in schema.items():
        location = f"{path}.{key}" if path else key

        # Nested schema.
        if isinstance(rule, dict):
            if key not in data:
                errors.append(f"{location}: missing required field")
            elif not isinstance(data[key], dict):
                errors.append(f"{location}: expected dict, got {type(data[key]).__name__}")
            else:
                errors.extend(validate(rule, data[key], location))
            continue

        # Normalize rule into (expected_type, required).
        if isinstance(rule, tuple):
            expected_type, required = rule
        else:
            expected_type, required = rule, True

        if key not in data:
            if required:
                errors.append(f"{location}: missing required field")
            continue

        value = data[key]
        if not isinstance(value, expected_type):
            errors.append(
                f"{location}: expected {expected_type.__name__}, got {type(value).__name__}"
            )

    return errors


if __name__ == "__main__":
    schema = {
        "user": {
            "name": str,
            "age": (int, False),
            "address": {
                "city": str,
                "zip": int,
            },
        },
        "active": bool,
    }

    data = {
        "user": {
            "name": 123,
            "address": {
                "city": "Paris",
                "zip": "75001",
                "country": "FR",
            },
            "extra": "unexpected",
        },
        "active": "yes",
        "debug": True,
    }

    for error in validate(schema, data):
        print(error)

