#!/usr/bin/env python3
from pathlib import Path
import argparse


def find_files_with_extension(start_dir: Path, extension: str):
    if not extension.startswith("."):
        extension = "." + extension

    for path in start_dir.rglob(f"*{extension}"):
        if path.is_file():
            yield path.relative_to(start_dir)


def main():
    parser = argparse.ArgumentParser(
        description="Recursively list files with a specific extension."
    )
    parser.add_argument(
        "directory",
        help="Starting directory to scan"
    )
    parser.add_argument(
        "extension",
        help="File extension to search for (example: txt or .txt)"
    )

    args = parser.parse_args()

    start_dir = Path(args.directory)

    if not start_dir.exists():
        print(f"Error: '{start_dir}' does not exist.")
        return

    if not start_dir.is_dir():
        print(f"Error: '{start_dir}' is not a directory.")
        return

    matches = list(find_files_with_extension(start_dir, args.extension))

    if matches:
        for file_path in matches:
            print(file_path)
    else:
        print(f"No files with extension '{args.extension}' found in '{start_dir}'.")


if __name__ == "__main__":
    main()
