from datetime import datetime, date
from collections import defaultdict
from typing import Any, Dict, List, Optional


def summarize_telemedicine_appointments(
    records: List[Dict[str, Any]],
    start_date: str,
    end_date: str,
) -> Dict[str, Dict[str, Any]]:
    valid_statuses = {"completed", "cancelled", "no_show", "rescheduled"}

    def parse_date(value: str) -> date:
        return datetime.strptime(value, "%Y-%m-%d").date()

    def parse_datetime(value: str) -> Optional[datetime]:
        if not isinstance(value, str):
            return None
        try:
            return datetime.fromisoformat(value.replace("Z", "+00:00"))
        except ValueError:
            return None

    start = parse_date(start_date)
    end = parse_date(end_date)
    if start > end:
        raise ValueError("start_date must be less than or equal to end_date")

    summary: Dict[str, Dict[str, Any]] = {}

    for record in records:
        if not isinstance(record, dict):
            continue

        required_fields = {
            "appointment_id",
            "patient_id",
            "provider_id",
            "scheduled_time",
            "status",
            "duration_minutes",
            "fee",
        }
        if not required_fields.issubset(record.keys()):
            continue

        scheduled_dt = parse_datetime(record.get("scheduled_time"))
        status = record.get("status")
        provider_id = record.get("provider_id")

        if scheduled_dt is None or status not in valid_statuses or provider_id in (None, ""):
            continue

        try:
            float(record.get("fee"))
            int(record.get("duration_minutes"))
        except (TypeError, ValueError):
            continue

        record_date = scheduled_dt.date()
        if not (start <= record_date <= end):
            continue

        date_key = record_date.strftime("%Y-%m-%d")
        if date_key not in summary:
            summary[date_key] = {
                "total_appointments": 0,
                "status_counts": {
                    "completed": 0,
                    "cancelled": 0,
                    "no_show": 0,
                    "rescheduled": 0,
                },
                "total_billable_revenue": 0.0,
                "_completed_by_provider": defaultdict(int),
                "top_provider_by_completed_consultations": None,
            }

        day_summary = summary[date_key]
        day_summary["total_appointments"] += 1
        day_summary["status_counts"][status] += 1

        if status == "completed":
            day_summary["total_billable_revenue"] += float(record["fee"])
            day_summary["_completed_by_provider"][provider_id] += 1

    for date_key, day_summary in summary.items():
        provider_counts = day_summary["_completed_by_provider"]
        if provider_counts:
            top_provider = sorted(
                provider_counts.items(),
                key=lambda item: (-item[1], str(item[0])),
            )[0][0]
            day_summary["top_provider_by_completed_consultations"] = top_provider
        del day_summary["_completed_by_provider"]
        day_summary["total_billable_revenue"] = round(day_summary["total_billable_revenue"], 2)

    return dict(sorted(summary.items(), key=lambda item: item[0]))

class PluginRegistry:
    """Singleton registry that stores plugin classes by name."""
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._plugins = {}
        return cls._instance

    def register(self, name, plugin_cls):
        if name in self._plugins:
            raise ValueError(f"Plugin '{name}' is already registered")
        self._plugins[name] = plugin_cls

    def get(self, name):
        if name not in self._plugins:
            raise KeyError(f"Plugin '{name}' is not registered")
        return self._plugins[name]

    def list_plugins(self):
        return sorted(self._plugins.keys())


class BasePlugin:
    """Base class that auto-registers subclasses in the singleton registry."""
    plugin_name = None

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        if cls.plugin_name:  # Skip abstract base class
            PluginRegistry().register(cls.plugin_name, cls)

    def run(self):
        raise NotImplementedError


class HelloPlugin(BasePlugin):
    plugin_name = "hello"

    def run(self):
        return "Hello from HelloPlugin"


class SumPlugin(BasePlugin):
    plugin_name = "sum"

    def __init__(self, a=0, b=0):
        self.a = a
        self.b = b

    def run(self):
        return self.a + self.b


if __name__ == "__main__":
    registry = PluginRegistry()

    print("Registered plugins:", registry.list_plugins())

    hello_cls = registry.get("hello")
    hello_plugin = hello_cls()
    print(hello_plugin.run())

    sum_cls = registry.get("sum")
    sum_plugin = sum_cls(5, 7)
    print("Sum result:", sum_plugin.run())

import time
import json
import hmac
import hashlib
from typing import Dict, Any


def handle_webhook(
    headers: Dict[str, str],
    body: bytes,
    secret: str,
    tolerance_seconds: int = 300,
) -> Dict[str, Any]:
    """Validate a signed webhook request and return the parsed JSON event."""
    signature_header = headers.get("X-Signature")
    if not signature_header:
        raise ValueError("Missing X-Signature header")

    # Parse header format: t=<timestamp>,v1=<signature>
    parts = {}
    for item in signature_header.split(","):
        if "=" not in item:
            raise ValueError("Malformed X-Signature header")
        key, value = item.split("=", 1)
        parts[key.strip()] = value.strip()

    if "t" not in parts or "v1" not in parts:
        raise ValueError("X-Signature header must contain t and v1 fields")

    try:
        timestamp = int(parts["t"])
    except ValueError as exc:
        raise ValueError("Invalid signature timestamp") from exc

    now = int(time.time())
    if abs(now - timestamp) > tolerance_seconds:
        raise ValueError("Webhook timestamp is outside the allowed tolerance")

    # Sign the exact payload: b"<timestamp>." + raw body bytes
    signed_payload = f"{timestamp}.".encode("utf-8") + body
    expected_signature = hmac.new(
        secret.encode("utf-8"),
        signed_payload,
        hashlib.sha256,
    ).hexdigest()

    if not hmac.compare_digest(expected_signature, parts["v1"]):
        raise ValueError("Invalid webhook signature")

    try:
        event = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError("Request body must be valid UTF-8 JSON") from exc

    required_fields = {"id", "type", "data"}
    missing = required_fields - event.keys() if isinstance(event, dict) else required_fields
    if not isinstance(event, dict):
        raise ValueError("Webhook JSON payload must be an object")
    if missing:
        raise ValueError(f"Missing required event fields: {', '.join(sorted(missing))}")

    return event

