def error_lines(lines):
    """Yield cleaned log lines that start with 'ERROR:'."""
    for line in lines:
        cleaned = line.strip()
        if cleaned.startswith('ERROR:'):
            yield cleaned


def error_messages(lines):
    """Yield only the message part from ERROR log lines."""
    for line in error_lines(lines):
        _, message = line.split(':', 1)
        yield message.strip()


def summarize_errors(messages):
    """Consume an iterator of error messages and return summary stats."""
    count = 0
    longest = ''

    for message in messages:
        count += 1
        if len(message) > len(longest):
            longest = message

    return {
        'count': count,
        'longest_message': longest
    }


