def repeat(n):
    # Outer function receives the number of repetitions
    def decorator(func):
        # This wrapper remembers both n and func using a closure
        def wrapper(*args, **kwargs):
            results = []
            for _ in range(n):
                results.append(func(*args, **kwargs))
            return results
        return wrapper
    return decorator


@repeat(3)
def greet(name):
