from datetime import datetime, timedelta


def to_datetime(time_str):
    """Convert HH:MM string to a datetime object on an arbitrary date."""
    return datetime.strptime(time_str, "%H:%M")


def to_time_string(dt):
    """Convert a datetime object back to HH:MM format."""
    return dt.strftime("%H:%M")


def find_available_slots(events, work_start, work_end, meeting_minutes):
    """Return available time slots of at least meeting_minutes within the workday."""
    day_start = to_datetime(work_start)
    day_end = to_datetime(work_end)
    min_duration = timedelta(minutes=meeting_minutes)

    # Convert and clamp events to the workday range
    busy = []
    for start, end in events:
        start_dt = max(to_datetime(start), day_start)
        end_dt = min(to_datetime(end), day_end)
        if start_dt < end_dt:
            busy.append((start_dt, end_dt))

    # Sort events by start time
    busy.sort(key=lambda x: x[0])

    # Merge overlapping or adjacent busy intervals
    merged = []
    for start, end in busy:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)

    # Find free slots between merged busy intervals
    available = []
    current = day_start

    for start, end in merged:
        if start - current >= min_duration:
            available.append((to_time_string(current), to_time_string(start)))
        current = max(current, end)

    # Check time after the last event until end of workday
    if day_end - current >= min_duration:
        available.append((to_time_string(current), to_time_string(day_end)))

    return available


def main():
    events = [
        ("09:00", "10:30"),
        ("12:00", "13:00"),
        ("10:15", "11:00"),
        ("15:30", "16:00")
    ]
    work_start = "09:00"
    work_end = "17:00"
    meeting_minutes = 30

    slots = find_available_slots(events, work_start, work_end, meeting_minutes)
    print("Available slots:")
    for start, end in slots:
        print(f"{start} - {end}")


if __name__ == "__main__":
