class PaymentError(Exception):
    """Base exception for all payment validation errors."""


class MissingFieldError(PaymentError):
    def __init__(self, field_name):
        self.field_name = field_name
        super().__init__(f"Missing required field: {field_name}")


class InvalidCurrencyError(PaymentError):
    def __init__(self, currency):
        self.currency = currency
        super().__init__(f"Invalid currency: {currency}")


class NegativeAmountError(PaymentError):
    def __init__(self, amount):
        self.amount = amount
        super().__init__(f"Amount must be positive, got: {amount}")


class UnsupportedPaymentMethodError(PaymentError):
    def __init__(self, method):
        self.method = method
        super().__init__(f"Unsupported payment method: {method}")


ALLOWED_CURRENCIES = {"USD", "EUR", "JPY"}
ALLOWED_METHODS = {"card", "bank_transfer", "wallet"}
REQUIRED_FIELDS = ("amount", "currency", "method")


def validate_payment(data):
    """Validate a single payment dictionary or raise a specific PaymentError."""
    for field in REQUIRED_FIELDS:
        if field not in data:
            raise MissingFieldError(field)

    amount = data["amount"]
    currency = data["currency"]
    method = data["method"]

    # Ensure amount is numeric and strictly positive.
    if not isinstance(amount, (int, float)) or isinstance(amount, bool) or amount <= 0:
        raise NegativeAmountError(amount)

    if currency not in ALLOWED_CURRENCIES:
        raise InvalidCurrencyError(currency)

    if method not in ALLOWED_METHODS:
        raise UnsupportedPaymentMethodError(method)

    return True


def process_payments(payments):
    """Process a list of payment dictionaries into status strings."""
    results = []
    for payment in payments:
        try:
            validate_payment(payment)
            results.append(
                f"OK:{payment['method']}:{payment['currency']}:{payment['amount']}"
            )
        except PaymentError as exc:
            results.append(f"ERROR:{exc.__class__.__name__}:{exc}")
    return results


if __name__ == "__main__":
    sample_payments = [
        {"amount": 100, "currency": "USD", "method": "card"},
        {"amount": -5, "currency": "EUR", "method": "wallet"},
        {"amount": 42, "currency": "GBP", "method": "card"},
        {"amount": 10, "currency": "JPY", "method": "crypto"},
        {"currency": "USD", "method": "bank_transfer"},
    ]

