class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False


class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end = True

    def search(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end

    def starts_with(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True


def main():
    trie = Trie()

    words = ["apple", "app", "bat", "ball"]
    for word in words:
        trie.insert(word)

    print(trie.search("apple"))   # True
    print(trie.search("appl"))    # False
    print(trie.search("bat"))     # True
    print(trie.starts_with("app"))  # True
    print(trie.starts_with("ba"))   # True
    print(trie.starts_with("cat"))  # False


