from math import gcd


def extended_gcd(a, b):
    """Return (g, x, y) such that a*x + b*y = g = gcd(a, b)."""
    if b == 0:
        return a, 1, 0
    g, x1, y1 = extended_gcd(b, a % b)
    return g, y1, x1 - (a // b) * y1


def mod_inverse(a, m):
    """Compute the modular inverse of a modulo m."""
    g, x, _ = extended_gcd(a, m)
    if g != 1:
        raise ValueError("Modular inverse does not exist")
    return x % m


def choose_public_exponent(phi):
    """Choose the smallest e > 1 that is coprime with phi."""
    for e in range(2, phi):
        if gcd(e, phi) == 1:
            return e
    raise ValueError("Failed to find a valid public exponent")


def rsa_demo(p, q, plaintext):
    n = p * q
    phi = (p - 1) * (q - 1)

    e = choose_public_exponent(phi)
    d = mod_inverse(e, phi)

    # Ensure each character can be represented as an integer smaller than n.
    code_points = [ord(ch) for ch in plaintext]
    if any(m >= n for m in code_points):
        raise ValueError("All plaintext character codes must be smaller than n")

    ciphertext = [pow(m, e, n) for m in code_points]
    decrypted_codes = [pow(c, d, n) for c in ciphertext]
    decrypted_text = ''.join(chr(m) for m in decrypted_codes)

    return {
        'public_key': (e, n),
        'private_key': (d, n),
        'ciphertext': ciphertext,
        'decrypted_text': decrypted_text,
    }


if __name__ == '__main__':
    result = rsa_demo(61, 53, 'HELLO')
    print(result)

import socket
import threading
from queue import Queue


def scan_port(host, port, timeout=0.5):
    """Return 'open' if a TCP connection succeeds, otherwise 'closed'."""
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(timeout)
    try:
        result = sock.connect_ex((host, port))
        return 'open' if result == 0 else 'closed'
    except socket.error:
        return 'closed'
    finally:
        sock.close()


def threaded_port_scan(host, ports, max_threads=20, timeout=0.5):
    """Scan ports concurrently and return a {port: status} dictionary."""
    results = {}
    lock = threading.Lock()
    port_queue = Queue()

    for port in ports:
        port_queue.put(port)

    def worker():
        while not port_queue.empty():
            try:
                port = port_queue.get_nowait()
            except Exception:
                break

            status = scan_port(host, port, timeout)
            with lock:
                results[port] = status
            port_queue.task_done()

    threads = []
    for _ in range(min(max_threads, len(ports))):
        t = threading.Thread(target=worker)
        t.start()
        threads.append(t)

    for t in threads:
        t.join()

    return dict(sorted(results.items()))


if __name__ == '__main__':
    target_host = '127.0.0.1'
    target_ports = [22, 80, 443, 8080, 3306]

    scan_results = threaded_port_scan(target_host, target_ports)
    print(f'Scan results for {target_host}:')
    for port, status in scan_results.items():
        print(f'Port {port}: {status}')

import json
