import io


class SerializerRegistry:
    """Singleton registry that stores serializer classes by format name."""
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._serializers = {}
        return cls._instance

    def register(self, name, serializer_cls):
        if name in self._serializers:
            raise ValueError(f"Serializer '{name}' is already registered")
        self._serializers[name] = serializer_cls

    def create(self, name):
        if name not in self._serializers:
            raise KeyError(f"Unknown serializer format: {name}")
        return self._serializers[name]()

    def formats(self):
        return sorted(self._serializers.keys())


def register_serializer(name):
    """Decorator to auto-register serializer classes in the singleton registry."""
    def decorator(cls):
        registry = SerializerRegistry()
        registry.register(name, cls)
        return cls
    return decorator


@register_serializer("json")
class JsonSerializer:
    def serialize(self, data):
        return json.dumps(data)

    def deserialize(self, text):
        return json.loads(text)


@register_serializer("csv")
class CsvSerializer:
    def serialize(self, data):
        if not data:
            return ""
        output = io.StringIO()
        writer = csv.DictWriter(output, fieldnames=data[0].keys())
        writer.writeheader()
        writer.writerows(data)
        return output.getvalue()

    def deserialize(self, text):
        if not text.strip():
            return []
        input_stream = io.StringIO(text)
        reader = csv.DictReader(input_stream)
        return list(reader)


if __name__ == "__main__":
