def caesar_shift_char(char, shift):
    """Shift a single alphabetic character by the given amount."""
    if char.isupper():
        start = ord('A')
        return chr((ord(char) - start + shift) % 26 + start)
    elif char.islower():
        start = ord('a')
        return chr((ord(char) - start + shift) % 26 + start)
    else:
        return char  # Leave non-alphabetic characters unchanged


def encrypt(text, shift):
    """Encrypt text using a Caesar cipher."""
    return ''.join(caesar_shift_char(char, shift) for char in text)


def decrypt(text, shift):
    """Decrypt text encrypted with a Caesar cipher."""
    return ''.join(caesar_shift_char(char, -shift) for char in text)


