from datetime import datetime
from zoneinfo import ZoneInfo


def find_overlaps(events_a, events_b, target_tz):
    """Return overlapping intervals between two event lists in target_tz."""
    tz = ZoneInfo(target_tz)

    def parse_event(event):
        """Parse and normalize a single event; return (start, end) or None if invalid."""
        try:
            start = datetime.fromisoformat(event['start'])
            end = datetime.fromisoformat(event['end'])
        except (KeyError, ValueError, TypeError):
            return None

        # Require timezone-aware datetimes for reliable cross-timezone comparison.
        if start.tzinfo is None or end.tzinfo is None:
            return None

        start = start.astimezone(tz)
        end = end.astimezone(tz)
        if end <= start:
            return None
        return start, end

    normalized_a = [parsed for e in events_a if (parsed := parse_event(e))]
    normalized_b = [parsed for e in events_b if (parsed := parse_event(e))]

    overlaps = []
    for start_a, end_a in normalized_a:
        for start_b, end_b in normalized_b:
            overlap_start = max(start_a, start_b)
            overlap_end = min(end_a, end_b)

            if overlap_start < overlap_end:
                minutes = int((overlap_end - overlap_start).total_seconds() // 60)
                overlaps.append({
                    'start': overlap_start.isoformat(),
                    'end': overlap_end.isoformat(),
                    'minutes': minutes,
                })

    overlaps.sort(key=lambda item: item['start'])
    return overlaps


