from typing import Any, Dict, List, Optional
import re
from pydantic import BaseModel, EmailStr, ValidationError, field_validator, model_validator, ConfigDict


class RegistrationSchema(BaseModel):
    model_config = ConfigDict(extra='forbid', str_strip_whitespace=True)

    username: str
    email: EmailStr
    age: int
    password: str
    tags: Optional[List[str]] = None

    @field_validator('username')
    @classmethod
    def validate_username(cls, value: str) -> str:
        if not re.fullmatch(r'\w{3,20}', value):
            raise ValueError('username must be 3-20 characters and contain only letters, digits, or underscores')
        return value

    @field_validator('email', mode='before')
    @classmethod
    def normalize_email(cls, value: Any) -> Any:
        return value.strip().lower() if isinstance(value, str) else value

    @field_validator('age')
    @classmethod
    def validate_age(cls, value: int) -> int:
        if not 18 <= value <= 120:
            raise ValueError('age must be between 18 and 120')
        return value

    @field_validator('password')
    @classmethod
    def validate_password(cls, value: str) -> str:
        if len(value) < 8:
            raise ValueError('password must be at least 8 characters long')
        if not re.search(r'[A-Z]', value):
            raise ValueError('password must contain at least one uppercase letter')
        if not re.search(r'[a-z]', value):
            raise ValueError('password must contain at least one lowercase letter')
        if not re.search(r'\d', value):
            raise ValueError('password must contain at least one digit')
        return value

    @field_validator('tags')
    @classmethod
    def validate_and_deduplicate_tags(cls, value: Optional[List[str]]) -> Optional[List[str]]:
        if value is None:
            return value
        result: List[str] = []
        seen = set()
        for tag in value:
            if not isinstance(tag, str):
                raise ValueError('each tag must be a string')
            tag = tag.strip()
            if not tag.islower() or not tag:
                raise ValueError('each tag must be non-empty and lowercase')
            if tag not in seen:
                seen.add(tag)
                result.append(tag)
        return result

    @model_validator(mode='after')
    def normalize_username(self) -> 'RegistrationSchema':
        self.username = self.username.strip()
        return self


def validate_registration(data: Dict[str, Any]) -> Dict[str, Any]:
    try:
        model = RegistrationSchema.model_validate(data)
        return {'ok': True, 'data': model.model_dump()}
    except ValidationError as exc:
        errors: Dict[str, List[str]] = {}
        for err in exc.errors():
            field = '.'.join(str(part) for part in err['loc'])
            errors.setdefault(field, []).append(err['msg'])
        return {'ok': False, 'errors': errors}

