def split_name(full_name):
    """Split a full name into first and last name."""
    parts = (full_name or '').strip().split()
    if not parts:
        return '', ''
    if len(parts) == 1:
        return parts[0], ''
    return parts[0], ' '.join(parts[1:])


def format_signup_date(signup_ts):
    """Convert ISO timestamp to YYYY-MM-DD, return empty string if invalid."""
    if not signup_ts:
        return ''
    try:
        # Handle timestamps ending with 'Z' as UTC
        signup_ts = signup_ts.replace('Z', '+00:00')
        return datetime.fromisoformat(signup_ts).strftime('%Y-%m-%d')
    except ValueError:
        return ''


def migrate_users():
    with open(INPUT_FILE, 'r', encoding='utf-8') as infile:
        users = json.load(infile)

    migrated = 0
    skipped = 0

    with open(OUTPUT_FILE, 'w', newline='', encoding='utf-8') as outfile:
        writer = csv.DictWriter(
            outfile,
            fieldnames=['user_id', 'first_name', 'last_name', 'email', 'signup_date', 'status']
        )
        writer.writeheader()

        for user in users:
            if not user.get('id') or not user.get('email'):
                skipped += 1
                continue

            first_name, last_name = split_name(user.get('full_name', ''))
            row = {
