        }
        if hasattr(record, "extra_data") and isinstance(record.extra_data, dict):
            payload.update(record.extra_data)
        return json.dumps(payload, default=str)


class StructuredLogger:
    def __init__(self, name: str = "inference_pipeline", level: int = logging.INFO) -> None:
        self.name = name
        self.level = level
        self.logger: Optional[logging.Logger] = None
        self.handler: Optional[logging.Handler] = None

    def __enter__(self) -> logging.Logger:
        logger = logging.getLogger(self.name)
        logger.setLevel(self.level)
        logger.propagate = False
        if not logger.handlers:
            handler = logging.StreamHandler()
            handler.setFormatter(JsonFormatter())
            logger.addHandler(handler)
            self.handler = handler
        self.logger = logger
        return logger

    def __exit__(self, exc_type, exc, tb) -> None:
        return None


@dataclass(frozen=True)
class RequestSchema:
    feature_names: Sequence[str]
    allow_extra_fields: bool = False

    def validate(self, payload: Union[str, Dict[str, Any]]) -> Dict[str, Any]:
        if isinstance(payload, str):
            try:
                payload = json.loads(payload)
            except json.JSONDecodeError as exc:
                raise ValidationError(f"Invalid JSON payload: {exc}") from exc

        if not isinstance(payload, dict):
            raise ValidationError("Payload must be a JSON object.")

        if "features" not in payload:
            raise ValidationError("Missing required field: 'features'.")

        features = payload["features"]
        if not isinstance(features, dict):
            raise ValidationError("'features' must be an object mapping feature names to numeric values.")

        expected = set(self.feature_names)
        received = set(features.keys())

        missing = expected - received
        extra = received - expected

        if missing:
            raise ValidationError(f"Missing required feature(s): {sorted(missing)}.")
        if extra and not self.allow_extra_fields:
            raise ValidationError(f"Unexpected feature(s): {sorted(extra)}.")

        normalized: Dict[str, float] = {}
        for name in self.feature_names:
            value = features.get(name)
            if not isinstance(value, (int, float, np.integer, np.floating)) or isinstance(value, bool):
                raise ValidationError(f"Feature '{name}' must be numeric.")
            normalized[name] = float(value)

        request_id = payload.get("request_id")
        if request_id is not None and not isinstance(request_id, str):
            raise ValidationError("'request_id' must be a string if provided.")

        return {
            "request_id": request_id,
            "features": normalized,
            "metadata": payload.get("metadata", {}),
        }


@dataclass(order=True, frozen=True)
class ModelVersion:
    sort_key: Tuple[int, ...] = field(init=False, repr=False)
    version: str
    path: Path

    def __post_init__(self) -> None:
        object.__setattr__(self, "sort_key", self._parse_version(self.version))

    @staticmethod
    def _parse_version(version: str) -> Tuple[int, ...]:
        nums = re.findall(r"\d+", version)
        if not nums:
            return (0,)
        return tuple(int(n) for n in nums)


class ModelArtifact:
    def __init__(self, path: Union[str, Path]) -> None:
        self.path = Path(path)
        self.model: Any = None

    def __enter__(self) -> Any:
        if not self.path.exists():
            raise ModelLoadError(f"Model artifact not found: {self.path}")
        try:
            self.model = joblib.load(self.path)
        except Exception as exc:
            raise ModelLoadError(f"Failed to load model artifact: {self.path}") from exc
        return self.model

    def __exit__(self, exc_type, exc, tb) -> None:
        self.model = None
        return None


class VersionedModelStore:
    def __init__(self, model_dir: Union[str, Path], file_pattern: str = "model_*.joblib") -> None:
        self.model_dir = Path(model_dir)
        self.file_pattern = file_pattern

    def _extract_version(self, path: Path) -> str:
        stem = path.stem
        match = re.search(r"(\d+(?:[._-]\d+)*)", stem)
        return match.group(1).replace("_", ".").replace("-", ".") if match else "0"

    def list_versions(self) -> List[ModelVersion]:
        if not self.model_dir.exists():
            raise ModelLoadError(f"Model directory does not exist: {self.model_dir}")
        versions = [
            ModelVersion(version=self._extract_version(path), path=path)
            for path in self.model_dir.glob(self.file_pattern)
            if path.is_file()
        ]
        if not versions:
            raise ModelLoadError(f"No model artifacts found in {self.model_dir} matching {self.file_pattern}")
        return sorted(versions)

    def latest(self) -> ModelVersion:
        return self.list_versions()[-1]


@dataclass
class LoadedModel:
    model: Any
    version: str
    path: Path
    loaded_at: float
    feature_names: List[str]
    classes: List[Any]


class ModelManager:
    def __init__(self, store: VersionedModelStore, logger: logging.Logger) -> None:
        self.store = store
        self.logger = logger
        self._lock = threading.RLock()
        self._loaded: Optional[LoadedModel] = None

    def _infer_feature_names(self, model: Any) -> List[str]:
        if hasattr(model, "feature_names_in_"):
            return [str(x) for x in list(model.feature_names_in_)]
        if hasattr(model, "n_features_in_"):
            return [f"f{i}" for i in range(int(model.n_features_in_))]
        raise ModelLoadError("Unable to infer feature names from model. Model must expose feature_names_in_ or n_features_in_.")

    def _infer_classes(self, model: Any) -> List[Any]:
        if hasattr(model, "classes_"):
            return list(model.classes_)
        raise ModelLoadError("Loaded classifier does not expose classes_.")

    def _load_version(self, mv: ModelVersion) -> LoadedModel:
        with ModelArtifact(mv.path) as model:
            feature_names = self._infer_feature_names(model)
            classes = self._infer_classes(model)
            loaded = LoadedModel(
                model=model,
                version=mv.version,
                path=mv.path,
                loaded_at=time.time(),
                feature_names=feature_names,
                classes=classes,
            )
            self.logger.info(
                "model_loaded",
                extra={"extra_data": {"event": "model_loaded", "version": mv.version, "path": str(mv.path)}},
            )
            return loaded

    def get_model(self) -> LoadedModel:
        with self._lock:
            latest = self.store.latest()
            if self._loaded is None:
                self._loaded = self._load_version(latest)
            elif latest.sort_key > ModelVersion(version=self._loaded.version, path=self._loaded.path).sort_key:
                self._loaded = self._load_version(latest)
                self.logger.info(
                    "model_hot_reloaded",
                    extra={"extra_data": {"event": "model_hot_reloaded", "version": latest.version}},
                )
            return self._loaded

    def force_reload(self) -> LoadedModel:
        with self._lock:
            latest = self.store.latest()
            self._loaded = self._load_version(latest)
            return self._loaded


@dataclass
class PredictionRequest:
    payload: Dict[str, Any]
    submitted_at: float
    result_queue: "queue.Queue[Dict[str, Any]]"


class InferencePipeline:
    def __init__(
        self,
        model_dir: Union[str, Path],
        batch_size: int = 32,
        batch_timeout_ms: int = 50,
        model_file_pattern: str = "model_*.joblib",
        logger_name: str = "inference_pipeline",
        log_level: int = logging.INFO,
    ) -> None:
        self.batch_size = int(batch_size)
        self.batch_timeout_ms = int(batch_timeout_ms)
        self._request_queue: "queue.Queue[PredictionRequest]" = queue.Queue()
        self._stop_event = threading.Event()
        self._worker_thread: Optional[threading.Thread] = None
        self._prediction_lock = threading.RLock()

        self._logger_cm = StructuredLogger(name=logger_name, level=log_level)
        self.logger = self._logger_cm.__enter__()

        self.model_store = VersionedModelStore(model_dir=model_dir, file_pattern=model_file_pattern)
        self.model_manager = ModelManager(self.model_store, self.logger)

        initial_model = self.model_manager.get_model()
        self.schema = RequestSchema(feature_names=initial_model.feature_names)

    def __enter__(self) -> "InferencePipeline":
        self.start()
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()
        return None

    def start(self) -> None:
        if self._worker_thread and self._worker_thread.is_alive():
            return
        self._stop_event.clear()
        self._worker_thread = threading.Thread(target=self._batch_worker, name="inference-batch-worker", daemon=True)
        self._worker_thread.start()
        self.logger.info("pipeline_started", extra={"extra_data": {"event": "pipeline_started"}})

    def close(self) -> None:
        self._stop_event.set()
        if self._worker_thread and self._worker_thread.is_alive():
            self._worker_thread.join(timeout=2.0)
        self.logger.info("pipeline_stopped", extra={"extra_data": {"event": "pipeline_stopped"}})

    def _refresh_schema_if_needed(self, model: LoadedModel) -> None:
        if list(self.schema.feature_names) != list(model.feature_names):
            self.schema = RequestSchema(feature_names=model.feature_names)

    def validate_request(self, payload: Union[str, Dict[str, Any]]) -> Dict[str, Any]:
        model = self.model_manager.get_model()
        self._refresh_schema_if_needed(model)
        return self.schema.validate(payload)

    def predict(self, payload: Union[str, Dict[str, Any]], timeout: Optional[float] = None) -> Dict[str, Any]:
        validated = self.validate_request(payload)
        result_queue: "queue.Queue[Dict[str, Any]]" = queue.Queue(maxsize=1)
        request = PredictionRequest(payload=validated, submitted_at=time.perf_counter(), result_queue=result_queue)
        self._request_queue.put(request)
        try:
            return result_queue.get(timeout=timeout)
        except queue.Empty as exc:
            raise BatchTimeoutError("Timed out waiting for prediction result.") from exc

    def predict_many(self, payloads: Sequence[Union[str, Dict[str, Any]]], timeout: Optional[float] = None) -> List[Dict[str, Any]]:
        requests = []
        for payload in payloads:
            validated = self.validate_request(payload)
            result_queue: "queue.Queue[Dict[str, Any]]" = queue.Queue(maxsize=1)
            request = PredictionRequest(payload=validated, submitted_at=time.perf_counter(), result_queue=result_queue)
            self._request_queue.put(request)
            requests.append(result_queue)

        results: List[Dict[str, Any]] = []
        for result_queue in requests:
            try:
                results.append(result_queue.get(timeout=timeout))
            except queue.Empty as exc:
                raise BatchTimeoutError("Timed out waiting for one or more prediction results.") from exc
        return results

    def _batch_worker(self) -> None:
        while not self._stop_event.is_set():
            batch: List[PredictionRequest] = []
            try:
                first = self._request_queue.get(timeout=0.05)
                batch.append(first)
            except queue.Empty:
                continue

            deadline = time.perf_counter() + (self.batch_timeout_ms / 1000.0)
            while len(batch) < self.batch_size:
                remaining = deadline - time.perf_counter()
                if remaining <= 0:
                    break
                try:
                    batch.append(self._request_queue.get(timeout=remaining))
                except queue.Empty:
                    break

            self._process_batch(batch)

    def _process_batch(self, batch: List[PredictionRequest]) -> None:
        try:
            model = self.model_manager.get_model()
            self._refresh_schema_if_needed(model)

            feature_order = model.feature_names
            matrix = np.array(
                [[req.payload["features"][name] for name in feature_order] for req in batch],
                dtype=float,
            )

            with self._prediction_lock:
                try:
                    labels = model.model.predict(matrix)
                    probabilities = model.model.predict_proba(matrix)
                except Exception as exc:
                    raise PredictionError("Model prediction failed.") from exc

            for idx, req in enumerate(batch):
                latency_ms = round((time.perf_counter() - req.submitted_at) * 1000.0, 3)
                response = {
                    "request_id": req.payload.get("request_id"),
                    "status": "ok",
                    "prediction": {
                        "label": self._to_native(labels[idx]),
                        "probabilities": {
                            str(cls): float(probabilities[idx][class_idx])
                            for class_idx, cls in enumerate(model.classes)
                        },
                    },
                    "model_version": model.version,
                    "latency_ms": latency_ms,
                }
                req.result_queue.put(response)

            self.logger.info(
                "batch_processed",
                extra={
                    "extra_data": {
                        "event": "batch_processed",
                        "batch_size": len(batch),
                        "model_version": model.version,
                    }
                },
            )
        except Exception as exc:
            self.logger.error(
                "batch_processing_failed",
                extra={
                    "extra_data": {
                        "event": "batch_processing_failed",
                        "batch_size": len(batch),
                        "error": str(exc),
                    }
                },
            )
            for req in batch:
                latency_ms = round((time.perf_counter() - req.submitted_at) * 1000.0, 3)
                req.result_queue.put(
                    {
                        "request_id": req.payload.get("request_id"),
                        "status": "error",
                        "error": {
                            "type": exc.__class__.__name__,
                            "message": str(exc),
                        },
                        "model_version": getattr(getattr(self.model_manager, "_loaded", None), "version", None),
                        "latency_ms": latency_ms,
                    }
                )

    @staticmethod
    def _to_native(value: Any) -> Any:
        if isinstance(value, np.generic):
            return value.item()
        return value


__all__ = [
    "InferencePipeline",
    "InferenceError",
    "ValidationError",
    "ModelLoadError",
    "PredictionError",
    "BatchTimeoutError",
]

class MaxStack:
    def __init__(self):
        # Each item stores (value, current_max_at_this_point)
        self._data = []

    def push(self, x):
        current_max = x if not self._data else max(x, self._data[-1][1])
        self._data.append((x, current_max))

    def pop(self):
        if not self._data:
            return "EMPTY"
        return self._data.pop()[0]

    def top(self):
        if not self._data:
            return "EMPTY"
        return self._data[-1][0]

    def get_max(self):
        if not self._data:
            return "EMPTY"
        return self._data[-1][1]


class TwoStackQueue:
    def __init__(self):
        self._in = []
        self._out = []

    def _shift(self):
        # Move items only when needed to preserve amortized O(1)
        if not self._out:
            while self._in:
                self._out.append(self._in.pop())

    def enqueue(self, x):
        self._in.append(x)

    def dequeue(self):
        self._shift()
        if not self._out:
            return "EMPTY"
        return self._out.pop()

    def peek(self):
        self._shift()
        if not self._out:
            return "EMPTY"
        return self._out[-1]


class MaxQueueStackProcessor:
    def __init__(self):
        self.queue = TwoStackQueue()
        self.stack = MaxStack()

    def process(self, operations):
        result = []

        for op in operations:
            parts = op.split()
            cmd = parts[0]

            if cmd == "ENQUEUE":
                self.queue.enqueue(int(parts[1]))
            elif cmd == "DEQUEUE":
                result.append(self.queue.dequeue())
            elif cmd == "QPEEK":
                result.append(self.queue.peek())
            elif cmd == "PUSH":
                self.stack.push(int(parts[1]))
            elif cmd == "POP":
                result.append(self.stack.pop())
            elif cmd == "TOP":
                result.append(self.stack.top())
            elif cmd == "MAX":
                result.append(self.stack.get_max())
            else:
                raise ValueError(f"Unknown operation: {cmd}")

        return result


# Example usage:
# ops = [
#     "ENQUEUE 5", "ENQUEUE 9", "QPEEK", "DEQUEUE",
#     "PUSH 3", "PUSH 7", "MAX", "POP", "TOP", "MAX"
# ]
# processor = MaxQueueStackProcessor()
# print(processor.process(ops))
# Output: [5, 5, 7, 7, 3, 3]

from __future__ import annotations

from dataclasses import dataclass, field
from typing import List, Tuple


@dataclass(frozen=True)
class Event:
    id: str
    title: str
    start_minute: int
    duration: int
    tags: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if not (0 <= self.start_minute <= 1439):
            raise ValueError("start_minute must be between 0 and 1439")
        if self.duration <= 0:
            raise ValueError("duration must be positive")

    @property
    def end_minute(self) -> int:
        return self.start_minute + self.duration


@dataclass(frozen=True)
class Schedule:
    events: tuple[Event, ...] = field(default_factory=tuple)

    def add_event(self, event: Event) -> Schedule:
        # Reject duplicate event IDs and return a new immutable schedule.
        if any(existing.id == event.id for existing in self.events):
            raise ValueError(f"duplicate event id: {event.id}")
        return Schedule(self.events + (event,))

    def overlapping(self) -> List[Tuple[Event, Event]]:
        overlaps: List[Tuple[Event, Event]] = []
        sorted_events = sorted(self.events, key=lambda e: e.start_minute)

        for i, current in enumerate(sorted_events):
            for other in sorted_events[i + 1:]:
                # Because events are sorted, we can stop early.
                if other.start_minute >= current.end_minute:
                    break
                if current.start_minute < other.end_minute and other.start_minute < current.end_minute:
                    overlaps.append((current, other))

        return overlaps

    def filter_by_tag(self, tag: str) -> List[Event]:
        return [event for event in self.events if tag in event.tags]


if __name__ == "__main__":
    schedule = Schedule()
    schedule = schedule.add_event(Event("e1", "Standup", 540, 15, ("work", "team")))
    schedule = schedule.add_event(Event("e2", "Code Review", 550, 30, ("work",)))
    schedule = schedule.add_event(Event("e3", "Lunch", 720, 60, ("personal",)))

    print("Work events:", schedule.filter_by_tag("work"))
    print("Overlaps:", schedule.overlapping())

import time
from collections import OrderedDict
from functools import update_wrapper
from threading import RLock


class CacheWithTTL:
    def __init__(self, ttl, maxsize=128):
        self.ttl = ttl
        self.maxsize = maxsize

    def __call__(self, func):
        cache = OrderedDict()  # key -> (value, expires_at)
        lock = RLock()
        stats = {"hits": 0, "misses": 0}

        def make_key(args, kwargs):
            # Hashable key built from args and sorted kwargs
            return args, tuple(sorted(kwargs.items()))

        def cache_info():
            with lock:
                return {
                    "hits": stats["hits"],
                    "misses": stats["misses"],
                    "current_size": len(cache),
                    "max_size": self.maxsize,
                }

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = time.time()

            with lock:
                if key in cache:
                    value, expires_at = cache[key]
                    if now < expires_at:
                        stats["hits"] += 1
                        cache.move_to_end(key)  # mark as recently used
                        return value
                    del cache[key]  # expired entry

                stats["misses"] += 1

            # Compute outside the lock to avoid blocking other threads
            value = func(*args, **kwargs)
            expires_at = time.time() + self.ttl

            with lock:
                cache[key] = (value, expires_at)
                cache.move_to_end(key)
                while len(cache) > self.maxsize:
                    cache.popitem(last=False)  # evict least recently used

            return value

        wrapper.cache_info = cache_info
        return update_wrapper(wrapper, func)


@CacheWithTTL(ttl=2, maxsize=5)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)


if __name__ == "__main__":
    print(fib(30))  # initial computation
    print(fib(30))  # cached
    print(fib(28))  # likely cached from recursion
    print(fib.cache_info())

    time.sleep(2.1)  # allow TTL to expire
    print(fib(30))  # recomputed after expiration
    print(fib.cache_info())

def analyze_orders(orders):
    # Track unique items ordered by each customer
    customer_items = {}

    # Track unique items seen for each order status
    items_by_status = {}

    # Track statuses associated with each customer
    customer_statuses = {}

    for order in orders:
        customer = order['customer']
        items = order['items']
        status = order['status']

        # Initialize dictionary entries when needed
        customer_items.setdefault(customer, set())
        items_by_status.setdefault(status, set())
        customer_statuses.setdefault(customer, set())

        # Update sets with current order data
        customer_items[customer].update(items)
        items_by_status[status].update(items)
        customer_statuses[customer].add(status)

    # Convert customer item sets into counts
    customer_item_counts = {
        customer: len(items)
        for customer, items in customer_items.items()
    }

    # Find customers who appear under multiple statuses
    customers_with_multiple_statuses = {
        customer
        for customer, statuses in customer_statuses.items()
        if len(statuses) > 1
    }

    return {
        'customer_item_counts': customer_item_counts,
        'all_items_by_status': items_by_status,
        'customers_with_multiple_statuses': customers_with_multiple_statuses,
    }


if __name__ == '__main__':
    sample_orders = [
        {'customer': 'Alice', 'items': ['apple', 'banana'], 'status': 'shipped'},
        {'customer': 'Bob', 'items': ['banana', 'carrot'], 'status': 'pending'},
        {'customer': 'Alice', 'items': ['apple', 'dates'], 'status': 'pending'},
        {'customer': 'Cara', 'items': ['eggs'], 'status': 'shipped'},
        {'customer': 'Bob', 'items': ['fig', 'carrot'], 'status': 'pending'},
    ]

    result = analyze_orders(sample_orders)
    print('Customer item counts:', result['customer_item_counts'])
    print('All items by status:', result['all_items_by_status'])
    print('Customers with multiple statuses:', result['customers_with_multiple_statuses'])

import math
import random


def fitness(x):
    return x * math.sin(10 * math.pi * x) + 1.0


def tournament_selection(population, k=3):
    competitors = random.sample(population, k)
    return max(competitors, key=fitness)


def crossover(parent1, parent2):
    alpha = random.random()
    child = alpha * parent1 + (1 - alpha) * parent2
    return min(1.0, max(0.0, child))


def mutate(x, mutation_rate=0.2, mutation_strength=0.1):
    if random.random() < mutation_rate:
        x += random.uniform(-mutation_strength, mutation_strength)
    return min(1.0, max(0.0, x))


def genetic_algorithm(pop_size=30, generations=50):
    population = [random.uniform(0.0, 1.0) for _ in range(pop_size)]

    for _ in range(generations):
        new_population = []

        # Elitism: keep the best solution
        best = max(population, key=fitness)
        new_population.append(best)

        while len(new_population) < pop_size:
            parent1 = tournament_selection(population)
            parent2 = tournament_selection(population)
            child = crossover(parent1, parent2)
            child = mutate(child)
            new_population.append(child)

        population = new_population

    best_solution = max(population, key=fitness)
    return best_solution, fitness(best_solution)


if __name__ == '__main__':
    random.seed()
    best_x, best_fit = genetic_algorithm()
    print(f'Best x: {best_x:.6f}')
    print(f'Best fitness: {best_fit:.6f}')

from collections.abc import Callable


def process_jobs(jobs):
    """Execute job definitions with validation, retries, and error tracking."""
    summary = {
        "results": {},
        "errors": {},
        "attempts": {},
    }

    for index, job in enumerate(jobs):
        job_name = f"job_{index}"
        attempts = 0

        try:
            # Validate the job structure early.
            if not isinstance(job, dict):
                raise ValueError("job must be a dictionary")

            name = job.get("name")
            if not isinstance(name, str) or not name.strip():
                raise ValueError("job 'name' must be a non-empty string")
            job_name = name

            action = job.get("action")
            if not isinstance(action, Callable):
                raise ValueError("job 'action' must be callable")

            args = job.get("args", [])
            kwargs = job.get("kwargs", {})
            retries = job.get("retries", 0)

            if not isinstance(args, list):
                raise ValueError("job 'args' must be a list")
            if not isinstance(kwargs, dict):
                raise ValueError("job 'kwargs' must be a dictionary")
            if not isinstance(retries, int) or retries < 0:
                raise ValueError("job 'retries' must be a non-negative integer")

            # Attempt once plus up to `retries` more on TimeoutError.
            while True:
                attempts += 1
                try:
                    result = action(*args, **kwargs)
                    summary["results"][job_name] = result
                    break
                except TimeoutError as exc:
                    if attempts > retries:
                        summary["errors"][job_name] = f"TimeoutError: {exc}"
                        break
                    # Retry only on timeout.
                    continue
                except Exception as exc:
                    # Non-timeout exceptions fail immediately.
                    summary["errors"][job_name] = f"{type(exc).__name__}: {exc}"
                    break

        except Exception as exc:
            # Validation or unexpected per-job setup errors are captured here.
            attempts = max(attempts, 1)
            summary["errors"][job_name] = f"{type(exc).__name__}: {exc}"
        finally:
            summary["attempts"][job_name] = attempts

    return summary


# Example usage
if __name__ == "__main__":
    state = {"flaky_calls": 0}

    def add(a, b):
        return a + b

    def flaky():
        state["flaky_calls"] += 1
        if state["flaky_calls"] < 3:
            raise TimeoutError("temporary network issue")
        return "ok"

    def bad():
        raise RuntimeError("unexpected failure")

    jobs = [
        {"name": "sum", "action": add, "args": [2, 3]},
        {"name": "retry_me", "action": flaky, "retries": 3},
        {"name": "explode", "action": bad, "retries": 5},
        {"name": "invalid", "action": "not_callable"},
    ]

    print(process_jobs(jobs))

from typing import List


def count_descending_paths(grid: List[List[int]]) -> int:
    """Return the number of strictly descending paths from (0, 0) to (rows-1, cols-1)."""
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    memo = {}
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def dfs(r: int, c: int) -> int:
        # Reached destination: count one valid path.
        if (r, c) == (rows - 1, cols - 1):
            return 1

        if (r, c) in memo:
            return memo[(r, c)]

        total_paths = 0
        current_height = grid[r][c]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] < current_height:
                total_paths += dfs(nr, nc)

        memo[(r, c)] = total_paths
        return total_paths

    return dfs(0, 0)


if __name__ == "__main__":
    sample_grid = [
        [9, 5, 3],
        [8, 4, 2],
        [7, 6, 1]
    ]
    print(count_descending_paths(sample_grid))  # Example output: 5

