class MaxStack:
    def __init__(self):
        self.data = []
        self.max_data = []

    def push(self, x):
        self.data.append(x)
        if not self.max_data:
            self.max_data.append(x)
        else:
            self.max_data.append(max(x, self.max_data[-1]))

    def pop(self):
        if not self.data:
            return 'EMPTY'
        self.max_data.pop()
        return self.data.pop()

    def max(self):
        return self.max_data[-1] if self.max_data else 'EMPTY'

    def empty(self):
        return not self.data


class MaxQueue:
    def __init__(self):
        self.in_stack = MaxStack()
        self.out_stack = MaxStack()

    def enqueue(self, x):
        self.in_stack.push(x)

    def _shift(self):
        if self.out_stack.empty():
            while not self.in_stack.empty():
                self.out_stack.push(self.in_stack.pop())

    def dequeue(self):
        self._shift()
        return self.out_stack.pop()

    def max(self):
        in_max = self.in_stack.max()
        out_max = self.out_stack.max()
        if in_max == 'EMPTY':
            return out_max
        if out_max == 'EMPTY':
            return in_max
        return max(in_max, out_max)


class MaxQueueStackManager:
    def __init__(self):
        self.queue = MaxQueue()
        self.stack = MaxStack()

    def process(self, commands):
        result = []
        for cmd in commands:
            parts = cmd.split()
            op = parts[0]

            if op == 'ENQUEUE':
                self.queue.enqueue(int(parts[1]))
            elif op == 'DEQUEUE':
                result.append(self.queue.dequeue())
            elif op == 'PUSH':
                self.stack.push(int(parts[1]))
            elif op == 'POP':
                result.append(self.stack.pop())
            elif op == 'QMAX':
                result.append(self.queue.max())
            elif op == 'SMAX':
                result.append(self.stack.max())

        return result


