import re


class Notifier(ABC):
    @property
    @abstractmethod
    def channel(self) -> str:
        """Unique channel name for this notifier."""
        raise NotImplementedError

    @abstractmethod
    def send(self, recipient: str, message: str) -> str:
        """Send a message and return a delivery summary."""
        raise NotImplementedError


class EmailNotifier(Notifier):
    EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")

    @property
    def channel(self) -> str:
        return "email"

    def send(self, recipient: str, message: str) -> str:
        if not self.EMAIL_RE.match(recipient):
            raise ValueError(f"Invalid email recipient: {recipient}")
        return f"EMAIL to {recipient}: {message}"


class SMSNotifier(Notifier):
    PHONE_RE = re.compile(r"^\+?\d{10,15}$")

    @property
    def channel(self) -> str:
        return "sms"

    def send(self, recipient: str, message: str) -> str:
        if not self.PHONE_RE.match(recipient):
            raise ValueError(f"Invalid phone recipient: {recipient}")
        return f"SMS to {recipient}: {message}"


class NotificationManager:
    def __init__(self, notifiers: list[Notifier]):
        self._notifiers = {}
        for notifier in notifiers:
            if notifier.channel in self._notifiers:
                raise ValueError(f"Duplicate channel: {notifier.channel}")
            self._notifiers[notifier.channel] = notifier

    def dispatch(self, channel: str, recipient: str, message: str) -> str:
        notifier = self._notifiers.get(channel)
        if notifier is None:
            raise ValueError(f"Unknown channel: {channel}")
        return notifier.send(recipient, message)


