from functools import lru_cache


def word_break_count(s, words):
    """Return the number of ways to segment s using words from the dictionary."""
    word_set = set(words)  # Fast membership checks
    n = len(s)

    @lru_cache(maxsize=None)
    def count_from(start):
        # Reached the end: one valid segmentation found
        if start == n:
            return 1

        total = 0

        # Try every possible next word starting at 'start'
        for end in range(start + 1, n + 1):
            piece = s[start:end]
            if piece in word_set:
                total += count_from(end)

        return total

    return count_from(0)


if __name__ == "__main__":
    s = "pineapplepenapple"
    words = ["apple", "pen", "applepen", "pine", "pineapple"]
    print(word_break_count(s, words))

