@dataclass
class Customer:
    name: str
    is_vip: bool = False


class DiscountStrategy(ABC):
    @abstractmethod
    def apply(self, total: float, customer: Customer) -> float:
        """Return the discounted total."""


class NoDiscount(DiscountStrategy):
    def apply(self, total: float, customer: Customer) -> float:
        return total


class PercentageDiscount(DiscountStrategy):
    def __init__(self, percent: float) -> None:
        self.percent = percent

    def apply(self, total: float, customer: Customer) -> float:
        return total * (1 - self.percent / 100)


class TieredDiscount(DiscountStrategy):
    def apply(self, total: float, customer: Customer) -> float:
        if total >= 500:
            return total * 0.90
        if total >= 100:
            return total * 0.95
        return total


class VipDiscount(DiscountStrategy):
    def apply(self, total: float, customer: Customer) -> float:
        return total * 0.85 if customer.is_vip else total


class Checkout:
    def __init__(self, strategy: DiscountStrategy) -> None:
        self.strategy = strategy

    def set_strategy(self, strategy: DiscountStrategy) -> None:
        self.strategy = strategy

    def total(self, prices: Iterable[float], customer: Customer) -> float:
        subtotal = sum(prices)
        final_total = self.strategy.apply(subtotal, customer)
        return round(final_total, 2)


