class BloomFilter:
    def __init__(self, size, hash_count):
        # Fixed-size bit array using 0/1 integers
        self.size = size
        self.hash_count = hash_count
        self.bits = [0] * size

    def _hashes(self, item):
        # Generate multiple hash positions by combining the item with an index
        for i in range(self.hash_count):
            yield hash(f"{item}:{i}") % self.size

    def add(self, item):
        # Set all hashed positions to 1
        for index in self._hashes(item):
            self.bits[index] = 1

    def might_contain(self, item):
        # If any required bit is 0, the item is definitely not present
        return all(self.bits[index] == 1 for index in self._hashes(item))


if __name__ == "__main__":
    bloom = BloomFilter(size=20, hash_count=3)

    # Add some words
    for word in ["apple", "banana", "grape"]:
        bloom.add(word)

    # Test membership
    test_words = ["apple", "banana", "orange", "melon", "grape"]
    for word in test_words:
        if bloom.might_contain(word):
            print(f"{word}: possibly in set")
        else:
            print(f"{word}: definitely not in set")

import hashlib


def verify_download(path, expected_sha256):
    """Return True if the file's SHA-256 matches the expected hex digest."""
    hasher = hashlib.sha256()

    try:
        with open(path, 'rb') as file:
            for chunk in iter(lambda: file.read(8192), b''):
                hasher.update(chunk)
    except FileNotFoundError:
        return False

    actual_sha256 = hasher.hexdigest()
    return actual_sha256.lower() == expected_sha256.strip().lower()


if __name__ == '__main__':
    file_path = input().strip()
    expected_hash = input().strip()

    if verify_download(file_path, expected_hash):
        print('OK')
    else:
        print('MISMATCH')

