class EvenIterator:
    """Iterator that yields the first n even numbers starting from 0."""

    def __init__(self, n):
        self.n = n
        self.current_index = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.current_index >= self.n:
            raise StopIteration

        value = self.current_index * 2
        self.current_index += 1
        return value


def even_generator(n):
    """Generator that yields the first n even numbers starting from 0."""
    for i in range(n):
        yield i * 2


def main():
    n = int(input("Enter how many even numbers to generate: "))

    iterator_result = list(EvenIterator(n))
    generator_result = list(even_generator(n))

