from collections import defaultdict
from typing import Callable, Dict, List, Set


class PluginManager:
    def __init__(self) -> None:
        self._plugins: Dict[str, Callable[[str], str]] = {}
        self._deps: Dict[str, List[str]] = defaultdict(list)

    def register(self, name: str, func: Callable[[str], str], after: List[str] | None = None) -> None:
        """Register a plugin with optional dependencies."""
        if name in self._plugins:
            raise ValueError(f"Plugin '{name}' is already registered")
        self._plugins[name] = func
        self._deps[name] = list(after or [])

    def _resolve_order(self) -> List[str]:
        """Topologically sort plugins and validate dependency graph."""
        for name, deps in self._deps.items():
            for dep in deps:
                if dep not in self._plugins:
                    raise ValueError(f"Plugin '{name}' depends on missing plugin '{dep}'")

        order: List[str] = []
        visiting: Set[str] = set()
        visited: Set[str] = set()

        def dfs(name: str) -> None:
            if name in visited:
                return
            if name in visiting:
                raise ValueError(f"Circular dependency detected at plugin '{name}'")

            visiting.add(name)
            for dep in self._deps[name]:
                dfs(dep)
            visiting.remove(name)
            visited.add(name)
            order.append(name)

        for name in self._plugins:
            dfs(name)

        return order

    def run(self, text: str) -> str:
        """Execute all plugins in dependency-safe order."""
        result = text
        for name in self._resolve_order():
            result = self._plugins[name](result)
        return result


# Example usage
if __name__ == "__main__":
    manager = PluginManager()

    manager.register("trim", lambda s: s.strip())
    manager.register("lowercase", lambda s: s.lower(), after=["trim"])
    manager.register("slugify", lambda s: s.replace(" ", "-"), after=["lowercase"])

    text = "  Hello Plugin World  "
    print(manager.run(text))  # hello-plugin-world

