class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.size = [1] * n
        self.components = n

    def find(self, x: int) -> int:
        # Path compression
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False

        # Union by size
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra

        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.components -= 1
        return True


def earliest_full_connectivity(n: int, logs):
    if n <= 1:
        return 0

    uf = UnionFind(n)

    # Process links in chronological order
    for timestamp, a, b in sorted(logs):
        if uf.union(a, b) and uf.components == 1:
            return timestamp

    return -1


