def max_profit_with_k_transactions(prices, k):
    """Return the maximum profit with at most k buy-sell transactions."""
    n = len(prices)
    if n < 2 or k <= 0:
        return 0

    # If k is large, this becomes the unlimited transactions case.
    if k >= n // 2:
        profit = 0
        for i in range(1, n):
            if prices[i] > prices[i - 1]:
                profit += prices[i] - prices[i - 1]
        return profit

    # buy[t]: max profit after buying for the t-th transaction
    # sell[t]: max profit after selling for the t-th transaction
    buy = [float('-inf')] * (k + 1)
    sell = [0] * (k + 1)

    for price in prices:
        for t in range(1, k + 1):
            buy[t] = max(buy[t], sell[t - 1] - price)
            sell[t] = max(sell[t], buy[t] + price)

    return sell[k]


if __name__ == '__main__':
