        ([3, 2, 6, 5, 0, 3], 2),
        ([2, 4, 1], 2),
        ([5, 4, 3, 2, 1], 3),
        ([1, 2, 3, 4, 5], 1),
    ]

    for prices, k in examples:
        print(f'prices={prices}, k={k} -> {max_profit_with_k_transactions(prices, k)}')

import random

# Target binary string to evolve toward
TARGET = "10110101100101101010"
POPULATION_SIZE = 10
MUTATION_RATE = 0.05
MAX_GENERATIONS = 50


def random_individual(length):
    return ''.join(random.choice('01') for _ in range(length))


def fitness(individual):
    return sum(1 for a, b in zip(individual, TARGET) if a == b)


def crossover(parent1, parent2):
    point = random.randint(1, len(parent1) - 1)
    return parent1[:point] + parent2[point:]


def mutate(individual):
    bits = list(individual)
    for i in range(len(bits)):
        if random.random() < MUTATION_RATE:
            bits[i] = '1' if bits[i] == '0' else '0'
    return ''.join(bits)


def main():
    population = [random_individual(len(TARGET)) for _ in range(POPULATION_SIZE)]

    for generation in range(1, MAX_GENERATIONS + 1):
        population.sort(key=fitness, reverse=True)
        best = population[0]
        best_score = fitness(best)

        print(f"Generation {generation}: best = {best}, fitness = {best_score}")

        if best == TARGET:
            print("Target found!")
            break

        survivors = population[:POPULATION_SIZE // 2]
        next_population = survivors[:]

        while len(next_population) < POPULATION_SIZE:
            parent1 = random.choice(survivors)
            parent2 = random.choice(survivors)
            child = crossover(parent1, parent2)
            child = mutate(child)
            next_population.append(child)

        population = next_population

    population.sort(key=fitness, reverse=True)
    print("\nFinal best individual:", population[0])
    print("Final fitness:", fitness(population[0]))
    print("Target:", TARGET)


if __name__ == "__main__":
    main()

