import time
import json
import hmac
import hashlib
from typing import Dict, Any

# Simple in-memory replay cache: event_id -> first_seen_timestamp
_SEEN_EVENTS: Dict[str, int] = {}


def _prune_seen_events(now: int, ttl: int) -> None:
    """Remove expired event IDs from the replay cache."""
    expired = [event_id for event_id, seen_at in _SEEN_EVENTS.items() if now - seen_at > ttl]
    for event_id in expired:
        del _SEEN_EVENTS[event_id]


def handle_webhook(
    headers: dict,
    body: bytes,
    secret: str,
    replay_window_seconds: int = 300,
) -> dict:
    """Validate and parse a signed webhook request."""
    required = ("X-Signature", "X-Timestamp", "X-Event-Id")
    missing = [name for name in required if name not in headers]
    if missing:
        raise ValueError(f"Missing required headers: {', '.join(missing)}")

    signature = headers["X-Signature"]
    event_id = headers["X-Event-Id"]

    try:
        timestamp = int(headers["X-Timestamp"])
    except (TypeError, ValueError):
        raise ValueError("Invalid X-Timestamp header")

    now = int(time.time())
    if abs(now - timestamp) > replay_window_seconds:
        raise ValueError("Webhook timestamp is outside the replay window")

    _prune_seen_events(now, replay_window_seconds)
    if event_id in _SEEN_EVENTS:
        raise ValueError("Duplicate webhook event ID")

    signed_payload = f"{timestamp}.".encode("utf-8") + body
    expected_signature = hmac.new(
        secret.encode("utf-8"),
        signed_payload,
        hashlib.sha256,
    ).hexdigest()

    if not hmac.compare_digest(signature, expected_signature):
        raise ValueError("Invalid webhook signature")

    try:
        payload: Dict[str, Any] = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError("Invalid JSON body")

    if not isinstance(payload, dict):
        raise ValueError("JSON body must be an object")
    if "event_type" not in payload or "data" not in payload:
        raise ValueError("JSON body must include 'event_type' and 'data'")

    _SEEN_EVENTS[event_id] = now

    return {
        "ok": True,
        "event_id": event_id,
        "event_type": payload["event_type"],
        "data": payload["data"],
    }

from collections import defaultdict
from typing import Any, Callable, Dict, List


class EventBus:
    def __init__(self) -> None:
        # topic -> ordered list of callbacks
        self._subscribers: Dict[str, List[Callable[[str, Any], None]]] = defaultdict(list)

    def subscribe(self, topic: str, callback: Callable[[str, Any], None]) -> None:
        callbacks = self._subscribers[topic]
        if callback not in callbacks:  # prevent duplicates
            callbacks.append(callback)

    def unsubscribe(self, topic: str, callback: Callable[[str, Any], None]) -> None:
        callbacks = self._subscribers.get(topic)
        if not callbacks:
            return
        if callback in callbacks:
            callbacks.remove(callback)
        if not callbacks:
            del self._subscribers[topic]

    def publish(self, topic: str, payload: Any) -> None:
        # Exact subscribers first
        for callback in list(self._subscribers.get(topic, [])):
            callback(topic, payload)

        # Then wildcard subscribers, preserving subscription order per pattern
        for pattern, callbacks in list(self._subscribers.items()):
            if pattern.endswith('*') and topic.startswith(pattern[:-1]):
                for callback in list(callbacks):
                    callback(topic, payload)


class TemperatureSensor:
    def __init__(self, location: str, bus: EventBus) -> None:
        self.location = location
        self.bus = bus

    def update(self, celsius: float) -> None:
        self.bus.publish(f"sensor.{self.location}", {"celsius": celsius})


def main() -> None:
    bus = EventBus()
    received: List[str] = []

    def dashboard(topic: str, payload: Any) -> None:
        received.append(f"dashboard:{topic}={payload['celsius']}")

    def alerting(topic: str, payload: Any) -> None:
        if payload["celsius"] > 25:
            received.append(f"alert:{topic}=HIGH")
        else:
            received.append(f"alert:{topic}=OK")

    def kitchen_only(topic: str, payload: Any) -> None:
        received.append(f"kitchen:{payload['celsius']}")

    bus.subscribe("sensor.*", dashboard)
    bus.subscribe("sensor.*", alerting)
    bus.subscribe("sensor.kitchen", kitchen_only)
    bus.subscribe("sensor.kitchen", kitchen_only)  # ignored duplicate

    kitchen = TemperatureSensor("kitchen", bus)
    office = TemperatureSensor("office", bus)

    kitchen.update(22.5)
    office.update(27.1)

    bus.unsubscribe("sensor.*", alerting)
    kitchen.update(26.0)

    for item in received:
        print(item)


if __name__ == "__main__":
    main()
}

from typing import Callable, Dict, List


class PluginManager:
    def __init__(self):
        self._plugins: Dict[str, Callable[[str], str]] = {}

    def register(self, name: str, plugin: Callable[[str], str]) -> None:
        """Register a plugin function under a unique name."""
        self._plugins[name] = plugin

    def run_pipeline(self, text: str, pipeline: List[str]) -> str:
        """Run the given text through each plugin in order."""
        result = text
        for name in pipeline:
            if name not in self._plugins:
                raise ValueError(f"Plugin '{name}' is not registered")
            result = self._plugins[name](result)
        return result


