import json
import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin


def fetch_page(url, session):
    """Fetch a page and return BeautifulSoup or None on failure."""
    try:
        response = session.get(url, timeout=10)
        response.raise_for_status()
        return BeautifulSoup(response.text, "html.parser")
    except requests.RequestException as e:
        print(f"Failed to fetch {url}: {e}")
        return None


def extract_articles(soup, base_url):
    """Extract article data from common blog-like markup patterns."""
    results = []
    for article in soup.select("article"):
        title_tag = article.select_one("h1 a, h2 a, h3 a, a[href]")
        if not title_tag:
            continue

        title = title_tag.get_text(" ", strip=True)
        href = title_tag.get("href")
        if not href:
            continue

        date_tag = article.select_one("time")
        summary_tag = article.select_one("p")

        results.append({
            "title": title,
            "url": urljoin(base_url, href),
            "published": date_tag.get("datetime") or date_tag.get_text(strip=True) if date_tag else None,
            "summary": summary_tag.get_text(" ", strip=True) if summary_tag else None,
        })
    return results


def find_next_page(soup, base_url):
    """Find a likely next-page link."""
    selectors = [
        'a[rel="next"]',
        'a.next',
        'li.next a',
    ]
    for selector in selectors:
        tag = soup.select_one(selector)
        if tag and tag.get("href"):
            return urljoin(base_url, tag["href"])

    for tag in soup.find_all("a", href=True):
        text = tag.get_text(" ", strip=True).lower()
        if text in {"next", "next page", "older posts", "→", ">"}:
            return urljoin(base_url, tag["href"])
    return None


def scrape_blog(start_url, max_pages=5):
    session = requests.Session()
    session.headers.update({"User-Agent": "Mozilla/5.0 (compatible; BlogScraper/1.0)"})

    seen_urls = set()
    collected = []
    current_url = start_url

    for _ in range(max_pages):
        if not current_url:
            break

        soup = fetch_page(current_url, session)
        if not soup:
            break

        for item in extract_articles(soup, current_url):
            if item["url"] not in seen_urls:
                seen_urls.add(item["url"])
                collected.append(item)

        next_url = find_next_page(soup, current_url)
        if next_url == current_url:
            break
        current_url = next_url

    return collected


if __name__ == "__main__":
    start_url = "https://example.com/blog"
    articles = scrape_blog(start_url, max_pages=5)
    print(json.dumps(articles, indent=2, ensure_ascii=False))

from __future__ import annotations

from collections import defaultdict, deque
from datetime import datetime, timezone
from typing import Any, Dict, Iterable, List, Optional, Sequence, Set, Union


def _parse_timestamp(value: Any) -> datetime:
    if isinstance(value, datetime):
        dt = value
    elif isinstance(value, (int, float)):
        dt = datetime.fromtimestamp(value, tz=timezone.utc)
    elif isinstance(value, str):
        text = value.strip()
        if not text:
            raise ValueError("Timestamp string cannot be empty.")
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        try:
            dt = datetime.fromisoformat(text)
        except ValueError as exc:
            raise ValueError(f"Invalid timestamp format: {value!r}") from exc
    else:
        raise TypeError("Timestamp must be a datetime, ISO string, int, or float.")

    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def analyze_transactions(
    transactions: Sequence[Dict[str, Any]],
    high_value_threshold: Union[int, float] = 10000.0,
    country_change_time_window_seconds: int = 3600,
    rapid_txn_count_threshold: int = 5,
    rapid_txn_window_seconds: int = 300,
) -> List[str]:
    if not isinstance(transactions, Sequence) or isinstance(transactions, (str, bytes)):
        raise TypeError("transactions must be a sequence of transaction dictionaries.")
    if high_value_threshold < 0:
        raise ValueError("high_value_threshold must be non-negative.")
    if country_change_time_window_seconds < 0:
        raise ValueError("country_change_time_window_seconds must be non-negative.")
    if rapid_txn_count_threshold < 1:
        raise ValueError("rapid_txn_count_threshold must be at least 1.")
    if rapid_txn_window_seconds < 0:
        raise ValueError("rapid_txn_window_seconds must be non-negative.")

    required_fields = {
        "transaction_id": str,
        "account_id": str,
        "timestamp": object,
        "amount": (int, float),
        "merchant_category": str,
        "country": str,
        "card_present": bool,
    }

    normalized: List[Dict[str, Any]] = []
    seen_transaction_ids: Set[str] = set()

    for idx, tx in enumerate(transactions):
        if not isinstance(tx, dict):
            raise TypeError(f"Transaction at index {idx} must be a dictionary.")

        for field in required_fields:
            if field not in tx:
                raise ValueError(f"Transaction at index {idx} is missing required field: {field}")

        transaction_id = tx["transaction_id"]
        account_id = tx["account_id"]
        amount = tx["amount"]
        merchant_category = tx["merchant_category"]
        country = tx["country"]
        card_present = tx["card_present"]

        if not isinstance(transaction_id, str) or not transaction_id.strip():
            raise ValueError(f"Invalid transaction_id at index {idx}.")
        if transaction_id in seen_transaction_ids:
            raise ValueError(f"Duplicate transaction_id found: {transaction_id}")
        seen_transaction_ids.add(transaction_id)

        if not isinstance(account_id, str) or not account_id.strip():
            raise ValueError(f"Invalid account_id for transaction {transaction_id}.")
        if not isinstance(amount, (int, float)) or isinstance(amount, bool):
            raise ValueError(f"Invalid amount for transaction {transaction_id}.")
        if amount < 0:
            raise ValueError(f"Amount cannot be negative for transaction {transaction_id}.")
        if not isinstance(merchant_category, str) or not merchant_category.strip():
            raise ValueError(f"Invalid merchant_category for transaction {transaction_id}.")
        if not isinstance(country, str) or not country.strip():
            raise ValueError(f"Invalid country for transaction {transaction_id}.")
        if not isinstance(card_present, bool):
            raise ValueError(f"card_present must be a boolean for transaction {transaction_id}.")

        normalized.append(
            {
                "transaction_id": transaction_id,
                "account_id": account_id,
                "timestamp": _parse_timestamp(tx["timestamp"]),
                "amount": float(amount),
                "merchant_category": merchant_category,
                "country": country.strip().upper(),
                "card_present": card_present,
            }
        )

    normalized.sort(key=lambda t: (t["account_id"], t["timestamp"], t["transaction_id"]))

    flagged_ids: Set[str] = set()
    previous_by_account: Dict[str, Dict[str, Any]] = {}
    recent_by_account: Dict[str, deque] = defaultdict(deque)

    for tx in normalized:
        tx_id = tx["transaction_id"]
        account_id = tx["account_id"]
        ts = tx["timestamp"]
        amount = tx["amount"]
        country = tx["country"]

        if amount > high_value_threshold:
            flagged_ids.add(tx_id)

        prev = previous_by_account.get(account_id)
        if prev is not None:
            delta_seconds = (ts - prev["timestamp"]).total_seconds()
            if (
                delta_seconds >= 0
                and delta_seconds <= country_change_time_window_seconds
                and country != prev["country"]
            ):
                flagged_ids.add(tx_id)

        window = recent_by_account[account_id]
        cutoff_seconds = rapid_txn_window_seconds
        while window and (ts - window[0]).total_seconds() > cutoff_seconds:
            window.popleft()
        window.append(ts)
        if len(window) > rapid_txn_count_threshold:
            flagged_ids.add(tx_id)

        previous_by_account[account_id] = {"timestamp": ts, "country": country}

    return list(filter(lambda tx_id: tx_id in flagged_ids, (tx["transaction_id"] for tx in normalized)))


