class Countdown:
    """An iterator that counts down from a starting number to 1."""

    def __init__(self, start):
        self.current = start

    def __iter__(self):
        return self

    def __next__(self):
        if self.current < 1:
            raise StopIteration
        number = self.current
        self.current -= 1
        return number


def even_numbers(limit):
    """Yield even numbers from 0 up to limit inclusive."""
    for number in range(0, limit + 1, 2):
        yield number


def main():
    # Demonstrate the custom iterator
    print("Countdown iterator:")
    countdown = Countdown(5)
    for value in countdown:
        print(value)

    print("\nEven numbers generator:")
    for value in even_numbers(10):
        print(value)


