from typing import List


def generate_momentum_signals(
    prices: List[float], short_window: int, long_window: int
) -> List[str]:
    if short_window <= 0 or long_window <= 0:
        raise ValueError("Moving average windows must be positive integers.")

    n = len(prices)

    short_ma = [
        sum(prices[i - short_window + 1 : i + 1]) / short_window
        if i >= short_window - 1
        else None
        for i in range(n)
    ]

    long_ma = [
        sum(prices[i - long_window + 1 : i + 1]) / long_window
        if i >= long_window - 1
        else None
        for i in range(n)
    ]

    signals = ["HOLD"] * n

    for i in range(n):
        if i == 0 or short_ma[i] is None or long_ma[i] is None:
            signals[i] = "HOLD"
            continue

        prev_short = short_ma[i - 1]
        prev_long = long_ma[i - 1]

        if prev_short is None or prev_long is None:
            signals[i] = "HOLD"
        elif prev_short <= prev_long and short_ma[i] > long_ma[i]:
            signals[i] = "BUY"
        elif prev_short >= prev_long and short_ma[i] < long_ma[i]:
            signals[i] = "SELL"
        else:
            signals[i] = "HOLD"

    return signals

import json
from pathlib import Path

INPUT_FILE = Path('old_users.json')
OUTPUT_FILE = Path('new_users.json')
REQUIRED_FIELDS = {'id', 'full_name', 'email', 'signup_date'}


def split_name(full_name: str) -> tuple[str, str]:
    parts = full_name.strip().split()
    if not parts:
        return '', ''
    if len(parts) == 1:
        return parts[0], ''
    return parts[0], ' '.join(parts[1:])


def transform_user(user: dict) -> dict | None:
    # Skip records missing required fields
    if not REQUIRED_FIELDS.issubset(user):
        return None

    first_name, last_name = split_name(user['full_name'])

    return {
        'user_id': user['id'],
        'first_name': first_name,
        'last_name': last_name,
        'email': user['email'],
        'created_at': f"{user['signup_date']}T00:00:00Z",
        'status': 'active' if user.get('is_active', False) else 'inactive',
    }


def main() -> None:
    with INPUT_FILE.open('r', encoding='utf-8') as f:
        old_users = json.load(f)

    migrated_users = []
    skipped = 0

    for user in old_users:
        new_user = transform_user(user)
        if new_user is None:
            skipped += 1
        else:
            migrated_users.append(new_user)

    with OUTPUT_FILE.open('w', encoding='utf-8') as f:
        json.dump(migrated_users, f, indent=2)

    print(f'Migrated: {len(migrated_users)}')
    print(f'Skipped: {skipped}')


if __name__ == '__main__':
    main()

from typing import Callable, Dict, List

Request = Dict[str, str]
Response = Dict[str, object]
Middleware = Callable[[Request, Callable[[Request], Response]], Response]
Handler = Callable[[Request], Response]


def build_pipeline(middlewares: List[Middleware], handler: Handler) -> Handler:
    """Wrap the handler with middleware from last to first."""
    next_func = handler

    for middleware in reversed(middlewares):
        current_next = next_func

        def wrapped(request: Request, mw=middleware, nxt=current_next) -> Response:
            return mw(request, nxt)

        next_func = wrapped

    return next_func


def logging_middleware(request: Request, next_func: Callable[[Request], Response]) -> Response:
    print(f"[LOG] path={request.get('path', '')}")
    return next_func(request)


def auth_defaults_middleware(request: Request, next_func: Callable[[Request], Response]) -> Response:
    request = dict(request)  # avoid mutating the original request
    request.setdefault('user', 'guest')
    return next_func(request)


def admin_block_middleware(request: Request, next_func: Callable[[Request], Response]) -> Response:
    if request.get('path') == '/admin':
        return {'status': 403, 'message': 'forbidden'}
    return next_func(request)


def final_handler(request: Request) -> Response:
    return {
        'status': 200,
        'message': f"hello {request['user']}"
    }


pipeline = build_pipeline(
    [logging_middleware, auth_defaults_middleware, admin_block_middleware],
    final_handler,
)

# Demonstration
requests = [
    {'path': '/home'},
    {'path': '/admin', 'user': 'alice'},
]

for req in requests:
    response = pipeline(req)
    print(f"Request: {req} -> Response: {response}")

from itertools import tee


def pairwise(iterable):
    """Return overlapping pairs from the input iterable."""
    a, b = tee(iterable)
    next(b, None)
    return zip(a, b)


def describe_changes(temperatures):
    """Print temperature changes between consecutive days."""
    for day, (first, second) in enumerate(pairwise(temperatures), start=1):
        change = second - first

        if change > 0:
            message = f"Day {day} to Day {day + 1}: up by {change} degrees"
        elif change < 0:
            message = f"Day {day} to Day {day + 1}: down by {abs(change)} degrees"
        else:
            message = f"Day {day} to Day {day + 1}: no change"

        print(message)


def main():
    temperatures = [20, 22, 22, 19, 21, 18]
    print("Daily temperatures:", temperatures)
    print("Changes between days:")
    describe_changes(temperatures)


