    main()

from collections import deque
from itertools import islice


class PeekableIterator:
    """Wrap an iterable to allow peeking at the next item lazily."""

    _MISSING = object()

    def __init__(self, iterable):
        self._iterator = iter(iterable)
        self._buffer = self._MISSING

    def peek(self):
        """Return the next item without consuming it."""
        if self._buffer is self._MISSING:
            self._buffer = next(self._iterator)  # May raise StopIteration
        return self._buffer

    def __iter__(self):
        return self

    def __next__(self):
        if self._buffer is not self._MISSING:
            item = self._buffer
            self._buffer = self._MISSING
            return item
        return next(self._iterator)


def lazy_windowed_map(source, window_size, transform):
    """Lazily apply transform to each full fixed-size window from source."""
    if window_size <= 0:
        raise ValueError("window_size must be positive")

    iterator = iter(source)

    while True:
        window = list(islice(iterator, window_size))
        if len(window) < window_size:
            return
        yield transform(window)


def event_stream(limit):
    """Example lazy source of events."""
    for i in range(1, limit + 1):
        yield i


def main():
    # Demonstrate PeekableIterator laziness.
    stream = PeekableIterator(event_stream(7))
    first_peek = stream.peek()
    second_peek = stream.peek()  # Should be the same, not consumed.
    first_item = next(stream)    # Should match the peeked value.

    print("peek 1:", first_peek)
    print("peek 2:", second_peek)
    print("next after peek:", first_item)

    # Demonstrate lazy windowed processing on the remaining stream.
    rolling_sums = lazy_windowed_map(stream, 3, sum)
    print("window sums:", list(rolling_sums))  # Remaining items: 2..7 -> [2,3,4], [5,6,7]


