    main()

import requests

BASE_URL = 'https://jsonplaceholder.typicode.com'
TIMEOUT = 5


def get_json(url, params=None):
    """Fetch JSON data from a URL with basic error handling."""
    try:
        response = requests.get(url, params=params, timeout=TIMEOUT)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.Timeout:
        print(f'Timeout while requesting: {url}')
    except requests.exceptions.HTTPError as exc:
        print(f'HTTP error for {url}: {exc}')
    except requests.exceptions.RequestException as exc:
        print(f'Request failed for {url}: {exc}')
    return None


def fetch_posts(limit=5):
    """Fetch a limited number of posts."""
    return get_json(f'{BASE_URL}/posts', params={'_limit': limit}) or []


def fetch_user(user_id, cache):
    """Fetch user data, using a cache to avoid duplicate requests."""
    if user_id not in cache:
        cache[user_id] = get_json(f'{BASE_URL}/users/{user_id}')
    return cache[user_id]


def main():
    posts = fetch_posts(5)
    if not posts:
        print('No posts could be retrieved.')
        return

    user_cache = {}

    for post in posts:
        user = fetch_user(post['userId'], user_cache)
        author_name = user['name'] if user else 'Unknown author'
        print(f"{post['id']}: {post['title']} - by {author_name}")


if __name__ == '__main__':
    main()

class TextDocument:
    def __init__(self):
        self.text = ""

    def add_text(self, new_text):
        self.text += new_text

    def delete_last(self, count):
        removed = self.text[-count:] if count <= len(self.text) else self.text
        self.text = self.text[:-count] if count <= len(self.text) else ""
        return removed


class AddTextCommand:
    def __init__(self, document, text):
        self.document = document
        self.text = text

    def execute(self):
        self.document.add_text(self.text)

    def undo(self):
        self.document.delete_last(len(self.text))


class DeleteTextCommand:
    def __init__(self, document, count):
        self.document = document
        self.count = count
        self.deleted_text = ""

    def execute(self):
        self.deleted_text = self.document.delete_last(self.count)

    def undo(self):
        self.document.add_text(self.deleted_text)


class CommandManager:
    def __init__(self):
        self.history = []

    def run_command(self, command):
        command.execute()
        self.history.append(command)

    def undo_last(self):
        if self.history:
            command = self.history.pop()
            command.undo()
        else:
            print("Nothing to undo.")


# Demo
if __name__ == "__main__":
    doc = TextDocument()
    manager = CommandManager()

    cmd1 = AddTextCommand(doc, "Hello")
    manager.run_command(cmd1)
    print("After first add:", doc.text)

    cmd2 = AddTextCommand(doc, " World")
    manager.run_command(cmd2)
    print("After second add:", doc.text)

    cmd3 = DeleteTextCommand(doc, 3)
    manager.run_command(cmd3)
    print("After delete:", doc.text)

    manager.undo_last()
    print("After undo delete:", doc.text)

    manager.undo_last()
    print("After undo second add:", doc.text)
}

from __future__ import annotations

from dataclasses import dataclass, field, asdict
from decimal import Decimal, getcontext, ROUND_HALF_UP
from typing import Any, Dict, Iterable, List, Optional, Tuple, Union
from contextlib import AbstractContextManager
import json
import copy

getcontext().prec = 28

D = Decimal
ZERO = D("0")


def _to_decimal(value: Any, default: Decimal = ZERO) -> Decimal:
    if value is None:
        return default
    if isinstance(value, Decimal):
        return value
    try:
        return Decimal(str(value))
    except Exception:
        return default


def _q(value: Decimal, places: str = "0.00000001") -> Decimal:
    return value.quantize(Decimal(places), rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class MarketDataEvent:
    ts: int
    symbol: str
    bid: Decimal
    ask: Decimal
    bid_size: Decimal = ZERO
    ask_size: Decimal = ZERO
    currency: str = "USD"
    type: str = field(default="market_data", init=False)


@dataclass(frozen=True)
class OrderEvent:
    ts: int
    order_id: str
    symbol: str
    side: str  # BUY / SELL
    qty: Decimal
    price: Decimal
    fill_qty: Decimal
    fill_price: Decimal
    slippage_per_unit: Decimal = ZERO
    commission: Decimal = ZERO
    commission_currency: str = "USD"
    currency: str = "USD"
    type: str = field(default="order_fill", init=False)


@dataclass
class PositionState:
    symbol: str
    qty: Decimal = ZERO
    avg_cost: Decimal = ZERO
    realized_pnl_local: Decimal = ZERO
    realized_pnl_base: Decimal = ZERO
    unrealized_pnl_local: Decimal = ZERO
    unrealized_pnl_base: Decimal = ZERO
    market_price: Decimal = ZERO
    bid: Decimal = ZERO
    ask: Decimal = ZERO
    currency: str = "USD"
    exposure_local: Decimal = ZERO
    exposure_base: Decimal = ZERO
    last_ts: int = -1

    def snapshot(self) -> Dict[str, Any]:
        return {
            "symbol": self.symbol,
            "qty": str(_q(self.qty)),
            "avg_cost": str(_q(self.avg_cost)),
            "market_price": str(_q(self.market_price)),
            "bid": str(_q(self.bid)),
            "ask": str(_q(self.ask)),
            "currency": self.currency,
            "realized_pnl_local": str(_q(self.realized_pnl_local)),
            "realized_pnl_base": str(_q(self.realized_pnl_base)),
            "unrealized_pnl_local": str(_q(self.unrealized_pnl_local)),
            "unrealized_pnl_base": str(_q(self.unrealized_pnl_base)),
            "exposure_local": str(_q(self.exposure_local)),
            "exposure_base": str(_q(self.exposure_base)),
            "last_ts": self.last_ts,
        }


class TransactionLogger(AbstractContextManager):
    def __init__(self, sink: Optional[Any] = None):
        self.sink = sink
        self.records: List[Dict[str, Any]] = []
        self._closed = False

    def __enter__(self) -> "TransactionLogger":
        return self

    def log(self, record: Dict[str, Any]) -> None:
        if self._closed:
            raise RuntimeError("Logger is closed")
        serializable = copy.deepcopy(record)
        self.records.append(serializable)
        if self.sink is not None:
            self.sink.write(json.dumps(serializable, default=str) + "\n")

    def __exit__(self, exc_type, exc, tb) -> bool:
        self._closed = True
        if self.sink is not None and hasattr(self.sink, "flush"):
            self.sink.flush()
        return False


class EventStream(AbstractContextManager):
    def __init__(self, events: Iterable[Dict[str, Any]]):
        self._events = iter(events)

    def __enter__(self) -> "EventStream":
        return self

    def __iter__(self):
        return self

    def __next__(self) -> Dict[str, Any]:
        return next(self._events)

    def __exit__(self, exc_type, exc, tb) -> bool:
        return False


def _normalize_fx_rates(
    fx_rates: Optional[Dict[Union[str, Tuple[str, str]], Any]],
    base_currency: str,
) -> Dict[Tuple[str, str], Decimal]:
    normalized: Dict[Tuple[str, str], Decimal] = {(base_currency, base_currency): D("1")}
    if not fx_rates:
        return normalized
    for k, v in fx_rates.items():
        rate = _to_decimal(v, D("1"))
        if isinstance(k, tuple) and len(k) == 2:
            normalized[(str(k[0]), str(k[1]))] = rate
        elif isinstance(k, str):
            if "/" in k:
                a, b = k.split("/", 1)
                normalized[(a, b)] = rate
            else:
                normalized[(k, base_currency)] = rate
    return normalized


def _fx_convert(
    amount: Decimal,
    from_ccy: str,
    to_ccy: str,
    fx: Dict[Tuple[str, str], Decimal],
) -> Decimal:
    if from_ccy == to_ccy:
        return amount
    if (from_ccy, to_ccy) in fx:
        return amount * fx[(from_ccy, to_ccy)]
    if (to_ccy, from_ccy) in fx and fx[(to_ccy, from_ccy)] != ZERO:
        return amount / fx[(to_ccy, from_ccy)]
    raise KeyError(f"Missing FX rate for {from_ccy}->{to_ccy}")


def _parse_event(raw: Dict[str, Any]) -> Union[MarketDataEvent, OrderEvent]:
    if not isinstance(raw, dict):
        raise ValueError("Event must be a dict")
    etype = raw.get("type")
    if etype == "market_data":
        required = ("ts", "symbol", "bid", "ask")
        for k in required:
            if k not in raw:
                raise ValueError(f"Malformed market_data event missing {k}")
        bid = _to_decimal(raw["bid"])
        ask = _to_decimal(raw["ask"])
        if bid < ZERO or ask < ZERO or ask < bid:
            raise ValueError("Invalid bid/ask values")
        return MarketDataEvent(
            ts=int(raw["ts"]),
            symbol=str(raw["symbol"]),
            bid=bid,
            ask=ask,
            bid_size=_to_decimal(raw.get("bid_size", ZERO)),
            ask_size=_to_decimal(raw.get("ask_size", ZERO)),
            currency=str(raw.get("currency", "USD")),
        )
    if etype == "order_fill":
        required = ("ts", "order_id", "symbol", "side", "qty", "price", "fill_qty", "fill_price")
        for k in required:
            if k not in raw:
                raise ValueError(f"Malformed order_fill event missing {k}")
        side = str(raw["side"]).upper()
        if side not in {"BUY", "SELL"}:
            raise ValueError("Order side must be BUY or SELL")
        qty = _to_decimal(raw["qty"])
        fill_qty = _to_decimal(raw["fill_qty"])
        if qty <= ZERO or fill_qty <= ZERO or fill_qty > qty:
            raise ValueError("Invalid qty/fill_qty")
        return OrderEvent(
            ts=int(raw["ts"]),
            order_id=str(raw["order_id"]),
            symbol=str(raw["symbol"]),
            side=side,
            qty=qty,
            price=_to_decimal(raw["price"]),
            fill_qty=fill_qty,
            fill_price=_to_decimal(raw["fill_price"]),
            slippage_per_unit=_to_decimal(raw.get("slippage_per_unit", ZERO)),
            commission=_to_decimal(raw.get("commission", ZERO)),
            commission_currency=str(raw.get("commission_currency", raw.get("currency", "USD"))),
            currency=str(raw.get("currency", "USD")),
        )
    raise ValueError(f"Unsupported event type: {etype}")


def reconcile_trading_stream(
    events: Iterable[Dict[str, Any]],
    *,
    base_currency: str = "USD",
    initial_cash: Union[str, float, Decimal] = D("0"),
    fx_rates: Optional[Dict[Union[str, Tuple[str, str]], Any]] = None,
    strict_sequence: bool = True,
    logger_sink: Optional[Any] = None,
) -> Dict[str, Any]:
    fx = _normalize_fx_rates(fx_rates, base_currency)
    cash_base = _to_decimal(initial_cash)
    positions: Dict[str, PositionState] = {}
    order_filled_qty: Dict[str, Decimal] = {}
    anomalies: List[Dict[str, Any]] = []
    equity_curve: List[Tuple[int, Decimal]] = []
    last_global_ts: Optional[int] = None

    def get_position(symbol: str, currency: str) -> PositionState:
        if symbol not in positions:
            positions[symbol] = PositionState(symbol=symbol, currency=currency)
        return positions[symbol]

    def mark_to_market(ts: int) -> Decimal:
        total_unrealized_base = ZERO
        total_exposure_base = ZERO
        for pos in positions.values():
            if pos.bid > ZERO and pos.ask > ZERO:
                pos.market_price = (pos.bid + pos.ask) / D("2")
            if pos.qty > ZERO:
                px = pos.bid if pos.bid > ZERO else pos.market_price
            elif pos.qty < ZERO:
                px = pos.ask if pos.ask > ZERO else pos.market_price
            else:
                px = pos.market_price
            pos.exposure_local = pos.qty * px
            pos.exposure_base = _fx_convert(pos.exposure_local, pos.currency, base_currency, fx)
            pos.unrealized_pnl_local = pos.qty * (px - pos.avg_cost)
            pos.unrealized_pnl_base = _fx_convert(pos.unrealized_pnl_local, pos.currency, base_currency, fx)
            total_unrealized_base += pos.unrealized_pnl_base
            total_exposure_base += abs(pos.exposure_base)
        total_realized_base = sum((p.realized_pnl_base for p in positions.values()), ZERO)
        equity = cash_base + total_exposure_base * ZERO + total_realized_base + total_unrealized_base
        equity_curve.append((ts, equity))
        return equity

    def apply_fill(ev: OrderEvent) -> None:
        nonlocal cash_base
        pos = get_position(ev.symbol, ev.currency)
        signed_fill = ev.fill_qty if ev.side == "BUY" else -ev.fill_qty
        effective_price = ev.fill_price + ev.slippage_per_unit if ev.side == "BUY" else ev.fill_price - ev.slippage_per_unit
        commission_base = _fx_convert(ev.commission, ev.commission_currency, base_currency, fx)
        trade_cash_local = signed_fill * effective_price
        trade_cash_base = _fx_convert(trade_cash_local, ev.currency, base_currency, fx)

        prev_qty = pos.qty
        prev_avg = pos.avg_cost
        new_qty = prev_qty + signed_fill

        realized_local = ZERO

        if prev_qty == ZERO or (prev_qty > ZERO and signed_fill > ZERO) or (prev_qty < ZERO and signed_fill < ZERO):
            total_abs_qty = abs(prev_qty) + abs(signed_fill)
            if total_abs_qty != ZERO:
                pos.avg_cost = ((abs(prev_qty) * prev_avg) + (abs(signed_fill) * effective_price)) / total_abs_qty
            pos.qty = new_qty
        else:
            closing_qty = min(abs(prev_qty), abs(signed_fill))
            if prev_qty > ZERO and signed_fill < ZERO:
                realized_local = closing_qty * (effective_price - prev_avg)
            elif prev_qty < ZERO and signed_fill > ZERO:
                realized_local = closing_qty * (prev_avg - effective_price)

            pos.qty = new_qty
            if pos.qty == ZERO:
                pos.avg_cost = ZERO
            elif (prev_qty > ZERO > pos.qty) or (prev_qty < ZERO < pos.qty):
                pos.avg_cost = effective_price

        realized_base = _fx_convert(realized_local, ev.currency, base_currency, fx)
        pos.realized_pnl_local += realized_local
        pos.realized_pnl_base += realized_base - commission_base

        cash_base -= trade_cash_base
        cash_base -= commission_base
        pos.last_ts = ev.ts

    with EventStream(events) as stream, TransactionLogger(logger_sink) as txlog:
        for raw in stream:
            try:
                ev = _parse_event(raw)
            except Exception as exc:
                anomalies.append({"kind": "malformed_event", "event": raw, "error": str(exc)})
                txlog.log({"status": "rejected", "reason": "malformed_event", "event": raw})
                continue

            if last_global_ts is not None and ev.ts < last_global_ts:
                anomaly = {
                    "kind": "out_of_sequence",
                    "event": raw,
                    "last_ts": last_global_ts,
                    "current_ts": ev.ts,
                }
                anomalies.append(anomaly)
                txlog.log({"status": "rejected" if strict_sequence else "accepted_with_anomaly", **anomaly})
                if strict_sequence:
                    continue
            last_global_ts = ev.ts if last_global_ts is None else max(last_global_ts, ev.ts)

            if isinstance(ev, MarketDataEvent):
                pos = get_position(ev.symbol, ev.currency)
                if pos.currency != ev.currency:
                    anomalies.append(
                        {
                            "kind": "currency_mismatch",
                            "symbol": ev.symbol,
                            "position_currency": pos.currency,
                            "event_currency": ev.currency,
                            "ts": ev.ts,
                        }
                    )
                pos.bid = ev.bid
                pos.ask = ev.ask
                pos.market_price = (ev.bid + ev.ask) / D("2")
                pos.last_ts = ev.ts
                equity = mark_to_market(ev.ts)
                txlog.log(
                    {
                        "status": "applied",
                        "type": ev.type,
                        "ts": ev.ts,
                        "symbol": ev.symbol,
                        "equity_base": str(_q(equity)),
                    }
                )
                continue

            if isinstance(ev, OrderEvent):
                cumulative = order_filled_qty.get(ev.order_id, ZERO) + ev.fill_qty
                if cumulative > ev.qty:
                    anomaly = {
                        "kind": "overfill",
                        "order_id": ev.order_id,
                        "declared_qty": str(ev.qty),
                        "cumulative_fill_qty": str(cumulative),
                        "ts": ev.ts,
                    }
                    anomalies.append(anomaly)
                    txlog.log({"status": "rejected", **anomaly})
                    continue
                order_filled_qty[ev.order_id] = cumulative

                pos = get_position(ev.symbol, ev.currency)
                if pos.currency != ev.currency:
                    anomalies.append(
                        {
                            "kind": "currency_mismatch",
                            "symbol": ev.symbol,
                            "position_currency": pos.currency,
                            "event_currency": ev.currency,
                            "ts": ev.ts,
                        }
                    )

                try:
                    apply_fill(ev)
                    equity = mark_to_market(ev.ts)
                    txlog.log(
                        {
                            "status": "applied",
                            "type": ev.type,
                            "ts": ev.ts,
                            "order_id": ev.order_id,
                            "symbol": ev.symbol,
                            "side": ev.side,
                            "fill_qty": str(_q(ev.fill_qty)),
                            "fill_price": str(_q(ev.fill_price)),
                            "equity_base": str(_q(equity)),
                        }
                    )
                except Exception as exc:
                    anomalies.append(
                        {
                            "kind": "apply_fill_error",
                            "order_id": ev.order_id,
                            "event": raw,
                            "error": str(exc),
                        }
                    )
                    txlog.log(
                        {
                            "status": "rejected",
                            "reason": "apply_fill_error",
                            "order_id": ev.order_id,
                            "error": str(exc),
                        }
                    )

    final_equity = mark_to_market(last_global_ts if last_global_ts is not None else 0)

    peak = None
    max_drawdown = ZERO
    for _, eq in equity_curve:
        peak = eq if peak is None else max(peak, eq)
        dd = peak - eq
        if dd > max_drawdown:
            max_drawdown = dd

    per_symbol_exposure: Dict[str, Any] = {}
    total_realized_base = ZERO
    total_unrealized_base = ZERO
    gross_exposure_base = ZERO
    net_exposure_base = ZERO

    for symbol, pos in sorted(positions.items()):
        total_realized_base += pos.realized_pnl_base
        total_unrealized_base += pos.unrealized_pnl_base
        gross_exposure_base += abs(pos.exposure_base)
        net_exposure_base += pos.exposure_base
        per_symbol_exposure[symbol] = {
            "qty": str(_q(pos.qty)),
            "currency": pos.currency,
            "market_price": str(_q(pos.market_price)),
            "vwap_cost_basis": str(_q(pos.avg_cost)),
            "exposure_local": str(_q(pos.exposure_local)),
            "exposure_base": str(_q(pos.exposure_base)),
            "realized_pnl_base": str(_q(pos.realized_pnl_base)),
            "unrealized_pnl_base": str(_q(pos.unrealized_pnl_base)),
        }

    portfolio_state = {
        "base_currency": base_currency,
        "cash_base": str(_q(cash_base)),
        "equity_base": str(_q(final_equity)),
        "realized_pnl_base": str(_q(total_realized_base)),
        "unrealized_pnl_base": str(_q(total_unrealized_base)),
        "gross_exposure_base": str(_q(gross_exposure_base)),
        "net_exposure_base": str(_q(net_exposure_base)),
        "drawdown_base": str(_q(max_drawdown)),
        "positions": {symbol: pos.snapshot() for symbol, pos in sorted(positions.items())},
    }

    return {
        "portfolio_state": portfolio_state,
        "per_symbol_exposure": per_symbol_exposure,
        "drawdown": {
            "base_currency": base_currency,
            "max_drawdown_base": str(_q(max_drawdown)),
        },
        "reconciliation_anomalies": anomalies,
        "deterministic_replay": {
            "event_count": len(equity_curve),
            "strict_sequence": strict_sequence,
        },
    }

def chunk_list(items, batch_size):
    """Split a list into smaller batches."""
    for i in range(0, len(items), batch_size):
        yield items[i:i + batch_size]


def process_order(order):
    """Validate and process a single order."""
    if order['quantity'] <= 0 or order['unit_price'] <= 0:
        return None

    total_price = order['quantity'] * order['unit_price']
    return {
        'order_id': order['order_id'],
        'customer': order['customer'],
        'total_price': total_price
    }


def main():
    orders = [
        {'order_id': 1, 'customer': 'Alice', 'quantity': 2, 'unit_price': 15.0},
        {'order_id': 2, 'customer': 'Bob', 'quantity': 1, 'unit_price': 25.0},
        {'order_id': 3, 'customer': 'Charlie', 'quantity': 0, 'unit_price': 30.0},
        {'order_id': 4, 'customer': 'Diana', 'quantity': 3, 'unit_price': 12.5},
        {'order_id': 5, 'customer': 'Evan', 'quantity': 2, 'unit_price': -5.0},
        {'order_id': 6, 'customer': 'Fiona', 'quantity': 4, 'unit_price': 8.0},
        {'order_id': 7, 'customer': 'George', 'quantity': 1, 'unit_price': 50.0}
    ]

    batch_size = 3
    processed_orders = []
    total_revenue = 0

    for batch_number, batch in enumerate(chunk_list(orders, batch_size), start=1):
        print(f'Processing batch {batch_number}:')

        for order in batch:
            result = process_order(order)
            if result is None:
                print(f"  Skipping invalid order {order['order_id']}")
            else:
                processed_orders.append(result)
                total_revenue += result['total_price']
                print(f"  Processed order {result['order_id']} for {result['customer']}")

    print('\nValid processed orders:')
    for order in processed_orders:
        print(order)

    print(f'\nTotal revenue: {total_revenue}')


if __name__ == '__main__':
    main()
}

import time


class CircuitBreaker:
    def __init__(self, failure_threshold=2, recovery_timeout=5):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.consecutive_failures = 0
        self.opened_at = None

    def is_open(self):
        if self.opened_at is None:
            return False
        # Allow retry after timeout expires
        if time.time() - self.opened_at >= self.recovery_timeout:
            self.opened_at = None
            return False
        return True

    def record_success(self):
        self.consecutive_failures = 0
        self.opened_at = None

    def record_failure(self):
        self.consecutive_failures += 1
        if self.consecutive_failures >= self.failure_threshold:
            self.opened_at = time.time()


breaker = CircuitBreaker()


def call_with_resilience(operation, max_retries=3, failure_threshold=2, recovery_timeout=5):
    global breaker

    # Recreate breaker if settings differ from current instance
    if (
        breaker.failure_threshold != failure_threshold
        or breaker.recovery_timeout != recovery_timeout
    ):
        breaker = CircuitBreaker(failure_threshold, recovery_timeout)

    if breaker.is_open():
        raise RuntimeError("Circuit is open")

    last_error = None
    for attempt in range(max_retries + 1):
        try:
            result = operation()
            breaker.record_success()
            return result
        except Exception as exc:
            last_error = exc
            if attempt < max_retries:
                time.sleep(0.2)  # Small delay between retries

    breaker.record_failure()
    raise last_error


if __name__ == "__main__":
    state = {"count": 0}

    def flaky_operation():
        state["count"] += 1
        # Fail on most early calls, then recover later
        if state["count"] in {1, 2, 3, 4, 7}:
            raise ValueError(f"Temporary failure on call {state['count']}")
        return f"Success on call {state['count']}"

    for i in range(8):
        try:
            result = call_with_resilience(
                flaky_operation,
                max_retries=2,
                failure_threshold=2,
                recovery_timeout=2,
            )
            print(f"Attempt {i + 1}: {result}")
        except Exception as e:
            print(f"Attempt {i + 1}: {e}")
        time.sleep(0.5)
}

def find_nested_paths(data, target):
    """
    Recursively find all paths to values equal to target inside nested
    dict/list/tuple/set structures.

    Path rules:
    - dict key -> append the key
    - list/tuple index -> append the integer index
    - set element -> append {"set_index": i} using deterministic sorted order

    Cycles are handled by tracking active container objects by id.
    """
    results = []

    def is_container(value):
        return isinstance(value, (dict, list, tuple, set))

    def walk(current, path, active_ids):
        # Record match for the current node itself.
        if current == target:
            results.append(path.copy())

        if not is_container(current):
            return

        obj_id = id(current)
        if obj_id in active_ids:
            return  # Prevent infinite recursion on cyclic references.

        active_ids.add(obj_id)
        try:
            if isinstance(current, dict):
                for key, value in current.items():
                    path.append(key)
                    walk(value, path, active_ids)
                    path.pop()

            elif isinstance(current, (list, tuple)):
                for index, value in enumerate(current):
                    path.append(index)
                    walk(value, path, active_ids)
                    path.pop()

            elif isinstance(current, set):
                # Deterministic order so output is stable.
                ordered = sorted(current, key=lambda x: repr(x))
                for index, value in enumerate(ordered):
                    path.append({"set_index": index})
                    walk(value, path, active_ids)
                    path.pop()
        finally:
            active_ids.remove(obj_id)

    walk(data, [], set())
    return results


# Example usage:
if __name__ == "__main__":
    a = {"x": [1, {"y": 2}, 2], "z": ({3, 2},)}
    a["self"] = a  # create a cycle
    print(find_nested_paths(a, 2))
    # Possible output:
    # [['x', 1, 'y'], ['x', 2], ['z', 0, {'set_index': 0}]]

from google.protobuf.message import DecodeError


def normalize_event_batch(event_batch_cls, payload: bytes) -> bytes:
    """
    Parse, validate, deduplicate, sort, and re-serialize an EventBatch message.

    Expected EventBatch schema shape:
      message Event {
        string id = 1;
        int64 timestamp = 2;
      }
      message EventBatch {
        repeated Event events = 1;
      }
    """
    batch = event_batch_cls()

    try:
        batch.ParseFromString(payload)
    except DecodeError as exc:
        raise ValueError("Failed to parse EventBatch payload") from exc

    seen_ids = set()
    unique_events = []

    for event in batch.events:
        # Validate required business rules.
        if not getattr(event, "id", ""):
            raise ValueError("Event id must be non-empty")
        if getattr(event, "timestamp", 0) <= 0:
            raise ValueError(f"Event '{event.id}' must have a positive timestamp")

        # Keep only the first event for each unique id.
        if event.id not in seen_ids:
            seen_ids.add(event.id)
            unique_events.append(event)

    # Sort by timestamp ascending.
    unique_events.sort(key=lambda e: e.timestamp)

    # Build a fresh message to avoid mutating the parsed input object.
    normalized = event_batch_cls()
    for event in unique_events:
        normalized.events.add().CopyFrom(event)

    return normalized.SerializeToString()

