def parse_signup_date(value):
    """Convert an ISO-like datetime string to YYYY-MM-DD."""
    if not value:
        return None
    try:
        return datetime.fromisoformat(value.replace('Z', '+00:00')).date().isoformat()
    except ValueError:
        return None


def split_name(full_name):
    """Split a full name into first and last name."""
    parts = full_name.strip().split()
    if not parts:
        return "", ""
    if len(parts) == 1:
        return parts[0], ""
    return parts[0], " ".join(parts[1:])


def migrate_users(old_records):
    migrated = []

    for record in old_records:
        # Skip invalid records missing required fields
        if not all(k in record and record[k] for k in ("user_id", "full_name", "email")):
            continue

        first_name, last_name = split_name(record["full_name"])
        new_record = {
            "id": int(record["user_id"]),
            "first_name": first_name,
            "last_name": last_name,
            "email": record["email"].strip().lower(),
            "signup_date": parse_signup_date(record.get("created_at")),
            "status": "active" if record.get("is_active") else "inactive",
        }
        migrated.append(new_record)

    return migrated


