from __future__ import annotations

from abc import ABC, abstractmethod


class PaymentError(Exception):
    """Raised when a payment cannot be processed."""


class PaymentStrategy(ABC):
    @abstractmethod
    def pay(self, amount: float) -> str:
        """Process a payment and return a summary."""
        raise NotImplementedError

    @staticmethod
    def _validate_amount(amount: float) -> None:
        if amount <= 0:
            raise PaymentError(f"Invalid payment amount: {amount}")


class CreditCardPayment(PaymentStrategy):
    def __init__(self, card_holder: str, last4: str) -> None:
        self.card_holder = card_holder
        self.last4 = last4

    def pay(self, amount: float) -> str:
        self._validate_amount(amount)
        fee = amount * 0.02
        total = amount + fee
        return (
            f"CreditCard payment approved for {self.card_holder} "
            f"(****{self.last4}): amount=${amount:.2f}, fee=${fee:.2f}, total=${total:.2f}"
        )


class PayPalPayment(PaymentStrategy):
    def __init__(self, email: str) -> None:
        self.email = email

    def pay(self, amount: float) -> str:
        self._validate_amount(amount)
        fee = 0.30 + amount * 0.03
        total = amount + fee
        return (
            f"PayPal payment sent from {self.email}: "
            f"amount=${amount:.2f}, fee=${fee:.2f}, total=${total:.2f}"
        )


class CryptoPayment(PaymentStrategy):
    def __init__(self, wallet_id: str, network: str) -> None:
        self.wallet_id = wallet_id
        self.network = network

    def pay(self, amount: float) -> str:
        self._validate_amount(amount)
        network_fee = 1.50
        total = amount + network_fee
        return (
            f"Crypto transfer on {self.network} to wallet {self.wallet_id}: "
            f"amount=${amount:.2f}, network_fee=${network_fee:.2f}, total=${total:.2f}"
        )


class PaymentProcessor:
    def __init__(self, strategy: PaymentStrategy) -> None:
        self.strategy = strategy

    def set_strategy(self, strategy: PaymentStrategy) -> None:
        self.strategy = strategy

    def process(self, amount: float) -> str:
        return self.strategy.pay(amount)


if __name__ == "__main__":
    processor = PaymentProcessor(CreditCardPayment("Alice Smith", "4242"))
    print(processor.process(120.00))

    processor.set_strategy(PayPalPayment("alice@example.com"))
    print(processor.process(75.50))

    processor.set_strategy(CryptoPayment("0xA1B2C3D4", "Ethereum"))
    try:
        print(processor.process(-10))
    except PaymentError as exc:
        print(f"Payment failed: {exc}")

from __future__ import annotations

from abc import ABC, abstractmethod
from collections import defaultdict
from typing import Dict, List, Set


class EventHandler(ABC):
    @abstractmethod
    def handle(self, event_type: str, **data) -> None:
        """Process an event and its payload."""


class EventBus:
    def __init__(self) -> None:
        self._subscribers: Dict[str, Set[EventHandler]] = defaultdict(set)

    def subscribe(self, event_type: str, handler: EventHandler) -> None:
        self._subscribers[event_type].add(handler)  # set prevents duplicates

    def unsubscribe(self, event_type: str, handler: EventHandler) -> None:
        self._subscribers[event_type].discard(handler)
        if not self._subscribers[event_type]:
            del self._subscribers[event_type]

    def publish(self, event_type: str, **data) -> None:
        for handler in list(self._subscribers.get(event_type, ())):
            handler.handle(event_type, **data)


class LoggingHandler(EventHandler):
    def __init__(self) -> None:
        self.logs: List[str] = []

    def handle(self, event_type: str, **data) -> None:
        payload = ", ".join(f"{k}={v}" for k, v in sorted(data.items()))
        self.logs.append(f"[{event_type}] {payload}")


class ThresholdAlertHandler(EventHandler):
    def __init__(self, key: str, threshold: float) -> None:
        self.key = key
        self.threshold = threshold
        self.alerts: List[str] = []

    def handle(self, event_type: str, **data) -> None:
        value = data.get(self.key)
        if isinstance(value, (int, float)) and value > self.threshold:
            self.alerts.append(
                f"ALERT: {event_type} {self.key}={value} exceeded {self.threshold}"
            )


if __name__ == "__main__":
    bus = EventBus()
    logger = LoggingHandler()
    temp_alert = ThresholdAlertHandler(key="temperature", threshold=75)

    bus.subscribe("sensor_update", logger)
    bus.subscribe("sensor_update", temp_alert)
    bus.subscribe("sensor_update", logger)  # duplicate ignored by set

    bus.publish("sensor_update", device="A1", temperature=72)
    bus.publish("sensor_update", device="A1", temperature=81)
    bus.publish("sensor_update", device="B4", temperature=90)

    print("Logs:")
    for entry in logger.logs:
        print("-", entry)

    print("\nAlerts:")
    for alert in temp_alert.alerts:
        print("-", alert)

class DisjointSet:
    def __init__(self, n):
        # Each node starts as its own parent
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        # Path compression
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)

        if root_a == root_b:
            return

        # Union by rank
        if self.rank[root_a] < self.rank[root_b]:
            self.parent[root_a] = root_b
        elif self.rank[root_a] > self.rank[root_b]:
            self.parent[root_b] = root_a
        else:
            self.parent[root_b] = root_a
            self.rank[root_a] += 1

    def connected(self, a, b):
        return self.find(a) == self.find(b)


def process_operations(n, operations):
    ds = DisjointSet(n)
    results = []

    for op in operations:
        action, a, b = op
        if action == 'union':
            ds.union(a, b)
        elif action == 'connected':
            results.append(ds.connected(a, b))

    return results


# Example usage
if __name__ == '__main__':
    n = 5
    operations = [
        ['union', 0, 1],
        ['union', 1, 2],
        ['connected', 0, 2],
        ['connected', 0, 3],
        ['union', 3, 4],
        ['union', 2, 4],
        ['connected', 0, 4]
    ]

    print(process_operations(n, operations))  # [True, False, True]

import json
import csv
from collections import defaultdict
from datetime import datetime

INPUT_FILE = 'events.jsonl'
OUTPUT_FILE = 'daily_user_metrics.csv'


def parse_timestamp(value):
    """Parse ISO-like timestamps safely, supporting trailing Z."""
    if not value or not isinstance(value, str):
        return None
    try:
        return datetime.fromisoformat(value.replace('Z', '+00:00'))
    except ValueError:
        return None


def to_float(value):
    """Convert values to float, defaulting invalid inputs to 0.0."""
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


aggregates = defaultdict(lambda: {
    'total_events': 0,
    'total_amount': 0.0,
    'purchase_events': 0,
    'sources': set(),
})

with open(INPUT_FILE, 'r', encoding='utf-8') as infile:
    for line in infile:
        line = line.strip()
        if not line:
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            continue  # Skip malformed JSON lines

        user_id = record.get('user_id')
        ts = parse_timestamp(record.get('timestamp'))
        if not user_id or ts is None:
            continue  # Drop records with missing user_id or invalid timestamp

        event_type = str(record.get('event_type', '')).lower()
        amount = to_float(record.get('amount'))
        event_date = ts.date().isoformat()
        source = record.get('metadata', {}).get('source')

        key = (event_date, str(user_id))
        row = aggregates[key]
        row['total_events'] += 1
        row['total_amount'] += amount
        row['purchase_events'] += 1 if event_type == 'purchase' else 0
        if source:
            row['sources'].add(str(source))

with open(OUTPUT_FILE, 'w', newline='', encoding='utf-8') as outfile:
    writer = csv.writer(outfile)
    writer.writerow([
        'event_date', 'user_id', 'total_events',
        'total_amount', 'purchase_events', 'unique_sources'
    ])

    for (event_date, user_id) in sorted(aggregates):
        row = aggregates[(event_date, user_id)]
        writer.writerow([
            event_date,
            user_id,
            row['total_events'],
            f"{row['total_amount']:.2f}",
            row['purchase_events'],
            len(row['sources']),
        ])

def validate_user_records(records):
    """Validate and normalize a list of user records against a simple schema."""
    results = {"valid": [], "errors": []}

    for index, record in enumerate(records):
        record_errors = []

        if not isinstance(record, dict):
            results["errors"].append({
                "index": index,
                "errors": ["Record must be a dictionary"]
            })
            continue

        # Validate required fields
        required_fields = ["id", "name", "email", "age"]
        for field in required_fields:
            if field not in record:
                record_errors.append(f"Missing required field: {field}")

        if record_errors:
            results["errors"].append({"index": index, "errors": record_errors})
            continue

        # Validate id
        if not isinstance(record["id"], int) or isinstance(record["id"], bool) or record["id"] <= 0:
            record_errors.append("id must be a positive integer")

        # Validate and normalize name
        name = record["name"]
        if not isinstance(name, str) or not name.strip():
            record_errors.append("name must be a non-empty string")
        else:
            name = name.strip()

        # Validate and normalize email
        email = record["email"]
        if not isinstance(email, str):
            record_errors.append("email must be a string")
        else:
            email = email.strip().lower()
            if email.count("@") != 1:
                record_errors.append("email must contain exactly one @")
            else:
                local, domain = email.split("@")
                if not local or "." not in domain:
                    record_errors.append("email must have a valid domain")

        # Validate age
        age = record["age"]
        if not isinstance(age, int) or isinstance(age, bool) or not (18 <= age <= 120):
            record_errors.append("age must be an integer between 18 and 120")

        # Validate optional tags
        tags = record.get("tags", [])
        if "tags" in record:
            if not isinstance(tags, list):
                record_errors.append("tags must be a list of non-empty strings")
            else:
                for i, tag in enumerate(tags):
                    if not isinstance(tag, str) or not tag.strip():
                        record_errors.append(f"tags[{i}] must be a non-empty string")

        if record_errors:
            results["errors"].append({
                "index": index,
                "errors": record_errors
            })
        else:
            results["valid"].append({
                "id": record["id"],
                "name": name,
                "email": email,
                "age": age,
                "tags": [tag.strip() for tag in tags]
            })

    return results


# Example usage
if __name__ == "__main__":
    sample_records = [
        {
            "id": 1,
            "name": " Alice ",
            "email": " Alice@example.com ",
