from __future__ import annotations

from abc import ABC, abstractmethod
import json


class ReportBuilder(ABC):
    """Abstract builder for assembling reports step by step."""

    @abstractmethod
    def add_title(self, title: str) -> None:
        pass

    @abstractmethod
    def add_section(self, heading: str, content: str) -> None:
        pass

    @abstractmethod
    def build(self) -> str:
        pass


class HtmlReportBuilder(ReportBuilder):
    def __init__(self) -> None:
        self.parts = []

    def add_title(self, title: str) -> None:
        self.parts.append(f"<h1>{title}</h1>")

    def add_section(self, heading: str, content: str) -> None:
        self.parts.append(f"<h2>{heading}</h2><p>{content}</p>")

    def build(self) -> str:
        return "<html><body>" + "".join(self.parts) + "</body></html>"


class JsonReportBuilder(ReportBuilder):
    def __init__(self) -> None:
        self.report = {"title": "", "sections": []}

    def add_title(self, title: str) -> None:
        self.report["title"] = title

    def add_section(self, heading: str, content: str) -> None:
        self.report["sections"].append({"heading": heading, "content": content})

    def build(self) -> str:
        return json.dumps(self.report, indent=2)


class ReportFactory:
    """Factory that selects the appropriate builder."""

    @staticmethod
    def create_builder(report_format: str) -> ReportBuilder:
        fmt = report_format.lower()
        if fmt == "html":
            return HtmlReportBuilder()
        if fmt == "json":
            return JsonReportBuilder()
        raise ValueError(f"Unsupported report format: {report_format}")


def build_sales_report(report_format: str, title: str, sections: list[dict]) -> str:
    builder = ReportFactory.create_builder(report_format)
    builder.add_title(title)

    for section in sections:
        builder.add_section(section["heading"], section["content"])

    return builder.build()


