import weakref
from collections import defaultdict


class EventBus:
    def __init__(self):
        self._subscribers = defaultdict(list)

    def subscribe(self, event_name, handler):
        # Store a weak reference to the bound method's instance and method name.
        self._subscribers[event_name].append((weakref.ref(handler.__self__), handler.__name__))

    def unsubscribe(self, event_name, handler):
        target = (handler.__self__, handler.__name__)
        self._subscribers[event_name] = [
            (obj_ref, method_name)
            for obj_ref, method_name in self._subscribers[event_name]
            if (obj_ref(), method_name) != target
        ]

    def emit(self, event_name, **data):
        alive = []
        for obj_ref, method_name in self._subscribers[event_name]:
            obj = obj_ref()
            if obj is None:
                continue  # Drop dead subscribers automatically.
            getattr(obj, method_name)(event_name, **data)
            alive.append((obj_ref, method_name))
        self._subscribers[event_name] = alive


class Plugin:
    def __init__(self, bus):
        self.bus = bus


class LoggerPlugin(Plugin):
    def __init__(self, bus):
        super().__init__(bus)
        self.history = []

    def handle(self, event_name, **data):
        self.history.append((event_name, data))


class ThresholdPlugin(Plugin):
    def __init__(self, bus, watch_event, threshold):
        super().__init__(bus)
        self.watch_event = watch_event
        self.threshold = threshold
        self.count = 0

    def handle(self, event_name, **data):
        if event_name == self.watch_event:
            self.count += 1
            if self.count >= self.threshold:
                self.bus.emit("alert", source=event_name, count=self.count)
                self.count = 0


if __name__ == "__main__":
    bus = EventBus()
    logger = LoggerPlugin(bus)
    threshold = ThresholdPlugin(bus, watch_event="task_done", threshold=3)

    bus.subscribe("task_done", logger.handle)
    bus.subscribe("task_done", threshold.handle)
    bus.subscribe("alert", logger.handle)

    for i in range(5):
        bus.emit("task_done", task_id=i)

    bus.unsubscribe("task_done", logger.handle)
    bus.emit("task_done", task_id=99)

    for event in logger.history:
        print(event)

class LogParser:
    """Iterates over log lines and yields parsed ERROR records."""

    def __init__(self, lines):
        self._lines = iter(lines)

    def __iter__(self):
        return self

    def __next__(self):
        while True:
            line = next(self._lines)  # Raises StopIteration when exhausted
            parts = line.strip().split("|", 2)

            # Skip malformed lines
            if len(parts) != 3:
                continue

            level, timestamp, message = parts
            if level != "ERROR":
                continue

            # Basic timestamp validation for YYYY-MM-DD...
            if len(timestamp) < 10 or timestamp[4] != "-" or timestamp[7] != "-":
                continue

            return {
                "level": level,
                "timestamp": timestamp,
                "message": message,
            }


def summarize_errors(records):
    """Yield (date, count) pairs in first-seen date order."""
    counts = {}
    order = []

    for record in records:
        date = record["timestamp"][:10]
        if date not in counts:
            counts[date] = 0
            order.append(date)
        counts[date] += 1

    for date in order:
        yield (date, counts[date])


