def read_numbers(lines):
    """Yield valid integers from a sequence of text lines lazily."""
    for line in lines:
        text = line.strip()
        if not text:
            continue  # Skip blank lines
        try:
            yield int(text)
        except ValueError:
            continue  # Skip invalid integers


def square_numbers(numbers):
    """Yield squared numbers lazily."""
    for number in numbers:
        yield number * number


