from __future__ import annotations

import hashlib
from pathlib import Path


def _sha256_file(path: Path, chunk_size: int = 65536) -> str:
    """Compute SHA-256 for a file without loading it all into memory."""
    h = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            h.update(chunk)
    return h.hexdigest()


def verify_manifest(base_dir: str, manifest_text: str) -> dict:
    """Validate files listed in a SHA-256 manifest.

    Manifest format per line:
        <64-hex-digest><two spaces><relative_path>
    """
    base = Path(base_dir).resolve()
    results = {"ok": [], "mismatch": [], "missing": []}

    for line_no, raw_line in enumerate(manifest_text.splitlines(), start=1):
        line = raw_line.strip('\n')
        if not line.strip() or line.lstrip().startswith('#'):
            continue

        # Require exactly the standard separator: two spaces.
        if '  ' not in line:
            raise ValueError(f"Malformed manifest line {line_no}: missing separator")

        digest, rel_path = line.split('  ', 1)
        if len(digest) != 64 or any(c not in '0123456789abcdefABCDEF' for c in digest):
            raise ValueError(f"Malformed manifest line {line_no}: invalid SHA-256 digest")
        if not rel_path or rel_path.strip() != rel_path:
            raise ValueError(f"Malformed manifest line {line_no}: invalid path field")

        target = (base / rel_path).resolve()

        # Prevent directory traversal outside the base directory.
        try:
            target.relative_to(base)
        except ValueError:
            raise ValueError(f"Manifest line {line_no}: path escapes base_dir")

        if not target.exists() or not target.is_file():
            results['missing'].append(rel_path)
            continue

        actual = _sha256_file(target)
        if actual.lower() == digest.lower():
            results['ok'].append(rel_path)
        else:
            results['mismatch'].append(rel_path)

    for key in results:
        results[key].sort()
    return results

from collections import Counter
import heapq
import ipaddress
import sys


def is_valid_ipv4(value: str) -> bool:
    """Return True if value is a valid IPv4 address."""
    try:
        return isinstance(ipaddress.ip_address(value), ipaddress.IPv4Address)
    except ValueError:
        return False



def stream_top_ips(path: str, k: int = 5):
    """
    Stream a log file line by line, count valid IPv4 addresses,
    and return the top-k most frequent as (ip, count) tuples.
    """
    if k <= 0:
        return []

    counts = Counter()

    # Read incrementally to avoid loading the whole file into memory.
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) < 4:
                continue

            ip = parts[-1]
            if is_valid_ipv4(ip):
                counts[ip] += 1

    # Use a heap-based top-k selection to avoid sorting all items when unnecessary.
    top = heapq.nsmallest(
        k,
        counts.items(),
        key=lambda item: (-item[1], item[0])
    )
    return top



def main():
    if len(sys.argv) < 2:
        print("Usage: python script.py <log_file> [k]")
        sys.exit(1)

    path = sys.argv[1]
    k = int(sys.argv[2]) if len(sys.argv) > 2 else 5

    for ip, count in stream_top_ips(path, k):
        print(f"{ip}\t{count}")


if __name__ == "__main__":
    main()
}

import os
import zipfile


def create_txt_zip(folder_path, zip_name):
    # Check that the folder exists
    if not os.path.isdir(folder_path):
        print("Error: folder does not exist.")
        return

    # Ensure the output file has a .zip extension
    if not zip_name.endswith('.zip'):
        zip_name += '.zip'

    # Find .txt files in the folder only
    txt_files = []
    for name in os.listdir(folder_path):
        full_path = os.path.join(folder_path, name)
        if os.path.isfile(full_path) and name.lower().endswith('.txt'):
            txt_files.append(full_path)

    if not txt_files:
        print("No .txt files found. Archive was not created.")
        return

    # Create the ZIP archive
    zip_path = os.path.join(folder_path, zip_name)
    with zipfile.ZipFile(zip_path, 'w', compression=zipfile.ZIP_DEFLATED) as zip_file:
        for file_path in txt_files:
            # Store only the filename inside the archive
            zip_file.write(file_path, arcname=os.path.basename(file_path))

    print(f"Created '{zip_path}' with {len(txt_files)} file(s).")


def main():
    folder = input("Enter the folder path: ").strip()
    zip_name = input("Enter the ZIP file name: ").strip()
    create_txt_zip(folder, zip_name)


if __name__ == '__main__':
    main()
}

from typing import Callable, Dict, Any, List

Request = Dict[str, Any]
Response = Dict[str, Any]
Middleware = Callable[[Request, Callable[[Request], Response]], Response]


class Pipeline:
    def __init__(self) -> None:
        self._middlewares: List[Middleware] = []

    def use(self, middleware: Middleware) -> None:
        self._middlewares.append(middleware)

    def execute(self, request: Request, final_handler: Callable[[Request], Response]) -> Response:
        def build_chain(index: int) -> Callable[[Request], Response]:
            if index == len(self._middlewares):
                return final_handler

            def step(req: Request) -> Response:
                current = self._middlewares[index]
                return current(req, build_chain(index + 1))

            return step

        return build_chain(0)(request)


logs: List[str] = []


def logging_middleware(request: Request, next_fn: Callable[[Request], Response]) -> Response:
    logs.append(f"Path accessed: {request.get('path', '/')}")
    return next_fn(request)


def auth_middleware(request: Request, next_fn: Callable[[Request], Response]) -> Response:
    headers = request.get("headers", {})
    token = headers.get("Authorization")

    if token == "Bearer admin-token":
        request["user"] = "admin"
    elif token == "Bearer user-token":
        request["user"] = "user"
    else:
        request["user"] = "guest"

    return next_fn(request)


def admin_guard_middleware(request: Request, next_fn: Callable[[Request], Response]) -> Response:
    if request.get("path") == "/admin" and request.get("user") != "admin":
        return {"status": 403, "data": "Forbidden"}
    return next_fn(request)


def final_handler(request: Request) -> Response:
    return {
        "status": 200,
        "data": {
            "message": f"Hello, {request.get('user', 'guest')}!",
            "path": request.get("path", "/")
        }
    }


if __name__ == "__main__":
    pipeline = Pipeline()
    pipeline.use(logging_middleware)
    pipeline.use(auth_middleware)
    pipeline.use(admin_guard_middleware)

    requests = [
        {"path": "/home", "headers": {}},
        {"path": "/admin", "headers": {"Authorization": "Bearer user-token"}},
        {"path": "/admin", "headers": {"Authorization": "Bearer admin-token"}},
    ]

    for req in requests:
        response = pipeline.execute(req.copy(), final_handler)
        print(f"Request: {req}")
        print(f"Response: {response}\n")

    print("Logs:")
    for entry in logs:
        print(entry)

def analyze_orders(orders):
    """Analyze order data using list comprehensions and list operations."""

    # Keep only non-cancelled orders for most calculations
    active_orders = [order for order in orders if order.get('status') != 'cancelled']

    # Precompute totals and quantities to avoid repeating logic
    order_summaries = [
        {
            'id': order['id'],
            'customer': order['customer'],
            'total': sum(item['qty'] * item['price'] for item in order['items']),
            'quantity': sum(item['qty'] for item in order['items'])
        }
        for order in active_orders
    ]

    # Orders with total value greater than 100
    high_value_ids = sorted([summary['id'] for summary in order_summaries if summary['total'] > 100])

    # Distinct item names across all active orders
    unique_items = sorted({
        item['name']
        for order in active_orders
        for item in order['items']
    })

    # Aggregate totals by customer
    customers = {summary['customer'] for summary in order_summaries}
    customer_totals = {
        customer: round(
            sum(summary['total'] for summary in order_summaries if summary['customer'] == customer),
            2
        )
        for customer in customers
    }

    # Orders with bulk quantity of at least 10 items
    bulk_discount_ids = sorted([summary['id'] for summary in order_summaries if summary['quantity'] >= 10])

    return {
        'high_value_ids': high_value_ids,
        'unique_items': unique_items,
        'customer_totals': customer_totals,
        'bulk_discount_ids': bulk_discount_ids,
    }


