import socket
import threading
from datetime import datetime

HOST = '127.0.0.1'
PORT = 9000


def handle_client(conn, addr):
    print(f'Connected: {addr}')
    try:
        with conn:
            buffer = b''
            while True:
                data = conn.recv(1024)
                if not data:
                    break
                buffer += data

                while b'\n' in buffer:
                    line, buffer = buffer.split(b'\n', 1)
                    message = line.decode('utf-8', errors='ignore').strip()

                    if not message:
                        response = 'ERROR\n'
                    elif message == 'TIME':
                        response = datetime.now().isoformat() + '\n'
                    elif message.startswith('ECHO '):
                        response = message[5:] + '\n'
                    elif message.startswith('REVERSE '):
                        response = message[8:][::-1] + '\n'
                    elif message == 'QUIT':
                        conn.sendall(b'BYE\n')
                        return
                    else:
                        response = 'ERROR\n'

                    conn.sendall(response.encode('utf-8'))
    except Exception as e:
        print(f'Error with {addr}: {e}')
    finally:
        print(f'Disconnected: {addr}')


def main():
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as server:
        server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server.bind((HOST, PORT))
        server.listen()
        print(f'Server listening on {HOST}:{PORT}')

        while True:
            conn, addr = server.accept()
            thread = threading.Thread(target=handle_client, args=(conn, addr), daemon=True)
            thread.start()


if __name__ == '__main__':
    main()
}

from collections.abc import Mapping


class RecordValidationError(Exception):
    """Raised when a record fails validation."""

    def __init__(self, index, message, *, cause=None):
        self.index = index
        self.cause = cause
        super().__init__(f"record {index}: {message}")


def _normalize_record(record, required_fields):
    """Validate a single record and return only the required fields."""
    if not isinstance(record, Mapping):
        raise TypeError("expected a mapping/dictionary-like object")

    normalized = {}
    for field in required_fields:
        try:
            value = record[field]
        except KeyError as exc:
            raise ValueError(f"missing required field '{field}'") from exc

        if value is None:
            raise ValueError(f"field '{field}' cannot be None")
        if isinstance(value, str) and not value.strip():
            raise ValueError(f"field '{field}' cannot be blank")

        normalized[field] = value.strip() if isinstance(value, str) else value

    return normalized


def fetch_required_fields(records, required_fields):
    """Return validated records or raise on the first invalid record."""
    result = []
    for index, record in enumerate(records):
        try:
            result.append(_normalize_record(record, required_fields))
        except Exception as exc:
            raise RecordValidationError(index, str(exc), cause=exc) from exc
    return result


def process_records(records, required_fields):
    """Process all records, collecting valid results and readable errors."""
    valid_records = []
    errors = []

    for index, record in enumerate(records):
        try:
            valid_records.append(_normalize_record(record, required_fields))
        except Exception as exc:
            wrapped = RecordValidationError(index, str(exc), cause=exc)
            cause_name = type(exc).__name__
            errors.append(f"{wrapped} ({cause_name})")

    return valid_records, errors


if __name__ == "__main__":
    sample_records = [
        {"id": 1, "name": " Alice ", "email": "alice@example.com"},
        {"id": 2, "name": "", "email": "bob@example.com"},
        ["not", "a", "mapping"],
        {"id": 4, "name": "Dana", "email": None},
        {"id": 5, "name": "Eve", "email": "eve@example.com"},
    ]

    required = ["id", "name", "email"]
    valid, errs = process_records(sample_records, required)
    print("VALID:", valid)
    print("ERRORS:", errs)

import heapq


def main():
    n = int(input().strip())
    heap = []

    for _ in range(n):
        parts = input().strip().split(maxsplit=2)
        command = parts[0]

        if command == 'ADD':
            # ADD priority task_name
            priority = int(parts[1])
            task_name = parts[2]
            heapq.heappush(heap, (priority, task_name))

        elif command == 'PEEK':
            # Show the highest-priority task without removing it
            if heap:
                priority, task_name = heap[0]
                print(task_name)
            else:
                print('No tasks')

        elif command == 'NEXT':
            # Remove and show the highest-priority task
            if heap:
                priority, task_name = heapq.heappop(heap)
                print(task_name)
            else:
                print('No tasks')


if __name__ == '__main__':
    main()

class PositiveInt:
    """Descriptor that stores only positive integers."""

    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, int) or value <= 0:
            raise ValueError(f"{self.private_name[1:]} must be a positive integer")
        setattr(instance, self.private_name, value)


class ServiceConfig:
    timeout = PositiveInt()
    retries = PositiveInt()

    def __init__(self, timeout, retries, endpoint):
        self.timeout = timeout
        self.retries = retries
        self.endpoint = endpoint

    @property
    def total_wait(self):
        """Read-only computed value based on descriptor-managed fields."""
        return self.timeout * self.retries

    @property
    def endpoint(self):
        return self._endpoint

    @endpoint.setter
    def endpoint(self, value):
        if not isinstance(value, str) or not value.strip():
            raise ValueError("endpoint must be a non-empty string")
        if not (value.startswith("http://") or value.startswith("https://")):
            raise ValueError("endpoint must start with 'http://' or 'https://'")
        self._endpoint = value


