class EventBus:
    def __init__(self):
        self._subscribers = {}

    def subscribe(self, event_name, handler):
        """Register a handler function for a named event."""
        self._subscribers.setdefault(event_name, []).append(handler)

    def emit(self, event_name, **data):
        """Call all handlers subscribed to the event."""
        for handler in self._subscribers.get(event_name, []):
            handler(**data)


class SmartHome:
    def __init__(self, bus):
        self.bus = bus
        self.bus.subscribe('motion_detected', self.on_motion_detected)
        self.bus.subscribe('door_opened', self.on_door_opened)
        self.bus.subscribe('temperature_changed', self.on_temperature_changed)

