class Router:
    def __init__(self):
        # Store routes as parsed segment lists with their handler.
        self._routes = []

    def add_route(self, pattern, handler):
        """Register a route pattern with a handler name."""
        segments = self._split_path(pattern)
        self._routes.append((segments, handler))

    def match(self, path):
        """Return {'handler': handler, 'params': {...}} for the first match, or None."""
        path_segments = self._split_path(path)

        for pattern_segments, handler in self._routes:
            if len(pattern_segments) != len(path_segments):
                continue

            params = {}
            matched = True

            for pattern_seg, path_seg in zip(pattern_segments, path_segments):
                if self._is_dynamic(pattern_seg):
                    param_name = pattern_seg[1:-1]
                    params[param_name] = path_seg
                elif pattern_seg != path_seg:
                    matched = False
                    break

            if matched:
                return {"handler": handler, "params": params}

        return None

    def _split_path(self, path):
        """Normalize and split a path into segments."""
        path = path.strip('/')
        return [] if not path else path.split('/')

    def _is_dynamic(self, segment):
        """Check whether a segment is a dynamic parameter like <id>."""
        return len(segment) >= 3 and segment.startswith('<') and segment.endswith('>')


