class BloomFilter:
    def __init__(self, size, hash_count):
        """Create a Bloom filter with a fixed bit array size and number of hashes."""
        self.size = size
        self.hash_count = hash_count
        self.bits = [0] * size

    def _hashes(self, item):
        """Generate hash positions for the given item using different seeds."""
        positions = []
        for seed in range(self.hash_count):
            # Combine the seed with the item to simulate multiple hash functions
            position = hash(f"{seed}-{item}") % self.size
            positions.append(position)
        return positions

    def add(self, item):
        """Add an item to the Bloom filter."""
        for position in self._hashes(item):
            self.bits[position] = 1

    def contains(self, item):
        """Return False if item is definitely not present, True if it might be present."""
        for position in self._hashes(item):
            if self.bits[position] == 0:
                return False
        return True


if __name__ == "__main__":
