    for word in words_to_add:
        bloom.add(word)

    test_words = ["apple", "grape", "banana", "melon"]
    for word in test_words:
        print(f"{word}: {bloom.contains(word)}")

import re

HEADER_RE = re.compile(r'^\[(?P<timestamp>[^\]]+)\]\s+(?P<level>[A-Z]+)\s*(?P<rest>.*)$')
KEY_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')


def _parse_quoted(s: str, i: int) -> tuple[str, int]:
    """Parse a double-quoted string with backslash escapes."""
    i += 1  # skip opening quote
    chars = []
    while i < len(s):
        ch = s[i]
        if ch == '\\':
            i += 1
            if i >= len(s):
                raise ValueError('Trailing escape in quoted value')
            chars.append(s[i])
        elif ch == '"':
            return ''.join(chars), i + 1
        else:
            chars.append(ch)
        i += 1
    raise ValueError('Unterminated quoted value')


def _parse_value(s: str, i: int) -> tuple[str, int]:
    """Parse either a quoted value or an unquoted token."""
    if i >= len(s):
        raise ValueError('Missing value')
    if s[i] == '"':
        return _parse_quoted(s, i)

    start = i
    while i < len(s) and not s[i].isspace():
        i += 1
    if start == i:
        raise ValueError('Empty value')
    return s[start:i], i


def parse_log_line(line: str) -> dict:
    match = HEADER_RE.match(line)
    if not match:
        raise ValueError('Invalid log header')

    timestamp = match.group('timestamp')
    level = match.group('level')
    rest = match.group('rest')

    fields = {}
    message = None
    i = 0

    while i < len(rest):
        while i < len(rest) and rest[i].isspace():
            i += 1
        if i >= len(rest):
            break

        key_match = KEY_RE.match(rest, i)
        if not key_match:
            raise ValueError(f'Invalid key at position {i}')
        key = key_match.group(0)
        i = key_match.end()

        if i >= len(rest) or rest[i] != '=':
            raise ValueError(f"Expected '=' after key '{key}'")
        i += 1

        value, i = _parse_value(rest, i)
        if key == 'message':
            message = value
        else:
            fields[key] = value

    if message is None:
        raise ValueError("Missing required 'message' field")

    return {
        'timestamp': timestamp,
        'level': level,
        'fields': fields,
        'message': message,
    }


def main() -> None:
    samples = [
        '[2025-04-01 10:15:30] INFO user_id=42 action=login message="User logged in successfully"',
        '[2025-04-01 10:16:02] WARN ip=192.168.1.5 path="/api/v1/items" message="Slow response: 512ms"',
        '[2025-04-01 10:17:45] ERROR code=E42 detail="Unexpected \\"quote\\" in payload" message="Request failed"',
    ]

    for line in samples:
        print(parse_log_line(line))


