from __future__ import annotations

from typing import List, Dict, Tuple


WIRE_VARINT = 0
WIRE_LEN = 2


def read_varint(data: bytes, pos: int) -> Tuple[int, int]:
    """Read a protobuf varint starting at pos and return (value, new_pos)."""
    value = 0
    shift = 0
    while True:
        if pos >= len(data):
            raise ValueError("Unexpected end of data while reading varint")
        b = data[pos]
        pos += 1
        value |= (b & 0x7F) << shift
        if not (b & 0x80):
            return value, pos
        shift += 7
        if shift >= 64:
            raise ValueError("Varint too long")


def write_varint(value: int) -> bytes:
    """Encode an integer as protobuf varint."""
    if value < 0:
        raise ValueError("Only non-negative integers supported in this demo")
    out = bytearray()
    while True:
        to_write = value & 0x7F
        value >>= 7
        if value:
            out.append(to_write | 0x80)
        else:
            out.append(to_write)
            return bytes(out)


def skip_field(data: bytes, pos: int, wire_type: int) -> int:
    """Skip an unknown protobuf field based on wire type."""
    if wire_type == WIRE_VARINT:
        _, pos = read_varint(data, pos)
        return pos
    if wire_type == WIRE_LEN:
        length, pos = read_varint(data, pos)
        end = pos + length
        if end > len(data):
            raise ValueError("Length-delimited field exceeds message bounds")
        return end
    raise ValueError(f"Unsupported wire type: {wire_type}")


def parse_person(message: bytes) -> Dict[str, object]:
    """Parse one Person message from raw protobuf bytes."""
    pos = 0
    person: Dict[str, object] = {}

    while pos < len(message):
        key, pos = read_varint(message, pos)
        field_number = key >> 3
        wire_type = key & 0x07

        if field_number == 1 and wire_type == WIRE_VARINT:
            person["id"], pos = read_varint(message, pos)
        elif field_number == 2 and wire_type == WIRE_LEN:
            length, pos = read_varint(message, pos)
            end = pos + length
            if end > len(message):
                raise ValueError("Invalid name length")
            person["name"] = message[pos:end].decode("utf-8")
            pos = end
        elif field_number == 3 and wire_type == WIRE_LEN:
            length, pos = read_varint(message, pos)
            end = pos + length
            if end > len(message):
                raise ValueError("Invalid email length")
            person["email"] = message[pos:end].decode("utf-8")
            pos = end
        else:
            pos = skip_field(message, pos, wire_type)

    if "id" not in person or "name" not in person:
        raise ValueError("Missing required fields: id and name are required")
    return person


def parse_people_stream(data: bytes) -> List[Dict[str, object]]:
    """Parse a stream of length-delimited Person messages."""
    pos = 0
    people: List[Dict[str, object]] = []

    while pos < len(data):
        msg_len, pos = read_varint(data, pos)
        end = pos + msg_len
        if end > len(data):
            raise ValueError("Message length exceeds stream size")
        people.append(parse_person(data[pos:end]))
        pos = end

    return people


def build_person(person_id: int, name: str, email: str | None = None) -> bytes:
    """Manually build a Person protobuf message for the demo."""
    msg = bytearray()

    # field 1: id (varint)
    msg += write_varint((1 << 3) | WIRE_VARINT)
    msg += write_varint(person_id)

    # field 2: name (length-delimited)
    name_bytes = name.encode("utf-8")
    msg += write_varint((2 << 3) | WIRE_LEN)
    msg += write_varint(len(name_bytes))
    msg += name_bytes

    # field 3: email (optional length-delimited)
    if email is not None:
        email_bytes = email.encode("utf-8")
        msg += write_varint((3 << 3) | WIRE_LEN)
        msg += write_varint(len(email_bytes))
        msg += email_bytes

    # Add an unknown field to demonstrate safe skipping.
    msg += write_varint((5 << 3) | WIRE_VARINT)
    msg += write_varint(999)

    return bytes(msg)


def build_stream(messages: List[bytes]) -> bytes:
    """Prefix each message with its varint length."""
    out = bytearray()
    for msg in messages:
        out += write_varint(len(msg))
        out += msg
    return bytes(out)


if __name__ == "__main__":
    stream = build_stream([
        build_person(1, "Alice", "alice@example.com"),
        build_person(2, "Bob"),
    ])
    print(parse_people_stream(stream))

from abc import ABC, abstractmethod
from typing import List


class DiscountStrategy(ABC):
    """Abstract strategy for applying discounts."""

    @abstractmethod
    def apply_discount(self, total: float) -> float:
        pass


class NoDiscount(DiscountStrategy):
    def apply_discount(self, total: float) -> float:
        return total


class PercentageDiscount(DiscountStrategy):
    def __init__(self, percent: float):
        self.percent = percent

    def apply_discount(self, total: float) -> float:
        return total * (1 - self.percent / 100)


class FixedDiscount(DiscountStrategy):
    def __init__(self, amount: float):
        self.amount = amount

    def apply_discount(self, total: float) -> float:
        return max(0.0, total - self.amount)


class ShoppingCart:
    def __init__(self, items: List[float], strategy: DiscountStrategy):
        self.items = items
        self.strategy = strategy

    def set_strategy(self, strategy: DiscountStrategy) -> None:
        """Change the discount strategy at runtime."""
        self.strategy = strategy

    def total_before_discount(self) -> float:
        return sum(self.items)

    def total_after_discount(self) -> float:
        total = self.total_before_discount()
        return self.strategy.apply_discount(total)


if __name__ == "__main__":
    cart = ShoppingCart([29.99, 15.50, 9.99], NoDiscount())

    print(f"Original total: ${cart.total_before_discount():.2f}")
    print(f"No discount: ${cart.total_after_discount():.2f}")

    cart.set_strategy(PercentageDiscount(20))
    print(f"20% discount: ${cart.total_after_discount():.2f}")

    cart.set_strategy(FixedDiscount(10))
    print(f"$10 fixed discount: ${cart.total_after_discount():.2f}")

import json
from abc import ABC, abstractmethod


class Report(ABC):
    def __init__(self):
        self.title = ""
        self.sections = []
        self.metadata = {}

    @abstractmethod
    def serialize(self) -> str:
        pass


class JSONReport(Report):
    def serialize(self) -> str:
        return json.dumps(
            {
                "title": self.title,
                "metadata": self.metadata,
                "sections": self.sections,
            },
            indent=2,
        )


class TextReport(Report):
    def serialize(self) -> str:
        lines = [f"# {self.title}"]
        if self.metadata:
            lines.append("Metadata:")
            for key, value in self.metadata.items():
                lines.append(f"- {key}: {value}")
        if self.sections:
            lines.append("")
            for section in self.sections:
                lines.append(f"## {section['heading']}")
                lines.append(section['content'])
                lines.append("")
        return "\n".join(lines).rstrip()


class ReportFactory:
    @staticmethod
    def create_report(format_name: str) -> Report:
        format_name = format_name.lower()
        if format_name == "json":
            return JSONReport()
        if format_name == "text":
            return TextReport()
        raise ValueError(f"Unsupported report format: {format_name}")


class ReportBuilder:
    def __init__(self, report: Report):
        self.report = report

    def set_title(self, title: str):
        self.report.title = title
        return self

    def add_metadata(self, key: str, value):
        self.report.metadata[key] = value
        return self

    def add_section(self, heading: str, content: str):
        self.report.sections.append({"heading": heading, "content": content})
        return self

    def build(self) -> str:
        return self.report.serialize()


if __name__ == "__main__":
    json_report = (
        ReportBuilder(ReportFactory.create_report("json"))
        .set_title("System Audit")
        .add_metadata("author", "Ops Team")
        .add_metadata("version", 3)
        .add_section("Summary", "All systems operational.")
        .add_section("Risks", "No critical risks detected.")
        .build()
    )

    text_report = (
        ReportBuilder(ReportFactory.create_report("text"))
        .set_title("Deployment Notes")
        .add_metadata("environment", "production")
        .add_section("Completed", "Deployment finished at 22:10 UTC.")
        .add_section("Rollback", "No rollback required.")
        .build()
    )

    print(json_report)
    print("\n" + "=" * 40 + "\n")
    print(text_report)

