import hashlib
import hmac
import json


def handle_webhook(headers, body, secret):
    """Validate a webhook signature and process supported events.

    Args:
        headers: dict of HTTP headers.
        body: raw request body as str or bytes.
        secret: shared secret used for HMAC-SHA256.

    Returns:
        A dict with status and message.
    """
    signature = headers.get("X-Signature")
    if not signature:
        return {"status": 401, "message": "invalid signature"}

    # Normalize body and secret to bytes for HMAC calculation.
    body_bytes = body if isinstance(body, bytes) else body.encode("utf-8")
    secret_bytes = secret if isinstance(secret, bytes) else secret.encode("utf-8")

    expected_signature = hmac.new(
        secret_bytes,
        body_bytes,
        hashlib.sha256,
    ).hexdigest()

    # Use constant-time comparison to avoid timing attacks.
    if not hmac.compare_digest(signature, expected_signature):
        return {"status": 401, "message": "invalid signature"}

    try:
        payload = json.loads(body_bytes.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return {"status": 400, "message": "invalid json"}

    event = payload.get("event")
    if event == "ping":
        return {"status": 200, "message": "pong"}
    if event == "user.created":
        user_id = payload.get("data", {}).get("id")
        return {"status": 200, "message": f"created user {user_id}"}

    return {"status": 400, "message": "unsupported event"}


if __name__ == "__main__":
    # Example usage
    secret = "topsecret"
    body = json.dumps({"event": "user.created", "data": {"id": 42}})
    signature = hmac.new(secret.encode("utf-8"), body.encode("utf-8"), hashlib.sha256).hexdigest()
    headers = {"X-Signature": signature}

    result = handle_webhook(headers, body, secret)
    print(result)

class ConnectionFSM:
    DISCONNECTED = 'DISCONNECTED'
    CONNECTING = 'CONNECTING'
    CONNECTED = 'CONNECTED'
    RETRY_WAIT = 'RETRY_WAIT'
    FAILED = 'FAILED'

    def __init__(self, max_retries: int):
        if max_retries < 0:
            raise ValueError('max_retries must be non-negative')
        self.max_retries = max_retries
        self.retries = 0
        self.state = self.DISCONNECTED

    def _can_retry(self) -> bool:
        return self.retries < self.max_retries

    def handle(self, event: str) -> None:
        # Transition table encoded as state-specific logic.
        if self.state == self.DISCONNECTED:
            if event == 'connect':
                self.state = self.CONNECTING
            else:
                raise ValueError(f'Invalid event {event!r} in state {self.state}')

        elif self.state == self.CONNECTING:
            if event == 'success':
                self.state = self.CONNECTED
            elif event in ('timeout', 'error'):
                self.state = self.RETRY_WAIT if self._can_retry() else self.FAILED
            else:
                raise ValueError(f'Invalid event {event!r} in state {self.state}')

        elif self.state == self.CONNECTED:
            if event == 'disconnect':
                self.state = self.DISCONNECTED
                self.retries = 0  # Successful session ended; clear retry history.
            elif event == 'error':
                self.state = self.RETRY_WAIT if self._can_retry() else self.FAILED
            else:
                raise ValueError(f'Invalid event {event!r} in state {self.state}')

        elif self.state == self.RETRY_WAIT:
            if event == 'retry':
                if not self._can_retry():
                    self.state = self.FAILED
                else:
                    self.retries += 1
                    self.state = self.CONNECTING
            elif event == 'give_up':
                self.state = self.FAILED
            else:
                raise ValueError(f'Invalid event {event!r} in state {self.state}')

        elif self.state == self.FAILED:
            if event == 'reset':
                self.state = self.DISCONNECTED
                self.retries = 0
            else:
                raise ValueError(f'Invalid event {event!r} in state {self.state}')

    def status(self) -> dict:
        return {
            'state': self.state,
            'retries_used': self.retries,
            'max_retries': self.max_retries,
        }


if __name__ == '__main__':
    fsm = ConnectionFSM(max_retries=2)
    for event in ['connect', 'timeout', 'retry', 'error', 'retry', 'success']:
        fsm.handle(event)
    print(fsm.status())

import asyncio
import inspect


class EventBus:
    def __init__(self):
        self._handlers = {}

    def subscribe(self, event_name, handler):
        self._handlers.setdefault(event_name, set()).add(handler)

    def unsubscribe(self, event_name, handler):
        if event_name in self._handlers:
            self._handlers[event_name].discard(handler)
            if not self._handlers[event_name]:
                del self._handlers[event_name]

    async def emit(self, event_name, payload):
        handlers = list(self._handlers.get(event_name, ()))
        tasks = [asyncio.create_task(self._run_handler(event_name, handler, payload)) for handler in handlers]
        if tasks:
            await asyncio.gather(*tasks)

    async def _run_handler(self, event_name, handler, payload):
        try:
            result = handler(payload)
            if inspect.isawaitable(result):
                await result
        except Exception as exc:
            # Avoid infinite recursion if an error handler itself fails.
            if event_name == "error":
                return
            error_payload = {
                "event": event_name,
                "handler": getattr(handler, "__name__", repr(handler)),
                "error": str(exc),
            }
            await self.emit("error", error_payload)


async def main():
    bus = EventBus()

    async def async_logger(data):
        await asyncio.sleep(0.05)
        print(f"async_logger received: {data}")

    def sync_logger(data):
        print(f"sync_logger received: {data}")

    def broken_handler(data):
        raise ValueError("simulated failure")

    def error_handler(data):
        print(f"ERROR from '{data['event']}' in {data['handler']}: {data['error']}")

    bus.subscribe("message", async_logger)
    bus.subscribe("message", sync_logger)
    bus.subscribe("message", broken_handler)
    bus.subscribe("error", error_handler)

    await bus.emit("message", {"text": "first event"})

    bus.unsubscribe("message", sync_logger)
    print("-- unsubscribed sync_logger --")

    await bus.emit("message", {"text": "second event"})


if __name__ == "__main__":
    asyncio.run(main())

class Light:
    def turn_on(self):
        print("The light is ON")

    def turn_off(self):
        print("The light is OFF")


class Command:
    def execute(self):
        raise NotImplementedError("Subclasses must implement execute()")


class TurnOnCommand(Command):
    def __init__(self, light):
        self.light = light

    def execute(self):
        self.light.turn_on()


class TurnOffCommand(Command):
    def __init__(self, light):
        self.light = light

    def execute(self):
        self.light.turn_off()


class RemoteControl:
    def __init__(self):
        self.command = None

    def set_command(self, command):
        self.command = command

    def press_button(self):
        if self.command is not None:
