import os
import json
import hashlib
import zipfile
from pathlib import Path


def sha256_file(path, chunk_size=1024 * 1024):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            h.update(chunk)
    return h.hexdigest()


def add_empty_dir(zf, rel_dir):
    # ZIP directories are represented by entries ending with '/'
    name = rel_dir.replace(os.sep, '/').rstrip('/') + '/'
    info = zipfile.ZipInfo(name)
    zf.writestr(info, b'')


def create_dedup_zip(source_dir, zip_path):
    source = Path(source_dir).resolve()
    manifest = {}
    seen_hashes = {}
    empty_dirs = []

    for root, dirs, files in os.walk(source):
        root_path = Path(root)
        rel_root = root_path.relative_to(source)

        if not dirs and not files and rel_root != Path('.'):
            empty_dirs.append(str(rel_root))

        for file_name in files:
            file_path = root_path / file_name
            rel_path = file_path.relative_to(source).as_posix()
            digest = sha256_file(file_path)
            size = file_path.stat().st_size
            blob_name = f'.dedup/{digest}'

            manifest[rel_path] = {
                'blob': blob_name,
                'size': size,
                'sha256': digest,
            }

            if digest not in seen_hashes:
                seen_hashes[digest] = file_path

    with zipfile.ZipFile(zip_path, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
        for rel_dir in sorted(empty_dirs):
            add_empty_dir(zf, rel_dir)

        for digest, file_path in seen_hashes.items():
            zf.write(file_path, arcname=f'.dedup/{digest}')

        zf.writestr('manifest.json', json.dumps(manifest, indent=2, sort_keys=True))


if __name__ == '__main__':
    import sys

    if len(sys.argv) != 3:
        print(f'Usage: {sys.argv[0]} <source_dir> <output.zip>')
        raise SystemExit(1)

    create_dedup_zip(sys.argv[1], sys.argv[2])
    print(f'Created archive: {sys.argv[2]}')

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_word = False
        self.prefix_count = 0  # Number of words passing through this node


class PrefixTrie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            node.prefix_count += 1
        node.is_word = True

    def search(self, word: str) -> bool:
        node = self._find_node(word)
        return node is not None and node.is_word

    def starts_with(self, prefix: str) -> bool:
        return self._find_node(prefix) is not None

    def count_prefix(self, prefix: str) -> int:
        node = self._find_node(prefix)
        return node.prefix_count if node else 0

    def _find_node(self, text: str):
        node = self.root
        for ch in text:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node


