import json
from collections import defaultdict, deque
from datetime import datetime


def parse_log_line(line):
    """Parse a log line into timestamp, level, and message."""
    parts = line.strip().split(" | ", 2)
    if len(parts) != 3:
        return None

    timestamp_str, level, message = parts
    try:
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return None

    return timestamp, level.strip(), message.strip()


def generate_report(input_file, output_file):
    level_counts = defaultdict(int)
    malformed_lines = 0
    earliest = None
    latest = None
    recent_errors = deque(maxlen=5)

    with open(input_file, "r", encoding="utf-8") as infile:
        for line in infile:
            if not line.strip():
                continue  # Ignore empty lines

            parsed = parse_log_line(line)
            if parsed is None:
                malformed_lines += 1
                continue

            timestamp, level, message = parsed
            level_counts[level] += 1

            if earliest is None or timestamp < earliest:
                earliest = timestamp
            if latest is None or timestamp > latest:
                latest = timestamp

            if level == "ERROR":
                recent_errors.append({
                    "timestamp": timestamp.strftime("%Y-%m-%d %H:%M:%S"),
                    "message": message
                })

    report = {
        "log_levels": dict(sorted(level_counts.items())),
        "earliest_timestamp": earliest.strftime("%Y-%m-%d %H:%M:%S") if earliest else None,
        "latest_timestamp": latest.strftime("%Y-%m-%d %H:%M:%S") if latest else None,
        "malformed_lines": malformed_lines,
        "recent_error_messages": list(recent_errors)
    }

    with open(output_file, "w", encoding="utf-8") as outfile:
        json.dump(report, outfile, indent=2)


if __name__ == "__main__":
    generate_report("app.log", "report.json")

class SimpleTradingBot:
    def __init__(self, starting_cash):
        self.cash_balance = float(starting_cash)
        self.shares_owned = 0
        self.trade_history = []

    def buy_one_share(self, price, day_index):
        if self.cash_balance >= price:
            self.cash_balance -= price
            self.shares_owned += 1
            self.trade_history.append(
                f"Day {day_index}: Bought 1 share at {price:.2f}"
            )
        else:
            self.trade_history.append(
                f"Day {day_index}: Hold (not enough cash to buy at {price:.2f})"
            )

    def sell_one_share(self, price, day_index):
        if self.shares_owned > 0:
            self.cash_balance += price
            self.shares_owned -= 1
            self.trade_history.append(
                f"Day {day_index}: Sold 1 share at {price:.2f}"
            )
        else:
            self.trade_history.append(
                f"Day {day_index}: Hold (no shares to sell at {price:.2f})"
            )

    def hold(self, price, day_index):
        self.trade_history.append(f"Day {day_index}: Hold at {price:.2f}")

    def process_prices(self, prices):
        if not prices:
            self.trade_history.append("No prices provided.")
            return float(self.cash_balance)

        if len(prices) == 1:
            self.trade_history.append(
                f"Day 0: Hold at {float(prices[0]):.2f} (only one price available)"
            )
            return float(self.cash_balance + self.shares_owned * float(prices[0]))

        for day_index in range(1, len(prices)):
            previous_price = float(prices[day_index - 1])
            current_price = float(prices[day_index])

            if current_price < previous_price and self.cash_balance >= current_price:
                self.buy_one_share(current_price, day_index)
            elif current_price > previous_price and self.shares_owned > 0:
                self.sell_one_share(current_price, day_index)
            else:
                self.hold(current_price, day_index)

        final_price = float(prices[-1])
        final_portfolio_value = self.cash_balance + (self.shares_owned * final_price)
        return float(final_portfolio_value)


if __name__ == "__main__":
    sample_prices = [100.0, 98.0, 101.0, 99.0, 103.0, 103.0]
    bot = SimpleTradingBot(500.0)
    final_value = bot.process_prices(sample_prices)

    print(f"Final cash balance: {bot.cash_balance:.2f}")
    print(f"Shares owned: {bot.shares_owned}")
    print(f"Final portfolio value: {final_value:.2f}")
    print("Trade history:")
    for trade in bot.trade_history:
        print(trade)

