import json
import sys
from collections import Counter, defaultdict
from datetime import datetime
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


def parse_datetime(value: Any) -> Optional[datetime]:
    if not isinstance(value, str) or not value.strip():
        return None

    text = value.strip()
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"

    try:
        return datetime.fromisoformat(text)
    except ValueError:
        formats = (
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%dT%H:%M:%S",
            "%Y-%m-%d %H:%M:%S%z",
            "%Y-%m-%dT%H:%M:%S%z",
        )
        for fmt in formats:
            try:
                return datetime.strptime(text, fmt)
            except ValueError:
                continue
    return None


def safe_float(value: Any) -> Optional[float]:
    try:
        if value is None or isinstance(value, bool):
            return None
        return float(value)
    except (TypeError, ValueError):
        return None


def normalize_status(value: Any) -> str:
    if not isinstance(value, str):
        return "unknown"
    return value.strip().lower()


def is_success_status(status: str) -> bool:
    return status in {"success", "succeeded", "passed", "completed"}


def is_failure_status(status: str) -> bool:
    return status in {"failed", "failure", "error", "cancelled", "canceled", "timed_out", "timeout"}


def compute_run_duration_seconds(run: Dict[str, Any]) -> Optional[float]:
    start = parse_datetime(run.get("start_time"))
    end = parse_datetime(run.get("end_time"))

    if start and end:
        delta = (end - start).total_seconds()
        if delta >= 0:
            return delta

    duration = safe_float(run.get("duration"))
    if duration is not None and duration >= 0:
        return duration

    stages = run.get("stages")
    if isinstance(stages, list):
        stage_durations = [
            d for d in (safe_float(stage.get("duration")) if isinstance(stage, dict) else None for stage in stages)
            if d is not None and d >= 0
        ]
        if stage_durations:
            return sum(stage_durations)

    return None


def extract_failing_stages(run: Dict[str, Any]) -> List[str]:
    stages = run.get("stages")
    if not isinstance(stages, list):
        return []

    failing = [
        str(stage.get("name")).strip()
        for stage in stages
        if isinstance(stage, dict)
        and str(stage.get("name", "")).strip()
        and is_failure_status(normalize_status(stage.get("result")))
    ]
    return failing


def analyze_pipelines(data: Any) -> Dict[str, Any]:
    if isinstance(data, dict):
        runs = data.get("runs", [])
    elif isinstance(data, list):
        runs = data
    else:
        runs = []

    pipeline_runs: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
    malformed_runs = 0

    for run in runs:
        if not isinstance(run, dict):
            malformed_runs += 1
            continue

        pipeline_name = run.get("pipeline_name")
        if not isinstance(pipeline_name, str) or not pipeline_name.strip():
            malformed_runs += 1
            continue

        pipeline_runs[pipeline_name.strip()].append(run)

    report: Dict[str, Any] = {
        "pipelines": {},
        "summary": {
            "total_pipelines": len(pipeline_runs),
            "total_runs": sum(len(items) for items in pipeline_runs.values()),
            "malformed_runs_skipped": malformed_runs,
        },
    }

    for pipeline_name, runs_list in sorted(pipeline_runs.items()):
        statuses = [normalize_status(run.get("status")) for run in runs_list]
        successful_runs = [run for run in runs_list if is_success_status(normalize_status(run.get("status")))]
        failed_runs = [run for run in runs_list if is_failure_status(normalize_status(run.get("status")))]

        durations = [
            duration
            for duration in (compute_run_duration_seconds(run) for run in runs_list)
            if duration is not None
        ]

        failing_stage_counter = Counter(
            stage_name
            for run in failed_runs
            for stage_name in extract_failing_stages(run)
        )

        most_frequent_failing_stage: Optional[str] = None
        if failing_stage_counter:
            most_frequent_failing_stage = failing_stage_counter.most_common(1)[0][0]

        total_runs = len(runs_list)
        success_rate = (len(successful_runs) / total_runs * 100.0) if total_runs else 0.0
        average_execution_time = (sum(durations) / len(durations)) if durations else None

        report["pipelines"][pipeline_name] = {
            "total_runs": total_runs,
            "success_rate_percent": round(success_rate, 2),
            "average_execution_time_seconds": round(average_execution_time, 2) if average_execution_time is not None else None,
            "most_frequently_failing_stage": most_frequent_failing_stage,
            "status_breakdown": {
                "successful": len(successful_runs),
                "failed": len(failed_runs),
                "other": len([status for status in statuses if not is_success_status(status) and not is_failure_status(status)]),
            },
        }

    return report


def load_json_file(file_path: Path) -> Any:
    with file_path.open("r", encoding="utf-8") as file:
        return json.load(file)


def main() -> None:
    input_path = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("pipeline_runs.json")

    try:
        data = load_json_file(input_path)
        report = analyze_pipelines(data)
    except FileNotFoundError:
        report = {
            "pipelines": {},
            "summary": {
                "total_pipelines": 0,
                "total_runs": 0,
                "malformed_runs_skipped": 0,
            },
            "error": f"Input file not found: {input_path}",
        }
    except json.JSONDecodeError as exc:
        report = {
            "pipelines": {},
            "summary": {
                "total_pipelines": 0,
                "total_runs": 0,
                "malformed_runs_skipped": 0,
            },
            "error": f"Invalid JSON input: {exc}",
        }
    except Exception as exc:
        report = {
            "pipelines": {},
            "summary": {
                "total_pipelines": 0,
                "total_runs": 0,
                "malformed_runs_skipped": 0,
            },
            "error": f"Unexpected error: {exc}",
        }

    print(json.dumps(report, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()

from abc import ABC, abstractmethod
from typing import Dict, List


class NotificationChannel(ABC):
    @property
    @abstractmethod
    def channel_name(self) -> str:
        """Unique name used to route notifications."""
        raise NotImplementedError

    @abstractmethod
    def send(self, recipient: str, message: str) -> bool:
        """Send a message to a single recipient."""
        raise NotImplementedError


class EmailChannel(NotificationChannel):
    @property
    def channel_name(self) -> str:
        return "email"

    def send(self, recipient: str, message: str) -> bool:
        print(f"[EMAIL] To: {recipient} | Message: {message}")
        return "@" in recipient


class SMSChannel(NotificationChannel):
    @property
    def channel_name(self) -> str:
        return "sms"

    def send(self, recipient: str, message: str) -> bool:
        print(f"[SMS] To: {recipient} | Message: {message}")
        return recipient.isdigit() and len(recipient) >= 10


class PushChannel(NotificationChannel):
    @property
    def channel_name(self) -> str:
        return "push"

    def send(self, recipient: str, message: str) -> bool:
        print(f"[PUSH] Device: {recipient} | Message: {message}")
        return recipient.startswith("device_")


class NotificationManager:
    def __init__(self, channels: List[NotificationChannel]):
        if not all(isinstance(channel, NotificationChannel) for channel in channels):
            raise TypeError("All channels must be instances of NotificationChannel")
        self._channels = {channel.channel_name: channel for channel in channels}

    def broadcast(self, recipients_by_channel: Dict[str, List[str]], message: str) -> Dict[str, int]:
        results: Dict[str, int] = {}

        for channel_name, recipients in recipients_by_channel.items():
            channel = self._channels.get(channel_name)
            if channel is None:
                results[channel_name] = 0
                continue

            success_count = 0
            for recipient in recipients:
                if channel.send(recipient, message):
                    success_count += 1
            results[channel_name] = success_count

        return results


def main() -> None:
    manager = NotificationManager([
        EmailChannel(),
        SMSChannel(),
        PushChannel(),
    ])

    recipients = {
        "email": ["alice@example.com", "invalid-email"],
        "sms": ["1234567890", "12ab"],
        "push": ["device_a1", "unknown"],
    }

    result = manager.broadcast(recipients, "System maintenance starts at 10 PM.")
    print("Summary:", result)


if __name__ == "__main__":
    main()
