class PrefixTrie:
    class _Node:
        __slots__ = ("children", "pass_count", "end_count")

        def __init__(self):
            self.children = {}
            self.pass_count = 0   # total word occurrences passing through this node
            self.end_count = 0    # total word occurrences ending at this node

    def __init__(self):
        self.root = self._Node()

    def insert(self, word: str) -> None:
        node = self.root
        node.pass_count += 1
        for ch in word:
            if ch not in node.children:
                node.children[ch] = self._Node()
            node = node.children[ch]
            node.pass_count += 1
        node.end_count += 1

    def delete(self, word: str) -> bool:
        # First verify the word exists and keep the traversal path.
        node = self.root
        path = [self.root]
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
            path.append(node)
        if node.end_count == 0:
            return False

        # Decrement counts along the path.
        self.root.pass_count -= 1
        node = self.root
        for i, ch in enumerate(word):
            child = node.children[ch]
            child.pass_count -= 1
            # Prune dead branches early.
            if child.pass_count == 0:
                del node.children[ch]
                break
            node = child
        else:
            path[-1].end_count -= 1
            return True

        # If pruned before reaching the terminal node, still decrement end_count there.
        path[-1].end_count -= 1
        return True

    def count_prefix(self, prefix: str) -> int:
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return 0
            node = node.children[ch]
        return node.pass_count

    def top_k(self, prefix: str, k: int):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]

        results = []

        def dfs(cur, path):
            if cur.end_count > 0:
                results.append(("".join(path), cur.end_count))
            for ch, nxt in cur.children.items():
                path.append(ch)
                dfs(nxt, path)
                path.pop()

        dfs(node, list(prefix))
        results.sort(key=lambda item: (-item[1], item[0]))
        return [word for word, _ in results[:k]]


