import hashlib


class BloomFilter:
    def __init__(self, size, hash_count):
        # size: number of bits in the filter
        # hash_count: number of hash functions to simulate
        self.size = size
        self.hash_count = hash_count
        self.bits = [0] * size

    def _hashes(self, item):
        # Generate multiple hash positions for the given item
        positions = []
        for i in range(self.hash_count):
            data = f"{item}:{i}".encode("utf-8")
            digest = hashlib.sha256(data).hexdigest()
            position = int(digest, 16) % self.size
            positions.append(position)
        return positions

    def add(self, item):
        # Set all hash positions to 1
        for position in self._hashes(item):
            self.bits[position] = 1

    def contains(self, item):
        # If any position is 0, the item is definitely not present
        return all(self.bits[position] == 1 for position in self._hashes(item))


if __name__ == "__main__":
    bloom = BloomFilter(size=50, hash_count=3)

    added_words = ["apple", "banana", "orange"]
    for word in added_words:
        bloom.add(word)

    test_words = ["apple", "banana", "grape", "melon", "orange"]
    for word in test_words:
        result = bloom.contains(word)
        print(f"{word}: {result}")

