    """Abstract interface for all notification channels."""

    @abstractmethod
    def send(self, message: str, recipient: str) -> str:
        pass


class EmailChannel(NotificationChannel):
    def send(self, message: str, recipient: str) -> str:
        return f"Email sent to {recipient}: {message}"


class SMSChannel(NotificationChannel):
    def send(self, message: str, recipient: str) -> str:
        return f"SMS sent to {recipient}: {message}"


class PushChannel(NotificationChannel):
    def send(self, message: str, recipient: str) -> str:
        return f"Push notification sent to {recipient}: {message}"


class NotificationService:
    """Registers and dispatches notifications through named channels."""

    def __init__(self):
        self._channels = {}

    def register_channel(self, name: str, channel: NotificationChannel) -> None:
        self._channels[name] = channel

    def send_via(self, channel_name: str, message: str, recipient: str) -> str:
        channel = self._channels.get(channel_name)
        if channel is None:
            raise ValueError(f"Unknown channel: {channel_name}")
        return channel.send(message, recipient)


# Usage example
if __name__ == "__main__":
    service = NotificationService()
    service.register_channel("email", EmailChannel())
    service.register_channel("sms", SMSChannel())
    service.register_channel("push", PushChannel())

    print(service.send_via("email", "Welcome aboard!", "alice@example.com"))
    print(service.send_via("sms", "Your code is 4821", "+123456789"))
    print(service.send_via("push", "You have a new follower", "user_42"))

import json
import csv
import io
import threading
from abc import ABC, abstractmethod


class Serializer(ABC):
    @abstractmethod
    def serialize(self, data):
        pass

    @abstractmethod
    def deserialize(self, text):
        pass


class SerializerRegistry:
    _instance = None
    _instance_lock = threading.Lock()

    def __new__(cls):
        # Double-checked locking for thread-safe singleton creation.
        if cls._instance is None:
            with cls._instance_lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
                    cls._instance._registry = {}
                    cls._instance._registry_lock = threading.RLock()
        return cls._instance

    def register(self, name, serializer_cls, override=False):
        if not issubclass(serializer_cls, Serializer):
            raise TypeError("Registered class must inherit from Serializer")
        with self._registry_lock:
            if name in self._registry and not override:
                raise ValueError(f"Serializer '{name}' is already registered")
            self._registry[name] = serializer_cls

    def get(self, name):
        with self._registry_lock:
            try:
                return self._registry[name]
            except KeyError:
                raise KeyError(f"Unknown serializer format: {name}") from None

    def create(self, name):
        return self.get(name)()

    def available_formats(self):
        with self._registry_lock:
            return tuple(sorted(self._registry.keys()))


def register_serializer(name, override=False):
    # Decorator for automatic class registration.
    def decorator(cls):
        SerializerRegistry().register(name, cls, override=override)
        return cls
    return decorator


@register_serializer("json")
class JsonSerializer(Serializer):
    def serialize(self, data):
        return json.dumps(data)

    def deserialize(self, text):
        return json.loads(text)


@register_serializer("csv")
class CsvSerializer(Serializer):
    def serialize(self, data):
        if not data:
            return ""
        output = io.StringIO()
        writer = csv.DictWriter(output, fieldnames=data[0].keys())
        writer.writeheader()
        writer.writerows(data)
        return output.getvalue()

    def deserialize(self, text):
        if not text.strip():
            return []
        input_stream = io.StringIO(text)
        return list(csv.DictReader(input_stream))


if __name__ == "__main__":
    registry = SerializerRegistry()

    json_serializer = registry.create("json")
    payload = {"service": "api", "enabled": True, "retries": 3}
    encoded = json_serializer.serialize(payload)
    decoded = json_serializer.deserialize(encoded)
    print("JSON:", encoded, decoded)

    csv_serializer = registry.create("csv")
    rows = [{"name": "Alice", "age": 30}, {"name": "Bob", "age": 25}]
    csv_text = csv_serializer.serialize(rows)
    csv_rows = csv_serializer.deserialize(csv_text)
    print("CSV:\n", csv_text)
    print("Parsed:", csv_rows)
    print("Available formats:", registry.available_formats())

import argparse
import csv
import json
import sys
from collections import defaultdict
from datetime import datetime
from decimal import Decimal, InvalidOperation
from pathlib import Path


def parse_args():
    parser = argparse.ArgumentParser(
        description="Process a CSV export of personal finance transactions and generate a monthly spending summary."
    )
    parser.add_argument(
        "input_csv",
        help="Path to the input CSV file containing transactions.",
    )
    parser.add_argument(
        "-b",
        "--budget",
        type=float,
        required=True,
        help="Monthly spending budget used to flag overspending.",
    )
    parser.add_argument(
        "-o",
        "--output-json",
        default="monthly_summary.json",
        help="Path to save the JSON summary file (default: monthly_summary.json).",
    )
    return parser.parse_args()


def normalize_header(header):
    return header.strip().lower() if header is not None else ""


def parse_date(date_str):
    date_str = (date_str or "").strip()
    formats = [
        "%Y-%m-%d",
        "%m/%d/%Y",
        "%d/%m/%Y",
        "%Y/%m/%d",
        "%m-%d-%Y",
        "%d-%m-%Y",
    ]
    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue
    raise ValueError(f"Unsupported date format: {date_str}")


def parse_amount(amount_str):
    cleaned = (amount_str or "").strip().replace(",", "").replace("$", "")
    if cleaned.startswith("(") and cleaned.endswith(")"):
        cleaned = f"-{cleaned[1:-1]}"
    return Decimal(cleaned)


def load_transactions(csv_path):
    transactions = []
    invalid_rows = []

    required_fields = {"date", "description", "category", "amount", "type"}

    with open(csv_path, "r", newline="", encoding="utf-8-sig") as csvfile:
        reader = csv.DictReader(csvfile)
        if reader.fieldnames is None:
            raise ValueError("CSV file is missing a header row.")

        normalized_fieldnames = [normalize_header(name) for name in reader.fieldnames]
        if not required_fields.issubset(set(normalized_fieldnames)):
            missing = sorted(required_fields - set(normalized_fieldnames))
            raise ValueError(f"CSV file is missing required columns: {', '.join(missing)}")

        for index, raw_row in enumerate(reader, start=2):
            row = {normalize_header(k): (v.strip() if isinstance(v, str) else v) for k, v in raw_row.items()}

            if not any((value or "").strip() for value in row.values() if isinstance(value, str)):
                invalid_rows.append({"row_number": index, "reason": "Empty row"})
                continue

            try:
                date_value = parse_date(row.get("date", ""))
                description = row.get("description", "") or "Unknown"
                category = row.get("category", "") or "Uncategorized"
                amount = parse_amount(row.get("amount", ""))
                tx_type = (row.get("type", "") or "").strip().lower()

                if tx_type not in {"debit", "credit"}:
                    raise ValueError("Type must be 'debit' or 'credit'")

                if amount < 0:
                    amount = abs(amount)

                transactions.append(
                    {
                        "date": date_value,
                        "month": date_value.strftime("%Y-%m"),
                        "description": description,
                        "category": category,
                        "amount": amount,
                        "type": tx_type,
                    }
                )
            except (ValueError, InvalidOperation) as exc:
                invalid_rows.append({"row_number": index, "reason": str(exc), "row": raw_row})

    return transactions, invalid_rows


def summarize_transactions(transactions, monthly_budget):
    monthly = defaultdict(
        lambda: {
            "expenses_by_category": defaultdict(Decimal),
            "income_by_category": defaultdict(Decimal),
            "total_expenses": Decimal("0"),
            "total_income": Decimal("0"),
            "transaction_count": 0,
        }
    )

    for tx in transactions:
        month_data = monthly[tx["month"]]
        month_data["transaction_count"] += 1

        if tx["type"] == "debit":
            month_data["expenses_by_category"][tx["category"]] += tx["amount"]
            month_data["total_expenses"] += tx["amount"]
        else:
            month_data["income_by_category"][tx["category"]] += tx["amount"]
            month_data["total_income"] += tx["amount"]

    summary = {}
    budget_decimal = Decimal(str(monthly_budget))

    for month in sorted(monthly.keys()):
        data = monthly[month]

        top_spending = sorted(
            [
                {"category": category, "amount": amount}
                for category, amount in data["expenses_by_category"].items()
            ],
            key=lambda item: item["amount"],
            reverse=True,
        )[:3]

        summary[month] = {
            "total_expenses": data["total_expenses"],
            "total_income": data["total_income"],
            "net": data["total_income"] - data["total_expenses"],
            "transaction_count": data["transaction_count"],
            "over_budget": data["total_expenses"] > budget_decimal,
            "budget": budget_decimal,
            "expenses_by_category": dict(sorted(data["expenses_by_category"].items())),
            "income_by_category": dict(sorted(data["income_by_category"].items())),
            "top_3_spending_categories": top_spending,
        }

    return summary


def decimal_to_float(value):
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, dict):
        return {k: decimal_to_float(v) for k, v in value.items()}
    if isinstance(value, list):
        return [decimal_to_float(item) for item in value]
    return value


def print_report(summary, invalid_rows, budget):
    print("=" * 72)
    print("MONTHLY SPENDING SUMMARY".center(72))
    print("=" * 72)
    print(f"Monthly Budget: ${budget:,.2f}")
    print()

    if not summary:
        print("No valid transactions found.")
    else:
        for month, data in summary.items():
            print(f"{month}")
            print("-" * 72)
            print(f"Transactions   : {data['transaction_count']}")
            print(f"Total Income   : ${float(data['total_income']):,.2f}")
            print(f"Total Expenses : ${float(data['total_expenses']):,.2f}")
            print(f"Net            : ${float(data['net']):,.2f}")
            print(f"Budget Status  : {'OVER BUDGET' if data['over_budget'] else 'Within Budget'}")

            print("Top 3 Spending Categories:")
            if data["top_3_spending_categories"]:
                for idx, item in enumerate(data["top_3_spending_categories"], start=1):
                    print(f"  {idx}. {item['category']}: ${float(item['amount']):,.2f}")
            else:
                print("  None")

            print("Expenses by Category:")
            expense_items = [
                f"  - {category}: ${float(amount):,.2f}"
                for category, amount in data["expenses_by_category"].items()
            ]
            print("\n".join(expense_items) if expense_items else "  None")

            print("Income by Category:")
            income_items = [
                f"  - {category}: ${float(amount):,.2f}"
                for category, amount in data["income_by_category"].items()
            ]
            print("\n".join(income_items) if income_items else "  None")
            print()

    print("=" * 72)
    print(f"Invalid/Missing Rows Skipped: {len(invalid_rows)}")
    if invalid_rows:
        preview = invalid_rows[:10]
        for item in preview:
            print(f"  Row {item.get('row_number', '?')}: {item.get('reason', 'Unknown error')}")
        if len(invalid_rows) > 10:
            print(f"  ... and {len(invalid_rows) - 10} more")
    print("=" * 72)


def save_json_summary(summary, invalid_rows, output_path):
    payload = {
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "months": decimal_to_float(summary),
        "invalid_rows_skipped": len(invalid_rows),
        "invalid_rows": invalid_rows,
    }

    with open(output_path, "w", encoding="utf-8") as json_file:
        json.dump(payload, json_file, indent=2)


def main():
    args = parse_args()
    input_path = Path(args.input_csv)
    output_path = Path(args.output_json)

    if not input_path.exists() or not input_path.is_file():
        print(f"Error: Input file not found: {input_path}", file=sys.stderr)
        sys.exit(1)

    try:
        transactions, invalid_rows = load_transactions(input_path)
        summary = summarize_transactions(transactions, args.budget)
        print_report(summary, invalid_rows, args.budget)
        save_json_summary(summary, invalid_rows, output_path)
        print(f"JSON summary saved to: {output_path}")
    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

class EventBus:
    def __init__(self):
        self._listeners = {}

    def subscribe(self, event_name, callback):
        self._listeners.setdefault(event_name, []).append(callback)

    def emit(self, event_name, data=None):
        for callback in self._listeners.get(event_name, []):
            callback(data)


class TaskManager:
    def __init__(self, event_bus):
        self.event_bus = event_bus
        self.tasks = {}
        self.next_id = 1

    def add_task(self, title):
        task = {
            'id': self.next_id,
            'title': title,
            'completed': False
        }
        self.tasks[self.next_id] = task
        self.next_id += 1
        self.event_bus.emit('task_added', task)
        return task['id']

    def complete_task(self, task_id):
        task = self.tasks.get(task_id)
        if task and not task['completed']:
            task['completed'] = True
            self.event_bus.emit('task_completed', task)

    def remove_task(self, task_id):
        task = self.tasks.pop(task_id, None)
        if task:
            self.event_bus.emit('task_removed', task)


# Event listeners
def on_task_added(task):
    print(f"Added: #{task['id']} - {task['title']}")


def on_task_completed(task):
    print(f"Completed: #{task['id']} - {task['title']}")


def on_task_removed(task):
    print(f"Removed: #{task['id']} - {task['title']}")


# Demonstration
bus = EventBus()
bus.subscribe('task_added', on_task_added)
bus.subscribe('task_completed', on_task_completed)
bus.subscribe('task_removed', on_task_removed)

manager = TaskManager(bus)
id1 = manager.add_task('Write project update')
id2 = manager.add_task('Review pull request')
manager.complete_task(id1)
manager.remove_task(id2)

from abc import ABC, abstractmethod


class Notification(ABC):
    def __init__(self, recipient: str, message: str, priority: str = "normal"):
        self.recipient = recipient
        self.message = message
        self.priority = priority

    @abstractmethod
    def send(self) -> None:
        pass


class EmailNotification(Notification):
    def send(self) -> None:
        print(f"[EMAIL] To: {self.recipient} | Priority: {self.priority} | Message: {self.message}")


class SMSNotification(Notification):
    def send(self) -> None:
        print(f"[SMS] To: {self.recipient} | Priority: {self.priority} | Message: {self.message}")


class NotificationFactory:
    @staticmethod
    def create(channel: str, recipient: str, message: str, priority: str = "normal") -> Notification:
        channel = channel.lower()
        if channel == "email":
            return EmailNotification(recipient, message, priority)
        if channel == "sms":
            return SMSNotification(recipient, message, priority)
        raise ValueError(f"Unsupported notification channel: {channel}")


class NotificationBuilder:
    def __init__(self):
        self._channel = None
        self._recipient = None
        self._message = ""
        self._priority = "normal"

    def channel(self, channel: str):
        self._channel = channel
        return self

    def recipient(self, recipient: str):
        self._recipient = recipient
        return self

    def message(self, message: str):
        self._message = message
        return self

    def priority(self, priority: str):
        self._priority = priority
        return self

    def build(self) -> Notification:
        if not self._channel:
            raise ValueError("Channel is required")
        if not self._recipient:
            raise ValueError("Recipient is required")
        return NotificationFactory.create(
            self._channel,
            self._recipient,
            self._message,
            self._priority,
        )


def main() -> None:
    email = (
        NotificationBuilder()
        .channel("email")
        .recipient("user@example.com")
        .message("Your report is ready.")
        .priority("high")
        .build()
    )

    sms = (
        NotificationBuilder()
        .channel("sms")
        .recipient("+1234567890")
        .message("Your code is 4821.")
        .build()
    )

    email.send()
    sms.send()


if __name__ == "__main__":
    main()
}

from typing import Dict
import re

from pydantic import BaseModel, Field, ValidationError, field_validator, model_validator, ConfigDict


SERVICE_RE = re.compile(r'^[a-z0-9-]+$')
ENV_KEY_RE = re.compile(r'^[A-Z][A-Z0-9_]*$')
MEMORY_RE = re.compile(r'^(\d+)(Mi|Gi)$')


class Resources(BaseModel):
    cpu: float = Field(..., gt=0, le=8)
    memory: str

    @field_validator('memory')
    @classmethod
    def validate_memory(cls, value: str) -> str:
        match = MEMORY_RE.fullmatch(value)
        if not match:
            raise ValueError("memory must be like '512Mi' or '2Gi'")
        amount = int(match.group(1))
        if amount <= 0:
            raise ValueError('memory amount must be positive')
        return value


class DeploymentConfig(BaseModel):
    model_config = ConfigDict(extra='forbid')

    service_name: str
    replicas: int = Field(..., ge=1, le=20)
    image: str
    env: Dict[str, str]
    resources: Resources

    @field_validator('service_name')
    @classmethod
    def validate_service_name(cls, value: str) -> str:
        if not value or not SERVICE_RE.fullmatch(value):
            raise ValueError('service_name must contain only lowercase letters, digits, and hyphens')
        return value

    @field_validator('image')
    @classmethod
    def validate_image(cls, value: str) -> str:
        if ':' not in value or value.endswith(':') or value.startswith(':'):
            raise ValueError("image must include a non-empty tag, e.g. 'nginx:1.25'")
        return value

    @field_validator('env')
    @classmethod
    def validate_env(cls, value: Dict[str, str]) -> Dict[str, str]:
        for key, val in value.items():
            if not ENV_KEY_RE.fullmatch(key):
                raise ValueError(f'invalid env key: {key}')
            if not isinstance(val, str):
                raise ValueError(f'env value for {key} must be a string')
        return value

    @model_validator(mode='after')
    def validate_scaling_rules(self):
        if self.replicas > 10 and self.resources.cpu < 1.0:
            raise ValueError('cpu must be at least 1.0 when replicas is greater than 10')
        return self


def validate_config(data: dict) -> dict:
    """Validate deployment configuration and return it as a plain dictionary."""
    config = DeploymentConfig.model_validate(data)
    return config.model_dump()


if __name__ == '__main__':
    sample = {
        'service_name': 'api-service',
        'replicas': 12,
        'image': 'nginx:1.25',
        'env': {'APP_ENV': 'production', 'LOG_LEVEL': 'info'},
        'resources': {'cpu': 1.5, 'memory': '512Mi'},
    }

    try:
        print(validate_config(sample))
    except ValidationError as e:
        print(e)

