import argparse
import re
import sys
from collections import Counter
from pathlib import Path


def extract_words(text, ignore_case=False, min_length=1):
    """Extract words using a simple alphabetic/apostrophe pattern."""
    if ignore_case:
        text = text.lower()
    words = re.findall(r"[A-Za-z']+", text)
    return [w for w in words if len(w) >= min_length]


def count_words(paths, top, min_length, ignore_case):
    counter = Counter()
    valid_files = 0

    for raw_path in paths:
        path = Path(raw_path)
        if not path.is_file():
            print(f"warning: skipping missing file: {raw_path}", file=sys.stderr)
            continue

        valid_files += 1
        try:
            text = path.read_text(encoding="utf-8")
        except OSError as exc:
            print(f"warning: could not read {raw_path}: {exc}", file=sys.stderr)
            continue

        counter.update(extract_words(text, ignore_case=ignore_case, min_length=min_length))

    if valid_files == 0:
        raise ValueError("no valid input files provided")

    items = sorted(counter.items(), key=lambda item: (-item[1], item[0]))
    return items[:top]


def build_parser():
    parser = argparse.ArgumentParser(
        description="Report the most frequent words across text files."
    )
    parser.add_argument("files", nargs="+", help="Input text files")
    parser.add_argument("--top", type=int, default=10, help="Number of results to show")
    parser.add_argument(
        "--min-length", type=int, default=1, help="Ignore words shorter than this"
    )
    parser.add_argument(
        "--ignore-case",
        action="store_true",
        help="Count words case-insensitively",
    )
    return parser


def main():
    parser = build_parser()
    args = parser.parse_args()

    if args.top < 1:
        parser.error("--top must be at least 1")
    if args.min_length < 1:
        parser.error("--min-length must be at least 1")

    try:
        results = count_words(
            args.files,
            top=args.top,
            min_length=args.min_length,
            ignore_case=args.ignore_case,
        )
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        sys.exit(1)

    for word, count in results:
        print(f"{word} {count}")


if __name__ == "__main__":
    main()

import argparse
import json
import sys


def parse_args():
    parser = argparse.ArgumentParser(
        description="Read integers from a file or stdin and print summary statistics."
    )
    parser.add_argument(
        "--file",
        help="Path to input file containing whitespace-separated integers"
    )
    parser.add_argument(
        "--top",
        type=int,
        help="Show the N largest unique numbers"
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Output results as JSON"
    )
    return parser.parse_args()


def read_input(path=None):
    try:
        if path:
            with open(path, "r", encoding="utf-8") as f:
                return f.read()
        return sys.stdin.read()
    except OSError as e:
        sys.exit(f"Error reading input: {e}")


def parse_numbers(text):
    tokens = text.split()
    if not tokens:
        sys.exit("Error: no integers provided")

    numbers = []
    for token in tokens:
        try:
            numbers.append(int(token))
        except ValueError:
            sys.exit(f"Error: invalid integer token: {token}")
    return numbers


def build_result(numbers, top_n=None):
    result = {
        "count": len(numbers),
        "sum": sum(numbers),
        "min": min(numbers),
        "max": max(numbers),
        "average": sum(numbers) / len(numbers),
    }
    if top_n is not None:
        result["top"] = sorted(set(numbers), reverse=True)[:top_n]
    return result


def print_result(result, as_json=False):
    if as_json:
        print(json.dumps(result, indent=2))
    else:
        for key in ("count", "sum", "min", "max", "average"):
            print(f"{key}: {result[key]}")
        if "top" in result:
            print("top:", " ".join(map(str, result["top"])))


def main():
    args = parse_args()

    if args.top is not None and args.top <= 0:
        sys.exit("Error: --top must be a positive integer")

    text = read_input(args.file)
    numbers = parse_numbers(text)
    result = build_result(numbers, args.top)
    print_result(result, args.json)


