import json
import csv
import io
import threading


class SingletonMeta(type):
    """Thread-safe Singleton metaclass."""
    _instances = {}
    _lock = threading.Lock()

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            with cls._lock:
                if cls not in cls._instances:
                    cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]


class SerializerRegistry(metaclass=SingletonMeta):
    def __init__(self):
        self._serializers = {}
        self._registry_lock = threading.Lock()

    def register(self, name):
        """Decorator to register a serializer class under a unique name."""
        def decorator(serializer_cls):
            with self._registry_lock:
                if name in self._serializers:
                    raise ValueError(f"Serializer '{name}' is already registered")
                if not hasattr(serializer_cls, 'serialize') or not callable(serializer_cls.serialize):
                    raise TypeError("Serializer class must define a callable 'serialize' method")
                self._serializers[name] = serializer_cls
            return serializer_cls
        return decorator

    def get(self, name):
        """Return a new serializer instance by name."""
        try:
            serializer_cls = self._serializers[name]
        except KeyError:
            raise KeyError(f"Unknown serializer: '{name}'") from None
        return serializer_cls()

    def list_serializers(self):
        return sorted(self._serializers.keys())


registry = SerializerRegistry()


@registry.register('json')
class JsonSerializer:
    def serialize(self, data):
        return json.dumps(data)


@registry.register('csv')
class CsvSerializer:
    def serialize(self, data):
        if not data:
            return ''
        output = io.StringIO()
        fieldnames = sorted(data[0].keys())
        writer = csv.DictWriter(output, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(data)
        return output.getvalue()


