    print(registry.get('json').serialize({'name': 'Ada', 'age': 30}))
    rows = [{'name': 'Ada', 'age': 30}, {'name': 'Linus', 'age': 28}]
    print(registry.get('csv').serialize(rows))

class LogWindow:
    """Iterate lazily over filtered log messages in a file."""

    def __init__(self, filename, level):
        self.filename = filename
        self.level = level
        self._file = None

    def __iter__(self):
        self._file = open(self.filename, 'r', encoding='utf-8')
        return self

    def __next__(self):
        if self._file is None:
            self.__iter__()

        for line in self._file:
            line = line.strip()
            if ':' not in line:
                continue  # Skip malformed lines

            log_level, message = line.split(':', 1)
            if log_level.strip() == self.level:
                return message.strip()

        self._file.close()
        self._file = None
        raise StopIteration


def batched(iterable, size):
    """Yield items from an iterable in fixed-size lists."""
    if size <= 0:
        raise ValueError('size must be greater than 0')

    batch = []
    for item in iterable:
        batch.append(item)
        if len(batch) == size:
            yield batch
            batch = []

    if batch:
        yield batch


