def parse_kv_line(line: str) -> dict:
    """Parse comma-separated key=value pairs with support for quoted values.

    Example:
        'name="Doe, John", age=30, path="C:\\\\Temp\\\\file.txt"'
        -> {'name': 'Doe, John', 'age': '30', 'path': 'C:\\Temp\\file.txt'}
    """
    result = {}
    i = 0
    n = len(line)

    while i < n:
        # Skip leading whitespace before a pair
        while i < n and line[i].isspace():
            i += 1
        if i >= n:
            break

        # Parse key
        key_start = i
        while i < n and line[i] not in '=,':
            i += 1
        if i >= n or line[i] != '=':
            raise ValueError("Expected '=' after key")

        key = line[key_start:i].strip()
        if not key:
            raise ValueError("Missing key")
        i += 1  # skip '='

        # Parse value
        if i < n and line[i] == '"':
            i += 1  # skip opening quote
            chars = []
            while i < n:
                ch = line[i]
                if ch == '\\':
                    i += 1
                    if i >= n:
                        raise ValueError("Dangling escape in quoted value")
                    esc = line[i]
                    if esc in {'\\', '"'}:
                        chars.append(esc)
                    else:
                        chars.append(esc)  # preserve unknown escaped char literally
                    i += 1
                elif ch == '"':
                    i += 1  # skip closing quote
                    break
                else:
                    chars.append(ch)
                    i += 1
            else:
                raise ValueError("Unterminated quoted value")

            value = ''.join(chars)

            # After quoted value, only whitespace then comma/end is allowed
            while i < n and line[i].isspace():
                i += 1
            if i < n and line[i] != ',':
                raise ValueError("Trailing characters after quoted value")
        else:
            value_start = i
            while i < n and line[i] != ',':
                i += 1
            value = line[value_start:i].strip()

        result[key] = value

        # Consume comma separator if present
        if i < n:
            if line[i] != ',':
                raise ValueError("Expected ',' between pairs")
            i += 1

    return result


