cart = ShoppingCart(StandardShipping())

print(f"Standard shipping for {weight} kg: ${cart.get_shipping_cost(weight):.2f}")

cart.set_strategy(ExpressShipping())
print(f"Express shipping for {weight} kg: ${cart.get_shipping_cost(weight):.2f}")

cart.set_strategy(OvernightShipping())
print(f"Overnight shipping for {weight} kg: ${cart.get_shipping_cost(weight):.2f}")

def min_path_sum(grid):
    """Return the minimum path sum from top-left to bottom-right."""
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])

    # dp[r][c] stores the minimum cost to reach cell (r, c)
    dp = [[0] * cols for _ in range(rows)]
    dp[0][0] = grid[0][0]

    # Fill the first row
    for c in range(1, cols):
        dp[0][c] = dp[0][c - 1] + grid[0][c]

    # Fill the first column
    for r in range(1, rows):
        dp[r][0] = dp[r - 1][0] + grid[r][0]

    # Fill the rest of the table
    for r in range(1, rows):
        for c in range(1, cols):
            dp[r][c] = min(dp[r - 1][c], dp[r][c - 1]) + grid[r][c]

    return dp[-1][-1]


if __name__ == '__main__':
