print(result)

class ConfigError(Exception):
    """Base class for all configuration-related errors."""


class InvalidConfigError(ConfigError):
    """Raised when a configuration value is present but invalid."""


class MissingKeyError(ConfigError):
    """Raised when a required configuration key is missing."""

    def __init__(self, key):
        self.key = key
        super().__init__(f"Missing required configuration key: '{key}'")


REQUIRED_KEYS = ("host", "port", "debug")


def validate_config(config):
    """Validate a single configuration dictionary.

    Returns the config if valid, otherwise raises a ConfigError subclass.
    """
    if not isinstance(config, dict):
        raise InvalidConfigError("Configuration must be a dictionary")

    for key in REQUIRED_KEYS:
        if key not in config:
            raise MissingKeyError(key)

    host = config["host"]
    port = config["port"]
    debug = config["debug"]

    if not isinstance(host, str) or not host.strip():
        raise InvalidConfigError("'host' must be a non-empty string")

    if not isinstance(port, int) or isinstance(port, bool) or not (1 <= port <= 65535):
        raise InvalidConfigError("'port' must be an integer between 1 and 65535")

    if not isinstance(debug, bool):
        raise InvalidConfigError("'debug' must be a boolean")

    return config


def load_and_validate(configs):
    """Validate a list of configs.

    Returns a tuple: (valid_configs, error_messages)
    """
    valid_configs = []
    error_messages = []

    for index, config in enumerate(configs):
        try:
            valid_configs.append(validate_config(config))
        except ConfigError as exc:
            error_messages.append(f"Config #{index}: {exc}")

    return valid_configs, error_messages


if __name__ == "__main__":
    sample_configs = [
        {"host": "localhost", "port": 8080, "debug": True},
        {"host": "", "port": 8080, "debug": False},
        {"port": 5000, "debug": True},
        {"host": "example.com", "port": 70000, "debug": False},
    ]

    valid, errors = load_and_validate(sample_configs)
    print("Valid configs:", valid)
    print("Errors:")
    for err in errors:
        print("-", err)

