def parse_bool(value: str) -> bool:
    """Convert common environment variable boolean strings to bool."""
    normalized = value.strip().lower()
    if normalized in {"1", "true", "yes", "on"}:
        return True
    if normalized in {"0", "false", "no", "off"}:
        return False
    raise ValueError(f"Invalid boolean value for APP_DEBUG: {value}")


def load_config() -> dict:
    # Defaults used when environment variables are missing
    host = os.getenv("APP_HOST", "127.0.0.1")
    port_raw = os.getenv("APP_PORT", "8000")
    debug_raw = os.getenv("APP_DEBUG", "false")
    timeout_raw = os.getenv("APP_TIMEOUT", "30.0")

    # Convert and validate APP_PORT
    try:
        port = int(port_raw)
    except ValueError as exc:
        raise ValueError(f"APP_PORT must be an integer, got: {port_raw}") from exc
    if not (1 <= port <= 65535):
        raise ValueError(f"APP_PORT must be between 1 and 65535, got: {port}")

    # Convert and validate APP_DEBUG
    debug = parse_bool(debug_raw)

    # Convert and validate APP_TIMEOUT
    try:
        timeout = float(timeout_raw)
    except ValueError as exc:
        raise ValueError(f"APP_TIMEOUT must be a number, got: {timeout_raw}") from exc
    if timeout <= 0:
        raise ValueError(f"APP_TIMEOUT must be positive, got: {timeout}")

    return {
        "host": host,
        "port": port,
        "debug": debug,
        "timeout": timeout,
    }


