def min_palindrome_cuts(s: str) -> int:
    # Empty or single-character strings need no cuts.
    n = len(s)
    if n <= 1:
        return 0

    # is_pal[i][j] will be True if s[i:j+1] is a palindrome.
    is_pal = [[False] * n for _ in range(n)]

    # Fill palindrome table from shorter substrings to longer ones.
    for end in range(n):
        for start in range(end + 1):
            if s[start] == s[end] and (end - start <= 2 or is_pal[start + 1][end - 1]):
                is_pal[start][end] = True

    # dp[i] = minimum cuts needed for s[:i+1]
    dp = [0] * n
    for i in range(n):
        # If the whole prefix is a palindrome, no cut is needed.
        if is_pal[0][i]:
            dp[i] = 0
            continue

        # Otherwise, try every possible last cut position.
        dp[i] = i  # Maximum possible cuts.
        for j in range(1, i + 1):
            if is_pal[j][i]:
                dp[i] = min(dp[i], dp[j - 1] + 1)

    return dp[-1]


