from itertools import islice


def lazy_even_numbers(numbers):
    """Yield only even numbers from the input sequence."""
    for number in numbers:
        if number % 2 == 0:
            yield number


def lazy_squares(numbers):
    """Yield the square of each number lazily."""
    for number in numbers:
        yield number * number


def main():
    numbers = list(range(1, 21))

    # Build a lazy pipeline: filter first, then transform.
    even_numbers = lazy_even_numbers(numbers)
    squared_evens = lazy_squares(even_numbers)

    # Take only the first three results without consuming everything.
    first_three = list(islice(squared_evens, 3))

    print('First three squared even numbers:', first_three)


if __name__ == '__main__':
    main()
}

def parse_log_line(line: str) -> dict:
    # Split on unescaped pipe characters.
    parts = []
    buf = []
    escaped = False
    for ch in line:
        if escaped:
            buf.append(ch)
            escaped = False
        elif ch == '\\':
            buf.append(ch)
            escaped = True
        elif ch == '|':
            parts.append(''.join(buf).strip())
            buf = []
        else:
            buf.append(ch)
    if escaped:
        buf.append('\\')
    parts.append(''.join(buf).strip())

    if len(parts) < 3 or len(parts) > 4:
        raise ValueError('Log line must contain 3 or 4 fields')

    timestamp, level, message = parts[:3]
    metadata_str = parts[3] if len(parts) == 4 else ''

    if not timestamp or not level:
        raise ValueError('Timestamp and level are required')

    # Unescape message pipes and backslashes.
    message = _unescape(message, {'|', '\\'})
    metadata = _parse_metadata(metadata_str) if metadata_str else {}

    return {
        'timestamp': timestamp,
        'level': level,
        'message': message,
        'metadata': metadata,
    }


def _unescape(text: str, escapable: set) -> str:
    result = []
    i = 0
    while i < len(text):
        if text[i] == '\\' and i + 1 < len(text) and text[i + 1] in escapable:
            result.append(text[i + 1])
            i += 2
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)


def _parse_metadata(metadata_str: str) -> dict:
    entries = []
    buf = []
    in_quotes = False
    escape = False

    # Split on unescaped semicolons outside quotes.
    for ch in metadata_str:
        if escape:
            buf.append(ch)
            escape = False
        elif ch == '\\':
            buf.append(ch)
            escape = True
        elif ch == '"':
            buf.append(ch)
            in_quotes = not in_quotes
        elif ch == ';' and not in_quotes:
            entry = ''.join(buf).strip()
            if entry:
                entries.append(entry)
            buf = []
        else:
            buf.append(ch)

    if in_quotes:
        raise ValueError('Unterminated quoted metadata value')
    if escape:
        buf.append('\\')

    tail = ''.join(buf).strip()
    if tail:
        entries.append(tail)

    metadata = {}
    for entry in entries:
        if '=' not in entry:
            raise ValueError(f'Invalid metadata entry: {entry}')
        key, value = entry.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not key:
            raise ValueError(f'Invalid metadata key in entry: {entry}')

        if value.startswith('"'):
            if len(value) < 2 or not value.endswith('"'):
                raise ValueError(f'Unterminated quoted value in entry: {entry}')
            inner = value[1:-1]
            value = _unescape(inner, {'"', ';', '\\'})
        else:
            value = _unescape(value, {';', '\\'})

        metadata[key] = value

    return metadata


# Example usage:
if __name__ == '__main__':
    sample = '2025-01-10T12:00:00Z | INFO | User updated profile\\|settings | user_id=42; note="changed name\\; title"; source=web'
    print(parse_log_line(sample))

import json
import os
from typing import Any, Dict


def _parse_bool(value: str) -> bool:
    """Parse common string representations of booleans."""
    normalized = value.strip().lower()
    if normalized in {"1", "true", "yes", "on"}:
        return True
    if normalized in {"0", "false", "no", "off"}:
        return False
    raise ValueError(f"Invalid boolean value: {value!r}")


def load_app_config(path: str, env_prefix: str = "APP_") -> Dict[str, Any]:
    """Load, validate, and override application configuration."""
    try:
        with open(path, "r", encoding="utf-8") as f:
            config = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in {path}: {e.msg}") from e
    except OSError as e:
        raise ValueError(f"Could not read config file {path}: {e}") from e

    if not isinstance(config, dict):
        raise ValueError("Configuration root must be a JSON object")

    # Apply defaults before validation.
    config.setdefault("debug", False)

    # Apply environment variable overrides.
    env_host = os.getenv(f"{env_prefix}HOST")
    env_port = os.getenv(f"{env_prefix}PORT")
    env_debug = os.getenv(f"{env_prefix}DEBUG")

    if env_host is not None:
        config["host"] = env_host
    if env_port is not None:
        try:
            config["port"] = int(env_port)
        except ValueError as e:
            raise ValueError(f"Invalid integer for {env_prefix}PORT: {env_port!r}") from e
    if env_debug is not None:
        config["debug"] = _parse_bool(env_debug)

    # Validate required keys and types.
    required = {"host": str, "port": int}
    for key, expected_type in required.items():
        if key not in config:
            raise ValueError(f"Missing required configuration key: {key}")
        if not isinstance(config[key], expected_type):
            raise ValueError(
                f"Configuration key {key!r} must be of type {expected_type.__name__}"
            )

    if not isinstance(config["debug"], bool):
        raise ValueError("Configuration key 'debug' must be of type bool")

    return {
        "host": config["host"],
        "port": config["port"],
        "debug": config["debug"],
    }


if __name__ == "__main__":
    # Example usage
    try:
        cfg = load_app_config("config.json")
        print(cfg)
    except ValueError as err:
        print(f"Configuration error: {err}")

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_word = False
        self.prefix_count = 0  # Number of words passing through this node


class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            node.prefix_count += 1
        node.is_word = True

    def search(self, word: str) -> bool:
        node = self._find_node(word)
        return node is not None and node.is_word

    def starts_with(self, prefix: str) -> bool:
        return self._find_node(prefix) is not None

    def count_prefix(self, prefix: str) -> int:
        node = self._find_node(prefix)
        return node.prefix_count if node else 0

    def _find_node(self, text: str):
        node = self.root
        for ch in text:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node


def main():
    words = ["apple", "app", "ape", "bat", "bath", "batman"]
    trie = Trie()

    for word in words:
        trie.insert(word)

    print(trie.search("app"))        # True
    print(trie.search("appl"))       # False
    print(trie.starts_with("ba"))    # True
    print(trie.starts_with("cat"))   # False
    print(trie.count_prefix("ap"))   # 3
    print(trie.count_prefix("bat"))  # 3
    print(trie.count_prefix("z"))    # 0


if __name__ == "__main__":
    main()
}

import requests
from typing import Any, Dict, List, Optional


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url.rstrip('/')
        self.timeout = timeout

    def get(self, path: str, params: Optional[Dict[str, Any]] = None) -> Any:
        """Send a GET request and return parsed JSON data."""
        url = f"{self.base_url}/{path.lstrip('/')}"
        try:
            response = requests.get(url, params=params, timeout=self.timeout)
            response.raise_for_status()
            return response.json()
        except requests.RequestException as exc:
            raise RuntimeError(f"GET request failed for {url}: {exc}") from exc


def fetch_users(client: APIClient, limit: Optional[int] = None) -> List[Dict[str, Any]]:
    users = client.get('/users')
    if not isinstance(users, list):
        raise RuntimeError('Unexpected API response: expected a list of users')
    return users[:limit] if limit is not None else users


def main() -> None:
    client = APIClient('https://jsonplaceholder.typicode.com')

    try:
        users = fetch_users(client, limit=5)
        for user in users:
            print(f"{user['id']}: {user['name']} <{user['email']}>")
    except RuntimeError as err:
        print(f"Error: {err}")


if __name__ == '__main__':
    main()

import hashlib
import os
from pathlib import Path


def _sha256_file(path, chunk_size=65536):
    """Compute SHA-256 for a file without loading it fully into memory."""
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            h.update(chunk)
    return h.hexdigest()


def verify_manifest(base_dir, manifest):
    """
    Validate files under base_dir against a manifest of relative paths -> SHA-256.

    Returns:
        {
            'ok': [...],
            'mismatch': {path: {'expected': ..., 'actual': ...}},
            'missing': [...]
        }
    """
    base = Path(base_dir).resolve()
    result = {'ok': [], 'mismatch': {}, 'missing': []}

    for rel_path, expected_digest in manifest.items():
        rel = Path(rel_path)

        # Disallow absolute paths in the manifest.
        if rel.is_absolute():
            raise ValueError(f'Absolute path not allowed: {rel_path}')

        target = (base / rel).resolve()

        # Ensure the resolved target remains inside base_dir.
        try:
            target.relative_to(base)
        except ValueError:
            raise ValueError(f'Path escapes base_dir: {rel_path}')

        if not target.exists() or not target.is_file():
            result['missing'].append(rel_path)
            continue

        actual_digest = _sha256_file(target)
        if actual_digest == expected_digest.lower():
            result['ok'].append(rel_path)
        else:
            result['mismatch'][rel_path] = {
                'expected': expected_digest.lower(),
                'actual': actual_digest,
            }

    return result


if __name__ == '__main__':
    # Example usage
    manifest = {
        'data/example.txt': 'd2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2d2',
        'missing.bin': '00' * 32,
    }
    print(verify_manifest('.', manifest))

from abc import ABC, abstractmethod
import math


class Shape(ABC):
    """Abstract base class for shapes."""

    @abstractmethod
    def area(self):
        pass


class Rectangle(Shape):
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height


class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return math.pi * self.radius ** 2


