def migrate_users(old_records):
    """Migrate user records from the old schema to the new schema."""
    migrated = []

    for record in old_records:
        # Skip invalid records missing required fields
        if 'id' not in record or 'email' not in record:
            continue

        full_name = record.get('full_name', '').strip()
        first_name = ''
        last_name = ''

        # Split full name into first and last name
        if full_name:
            parts = full_name.split(' ', 1)
            first_name = parts[0]
            last_name = parts[1] if len(parts) > 1 else ''

        new_record = {
            'user_id': record['id'],
            'first_name': first_name,
            'last_name': last_name,
            'email': record['email'].strip().lower(),
            'created_at': record.get('signup_date'),
            'status': 'active' if record.get('active') else 'inactive'
        }

        migrated.append(new_record)

    return migrated


