import re
from typing import Any, Dict


EXPR_RE = re.compile(r"\{\{\s*(.*?)\s*\}\}")
DEFAULT_RE = re.compile(r"^default\((['\"])(.*?)\1\)$")


def resolve_path(context: Dict[str, Any], path: str) -> Any:
    """Resolve a dotted path like 'user.profile.name' in nested dictionaries."""
    value: Any = context
    for part in path.split('.'):
        if isinstance(value, dict) and part in value:
            value = value[part]
        else:
            raise KeyError(path)
    return value


def apply_filter(value: Any, filter_name: str) -> Any:
    """Apply a supported filter to a value."""
    if filter_name == 'upper':
        return str(value).upper()
    if filter_name == 'lower':
        return str(value).lower()
    if filter_name == 'title':
        return str(value).title()
    raise ValueError(f"Unsupported filter: {filter_name}")


def render_template(template: str, context: Dict[str, Any]) -> str:
    """Render placeholders with dotted-path lookup and simple filters."""

    def replace(match: re.Match[str]) -> str:
        expr = match.group(1)
        parts = [p.strip() for p in expr.split('|') if p.strip()]
        if not parts:
            return ''

        path = parts[0]
        filters = parts[1:]
        missing = False

        try:
            value = resolve_path(context, path)
        except KeyError:
            value = None
            missing = True

        for f in filters:
            default_match = DEFAULT_RE.match(f)
            if default_match:
                if missing or value is None:
                    value = default_match.group(2)
                    missing = False
                continue

            if missing:
                raise KeyError(path)
            value = apply_filter(value, f)

        if missing:
            raise KeyError(path)
        return str(value)

    return EXPR_RE.sub(replace, template)


if __name__ == '__main__':
