class PaymentError(Exception):
    """Base class for all payment-related errors."""


class ValidationError(PaymentError):
    """Raised when the request payload is malformed."""


class CurrencyError(ValidationError):
    """Raised when the payment currency is not supported."""


class LimitExceededError(PaymentError):
    """Raised when the payment exceeds the account's daily limit."""


class AccountStateError(PaymentError):
    """Raised when the account state prevents processing."""


SUPPORTED_CURRENCIES = {"USD", "EUR", "GBP"}


def process_payment(request, account_state):
    """Validate and process a payment request.

    Args:
        request: dict with keys amount, currency, destination
        account_state: dict with keys frozen, daily_limit

    Returns:
        dict with approval details

    Raises:
        ValidationError, CurrencyError, LimitExceededError, AccountStateError
    """
    if not isinstance(request, dict):
        raise ValidationError("request must be a dictionary")
    if not isinstance(account_state, dict):
        raise ValidationError("account_state must be a dictionary")

    # Validate account state first because it blocks all processing.
    if account_state.get("frozen") is True:
        raise AccountStateError("account is frozen")

    if "daily_limit" not in account_state:
        raise ValidationError("missing account_state field: daily_limit")

    try:
        daily_limit = float(account_state["daily_limit"])
    except (TypeError, ValueError):
        raise ValidationError("daily_limit must be numeric")

    for field in ("amount", "currency", "destination"):
        if field not in request:
            raise ValidationError(f"missing request field: {field}")

    try:
        amount = float(request["amount"])
    except (TypeError, ValueError):
        raise ValidationError("amount must be numeric")

    if amount <= 0:
        raise ValidationError("amount must be positive")

    currency = request["currency"]
    if not isinstance(currency, str) or not currency.strip():
        raise ValidationError("currency must be a non-empty string")
    currency = currency.strip().upper()
    if currency not in SUPPORTED_CURRENCIES:
        raise CurrencyError(f"unsupported currency: {currency}")

    destination = request["destination"]
    if not isinstance(destination, str) or not destination.strip():
        raise ValidationError("destination must be a non-empty string")

    if amount > daily_limit:
        raise LimitExceededError(
            f"amount {amount:.2f} exceeds daily limit {daily_limit:.2f}"
        )

    return {
        "status": "approved",
        "currency": currency,
        "amount": round(amount, 2),
    }

from typing import List, Dict, Any


def chunk_records(records: List[Dict[str, Any]], batch_size: int) -> List[List[Dict[str, Any]]]:
    """Split records into batches of a fixed size."""
    return [records[i:i + batch_size] for i in range(0, len(records), batch_size)]


def is_valid_record(record: Dict[str, Any]) -> bool:
    """Check whether a record contains all required fields."""
    required_keys = {"timestamp", "level", "message"}
    return required_keys.issubset(record.keys())


def transform_record(record: Dict[str, Any]) -> Dict[str, Any]:
    """Normalize a valid log record."""
    return {
        "timestamp": record["timestamp"],
        "level": str(record["level"]).upper(),
        "message": str(record["message"]).strip(),
    }


def process_pipeline(records: List[Dict[str, Any]], batch_size: int) -> Dict[str, Any]:
    """Validate, transform, and batch log records."""
    valid_count = 0
    invalid_count = 0
    processed_records = []

    for record in records:
        if is_valid_record(record):
            processed_records.append(transform_record(record))
            valid_count += 1
        else:
            invalid_count += 1

    batches = chunk_records(processed_records, batch_size)

    return {
        "batches": batches,
        "valid_records": valid_count,
        "invalid_records": invalid_count,
    }


