class PositiveNumber:
    """Descriptor that ensures assigned values are positive numbers."""

    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, (int, float)):
            raise ValueError(f"{self.private_name[1:]} must be a number")
        if value <= 0:
            raise ValueError(f"{self.private_name[1:]} must be greater than zero")
        setattr(instance, self.private_name, float(value))


class Product:
    price = PositiveNumber()
    weight = PositiveNumber()

    def __init__(self, name, price, weight, discount_percent=0):
        self.name = name
        self.price = price
        self.weight = weight
        self.discount_percent = discount_percent

    @property
    def discount_percent(self):
        return self._discount_percent

    @discount_percent.setter
    def discount_percent(self, value):
        if not isinstance(value, (int, float)):
            raise ValueError("discount_percent must be a number")
        if not 0 <= value <= 100:
            raise ValueError("discount_percent must be between 0 and 100")
        self._discount_percent = float(value)

    @property
    def final_price(self):
        return self.price * (1 - self.discount_percent / 100)


# Example usage
