def repeat_message(times):
    # Closure: 'times' is remembered by the decorator
    def decorator(func):
        def wrapper(*args, **kwargs):
            results = []
            for _ in range(times):
                results.append(func(*args, **kwargs))
            return results
        return wrapper
    return decorator


@repeat_message(3)
def greet(name):
    return f"Hello, {name}!"


def main():
    messages = greet("Alice")
    for message in messages:
        print(message)


