class TextDocument:
    def __init__(self):
        self.text = ""

    def append(self, value):
        self.text += value

    def delete_last(self, count):
        removed = self.text[-count:] if count <= len(self.text) else self.text
        self.text = self.text[:-count] if count <= len(self.text) else ""
        return removed


class Command:
    def execute(self):
        raise NotImplementedError

    def undo(self):
        raise NotImplementedError


class AddTextCommand(Command):
    def __init__(self, document, text):
        self.document = document
        self.text = text

    def execute(self):
        self.document.append(self.text)

    def undo(self):
        self.document.delete_last(len(self.text))


class DeleteTextCommand(Command):
    def __init__(self, document, count):
        self.document = document
        self.count = count
        self.deleted_text = ""

    def execute(self):
        self.deleted_text = self.document.delete_last(self.count)

    def undo(self):
        self.document.append(self.deleted_text)


class Editor:
    def __init__(self):
        self.history = []

    def run_command(self, command):
        command.execute()
        self.history.append(command)

    def undo_last(self):
        if self.history:
            command = self.history.pop()
            command.undo()


# Demo
if __name__ == "__main__":
    document = TextDocument()
    editor = Editor()

    editor.run_command(AddTextCommand(document, "Hello"))
    print(document.text)  # Hello

    editor.run_command(AddTextCommand(document, " World"))
    print(document.text)  # Hello World

    editor.run_command(DeleteTextCommand(document, 6))
    print(document.text)  # Hello

    editor.undo_last()
    print(document.text)  # Hello World

    editor.undo_last()
    print(document.text)  # Hello

import json
import os
import re
from collections import Counter
from datetime import datetime

LOG_FILE = 'app.log'
REPORT_FILE = 'report.json'
LOG_PATTERN = re.compile(r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) \| ([A-Z]+) \| (.*)$')


def build_report(log_path):
    level_counts = Counter()
    error_messages = []
    earliest = None
    latest = None

    if not os.path.exists(log_path):
        return {
            'level_counts': {},
            'earliest_timestamp': None,
            'latest_timestamp': None,
            'error_messages': []
        }

    with open(log_path, 'r', encoding='utf-8') as f:
        for raw_line in f:
            line = raw_line.rstrip('\n')
            match = LOG_PATTERN.match(line)
            if not match:
                continue  # Ignore malformed lines

            timestamp_str, level, message = match.groups()
            try:
                timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
            except ValueError:
                continue  # Ignore invalid timestamps

            level_counts[level] += 1
            if level == 'ERROR':
                error_messages.append(message)

            if earliest is None or timestamp < earliest:
                earliest = timestamp
            if latest is None or timestamp > latest:
                latest = timestamp

    return {
        'level_counts': dict(level_counts),
        'earliest_timestamp': earliest.strftime('%Y-%m-%d %H:%M:%S') if earliest else None,
        'latest_timestamp': latest.strftime('%Y-%m-%d %H:%M:%S') if latest else None,
        'error_messages': error_messages
    }


def main():
    report = build_report(LOG_FILE)
    with open(REPORT_FILE, 'w', encoding='utf-8') as f:
        json.dump(report, f, indent=2)


if __name__ == '__main__':
    main()

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size

    def find(self, x):
        # Path compression
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)

        if root_a == root_b:
            return False

        # Union by rank
        if self.rank[root_a] < self.rank[root_b]:
            self.parent[root_a] = root_b
        elif self.rank[root_a] > self.rank[root_b]:
            self.parent[root_b] = root_a
        else:
            self.parent[root_b] = root_a
            self.rank[root_a] += 1

        return True


def count_friend_groups(n, friendships):
    uf = UnionFind(n)

    for a, b in friendships:
        uf.union(a, b)

    # Count unique roots
    groups = set()
    for person in range(n):
        groups.add(uf.find(person))

    return len(groups)


# Example usage
