    n = 6
    friendships = [(0, 1), (1, 2), (3, 4)]
    print(count_friend_groups(n, friendships))  # Output: 3

from __future__ import annotations

import hashlib
from pathlib import Path
from typing import Dict, List


def _sha256_file(path: Path, chunk_size: int = 65536) -> str:
    """Compute SHA-256 for a file by streaming it in chunks."""
    h = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            h.update(chunk)
    return h.hexdigest()


def _resolve_safe(base_dir: Path, rel_path: str) -> Path:
    """Resolve a manifest path and ensure it stays within base_dir."""
    rel = Path(rel_path)
    if rel.is_absolute():
        raise ValueError(f"Absolute paths are not allowed: {rel_path}")

    base_resolved = base_dir.resolve()
    candidate = (base_resolved / rel).resolve(strict=False)

    try:
        candidate.relative_to(base_resolved)
    except ValueError:
        raise ValueError(f"Path escapes base directory: {rel_path}") from None

    return candidate


def verify_manifest(base_dir: str, manifest: Dict[str, str]) -> Dict[str, List[str]]:
    """
    Validate files listed in manifest against expected SHA-256 digests.

    Returns:
        {
            'ok': [...],
            'modified': [...],
            'missing': [...]
        }
    """
    base = Path(base_dir)
    result = {
        'ok': [],
        'modified': [],
        'missing': [],
    }

    for rel_path, expected_digest in manifest.items():
        file_path = _resolve_safe(base, rel_path)

        if not file_path.is_file():
            result['missing'].append(rel_path)
            continue

        actual_digest = _sha256_file(file_path)
        if actual_digest.lower() == expected_digest.lower():
            result['ok'].append(rel_path)
        else:
            result['modified'].append(rel_path)

    for key in result:
        result[key].sort()

    return result


