import re
from dataclasses import dataclass, field
from typing import Callable, Dict, List, Pattern, Tuple, Any


TYPE_PATTERNS = {
    'int': (r'\\d+', int),
    'str': (r'[^/]+', str),
    'path': (r'.+', str),
    'slug': (r'[A-Za-z0-9_-]+', str),
}


@dataclass(order=True)
class Route:
    # Lower sort_index means higher priority during dispatch
    sort_index: Tuple[int, int] = field(init=False, repr=False)
    method: str
    pattern: str
    handler: Callable[..., Any]
    regex: Pattern = field(init=False, repr=False)
    converters: Dict[str, Callable[[str], Any]] = field(init=False, repr=False)

    def __post_init__(self):
        self.method = self.method.upper()
        self.regex, self.converters, static_count, param_count = self._compile_pattern(self.pattern)
        # More static segments first, fewer params first
        self.sort_index = (-static_count, param_count)

    def _compile_pattern(self, pattern: str):
        parts = [p for p in pattern.strip('/').split('/') if p]
        converters = {}
        regex_parts = []
        static_count = 0
        param_count = 0

        for part in parts:
            if part.startswith('<') and part.endswith('>'):
                inner = part[1:-1]
                if ':' in inner:
                    type_name, name = inner.split(':', 1)
                else:
                    type_name, name = 'str', inner

                if type_name not in TYPE_PATTERNS:
                    raise ValueError(f'Unsupported parameter type: {type_name}')

                pattern_text, converter = TYPE_PATTERNS[type_name]
                regex_parts.append(f'(?P<{name}>{pattern_text})')
                converters[name] = converter
                param_count += 1
            else:
                regex_parts.append(re.escape(part))
                static_count += 1

        regex = re.compile(r'^/' + '/'.join(regex_parts) + r'/?$')
        return regex, converters, static_count, param_count

    def match(self, path: str):
        match = self.regex.match(path)
        if not match:
            return None
        params = {
            name: self.converters[name](value)
            for name, value in match.groupdict().items()
        }
        return params


class Router:
    def __init__(self):
        self._routes: List[Route] = []

    def add_route(self, method: str, pattern: str, handler: Callable[..., Any]):
        route = Route(method=method, pattern=pattern, handler=handler)
        self._routes.append(route)
        self._routes.sort()

    def dispatch(self, method: str, path: str):
        method = method.upper()
        for route in self._routes:
            if route.method != method:
                continue
            params = route.match(path)
            if params is not None:
                return route.handler(**params), params
        raise LookupError(f'No route for {method} {path}')


# Example usage
if __name__ == '__main__':
    router = Router()
    router.add_route('GET', '/users/<int:id>', lambda id: f'user:{id}')
    router.add_route('GET', '/files/<path:rest>', lambda rest: f'file:{rest}')
    router.add_route('GET', '/posts/<slug>', lambda slug: f'post:{slug}')
    router.add_route('GET', '/posts/archive', lambda: 'archive')

    print(router.dispatch('GET', '/users/42'))         # ('user:42', {'id': 42})
    print(router.dispatch('GET', '/files/a/b/c.txt')) # ('file:a/b/c.txt', {'rest': 'a/b/c.txt'})
    print(router.dispatch('GET', '/posts/hello-1'))   # ('post:hello-1', {'slug': 'hello-1'})
    print(router.dispatch('GET', '/posts/archive'))   # ('archive', {})

import random


def random_individual(length=5):
    """Create a random binary string."""
    return ''.join(random.choice('01') for _ in range(length))


def fitness(individual):
    """Fitness is x^2, where x is the integer value of the binary string."""
    x = int(individual, 2)
    return x * x


def mutate(individual, mutation_rate=0.1):
    """Flip each bit with a small probability."""
    bits = []
    for bit in individual:
        if random.random() < mutation_rate:
            bits.append('1' if bit == '0' else '0')
        else:
            bits.append(bit)
    return ''.join(bits)


def crossover(parent1, parent2):
    """Single-point crossover between two parents."""
    point = random.randint(1, len(parent1) - 1)
    child1 = parent1[:point] + parent2[point:]
    child2 = parent2[:point] + parent1[point:]
    return child1, child2


def genetic_algorithm(pop_size=10, generations=20, bit_length=5):
    # Create initial population
    population = [random_individual(bit_length) for _ in range(pop_size)]

    for _ in range(generations):
        # Sort population by fitness (highest first)
        population.sort(key=fitness, reverse=True)

        # Select the top half as parents
        parents = population[:pop_size // 2]

        # Create next generation starting with the best parents
        next_population = parents[:]

        # Generate children until population is full again
        while len(next_population) < pop_size:
            parent1, parent2 = random.sample(parents, 2)
            child1, child2 = crossover(parent1, parent2)
            next_population.append(mutate(child1))
            if len(next_population) < pop_size:
                next_population.append(mutate(child2))

        population = next_population

    # Return the best individual found
    best = max(population, key=fitness)
    return best, int(best, 2), fitness(best)


if __name__ == '__main__':
    best_binary, best_value, best_fitness = genetic_algorithm()
    print('Best binary string:', best_binary)
    print('Integer value:', best_value)
    print('Fitness:', best_fitness)

class TrafficLight:
    # State transitions for normal timer events
    TIMER_TRANSITIONS = {
        'RED': 'GREEN',
        'GREEN': 'YELLOW',
        'YELLOW': 'RED'
    }

    def __init__(self):
        self.state = 'RED'

    def handle_event(self, event):
        """Apply a single event and return the new state."""
        if event == 'timer':
            self.state = self.TIMER_TRANSITIONS[self.state]
        elif event == 'emergency':
            self.state = 'RED'
        else:
            raise ValueError(f'Unknown event: {event}')
        return self.state

    def process_events(self, events):
        """Process a list of events and return states after each event."""
        states = []
        for event in events:
            states.append(self.handle_event(event))
        return states


