import heapq
import sys


def main():
    input = sys.stdin.readline
    n = int(input().strip())
    heap = []

    for _ in range(n):
        parts = input().strip().split()
        if not parts:
            continue

        command = parts[0]

        if command == 'ADD':
            task_name = parts[1]
            priority = int(parts[2])
            # Push as (priority, task_name) so the smallest priority comes first
            heapq.heappush(heap, (priority, task_name))

        elif command == 'POP':
            if heap:
                priority, task_name = heapq.heappop(heap)
                print(task_name)
            else:
                print('EMPTY')

        elif command == 'PEEK':
            if heap:
                priority, task_name = heap[0]
                print(task_name)
            else:
                print('EMPTY')


if __name__ == '__main__':
    main()

