REQUIRED_FIELDS = ("patient_id", "medication_name", "dosage", "start_date")


def _is_non_string_iterable(value: Any) -> bool:
    return isinstance(value, (list, tuple))


def _parse_date(date_value: Any) -> Tuple[bool, str]:
    if not isinstance(date_value, str):
        return False, "start_date must be a string in YYYY-MM-DD format"
    try:
        parsed = datetime.strptime(date_value, "%Y-%m-%d")
        return True, parsed.strftime("%Y-%m-%d")
    except ValueError:
        return False, "start_date must use YYYY-MM-DD format"


def _normalize_string(value: Any) -> Any:
    if isinstance(value, str):
        normalized = value.strip()
        return normalized
    return value


def validate_and_normalize_medication_records(
    entries: Any,
) -> Dict[str, List[Dict[str, Any]]]:
    result: Dict[str, List[Dict[str, Any]]] = {
        "valid_records": [],
        "errors": [],
    }

    if entries is None:
        result["errors"].append(
            {
                "index": None,
                "message": "Payload is required and must be a list of medication records",
            }
        )
        return result

    if not _is_non_string_iterable(entries):
        result["errors"].append(
            {
                "index": None,
                "message": "Payload must be a list of medication records",
            }
        )
        return result

    if len(entries) == 0:
        result["errors"].append(
            {
                "index": None,
                "message": "Payload is empty",
            }
        )
        return result

    seen_keys = set()

    for index, entry in enumerate(entries):
        entry_errors: List[str] = []

