            elif not isinstance(patient_id, int):
                entry_errors.append("patient_id must be a non-empty string or integer")

        if "medication_name" in normalized_entry:
            if not isinstance(medication_name, str):
                entry_errors.append("medication_name must be a string")
            elif not medication_name:
                entry_errors.append("medication_name must not be empty")

