        normalized_start_date = None
        if "start_date" in normalized_entry:
            is_valid_date, date_result = _parse_date(start_date)
            if not is_valid_date:
                entry_errors.append(date_result)
            else:
                normalized_start_date = date_result

        if not entry_errors and normalized_start_date is not None:
            duplicate_key = (
                str(patient_id).strip().lower() if isinstance(patient_id, str) else patient_id,
                medication_name.strip().lower(),
                normalized_start_date,
            )
            if duplicate_key in seen_keys:
                entry_errors.append(
                    "Duplicate medication for the same patient and start_date"
                )
            else:
                seen_keys.add(duplicate_key)

        if entry_errors:
            result["errors"].append(
                {
                    "index": index,
                    "message": "; ".join(entry_errors),
                    "entry": entry,
                }
            )
            continue

        valid_record = dict(normalized_entry)
        valid_record["start_date"] = normalized_start_date
        result["valid_records"].append(valid_record)

    return result


@app.route("/validate-medications", methods=["POST"])
def validate_medications_endpoint():
    payload = request.get_json(silent=True)

    if payload is None:
        return (
            jsonify(
                {
                    "valid_records": [],
                    "errors": [
                        {
                            "index": None,
                            "message": "Request body must contain valid JSON",
                        }
                    ],
                }
            ),
            400,
        )

    entries = payload.get("medications") if isinstance(payload, dict) else payload
    result = validate_and_normalize_medication_records(entries)

    status_code = 200 if result["valid_records"] else 400
    return jsonify(result), status_code


