def chunk_list(items, batch_size):
    """Split a list into batches of a fixed size."""
    for i in range(0, len(items), batch_size):
        yield items[i:i + batch_size]


def process_order(order):
    """Validate and process a single order."""
    if order['quantity'] <= 0 or order['price'] < 0:
        return None

    return {
        'order_id': order['id'],
        'total_cost': order['quantity'] * order['price']
    }


def main():
    orders = [
        {'id': 1, 'quantity': 2, 'price': 10.0},
        {'id': 2, 'quantity': 0, 'price': 5.0},
        {'id': 3, 'quantity': 1, 'price': 7.5},
        {'id': 4, 'quantity': 3, 'price': -2.0},
        {'id': 5, 'quantity': 4, 'price': 6.25},
        {'id': 6, 'quantity': 2, 'price': 8.0}
    ]

    batch_size = 3
    successful = 0
    failed = 0
    processed_results = []

    for batch_number, batch in enumerate(chunk_list(orders, batch_size), start=1):
        print(f'Processing batch {batch_number}: {batch}')

        for order in batch:
            result = process_order(order)
            if result is None:
                failed += 1
            else:
                successful += 1
                processed_results.append(result)

    print('\nProcessed results:')
    for result in processed_results:
        print(result)

    print(f'\nSummary: {successful} successful, {failed} failed')


if __name__ == '__main__':
    main()
