import hashlib


class BloomFilter:
    def __init__(self, size: int, hash_count: int):
        if size <= 0 or hash_count <= 0:
            raise ValueError('size and hash_count must be positive integers')
        self.size = size
        self.hash_count = hash_count
        self.bits = [0] * size

    def _hashes(self, item: str):
        data = item.encode('utf-8')
        # Double hashing to derive multiple hash values efficiently.
        h1 = int(hashlib.sha256(data).hexdigest(), 16)
        h2 = int(hashlib.md5(data).hexdigest(), 16)
        for i in range(self.hash_count):
            yield (h1 + i * h2) % self.size

    def add(self, item: str) -> None:
        for index in self._hashes(item):
            self.bits[index] = 1

    def might_contain(self, item: str) -> bool:
        return all(self.bits[index] for index in self._hashes(item))


if __name__ == '__main__':
    bloom = BloomFilter(size=100, hash_count=3)

    inserted_words = ['apple', 'banana', 'cherry', 'date']
    for word in inserted_words:
        bloom.add(word)

    test_words = ['apple', 'banana', 'grape', 'kiwi', 'cherry', 'melon']
    for word in test_words:
        result = bloom.might_contain(word)
        print(f'{word}: {result}')

from __future__ import annotations

from dataclasses import dataclass, field
from typing import List, Tuple


@dataclass(frozen=True)
class Event:
    title: str
    start_hour: int
    duration_hours: int
    tags: Tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if not 0 <= self.start_hour <= 23:
            raise ValueError("start_hour must be between 0 and 23")
        if self.duration_hours <= 0:
            raise ValueError("duration_hours must be positive")
        if self.start_hour + self.duration_hours > 24:
            raise ValueError("event must end within the same day")

    @property
    def end_hour(self) -> int:
        return self.start_hour + self.duration_hours


@dataclass
class Schedule:
    events: List[Event] = field(default_factory=list)

    def add_event(self, event: Event) -> None:
        self.events.append(event)

    def total_scheduled_hours(self) -> int:
        return sum(event.duration_hours for event in self.events)

    def events_by_tag(self, tag: str) -> List[Event]:
        return [event for event in self.events if tag in event.tags]

    def has_overlaps(self) -> bool:
        # Sort by start time to check only neighboring intervals.
        ordered = sorted(self.events, key=lambda event: event.start_hour)
        for previous, current in zip(ordered, ordered[1:]):
            if current.start_hour < previous.end_hour:
                return True
        return False


if __name__ == "__main__":
    schedule = Schedule()
    schedule.add_event(Event("Planning", 9, 2, ("work", "team")))
    schedule.add_event(Event("Lunch", 12, 1, ("personal",)))
    schedule.add_event(Event("Code Review", 13, 2, ("work",)))

    print("Total hours:", schedule.total_scheduled_hours())
    print("Work events:", [event.title for event in schedule.events_by_tag("work")])
    print("Has overlaps:", schedule.has_overlaps())

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False


class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        """Insert a word into the trie."""
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end = True

    def search(self, word):
        """Return True if the exact word exists in the trie."""
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end

    def starts_with(self, prefix):
        """Return True if any word in the trie starts with the prefix."""
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True


def main():
    trie = Trie()

    # Insert sample words
    for word in ["cat", "car", "care", "dog"]:
        trie.insert(word)

    # Exact word searches
    print(trie.search("cat"))   # True
    print(trie.search("cap"))   # False
    print(trie.search("care"))  # True
    print(trie.search("ca"))    # False

    # Prefix checks
    print(trie.starts_with("ca"))   # True
    print(trie.starts_with("car"))  # True
    print(trie.starts_with("do"))   # True
    print(trie.starts_with("z"))    # False


if __name__ == "__main__":
    main()

import time
from typing import Callable, Dict, Any, List

Request = Dict[str, Any]
Response = Dict[str, Any]
Middleware = Callable[[Request, Callable[[Request], Response]], Response]


class Pipeline:
    def __init__(self) -> None:
        self._middleware: List[Middleware] = []

    def add(self, middleware: Middleware) -> None:
        self._middleware.append(middleware)

    def execute(self, request: Request, handler: Callable[[Request], Response]) -> Response:
        def build_chain(index: int) -> Callable[[Request], Response]:
            if index == len(self._middleware):
                return handler

            def current(req: Request) -> Response:
                return self._middleware[index](req, build_chain(index + 1))

            return current

        return build_chain(0)(request)


def logging_middleware(request: Request, next_handler: Callable[[Request], Response]) -> Response:
    request.setdefault("log", []).append("before_logging")
    response = next_handler(request)
    response.setdefault("log", []).append("after_logging")
    return response


def timing_middleware(request: Request, next_handler: Callable[[Request], Response]) -> Response:
    start = time.perf_counter()
    response = next_handler(request)
    response["duration_ms"] = round((time.perf_counter() - start) * 1000, 3)
    return response


def auth_middleware(request: Request, next_handler: Callable[[Request], Response]) -> Response:
    if request.get("token") != "secret-token":
        return {
            "status": 401,
            "error": "Unauthorized",
            "log": request.get("log", []) + ["auth_failed"],
        }
    request.setdefault("log", []).append("auth_passed")
    return next_handler(request)


def transform_middleware(request: Request, next_handler: Callable[[Request], Response]) -> Response:
    if "data" in request and isinstance(request["data"], str):
        request["data"] = request["data"].strip().upper()
    request.setdefault("log", []).append("transformed")
    return next_handler(request)


def final_handler(request: Request) -> Response:
    return {
        "status": 200,
        "result": f"Processed: {request.get('data', '')}",
        "log": request.get("log", []) + ["handled"],
    }


if __name__ == "__main__":
    pipeline = Pipeline()
    pipeline.add(logging_middleware)
    pipeline.add(timing_middleware)
    pipeline.add(auth_middleware)
    pipeline.add(transform_middleware)

    authorized_request = {"token": "secret-token", "data": "  middleware pipeline  "}
    unauthorized_request = {"token": "bad-token", "data": "should not process"}

    print(pipeline.execute(authorized_request, final_handler))
    print(pipeline.execute(unauthorized_request, final_handler))

class StreamParser:
    # Parser states
    READ_TYPE = 'READ_TYPE'
    READ_LENGTH = 'READ_LENGTH'
    READ_PAYLOAD = 'READ_PAYLOAD'
    EXPECT_END = 'EXPECT_END'
    ERROR = 'ERROR'

    def __init__(self):
        self.reset()

    def reset(self):
        self.state = self.READ_TYPE
        self.type_buf = ''
        self.length_buf = ''
        self.payload_buf = ''
        self.expected_length = 0

    def _enter_error(self):
        self.state = self.ERROR

    def feed(self, text):
        messages = []

        for ch in text:
            if self.state == self.ERROR:
                # Discard until message terminator, then reset.
                if ch == '#':
                    self.reset()
                continue

            if self.state == self.READ_TYPE:
                if ch == '|':
                    if self.type_buf not in ('CMD', 'DATA'):
                        self._enter_error()
                    else:
                        self.state = self.READ_LENGTH
                elif ch.isalpha():
                    self.type_buf += ch
                else:
                    self._enter_error()

            elif self.state == self.READ_LENGTH:
                if ch == '|':
                    if not self.length_buf or not self.length_buf.isdigit() or int(self.length_buf) <= 0:
                        self._enter_error()
                    else:
                        self.expected_length = int(self.length_buf)
                        self.state = self.READ_PAYLOAD
                elif ch.isdigit():
                    self.length_buf += ch
                else:
                    self._enter_error()

            elif self.state == self.READ_PAYLOAD:
                self.payload_buf += ch
                if len(self.payload_buf) == self.expected_length:
                    self.state = self.EXPECT_END
                elif len(self.payload_buf) > self.expected_length:
                    self._enter_error()

            elif self.state == self.EXPECT_END:
                if ch == '#':
                    messages.append({
                        'type': self.type_buf,
                        'payload': self.payload_buf
                    })
                    self.reset()
                else:
                    self._enter_error()

        return messages


# Example usage
if __name__ == '__main__':
    parser = StreamParser()
    chunks = [
        'CMD|5|hello#DATA|4|test#',
        'CMD|3|ab',
        'c#BAD|2|xx#DATA|6|python#'
    ]

    for chunk in chunks:
        for msg in parser.feed(chunk):
            print(msg)

from __future__ import annotations

from datetime import date, datetime
from typing import Any, Dict, List, Optional, Set


class EHRVisitManager:
    REQUIRED_FIELDS = ("patient_id", "visit_date", "vital_signs")
    REQUIRED_VITALS = ("systolic_bp", "diastolic_bp")

    def __init__(self) -> None:
        self.records: List[Dict[str, Any]] = []

    def _parse_date(self, value: Any) -> date:
        if isinstance(value, date) and not isinstance(value, datetime):
            return value
        if isinstance(value, datetime):
            return value.date()
        if isinstance(value, str):
            try:
                return datetime.strptime(value, "%Y-%m-%d").date()
            except ValueError as exc:
                raise ValueError("visit_date must be in YYYY-MM-DD format") from exc
        raise ValueError("visit_date must be a date, datetime, or YYYY-MM-DD string")

    def _validate_visit(self, visit: Dict[str, Any]) -> Dict[str, Any]:
        for field in self.REQUIRED_FIELDS:
            if field not in visit or visit[field] in (None, ""):
                raise ValueError(f"Missing required field: {field}")

        patient_id = str(visit["patient_id"]).strip()
        if not patient_id:
            raise ValueError("Missing required field: patient_id")

        visit_date = self._parse_date(visit["visit_date"])

        vital_signs = visit["vital_signs"]
        if not isinstance(vital_signs, dict):
            raise ValueError("vital_signs must be a dictionary")

        for vital in self.REQUIRED_VITALS:
            if vital not in vital_signs or vital_signs[vital] in (None, ""):
                raise ValueError(f"Missing required vital sign value: {vital}")

        try:
            systolic_bp = float(vital_signs["systolic_bp"])
            diastolic_bp = float(vital_signs["diastolic_bp"])
        except (TypeError, ValueError) as exc:
            raise ValueError("Vital sign values must be numeric") from exc

        diagnosis_codes = visit.get("diagnosis_codes", [])
        if diagnosis_codes is None:
            diagnosis_codes = []
        if not isinstance(diagnosis_codes, list):
            raise ValueError("diagnosis_codes must be a list")

        return {
            "patient_id": patient_id,
            "visit_date": visit_date,
            "vital_signs": {
                **vital_signs,
                "systolic_bp": systolic_bp,
                "diastolic_bp": diastolic_bp,
            },
            "diagnosis_codes": diagnosis_codes,
            "notes": visit.get("notes", ""),
        }

    def add_visit(self, visit: Dict[str, Any]) -> None:
        validated_visit = self._validate_visit(visit)
        self.records.append(validated_visit)

    def filter_visits_by_date_range(
        self, start_date: Any, end_date: Any
    ) -> List[Dict[str, Any]]:
        start = self._parse_date(start_date)
        end = self._parse_date(end_date)
        if start > end:
            raise ValueError("start_date cannot be after end_date")

        return [
            record
            for record in self.records
            if start <= record["visit_date"] <= end
        ]

    def identify_high_bp_patients(
        self,
        systolic_threshold: float = 140,
        diastolic_threshold: float = 90,
        visits: Optional[List[Dict[str, Any]]] = None,
    ) -> List[Dict[str, Any]]:
        source = visits if visits is not None else self.records
        return [
            record
            for record in source
            if record["vital_signs"]["systolic_bp"] > systolic_threshold
            or record["vital_signs"]["diastolic_bp"] > diastolic_threshold
        ]

    def collect_unique_diagnosis_codes(
        self, visits: Optional[List[Dict[str, Any]]] = None
    ) -> List[str]:
        source = visits if visits is not None else self.records
        unique_codes: Set[str] = {
            str(code).strip()
            for record in source
            for code in record.get("diagnosis_codes", [])
            if str(code).strip()
        }
        return sorted(unique_codes)

    def generate_abnormal_vitals_report(
        self,
        start_date: Optional[Any] = None,
        end_date: Optional[Any] = None,
        systolic_threshold: float = 140,
        diastolic_threshold: float = 90,
    ) -> Dict[str, Any]:
        visits = self.records

        if start_date is not None and end_date is not None:
            visits = self.filter_visits_by_date_range(start_date, end_date)
            report_start = self._parse_date(start_date).isoformat()
            report_end = self._parse_date(end_date).isoformat()
        elif start_date is None and end_date is None:
            report_start = None
            report_end = None
        else:
            raise ValueError("Both start_date and end_date must be provided together")

        abnormal_visits = self.identify_high_bp_patients(
            systolic_threshold=systolic_threshold,
            diastolic_threshold=diastolic_threshold,
            visits=visits,
        )

        unique_patients = sorted({visit["patient_id"] for visit in abnormal_visits})
        diagnosis_codes = self.collect_unique_diagnosis_codes(abnormal_visits)

        patient_summaries = [
            {
                "patient_id": visit["patient_id"],
                "visit_date": visit["visit_date"].isoformat(),
                "systolic_bp": visit["vital_signs"]["systolic_bp"],
                "diastolic_bp": visit["vital_signs"]["diastolic_bp"],
                "diagnosis_codes": visit.get("diagnosis_codes", []),
            }
            for visit in abnormal_visits
        ]

        return {
            "report_parameters": {
                "start_date": report_start,
                "end_date": report_end,
                "systolic_threshold": systolic_threshold,
                "diastolic_threshold": diastolic_threshold,
            },
            "summary": {
                "total_visits_evaluated": len(visits),
                "abnormal_visit_count": len(abnormal_visits),
                "unique_patient_count": len(unique_patients),
                "unique_diagnosis_codes": diagnosis_codes,
            },
            "patients_with_abnormal_vitals": patient_summaries,
        }


