import os
import time
from collections import Counter


def classify_line(line: str) -> str | None:
    """Return the log level found in a line, if any."""
    for level in ("ERROR", "WARNING", "INFO"):
        if level in line:
            return level
    return None


def monitor_log(file_path: str, iterations: int = 10, interval: float = 1.0, error_threshold: int = 3) -> None:
    """Monitor newly appended log lines and print summary metrics."""
    counts = Counter({"INFO": 0, "WARNING": 0, "ERROR": 0})

    # Start at the end of the file so we only process new lines.
    with open(file_path, "r", encoding="utf-8") as log_file:
        log_file.seek(0, os.SEEK_END)

        for i in range(1, iterations + 1):
            new_lines = log_file.readlines()

            for line in new_lines:
                level = classify_line(line)
                if level:
                    counts[level] += 1

            print(
                f"Check {i}: INFO={counts['INFO']} "
                f"WARNING={counts['WARNING']} ERROR={counts['ERROR']}"
            )

            if counts["ERROR"] >= error_threshold:
                print(f"ALERT: error threshold reached ({counts['ERROR']} >= {error_threshold})")

            time.sleep(interval)


def ensure_log_file_exists(file_path: str) -> None:
    """Create the log file if it does not already exist."""
    if not os.path.exists(file_path):
        with open(file_path, "w", encoding="utf-8"):
            pass


if __name__ == "__main__":
    log_path = "application.log"
    ensure_log_file_exists(log_path)
    monitor_log(log_path, iterations=8, interval=1.0, error_threshold=2)

class Stack:
    def __init__(self):
        self.items = []

    def push(self, value):
        self.items.append(value)

    def pop(self):
        if not self.items:
            return 'Stack is empty'
        return self.items.pop()

    def display(self):
        return self.items


class Queue:
    def __init__(self):
        self.items = []

    def enqueue(self, value):
        self.items.append(value)

    def dequeue(self):
        if not self.items:
            return 'Queue is empty'
        return self.items.pop(0)

    def display(self):
        return self.items


