from collections import defaultdict
from typing import Callable, Dict, List


class EventBus:
    """Simple pub/sub event bus for named topics."""

    def __init__(self):
        self._subscribers: Dict[str, List[Callable]] = defaultdict(list)

    def subscribe(self, topic: str, callback: Callable) -> None:
        """Register a callback for a topic."""
        if callback not in self._subscribers[topic]:
            self._subscribers[topic].append(callback)

    def unsubscribe(self, topic: str, callback: Callable) -> None:
        """Remove a callback from a topic if present."""
        if callback in self._subscribers[topic]:
            self._subscribers[topic].remove(callback)

    def publish(self, topic: str, data: dict) -> None:
        """Notify all subscribers of a topic."""
        for callback in list(self._subscribers[topic]):
            callback(data)


class ChatRoom:
    """Publishes chat messages through the event bus."""

    def __init__(self, bus: EventBus):
        self.bus = bus

    def send_message(self, sender: str, text: str) -> None:
        event = {"sender": sender, "text": text}
        self.bus.publish("message", event)


def print_listener(event: dict) -> None:
    print(f"[Printer] {event['sender']}: {event['text']}")


def log_listener(event: dict) -> None:
    print(f"[Logger] Stored message from {event['sender']}")


if __name__ == "__main__":
    bus = EventBus()
    room = ChatRoom(bus)

    # Register observers/subscribers
    bus.subscribe("message", print_listener)
    bus.subscribe("message", log_listener)

    # Publish a few events
    room.send_message("Alice", "Hello everyone!")
    room.send_message("Bob", "Hi Alice!")

    # Unsubscribe one listener
    bus.unsubscribe("message", log_listener)
    print("-- Logger unsubscribed --")

    # Only the print listener should receive this
    room.send_message("Charlie", "Is anyone here?")

def analyze_stock_prices(prices):
    if not prices:
        return {
            "lowest_price": 0,
            "highest_price": 0,
            "average_price": 0,
        }

    lowest_price = min(prices)
    highest_price = max(prices)
    average_price = sum(prices) / len(prices)

    return {
        "lowest_price": float(lowest_price),
        "highest_price": float(highest_price),
        "average_price": float(average_price),
    }

class NumberRange:
    """A simple iterator that returns numbers from start to end inclusive."""

    def __init__(self, start, end):
        self.current = start
        self.end = end

    def __iter__(self):
        return self

    def __next__(self):
        if self.current > self.end:
            raise StopIteration
        value = self.current
        self.current += 1
        return value


def even_squares(numbers):
    """Yield the square of each even number from the input iterable."""
    for number in numbers:
        if number % 2 == 0:
            yield number * number


