def fibonacci(n, cache):
    # Return cached result if available
    if n in cache:
        return cache[n]

    # Compute the value recursively and store it in the cache
    cache[n] = fibonacci(n - 1, cache) + fibonacci(n - 2, cache)
    return cache[n]


