    # Start cache with base Fibonacci values
    cache = {0: 0, 1: 1}

    # Print Fibonacci numbers from 0 to 10
    for i in range(11):
        print(f"Fibonacci({i}) = {fibonacci(i, cache)}")

    # Show cached results
    print("\nCache contents:")
    print(cache)


