from typing import List, Dict, Tuple


def top_k_frequent_sorted(nums: List[int], k: int) -> List[int]:
    if k <= 0 or not nums:
        return []

    # Phase 1: frequency count
    freq: Dict[int, int] = {}
    for n in nums:
        freq[n] = freq.get(n, 0) + 1

    items: List[Tuple[int, int]] = [(value, count) for value, count in freq.items()]
    k = min(k, len(items))

    def better(a: Tuple[int, int], b: Tuple[int, int]) -> bool:
        # Higher frequency is better; for ties, smaller value is better.
        return a[1] > b[1] or (a[1] == b[1] and a[0] < b[0])

    def partition(left: int, right: int, pivot_idx: int) -> int:
        pivot = items[pivot_idx]
        items[pivot_idx], items[right] = items[right], items[pivot_idx]
        store = left
        for i in range(left, right):
            if better(items[i], pivot):
                items[store], items[i] = items[i], items[store]
                store += 1
        items[store], items[right] = items[right], items[store]
        return store

    def quickselect(left: int, right: int, target_idx: int) -> None:
        while left <= right:
            pivot_idx = (left + right) // 2
            new_idx = partition(left, right, pivot_idx)
            if new_idx == target_idx:
                return
            if new_idx < target_idx:
                left = new_idx + 1
            else:
                right = new_idx - 1

    # Phase 2: place the top k elements into the first k positions
    quickselect(0, len(items) - 1, k - 1)

    # Sort only the selected top-k region
    top_k = items[:k]
    top_k.sort(key=lambda x: (-x[1], x[0]))
    return [value for value, _ in top_k]


def find_rank_of_value(nums: List[int], target: int) -> int:
    # Build the same frequency model used by the top-k function
    freq: Dict[int, int] = {}
    for n in nums:
        freq[n] = freq.get(n, 0) + 1

    if target not in freq:
        return -1

    target_count = freq[target]
    rank = 1
    for value, count in freq.items():
        # Count how many values outrank the target in the ordering
        if count > target_count or (count == target_count and value < target):
            rank += 1
    return rank


if __name__ == "__main__":
    data = [5, 3, 5, 2, 3, 5, 7, 2, 2, 7, 7, 7, 1, 3, 3, 3]
    print(top_k_frequent_sorted(data, 3))  # Expected: [3, 7, 5]
    print(find_rank_of_value(data, 5))     # Expected: 3
    print(find_rank_of_value(data, 4))     # Expected: -1

def make_logger(prefix):
    # Closure: this decorator remembers the prefix value
    def decorator(func):
        def wrapper(*args, **kwargs):
            print(f"[{prefix}] Starting '{func.__name__}'")
            result = func(*args, **kwargs)
            print(f"[{prefix}] Finished '{func.__name__}'")
            return result
        return wrapper
    return decorator


