class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n + 2))
        self.size = [0] * (n + 2)
        self.active = [False] * (n + 2)

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def activate(self, x: int) -> None:
        self.active[x] = True
        self.parent[x] = x
        self.size[x] = 1

    def union(self, a: int, b: int) -> int:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return ra
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        return ra


def latest_step_with_group_size(arr, m):
    n = len(arr)
    if m > n:
        return -1
    if m == n:
        return n

    uf = UnionFind(n)
    groups_of_size_m = 0
    latest = -1

    for step, pos in enumerate(arr, 1):
        uf.activate(pos)

        # A newly activated cell starts as a group of size 1.
        if m == 1:
            groups_of_size_m += 1

        for nei in (pos - 1, pos + 1):
            if 1 <= nei <= n and uf.active[nei]:
                root_pos = uf.find(pos)
                root_nei = uf.find(nei)
                if root_pos == root_nei:
                    continue

                # Remove old contributions before merging.
                if uf.size[root_pos] == m:
                    groups_of_size_m -= 1
                if uf.size[root_nei] == m:
                    groups_of_size_m -= 1

                new_root = uf.union(root_pos, root_nei)

                # Add new contribution after merging.
                if uf.size[new_root] == m:
                    groups_of_size_m += 1

        if groups_of_size_m > 0:
            latest = step

    return latest


# Example usage:
if __name__ == '__main__':
    print(latest_step_with_group_size([3, 5, 1, 2, 4], 1))  # 4
    print(latest_step_with_group_size([3, 1, 5, 4, 2], 2))  # -1

from collections import Counter
from datetime import datetime
from pathlib import Path


def parse_log_line(line: str):
    """Parse a single log line into (timestamp, level, message) or return None."""
    parts = [part.strip() for part in line.split("|", 2)]
    if len(parts) != 3:
        return None

    timestamp_str, level, message = parts
    try:
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return None

    if not level:
        return None

    return timestamp, level, message


def generate_report(input_file: str = "app.log", output_file: str = "report.txt"):
    input_path = Path(input_file)
    output_path = Path(output_file)

    if not input_path.exists():
        output_path.write_text("Input file not found: app.log\n", encoding="utf-8")
        return

    level_counts = Counter()
    critical_messages = []
    earliest = None
    latest = None
    total_valid = 0

    with input_path.open("r", encoding="utf-8") as f:
        for raw_line in f:
            line = raw_line.strip()
            if not line:
                continue

            parsed = parse_log_line(line)
            if parsed is None:
                continue

            timestamp, level, message = parsed
            total_valid += 1
            level_counts[level] += 1

            if earliest is None or timestamp < earliest:
                earliest = timestamp
            if latest is None or timestamp > latest:
                latest = timestamp

            if level in {"ERROR", "CRITICAL"}:
                critical_messages.append(f"[{level}] {message}")

    lines = [f"Total valid entries: {total_valid}"]

    for level in sorted(level_counts):
        lines.append(f"{level}: {level_counts[level]}")

    if earliest and latest:
        lines.append(
            f"Time range: {earliest.strftime('%Y-%m-%d %H:%M:%S')} to {latest.strftime('%Y-%m-%d %H:%M:%S')}"
        )
    else:
        lines.append("Time range: N/A")

    lines.append("Critical messages:")
    if critical_messages:
        lines.extend(critical_messages)
    else:
        lines.append("None")

    output_path.write_text("\n".join(lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    generate_report()

from typing import Any, Callable, Dict


def validate(data: Dict[str, Any], schema: Dict[str, Dict[str, Any]], path: str = "root") -> Dict[str, Any]:
    """Validate and normalize a dictionary according to a schema."""
    if not isinstance(data, dict):
        raise ValueError(f"{path}: expected dict, got {type(data).__name__}")

    # Reject unknown fields early.
    for key in data:
        if key not in schema:
            raise ValueError(f"{path}: unknown field '{key}'")

    result = {}
    for field, rules in schema.items():
        field_path = f"{path}.{field}"
        required = rules.get("required", False)

        if field not in data:
            if "default" in rules:
                result[field] = rules["default"]
                continue
            if required:
                raise ValueError(f"{field_path}: missing required field")
            continue

        value = data[field]
        expected_type = rules.get("type")
        if expected_type and not isinstance(value, expected_type):
            raise ValueError(
                f"{field_path}: expected {expected_type.__name__}, got {type(value).__name__}"
            )

        # Nested dictionary validation.
        if expected_type is dict and "schema" in rules:
            value = validate(value, rules["schema"], field_path)

        # List item validation.
        elif expected_type is list and "items" in rules:
            item_rules = rules["items"]
            validated_items = []
            for i, item in enumerate(value):
                item_path = f"{field_path}[{i}]"
                item_type = item_rules.get("type")
                if item_type and not isinstance(item, item_type):
                    raise ValueError(
                        f"{item_path}: expected {item_type.__name__}, got {type(item).__name__}"
                    )
                validator: Callable[[Any], bool] | None = item_rules.get("validator")
                if validator and not validator(item):
                    raise ValueError(f"{item_path}: custom validation failed")
                validated_items.append(item)
            value = validated_items

        # Field-level custom validator.
        validator: Callable[[Any], bool] | None = rules.get("validator")
        if validator and not validator(value):
            raise ValueError(f"{field_path}: custom validation failed")

        result[field] = value

    return result


if __name__ == "__main__":
