import heapq
from typing import List, TextIO


def _read_next_int(file_obj: TextIO, source_name: str):
    """Read the next non-blank integer from a file, or return None at EOF."""
    while True:
        line = file_obj.readline()
        if line == "":
            return None
        line = line.strip()
        if not line:
            continue
        try:
            return int(line)
        except ValueError as exc:
            raise ValueError(f"Invalid integer in {source_name}: {line!r}") from exc


def merge_sorted_files(input_paths: List[str], output_path: str) -> None:
    """Merge multiple sorted integer files into one sorted output file."""
    if not input_paths:
        raise ValueError("input_paths must contain at least one file path")

    files = []
    heap = []

    try:
        # Open all input files and seed the heap with the first value from each.
        for index, path in enumerate(input_paths):
            f = open(path, "r", encoding="utf-8")
            files.append(f)
            value = _read_next_int(f, path)
            if value is not None:
                heapq.heappush(heap, (value, index))

        with open(output_path, "w", encoding="utf-8") as out:
            while heap:
                value, file_index = heapq.heappop(heap)
                out.write(f"{value}\n")

                next_value = _read_next_int(files[file_index], input_paths[file_index])
                if next_value is not None:
                    heapq.heappush(heap, (next_value, file_index))
    finally:
        for f in files:
            f.close()


if __name__ == "__main__":
    # Example usage:
    # merge_sorted_files(["sorted1.txt", "sorted2.txt", "sorted3.txt"], "merged.txt")
    pass

