from dataclasses import dataclass, field
from typing import List


@dataclass
class Book:
    title: str
    author: str
    price: float
    stock: int


@dataclass
class Inventory:
    books: List[Book] = field(default_factory=list)

    def add_book(self, book: Book) -> None:
        """Add a book to the inventory."""
        self.books.append(book)

    def total_value(self) -> float:
        """Calculate the total value of all books in stock."""
        return sum(book.price * book.stock for book in self.books)

    def find_by_author(self, author: str) -> List[Book]:
        """Return all books written by the given author."""
        return [book for book in self.books if book.author == author]

    def low_stock_titles(self, threshold: int) -> List[str]:
        """Return titles of books with stock below the threshold."""
        return [book.title for book in self.books if book.stock < threshold]


if __name__ == "__main__":
