    inventory.add_book(Book(title="1984", author="George Orwell", price=12.99, stock=5))
    inventory.add_book(Book(title="Animal Farm", author="George Orwell", price=9.99, stock=2))
    inventory.add_book(Book(title="Dune", author="Frank Herbert", price=15.50, stock=8))

    print("Total inventory value:", inventory.total_value())
    print("Books by George Orwell:", inventory.find_by_author("George Orwell"))
