class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
        self.size = 1  # size of subtree rooted at this node


class BinarySearchTree:
    def __init__(self):
        self.root = None

    def _size(self, node):
        return node.size if node else 0

    def _update(self, node):
        if node:
            node.size = 1 + self._size(node.left) + self._size(node.right)

    def insert(self, key):
        def _insert(node, key):
            if not node:
                return Node(key)
            if key < node.key:
                node.left = _insert(node.left, key)
            elif key > node.key:
                node.right = _insert(node.right, key)
            # Ignore duplicates
            self._update(node)
            return node

        self.root = _insert(self.root, key)

    def delete(self, key):
        def _min_node(node):
            while node.left:
                node = node.left
            return node

        def _delete(node, key):
            if not node:
                return None
            if key < node.key:
                node.left = _delete(node.left, key)
            elif key > node.key:
                node.right = _delete(node.right, key)
            else:
                # Node with 0 or 1 child
                if not node.left:
                    return node.right
                if not node.right:
                    return node.left
                # Node with 2 children: replace with inorder successor
                succ = _min_node(node.right)
                node.key = succ.key
                node.right = _delete(node.right, succ.key)
            self._update(node)
            return node

        self.root = _delete(self.root, key)

    def kth_smallest(self, k):
        node = self.root
        while node:
            left_size = self._size(node.left)
            if k == left_size + 1:
                return node.key
            if k <= left_size:
                node = node.left
            else:
                k -= left_size + 1
                node = node.right
        return None

    def is_valid_bst(self):
        def _validate(node, low, high):
            if not node:
                return True, 0
            if not (low < node.key < high):
                return False, 0

            left_ok, left_size = _validate(node.left, low, node.key)
            right_ok, right_size = _validate(node.right, node.key, high)
            expected_size = 1 + left_size + right_size

            return (
                left_ok and right_ok and node.size == expected_size,
                expected_size,
            )

        valid, _ = _validate(self.root, float('-inf'), float('inf'))
        return valid


