import time
import threading
from dataclasses import dataclass
from typing import Dict


@dataclass
class _Bucket:
    tokens: float
    last_refill: float


class TokenBucketRateLimiter:
    """Thread-safe per-client token bucket rate limiter."""

    def __init__(self, refill_rate: float, capacity: int):
        if refill_rate <= 0:
            raise ValueError("refill_rate must be > 0")
        if capacity <= 0:
            raise ValueError("capacity must be > 0")

        self.refill_rate = refill_rate
        self.capacity = capacity
        self._buckets: Dict[str, _Bucket] = {}
        self._lock = threading.Lock()

    def allow(self, client_id: str, tokens: int = 1) -> bool:
        if tokens <= 0:
            raise ValueError("tokens must be > 0")
        if tokens > self.capacity:
            return False  # Cannot ever fit in a bucket.

        now = time.monotonic()
        with self._lock:
            bucket = self._buckets.get(client_id)
            if bucket is None:
                bucket = _Bucket(tokens=float(self.capacity), last_refill=now)
                self._buckets[client_id] = bucket

            # Refill lazily according to elapsed time.
            elapsed = now - bucket.last_refill
            if elapsed > 0:
                bucket.tokens = min(
                    self.capacity,
                    bucket.tokens + elapsed * self.refill_rate,
                )
                bucket.last_refill = now

            if bucket.tokens >= tokens:
                bucket.tokens -= tokens
                return True
            return False


if __name__ == "__main__":
    limiter = TokenBucketRateLimiter(refill_rate=2.0, capacity=5)

    client = "user-123"
    for i in range(7):
        print(f"req {i + 1}:", limiter.allow(client))

    time.sleep(1.5)  # Refill about 3 tokens.
    for i in range(4):
        print(f"after wait req {i + 1}:", limiter.allow(client))

from typing import Literal
from pydantic import BaseModel, Field, field_validator, model_validator, ConfigDict
import re


class StorageConfig(BaseModel):
    type: Literal['s3', 'gcs', 'local']
    path: str

    @field_validator('path')
    @classmethod
    def path_must_not_be_empty(cls, v: str) -> str:
        v = v.strip()
        if not v:
            raise ValueError('path must be non-empty')
        return v


class JobConfig(BaseModel):
    model_config = ConfigDict(str_strip_whitespace=True)

    job_name: str = Field(min_length=3, max_length=30)
    retries: int = Field(ge=0, le=10)
    schedule: str
    source: StorageConfig
    destination: StorageConfig
    tags: list[str] = Field(default_factory=list)

    @field_validator('job_name')
    @classmethod
    def validate_job_name(cls, v: str) -> str:
        if not re.fullmatch(r'[A-Za-z0-9_-]+', v):
            raise ValueError('job_name may contain only letters, numbers, underscores, or hyphens')
        return v

    @field_validator('schedule')
    @classmethod
    def validate_schedule(cls, v: str) -> str:
        if v in {'@daily', '@hourly'}:
            return v
        parts = v.split()
        if len(parts) != 5:
            raise ValueError('schedule must be a 5-part cron expression or @daily/@hourly')
        return v

    @field_validator('tags', mode='before')
    @classmethod
    def normalize_tags(cls, v):
        if v is None:
            return []
        if not isinstance(v, list):
            raise TypeError('tags must be a list of strings')
        seen = set()
        result = []
        for item in v:
            if not isinstance(item, str):
                raise TypeError('each tag must be a string')
            tag = item.strip().lower()
            if not tag:
                continue
            if tag not in seen:
                seen.add(tag)
                result.append(tag)
        return result

    @model_validator(mode='after')
    def validate_source_destination(self):
        if self.source.type == self.destination.type:
            raise ValueError('source and destination types must be different')
        return self


