import time
import threading
from collections import OrderedDict
from functools import wraps


class TTLCache:
    def __init__(self, capacity=128, default_ttl=60):
        if capacity <= 0:
            raise ValueError('capacity must be positive')
        self.capacity = capacity
        self.default_ttl = default_ttl
        self._data = OrderedDict()  # key -> (value, expires_at)
        self._lock = threading.RLock()

    def _now(self):
        return time.monotonic()

    def _freeze(self, obj):
        """Convert nested/unhashable objects into deterministic hashable forms."""
        if isinstance(obj, dict):
            return ('dict', tuple(sorted((self._freeze(k), self._freeze(v)) for k, v in obj.items())))
        if isinstance(obj, (list, tuple)):
            return (type(obj).__name__, tuple(self._freeze(x) for x in obj))
        if isinstance(obj, set):
            return ('set', tuple(sorted(self._freeze(x) for x in obj)))
        return obj

    def _make_call_key(self, args, kwargs):
        return self._freeze((args, kwargs))

    def _is_expired(self, expires_at):
        return expires_at is not None and expires_at <= self._now()

    def get(self, key):
        with self._lock:
            item = self._data.get(key)
            if item is None:
                return None
            value, expires_at = item
            if self._is_expired(expires_at):
                del self._data[key]
                return None
            self._data.move_to_end(key)  # mark as recently used
            return value

    def set(self, key, value, ttl=None):
        with self._lock:
            ttl = self.default_ttl if ttl is None else ttl
            expires_at = None if ttl is None else self._now() + ttl

            # Replace existing key and mark as recently used.
            if key in self._data:
                del self._data[key]
            self._data[key] = (value, expires_at)
            self._data.move_to_end(key)

            # Evict expired entries first, then least recently used if still over capacity.
            expired_keys = [k for k, (_, exp) in self._data.items() if self._is_expired(exp)]
            for k in expired_keys:
                self._data.pop(k, None)
            while len(self._data) > self.capacity:
                self._data.popitem(last=False)

    def memoize(self, ttl=None):
        def decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = (func.__module__, func.__qualname__, self._make_call_key(args, kwargs))
                cached = self.get(key)
                if cached is not None:
                    return cached
                result = func(*args, **kwargs)
                self.set(key, result, ttl=ttl)
                return result
            return wrapper
        return decorator


# Example usage
if __name__ == '__main__':
    cache = TTLCache(capacity=3, default_ttl=2)

    @cache.memoize(ttl=1)
    def expensive_sum(data, scale=1):
        time.sleep(0.1)
        return sum(data) * scale

    print(expensive_sum([1, 2, 3], scale=2))
    print(expensive_sum([1, 2, 3], scale=2))  # served from cache
    time.sleep(1.1)
    print(expensive_sum([1, 2, 3], scale=2))  # recomputed after TTL expiry

import os
import hashlib
from collections import defaultdict


def sha256_file(path, chunk_size=65536):
    """Compute SHA-256 checksum of a file without reading it all into memory."""
    hasher = hashlib.sha256()
    with open(path, 'rb') as f:
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            hasher.update(chunk)
    return hasher.hexdigest()


def find_duplicate_files(root_dir):
    """Return a list of duplicate-file groups under root_dir."""
    size_groups = defaultdict(list)

    # First pass: group files by size
    for dirpath, _, filenames in os.walk(root_dir):
        for name in filenames:
            path = os.path.join(dirpath, name)
            try:
                size = os.path.getsize(path)
                size_groups[size].append(path)
            except OSError:
                # Ignore unreadable/inaccessible files
                continue

    duplicates = []

    # Second pass: hash only files that share the same size
    for paths in size_groups.values():
        if len(paths) < 2:
            continue

        hash_groups = defaultdict(list)
        for path in paths:
            try:
                file_hash = sha256_file(path)
                hash_groups[file_hash].append(path)
            except OSError:
                # Ignore files that cannot be opened/read
                continue

        for group in hash_groups.values():
            if len(group) >= 2:
                duplicates.append(sorted(group))

    return duplicates


if __name__ == '__main__':
    import sys

    if len(sys.argv) != 2:
        print('Usage: python duplicate_finder.py <root_dir>')
        sys.exit(1)

    for group in find_duplicate_files(sys.argv[1]):
        print('\n'.join(group))
        print('-' * 40)

import os
import time
from collections import Counter


def monitor_log_file(path):
    counts = Counter({"INFO": 0, "WARNING": 0, "ERROR": 0})
    levels = tuple(counts.keys())

    print(f"Waiting for log file: {path}")
    while not os.path.exists(path):
        time.sleep(1)

    print(f"Monitoring started: {path}")
    with open(path, "r", encoding="utf-8") as file:
        # Start at the end of the file to monitor only new entries
        file.seek(0, os.SEEK_END)

        while True:
            line = file.readline()
            if not line:
                time.sleep(0.5)
                continue

            line = line.strip()
            for level in levels:
                if level in line:
                    counts[level] += 1
                    print(
                        f"INFO={counts['INFO']} WARNING={counts['WARNING']} ERROR={counts['ERROR']}"
                    )
                    break


