from pathlib import Path
import hashlib
from collections import defaultdict
from typing import Dict, List


def file_sha256(path: Path, chunk_size: int = 65536) -> str:
    """Compute the SHA-256 hash of a file efficiently in chunks."""
    hasher = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            hasher.update(chunk)
    return hasher.hexdigest()


def find_duplicate_files(root: str) -> Dict[str, List[str]]:
    """
    Recursively scan root for duplicate files by content.
    Ignores symlinks and skips files/directories that cannot be accessed.
    Returns only hashes that correspond to more than one file.
    """
    root_path = Path(root)
    files_by_hash = defaultdict(list)

    for path in root_path.rglob('*'):
        try:
            if path.is_symlink() or not path.is_file():
                continue
            digest = file_sha256(path)
            files_by_hash[digest].append(str(path.resolve()))
        except (PermissionError, OSError):
            # Skip unreadable or problematic files gracefully
            continue

    return {
        digest: sorted(paths)
        for digest, paths in files_by_hash.items()
        if len(paths) > 1
    }


