def retry(max_attempts):
    """Decorator factory that retries a function up to max_attempts times."""
    def decorator(func):
        def wrapper(*args, **kwargs):
            last_error = None

            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    last_error = exc
                    print(f"Attempt {attempt} failed: {exc}")

            # If all attempts failed, re-raise the last exception
            raise last_error
        return wrapper
    return decorator


# Closure-based state for the decorated function's behavior
call_count = 0


@retry(4)
def flaky_divide(a, b):
    """Fails on the first two calls, then succeeds."""
    global call_count
    call_count += 1

    if call_count < 3:
        raise ValueError("Temporary failure")

    return a / b


result = flaky_divide(10, 2)
print(f"Final result: {result}")

def caesar_shift(text, key):
    """Shift alphabetic characters by key positions, preserving case."""
    result = []
    key = key % 26

    for char in text:
        if 'a' <= char <= 'z':
            base = ord('a')
            shifted = chr(base + (ord(char) - base + key) % 26)
            result.append(shifted)
        elif 'A' <= char <= 'Z':
            base = ord('A')
            shifted = chr(base + (ord(char) - base + key) % 26)
            result.append(shifted)
        else:
            result.append(char)

    return ''.join(result)


def encrypt(message, key):
    """Encrypt a message using a Caesar cipher."""
    return caesar_shift(message, key)


def decrypt(ciphertext, key):
    """Decrypt a Caesar cipher message."""
    return caesar_shift(ciphertext, -key)


