import os


def _to_bool(value):
    """Convert common string representations to bool."""
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in {"1", "true", "yes", "on"}:
        return True
    if text in {"0", "false", "no", "off"}:
        return False
    raise ValueError(f"invalid boolean value: {value!r}")


def _convert(value, expected_type):
    """Convert a raw environment value to the requested type."""
    converters = {
        str: str,
        int: int,
        float: float,
        bool: _to_bool,
    }
    if expected_type not in converters:
        raise TypeError(f"unsupported type: {expected_type}")
    return converters[expected_type](value)


def load_config(schema, env=None):
    """
    Load and validate configuration from environment variables.

    Schema format:
    {
        "PORT": {"type": int, "required": True},
        "DEBUG": {"type": bool, "default": False},
        "MODE": {"type": str, "choices": ["dev", "prod"]},
        "API_KEY": {"type": str, "secret": True, "required": True},
    }
    """
    env = os.environ if env is None else env
    config = {}
    errors = []

    for key, rules in schema.items():
        expected_type = rules.get("type", str)
        required = rules.get("required", False)
        has_default = "default" in rules
        choices = rules.get("choices")

        if key in env and env[key] != "":
            raw_value = env[key]
        elif has_default:
            raw_value = rules["default"]
        elif required:
            errors.append(f"{key}: missing required variable")
            continue
        else:
            config[key] = None
            continue

        try:
            value = raw_value if isinstance(raw_value, expected_type) else _convert(raw_value, expected_type)
        except Exception as exc:
            errors.append(f"{key}: {exc}")
            continue

        if choices is not None and value not in choices:
            errors.append(f"{key}: must be one of {list(choices)!r}")
            continue

        config[key] = value

    if errors:
        raise ValueError("; ".join(errors))

    return config


def redact_config(config, schema):
    """Return a copy of config with secret values masked."""
    redacted = dict(config)
    for key, rules in schema.items():
        if rules.get("secret") and key in redacted and redacted[key] is not None:
            redacted[key] = "***"
    return redacted


