class BloomFilter:
    def __init__(self, size, num_hashes):
        # Size of the bit array and number of hash functions
        self.size = size
        self.num_hashes = num_hashes
        self.bits = [0] * size

    def _hashes(self, item):
        # Generate multiple positions for one item
        for i in range(self.num_hashes):
            yield hash(f"{item}-{i}") % self.size

    def add(self, item):
        # Set all relevant bit positions to 1
        for position in self._hashes(item):
            self.bits[position] = 1

    def contains(self, item):
        # If any required bit is 0, the item is definitely not present
        return all(self.bits[position] == 1 for position in self._hashes(item))


