from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation


def parse_timestamp(value):
    """Parse multiple timestamp formats and normalize to UTC ISO-8601."""
    if value is None:
        return None
    if isinstance(value, datetime):
        dt = value
    else:
        text = str(value).strip().replace('Z', '+00:00')
        try:
            dt = datetime.fromisoformat(text)
        except ValueError:
            for fmt in ("%Y-%m-%d %H:%M:%S", "%Y/%m/%d %H:%M:%S", "%Y-%m-%d"):
                try:
                    dt = datetime.strptime(text, fmt)
                    break
                except ValueError:
                    continue
            else:
                return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def parse_amount(value):
    """Convert amount-like values to float, handling currency symbols and commas."""
    if value is None or value == "":
        return 0.0
    if isinstance(value, (int, float)):
        return float(value)
    cleaned = str(value).strip().replace('$', '').replace(',', '')
    try:
        return float(Decimal(cleaned))
    except (InvalidOperation, ValueError):
        return None



def transform_events(records):
    latest_by_key = {}

    for record in records:
        user_id = record.get('user_id', record.get('userId'))
        event_type = record.get('event_type', record.get('type'))
        raw_time = record.get('event_time', record.get('timestamp'))
        amount = parse_amount(record.get('amount'))
        event_dt = parse_timestamp(raw_time)

        # Skip invalid records missing required fields or with unparseable values.
        if not user_id or not event_type or event_dt is None or amount is None:
            continue

        normalized = {
            'user_id': str(user_id),
            'event_type': str(event_type),
            'event_time': event_dt,
            'amount': amount,
        }
        key = (normalized['user_id'], normalized['event_type'])

        # Deduplicate by keeping the latest event for each (user_id, event_type).
        if key not in latest_by_key or normalized['event_time'] > latest_by_key[key]['event_time']:
            latest_by_key[key] = normalized

    aggregates = {}
    for event in latest_by_key.values():
        user_id = event['user_id']
        agg = aggregates.setdefault(user_id, {
            'user_id': user_id,
            'total_amount': 0.0,
            'event_count': 0,
            'latest_event_time': event['event_time'],
        })
        agg['total_amount'] += event['amount']
        agg['event_count'] += 1
        if event['event_time'] > agg['latest_event_time']:
            agg['latest_event_time'] = event['event_time']

    result = []
    for agg in sorted(aggregates.values(), key=lambda x: x['user_id']):
        result.append({
            'user_id': agg['user_id'],
            'total_amount': round(agg['total_amount'], 2),
            'event_count': agg['event_count'],
            'latest_event_time': agg['latest_event_time'].isoformat().replace('+00:00', 'Z'),
        })
    return result

import time
from copy import deepcopy


def build_pipeline(middlewares, handler):
    """Wrap middlewares around the final handler from last to first."""
    next_handler = handler
    for middleware in reversed(middlewares):
        current_next = next_handler

        def make_wrapper(mw, nxt):
            return lambda request: mw(request, nxt)

        next_handler = make_wrapper(middleware, current_next)
    return next_handler


def logging_middleware(request, next_handler):
    request.setdefault('log', []).append(f"path={request.get('path', '/')}")
    return next_handler(request)


def auth_middleware(request, next_handler):
    if 'user' not in request:
        return {'status': 401, 'error': 'unauthorized'}
    return next_handler(request)


def timing_middleware(request, next_handler):
    start = time.perf_counter()
    response = next_handler(request)
    response['duration_ms'] = round((time.perf_counter() - start) * 1000, 3)
    return response


def final_handler(request):
    return {
        'status': 200,
        'message': f"hello {request['user']}"
    }


pipeline = build_pipeline(
    [logging_middleware, auth_middleware, timing_middleware],
    final_handler,
)

