    result = pipeline(request_copy)
    print(f"{name}: {result}")
    print(f"{name} request log: {request_copy.get('log', [])}")

import re
from collections import Counter
from itertools import tee, islice, starmap


def sliding_window(iterable, size):
    """Yield overlapping tuples of length `size` from `iterable`."""
    if size <= 0:
        raise ValueError('size must be positive')
    iterators = tee(iterable, size)
    for offset, it in enumerate(iterators):
        next(islice(it, offset, offset), None)
    return zip(*iterators)


def ngrams(words, n):
    """Yield n-grams as tuples using an itertools recipe."""
    if n <= 0:
        raise ValueError('n must be positive')
    iterators = tee(words, n)
    for offset, it in enumerate(iterators):
        next(islice(it, offset, offset), None)
    return zip(*iterators)


def tokenize(text):
    """Extract lowercase alphabetic words."""
    return re.findall(r"[a-zA-Z]+", text.lower())


def top_k_ngrams_in_window(window_words, n, k):
    """Count n-grams in one window and return the top-k sorted results."""
    counts = Counter(ngrams(window_words, n))
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:k]


def sliding_topk_ngrams(text, n, window_size, k):
    """
    For each sliding word window, compute the top-k most frequent n-grams.

    Returns:
        List of (window_words, top_ngrams) tuples.
    """
    if window_size <= 0 or n <= 0 or k < 0:
        raise ValueError('window_size and n must be positive, k must be non-negative')
    if n > window_size:
        return []

    words = tokenize(text)
    windows = sliding_window(words, window_size)

    # starmap applies the counting function to each produced window.
    top_lists = starmap(
        lambda window: (window, top_k_ngrams_in_window(window, n, k)),
        ((window,) for window in windows)
    )
    return list(top_lists)


if __name__ == '__main__':
    sample = (
        'Data science uses data pipelines. Science teams clean data, '
        'model data, and validate science workflows with data pipelines.'
    )

    result = sliding_topk_ngrams(sample, n=2, window_size=6, k=3)
    for window_words, top_ngrams in result:
        print('WINDOW:', window_words)
        print('TOP:', top_ngrams)
        print()

import pytest


class Cart:
    def __init__(self):
        self.items = {}

    def add_item(self, name, price):
        """Add or update an item with a non-negative price."""
        if price < 0:
            raise ValueError("price must be non-negative")
        self.items[name] = float(price)

    def remove_item(self, name):
        """Remove an item, raising KeyError if it does not exist."""
        if name not in self.items:
            raise KeyError(f"item not found: {name}")
        del self.items[name]

    def total(self, with_tax=False):
        """Return the total price, optionally including 10% tax."""
        subtotal = sum(self.items.values())
        return round(subtotal * 1.10, 2) if with_tax else round(subtotal, 2)

    def apply_discount(self, percent):
        """Apply a percentage discount to all items."""
        if not 0 <= percent <= 100:
            raise ValueError("discount percent must be between 0 and 100")
        factor = 1 - (percent / 100)
        for name in self.items:
            self.items[name] = round(self.items[name] * factor, 2)


