class TextEditor:
    def __init__(self):
        self.content = ""

    def insert(self, text):
        self.content += text

    def delete(self, count):
        deleted = self.content[-count:] if count <= len(self.content) else self.content
        self.content = self.content[:-count] if count <= len(self.content) else ""
        return deleted


class Command:
    def execute(self):
        raise NotImplementedError

    def undo(self):
        raise NotImplementedError


class InsertCommand(Command):
    def __init__(self, editor, text):
        self.editor = editor
        self.text = text

    def execute(self):
        self.editor.insert(self.text)

    def undo(self):
        self.editor.delete(len(self.text))


class DeleteCommand(Command):
    def __init__(self, editor, count):
        self.editor = editor
        self.count = count
        self.deleted_text = ""

    def execute(self):
        self.deleted_text = self.editor.delete(self.count)

    def undo(self):
        self.editor.insert(self.deleted_text)


class CommandManager:
    def __init__(self):
        self.history = []

    def run(self, command):
        command.execute()
        self.history.append(command)

    def undo(self):
        if self.history:
            command = self.history.pop()
            command.undo()


if __name__ == "__main__":
    editor = TextEditor()
    manager = CommandManager()

    commands = [
        InsertCommand(editor, "Hello"),
        InsertCommand(editor, " World"),
        DeleteCommand(editor, 3),
        InsertCommand(editor, "!!!")
    ]

    for cmd in commands:
        manager.run(cmd)
        print("Current content:", editor.content)

    manager.undo()
    print("After undo 1:", editor.content)

    manager.undo()
    print("After undo 2:", editor.content)

import re
from typing import Any

# Matches {{ expr }}, capturing the inner expression.
_PLACEHOLDER_RE = re.compile(r"\{\{\s*(.*?)\s*\}\}")
# Parses: path[|default(value)][ :format_spec ]
_EXPR_RE = re.compile(
    r"^(?P<path>[a-zA-Z_][\w.]*?)"
    r"(?:\|default\((?P<default>.*?)\))?"
    r"(?:\:(?P<format>.*))?$"
)


def _resolve_path(context: dict, path: str) -> Any:
    """Resolve dotted paths through nested dictionaries."""
    value: Any = context
    for part in path.split('.'):
        if not isinstance(value, dict) or part not in value:
            raise KeyError(path)
        value = value[part]
    return value


def _parse_default(raw: str) -> Any:
    """Parse a simple default literal using Python literal syntax."""
    if raw is None:
        return None
    raw = raw.strip()
    try:
        import ast
        return ast.literal_eval(raw)
    except Exception:
        # Fallback: treat as a raw string if not a valid literal.
        return raw


def _render_expr(expr: str, context: dict) -> str:
    match = _EXPR_RE.fullmatch(expr.strip())
    if not match:
        raise ValueError(f"Invalid template expression: {expr!r}")

    path = match.group('path')
    default_raw = match.group('default')
    format_spec = match.group('format')

    try:
        value = _resolve_path(context, path)
    except KeyError:
        if default_raw is None:
            raise
        value = _parse_default(default_raw)

    return format(value, format_spec or '')


def render_template(template: str, context: dict) -> str:
    """Render a template string by replacing all {{ ... }} placeholders."""
    return _PLACEHOLDER_RE.sub(lambda m: _render_expr(m.group(1), context), template)


def render_many(templates: list[str], context: dict) -> list[str]:
    """Render multiple templates using the same expression renderer."""
    return [render_template(template, context) for template in templates]


