import re
from pprint import pprint


def parse_log_entries(log_text):
    """Parse multiline log text into a list of structured dictionaries."""
    pattern = re.compile(
        r"^\s*\[(?P<timestamp>[^\]]+)\]\s*(?P<level>[A-Z]+)\s*:\s*(?P<message>[^|]*?)\s*(?:\|\s*(?P<meta>.*))?$"
    )

    entries = []

    for line in log_text.splitlines():
        line = line.strip()
        if not line:
            continue

        match = pattern.match(line)
        if not match:
            continue  # Skip malformed lines

        metadata = {}
        meta_text = match.group("meta")

        if meta_text:
            for item in meta_text.split(";"):
                item = item.strip()
                if not item or "=" not in item:
                    continue
                key, value = item.split("=", 1)
                metadata[key.strip()] = value.strip()

        entries.append({
            "timestamp": match.group("timestamp").strip(),
            "level": match.group("level").strip(),
            "message": match.group("message").strip(),
            "metadata": metadata,
        })

    return entries


