import time
from functools import wraps


def memoize_with_ttl(ttl_seconds):
    """Decorator factory that caches results for a limited time."""
    def decorator(func):
        cache = {}
        stats = {"hits": 0, "misses": 0}

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Build a hashable cache key from positional and keyword arguments.
            key = (args, tuple(sorted(kwargs.items())))
            now = time.time()

            if key in cache:
                value, expires_at = cache[key]
                if now < expires_at:
                    stats["hits"] += 1
                    return value
                # Remove expired entry before recomputing.
                del cache[key]

            stats["misses"] += 1
            result = func(*args, **kwargs)
            cache[key] = (result, now + ttl_seconds)
            return result

        def cache_info():
            # Drop expired entries before reporting cache size.
            now = time.time()
            expired_keys = [k for k, (_, exp) in cache.items() if now >= exp]
            for k in expired_keys:
                del cache[k]
            return {
                "hits": stats["hits"],
                "misses": stats["misses"],
                "current_size": len(cache),
                "ttl": ttl_seconds,
            }

        def cache_clear():
            cache.clear()
            stats["hits"] = 0
            stats["misses"] = 0

        # Expose utility methods on the wrapped function.
        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator


@memoize_with_ttl(ttl_seconds=2)
def fib(n):
    """Compute the nth Fibonacci number recursively."""
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)


if __name__ == "__main__":
    print("fib(10) =", fib(10))
    print("After first call:", fib.cache_info())

    print("fib(10) again =", fib(10))
    print("After cached call:", fib.cache_info())

    time.sleep(2.1)
    print("fib(10) after TTL expires =", fib(10))
    print("After expiration:", fib.cache_info())

