import hmac
import hashlib
import json


def handle_webhook(headers, body, secret):
    """Validate webhook signature and process supported events.

    Args:
        headers: dict containing request headers.
        body: request body as str or bytes.
        secret: shared secret used to verify the signature.

    Returns:
        dict with status and message.
    """
    signature = headers.get("X-Signature")
    if not signature:
        return {"status": 401, "message": "invalid signature"}

    # Normalize body/secret to bytes for hashing.
    body_bytes = body.encode("utf-8") if isinstance(body, str) else body
    secret_bytes = secret.encode("utf-8") if isinstance(secret, str) else secret

    expected_signature = hmac.new(
        secret_bytes,
        body_bytes,
        hashlib.sha256,
    ).hexdigest()

    # Use constant-time comparison to avoid timing attacks.
    if not hmac.compare_digest(signature, expected_signature):
        return {"status": 401, "message": "invalid signature"}

    try:
        payload = json.loads(body_bytes.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return {"status": 400, "message": "invalid json"}

    event_type = payload.get("type")
    payment_id = payload.get("data", {}).get("payment_id")

    if event_type == "payment.succeeded":
        return {"status": 200, "message": f"payment succeeded: {payment_id}"}
    if event_type == "payment.failed":
        return {"status": 200, "message": f"payment failed: {payment_id}"}

    return {"status": 400, "message": "unsupported event"}


