import time
from collections import deque
from functools import wraps


def rate_limiter(max_calls, period):
    """Decorator factory that limits calls within a rolling time window."""
    if max_calls <= 0:
        raise ValueError("max_calls must be > 0")
    if period <= 0:
        raise ValueError("period must be > 0")

    def decorator(func):
        call_times = deque()  # Stored in closure, one queue per wrapped function.

        @wraps(func)
        def wrapper(*args, **kwargs):
            now = time.monotonic()

            # Drop timestamps outside the rolling window.
            while call_times and now - call_times[0] >= period:
                call_times.popleft()

            if len(call_times) >= max_calls:
                wait_time = period - (now - call_times[0])
                raise RuntimeError(f"Rate limit exceeded. Try again in {wait_time:.2f}s")

            call_times.append(now)
            return func(*args, **kwargs)

        def get_call_times():
            """Return a snapshot of currently tracked call timestamps."""
            now = time.monotonic()
            while call_times and now - call_times[0] >= period:
                call_times.popleft()
            return list(call_times)

        def reset_limit():
            """Clear the stored call history for this function."""
            call_times.clear()

        # Expose helper methods on the wrapped function.
        wrapper.get_call_times = get_call_times
        wrapper.reset_limit = reset_limit
        return wrapper

    return decorator


# Example usage
