def fetch_data(item_id):
    return f"Fetched item {item_id}"

import time
import threading
from collections import OrderedDict, namedtuple
from functools import wraps

CacheInfo = namedtuple('CacheInfo', 'hits misses currsize maxsize')


def ttl_memoize(ttl_seconds, maxsize=128):
    """Thread-safe TTL + LRU memoization decorator."""
    def decorator(func):
        cache = OrderedDict()  # key -> (expires_at, value)
        hits = 0
        misses = 0
        lock = threading.RLock()

        def make_key(args, kwargs):
            if kwargs:
                return args + (object(),) + tuple(sorted(kwargs.items()))
            return args

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = make_key(args, kwargs)
            now = time.monotonic()

            with lock:
                if key in cache:
                    expires_at, value = cache[key]
                    if now < expires_at:
                        hits += 1
                        cache.move_to_end(key)  # mark as recently used
                        return value
                    del cache[key]  # expired entry

                misses += 1

            # Compute outside the lock to avoid blocking other threads.
            result = func(*args, **kwargs)
            expires_at = time.monotonic() + ttl_seconds

            with lock:
                cache[key] = (expires_at, result)
                cache.move_to_end(key)
                while len(cache) > maxsize:
                    cache.popitem(last=False)  # evict least recently used
            return result

        def cache_info():
            with lock:
                return CacheInfo(hits, misses, len(cache), maxsize)

        def cache_clear():
            nonlocal hits, misses
            with lock:
                cache.clear()
                hits = misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator


@ttl_memoize(ttl_seconds=10, maxsize=256)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)


if __name__ == '__main__':
    print(fib(35))
    print(fib.cache_info())

from functools import reduce, wraps, partial


def counted(func):
    """Decorator that counts how many times a function is called."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)

    wrapper.calls = 0
    return wrapper


def build_processor(rules):
    """Build a processor that applies matching transforms in rule order."""
    prepared_rules = []
    for rule in rules:
        prepared_rules.append({
            "name": rule["name"],
            "predicate": counted(rule["predicate"]),
            "transform": rule["transform"],
        })

    def apply_rule(event, rule):
        # Work with the current event snapshot; transforms must return new dicts.
        return rule["transform"](event) if rule["predicate"](event) else event

    def processor(event):
        # Start from a shallow copy to avoid mutating the original input.
        return reduce(apply_rule, prepared_rules, dict(event))

    # Expose wrapped rules so callers can inspect predicate call counts.
    processor.rules = prepared_rules
    return processor


def _extract_pair(event, *, processor):
    processed = processor(event)
    return (processed.get("type"), processed.get("priority"))


extract_with_processor = partial(_extract_pair)


def summarize_events(events, processor):
    """Return frequency counts of (type, priority) after processing."""
    pair_getter = partial(extract_with_processor, processor=processor)
    summary = {}
    for event in events:
        key = pair_getter(event)
        summary[key] = summary.get(key, 0) + 1
    return summary


if __name__ == "__main__":
    rules = [
        {
            "name": "promote_errors",
            "predicate": lambda e: e.get("type") == "error",
            "transform": lambda e: {**e, "priority": "high"},
        },
        {
            "name": "tag_large_payloads",
            "predicate": lambda e: e.get("size", 0) > 1000,
            "transform": lambda e: {**e, "type": f"{e.get('type', 'unknown')}_large"},
        },
    ]

    processor = build_processor(rules)
    events = [
        {"type": "error", "size": 1200, "priority": "low"},
        {"type": "info", "size": 50, "priority": "low"},
        {"type": "error", "size": 10, "priority": "low"},
    ]

    print(summarize_events(events, processor))
    print({rule['name']: rule['predicate'].calls for rule in processor.rules})

import hashlib


class BloomFilter:
    def __init__(self, size, hash_count):
        if size <= 0 or hash_count <= 0:
            raise ValueError("size and hash_count must be positive")
        self.size = size
        self.hash_count = hash_count
        self.bits = bytearray(size)

    def _hashes(self, item):
        """Generate hash_count positions for the given string item."""
        if not isinstance(item, str):
            raise TypeError("BloomFilter only supports string items")

        item_bytes = item.encode("utf-8")
        for i in range(self.hash_count):
            # Salt each hash with the index to simulate multiple hash functions
            digest = hashlib.sha256(i.to_bytes(2, "big") + item_bytes).digest()
            yield int.from_bytes(digest, "big") % self.size

    def add(self, item):
        """Add an item to the bloom filter."""
        for pos in self._hashes(item):
            self.bits[pos] = 1

    def __contains__(self, item):
        """Return True if item may be present, False if definitely absent."""
        return all(self.bits[pos] for pos in self._hashes(item))

    def stats(self):
        """Return the number of set bits and the current fill ratio."""
        set_bits = sum(self.bits)
        return {
            "set_bits": set_bits,
            "fill_ratio": set_bits / self.size,
        }


if __name__ == "__main__":
    bf = BloomFilter(size=100, hash_count=3)

    words_to_add = ["apple", "banana", "orange", "grape"]
    for word in words_to_add:
        bf.add(word)

    test_words = ["apple", "banana", "melon", "kiwi"]
    for word in test_words:
        result = "possibly present" if word in bf else "definitely absent"
        print(f"{word}: {result}")

    print("Stats:", bf.stats())

from collections import deque
from datetime import datetime


def process_logs(log_lines, error_threshold=3, window_seconds=60):
    """Process log lines and monitor error frequency in a sliding time window."""
    counts = {"INFO": 0, "WARNING": 0, "ERROR": 0}
    recent_errors = deque()

    for line in log_lines:
        # Expected format: YYYY-MM-DD HH:MM:SS LEVEL Message...
        parts = line.split(" ", 3)
        if len(parts) < 4:
            continue  # Skip malformed lines

        timestamp_str = f"{parts[0]} {parts[1]}"
        level = parts[2]

        try:
            timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M:%S")
        except ValueError:
            continue  # Skip lines with invalid timestamps

        if level in counts:
            counts[level] += 1

        if level == "ERROR":
            recent_errors.append(timestamp)

            # Remove errors older than the monitoring window
            while recent_errors and (timestamp - recent_errors[0]).total_seconds() > window_seconds:
                recent_errors.popleft()

            if len(recent_errors) >= error_threshold:
                print(
                    f"ALERT: {len(recent_errors)} errors in the last {window_seconds} seconds "
                    f"at {timestamp.strftime('%Y-%m-%d %H:%M:%S')}"
                )

    return counts


