from collections import deque


def count_connected_components(n, edges):
    """Return the number of connected components in an undirected graph."""
    # Build adjacency list
    graph = {i: [] for i in range(n)}
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()
    components = 0

    for node in range(n):
        if node in visited:
            continue

        # Start BFS for a new component
        components += 1
        queue = deque([node])
        visited.add(node)

        while queue:
            current = queue.popleft()
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    return components


if __name__ == '__main__':
    n = 7
    edges = [(0, 1), (1, 2), (3, 4), (5, 6)]
    print('Connected components:', count_connected_components(n, edges))

import subprocess
import shlex


def run_command(command):
    """Run a system command and capture its result."""
    try:
        # Split the command safely into arguments
        args = shlex.split(command)
        result = subprocess.run(
            args,
            capture_output=True,
            text=True,
            check=False
        )
        return {
            'command': command,
            'exit_code': result.returncode,
            'stdout': result.stdout.strip(),
            'stderr': result.stderr.strip()
        }
    except FileNotFoundError as e:
        return {
            'command': command,
            'exit_code': None,
            'stdout': '',
            'stderr': str(e)
        }
    except Exception as e:
        return {
            'command': command,
            'exit_code': None,
            'stdout': '',
            'stderr': f'Unexpected error: {e}'
        }


def print_summary(result):
    """Print a readable summary for a command result."""
    print(f"Command: {result['command']}")
    print(f"Exit code: {result['exit_code']}")
    print(f"STDOUT: {result['stdout'] or '[no output]'}")
    print(f"STDERR: {result['stderr'] or '[no errors]'}")
    print('-' * 40)


