class TrieNode:
    def __init__(self):
        self.children = {}
        self.prefix_count = 0   # number of words passing through this node
        self.end_count = 0      # number of words ending at this node


class PrefixDictionary:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            node.prefix_count += 1
        node.end_count += 1

    def count_prefix(self, prefix: str) -> int:
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return 0
            node = node.children[ch]
        return node.prefix_count

    def search(self, pattern: str) -> bool:
        # Supports '.' wildcard matching any single character.
        def dfs(node: TrieNode, i: int) -> bool:
            if i == len(pattern):
                return node.end_count > 0
            ch = pattern[i]
            if ch == '.':
                return any(dfs(child, i + 1) for child in node.children.values())
            if ch not in node.children:
                return False
            return dfs(node.children[ch], i + 1)

        return dfs(self.root, 0)

    def delete(self, word: str) -> bool:
        # First verify the word exists while storing the path.
        node = self.root
        path = []  # list of (parent, char, child)
        for ch in word:
            if ch not in node.children:
                return False
            child = node.children[ch]
            path.append((node, ch, child))
            node = child

        if node.end_count == 0:
            return False

        # Remove one occurrence.
        node.end_count -= 1
        for _, _, child in path:
            child.prefix_count -= 1

        # Prune unused nodes from the end of the word.
        for parent, ch, child in reversed(path):
            if child.prefix_count == 0 and child.end_count == 0 and not child.children:
                del parent.children[ch]
            else:
                break

        return True


# Example usage:
if __name__ == '__main__':
    pd = PrefixDictionary()
    pd.insert('apple')
    pd.insert('app')
    pd.insert('apple')
    print(pd.count_prefix('app'))   # 3
    print(pd.search('a..le'))       # True
    print(pd.delete('apple'))       # True
    print(pd.count_prefix('app'))   # 2
    print(pd.search('apple'))       # True
    print(pd.delete('banana'))      # False

from dataclasses import dataclass
from typing import Any, Iterable, List


@dataclass
class Transaction:
    transaction_id: str
    account_id: str
    amount: float
    country: str
    card_present: bool


def find_suspicious_transactions(
    transactions: Iterable[Transaction],
    home_country: str = "home_country",
) -> List[str]:
    if not isinstance(home_country, str) or not home_country.strip():
        raise ValueError("home_country must be a non-empty string.")

    if transactions is None:
        raise ValueError("transactions must not be None.")

    suspicious_ids: List[str] = []

    for transaction in transactions:
        if not isinstance(transaction, Transaction):
            raise TypeError("Each item in transactions must be a Transaction instance.")

        if not isinstance(transaction.transaction_id, str) or not transaction.transaction_id.strip():
            raise ValueError("transaction_id must be a non-empty string.")

        if not isinstance(transaction.account_id, str) or not transaction.account_id.strip():
            raise ValueError("account_id must be a non-empty string.")

        if not isinstance(transaction.country, str) or not transaction.country.strip():
            raise ValueError("country must be a non-empty string.")

        if not isinstance(transaction.card_present, bool):
            raise ValueError("card_present must be a boolean value.")

        if not isinstance(transaction.amount, (int, float)):
            raise ValueError("amount must be a number.")

        if transaction.amount < 0:
            raise ValueError("amount must not be negative.")

        is_over_limit = transaction.amount > 5000
        is_foreign_country = transaction.country != home_country
        is_card_not_present_high_amount = not transaction.card_present and transaction.amount > 1000

        if is_over_limit or is_foreign_country or is_card_not_present_high_amount:
            suspicious_ids.append(transaction.transaction_id)

    return suspicious_ids


