    flagged = find_suspicious_transactions(sample_transactions)
    print(flagged)

def build_pipeline(middlewares, handler):
    """Wrap middlewares around the final handler."""
    def call_next(index, request):
        if index == len(middlewares):
            return handler(request)
        return middlewares[index](request, lambda req: call_next(index + 1, req))

    return lambda request: call_next(0, request)


def logging_middleware(request, next_func):
    print(f"Log: request for {request.get('path', '/')}")
    return next_func(request)


def default_user_middleware(request, next_func):
    if 'user' not in request:
        request['user'] = 'guest'
    return next_func(request)


def auth_middleware(request, next_func):
    if request.get('path') == '/admin' and request.get('user') != 'admin':
        return {
            'status': 403,
            'message': 'Access denied'
        }
    return next_func(request)


def final_handler(request):
    return {
        'status': 200,
        'message': f"Hello {request['user']}, you requested {request['path']}"
    }


pipeline = build_pipeline(
    [logging_middleware, default_user_middleware, auth_middleware],
    final_handler
)

requests = [
    {'path': '/home'},
    {'path': '/admin', 'user': 'guest'},
    {'path': '/admin', 'user': 'admin'}
]

for req in requests:
    response = pipeline(req.copy())
    print(response)

