def analyze_transactions(transactions):
    # Keep only valid transactions with positive amounts
    valid = [
        t for t in transactions
        if isinstance(t, dict)
        and {'user', 'category', 'amount'}.issubset(t)
        and isinstance(t['amount'], (int, float))
        and t['amount'] > 0
    ]

    if not valid:
        return {
            'high_value_users': [],
            'category_totals': {},
            'large_transactions': [],
            'normalized_amounts': []
        }

    # Build category totals using unique category discovery + comprehensions
    categories = sorted({t['category'] for t in valid})
    category_totals = {
        category: sum(t['amount'] for t in valid if t['category'] == category)
        for category in categories
    }

    # Compute total spending per user
    users = {t['user'] for t in valid}
    user_totals = {
        user: sum(t['amount'] for t in valid if t['user'] == user)
        for user in users
    }
    high_value_users = sorted([user for user, total in user_totals.items() if total > 500])

    # Filter and format large transactions, sorted by amount descending then user
    large_sorted = sorted(
        [t for t in valid if t['amount'] >= 200],
        key=lambda t: (-t['amount'], t['user'])
    )
    large_transactions = [
        f"{t['user']}:{t['category']}:{t['amount']}"
        for t in large_sorted
    ]

    # Normalize amounts against the maximum valid transaction amount
    max_amount = max(t['amount'] for t in valid)
    normalized_amounts = [round(t['amount'] / max_amount, 2) for t in valid]

    return {
        'high_value_users': high_value_users,
        'category_totals': category_totals,
        'large_transactions': large_transactions,
        'normalized_amounts': normalized_amounts
    }


# Example usage
if __name__ == '__main__':
    sample_transactions = [
        {'user': 'alice', 'category': 'groceries', 'amount': 120},
        {'user': 'bob', 'category': 'electronics', 'amount': 650},
        {'user': 'alice', 'category': 'books', 'amount': 220},
        {'user': 'carol', 'category': 'groceries', 'amount': 300},
        {'user': 'bob', 'category': 'groceries', 'amount': 50},
        {'user': 'alice', 'category': 'electronics', 'amount': -10},
        {'user': 'dave', 'category': 'sports', 'amount': 200}
    ]

    result = analyze_transactions(sample_transactions)
    print(result)

import pytest


def calculate_total(prices, tax_rate=0.0):
    """Return the total price including tax.

    Args:
        prices: A list of item prices.
        tax_rate: Tax rate as a decimal, for example 0.1 for 10%.

    Returns:
        Total cost after tax.

    Raises:
        ValueError: If any price or the tax rate is negative.
    """
    if tax_rate < 0:
        raise ValueError("tax_rate cannot be negative")

    if any(price < 0 for price in prices):
        raise ValueError("prices cannot contain negative values")

    subtotal = sum(prices)
    return subtotal * (1 + tax_rate)


