import time
from urllib.parse import urljoin

import requests


class ApiClientError(Exception):
    """Raised for non-retryable API client errors."""


class ApiServerError(Exception):
    """Raised when retries are exhausted for transient/server errors."""


def _request_with_retries(session, url, max_retries=3, timeout=10):
    """Perform a GET request with retry handling for transient failures."""
    backoff = 1.0

    for attempt in range(1, max_retries + 1):
        try:
            response = session.get(url, timeout=timeout)
        except requests.RequestException as exc:
            if attempt == max_retries:
                raise ApiServerError(f"Network error after {max_retries} attempts: {exc}") from exc
            time.sleep(backoff)
            backoff *= 2
            continue

        if response.status_code == 429:
            if attempt == max_retries:
                raise ApiServerError("Rate limited and retries exhausted")
            retry_after = response.headers.get("Retry-After")
            wait_seconds = float(retry_after) if retry_after and retry_after.isdigit() else backoff
            time.sleep(wait_seconds)
            backoff *= 2
            continue

        if 500 <= response.status_code < 600:
            if attempt == max_retries:
                raise ApiServerError(
                    f"Server error {response.status_code} after {max_retries} attempts"
                )
            time.sleep(backoff)
            backoff *= 2
            continue

        if 400 <= response.status_code < 500:
            raise ApiClientError(
                f"Client error {response.status_code}: {response.text.strip()}"
            )

        return response

    raise ApiServerError("Unexpected retry loop termination")


def fetch_all_users(base_url, token):
    """Fetch all users from a paginated REST endpoint."""
    users = []
    next_url = urljoin(base_url.rstrip("/") + "/", "users")

    with requests.Session() as session:
        session.headers.update({
            "Authorization": f"Bearer {token}",
            "Accept": "application/json",
        })

        while next_url:
            response = _request_with_retries(session, next_url)
            payload = response.json()

            users.extend(payload.get("items", []))
            next_link = payload.get("next")
            next_url = urljoin(next_url, next_link) if next_link else None

    return users


