import json
import csv
import io
import threading
from abc import ABC, abstractmethod


class SingletonMeta(type):
    """Thread-safe Singleton metaclass."""
    _instances = {}
    _lock = threading.Lock()

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            with cls._lock:
                if cls not in cls._instances:
                    cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]


class SerializerRegistry(metaclass=SingletonMeta):
    def __init__(self):
        self._serializers = {}

    def register(self, name):
        """Decorator to register a serializer class under a format name."""
        def decorator(serializer_cls):
            self._serializers[name.lower()] = serializer_cls
            return serializer_cls
        return decorator

    def create(self, name, **kwargs):
        """Instantiate a registered serializer by name."""
        serializer_cls = self._serializers.get(name.lower())
        if serializer_cls is None:
            raise ValueError(f"Unknown serializer format: {name}")
        return serializer_cls(**kwargs)

    def formats(self):
        return sorted(self._serializers)


class Serializer(ABC):
    @abstractmethod
    def serialize(self, data):
        pass


registry = SerializerRegistry()


@registry.register("json")
class JsonSerializer(Serializer):
    def __init__(self, indent=None):
        self.indent = indent

    def serialize(self, data):
        return json.dumps(data, indent=self.indent)


@registry.register("csv")
class CsvSerializer(Serializer):
    def serialize(self, data):
        if not data:
            return ""
        if not isinstance(data, list) or not all(isinstance(row, dict) for row in data):
            raise ValueError("CSV serialization requires a list of dictionaries")

        output = io.StringIO()
        fieldnames = list(data[0].keys())
        writer = csv.DictWriter(output, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(data)
        return output.getvalue()


if __name__ == "__main__":
    json_serializer = registry.create("json", indent=2)
    csv_serializer = registry.create("csv")

    obj_data = {"service": "billing", "active": True, "retries": 3}
    table_data = [
        {"name": "Alice", "age": 30},
        {"name": "Bob", "age": 25},
    ]

    print("Available formats:", registry.formats())
    print("\nJSON output:")
    print(json_serializer.serialize(obj_data))
    print("\nCSV output:")
    print(csv_serializer.serialize(table_data))

import heapq
from collections import defaultdict


def sliding_window_median(nums, k):
    if k <= 0 or not nums or k > len(nums):
        return []

    # small: max-heap via negative values, large: min-heap
    small = []
    large = []
    delayed = defaultdict(int)  # lazy deletion counts
    small_size = 0  # count of valid elements in small
    large_size = 0  # count of valid elements in large

    def prune(heap):
        # Remove elements marked for deletion from heap top
        while heap:
            value = -heap[0] if heap is small else heap[0]
            if delayed[value]:
                delayed[value] -= 1
                if delayed[value] == 0:
                    del delayed[value]
                heapq.heappop(heap)
            else:
                break

    def rebalance():
        nonlocal small_size, large_size
        # Keep sizes balanced: small may have at most one extra element
        if small_size > large_size + 1:
            heapq.heappush(large, -heapq.heappop(small))
            small_size -= 1
            large_size += 1
            prune(small)
        elif small_size < large_size:
            heapq.heappush(small, -heapq.heappop(large))
            small_size += 1
            large_size -= 1
            prune(large)

    def add_num(num):
        nonlocal small_size, large_size
        if not small or num <= -small[0]:
            heapq.heappush(small, -num)
            small_size += 1
        else:
            heapq.heappush(large, num)
            large_size += 1
        rebalance()

    def remove_num(num):
        nonlocal small_size, large_size
        delayed[num] += 1
        if num <= -small[0]:
            small_size -= 1
            if num == -small[0]:
                prune(small)
        else:
            large_size -= 1
            if large and num == large[0]:
                prune(large)
        rebalance()

    def get_median():
        if k % 2 == 1:
            return float(-small[0])
        return (-small[0] + large[0]) / 2.0

    # Initialize first window
    for i in range(k):
        add_num(nums[i])

    result = [get_median()]

    # Slide the window
    for i in range(k, len(nums)):
        add_num(nums[i])
        remove_num(nums[i - k])
        result.append(get_median())

    return result


# Example usage
if __name__ == '__main__':
    print(sliding_window_median([1, 3, -1, -3, 5, 3, 6, 7], 3))
    print(sliding_window_median([1, 2, 3, 4], 2))

class PositiveNumber:
    """Descriptor that accepts only positive int/float values."""

    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, (int, float)):
            raise TypeError(f"{self.private_name[1:]} must be a number")
        if value <= 0:
            raise ValueError(f"{self.private_name[1:]} must be > 0")
        setattr(instance, self.private_name, float(value))


class Product:
    base_price = PositiveNumber()
    tax_rate = PositiveNumber()

    def __init__(self, name, base_price, tax_rate):
        self.name = name
        self.base_price = base_price
        self.tax_rate = tax_rate
        self._sku = None
        self._discount_percent = 0.0

    @property
    def sku(self):
        return self._sku

    @sku.setter
    def sku(self, value):
        if not isinstance(value, str):
            raise TypeError("sku must be a string")
        normalized = value.strip().upper()
        if not normalized:
            raise ValueError("sku cannot be empty")
        self._sku = normalized

    @property
    def discount_percent(self):
        return self._discount_percent

    @discount_percent.setter
    def discount_percent(self, value):
        if not isinstance(value, (int, float)):
            raise TypeError("discount_percent must be a number")
        if not 0 <= value <= 100:
            raise ValueError("discount_percent must be between 0 and 100")
        self._discount_percent = float(value)

    @property
    def total_price(self):
        return self.base_price * (1 + self.tax_rate / 100)

    def final_price(self):
        return self.total_price * (1 - self.discount_percent / 100)


# Example usage
if __name__ == "__main__":
    product = Product("Laptop", 1000, 20)
    product.sku = "  ab-123  "
    product.discount_percent = 15

    print(product.name)          # Laptop
    print(product.sku)           # AB-123
    print(product.total_price)   # 1200.0
    print(product.final_price()) # 1020.0

