    total_amount = Decimal("0")

    for item in order["items"]:
        if not isinstance(item, dict):
            return None
        if not all(k in item for k in ("sku", "quantity", "unit_price")):
            return None
        if not isinstance(item["sku"], str):
            return None

        try:
            quantity = int(item["quantity"])
            unit_price = Decimal(str(item["unit_price"]))
        except (ValueError, TypeError, InvalidOperation):
            return None

        total_quantity += quantity
        total_amount += unit_price * quantity

    total_amount = total_amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return {
        "order_id": order["order_id"],
        "customer": order["customer"],
        "item_count": len(order["items"]),
        "total_quantity": total_quantity,
        "total_amount": total_amount,
    }


def main():
    try:
        data = json.load(sys.stdin)
    except json.JSONDecodeError:
        return

    if not isinstance(data, list):
        return

    rows = []
    for order in data:
        parsed = parse_order(order)
        if parsed is not None:
            rows.append(parsed)

    rows.sort(key=lambda r: (-r["total_amount"], r["order_id"]))

    writer = csv.writer(sys.stdout)
    writer.writerow(["order_id", "customer", "item_count", "total_quantity", "total_amount"])
    for row in rows:
        writer.writerow([
            row["order_id"],
            row["customer"],
            row["item_count"],
            row["total_quantity"],
            f"{row['total_amount']:.2f}",
        ])


if __name__ == "__main__":
    main()
}

from itertools import islice, tee
from collections import Counter


def sliding_window(iterable, n):
    """Yield overlapping tuples of size n from the iterable.

    Recipe-style implementation using itertools.tee.
    Example: sliding_window('abcd', 3) -> ('a','b','c'), ('b','c','d')
    """
    if n <= 0:
        raise ValueError("window size must be positive")

    iterators = tee(iterable, n)
    for offset, it in enumerate(iterators):
        next(islice(it, offset, offset), None)
    return zip(*iterators)



def sliding_anagram_windows(text, pattern):
    """Return start indices where an anagram of pattern appears in text."""
    if not pattern or len(pattern) > len(text):
        return []

    target_count = Counter(pattern)
    matches = []

    for i, window in enumerate(sliding_window(text, len(pattern))):
        if Counter(window) == target_count:
            matches.append(i)

    return matches


if __name__ == "__main__":
    text = "cbaebabacd"
    pattern = "abc"
    result = sliding_anagram_windows(text, pattern)
    print(result)  # Expected: [0, 6]

import json
from abc import ABC, abstractmethod


class Report:
    def __init__(self, title, sections, metadata):
        self.title = title
        self.sections = sections
        self.metadata = metadata

    @abstractmethod
    def render(self):
        raise NotImplementedError


class JsonReport(Report):
    def render(self):
        return json.dumps({
            "title": self.title,
            "metadata": self.metadata,
            "sections": self.sections,
        }, indent=2)


class TextReport(Report):
    def render(self):
        lines = [f"# {self.title}"]
        if self.metadata:
            lines.append("Metadata:")
            for key, value in self.metadata.items():
                lines.append(f"- {key}: {value}")
        for section in self.sections:
            lines.append(f"\n## {section['heading']}")
            lines.append(section['content'])
        return "\n".join(lines)


class ReportFactory:
    @staticmethod
    def create_report(report_type, title, sections, metadata):
        report_map = {
            "json": JsonReport,
            "text": TextReport,
        }
        if report_type not in report_map:
            raise ValueError(f"Unsupported report type: {report_type}")
        return report_map[report_type](title, sections, metadata)


class ReportBuilder:
    def __init__(self, report_type):
        self.report_type = report_type
        self._title = "Untitled"
        self._sections = []
        self._metadata = {}

    def set_title(self, title):
        self._title = title
        return self

    def add_section(self, heading, content):
        self._sections.append({"heading": heading, "content": content})
        return self

    def add_metadata(self, key, value):
        self._metadata[key] = value
        return self

    def build(self):
        return ReportFactory.create_report(
            self.report_type,
            self._title,
            self._sections,
            self._metadata,
        )


if __name__ == "__main__":
    source_data = {
        "title": "Quarterly Engineering Summary",
