            ("Risks", "Test coverage in one service remains below target."),
        ],
        "metadata": {
            "author": "Team Lead",
            "quarter": "Q2",
        },
    }

    json_builder = ReportBuilder("json").set_title(source_data["title"])
    text_builder = ReportBuilder("text").set_title(source_data["title"])

    for heading, content in source_data["sections"]:
        json_builder.add_section(heading, content)
        text_builder.add_section(heading, content)

    for key, value in source_data["metadata"].items():
        json_builder.add_metadata(key, value)
        text_builder.add_metadata(key, value)

