from time import perf_counter
from typing import Callable, Dict, Any, List

Context = Dict[str, Any]
Middleware = Callable[[Context, Callable[[Context], Any]], Any]
Handler = Callable[[Context], Any]


class Pipeline:
    def __init__(self) -> None:
        self._middleware: List[Middleware] = []

    def add(self, middleware: Middleware) -> "Pipeline":
        self._middleware.append(middleware)
        return self

    def run(self, context: Context, handler: Handler) -> Any:
        def call(index: int, ctx: Context) -> Any:
            if index == len(self._middleware):
                return handler(ctx)
            return self._middleware[index](ctx, lambda new_ctx: call(index + 1, new_ctx))

        return call(0, context)


def tracing_middleware(context: Context, next_call: Callable[[Context], Any]) -> Any:
    context.setdefault("trace", []).append("trace:before")
    result = next_call(context)
    context["trace"].append("trace:after")
    return result


def timing_middleware(context: Context, next_call: Callable[[Context], Any]) -> Any:
    start = perf_counter()
    try:
        return next_call(context)
    finally:
        context["duration_ms"] = round((perf_counter() - start) * 1000, 3)


def auth_middleware(context: Context, next_call: Callable[[Context], Any]) -> Any:
    token = context.get("token")
    if token != "secret-token":
        context.setdefault("trace", []).append("auth:blocked")
        return {"status": 401, "error": "unauthorized"}
    context.setdefault("trace", []).append("auth:ok")
    context["user"] = {"id": 1, "role": "admin"}
    return next_call(context)


def validation_middleware(context: Context, next_call: Callable[[Context], Any]) -> Any:
    payload = context.get("payload")
    if not isinstance(payload, dict) or "action" not in payload:
        raise ValueError("payload must be a dict containing 'action'")
    context.setdefault("trace", []).append("validation:ok")
    return next_call(context)


def error_handling_middleware(context: Context, next_call: Callable[[Context], Any]) -> Any:
    try:
        return next_call(context)
    except Exception as exc:
        context.setdefault("trace", []).append("error:handled")
        return {"status": 500, "error": str(exc)}


def final_handler(context: Context) -> Dict[str, Any]:
    context.setdefault("trace", []).append("handler:executed")
    return {
        "status": 200,
        "message": "processed",
        "user": context.get("user"),
        "action": context["payload"]["action"],
    }


if __name__ == "__main__":
    pipeline = (
        Pipeline()
        .add(error_handling_middleware)
        .add(tracing_middleware)
        .add(timing_middleware)
        .add(auth_middleware)
        .add(validation_middleware)
    )

    ok_context = {"token": "secret-token", "payload": {"action": "deploy"}}
    bad_context = {"token": "wrong-token", "payload": {"action": "deploy"}}
    invalid_context = {"token": "secret-token", "payload": "invalid"}

    for name, ctx in [("success", ok_context), ("unauthorized", bad_context), ("invalid", invalid_context)]:
        result = pipeline.run(ctx, final_handler)
        print(name, result)
        print("context", ctx)
        print("-" * 40)

from typing import Dict, Tuple


WIRE_VARINT = 0
WIRE_LEN_DELIMITED = 2


def read_varint(data: bytes, offset: int) -> Tuple[int, int]:
    """Read a protobuf varint starting at offset."""
    result = 0
    shift = 0
    while True:
        if offset >= len(data):
            raise ValueError("Unexpected end of data while reading varint")
        byte = data[offset]
        offset += 1
        result |= (byte & 0x7F) << shift
        if not (byte & 0x80):
            return result, offset
        shift += 7
        if shift >= 64:
            raise ValueError("Varint too long")


def skip_field(data: bytes, offset: int, wire_type: int) -> int:
    """Skip an unknown field based on its wire type."""
    if wire_type == WIRE_VARINT:
        _, offset = read_varint(data, offset)
        return offset
    if wire_type == WIRE_LEN_DELIMITED:
        length, offset = read_varint(data, offset)
        end = offset + length
        if end > len(data):
            raise ValueError("Length-delimited field exceeds data size")
        return end
    raise ValueError(f"Unsupported wire type: {wire_type}")


def decode_person_message(data: bytes) -> Dict[str, object]:
    """Decode a minimal Person protobuf message without external libraries."""
    person = {}
    offset = 0

    while offset < len(data):
        key, offset = read_varint(data, offset)
        field_number = key >> 3
        wire_type = key & 0x07

        if field_number == 1 and wire_type == WIRE_LEN_DELIMITED:
            length, offset = read_varint(data, offset)
            end = offset + length
            if end > len(data):
                raise ValueError("Invalid name field length")
            person["name"] = data[offset:end].decode("utf-8")
            offset = end
        elif field_number == 2 and wire_type == WIRE_VARINT:
            value, offset = read_varint(data, offset)
            person["id"] = value
        elif field_number == 3 and wire_type == WIRE_LEN_DELIMITED:
            length, offset = read_varint(data, offset)
            end = offset + length
            if end > len(data):
                raise ValueError("Invalid email field length")
            person["email"] = data[offset:end].decode("utf-8")
            offset = end
        else:
            offset = skip_field(data, offset, wire_type)

    return person


def encode_varint(value: int) -> bytes:
    """Encode an integer as a protobuf varint for the example."""
    if value < 0:
        raise ValueError("This example only supports non-negative integers")
    out = bytearray()
    while True:
        to_write = value & 0x7F
        value >>= 7
        if value:
            out.append(to_write | 0x80)
        else:
            out.append(to_write)
            return bytes(out)


def make_length_delimited(field_number: int, text: str) -> bytes:
    payload = text.encode("utf-8")
    key = (field_number << 3) | WIRE_LEN_DELIMITED
    return encode_varint(key) + encode_varint(len(payload)) + payload


def make_varint_field(field_number: int, value: int) -> bytes:
    key = (field_number << 3) | WIRE_VARINT
    return encode_varint(key) + encode_varint(value)


if __name__ == "__main__":
    # Person { name: "Alice", id: 123, email: "alice@example.com" }
    message = b"".join([
        make_length_delimited(1, "Alice"),
        make_varint_field(2, 123),
        make_length_delimited(3, "alice@example.com"),
    ])

    decoded = decode_person_message(message)
    print(decoded)

import csv
import os


class ExperimentResults:
    def __init__(self, csv_file_path=None):
        self.experiments = []
        if csv_file_path:
            self.load_from_csv(csv_file_path)

    def _to_float(self, value, field_name):
        try:
            if value is None or str(value).strip() == "":
                raise ValueError(f"Missing value for {field_name}")
            return float(value)
        except (ValueError, TypeError):
            print(f"Warning: Invalid {field_name} value: {value}")
            return None

    def load_from_csv(self, csv_file_path):
        if not os.path.exists(csv_file_path):
            print(f"Warning: File not found: {csv_file_path}")
            return

        try:
            with open(csv_file_path, mode="r", newline="", encoding="utf-8") as file:
                reader = csv.DictReader(file)

                required_columns = {"model_name", "accuracy", "training_time"}
                if not reader.fieldnames or not required_columns.issubset(set(reader.fieldnames)):
                    print("Warning: CSV file must contain columns: model_name, accuracy, training_time")
                    return

                for row in reader:
                    model_name = str(row.get("model_name", "")).strip()
                    accuracy = self._to_float(row.get("accuracy"), "accuracy")
                    training_time = self._to_float(row.get("training_time"), "training_time")

                    if not model_name:
                        print("Warning: Skipping row with missing model_name")
                        continue

                    if accuracy is None or training_time is None:
                        print(f"Warning: Skipping invalid row for model: {model_name}")
                        continue

                    self.experiments.append(
                        {
                            "model_name": model_name,
                            "accuracy": accuracy,
                            "training_time": training_time,
                        }
                    )
        except Exception as error:
            print(f"Warning: Could not read CSV file. Error: {error}")

    def add_experiment(self, model_name, accuracy, training_time):
        model_name = str(model_name).strip()
        accuracy = self._to_float(accuracy, "accuracy")
        training_time = self._to_float(training_time, "training_time")

        if not model_name:
            print("Warning: model_name cannot be empty")
            return False

        if accuracy is None or training_time is None:
            print("Warning: Experiment was not added due to invalid numeric values")
            return False

        self.experiments.append(
            {
                "model_name": model_name,
                "accuracy": accuracy,
                "training_time": training_time,
            }
        )
        return True

    def calculate_average_accuracy(self):
        if not self.experiments:
            return 0.0

        total_accuracy = 0.0
        for experiment in self.experiments:
            total_accuracy += experiment["accuracy"]

        return total_accuracy / len(self.experiments)

    def find_fastest_model(self):
        if not self.experiments:
            return None

        fastest = self.experiments[0]
        for experiment in self.experiments[1:]:
            if experiment["training_time"] < fastest["training_time"]:
                fastest = experiment

        return fastest

    def print_summary_report(self):
        print("Experiment Summary Report")
        print("-" * 30)
        print(f"Total experiments: {len(self.experiments)}")

        average_accuracy = self.calculate_average_accuracy()
        print(f"Average accuracy: {average_accuracy:.2f}")

        fastest = self.find_fastest_model()
        if fastest:
            print(
                f"Fastest model: {fastest['model_name']} "
                f"({fastest['training_time']:.2f} seconds)"
            )
        else:
            print("Fastest model: No data available")

        print("\nAll Experiments:")
        if not self.experiments:
            print("No experiments to display")
            return

        for experiment in self.experiments:
            print(
                f"- Model: {experiment['model_name']}, "
                f"Accuracy: {experiment['accuracy']:.2f}, "
                f"Training Time: {experiment['training_time']:.2f} seconds"
            )


if __name__ == "__main__":
    sample_csv_path = "sample_experiments.csv"

    sample_csv_content = """model_name,accuracy,training_time
Linear Regression,0.82,12.5
Decision Tree,0.88,8.2
Random Forest,0.91,15.0
Bad Model,not_a_number,9.1
Missing Time,0.77,
"""

    with open(sample_csv_path, mode="w", encoding="utf-8") as file:
        file.write(sample_csv_content)

    results = ExperimentResults(sample_csv_path)

    results.add_experiment("Neural Network", 0.95, 20.3)
    results.add_experiment("Fast SVM", "0.89", "6.4")
    results.add_experiment("Broken Model", "", 10)

    results.print_summary_report()

from functools import lru_cache


def count_paths(rows, cols):
    """Return the number of unique paths in a rows x cols grid."""
    if rows <= 0 or cols <= 0:
        raise ValueError("rows and cols must be positive integers")

    @lru_cache(maxsize=None)
    def paths(r, c):
        # Base case: first row or first column has only one path
        if r == 1 or c == 1:
            return 1
        # Recursive case: paths from top + paths from left
        return paths(r - 1, c) + paths(r, c - 1)

    return paths(rows, cols)


def main():
    samples = [(2, 3), (3, 3), (4, 5), (10, 10)]
    for rows, cols in samples:
        print(f"Grid {rows}x{cols}: {count_paths(rows, cols)} unique paths")


if __name__ == "__main__":
    main()

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_word = False


class PrefixTrie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_word = True

    def search(self, word: str) -> bool:
        node = self._find_node(word)
        return node is not None and node.is_word

    def starts_with(self, prefix: str) -> bool:
        return self._find_node(prefix) is not None

    def words_with_prefix(self, prefix: str):
        start = self._find_node(prefix)
        if start is None:
            return []

        result = []
        self._collect_words(start, prefix, result)
        return result

    def _find_node(self, text: str):
        node = self.root
        for ch in text:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

    def _collect_words(self, node: TrieNode, path: str, result: list) -> None:
        if node.is_word:
            result.append(path)

        for ch in sorted(node.children):
            self._collect_words(node.children[ch], path + ch, result)


if __name__ == '__main__':
    trie = PrefixTrie()
    words = ['app', 'apple', 'apply', 'apt', 'bat', 'batch', 'bath']

    for word in words:
        trie.insert(word)

    print(trie.search('apple'))     # True
    print(trie.search('appl'))      # False
    print(trie.starts_with('app'))  # True
    print(trie.starts_with('cat'))  # False
    print(trie.words_with_prefix('ap'))   # ['app', 'apple', 'apply', 'apt']
    print(trie.words_with_prefix('bat'))  # ['bat', 'batch', 'bath']

class Router:
    def __init__(self):
        # Store routes in registration order.
        self._routes = []

    def add_route(self, pattern, handler):
        segments = self._split(pattern)
        dynamic_count = sum(1 for seg in segments if self._is_param(seg))
        self._routes.append({
            'pattern': pattern,
            'handler': handler,
            'segments': segments,
            'dynamic_count': dynamic_count,
        })

    def match(self, path):
        path_segments = self._split(path)

        # Prefer more specific routes: fewer dynamic segments first.
        sorted_routes = sorted(self._routes, key=lambda r: r['dynamic_count'])

        for route in sorted_routes:
            route_segments = route['segments']
            if len(route_segments) != len(path_segments):
                continue

            params = {}
            matched = True

            for route_seg, path_seg in zip(route_segments, path_segments):
                if self._is_param(route_seg):
                    param_name = route_seg[1:-1]
                    params[param_name] = path_seg
                elif route_seg != path_seg:
                    matched = False
                    break

            if matched:
                return {
                    'handler': route['handler'],
                    'params': params,
                }

        return None

    @staticmethod
    def _split(path):
        # Normalize leading/trailing slashes so '/users/42/' works like '/users/42'.
        stripped = path.strip('/')
        return [] if stripped == '' else stripped.split('/')

    @staticmethod
    def _is_param(segment):
        return segment.startswith('<') and segment.endswith('>') and len(segment) > 2


if __name__ == '__main__':
    router = Router()
    router.add_route('/about', 'about_handler')
    router.add_route('/users/<id>', 'user_detail')
    router.add_route('/users/settings', 'user_settings')
    router.add_route('/posts/<post_id>/comments/<comment_id>', 'comment_detail')

    tests = [
        '/about',
        '/users/42',
        '/users/settings',
        '/posts/10/comments/5',
        '/missing',
    ]

    for path in tests:
        print(path, '->', router.match(path))

import re
from collections import Counter
from itertools import tee


def tokenize(text):
    # Keep alphabetic words and simple contractions like don't
    return re.findall(r"[a-z]+(?:'[a-z]+)?", text.lower())


def bigrams(tokens):
    a, b = tee(tokens)
    next(b, None)
    return zip(a, b)


def main():
    text = """
    Natural language processing enables computers to analyze human language.
    Language models can summarize text, extract keywords, and detect patterns.
    In practice, good preprocessing improves text analysis by removing noise,
    normalizing tokens, and focusing on informative terms rather than common words.
    """

    stopwords = {
        'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'can', 'for', 'from',
        'good', 'in', 'is', 'it', 'of', 'on', 'or', 'rather', 'than', 'the',
        'to', 'with', 'this', 'that', 'into', 'their', 'them', 'words', 'common'
    }

    tokens = tokenize(text)
    filtered = [t for t in tokens if t not in stopwords]

    if not filtered:
        print('No tokens remain after stopword removal.')
        return

    word_counts = Counter(filtered)
    bigram_counts = Counter(bigrams(filtered))
    lexical_diversity = len(set(filtered)) / len(filtered)

    print('Top 10 words:')
    for word, count in word_counts.most_common(10):
        print(f'{word}: {count}')

    print('\nTop 5 bigrams:')
    for pair, count in bigram_counts.most_common(5):
        print(f'{pair[0]} {pair[1]}: {count}')

    print(f'\nLexical diversity: {lexical_diversity:.3f}')


if __name__ == '__main__':
    main()
}

import traceback


def run_jobs(jobs):
    """Execute zero-argument callables with recoverable and fatal error handling."""
    summary = {
        "results": [],
        "errors": [],
        "fatal": None,
    }

    for index, job in enumerate(jobs):
        try:
            if not callable(job):
                raise TypeError(f"Job at index {index} is not callable")

            result = job()
            summary["results"].append(result)

        except (ValueError, TypeError) as exc:
            # Recoverable errors: record and continue.
            summary["errors"].append({
                "index": index,
                "type": type(exc).__name__,
                "message": str(exc),
            })

        except Exception as exc:
            # Fatal errors: capture traceback and stop processing.
            summary["fatal"] = {
                "index": index,
                "type": type(exc).__name__,
                "message": str(exc),
                "traceback": traceback.format_exc(),
            }
            break

    return summary


# Example usage
if __name__ == "__main__":
    jobs = [
        lambda: 10,
        lambda: int("bad"),          # ValueError -> recoverable
        42,                           # non-callable -> TypeError -> recoverable
        lambda: "done",
        lambda: (_ for _ in ()).throw(RuntimeError("database offline")),  # fatal
        lambda: "never runs",
    ]

    from pprint import pprint
    pprint(run_jobs(jobs))

def process_numbers_file(filename):
    total = 0
    count = 0

    try:
        # Read the file one line at a time to avoid loading everything into memory.
        with open(filename, 'r', encoding='utf-8') as file:
            for line in file:
                line = line.strip()

                if not line:
                    continue  # Skip empty lines

                try:
                    number = int(line)
                    total += number
                    count += 1
                except ValueError:
                    continue  # Skip invalid integer lines

    except FileNotFoundError:
        print(f'File not found: {filename}')
        return

    if count == 0:
        print('No valid integers found in the file.')
        return

    average = total / count
    print(f'Count: {count}')
    print(f'Sum: {total}')
    print(f'Average: {average:.2f}')


