def fibonacci(n, cache):
    # Return cached result if already computed
    if n in cache:
        return cache[n]

    # Compute and store the result recursively
    cache[n] = fibonacci(n - 1, cache) + fibonacci(n - 2, cache)
    return cache[n]


def main():
    # Base cases are pre-filled in the cache
    cache = {0: 0, 1: 1}

    try:
        n = int(input('Enter a non-negative integer: '))
        if n < 0:
            print('Please enter a non-negative integer.')
            return
    except ValueError:
        print('Invalid input. Please enter a whole number.')
        return

    result = fibonacci(n, cache)
    print(f'Fibonacci({n}) = {result}')
    print(f'Cached values: {len(cache)}')


if __name__ == '__main__':
    main()

class ValidationError(Exception):
    """Base class for registration validation errors."""


class UsernameError(ValidationError):
    """Raised when the username is invalid."""


class PasswordError(ValidationError):
    """Raised when the password is invalid."""


class AgeError(ValidationError):
    """Raised when the age is invalid."""


def validate_registration(username, password, age):
    """Validate registration fields and raise specific exceptions on failure."""
    if len(username) < 3 or " " in username:
        raise UsernameError("Username must be at least 3 characters long and contain no spaces.")

    if len(password) < 8 or not any(char.isdigit() for char in password):
        raise PasswordError("Password must be at least 8 characters long and include at least one digit.")

    if age < 18:
        raise AgeError("User must be at least 18 years old.")

    return f"Registration successful for user '{username}'."


