import time
from typing import Any, Callable, Dict, List

Request = Dict[str, Any]
Response = Dict[str, Any]
Middleware = Callable[[Request, Callable[[Request], Response]], Response]
Handler = Callable[[Request], Response]


class Pipeline:
    def __init__(self) -> None:
        self._middleware: List[Middleware] = []

    def use(self, middleware: Middleware) -> None:
        self._middleware.append(middleware)

    def run(self, request: Request, final_handler: Handler) -> Response:
        def build_chain(index: int) -> Handler:
            if index == len(self._middleware):
                return final_handler

            def current(req: Request) -> Response:
                return self._middleware[index](req, build_chain(index + 1))

            return current

        return build_chain(0)(request)


def timing_middleware(request: Request, next_handler: Handler) -> Response:
    start = time.perf_counter()
    response = next_handler(request)
    response["duration_ms"] = round((time.perf_counter() - start) * 1000, 3)
    return response


def auth_middleware(request: Request, next_handler: Handler) -> Response:
    if request.get("token") != "secret-token":
        return {"status": 401, "error": "unauthorized"}
    return next_handler(request)


def uppercase_middleware(request: Request, next_handler: Handler) -> Response:
    modified = dict(request)
    if "message" in modified and isinstance(modified["message"], str):
        modified["message"] = modified["message"].upper()
    response = next_handler(modified)
    if "result" in response and isinstance(response["result"], str):
        response["result"] = f"[PROCESSED] {response['result']}"
    return response


def final_handler(request: Request) -> Response:
    return {
        "status": 200,
        "result": f"Handled message: {request.get('message', '')}"
    }


if __name__ == "__main__":
    pipeline = Pipeline()
    pipeline.use(timing_middleware)
    pipeline.use(auth_middleware)
    pipeline.use(uppercase_middleware)

    requests = [
        {"message": "hello pipeline", "token": "secret-token"},
        {"message": "blocked request", "token": "wrong-token"},
    ]

    for req in requests:
        print(pipeline.run(req, final_handler))

class TextPlugin:
    """Base class for text processing plugins."""

    name = "base"

    def process(self, text):
        raise NotImplementedError("Plugins must implement process()")


class UppercasePlugin(TextPlugin):
    name = "uppercase"

    def process(self, text):
        return text.upper()


class ReversePlugin(TextPlugin):
    name = "reverse"

    def process(self, text):
        return text[::-1]


class PluginManager:
    """Registers and runs text plugins."""

    def __init__(self):
        self.plugins = []

    def register(self, plugin):
        self.plugins.append(plugin)

    def run_all(self, text):
        results = {}
        for plugin in self.plugins:
            results[plugin.name] = plugin.process(text)
        return results


# Demo usage
if __name__ == "__main__":
    manager = PluginManager()
    manager.register(UppercasePlugin())
    manager.register(ReversePlugin())

    sample_text = "Hello plugins"
    results = manager.run_all(sample_text)

    for plugin_name, output in results.items():
        print(f"{plugin_name}: {output}")

import pytest
from unittest.mock import Mock


def fetch_user_profile(client, user_id, retries=3):
    """Fetch a user profile with retry logic for transient server errors."""
    attempts = retries + 1  # initial attempt + retries
    last_status = None

    for _ in range(attempts):
        response = client.get(f"/users/{user_id}")
        last_status = response.status_code

        if response.status_code == 200:
            return response.json()
        if response.status_code == 404:
            raise ValueError(f"User {user_id} not found")
        if response.status_code != 500:
            raise RuntimeError(f"Unexpected status: {response.status_code}")

    raise RuntimeError(f"Failed after retries, last status: {last_status}")


class FakeResponse:
    def __init__(self, status_code, payload=None):
        self.status_code = status_code
        self._payload = payload or {}

    def json(self):
        return self._payload


@pytest.mark.parametrize(
    "statuses,retries,expected_calls,expected_result,expected_exception",
    [
        ([200], 3, 1, {"id": 1, "name": "Ada"}, None),
        ([500, 500, 200], 3, 3, {"id": 1, "name": "Ada"}, None),
        ([500, 500, 500, 500], 3, 4, None, RuntimeError),
        ([404], 3, 1, None, ValueError),
    ],
)
def test_fetch_user_profile_behaviors(
    statuses, retries, expected_calls, expected_result, expected_exception
):
    payload = {"id": 1, "name": "Ada"}
    responses = [FakeResponse(status, payload if status == 200 else None) for status in statuses]

    client = Mock()
    client.get = Mock(side_effect=responses)

    if expected_exception:
        with pytest.raises(expected_exception):
            fetch_user_profile(client, 1, retries=retries)
    else:
        result = fetch_user_profile(client, 1, retries=retries)
        assert result == expected_result

    assert client.get.call_count == expected_calls
    client.get.assert_called_with("/users/1")


def test_404_does_not_consume_additional_responses():
    client = Mock()
    client.get = Mock(side_effect=[FakeResponse(404), FakeResponse(200, {"id": 1})])

    with pytest.raises(ValueError):
        fetch_user_profile(client, 1, retries=5)

    # Ensure no retry happened after 404
    assert client.get.call_count == 1

