from typing import Dict, Tuple


def read_varint(data: bytes, pos: int) -> Tuple[int, int]:
    """Read a protobuf varint starting at pos."""
    result = 0
    shift = 0
    while True:
        if pos >= len(data):
            raise ValueError('Unexpected end of data while reading varint')
        b = data[pos]
        pos += 1
        result |= (b & 0x7F) << shift
        if not (b & 0x80):
            return result, pos
        shift += 7
        if shift >= 64:
            raise ValueError('Varint too long')


def write_varint(value: int) -> bytes:
    """Encode an integer as a protobuf varint."""
    if value < 0:
        raise ValueError('This demo only supports non-negative varints')
    out = bytearray()
    while True:
        b = value & 0x7F
        value >>= 7
        if value:
            out.append(b | 0x80)
        else:
            out.append(b)
            return bytes(out)


def parse_entry(data: bytes) -> Dict[str, int]:
    """Parse a single Entry message with fields: 1=key(string), 2=value(int32)."""
    pos = 0
    key = None
    value = None

    while pos < len(data):
        tag, pos = read_varint(data, pos)
        field_number = tag >> 3
        wire_type = tag & 0x07

        if field_number == 1 and wire_type == 2:  # key: length-delimited string
            length, pos = read_varint(data, pos)
            key = data[pos:pos + length].decode('utf-8')
            pos += length
        elif field_number == 2 and wire_type == 0:  # value: varint int32
            value, pos = read_varint(data, pos)
        else:
            raise ValueError(f'Unsupported field in Entry: field={field_number}, wire={wire_type}')

    if key is None or value is None:
        raise ValueError('Entry is missing key or value')

    return {key: value}


def parse_map_message(data: bytes) -> Dict[str, int]:
    """Parse a top-level message with repeated field 1 containing Entry messages."""
    pos = 0
    result = {}

    while pos < len(data):
        tag, pos = read_varint(data, pos)
        field_number = tag >> 3
        wire_type = tag & 0x07

        if field_number == 1 and wire_type == 2:
            length, pos = read_varint(data, pos)
            entry_bytes = data[pos:pos + length]
            pos += length
            result.update(parse_entry(entry_bytes))
        else:
            raise ValueError(f'Unsupported top-level field: field={field_number}, wire={wire_type}')

    return result


def build_entry(key: str, value: int) -> bytes:
    """Build a single Entry message."""
    key_bytes = key.encode('utf-8')
    entry = bytearray()
    entry += write_varint((1 << 3) | 2)  # field 1, length-delimited
    entry += write_varint(len(key_bytes))
    entry += key_bytes
    entry += write_varint((2 << 3) | 0)  # field 2, varint
    entry += write_varint(value)
    return bytes(entry)


def build_map_message(items: Dict[str, int]) -> bytes:
    """Build the top-level message with repeated Entry messages."""
    out = bytearray()
    for key, value in items.items():
        entry = build_entry(key, value)
        out += write_varint((1 << 3) | 2)  # field 1, length-delimited
        out += write_varint(len(entry))
        out += entry
    return bytes(out)


if __name__ == '__main__':
    demo_items = {'apples': 3, 'bananas': 7, 'pears': 2}
    message = build_map_message(demo_items)
    parsed = parse_map_message(message)
    print(parsed)

from abc import ABC, abstractmethod


class Notifier(ABC):
    @property
    @abstractmethod
    def channel(self) -> str:
        """Unique channel name for this notifier."""
        raise NotImplementedError

    @abstractmethod
    def send(self, recipient: str, message: str) -> str:
        """Send a message to a recipient and return a status string."""
        raise NotImplementedError


class EmailNotifier(Notifier):
    @property
    def channel(self) -> str:
        return "email"

    def send(self, recipient: str, message: str) -> str:
        return f"Email sent to {recipient}: {message}"


class SMSNotifier(Notifier):
    @property
    def channel(self) -> str:
        return "sms"

    def send(self, recipient: str, message: str) -> str:
        return f"SMS sent to {recipient}: {message}"


class NotificationManager:
    def __init__(self, notifiers: list[Notifier]):
        self._notifiers = {}
        for notifier in notifiers:
            if notifier.channel in self._notifiers:
                raise ValueError(f"Duplicate notifier channel: {notifier.channel}")
            self._notifiers[notifier.channel] = notifier

    def notify(self, channel: str, recipient: str, message: str) -> str:
        notifier = self._notifiers.get(channel)
        if notifier is None:
            raise ValueError(f"Unknown notification channel: {channel}")
        return notifier.send(recipient, message)


if __name__ == "__main__":
    manager = NotificationManager([EmailNotifier(), SMSNotifier()])

    print(manager.notify("email", "alice@example.com", "Your report is ready."))
    print(manager.notify("sms", "+15551234567", "Your code is 4821."))

from itertools import islice


def chunked_running_average(numbers, chunk_size):
    """Yield the average of each chunk from the input iterable lazily."""
    if chunk_size < 1:
        raise ValueError("chunk_size must be at least 1")

    it = iter(numbers)  # Support any iterable, including generators

    while True:
        chunk = list(islice(it, chunk_size))
        if not chunk:
            break
        yield sum(chunk) / len(chunk)


def main():
    data = [10, 20, 30, 40, 50, 60, 70]
    averages = chunked_running_average(data, 3)

    print("Chunk averages:")
    for avg in averages:
        print(avg)


if __name__ == "__main__":
    main()

