}

permissions = {
    'delete_post': ['admin'],
    'edit_post': ['admin', 'editor'],
    'view_post': ['admin', 'editor', 'viewer']
}


def login(username, password):
    """Return user role if login is successful, otherwise return None."""
    user = users.get(username)
    if not user:
        print(f"Login failed: user '{username}' does not exist.")
        return None

    if user['password'] != password:
        print(f"Login failed: incorrect password for '{username}'.")
        return None

    print(f"Login successful: '{username}' logged in as {user['role']}.")
    return user['role']



def is_authorized(role, action):
    """Check whether a role is allowed to perform an action."""
    allowed_roles = permissions.get(action, [])
    return role in allowed_roles


# Demonstration of authentication and authorization
