import random
import time
from enum import Enum
from typing import Any, Callable, Optional


class CircuitOpenError(Exception):
    pass


class CircuitState(Enum):
    CLOSED = "closed"
    OPEN = "open"
    HALF_OPEN = "half_open"


class CircuitBreaker:
    def __init__(self, failure_threshold: int = 3, recovery_timeout: float = 2.0):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.state = CircuitState.CLOSED
        self.failure_count = 0
        self.opened_at: Optional[float] = None

    def before_call(self) -> None:
        if self.state == CircuitState.OPEN:
            if time.monotonic() - self.opened_at >= self.recovery_timeout:
                self.state = CircuitState.HALF_OPEN
            else:
                raise CircuitOpenError("Circuit is open; calls are temporarily blocked")

    def record_success(self) -> None:
        self.failure_count = 0
        self.state = CircuitState.CLOSED
        self.opened_at = None

    def record_failure(self) -> None:
        if self.state == CircuitState.HALF_OPEN:
            self._trip()
            return
        self.failure_count += 1
        if self.failure_count >= self.failure_threshold:
            self._trip()

    def _trip(self) -> None:
        self.state = CircuitState.OPEN
        self.opened_at = time.monotonic()


def retry_call(
    func: Callable[..., Any],
    *args: Any,
    retries: int = 5,
    base_delay: float = 0.1,
    max_delay: float = 2.0,
    jitter: float = 0.05,
    breaker: Optional[CircuitBreaker] = None,
    **kwargs: Any,
) -> Any:
    last_error: Optional[Exception] = None

    for attempt in range(retries + 1):
        if breaker:
            breaker.before_call()
        try:
            result = func(*args, **kwargs)
            if breaker:
                breaker.record_success()
            return result
        except Exception as exc:
            last_error = exc
            if breaker:
                breaker.record_failure()
            if attempt == retries:
                break
            delay = min(base_delay * (2 ** attempt), max_delay)
            delay += random.uniform(0, jitter)
            time.sleep(delay)

    raise last_error if last_error else RuntimeError("retry_call failed unexpectedly")


def main() -> None:
    breaker = CircuitBreaker(failure_threshold=3, recovery_timeout=1.0)

    def flaky_operation() -> str:
        if random.random() < 0.7:
            raise ValueError("Transient service failure")
        return "success"

    try:
        result = retry_call(flaky_operation, retries=6, breaker=breaker)
        print(f"Result: {result}")
    except Exception as exc:
        print(f"Final failure: {type(exc).__name__}: {exc}")


if __name__ == "__main__":
    main()
}

import hashlib
import hmac
import json
import time
from typing import Dict, Tuple, Any

# In-memory deduplication store for processed event IDs.
# In a real system, this would be persistent/shared storage.
_PROCESSED_EVENTS = set()


def handle_webhook(headers: Dict[str, str], body: str, secret: str, tolerance: int = 300) -> Tuple[int, Dict[str, Any]]:
    """Validate and process a webhook request.

    Args:
        headers: Request headers containing X-Signature and X-Timestamp.
        body: Raw request body as an exact string.
        secret: Shared webhook signing secret.
        tolerance: Maximum allowed age of the request in seconds.

    Returns:
        (status_code, response_dict)
    """
    # Extract required headers.
    signature = headers.get("X-Signature")
    timestamp_raw = headers.get("X-Timestamp")
    if not signature or not timestamp_raw:
        return 400, {"error": "missing required headers"}

    # Validate timestamp format and replay window.
    try:
        timestamp = int(timestamp_raw)
    except (TypeError, ValueError):
        return 400, {"error": "invalid timestamp header"}

    now = int(time.time())
    if timestamp > now or now - timestamp > tolerance:
        return 401, {"error": "stale or future timestamp"}

    # Validate HMAC signature against the exact raw body.
    expected = hmac.new(secret.encode("utf-8"), body.encode("utf-8"), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        return 401, {"error": "invalid signature"}

    # Parse JSON payload.
    try:
        payload = json.loads(body)
    except json.JSONDecodeError:
        return 400, {"error": "invalid JSON body"}

    # Validate required fields.
    required_fields = ("event_id", "type", "data")
    if not all(field in payload for field in required_fields):
        return 422, {"error": "missing required fields"}

    event_id = payload["event_id"]
    if not isinstance(event_id, str) or not event_id.strip():
        return 422, {"error": "event_id must be a non-empty string"}

    # Deduplicate events.
    if event_id in _PROCESSED_EVENTS:
        return 409, {"error": "duplicate event", "event_id": event_id}

    # Mark as processed only after all validations pass.
    _PROCESSED_EVENTS.add(event_id)

    return 200, {
        "ok": True,
        "event_id": event_id,
        "type": payload["type"],
        "received_at": now,
    }


if __name__ == "__main__":
    # Example usage.
    secret = "supersecret"
    body = json.dumps({"event_id": "evt_123", "type": "payment.succeeded", "data": {"amount": 5000}})
    headers = {
        "X-Timestamp": str(int(time.time())),
        "X-Signature": hmac.new(secret.encode("utf-8"), body.encode("utf-8"), hashlib.sha256).hexdigest(),
    }

    status, response = handle_webhook(headers, body, secret)
    print(status, response)

import configparser
import os
from pathlib import Path


def merge_ini_configs(base_path, override_path):
    """Load, merge, and expand environment variables in two INI files."""
    base_path = Path(base_path)
    override_path = Path(override_path)

    if not base_path.is_file():
        raise FileNotFoundError(f"Base config not found: {base_path}")
    if not override_path.is_file():
        raise FileNotFoundError(f"Override config not found: {override_path}")

    # Disable built-in interpolation; we only want environment expansion.
    base_cfg = configparser.ConfigParser(interpolation=None)
    override_cfg = configparser.ConfigParser(interpolation=None)

    # Preserve original key casing.
    base_cfg.optionxform = str
    override_cfg.optionxform = str

    base_cfg.read(base_path)
    override_cfg.read(override_path)

    merged = configparser.ConfigParser(interpolation=None)
    merged.optionxform = str

    # Merge DEFAULT values first.
    for key, value in base_cfg.defaults().items():
        merged['DEFAULT'][key] = value
    for key, value in override_cfg.defaults().items():
        merged['DEFAULT'][key] = value

    # Copy base sections and keys.
    for section in base_cfg.sections():
        merged.add_section(section)
        for key, value in base_cfg.items(section, raw=True):
            merged.set(section, key, value)

    # Apply overrides, adding new sections if needed.
    for section in override_cfg.sections():
        if not merged.has_section(section):
            merged.add_section(section)
        for key, value in override_cfg.items(section, raw=True):
            merged.set(section, key, value)

    # Convert to nested dict and expand environment variables.
    result = {'DEFAULT': {}}
    for key, value in merged.defaults().items():
        result['DEFAULT'][key] = os.path.expandvars(value)

    for section in merged.sections():
        result[section] = {}
        for key, value in merged.items(section, raw=True):
            result[section][key] = os.path.expandvars(value)

    return result

class FibonacciCache:
    def __init__(self):
        # Base cases are preloaded into the cache.
        self.cache = {0: 0, 1: 1}
        self.hits = 0
        self.misses = 0

    def cached_fibonacci(self, n):
        if n < 0:
            raise ValueError('n must be non-negative')

        if n in self.cache:
            self.hits += 1
            return self.cache[n]

        self.misses += 1
        # Recursive computation uses the same cache for efficiency.
        self.cache[n] = self.cached_fibonacci(n - 1) + self.cached_fibonacci(n - 2)
        return self.cache[n]


def main():
    fib = FibonacciCache()
    inputs = [10, 15, 10, 20, 15, 25]

    for n in inputs:
        result = fib.cached_fibonacci(n)
        print(f'fib({n}) = {result}')

    print(f'Cache hits: {fib.hits}')
    print(f'Cache misses: {fib.misses}')
    print(f'Cached values: {len(fib.cache)} entries')


if __name__ == '__main__':
    main()

