from typing import Any, Dict, List, Optional

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field, ValidationError, field_validator


class PredictionRecord(BaseModel):
    model_id: str = Field(..., min_length=1)
    timestamp: datetime
    predicted_label: str = Field(..., min_length=1)
    actual_label: str = Field(..., min_length=1)
    confidence_score: float

    @field_validator("model_id", "predicted_label", "actual_label")
    @classmethod
    def validate_non_empty_string(cls, value: str) -> str:
        if not isinstance(value, str) or not value.strip():
            raise ValueError("must be a non-empty string")
        return value.strip()

    @field_validator("confidence_score")
    @classmethod
    def validate_confidence_score(cls, value: float) -> float:
        if not isinstance(value, (int, float)):
            raise ValueError("confidence_score must be a number")
        value = float(value)
        if not 0.0 <= value <= 1.0:
            raise ValueError("confidence_score must be between 0.0 and 1.0")
        return value


class SummaryRequest(BaseModel):
    records: List[Dict[str, Any]]
    accuracy_threshold: float = Field(0.8, ge=0.0, le=1.0)


class InvalidRecord(BaseModel):
    index: int
    errors: List[str]
    raw_record: Any


class ModelSummary(BaseModel):
    model_id: str
    total_predictions: int
    accuracy: float
    average_confidence: float
    marked_for_review: bool


class SummaryResponse(BaseModel):
    summaries: List[ModelSummary]
    invalid_records: List[InvalidRecord]
    total_valid_records: int
    total_invalid_records: int


def summarize_prediction_records(
    records: List[Dict[str, Any]],
    accuracy_threshold: float = 0.8,
) -> SummaryResponse:
    if not isinstance(records, list):
        raise ValueError("records must be a list")
    if not isinstance(accuracy_threshold, (int, float)):
        raise ValueError("accuracy_threshold must be a number")
    if not 0.0 <= float(accuracy_threshold) <= 1.0:
        raise ValueError("accuracy_threshold must be between 0.0 and 1.0")

    grouped: Dict[str, Dict[str, float]] = {}
    invalid_records: List[InvalidRecord] = []
    valid_count = 0

    for index, raw_record in enumerate(records):
        if not isinstance(raw_record, dict):
            invalid_records.append(
                InvalidRecord(
                    index=index,
                    errors=["record must be a dictionary"],
                    raw_record=raw_record,
                )
            )
            continue

        try:
            record = PredictionRecord.model_validate(raw_record)
        except ValidationError as exc:
            invalid_records.append(
                InvalidRecord(
                    index=index,
                    errors=[
                        f"{'.'.join(str(part) for part in err['loc'])}: {err['msg']}"
                        for err in exc.errors()
                    ],
                    raw_record=raw_record,
                )
            )
            continue

        valid_count += 1
        model_stats = grouped.setdefault(
            record.model_id,
            {"total": 0.0, "correct": 0.0, "confidence_sum": 0.0},
        )
        model_stats["total"] += 1
        model_stats["confidence_sum"] += record.confidence_score
        if record.predicted_label == record.actual_label:
            model_stats["correct"] += 1

    summaries: List[ModelSummary] = []
    for model_id, stats in sorted(grouped.items(), key=lambda item: item[0]):
        total_predictions = int(stats["total"])
        accuracy = stats["correct"] / stats["total"] if stats["total"] else 0.0
        average_confidence = (
            stats["confidence_sum"] / stats["total"] if stats["total"] else 0.0
        )
        summaries.append(
            ModelSummary(
                model_id=model_id,
                total_predictions=total_predictions,
                accuracy=round(accuracy, 4),
                average_confidence=round(average_confidence, 4),
                marked_for_review=accuracy < float(accuracy_threshold),
            )
        )

    return SummaryResponse(
        summaries=summaries,
        invalid_records=invalid_records,
        total_valid_records=valid_count,
        total_invalid_records=len(invalid_records),
    )


app = FastAPI(title="AI/ML Prediction Summary API", version="1.0.0")


@app.post("/models/predictions/summary", response_model=SummaryResponse)
def create_prediction_summary(payload: SummaryRequest) -> SummaryResponse:
    try:
        return summarize_prediction_records(
            records=payload.records,
            accuracy_threshold=payload.accuracy_threshold,
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc))


if __name__ == "__main__":
    sample_records: List[Dict[str, Any]] = [
        {
            "model_id": "model_a",
            "timestamp": "2026-04-01T10:00:00",
            "predicted_label": "cat",
            "actual_label": "cat",
            "confidence_score": 0.95,
        },
        {
            "model_id": "model_a",
            "timestamp": "2026-04-01T10:05:00",
            "predicted_label": "dog",
            "actual_label": "cat",
            "confidence_score": 0.72,
        },
        {
            "model_id": "model_b",
            "timestamp": "2026-04-01T11:00:00",
            "predicted_label": "spam",
            "actual_label": "spam",
            "confidence_score": 0.88,
        },
        {
            "model_id": "",
            "timestamp": "invalid-date",
            "predicted_label": "x",
            "actual_label": "x",
            "confidence_score": 1.2,
        },
        "malformed_record",
    ]

    result = summarize_prediction_records(sample_records, accuracy_threshold=0.75)
