import hmac
import json
import time
import hashlib
import threading
from typing import Dict, Any


_seen_event_ids = set()
_seen_lock = threading.Lock()


def _error(status: int, message: str) -> Dict[str, Any]:
    return {"ok": False, "status": status, "error": message}


def handle_webhook(headers: dict, body: bytes, secret: str, replay_window: int = 300) -> dict:
    # Validate required headers.
    required = ("X-Signature", "X-Timestamp", "X-Event-Id")
    missing = [name for name in required if name not in headers]
    if missing:
        return _error(400, f"missing headers: {', '.join(missing)}")

    signature = str(headers["X-Signature"])
    event_id = str(headers["X-Event-Id"])

    # Timestamp must be an integer and within the replay window.
    try:
        timestamp = int(str(headers["X-Timestamp"]))
    except (TypeError, ValueError):
        return _error(400, "invalid timestamp")

    now = int(time.time())
    if abs(now - timestamp) > replay_window:
        return _error(401, "timestamp outside replay window")

    # Verify HMAC over the exact bytes: b"{timestamp}." + body
    signed_payload = f"{timestamp}.".encode("utf-8") + body
    expected = hmac.new(secret.encode("utf-8"), signed_payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        return _error(401, "invalid signature")

    # Enforce idempotency in a thread-safe way.
    with _seen_lock:
        if event_id in _seen_event_ids:
            return _error(409, "duplicate event")
        _seen_event_ids.add(event_id)

    # Parse JSON and validate schema.
    try:
        payload = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        with _seen_lock:
            _seen_event_ids.discard(event_id)
        return _error(400, "invalid JSON body")

    if not isinstance(payload, dict) or "type" not in payload or "data" not in payload:
        with _seen_lock:
            _seen_event_ids.discard(event_id)
        return _error(422, "body must contain 'type' and 'data'")

    event = {
        "id": event_id,
        "timestamp": timestamp,
        "type": payload["type"],
        "data": payload["data"],
    }
    return {"ok": True, "status": 200, "event": event}

from dataclasses import dataclass, field
from typing import List, Optional


@dataclass
class Item:
    name: str
    price: float
    quantity: int


@dataclass
class Inventory:
    items: List[Item] = field(default_factory=list)

    def add_item(self, item: Item) -> None:
        """Add a new item to the inventory."""
        self.items.append(item)

    def total_value(self) -> float:
        """Calculate the total value of all items in stock."""
        return sum(item.price * item.quantity for item in self.items)

    def low_stock_items(self, threshold: int) -> List[str]:
        """Return names of items with quantity below the threshold."""
        return [item.name for item in self.items if item.quantity < threshold]

    def most_expensive_item(self) -> Optional[Item]:
        """Return the item with the highest unit price, or None if empty."""
        if not self.items:
            return None
        return max(self.items, key=lambda item: item.price)


def main() -> None:
    inventory = Inventory()
    inventory.add_item(Item(name="Notebook", price=2.5, quantity=40))
    inventory.add_item(Item(name="Pen", price=1.2, quantity=12))
    inventory.add_item(Item(name="Backpack", price=35.0, quantity=5))
    inventory.add_item(Item(name="Calculator", price=18.75, quantity=3))

    print(f"Total inventory value: ${inventory.total_value():.2f}")
    print("Low stock items:", inventory.low_stock_items(threshold=10))

    most_expensive = inventory.most_expensive_item()
    if most_expensive is not None:
        print(
            f"Most expensive item: {most_expensive.name} (${most_expensive.price:.2f})"
        )


if __name__ == "__main__":
    main()

from typing import List, Tuple, Union

Operation = Union[Tuple[str, int], Tuple[str, int, int]]


def lower_bound(arr: List[int], target: int) -> int:
    """Return the first index where arr[index] >= target."""
    left, right = 0, len(arr)
    while left < right:
        mid = (left + right) // 2
        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left


def upper_bound(arr: List[int], target: int) -> int:
    """Return the first index where arr[index] > target."""
    left, right = 0, len(arr)
    while left < right:
        mid = (left + right) // 2
        if arr[mid] <= target:
            left = mid + 1
        else:
            right = mid
    return left


class SortedEventIndex:
    def __init__(self) -> None:
        self.data: List[int] = []

    def add(self, value: int) -> None:
        # Insert while preserving sorted order using binary search.
        pos = lower_bound(self.data, value)
        self.data.insert(pos, value)

    def count_range(self, low: int, high: int) -> int:
        if low > high:
            return 0
        start = lower_bound(self.data, low)
        end = upper_bound(self.data, high)
        return end - start


def process_operations(operations: List[Operation]) -> List[int]:
    """Execute add/count operations and return results of count queries."""
    index = SortedEventIndex()
    results: List[int] = []

    for op in operations:
        if op[0] == 'add':
            _, value = op
            index.add(value)
        elif op[0] == 'count':
            _, low, high = op
            results.append(index.count_range(low, high))
        else:
            raise ValueError(f'Unknown operation: {op[0]}')

    return results


if __name__ == '__main__':
    ops: List[Operation] = [
        ('add', 10),
        ('add', 3),
        ('add', 7),
        ('add', 7),
        ('add', 15),
        ('count', 1, 7),   # 3 values: 3, 7, 7
        ('count', 8, 20),  # 2 values: 10, 15
        ('count', 7, 7),   # 2 values: 7, 7
    ]
    print(process_operations(ops))

import re
import sys
from collections import Counter


def iter_words(file_path):
    """Yield lowercase alphabetic words from a file line by line."""
    word_pattern = re.compile(r"[A-Za-z]+")
    with open(file_path, "r", encoding="utf-8", errors="ignore") as f:
        for line in f:
            for match in word_pattern.finditer(line):
                yield match.group(0).lower()


def top_words(file_path, limit=10):
    """Count words without loading the full file into memory."""
    counts = Counter()
    for word in iter_words(file_path):
        counts[word] += 1

    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:limit]


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <input_file>", file=sys.stderr)
        sys.exit(1)

    file_path = sys.argv[1]

    try:
        results = top_words(file_path)
    except OSError as e:
        print(f"Error reading file: {e}", file=sys.stderr)
        sys.exit(1)

    for word, count in results:
        print(f"{word} {count}")


if __name__ == "__main__":
    main()

import re
from typing import Dict, List, Optional, Tuple


class Router:
    def __init__(self) -> None:
        self._routes: List[Tuple[re.Pattern, str, List[str]]] = []

    def add_route(self, pattern: str, handler_name: str) -> None:
        # Find dynamic parameter names like <id> or <post_id>
        param_names = re.findall(r'<([a-zA-Z_][a-zA-Z0-9_]*)>', pattern)

        # Escape the pattern, then replace escaped dynamic parts with regex groups
        regex_pattern = re.escape(pattern)
        regex_pattern = re.sub(
            r'\\<([a-zA-Z_][a-zA-Z0-9_]*)\\>',
            r'([^/]+)',
            regex_pattern,
        )

        # Match the entire path exactly
        compiled = re.compile(f'^{regex_pattern}$')
        self._routes.append((compiled, handler_name, param_names))

    def resolve(self, path: str) -> Optional[Tuple[str, Dict[str, str]]]:
        for regex, handler_name, param_names in self._routes:
            match = regex.match(path)
            if not match:
                continue

            params = {
                name: value
                for name, value in zip(param_names, match.groups())
            }
            return handler_name, params

        return None


if __name__ == '__main__':
    router = Router()
    router.add_route('/users', 'list_users')
    router.add_route('/users/<id>', 'get_user')
    router.add_route('/posts/<post_id>/comments/<comment_id>', 'get_comment')

    test_paths = [
        '/users',
        '/users/42',
        '/posts/10/comments/5',
        '/unknown',
    ]

    for path in test_paths:
        print(f'{path} -> {router.resolve(path)}')

from typing import Any, Dict, List


def classify_patient_risk(patient_records: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    results = []

    for record in patient_records:
        if not isinstance(record, dict):
            continue

        name = record.get("name")
        fever = record.get("fever")
        cough = record.get("cough")
        fatigue = record.get("fatigue")

        if not isinstance(name, str) or not name.strip():
            continue

        scores = [fever, cough, fatigue]

        if any(score is None for score in scores):
            continue

        if not all(isinstance(score, (int, float)) for score in scores):
            continue

        if not all(0 <= score <= 10 for score in scores):
            continue

        total_score = sum(scores)

        if 0 <= total_score <= 9:
            risk_level = "Low Risk"
        elif 10 <= total_score <= 19:
            risk_level = "Moderate Risk"
        elif 20 <= total_score <= 30:
            risk_level = "High Risk"
        else:
            continue

        results.append(
            {
                "name": name.strip(),
                "total_score": total_score,
                "risk_level": risk_level,
            }
        )

    return results


if __name__ == "__main__":
    sample_patients = [
        {"name": "Alice", "fever": 2, "cough": 3, "fatigue": 1},
        {"name": "Bob", "fever": 5, "cough": 4, "fatigue": 3},
        {"name": "Charlie", "fever": 8, "cough": 7, "fatigue": 6},
        {"name": "Dana", "fever": 11, "cough": 2, "fatigue": 1},   # Invalid
        {"name": "Evan", "fever": 4, "cough": None, "fatigue": 2},  # Invalid
    ]

    classified_results = classify_patient_risk(sample_patients)

    for patient in classified_results:
        print(patient)

from typing import List, Tuple


def min_partition_difference(nums: List[int]) -> Tuple[int, List[int], List[int]]:
    # dp[sum] = bitmask of used indices to achieve this sum
    total = sum(nums)
    n = len(nums)
    if n < 2:
        raise ValueError('nums must contain at least two elements')

    dp = {0: 0}

    for i, num in enumerate(nums):
        current = list(dp.items())
        bit = 1 << i
        for s, mask in current:
            new_sum = s + num
            if new_sum not in dp:
                dp[new_sum] = mask | bit

    best_sum = None
    min_diff = float('inf')

    # Avoid empty/full subset by rejecting masks with all or no elements used
    full_mask = (1 << n) - 1
    for s, mask in dp.items():
        if mask == 0 or mask == full_mask:
            continue
        diff = abs(total - 2 * s)
        if diff < min_diff:
            min_diff = diff
            best_sum = s

    if best_sum is None:
        raise ValueError('Could not form two non-empty subsets')

    mask = dp[best_sum]
    subset1, subset2 = [], []
    for i, num in enumerate(nums):
        if mask & (1 << i):
            subset1.append(num)
        else:
            subset2.append(num)

    return min_diff, subset1, subset2


if __name__ == '__main__':
    nums = [3, 1, 4, 2, 2, 1]
    result = min_partition_difference(nums)
    print(result)

from datetime import datetime, timezone
import re


def is_valid_email(email: str) -> bool:
    """Basic email validation for migration purposes."""
    return bool(re.match(r'^[^@\s]+@[^@\s]+\.[^@\s]+$', email or ''))


def split_name(full_name: str):
    """Split full name into first and last name."""
    parts = full_name.strip().split()
    if len(parts) < 2:
        return None, None
    return parts[0], ' '.join(parts[1:])


def convert_signup_ts(ts):
    """Convert Unix timestamp to ISO date string in UTC."""
    if ts is None:
        return None
    return datetime.fromtimestamp(ts, tz=timezone.utc).date().isoformat()


def migrate_users(old_records):
    migrated = []
    skipped = 0

    for record in old_records:
        # Check required fields
        required = ('user_id', 'full_name', 'email')
        if not all(field in record and record[field] for field in required):
            skipped += 1
            continue

        if not is_valid_email(record['email']):
            skipped += 1
            continue

        first_name, last_name = split_name(record['full_name'])
        if not first_name or not last_name:
            skipped += 1
            continue

        try:
            new_record = {
                'id': int(record['user_id']),
                'first_name': first_name,
                'last_name': last_name,
                'email': record['email'].lower(),
                'signup_date': convert_signup_ts(record.get('signup_ts')),
            }
        except (ValueError, TypeError, OSError):
            skipped += 1
            continue

        migrated.append(new_record)

    print(f'Migration complete: migrated={len(migrated)}, skipped={skipped}')
    return migrated


if __name__ == '__main__':
    old_users = [
        {'user_id': '101', 'full_name': 'Alice Johnson', 'email': 'ALICE@EXAMPLE.COM', 'signup_ts': 1704067200},
        {'user_id': '102', 'full_name': 'Bob Smith', 'email': 'bob.smith@example.com'},
        {'user_id': 'bad-id', 'full_name': 'Carol White', 'email': 'carol@example.com'},
        {'user_id': '104', 'full_name': 'SingleName', 'email': 'single@example.com'},
        {'user_id': '105', 'full_name': 'Eve Adams', 'email': 'invalid-email'},
    ]

    migrated_users = migrate_users(old_users)
    for user in migrated_users:
        print(user)

class EventBus:
    def __init__(self):
        self._subscribers = {}

    def subscribe(self, event_name, handler):
        """Register a handler for a specific event."""
        self._subscribers.setdefault(event_name, []).append(handler)

    def unsubscribe(self, event_name, handler):
        """Remove a handler from a specific event if present."""
        handlers = self._subscribers.get(event_name, [])
        if handler in handlers:
            handlers.remove(handler)
            if not handlers:
                del self._subscribers[event_name]

    def publish(self, event_name, data=None):
        """Notify all handlers subscribed to the event."""
        for handler in self._subscribers.get(event_name, []):
            handler(data)


class TemperatureSensor:
    def __init__(self, bus):
        self._bus = bus
        self._temperature = None

    def set_temperature(self, value):
        self._temperature = value
        self._bus.publish("temperature_changed", value)


# Listener functions

def log_temperature(value):
    print(f"[LOG] Temperature updated to {value}°C")


def high_temp_alert(value):
    if value > 30:
        print(f"[ALERT] High temperature detected: {value}°C")


# Demo
if __name__ == "__main__":
    bus = EventBus()
    sensor = TemperatureSensor(bus)

    bus.subscribe("temperature_changed", log_temperature)
    bus.subscribe("temperature_changed", high_temp_alert)

    for temp in [22, 28, 31, 35]:
        sensor.set_temperature(temp)

    print("-- Unsubscribing logger --")
    bus.unsubscribe("temperature_changed", log_temperature)

    sensor.set_temperature(33)

import json
from pathlib import Path

CONFIG_FILE = Path("config.json")
DEFAULT_CONFIG = {
    "host": "localhost",
    "port": 8080,
    "debug": False,
    "allowed_ips": []
}


def load_config(path: Path) -> dict:
    """Load configuration from JSON, creating or repairing it if needed."""
    if not path.exists():
        save_config(path, DEFAULT_CONFIG)
        return DEFAULT_CONFIG.copy()

    try:
        with path.open("r", encoding="utf-8") as file:
            config = json.load(file)
    except (json.JSONDecodeError, OSError):
        # If the file is unreadable or invalid, reset to defaults
        save_config(path, DEFAULT_CONFIG)
        return DEFAULT_CONFIG.copy()

    updated = False
    for key, value in DEFAULT_CONFIG.items():
        if key not in config:
            config[key] = value
            updated = True

    if updated:
        save_config(path, config)

    return config


def save_config(path: Path, config: dict) -> None:
    """Save configuration to JSON with indentation."""
    with path.open("w", encoding="utf-8") as file:
        json.dump(config, file, indent=4)


def print_config(config: dict) -> None:
    """Print configuration in a readable format."""
    print("Application Configuration:")
    for key, value in config.items():
        print(f"- {key}: {value}")


if __name__ == "__main__":
    config = load_config(CONFIG_FILE)
    print_config(config)

class TransactionManager:
    """Nested transaction context manager for in-memory dictionary updates."""

    def __init__(self, data):
        self.data = data
        self._snapshots = []  # Stack of per-level snapshots

    def __enter__(self):
        # Save the current state for this transaction level.
        self._snapshots.append(self.data.copy())
        return self.data

    def __exit__(self, exc_type, exc, tb):
        if not self._snapshots:
            raise RuntimeError("TransactionManager exited more times than entered")

        snapshot = self._snapshots.pop()

        if exc_type is not None:
            # Roll back only this transaction level.
            self.data.clear()
            self.data.update(snapshot)

        # Returning False ensures exceptions are propagated.
        return False


# Example usage
if __name__ == "__main__":
    state = {"balance": 100, "status": "open"}
    tm = TransactionManager(state)

    try:
        with tm:
            state["balance"] -= 10
            with tm:
                state["status"] = "pending"
            try:
                with tm:
                    state["balance"] = -999
                    raise ValueError("invalid update")
            except ValueError:
                pass
    except Exception:
        pass

    print(state)  # {'balance': 90, 'status': 'pending'}

def run_traffic_light():
    # Define the state transitions for the traffic light
    transitions = {
        'Red': 'Green',
        'Green': 'Yellow',
        'Yellow': 'Red'
    }

    current_state = 'Red'
    print(f'Starting state: {current_state}')

    # Perform 6 state transitions
    for step in range(6):
        input('Press Enter to move to the next state...')
        current_state = transitions[current_state]
        print(f'Transition {step + 1}: {current_state}')


if __name__ == '__main__':
    run_traffic_light()

from functools import wraps


def retry(max_attempts):
    """Decorator factory that retries a function on failure."""
    successful_count = 0  # Stored in the closure

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal successful_count
            last_error = None

            for _ in range(max_attempts):
                try:
                    result = func(*args, **kwargs)
                    successful_count += 1
                    wrapper.successful_calls = successful_count
                    return result
                except Exception as exc:
                    last_error = exc

            raise last_error

        wrapper.successful_calls = successful_count
        return wrapper

    return decorator


@retry(3)
def unstable_divide(a, b):
    if b == 0:
        raise ValueError("Division by zero is not allowed")
    return a / b


