class PluginRegistry:
    """Singleton registry for plugin classes."""
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._plugins = {}
        return cls._instance

    def register(self, name, plugin_cls):
        if name in self._plugins:
            raise ValueError(f"Plugin '{name}' is already registered")
        self._plugins[name] = plugin_cls

    def get(self, name):
        if name not in self._plugins:
            raise KeyError(f"Plugin '{name}' not found")
        return self._plugins[name]

    def create(self, name, **kwargs):
        plugin_cls = self.get(name)
        return plugin_cls(**kwargs)


class BasePlugin:
    """Base class that auto-registers subclasses in the singleton registry."""

    plugin_name = None

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        if cls.plugin_name:
            PluginRegistry().register(cls.plugin_name, cls)

    def describe(self):
        raise NotImplementedError


class LoggerPlugin(BasePlugin):
    plugin_name = "logger"

    def __init__(self, level="INFO"):
        self.level = level

    def describe(self):
        return f"LoggerPlugin(level={self.level})"


class CachePlugin(BasePlugin):
    plugin_name = "cache"

    def __init__(self, size=128):
        self.size = size

    def describe(self):
        return f"CachePlugin(size={self.size})"


