def validate_order(order):
    """Return (True, '') if the order is valid, otherwise (False, reason)."""
    if order.get('quantity', 0) <= 0:
        return False, 'Invalid quantity'
    if order.get('price_per_item', 0) <= 0:
        return False, 'Invalid price_per_item'
    return True, ''


def process_order(order):
    """Calculate total price for a valid order."""
    total_price = order['quantity'] * order['price_per_item']
    return {
        'order_id': order['order_id'],
        'customer': order['customer'],
        'total_price': total_price
    }


def run_batch_pipeline(orders):
    """Process orders and split them into successful and failed results."""
    successful_orders = []
    failed_orders = []

    for order in orders:
        is_valid, reason = validate_order(order)
        if is_valid:
            successful_orders.append(process_order(order))
        else:
            failed_orders.append({
                'order_id': order.get('order_id'),
                'reason': reason
            })

    return successful_orders, failed_orders


