def summarize_orders(orders):
    # Keep only completed orders with at least one purchased item quantity.
    completed_orders = [
        order for order in orders
        if order.get('status') == 'completed'
        and sum(item.get('qty', 0) for item in order.get('items', [])) > 0
    ]

    # Precompute total value per completed order.
    order_values = [
        sum(item.get('qty', 0) * item.get('price', 0) for item in order.get('items', []))
        for order in completed_orders
    ]

    # Sorted IDs of valid completed orders.
    completed_ids = sorted([order['id'] for order in completed_orders])

    # Unique customers with completed orders worth at least 100.
    high_value_customers = sorted({
        order['customer']
        for order, value in zip(completed_orders, order_values)
        if value >= 100
    })

    # Flatten all items from completed orders.
    completed_items = [
        item
        for order in completed_orders
        for item in order.get('items', [])
    ]

    # Aggregate quantities per item name.
    item_names = {item.get('name') for item in completed_items if item.get('name')}
    item_totals = {
        name: sum(item.get('qty', 0) for item in completed_items if item.get('name') == name)
        for name in item_names
    }

    average_completed_value = round(sum(order_values) / len(order_values), 2) if order_values else 0

    return {
        'completed_ids': completed_ids,
        'high_value_customers': high_value_customers,
        'item_totals': item_totals,
        'average_completed_value': average_completed_value,
    }


