import json
from abc import ABC, abstractmethod


class Report(ABC):
    """Abstract product."""

    def __init__(self, title, sections, metadata):
        self.title = title
        self.sections = sections
        self.metadata = metadata

    @abstractmethod
    def render(self):
        pass


class JSONReport(Report):
    def render(self):
        return json.dumps({
            'title': self.title,
            'sections': self.sections,
            'metadata': self.metadata,
        }, indent=2)


class TextReport(Report):
    def render(self):
        lines = [f"# {self.title}"]
        if self.metadata:
            lines.append("Metadata:")
            for key, value in self.metadata.items():
                lines.append(f"- {key}: {value}")
        for section in self.sections:
            lines.append(f"\n## {section['heading']}")
            lines.append(section['content'])
        return "\n".join(lines)


class ReportFactory:
    """Factory for selecting the concrete report type."""

    _formats = {
        'json': JSONReport,
        'text': TextReport,
    }

    @classmethod
    def create_report(cls, fmt, title, sections, metadata):
        report_cls = cls._formats.get(fmt.lower())
        if not report_cls:
            raise ValueError(f"Unsupported report format: {fmt}")
        return report_cls(title, sections, metadata)


class ReportBuilder:
    """Builder with a fluent interface."""

    def __init__(self, report_format):
        self.report_format = report_format
        self.title = "Untitled"
        self.sections = []
        self.metadata = {}

    def set_title(self, title):
        self.title = title
        return self

    def add_section(self, heading, content):
        self.sections.append({'heading': heading, 'content': content})
        return self

    def add_metadata(self, key, value):
        self.metadata[key] = value
        return self

    def build(self):
        return ReportFactory.create_report(
            self.report_format,
            self.title,
            self.sections,
            self.metadata,
        )


if __name__ == '__main__':
    json_report = (
        ReportBuilder('json')
        .set_title('Quarterly Summary')
        .add_section('Revenue', 'Revenue increased by 18%.')
        .add_section('Risks', 'Supply chain delays remain a concern.')
        .add_metadata('author', 'Analyst Team')
        .add_metadata('quarter', 'Q2')
        .build()
    )

    text_report = (
        ReportBuilder('text')
        .set_title('Deployment Notes')
        .add_section('Status', 'Deployment completed successfully.')
        .add_section('Follow-up', 'Monitor error rates for 24 hours.')
        .add_metadata('environment', 'production')
        .build()
    )

    print(json_report.render())
    print('\n' + '=' * 40 + '\n')
    print(text_report.render())

from itertools import tee
from collections import Counter


def pairwise(iterable):
    """Return overlapping pairs from the input iterable.
    Fallback recipe for Python versions without itertools.pairwise.
    """
    a, b = tee(iterable)
    next(b, None)
    return zip(a, b)


def count_page_transitions(pages):
    """Count consecutive page-to-page transitions."""
    transitions = pairwise(pages)
    return Counter(transitions)


