class UnreliableService:
    def __init__(self, outcomes):
        self.outcomes = outcomes
        self.index = 0

    def call(self):
        if self.index >= len(self.outcomes):
            raise IndexError("No more outcomes available")
        result = self.outcomes[self.index]
        self.index += 1
        return result


def call_with_retry(service, max_retries=3):
    """Try the service up to max_retries times. Return True on success, else False."""
    for attempt in range(1, max_retries + 1):
        success = service.call()
        print(f"  Attempt {attempt}: {'success' if success else 'failure'}")
        if success:
            return True
    return False


def main():
    # True = success, False = failure
    outcomes = [False, False, False, False, False, False, True, False, True, True]
    service = UnreliableService(outcomes)

    consecutive_failed_requests = 0
    blocked_requests_left = 0
    total_requests = 6

    for request_number in range(1, total_requests + 1):
        print(f"Request {request_number}:")

        # Circuit is open, so block this request
        if blocked_requests_left > 0:
            print("  Circuit open: request blocked")
            blocked_requests_left -= 1
            if blocked_requests_left == 0:
                print("  Circuit closes again")
            continue

        # Try the request with retry logic
        request_success = call_with_retry(service)

        if request_success:
            print("  Final result: request succeeded")
            consecutive_failed_requests = 0
        else:
            print("  Final result: request failed")
            consecutive_failed_requests += 1

        # Open circuit after 2 consecutive failed requests
        if consecutive_failed_requests >= 2:
            print("  Circuit opens: next 2 requests will be blocked")
            blocked_requests_left = 2
            consecutive_failed_requests = 0

        print()


if __name__ == "__main__":
    main()

import argparse
import sys
from functools import reduce
from operator import mul


def parse_args():
    parser = argparse.ArgumentParser(
        description="Compute sum, product, or average for integers from args or stdin."
    )
    parser.add_argument(
        "numbers",
        nargs="*",
        type=int,
        help="Integers to process. If omitted, values are read from stdin."
    )
    parser.add_argument(
        "--mode",
        required=True,
        choices=["sum", "product", "average"],
        help="Operation to perform."
    )

    verbosity = parser.add_mutually_exclusive_group()
    verbosity.add_argument(
        "--quiet",
        action="store_true",
        help="Print only the result."
    )
    verbosity.add_argument(
        "--verbose",
        action="store_true",
        help="Print a descriptive result message."
    )
    return parser.parse_args()


def read_numbers(args):
    if args.numbers:
        return args.numbers

    if sys.stdin.isatty():
        return []

    data = sys.stdin.read().strip()
    if not data:
        return []

    try:
        return [int(token) for token in data.split()]
    except ValueError:
        raise SystemExit("error: stdin must contain only integers separated by whitespace")


def compute(numbers, mode):
    if mode == "sum":
        return sum(numbers)
    if mode == "product":
        return reduce(mul, numbers, 1)
    if mode == "average":
        if not numbers:
            raise SystemExit("error: cannot compute average of zero numbers")
        return sum(numbers) / len(numbers)
    raise SystemExit(f"error: unsupported mode: {mode}")


def main():
    args = parse_args()
    numbers = read_numbers(args)

    if not numbers:
        raise SystemExit("error: no numbers provided via arguments or stdin")

    result = compute(numbers, args.mode)

    if args.quiet:
        print(result)
    elif args.verbose:
        print(f"Mode={args.mode}, count={len(numbers)}, result={result}")
    else:
        print(result)


if __name__ == "__main__":
    main()

