from __future__ import annotations

from dataclasses import dataclass, asdict
from datetime import datetime, time, timedelta
from typing import Dict, List, Optional, Tuple
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from flask import Flask, jsonify, request

app = Flask(__name__)

APPOINTMENT_DURATION_MINUTES = 30
CLINIC_HOURS = {
    0: (time(9, 0), time(17, 0)),  # Monday
    1: (time(9, 0), time(17, 0)),  # Tuesday
    2: (time(9, 0), time(17, 0)),  # Wednesday
    3: (time(9, 0), time(17, 0)),  # Thursday
    4: (time(9, 0), time(17, 0)),  # Friday
}

VALID_APPOINTMENT_TYPES = {"consultation", "follow-up", "urgent-care", "therapy"}


@dataclass
class Patient:
    patient_id: str
    name: str
    active: bool = True


@dataclass
class Doctor:
    doctor_id: str
    name: str
    active: bool = True


@dataclass
class Appointment:
    appointment_id: str
    patient_id: str
    doctor_id: str
    appointment_type: str
    insurance_status: str
    timezone: str
    start_at_utc: datetime
    end_at_utc: datetime
    requested_local_iso: str
    created_at_utc: datetime


PATIENTS: Dict[str, Patient] = {
    "P1001": Patient(patient_id="P1001", name="Alice Johnson"),
    "P1002": Patient(patient_id="P1002", name="Bob Smith"),
}

DOCTORS: Dict[str, Doctor] = {
    "D2001": Doctor(doctor_id="D2001", name="Dr. Emily Carter"),
    "D2002": Doctor(doctor_id="D2002", name="Dr. Michael Lee"),
}

APPOINTMENTS: List[Appointment] = []


def error_response(message: str, field: Optional[str] = None, code: str = "validation_error") -> Dict:
    payload = {"code": code, "message": message}
    if field:
        payload["field"] = field
    return payload


def parse_timezone(tz_name: str) -> ZoneInfo:
    try:
        return ZoneInfo(tz_name)
    except ZoneInfoNotFoundError as exc:
        raise ValueError("Invalid timezone.") from exc


def parse_requested_datetime(dt_str: str, tz_name: str) -> datetime:
    try:
        naive_or_aware = datetime.fromisoformat(dt_str)
    except ValueError as exc:
        raise ValueError("Invalid appointment datetime format. Use ISO 8601.") from exc

    tz = parse_timezone(tz_name)

    if naive_or_aware.tzinfo is None:
        return naive_or_aware.replace(tzinfo=tz)

    return naive_or_aware.astimezone(tz)


def validate_payload(data: dict) -> Tuple[List[Dict], Optional[dict]]:
    errors: List[Dict] = []
    required_fields = [
        "patient_id",
        "doctor_id",
        "requested_appointment_datetime",
        "timezone",
        "appointment_type",
        "insurance_status",
    ]

    for field in required_fields:
        if field not in data or data[field] in (None, ""):
            errors.append(error_response(f"{field} is required.", field=field))

    if errors:
        return errors, None

    patient_id = str(data["patient_id"]).strip()
    doctor_id = str(data["doctor_id"]).strip()
    requested_dt = str(data["requested_appointment_datetime"]).strip()
    timezone_name = str(data["timezone"]).strip()
    appointment_type = str(data["appointment_type"]).strip().lower()
    insurance_status = str(data["insurance_status"]).strip().lower()

    if appointment_type not in VALID_APPOINTMENT_TYPES:
        errors.append(
            error_response(
                f"appointment_type must be one of: {', '.join(sorted(VALID_APPOINTMENT_TYPES))}.",
                field="appointment_type",
            )
        )

    if insurance_status not in {"insured", "uninsured", "pending"}:
        errors.append(
            error_response(
                "insurance_status must be one of: insured, uninsured, pending.",
                field="insurance_status",
            )
        )

    try:
        local_dt = parse_requested_datetime(requested_dt, timezone_name)
    except ValueError as exc:
        errors.append(error_response(str(exc), field="requested_appointment_datetime"))
        local_dt = None

    if errors:
        return errors, None

    return errors, {
        "patient_id": patient_id,
        "doctor_id": doctor_id,
        "requested_local_dt": local_dt,
        "timezone": timezone_name,
        "appointment_type": appointment_type,
        "insurance_status": insurance_status,
    }


def patient_exists(patient_id: str) -> bool:
    patient = PATIENTS.get(patient_id)
    return bool(patient and patient.active)


def doctor_exists(doctor_id: str) -> bool:
    doctor = DOCTORS.get(doctor_id)
    return bool(doctor and doctor.active)


def is_in_past(local_dt: datetime) -> bool:
    now_local = datetime.now(local_dt.tzinfo)
    return local_dt < now_local


def is_within_clinic_hours(local_dt: datetime, duration_minutes: int = APPOINTMENT_DURATION_MINUTES) -> bool:
    weekday = local_dt.weekday()
    if weekday not in CLINIC_HOURS:
        return False

    open_time, close_time = CLINIC_HOURS[weekday]
    appointment_end = local_dt + timedelta(minutes=duration_minutes)

    start_local_time = local_dt.timetz().replace(tzinfo=None)
    end_local_time = appointment_end.timetz().replace(tzinfo=None)

    return open_time <= start_local_time and end_local_time <= close_time


def has_overlapping_appointment(doctor_id: str, start_utc: datetime, end_utc: datetime) -> bool:
    for appt in APPOINTMENTS:
        if appt.doctor_id != doctor_id:
            continue
        if start_utc < appt.end_at_utc and end_utc > appt.start_at_utc:
            return True
    return False


def generate_appointment_id() -> str:
    return f"A{len(APPOINTMENTS) + 1:05d}"


def schedule_appointment(data: dict) -> Tuple[Dict, int]:
    errors, cleaned = validate_payload(data)
    if errors:
        return {"status": "error", "errors": errors}, 400

    patient_id = cleaned["patient_id"]
    doctor_id = cleaned["doctor_id"]
    requested_local_dt = cleaned["requested_local_dt"]
    timezone_name = cleaned["timezone"]
    appointment_type = cleaned["appointment_type"]
    insurance_status = cleaned["insurance_status"]

    validation_errors: List[Dict] = []

    if not patient_exists(patient_id):
        validation_errors.append(error_response("Patient record not found or inactive.", field="patient_id"))

    if not doctor_exists(doctor_id):
        validation_errors.append(error_response("Doctor record not found or inactive.", field="doctor_id"))

    if is_in_past(requested_local_dt):
        validation_errors.append(
            error_response(
                "Appointments cannot be scheduled in the past.",
                field="requested_appointment_datetime",
            )
        )

    if not is_within_clinic_hours(requested_local_dt):
        validation_errors.append(
            error_response(
                "Requested time is outside clinic hours.",
                field="requested_appointment_datetime",
            )
        )

    if validation_errors:
        return {"status": "error", "errors": validation_errors}, 400

    start_utc = requested_local_dt.astimezone(ZoneInfo("UTC"))
    end_utc = start_utc + timedelta(minutes=APPOINTMENT_DURATION_MINUTES)

    if has_overlapping_appointment(doctor_id, start_utc, end_utc):
        return {
            "status": "error",
            "errors": [
                error_response(
                    "Doctor already has an overlapping appointment at the requested time.",
                    field="requested_appointment_datetime",
                    code="overlap_error",
                )
            ],
        }, 409

    appointment = Appointment(
        appointment_id=generate_appointment_id(),
        patient_id=patient_id,
        doctor_id=doctor_id,
        appointment_type=appointment_type,
        insurance_status=insurance_status,
        timezone=timezone_name,
        start_at_utc=start_utc,
        end_at_utc=end_utc,
        requested_local_iso=requested_local_dt.isoformat(),
        created_at_utc=datetime.now(ZoneInfo("UTC")),
    )

    APPOINTMENTS.append(appointment)

    response = {
        "status": "success",
        "message": "Appointment scheduled successfully.",
        "appointment": {
            "appointment_id": appointment.appointment_id,
            "patient_id": appointment.patient_id,
            "doctor_id": appointment.doctor_id,
            "appointment_type": appointment.appointment_type,
            "insurance_status": appointment.insurance_status,
            "timezone": appointment.timezone,
            "requested_appointment_local": appointment.requested_local_iso,
            "start_at_utc": appointment.start_at_utc.isoformat(),
            "end_at_utc": appointment.end_at_utc.isoformat(),
            "duration_minutes": APPOINTMENT_DURATION_MINUTES,
