class ConnectionFSM:
    # Transition table: current_state -> event -> next_state
    TRANSITIONS = {
        'DISCONNECTED': {'connect': 'CONNECTING', 'close': 'CLOSED'},
        'CONNECTING': {'success': 'CONNECTED', 'fail': 'RETRY_WAIT', 'timeout': 'RETRY_WAIT', 'close': 'CLOSED'},
        'CONNECTED': {'fail': 'RETRY_WAIT', 'close': 'CLOSED'},
        'RETRY_WAIT': {'retry': 'CONNECTING', 'close': 'CLOSED'},
        'CLOSED': {},
    }

    def __init__(self):
        self.state = 'DISCONNECTED'
        self.attempts = 0
        self.active = True

    def can(self, event):
        """Return True if the event is valid in the current state."""
        return event in self.TRANSITIONS[self.state]

    def trigger(self, event):
        """Apply an event, moving to the next state or raising ValueError."""
        if not self.can(event):
            valid = sorted(self.TRANSITIONS[self.state].keys())
            raise ValueError(
                f"Invalid event '{event}' from state '{self.state}'. Valid events: {valid}"
            )

        next_state = self.TRANSITIONS[self.state][event]
        self.state = next_state
        self._on_enter(next_state)
        return self.state

    def _on_enter(self, state):
        """Entry actions for specific states."""
        if state == 'CONNECTING':
            self.attempts += 1
        elif state == 'CONNECTED':
            self.attempts = 0
        elif state == 'CLOSED':
            self.active = False

    def status(self):
        """Return a snapshot of the machine's current status."""
        return {
            'state': self.state,
            'attempts': self.attempts,
            'active': self.active,
        }


# Example usage
if __name__ == '__main__':
    fsm = ConnectionFSM()
    for event in ['connect', 'fail', 'retry', 'success', 'close']:
        if fsm.can(event):
            fsm.trigger(event)
    print(fsm.status())

from typing import List, Dict, Any, Optional


def generate_moving_average_signals(
    ticks: List[Dict[str, Any]],
    short_window: int,
    long_window: int,
) -> List[Dict[str, Optional[float]]]:
    if not isinstance(ticks, list):
        raise TypeError("ticks must be a list of dictionaries")
    if not isinstance(short_window, int) or not isinstance(long_window, int):
        raise TypeError("short_window and long_window must be integers")
    if short_window <= 0 or long_window <= 0:
        raise ValueError("short_window and long_window must be positive integers")
    if short_window >= long_window:
        raise ValueError("short_window must be less than long_window")

    get_price = lambda tick: float(tick["price"])
    format_output = lambda ts, sma, lma, sig: {
        "timestamp": ts,
        "short_moving_average": sma,
        "long_moving_average": lma,
        "signal": sig,
    }

    for i, tick in enumerate(ticks):
        if not isinstance(tick, dict):
            raise TypeError(f"Each tick must be a dictionary, got {type(tick).__name__} at index {i}")
        if "timestamp" not in tick or "price" not in tick:
            raise ValueError(f"Each tick must contain 'timestamp' and 'price' keys at index {i}")
        try:
            get_price(tick)
        except (TypeError, ValueError, KeyError):
            raise ValueError(f"Invalid price value at index {i}")

    results: List[Dict[str, Optional[float]]] = []
    prev_relation: Optional[int] = None

    for i, tick in enumerate(ticks):
        timestamp = tick["timestamp"]

        if i + 1 < long_window:
            results.append(format_output(timestamp, None, None, "HOLD"))
            continue

        short_prices = list(map(get_price, ticks[i - short_window + 1 : i + 1]))
        long_prices = list(map(get_price, ticks[i - long_window + 1 : i + 1]))

        short_ma = sum(short_prices) / short_window
        long_ma = sum(long_prices) / long_window

        current_relation = 1 if short_ma > long_ma else -1 if short_ma < long_ma else 0

        if prev_relation is None:
            signal = "HOLD"
        elif prev_relation <= 0 and current_relation > 0:
            signal = "BUY"
        elif prev_relation >= 0 and current_relation < 0:
            signal = "SELL"
        else:
            signal = "HOLD"

        results.append(
            format_output(
                timestamp,
                round(short_ma, 6),
                round(long_ma, 6),
                signal,
            )
        )

        prev_relation = current_relation

    return results


if __name__ == "__main__":
    sample_ticks = [
        {"timestamp": "2024-01-01T09:30:00", "price": 100},
        {"timestamp": "2024-01-01T09:31:00", "price": 101},
        {"timestamp": "2024-01-01T09:32:00", "price": 102},
        {"timestamp": "2024-01-01T09:33:00", "price": 99},
        {"timestamp": "2024-01-01T09:34:00", "price": 98},
        {"timestamp": "2024-01-01T09:35:00", "price": 100},
        {"timestamp": "2024-01-01T09:36:00", "price": 103},
        {"timestamp": "2024-01-01T09:37:00", "price": 104},
    ]

    signals = generate_moving_average_signals(sample_ticks, short_window=3, long_window=5)
    for row in signals:
        print(row)

from pathlib import Path


def ensure_input_file(file_path: Path) -> None:
    """Create the binary file with sample data if it does not exist."""
    if not file_path.exists():
        sample_bytes = bytes([10, 200, 255, 0, 128, 50])
        file_path.write_bytes(sample_bytes)


def count_high_bytes(file_path: Path) -> int:
    """Count bytes with values greater than 127."""
    data = file_path.read_bytes()
    return sum(1 for byte in data if byte > 127)


def write_result(file_path: Path, count: int) -> None:
    """Write the count result to a text file."""
    file_path.write_text(f"Bytes greater than 127: {count}\n", encoding="utf-8")


def main() -> None:
    input_file = Path("input.bin")
    result_file = Path("result.txt")

    ensure_input_file(input_file)
    count = count_high_bytes(input_file)
    write_result(result_file, count)


if __name__ == "__main__":
    main()

