class EventBus:
    def __init__(self):
        self._listeners = {}

    def subscribe(self, event_name, handler):
        """Register a handler for a named event."""
        self._listeners.setdefault(event_name, []).append(handler)

    def emit(self, event_name, data):
        """Send data to all handlers subscribed to the event."""
        for handler in self._listeners.get(event_name, []):
            handler(data)


class SmartHomeMonitor:
    def __init__(self, bus):
        self.alerts = []
        bus.subscribe('temperature', self.on_temperature)
        bus.subscribe('motion', self.on_motion)
        bus.subscribe('door', self.on_door)

    def on_temperature(self, data):
        value = data.get('value', 0)
        room = data.get('room', 'unknown')
        if value > 30:
            self.alerts.append(f'High temperature in {room}: {value}C')

    def on_motion(self, data):
        room = data.get('room', 'unknown')
        detected = data.get('detected', False)
        if detected:
            self.alerts.append(f'Motion detected in {room}')

    def on_door(self, data):
        door = data.get('door', 'unknown')
        state = data.get('state', 'closed')
        if state == 'opened':
            self.alerts.append(f'Door opened: {door}')


if __name__ == '__main__':
    bus = EventBus()
    monitor = SmartHomeMonitor(bus)

    # Demo events
    bus.emit('temperature', {'room': 'kitchen', 'value': 28})
    bus.emit('temperature', {'room': 'server room', 'value': 35})
    bus.emit('motion', {'room': 'hallway', 'detected': True})
    bus.emit('door', {'door': 'front door', 'state': 'opened'})
    bus.emit('door', {'door': 'garage', 'state': 'closed'})

    print('Alerts:')
    for alert in monitor.alerts:
        print('-', alert)

import time
import uuid
from typing import Callable, Dict, List, Any

Request = Dict[str, Any]
Response = Dict[str, Any]
Middleware = Callable[[Request, Callable[[Request], Response]], Response]
Handler = Callable[[Request], Response]


def build_pipeline(middlewares: List[Middleware], handler: Handler) -> Handler:
    """Compose middleware around the final handler."""
    def pipeline(request: Request) -> Response:
        def call(index: int, current_request: Request) -> Response:
            if index == len(middlewares):
                return handler(current_request)
            return middlewares[index](current_request, lambda req: call(index + 1, req))

        return call(0, request)

    return pipeline


def request_id_middleware(request: Request, call_next: Callable[[Request], Response]) -> Response:
    request = dict(request)  # avoid mutating caller-owned data
    request.setdefault("request_id", str(uuid.uuid4()))
    response = call_next(request)
    response["request_id"] = request["request_id"]
    return response


def timing_middleware(request: Request, call_next: Callable[[Request], Response]) -> Response:
    start = time.perf_counter()
    response = call_next(request)
    response["duration_ms"] = round((time.perf_counter() - start) * 1000, 3)
    return response


def auth_middleware(request: Request, call_next: Callable[[Request], Response]) -> Response:
    if request.get("token") != "secret-token":
        return {
            "status": 401,
            "error": "unauthorized",
            "path": request.get("path", "/")
        }
    return call_next(request)


def final_handler(request: Request) -> Response:
    return {
        "status": 200,
        "message": f"Processed {request.get('path', '/')}",
        "user": request.get("user", "anonymous")
    }


if __name__ == "__main__":
    app = build_pipeline(
        [request_id_middleware, timing_middleware, auth_middleware],
        final_handler,
    )

    requests = [
        {"path": "/orders", "user": "alice", "token": "secret-token"},
        {"path": "/admin", "user": "bob", "token": "bad-token"},
        {"path": "/profile", "token": "secret-token"},
    ]

    for req in requests:
        print(app(req))

class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None


class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """Insert a value into the BST."""
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_recursive(self.root, value)

    def _insert_recursive(self, current, value):
        if value < current.value:
            if current.left is None:
                current.left = Node(value)
            else:
                self._insert_recursive(current.left, value)
        else:
            if current.right is None:
                current.right = Node(value)
            else:
                self._insert_recursive(current.right, value)

    def inorder_traversal(self):
        """Return the in-order traversal as a list."""
        result = []
        self._inorder_recursive(self.root, result)
        return result

    def _inorder_recursive(self, node, result):
        if node is not None:
            self._inorder_recursive(node.left, result)
            result.append(node.value)
            self._inorder_recursive(node.right, result)


# Create the BST and insert values
bst = BinarySearchTree()
values = [50, 30, 70, 20, 40, 60, 80]

for value in values:
    bst.insert(value)

# Print sorted values using in-order traversal
print(bst.inorder_traversal())

class CloudServerMonitor:
    def __init__(self, cpu_usages):
        self.cpu_usages = cpu_usages

    def analyze_usage(self):
        if not self.cpu_usages:
            return {
                "average_cpu_usage": 0.0,
                "highest_cpu_usage": 0.0,
                "status": "No Data",
            }

        total_usage = 0
        highest_usage = self.cpu_usages[0]

        for usage in self.cpu_usages:
            total_usage += usage
            if usage > highest_usage:
                highest_usage = usage

        average_usage = total_usage / len(self.cpu_usages)

        if average_usage < 50 and highest_usage < 70:
            status = "Normal"
        elif average_usage < 75 and highest_usage < 90:
            status = "Warning"
        else:
            status = "Critical"

        return {
            "average_cpu_usage": round(average_usage, 2),
            "highest_cpu_usage": highest_usage,
            "status": status,
        }


if __name__ == "__main__":
    vm_cpu_usages = [35, 48, 62, 77, 54]

    monitor = CloudServerMonitor(vm_cpu_usages)
    result = monitor.analyze_usage()

    print("Average CPU Usage:", result["average_cpu_usage"], "%")
    print("Highest CPU Usage:", result["highest_cpu_usage"], "%")
    print("Status:", result["status"])
